/*
 * Raspberry Pi 4 Model B - Soil Moisture Monitor
 *
 * Hardware:
 *   - DFRobot Soil Moisture Sensor v2.0 (analog resistive) -> MCP3008 CH0
 *   - MCP3008 ADC on SPI0:
 *       CE0  -> GPIO8  (physical pin 24)
 *       MOSI -> GPIO10 (physical pin 19)
 *       MISO -> GPIO9  (physical pin 21)
 *       SCLK -> GPIO11 (physical pin 23)
 *       VDD  -> 3.3 V, VREF -> 3.3 V, DGND/AGND -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o soil_monitor soil_monitor.c -lpigpio -lrt
 * Run:   sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz - well within MCP3008 3.3 V limit */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, 8-bit words */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define SAMPLE_PERIOD  1          /* seconds between readings */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (3-byte transfer, Mode 0, MSB-first):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low nibble)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 *
 * Returns 0-1023 on success, -1 on error.
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01,
                   (char)((0x08 | channel) << 4),
                   0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (spiXfer returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil Moisture Monitor started. Press Ctrl+C to exit.\n");
    printf("SPI0 CE0 @ %d Hz, ADC channel %d\n", SPI_SPEED, ADC_CHANNEL);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = -1;
        int retries = 0;

        /* Retry transient SPI errors up to MAX_RETRIES times */
        while (retries < MAX_RETRIES && g_running) {
            adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
            if (adc_value >= 0)
                break;

            retries++;
            if (retries < MAX_RETRIES)
                time_sleep(0.01);  /* 10 ms backoff */
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries; skipping sample\n",
                    MAX_RETRIES);
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        /* --- Timestamp and log --- */
        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];

        if (localtime_r(&now, &tm_info) != NULL) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            snprintf(ts, sizeof(ts), "unknown-time");
        }

        printf("[%s] Moisture Level: %4d (ADC: %4d)\n", ts, adc_value, adc_value);
        fflush(stdout);

        /* --- Wait for next sample period --- */
        time_sleep(SAMPLE_PERIOD);
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

