/*
 * MLX91219 Hall-effect current sensor reader via ADS1115 ADC on Raspberry Pi 4.
 *
 * Wiring:
 *   ADS1115 VDD  -> Pi 3.3 V (pin 1)
 *   ADS1115 GND  -> Pi GND  (pin 9)
 *   ADS1115 SDA  -> Pi GPIO2 / I2C bus 1 SDA (pin 3)
 *   ADS1115 SCL  -> Pi GPIO3 / I2C bus 1 SCL (pin 5)
 *   ADS1115 ADDR -> GND  (I2C address 0x48)
 *   MLX91219 AOUT-> ADS1115 AIN0
 *
 * Build:  gcc -O2 -Wall -o mlx91219_ads1115 mlx91219_ads1115.c -lpigpio -lrt
 * Run:    sudo ./mlx91219_ads1115
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADS1115 constants (verified against datasheet) ---- */
#define ADS1115_ADDR          0x48
#define ADS1115_REG_CONVERT   0x00
#define ADS1115_REG_CONFIG    0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   [15]    OS       = 1  (begin single conversion)
 *   [14:12] MUX      = 100 (AIN0 single-ended)
 *   [11:9]  PGA      = 001 (±4.096 V)
 *   [8]     MODE     = 1  (single-shot)
 *   [7:5]   DR       = 100 (128 SPS)
 *   [4]     COMP_MODE= 0
 *   [3]     COMP_POL = 0
 *   [2]     COMP_LAT = 0
 *   [1:0]   COMP_QUE = 11 (disable comparator)
 *   => 0x8483
 */
#define ADS1115_CFG_BASE      0x8483

/* ---- MLX91219 parameters ---- */
#define MLX91219_SENSITIVITY  0.040f   /* 40 mV/A */
#define MLX91219_OFFSET      2.5f     /* mid-supply zero-current offset (V) */
#define ADC_VREF             4.096f   /* ADS1115 PGA full-scale */
#define ADC_MAX_COUNT        32767.0f /* 16-bit signed positive max */

/* ---- I2C / timing ---- */
#define I2C_BUS              1
#define SAMPLE_PERIOD_US     500000   /* 500 ms */
#define CONV_TIMEOUT_US      100000   /* 100 ms max wait for conversion */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ADS1115 register (big-endian on the bus). */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);   /* MSB first */
    buf[2] = (char)(value & 0xFF);          /* LSB second */

    if (i2cWriteI2CBlockData(handle, reg, buf + 1, 2) < 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an ADS1115 register (big-endian on the bus). */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single-shot conversion and read the raw 16-bit result. */
static int ads1115_read_raw(int handle, int16_t *raw_out)
{
    uint16_t cfg = ADS1115_CFG_BASE;
    uint16_t cfg_readback;
    uint16_t raw;
    int      elapsed;

    /* Write config to start a conversion. */
    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, cfg) < 0) {
        return -1;
    }

    /* Poll the OS bit (bit 15) until conversion completes. */
    elapsed = 0;
    do {
        if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg_readback) < 0) {
            return -1;
        }
        if (cfg_readback & 0x8000) {
            break;                 /* conversion ready */
        }
        gpioDelay(1000);           /* 1 ms */
        elapsed += 1000;
    } while (elapsed < CONV_TIMEOUT_US);

    if (elapsed >= CONV_TIMEOUT_US) {
        return -2;                 /* conversion timeout */
    }

    /* Read the conversion result. */
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERT, &raw) < 0) {
        return -1;
    }

    *raw_out = (int16_t)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
static float raw_to_current(int16_t raw)
{
    float voltage = ((float)raw / ADC_MAX_COUNT) * ADC_VREF;
    return (voltage - MLX91219_OFFSET) / MLX91219_SENSITIVITY;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t raw;
    float   current;
    int     rc;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at ADS1115 address 0x48 --- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). "
                        "Check wiring and that ADS1115 is present.\n",
                        g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 via ADS1115 (I2C 0x48, bus %d)\n", I2C_BUS);
    printf("Sampling every %d ms. Press Ctrl+C to exit.\n\n",
           SAMPLE_PERIOD_US / 1000);

    /* --- Main sampling loop --- */
    while (g_running) {
        rc = ads1115_read_raw(g_i2c_handle, &raw);
        if (rc == 0) {
            current = raw_to_current(raw);
            printf("Current: %.4f A\n", current);
        } else if (rc == -2) {
            fprintf(stderr, "Warning: ADS1115 conversion timeout.\n");
        } else {
            fprintf(stderr, "Warning: I2C read error (rc=%d).\n", rc);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

