#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONV_REG 0x00
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADC_VREF 3.3
#define ADC_MAX 32767.0
#define TEMP_MIN 20.0
#define TEMP_MAX 80.0
#define TEMP_THRESHOLD 60.0
#define DEBOUNCE_MS 50
#define POLL_MS 100
#define BUZZER_MS 2000

static volatile sig_atomic_t running = 1;
static volatile uint32_t last_flame_tick = 0;
static volatile int flame_event_pending = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flame_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    uint32_t elapsed = tick - last_flame_tick;
    if (elapsed < DEBOUNCE_MS * 1000) return;
    last_flame_tick = tick;
    flame_event_pending = 1;
}

static int init_flame_sensor(void) {
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        return -1;
    }
    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on flame sensor pin\n");
        return -1;
    }
    if (gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, flame_isr, NULL) < 0) {
        fprintf(stderr, "Failed to register ISR for flame sensor\n");
        return -1;
    }
    return 0;
}

static int init_buzzer(void) {
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        return -1;
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize buzzer state\n");
        return -1;
    }
    return 0;
}

static int init_ads1115(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    char buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 3) < 0) {
        fprintf(stderr, "Failed to write ADS1115 config register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp_out) {
    if (i2c_handle < 0) return -1;
    char reg = ADS1115_CONFIG_REG;
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Failed to trigger ADS1115 conversion\n");
        return -1;
    }
    gpioDelay(10000);
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) < 0) {
        fprintf(stderr, "Failed to read ADS1115 conversion result\n");
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    float voltage = (raw / ADC_MAX) * ADC_VREF;
    *temp_out = TEMP_MIN + (voltage / (ADC_VREF / (TEMP_MAX - TEMP_MIN)));
    return 0;
}

static void log_event(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "[%s] %s\n", ts, msg);
    fflush(log_file);
}

static void activate_buzzer(int duration_ms) {
    if (gpioWrite(BUZZER_PIN, 1) < 0) {
        fprintf(stderr, "Failed to activate buzzer\n");
        return;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to deactivate buzzer\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    if (init_flame_sensor() < 0) {
        gpioTerminate();
        return 1;
    }
    if (init_buzzer() < 0) {
        gpioTerminate();
        return 1;
    }
    if (init_ads1115() < 0) {
        gpioTerminate();
        return 1;
    }
    log_file = fopen("fire_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open fire_log.txt\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("Fire detection system started. Press Ctrl+C to exit.\n");
    while (running) {
        if (flame_event_pending) {
            flame_event_pending = 0;
            float temp;
            if (read_temperature(&temp) == 0) {
                if (temp > TEMP_THRESHOLD) {
                    char msg[128];
                    snprintf(msg, sizeof(msg), "Flame detected! Temperature: %.2f C", temp);
                    log_event(msg);
                    printf("%s\n", msg);
                    activate_buzzer(BUZZER_MS);
                } else {
                    char msg[128];
                    snprintf(msg, sizeof(msg), "Flame detected! Temperature: %.2f C (below threshold)", temp);
                    log_event(msg);
                    printf("%s\n", msg);
                }
            } else {
                log_event("Error reading temperature sensor");
                fprintf(stderr, "Temperature read failed\n");
            }
        }
        gpioDelay(POLL_MS * 1000);
    }
    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, NULL, NULL);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

