#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define DEFAULT_THRESHOLD 5.0
#define DEFAULT_SENSITIVITY 0.1
#define DEFAULT_LOG_FILE "current_log.txt"
#define DEFAULT_SPI_DEVICE "/dev/spidev0.0"
#define DEFAULT_SPI_SPEED 1000000
#define DEFAULT_GPIO_CHIP "gpiochip4"
#define DEFAULT_GPIO_LINE 18

#define ADC_VREF 3.3
#define ADC_MAX 1023.0
#define SENSOR_MIN_V 0.0
#define SENSOR_MAX_V 3.3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *fan_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(const char *device, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_adc(int fd, uint8_t channel) {
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)(0x80 | (channel << 4)), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = DEFAULT_SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

static double adc_to_current(int adc_value, double sensitivity) {
    double voltage = (double)adc_value / ADC_MAX * ADC_VREF;
    return (voltage - SENSOR_MIN_V) / sensitivity;
}

static void log_data(double current, int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Current: %.2f A, ADC: %d\n", timestamp, current, adc_value);
    fflush(log_file);
}

static void control_fan(double current, double threshold) {
    int val = (current > threshold) ? 1 : 0;
    if (gpiod_line_set_value(fan_line, val) < 0) {
        fprintf(stderr, "Error setting fan GPIO value: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
        fan_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(int argc, char *argv[]) {
    double threshold = DEFAULT_THRESHOLD;
    double sensitivity = DEFAULT_SENSITIVITY;
    const char *log_file_path = DEFAULT_LOG_FILE;
    const char *spi_device = DEFAULT_SPI_DEVICE;
    uint32_t spi_speed = DEFAULT_SPI_SPEED;
    const char *gpio_chip_name = DEFAULT_GPIO_CHIP;
    int gpio_line_num = DEFAULT_GPIO_LINE;

    int opt;
    while ((opt = getopt(argc, argv, "t:s:l:d:c:h")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                sensitivity = atof(optarg);
                break;
            case 'l':
                log_file_path = optarg;
                break;
            case 'd':
                spi_device = optarg;
                break;
            case 'c':
                spi_speed = atoi(optarg);
                break;
            case 'h':
                fprintf(stderr, "Usage: %s [-t threshold] [-s sensitivity] [-l log_file] [-d spi_device] [-c spi_speed]\n", argv[0]);
                return 1;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s sensitivity] [-l log_file] [-d spi_device] [-c spi_speed]\n", argv[0]);
                return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen(log_file_path, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", log_file_path, strerror(errno));
        return 1;
    }

    spi_fd = spi_init(spi_device, spi_speed);
    if (spi_fd < 0) {
        cleanup();
        return 1;
    }

    gpio_chip = gpiod_chip_open_by_name(gpio_chip_name);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", gpio_chip_name, strerror(errno));
        cleanup();
        return 1;
    }

    fan_line = gpiod_chip_get_line(gpio_chip, gpio_line_num);
    if (!fan_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", gpio_line_num, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Monitoring current... Press Ctrl+C to exit.\n");
    printf("Threshold: %.2f A, Sensitivity: %.2f mV/A, Log: %s\n", threshold, sensitivity * 1000.0, log_file_path);

    while (running) {
        int adc_value = read_adc(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            sleep(1);
            continue;
        }

        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Warning: ADC reading at extreme (%d). Sensor absent or wiring fault?\n", adc_value);
        }

        double current = adc_to_current(adc_value, sensitivity);
        log_data(current, adc_value);
        control_fan(current, threshold);
        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

