#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_co_resistance(int handle, int *co_resistance) {
    char buf[2];
    int bytes_read;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        bytes_read = i2cReadDevice(handle, buf, 2);
        if (bytes_read == 2) {
            *co_resistance = ((int)(buf[0] & 0xFF) << 8) | (int)(buf[1] & 0xFF);
            return 0;
        }
        fprintf(stderr, "I2C read attempt %d failed (returned %d)\n", attempt + 1, bytes_read);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(100000); /* 100 ms backoff */
        }
    }
    return -1;
}

static float calculate_co_ppm(int co_resistance) {
    if (co_resistance <= 0) {
        return 0.0f;
    }
    float log_res = log10f((float)co_resistance);
    float ppm = 100.0f * powf(10.0f, (log_res - 1.5f) / -0.5f);
    return (ppm < 0.0f) ? 0.0f : ppm;
}

static int log_co_data(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        perror("localtime failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f PPM\n", timestamp, co_ppm) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM) failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d, addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("CO sensor monitoring started. Logging to %s every %d seconds. Press Ctrl+C to exit.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        int co_resistance = 0;

        if (read_co_resistance(i2c_handle, &co_resistance) != 0) {
            fprintf(stderr, "Failed to read CO resistance after %d attempts. Skipping sample.\n", MAX_RETRIES);
        } else {
            float co_ppm = calculate_co_ppm(co_resistance);
            if (log_co_data(co_ppm) != 0) {
                fprintf(stderr, "Failed to log CO data.\n");
            } else {
                printf("CO: %.2f PPM (raw resistance: %d)\n", co_ppm, co_resistance);
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            gpioDelay(1000000); /* 1 second */
        }
    }

    printf("\nShutting down gracefully...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

