            fprintf(stderr, "Failed to read CO resistance after %d attempts. Skipping sample.\n", MAX_RETRIES);
        } else {
            float co_ppm = calculate_co_ppm(co_resistance);
            if (log_co_data(co_ppm) != 0) {
                fprintf(stderr, "Failed to log CO data.\n");
            } else {
                printf("CO: %.2f PPM (raw resistance: %d)\n", co_ppm, co_resistance);
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            gpioDelay(1000000); /* 1 second */
        }
    }

    printf("\nShutting down gracefully...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

