        }

        float temperature = convert_adc_to_temperature(adc_value);

        if (log_data(flame_presence, temperature) != 0) {
            fprintf(stderr, "Logging failed, continuing.\n");
        }

        gpioDelay(1000000);
    }

    printf("\nCleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

