#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x4B
#define CO_THRESHOLD 25.0
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define READ_INTERVAL 5

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float co_ppm;
    float no2_ppm;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *co, uint16_t *no2);
float calculate_co_ppm(uint16_t co_raw);
void log_co_level(float co_ppm);
void log_alert(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from MICS-4514
int read_sensor_data(uint16_t *co, uint16_t *no2) {
    char buf[4];
    int result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // MICS-4514 returns 2 bytes for OX (CO) and 2 bytes for RED (NO2)
    *co = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    *no2 = ((uint16_t)buf[2] << 8) | (uint8_t)buf[3];

    return 0;
}

// Calculate CO level in PPM
float calculate_co_ppm(uint16_t co_raw) {
    // Placeholder calibration formula
    // In a real application, this would be calibrated against known CO levels
    return (float)co_raw * 0.1f;
}

// Log CO level to file
void log_co_level(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f PPM\n", s, co_ppm);
    fclose(fp);
}

// Log alert to file
void log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alert log file: %s\n", ALERT_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, CO level exceeded threshold: %.2f PPM\n", s, co_ppm);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t co_raw, no2_raw;
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&co_raw, &no2_raw) == 0) {
            sensor_data.co_ppm = calculate_co_ppm(co_raw);
            sensor_data.no2_ppm = (float)no2_raw * 0.1f; // Placeholder NO2 calculation

            log_co_level(sensor_data.co_ppm);

            if (sensor_data.co_ppm > CO_THRESHOLD) {
                log_alert(sensor_data.co_ppm);
            }

            printf("CO: %.2f PPM, NO2: %.2f PPM\n", sensor_data.co_ppm, sensor_data.no2_ppm);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(READ_INTERVAL);
    }

    // Cleanup
    cleanup();
    return 0;
}

