#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define I2C_BUS 1
#define IMP23ABSU_ADDR_1 0x48
#define IMP23ABSU_ADDR_2 0x49
#define REG_DATA 0x00
#define SAMPLE_INTERVAL_US 100000
#define SENSITIVITY_DBV_PER_PA -38.0
#define REFERENCE_PRESSURE 20.0e-6
#define ERROR_VALUE -999.0

static volatile sig_atomic_t running = 1;
static int i2c_handle_1 = -1;
static int i2c_handle_2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double read_microphone(int handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, REG_DATA, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading I2C block: %d\n", result);
        return ERROR_VALUE;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    double pressure = (raw / 32768.0) * REFERENCE_PRESSURE;
    return pressure * SENSITIVITY_DBV_PER_PA;
}

static void log_data(double avg_db) {
    FILE *fp = fopen("audio_log.txt", "a");
    if (!fp) {
        perror("Error opening audio_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f dB\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, avg_db);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle_1 = i2cOpen(I2C_BUS, IMP23ABSU_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle_2 = i2cOpen(I2C_BUS, IMP23ABSU_ADDR_2, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle_2);
        i2cClose(i2c_handle_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        double db1 = read_microphone(i2c_handle_1);
        double db2 = read_microphone(i2c_handle_2);
        double avg_db = (db1 + db2) / 2.0;
        log_data(avg_db);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle_1 >= 0) i2cClose(i2c_handle_1);
    if (i2c_handle_2 >= 0) i2cClose(i2c_handle_2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

