#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 27
#define THRESHOLD 0.7
#define SAMPLE_WINDOW_MS 100
#define SAMPLE_INTERVAL_US 1000 // 1 ms
#define NUM_SAMPLES (SAMPLE_WINDOW_MS * 1000 / SAMPLE_INTERVAL_US)

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float calculate_rms(int *samples, int num_samples);
void control_led(int state);
void log_data(float mic1_rms, float mic2_rms);
void signal_handler(int signal);

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message for MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate RMS value
float calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Function to log data to a CSV file
void log_data(float mic1_rms, float mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    control_led(0);

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int samples[NUM_SAMPLES];
    float mic1_rms, mic2_rms;

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read samples from both microphones
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int val1 = read_mcp3008(0); // Mic 1 connected to channel 0
            int val2 = read_mcp3008(1); // Mic 2 connected to channel 1
            if (val1 < 0 || val2 < 0) {
                fprintf(stderr, "Error reading ADC values\n");
                program_running = 0;
                break;
            }
            samples[i] = val1; // Store the first microphone's value
            gpioDelay(SAMPLE_INTERVAL_US); // Delay for 1 ms
        }

        if (!program_running) break;

        // Calculate RMS values
        mic1_rms = calculate_rms(samples, NUM_SAMPLES);
        mic2_rms = calculate_rms(samples, NUM_SAMPLES);

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Check threshold and control LED
        if (mic1_rms > THRESHOLD * mic2_rms || mic2_rms > THRESHOLD * mic1_rms) {
            control_led(1);
            gpioDelay(500000); // 500 ms
            control_led(0);
        }

        gpioDelay(100000); // 100 ms delay between windows
    }

    // Cleanup
    control_led(0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Audio monitoring stopped.\n");
    return 0;
}

