#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONFIG_MUX_A0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_MAX_VALUE 32767.0f
#define ADS1115_VREF 4.096f
#define MLX91204_VMIN 0.5f
#define MLX91204_VMAX 4.5f
#define MLX91204_AMAX 100.0f
#define OVERCURRENT_THRESHOLD 50.0f
#define WARNING_LED_GPIO 17
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// Global variables
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static float current_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

// Function prototypes
static int init_i2c(void);
static int read_ads1115(int16_t *raw_value);
static float convert_to_current(int16_t raw_value);
static void add_to_buffer(float current);
static float calculate_average_current(void);
static void check_overcurrent(float current);
static void cleanup(void);
static void signal_handler(int signal);

// Initialize I2C communication with ADS1115
static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }

    // Configure ADS1115: single-ended A0, PGA 4.096V, 128SPS, continuous conversion
    uint16_t config = ADS1115_CONFIG_MUX_A0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    char config_buf[3];
    config_buf[0] = ADS1115_CONFIG_REG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) != 0) {
        fprintf(stderr, "Error writing ADS1115 config register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

// Read raw 16-bit value from ADS1115 conversion register
static int read_ads1115(int16_t *raw_value) {
    char reg_buf[1] = {ADS1115_CONVERSION_REG};
    char data_buf[2];

    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error selecting ADS1115 conversion register\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data_buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion data\n");
        return -1;
    }

    *raw_value = (int16_t)((data_buf[0] << 8) | data_buf[1]);
    return 0;
}

// Convert raw ADC value to current (A) using ratiometric scaling
static float convert_to_current(int16_t raw_value) {
    float voltage = ((float)raw_value / ADS1115_MAX_VALUE) * ADS1115_VREF;
    if (voltage < MLX91204_VMIN) voltage = MLX91204_VMIN;
    if (voltage > MLX91204_VMAX) voltage = MLX91204_VMAX;
    return (voltage - MLX91204_VMIN) * MLX91204_AMAX / (MLX91204_VMAX - MLX91204_VMIN);
}

// Add current reading to circular buffer
static void add_to_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

// Calculate average current from buffer
static float calculate_average_current(void) {
    if (buffer_count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) {
        sum += current_buffer[i];
    }
    return sum / buffer_count;
}

// Check for overcurrent condition and trigger LED
static void check_overcurrent(float current) {
    if (current > OVERCURRENT_THRESHOLD) {
        gpioWrite(WARNING_LED_GPIO, 1);
        printf("OVERCURRENT DETECTED! Current: %.2fA\n", current);
    } else {
        gpioWrite(WARNING_LED_GPIO, 0);
    }
}

// Cleanup resources
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(WARNING_LED_GPIO, 0);
    gpioTerminate();
}

// Signal handler for graceful shutdown
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(WARNING_LED_GPIO, PI_OUTPUT);
    gpioWrite(WARNING_LED_GPIO, 0);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Overcurrent protection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) != 0) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float current = convert_to_current(raw_value);
        add_to_buffer(current);
        float avg_current = calculate_average_current();
        check_overcurrent(avg_current);

        printf("Current: %.2fA, Average: %.2fA\n", current, avg_current);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

