        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(WARNING_LED_GPIO, PI_OUTPUT);
    gpioWrite(WARNING_LED_GPIO, 0);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Overcurrent protection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) != 0) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float current = convert_to_current(raw_value);
        add_to_buffer(current);
        float avg_current = calculate_average_current();
        check_overcurrent(avg_current);

        printf("Current: %.2fA, Average: %.2fA\n", current, avg_current);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

