#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_ID 0x12
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

#define ENABLE_PON 0x01
#define ENABLE_AEN 0x02
#define GAIN_4X 0x01
#define INTEGRATION_TIME_2_4MS 0xFF

#define LOG_FILE "color_log.csv"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, TCS34725_COMMAND_BIT | reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out) {
    int rc = i2cReadWordData(handle, TCS34725_COMMAND_BIT | reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

static int initialize_sensor(int handle) {
    int id = i2cReadByteData(handle, TCS34725_COMMAND_BIT | TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "Failed to read ID register: %d\n", id);
        return -1;
    }
    if ((id & 0x0F) != 0x44) {
        fprintf(stderr, "Unexpected ID: 0x%02X (expected lower nibble 0x44)\n", id);
        return -1;
    }

    if (i2c_write_byte(handle, TCS34725_ATIME, INTEGRATION_TIME_2_4MS) < 0) return -1;
    if (i2c_write_byte(handle, TCS34725_CONTROL, GAIN_4X) < 0) return -1;

    if (i2c_write_byte(handle, TCS34725_ENABLE, ENABLE_PON) < 0) return -1;
    gpioDelay(3000);
    if (i2c_write_byte(handle, TCS34725_ENABLE, ENABLE_PON | ENABLE_AEN) < 0) return -1;
    gpioDelay(3000);
    return 0;
}

static int read_sensor_data(int handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (i2c_read_word(handle, TCS34725_CDATA, clear) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_RDATA, red) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_GDATA, green) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_BDATA, blue) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t t = time(NULL);
