#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define CS_LINE_OFFSET 8  // GPIO8 = CE0

#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1

#define LOG_FILE "moisture_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_mcp3008(int spi_fd, struct gpiod_line *cs_line, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 single-ended read: start bit, config byte, dummy byte
    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (channel << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    // Assert chip-select (active low)
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Failed to set CS low");
        return -1;
    }

    // Perform SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        gpiod_line_set_value(cs_line, 1);  // Deassert on error
        return -1;
    }

    // Deassert chip-select
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Failed to set CS high");
        return -1;
    }

    // Extract 10-bit ADC value: bits 1-2 of rx[1] are MSB, rx[2] is LSB
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float map_adc_to_moisture(int adc_value) {
    return (float)adc_value / 1023.0f * 100.0f;
}

static int log_data(const char *filename, float moisture1, float moisture2) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, moisture1, moisture2);
    fclose(fp);
    return 0;
}

int main(void) {
    // Setup signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open SPI device
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Configure SPI mode (mode 0)
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }

    // Configure SPI max speed
    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return 1;
    }

    // Open GPIO chip and request CS line
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        perror("Failed to get CS line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Configure CS line as output, initially high (deselected)
    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        perror("Failed to request CS line as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Create log file and write header
    FILE *fp = fopen(LOG_FILE, "w");
    if (!fp) {
        perror("Failed to create log file");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }
    fprintf(fp, "Timestamp,Moisture1,Moisture2\n");
    fclose(fp);

    printf("Starting moisture monitoring. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc1 = read_mcp3008(spi_fd, cs_line, MCP3008_CHANNEL_0);
        int adc2 = read_mcp3008(spi_fd, cs_line, MCP3008_CHANNEL_1);

        if (adc1 < 0 || adc2 < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
        } else {
            float moisture1 = map_adc_to_moisture(adc1);
            float moisture2 = map_adc_to_moisture(adc2);

            if (log_data(LOG_FILE, moisture1, moisture2) != 0) {
                fprintf(stderr, "Error logging data.\n");
            } else {
                printf("Moisture1: %.2f%%, Moisture2: %.2f%%\n", moisture1, moisture2);
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    printf("\nCleaning up...\n");
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

