#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define MOTOR_SHUTDOWN_PIN 17
#define OVERCURRENT_THRESHOLD 10.0
#define SENSITIVITY 0.1
#define OFFSET 0.05
#define LOG_FILE "current_log.csv"
#define SAMPLE_INTERVAL_SEC 1
#define SPI_RETRIES 3
#define SPI_SPEED_HZ 1000000

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *shutdown_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    unsigned int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd); spi_fd = -1; return -1;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd); spi_fd = -1; return -1;
    }

    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd); spi_fd = -1; return -1;
    }

    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    shutdown_line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!shutdown_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip); chip = NULL; return -1;
    }

    if (gpiod_line_request_output(shutdown_line, "current_monitor", 1) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip); chip = NULL; shutdown_line = NULL; return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    for (int attempt = 0; attempt < SPI_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n", attempt + 1, SPI_RETRIES, strerror(errno));
        usleep(10000);
    }
    return -1;
}

static float convert_to_current(int adc_value) {
    float voltage = (float)adc_value * 3.3f / 1024.0f;
    return (voltage - OFFSET) / SENSITIVITY;
}

static int log_current(float current) {
    int needs_header = 0;
    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        if (errno == ENOENT) needs_header = 1;
        else { perror("Failed to open log file"); return -1; }
    } else {
        fseek(fp, 0, SEEK_END);
        if (ftell(fp) == 0) needs_header = 1;
        fclose(fp);
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("Failed to open log file for writing"); return -1; }

    if (needs_header) {
        fprintf(fp, "Timestamp,Current_Amperes\n");
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, current);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (shutdown_line) {
        gpiod_line_set_value(shutdown_line, 1);
        gpiod_line_release(shutdown_line);
        shutdown_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float current = convert_to_current(adc_value);

        if (log_current(current) < 0) {
            fprintf(stderr, "Failed to log current reading.\n");
        }

        if (current > OVERCURRENT_THRESHOLD) {
            printf("Overcurrent detected! Current: %.2fA\n", current);
            if (gpiod_line_set_value(shutdown_line, 0) < 0) {
                perror("Failed to disable motor");
            }
            log_current(current);
            sleep(1);
            if (gpiod_line_set_value(shutdown_line, 1) < 0) {
                perror("Failed to re-enable motor");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

