#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_US      1000000  /* 1 second */
#define MAX_READ_ERRS  5

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: pigpio error %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure_kPa)
{
    int raw = i2cReadWordData(g_i2c_handle, PRESSURE_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading pressure register 0x%02X: pigpio error %d\n",
                PRESSURE_REG, raw);
        return -1;
    }
    /* pigpio returns the word as (high_byte << 8) | low_byte */
    unsigned int raw_u = (unsigned int)raw;
    *pressure_kPa = ((float)raw_u / 65535.0f) * 500.0f;
    return 0;
}

static int log_data(float pressure_kPa)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return -1;
    }
    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(g_log_file, "%s,%.2f\n", ts, pressure_kPa) < 0) {
        fprintf(stderr, "fprintf() to log file failed\n");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush() failed\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction() failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    if (fseek(g_log_file, 0, SEEK_END) != 0) {
        fprintf(stderr, "fseek() failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    long pos = ftell(g_log_file);
    if (pos < 0) {
        fprintf(stderr, "ftell() failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (pos == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0 || fflush(g_log_file) != 0) {
            fprintf(stderr, "Failed to write CSV header\n");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    int consecutive_errs = 0;

    while (g_running) {
        float pressure;
        if (read_pressure(&pressure) == 0) {
            if (log_data(pressure) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
            consecutive_errs = 0;
        } else {
            consecutive_errs++;
            fprintf(stderr, "Pressure read failed (%d consecutive)\n", consecutive_errs);
            if (consecutive_errs >= MAX_READ_ERRS) {
                fprintf(stderr, "Too many consecutive read failures; aborting\n");
                break;
            }
        }
        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

