    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction() failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    if (fseek(g_log_file, 0, SEEK_END) != 0) {
        fprintf(stderr, "fseek() failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    long pos = ftell(g_log_file);
    if (pos < 0) {
        fprintf(stderr, "ftell() failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (pos == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0 || fflush(g_log_file) != 0) {
            fprintf(stderr, "Failed to write CSV header\n");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    int consecutive_errs = 0;

    while (g_running) {
        float pressure;
        if (read_pressure(&pressure) == 0) {
            if (log_data(pressure) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
            consecutive_errs = 0;
        } else {
            consecutive_errs++;
            fprintf(stderr, "Pressure read failed (%d consecutive)\n", consecutive_errs);
            if (consecutive_errs >= MAX_READ_ERRS) {
                fprintf(stderr, "Too many consecutive read failures; aborting\n");
                break;
            }
        }
        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

