#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_MUX_AIN1 0x5000
#define ADS1115_CONFIG_PGA_2_048V 0x0000
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

#define LED_PIN 17
#define PRESSURE_THRESHOLD 105.0
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115(int handle, uint16_t mux) {
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | mux | ADS1115_CONFIG_PGA_2_048V |
                      ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS |
                      ADS1115_CONFIG_CQUE_NONE;

    char cfg[3];
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (config >> 8) & 0xFF;
    cfg[2] = config & 0xFF;

    if (i2cWriteDevice(handle, cfg, 3) < 0) {
        return -1;
    }

    gpioDelay(10000);

    char reg[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(handle, reg, 1) < 0) {
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) < 0) {
        return -1;
    }

    return (int16_t)((data[0] << 8) | data[1]);
}

static double convert_pressure(int16_t adc_value) {
    double voltage = (adc_value * 2.048) / 32768.0;
    return (voltage / 5.0) * 400.0;
}

static double convert_temperature(int16_t adc_value) {
    double voltage = (adc_value * 2.048) / 32768.0;
    return (voltage - 1.0) * 50.0;
}

