        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("MLX90834 Pressure Sensor Interface\n");
    printf("Press Ctrl+C to exit\n");

    while (running) {
        int16_t pressure_adc = -1;
        int16_t temp_adc = -1;
        int retry;

        for (retry = 0; retry < MAX_RETRIES; retry++) {
            pressure_adc = read_ads1115(i2c_handle, ADS1115_CONFIG_MUX_AIN0);
            if (pressure_adc >= 0) break;
            gpioDelay(10000);
        }

        if (pressure_adc < 0) {
            fprintf(stderr, "Error reading pressure ADC after %d retries\n", MAX_RETRIES);
            continue;
        }

        for (retry = 0; retry < MAX_RETRIES; retry++) {
            temp_adc = read_ads1115(i2c_handle, ADS1115_CONFIG_MUX_AIN1);
            if (temp_adc >= 0) break;
            gpioDelay(10000);
        }

        if (temp_adc < 0) {
            fprintf(stderr, "Error reading temperature ADC after %d retries\n", MAX_RETRIES);
            continue;
        }

        double pressure = convert_pressure(pressure_adc);
        double temperature = convert_temperature(temp_adc);

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(LED_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return 0;
