#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* Configuration */
#define SPI_CHANNEL      0          /* MCP3008 on SPI0 CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0 */
#define OVERCURRENT_THRESHOLD 10.0  /* Amperes */
#define SHUTDOWN_GPIO    27         /* GPIO pin for overcurrent indicator */
#define VREF             3.3        /* Reference voltage (Vcc) */
#define ZERO_CURRENT_MV  1650.0     /* MLX91209 zero-current midpoint (mV) */
#define SENSITIVITY_MV_PER_A 66.0   /* MLX91209 sensitivity (mV/A) */
#define SAMPLE_INTERVAL_US 100000   /* 100 ms */
#define LOG_FILE         "current_log.txt"

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int  read_adc(int channel);
static double adc_to_voltage(int adc_value);
static double voltage_to_current(double voltage);
static void log_data(double current);
static void overcurrent_event(double current);
static void signal_handler(int sig);
static void cleanup(void);

/* Read a single-ended channel from the MCP3008 */
static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, zero pad */
    unsigned char tx[3] = {
        0x01,
        (unsigned char)((channel & 0x07) << 4) | 0x80,
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* Convert ADC value to voltage (0-3.3V full-scale) */
static double adc_to_voltage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value %d\n", adc_value);
        return -1.0;
    }
    return (double)adc_value * VREF / 1024.0;
}

/* Convert voltage to current (A) using MLX91209 parameters */
static double voltage_to_current(double voltage) {
    if (voltage < 0.0) {
        fprintf(stderr, "Invalid voltage %f\n", voltage);
        return -1.0;
    }
    return (voltage - ZERO_CURRENT_MV / 1000.0) / (SENSITIVITY_MV_PER_A / 1000.0);
}

/* Log current reading with timestamp */
static void log_data(double current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime() failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

/* Log overcurrent event and trigger shutdown */
static void overcurrent_event(double current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime() failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, OVERCURRENT: %.2f A\n", timestamp, current);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }

    fprintf(stderr, "%s, OVERCURRENT: %.2f A\n", timestamp, current);

    /* Trigger shutdown GPIO */
    if (gpioWrite(SHUTDOWN_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO%d HIGH\n", SHUTDOWN_GPIO);
    }
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Reset GPIO27 to LOW before terminating */
    gpioWrite(SHUTDOWN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure overcurrent GPIO as output, initially LOW */
    if (gpioSetMode(SHUTDOWN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SHUTDOWN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SHUTDOWN_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO%d LOW\n", SHUTDOWN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Motor current monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double voltage = adc_to_voltage(adc_value);
        if (voltage < 0.0) {
            fprintf(stderr, "Voltage conversion error, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double current = voltage_to_current(voltage);
        if (current < 0.0) {
            fprintf(stderr, "Current conversion error, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        log_data(current);

        if (current > OVERCURRENT_THRESHOLD) {
            overcurrent_event(current);
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful cleanup */
    cleanup();
    fprintf(stderr, "Program terminated.\n");
    return EXIT_SUCCESS;
}

