        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Motor current monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double voltage = adc_to_voltage(adc_value);
        if (voltage < 0.0) {
            fprintf(stderr, "Voltage conversion error, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double current = voltage_to_current(voltage);
        if (current < 0.0) {
            fprintf(stderr, "Current conversion error, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        log_data(current);

        if (current > OVERCURRENT_THRESHOLD) {
            overcurrent_event(current);
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful cleanup */
    cleanup();
    fprintf(stderr, "Program terminated.\n");
    return EXIT_SUCCESS;
}

