// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_ads1115(int16_t *raw_value);
double convert_to_pressure(int16_t raw_value);
int log_pressure(double pressure);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Initialize I2C communication with ADS1115
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, ADS1115_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

// Read raw 16-bit value from ADS1115
int read_ads1115(int16_t *raw_value) {
    char config[3];
    char reg = ADS1115_REG_CONFIG;
    char buf[2];

    // Write config to start single conversion
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE) >> 8;
    config[2] = (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE) & 0xFF;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing ADS1115 config: %s\n", strerror(errno));
        return -1;
    }

    // Wait for conversion to complete (approx 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion register
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error setting ADS1115 register pointer: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion: %s\n", strerror(errno));
        return -1;
    }

    *raw_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw ADC value to pressure in kPa
double convert_to_pressure(int16_t raw_value) {
    double voltage = ((double)raw_value / 32768.0) * ADS1115_PGA_4_096V;
    double pressure = (voltage - OFFSET_V) / SENSITIVITY_V_PER_KPA;
    return pressure;
}

// Log pressure reading with timestamp to file
int log_pressure(double pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) == 0) {
            double pressure = convert_to_pressure(raw_value);
            if (pressure >= MIN_PRESSURE && pressure <= MAX_PRESSURE) {
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Error logging pressure reading.\n");
                }
            } else {
                fprintf(stderr, "Pressure reading out of range: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Error reading pressure sensor.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Pressure monitoring stopped.\n");
    return 0;
}

