#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3208_CHANNEL 0
#define HUMIDITY_THRESHOLD 80.0
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_SENDER "sender@example.com"
#define EMAIL_SUBJECT "Humidity Alert"
#define EMAIL_BODY "Humidity exceeds threshold!"
#define LOG_FILE "humidity_log.txt"
#define SUPPLY_VOLTAGE 5.0
#define ADC_MAX_VALUE 4095.0
#define VREF 3.3
#define R0 10000.0
#define T0 298.15
#define BETA 3950.0

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) return -1;
    return ((rx[1] & 0x0F) << 8) | rx[2];
}

static float read_humidity(void) {
    int raw = read_mcp3208(MCP3208_CHANNEL);
    if (raw < 0) return -1.0;
    float vout = (raw / ADC_MAX_VALUE) * VREF;
    float rh = (vout - 0.824) / 0.0315;
    if (rh < 0.0) rh = 0.0;
    if (rh > 100.0) rh = 100.0;
    return rh;
}

static float read_temperature(void) {
    int raw = read_mcp3208(MCP3208_CHANNEL);
    if (raw < 0) return -273.15;
    float vout = (raw / ADC_MAX_VALUE) * VREF;
    float r = (SUPPLY_VOLTAGE / vout) - 1.0;
    if (r <= 0.0) return -273.15;
    float t = 1.0 / (1.0 / (T0 + 273.15) + (1.0 / BETA) * log(r / R0));
    return t - 273.15;
}

static void send_email_alert(float humidity, float temperature) {
    char body[256];
    snprintf(body, sizeof(body), "Humidity: %.2f%%, Temperature: %.2f°C", humidity, temperature);
    char command[512];
    snprintf(command, sizeof(command), "echo \"%s\" | ssmtp -s \"%s\" -a \"From: %s\" %s", body, EMAIL_SUBJECT, EMAIL_SENDER, EMAIL_RECIPIENT);
    int ret = system(command);
    if (ret == -1) fprintf(stderr, "Error: Failed to execute ssmtp\n");
}

static void log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Cannot open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");
    while (!terminate) {
        float humidity = read_humidity();
        float temperature = read_temperature();
        if (humidity < 0.0 || temperature < -273.0) {
            fprintf(stderr, "Error: Sensor read failed\n");
        } else {
            printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);
            if (humidity > HUMIDITY_THRESHOLD) {
                send_email_alert(humidity, temperature);
            }
            log_data(humidity, temperature);
        }
        sleep(60);
    }
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Humidity monitoring stopped.\n");
    return 0;
}

