/*
 * Si1172-A30-GMR Optical Heart Rate Sensor Reader
 * Board:  Raspberry Pi Zero W
 * Library: pigpio (I2C bus 1, address 0x49)
 * Output:  biometric_log.csv (CSV header + Unix timestamp,HR,SpO2,error_flag)
 *
 * NOTE: The Si1172 is a proprietary sensor from Silicon Labs.  It does NOT
 *       provide a direct HR/SpO2 conversion algorithm.  The raw 16-bit ADC
 *       values (IR and RED) are read from the FIFO and logged as proxies.
 *       A full implementation requires the proprietary Si1172 firmware and
 *       the Si1172 datasheet.  This code provides a minimal I2C read loop
 *       that logs the raw ADC values for HR and SpO2.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1172 I2C constants (7-bit address 0x49) ---- */
#define SI1172_I2C_BUS        1
#define SI1172_I2C_ADDR       0x49

/* Si1172 command register */
#define SI1172_REG_COMMAND    0xC0

/* Si1172 FIFO data registers (16-bit, little-endian on bus) */
#define SI1172_REG_FIFO_IR    0xC1
#define SI1172_REG_FIFO_RED   0xC2
#define SI1172_REG_FIFO_GREEN 0xC3
#define SI1172_REG_FIFO_UV    0xC4

/* Command codes (sent to SI1172_REG_COMMAND) */
#define SI1172_CMD_START      0x01  /* Start / reset measurement */
#define SI1172_CMD_READ_FIFO  0x02  /* Read FIFO data */

/* Error codes */
#define ERR_OK               0
#define ERR_I2C             -1
#define ERR_SENSOR_ABSENT   -2
#define ERR_READ            -3

/* Globals for signal handler */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a Si1172 register                                 */
/* ------------------------------------------------------------------ */
static int si1172_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return ERR_I2C;
    }
    return ERR_OK;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a Si1172 register                                 */
/* ------------------------------------------------------------------ */
static int si1172_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return ERR_I2C;
    }
    *value = (uint8_t)rc;
    return ERR_OK;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from a Si1172 register            */
/* ------------------------------------------------------------------ */
static int si1172_read_reg16(uint8_t reg, uint16_t *value)
{
    uint8_t lo, hi;
    int rc = i2cReadI2CBlockData(g_i2c_handle, reg, (char *)&lo, 1);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, lo) failed: %d\n", reg, rc);
        return ERR_I2C;
    }
    rc = i2cReadI2CBlockData(g_i2c_handle, reg + 1, (char *)&hi, 1);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, hi) failed: %d\n", reg + 1, rc);
        return ERR_I2C;
    }
    *value = (uint16_t)((hi << 8) | lo);
    return ERR_OK;
}

/* ------------------------------------------------------------------ */
/* Trigger a measurement and read one sample from the FIFO            */
/* ------------------------------------------------------------------ */
static int si1172_read_fifo_sample(uint16_t *ir, uint16_t *red)
{
    uint8_t cmd;

    /* Trigger a measurement by writing the START command */
    cmd = SI1172_CMD_START;
    if (si1172_write_reg(SI1172_REG_COMMAND, cmd) != ERR_OK)
        return ERR_I2C;

    /* Small delay for the measurement to complete */
    gpioDelay(2000);  /* 2 ms */

    /* Read the FIFO data: IR in C1/C2, RED in C3/C4 */
    if (si1172_read_reg16(SI1172_REG_FIFO_IR, ir) != ERR_OK)
        return ERR_I2C;
    if (si1172_read_reg16(SI1172_REG_FIFO_RED, red) != ERR_OK)
        return ERR_I2C;

    return ERR_OK;
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file                                    */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int hr, int spo2, int error_code)
{
    time_t now = time(NULL);
    fprintf(fp, "%ld,%d,%d,%d\n", (long)now, hr, spo2, error_code);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1172 default address */
    g_i2c_handle = i2cOpen(SI1172_I2C_BUS, SI1172_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                SI1172_I2C_BUS, SI1172_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("biometric_log.csv", "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open biometric_log.csv for writing\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,HR,SpO2,error_code\n");
        fflush(g_log_file);
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1172 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t ir = 0, red = 0;
        int error_code = ERR_OK;

        error_code = si1172_read_fifo_sample(&ir, &red);
        if (error_code != ERR_OK) {
            /* Log error row: sensor absent or I2C bus error */
            if (error_code == ERR_I2C) {
                fprintf(stderr, "[WARN] I2C communication error — sensor may be absent or bus fault\n");
                error_code = ERR_I2C;
            } else {
                fprintf(stderr, "[WARN] Sensor absent or uninitialized (no response to START command)\n");
                error_code = ERR_SENSOR_ABSENT;
            }
            log_data(g_log_file, -1, -1, error_code);
        } else {
            /* Proxy HR/SpO2 values (Si1172 has proprietary algorithm) */
            log_data(g_log_file, (int)ir, (int)red, ERR_OK);
        }

        /* Sleep 1 second between samples */
        gpioDelay(1000000);  /* 1,000,000 microseconds */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

