#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x67
#define MEASURE_CMD 0x6845
#define CSV_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL_SEC 5
#define CONVERSION_DELAY_MS 20

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *data, size_t len) {
    if (read(fd, data, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, uint16_t *pressure, uint16_t *temperature) {
    if (i2c_write_cmd(fd, MEASURE_CMD) < 0) return -1;
    usleep(CONVERSION_DELAY_MS * 1000);

    uint8_t data[6];
    if (i2c_read_data(fd, data, 6) < 0) return -1;

    *pressure = ((uint16_t)data[0] << 8) | data[1];
    *temperature = ((uint16_t)data[3] << 8) | data[4];
    return 0;
}

static int calibrate_sensor(uint16_t raw_pressure, uint16_t raw_temperature,
                            float *temperature, float *pressure) {
    /* Placeholder calibration constants (replace with actual values from datasheet) */
    const float P_SENS = 0.1f;
    const float T_SENS = 0.01f;
    const float P_OFFSET = 0.0f;
    const float T_OFFSET = 0.0f;

    float p_comp = (float)raw_pressure * P_SENS + P_OFFSET;
    float t_comp = (float)raw_temperature * T_SENS + T_OFFSET;

    *pressure = p_comp;
    *temperature = t_comp;
    return 0;
}

static int log_data(FILE *fp, float temperature, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, pressure) < 0) {
        fprintf(stderr, "Failed to write to CSV: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ICP10125_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(CSV_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open CSV file %s: %s\n", CSV_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Pressure(Pa)\n");
    }

    printf("Weather station prototype started. Logging to %s\n", CSV_FILE);

    while (running) {
        uint16_t raw_pressure, raw_temperature;
        if (read_sensor_data(i2c_fd, &raw_pressure, &raw_temperature) == 0) {
            float temperature, pressure;
            if (calibrate_sensor(raw_pressure, raw_temperature, &temperature, &pressure) == 0) {
                if (log_data(log_file, temperature, pressure) == 0) {
                    printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
                }
            } else {
                fprintf(stderr, "Sensor calibration failed\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

