#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNELS 8
#define SAMPLE_RATE 1000
#define GAIN 1.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel >= MCP3008_CHANNELS) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        GAIN = atof(argv[1]);
        if (GAIN <= 0.0) {
            fprintf(stderr, "Error: Gain must be a positive number.\n");
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed.\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Sampling audio from two microphones... (Press Ctrl+C to stop)\n");

    while (running) {
        int mic1 = read_mcp3008(0);
        int mic2 = read_mcp3008(1);

        if (mic1 < 0 || mic2 < 0) {
            fprintf(stderr, "Error: Failed to read microphone data.\n");
            break;
        }

        int diff = (int)((mic1 - mic2) * GAIN);
        printf("%d,%d\n", mic1, diff);

        gpioDelay(1000000 / SAMPLE_RATE);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("\nProgram terminated cleanly.\n");
    return 0;
}

