#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define LED_GPIO    17
#define WATER_CHANNEL 0
#define JSON_FILE   "water_levels.json"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds in microseconds */
#define POLL_INTERVAL_US    100000   /* 100 ms poll interval */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_json_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI transfer error.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer.
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static float calculate_water_level(int adc_value)
{
    return (float)adc_value / 1023.0f * 100.0f;
}

static void control_led(float water_level)
{
    if (water_level > 75.0f) {
        gpioWrite(LED_GPIO, 1);
    } else if (water_level < 70.0f) {
        gpioWrite(LED_GPIO, 0);
    }
}

static void log_to_json(float water_level)
{
    if (g_json_fp == NULL) {
        fprintf(stderr, "JSON file not open\n");
        return;
    }

    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_json_fp, "  {\"timestamp\": \"%s.%03d\", \"water_level\": %.2f}\n",
            timestamp, (int)((rawtime % 1000) * 1000),
            water_level);
    fflush(g_json_fp);
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open JSON log file (write '[' prefix) --- */
    g_json_fp = fopen(JSON_FILE, "w");
    if (g_json_fp == NULL) {
        perror("Failed to open JSON file");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(g_json_fp, "[\n");
    fflush(g_json_fp);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(WATER_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, skipping sample\n");
        } else {
            float water_level = calculate_water_level(adc_value);
            control_led(water_level);
            log_to_json(water_level);
            printf("Water Level: %.2f%% (ADC: %d)\n", water_level, adc_value);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(POLL_INTERVAL_US / 50);
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");

    /* Close JSON file (write trailing ']') */
    if (g_json_fp != NULL) {
        fprintf(g_json_fp, "]\n");
        fclose(g_json_fp);
        g_json_fp = NULL;
    }

    /* Close SPI */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Turn off LED */
    gpioWrite(LED_GPIO, 0);

    /* Terminate pigpio */
    gpioTerminate();

    printf("Water level monitoring stopped.\n");
    return EXIT_SUCCESS;
}

