#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_RAW 300
#define DEFAULT_MAX_RAW 700
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOGGING_FREQUENCY 60
#define DEFAULT_EMAIL_RECIPIENT "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG "/etc/msmtprc"

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int spi_channel;
    int adc_channel;
    int min_raw;
    int max_raw;
    int moisture_threshold;
    int logging_frequency;
    char *email_recipient;
    char *msmtp_config;
} Config;

static Config config = {
    DEFAULT_SPI_CHANNEL,
    DEFAULT_ADC_CHANNEL,
    DEFAULT_MIN_RAW,
    DEFAULT_MAX_RAW,
    DEFAULT_MOISTURE_THRESHOLD,
    DEFAULT_LOGGING_FREQUENCY,
    DEFAULT_EMAIL_RECIPIENT,
    DEFAULT_MSMTP_CONFIG
};

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calibrate_moisture(int raw_value, int min_raw, int max_raw) {
    if (max_raw <= min_raw) {
        fprintf(stderr, "Error: Invalid calibration range (max=%d, min=%d)\n", max_raw, min_raw);
        return -1;
    }
    return (int)(((float)(raw_value - min_raw) / (float)(max_raw - min_raw)) * 100.0);
}

static int log_data(int moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("plant_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open plant_data.txt for writing\n");
        return -1;
    }

    if (fprintf(fp, "%s, %d\n", timestamp, moisture_percentage) < 0) {
        fprintf(stderr, "Error: Failed to write to plant_data.txt\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Failed to close plant_data.txt\n");
        return -1;
    }

    return 0;
}

static int send_email_alert(int moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    char command[512];
    int ret = snprintf(command, sizeof(command),
        "echo \"Subject: Soil Moisture Alert\n\nPlant moisture is below threshold at %s. Current moisture: %d%%\" | msmtp -t %s -C %s",
        timestamp, moisture_percentage, config.email_recipient, config.msmtp_config);

    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: Email command buffer too small\n");
        return -1;
    }

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to execute msmtp command\n");
        return -1;
    }

    int status = pclose(fp);
    if (status == -1) {
        fprintf(stderr, "Error: pclose failed\n");
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    if (WIFSIGNALED(status)) {
        fprintf(stderr, "Error: msmtp killed by signal %d\n", WTERMSIG(status));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
