    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("plant_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open plant_data.txt for writing\n");
        return -1;
    }

    if (fprintf(fp, "%s, %d\n", timestamp, moisture_percentage) < 0) {
        fprintf(stderr, "Error: Failed to write to plant_data.txt\n");
        fclose(fp);
        return -1;
    }

