#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0
#define SPI_SPEED 1000000   // 1 MHz
#define ADC_CHANNEL 0       // MCP3008 channel 0
#define VREF 3.3            // Reference voltage
#define MIN_VOLTAGE 0.5     // Minimum sensor output voltage (V)
#define MAX_VOLTAGE 4.5     // Maximum sensor output voltage (V)
#define MIN_PRESSURE 10.0   // Minimum pressure (kPa)
#define MAX_PRESSURE 150.0  // Maximum pressure (kPa)
#define SAMPLE_INTERVAL 1   // Sample interval in seconds

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
double adc_to_voltage(int adc_value);
double voltage_to_pressure(double voltage);
void log_pressure(double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

// Function to read from MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode
    // Start bit (1), SGL/DIFF=1 (single), D2 D1 D0 (channel), then don't care
    unsigned char tx_buf[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx_buf[3] = {0};

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
double adc_to_voltage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1.0;
    }
    return (double)adc_value * VREF / 1023.0;
}

// Function to convert voltage to pressure (kPa)
double voltage_to_pressure(double voltage) {
    if (voltage < 0.0 || voltage > VREF) {
        fprintf(stderr, "Error: Voltage out of range: %.3f V\n", voltage);
        return -1.0;
    }

    // Check for sensor-absent conditions (stuck at 0V or 3.3V)
    if (voltage < 0.01 || voltage > VREF - 0.01) {
        fprintf(stderr, "Warning: Sensor output may be disconnected or shorted (voltage %.3f V)\n", voltage);
    }

    double pressure = MIN_PRESSURE + (voltage - MIN_VOLTAGE) * (MAX_PRESSURE - MIN_PRESSURE) / (MAX_VOLTAGE - MIN_VOLTAGE);
    return pressure;
}

// Function to log pressure readings with timestamps
void log_pressure(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
    fflush(stdout);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination signals
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGTERM handler: %s\n", strerror(errno));
    }

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("Reading every %d seconds. Press Ctrl+C to exit.\n", SAMPLE_INTERVAL);

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        double voltage = adc_to_voltage(adc_value);
        if (voltage < 0.0) {
            fprintf(stderr, "Error: Failed to convert ADC value to voltage\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        double pressure = voltage_to_pressure(voltage);
        if (pressure < 0.0) {
            fprintf(stderr, "Error: Failed to convert voltage to pressure\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        log_pressure(pressure);

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    cleanup();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

