#define MAX_ADC_VALUE   700

#define GPIO_CHIP       "gpiochip0"
#define CS_PIN          8

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int read_mcp3008(int fd, int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((channel & 0x07) << 4) | 0x80,
        0x00
    };
    uint8_t rx[3] = {0};

