        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_moisture(int adc_value) {
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    float moisture = 100.0f - ((float)(adc_value - MIN_ADC_VALUE) /
                                (float)(MAX_ADC_VALUE - MIN_ADC_VALUE)) * 100.0f;

    if (moisture < 0.0f) moisture = 0.0f;
    if (moisture > 100.0f) moisture = 100.0f;
