#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define VREF 3.3
#define NUM_SENSORS 4
#define LOG_FILE "environmental_data.csv"

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, 8);
    if (!cs_line) {
        fprintf(stderr, "Error getting GPIO line 8: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        fprintf(stderr, "Error requesting CS line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        cs_line = NULL;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error setting CS low: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error setting CS high: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0f) * VREF;
}

static void log_data(float voltages[NUM_SENSORS]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_fp, "%s", timestamp);
    for (int i = 0; i < NUM_SENSORS; i++) {
        fprintf(log_fp, ",%.3f", voltages[i]);
    }
    fprintf(log_fp, "\n");
    fflush(log_fp);
}

static void cleanup(void) {
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(spi_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        fprintf(log_fp, "Timestamp,Sensor1,Sensor2,Sensor3,Sensor4\n");
        fflush(log_fp);
    }

    while (running) {
        float voltages[NUM_SENSORS];
        int error = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                error = 1;
                break;
            }
            voltages[i] = adc_to_voltage(adc_value);
        }

        if (!error) {
            log_data(voltages);
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

