#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 17
#define MOISTURE_CHANNEL 0
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_MS 5000

#define MCP3008_START_BIT 0x01
#define MCP3008_SINGLE_ENDED 0x80

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        MCP3008_START_BIT | (channel & 0x07) | MCP3008_SINGLE_ENDED,
        0x00,
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write pump GPIO %d\n", PUMP_GPIO);
    }
}

static void log_data(int moisture_level, int pump_state) {
    time_t now = time(NULL);
    LogEntry entry;
    entry.timestamp = now;
    entry.moisture_level = moisture_level;
    entry.pump_state = pump_state;

    log_buffer[buffer_index] = entry;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }

    char time_str[32];
    struct tm *tm_info = localtime(&now);
    if (tm_info) {
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
    } else {
        strncpy(time_str, "UNKNOWN", sizeof(time_str));
    }

    printf("[%s] Moisture: %d, Pump: %s\n",
           time_str, moisture_level, pump_state ? "ON" : "OFF");
}

static void timer_callback(void *user_data) {
    (void)user_data;

    int moisture_level = read_mcp3008(MOISTURE_CHANNEL);
    if (moisture_level < 0) {
        fprintf(stderr, "Failed to read moisture sensor\n");
        return;
    }

    int pump_state = gpioRead(PUMP_GPIO);
    if (pump_state < 0) {
        fprintf(stderr, "Failed to read pump GPIO %d\n", PUMP_GPIO);
        return;
    }

    if (moisture_level < LOW_THRESHOLD && pump_state == 0) {
        control_pump(1);
        log_data(moisture_level, 1);
    } else if (moisture_level > HIGH_THRESHOLD && pump_state == 1) {
        control_pump(0);
        log_data(moisture_level, 0);
    } else {
        log_data(moisture_level, pump_state);
    }
}

static void print_log_buffer(void) {
    printf("\n--- Log Buffer (%d entries) ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&log_buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
        }
        printf("[%s] Moisture: %d, Pump: %s\n",
               time_str, log_buffer[idx].moisture_level,
               log_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO %d as output\n", PUMP_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer\n");
        control_pump(0);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitoring System started.\n");
    printf("SPI: channel %d, speed %d Hz, MCP3008 ch %d\n",
           SPI_CHANNEL, SPI_SPEED, MOISTURE_CHANNEL);
    printf("Pump: GPIO %d, low threshold %d, high threshold %d\n",
           PUMP_GPIO, LOW_THRESHOLD, HIGH_THRESHOLD);
    printf("Sampling every %d ms. Press Ctrl+C to exit.\n\n",
           SAMPLE_INTERVAL_MS);

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    print_log_buffer();
    return EXIT_SUCCESS;
}

