#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_ENABLE_1 0x01
#define REG_FIFO_WR_PTR 0x02
#define REG_OVF_COUNTER 0x03
#define REG_FIFO_RD_PTR 0x04
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED1_PA 0x0C
#define REG_LED2_PA 0x0D
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15
#define SAMPLE_RATE 100
#define SAMPLE_INTERVAL_US (1000000 / SAMPLE_RATE)
#define LOG_FILE "health_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int max30102_write(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, rc=%d\n", reg, rc);
    }
    return rc;
}

static int max30102_read(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int max30102_read_burst(uint8_t reg, uint8_t *buf, int len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "I2C block read failed: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int init_max30102(void) {
    uint8_t part_id;
    if (max30102_read(REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read Part ID - sensor absent or bus error\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("MAX30102 detected (Part ID: 0x%02X)\n", part_id);

    if (max30102_write(REG_MODE_CONFIG, 0x40) != 0) return -1; /* Reset */
    gpioDelay(10000);

    if (max30102_write(REG_INTR_ENABLE_1, 0x00) != 0) return -1;
    if (max30102_write(REG_FIFO_WR_PTR, 0x00) != 0) return -1;
    if (max30102_write(REG_OVF_COUNTER, 0x00) != 0) return -1;
    if (max30102_write(REG_FIFO_RD_PTR, 0x00) != 0) return -1;
    if (max30102_write(REG_FIFO_CONFIG, 0x0F) != 0) return -1; /* 17 samples avg, FIFO rollover */
    if (max30102_write(REG_MODE_CONFIG, 0x03) != 0) return -1; /* SpO2 mode */
    if (max30102_write(REG_SPO2_CONFIG, 0x27) != 0) return -1; /* 100Hz, 411us pulse width, 4096 ADC range */
    if (max30102_write(REG_LED1_PA, 0x24) != 0) return -1;
    if (max30102_write(REG_LED2_PA, 0x24) != 0) return -1;

    return 0;
}

static int read_fifo_sample(uint32_t *red, uint32_t *ir) {
    uint8_t buf[6];
    if (max30102_read_burst(REG_FIFO_DATA, buf, 6) != 0) return -1;
    *red = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
