        printf("ADC Value: %d\n", adc_value);

        if (adc_value < THRESHOLD) {
            if (control_buzzer(BUZZER_GPIO, 1) != 0) {
                break;
            }
        } else {
            if (control_buzzer(BUZZER_GPIO, 0) != 0) {
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    control_buzzer(BUZZER_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

