/*
 * door_lock.c — Raspberry Pi 5 (64-bit Bookworm, kernel 6.6+)
 *
 * Proximity-triggered magnetic door lock with a Sharp GP2Y0A21YK0F IR
 * distance sensor driven by an ADS1115 ADC (I2C 0x48) and a 5 V relay
 * module on GPIO17.  A magnetic reed switch on GPIO27 (active-low, pulled
 * high) indicates the door is open.
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_lock door_lock.c -lgpiod
 *
 * Wiring:
 *   ADS1115 SDA -> GPIO2  (I2C bus 1)
 *   ADS1115 SCL -> GPIO3  (I2C bus 1)
 *   ADS1115 ADDR-> GND   (I2C address 0x48)
 *   ADS1115 A0  -> GP2Y0A21YK0F analog output
 *   Relay IN    -> GPIO17 (active-high)
 *   Reed switch-> GPIO27 (active-low, pulled high)
 */

#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <time.h>
#include <unistd.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

#define ADS_REG_CONV   0x00
#define ADS_REG_CONFIG 0x01

/* Config: single-shot, AIN0 single-ended, 4.096 V, 128 SPS, no comparator */
#define ADS_CFG_BASE   0x8000  /* OS bit */
#define ADS_CFG_MUX0   0x4000  /* MUX[14:12] = 100 -> AIN0 single-ended */
#define ADS_CFG_PGA4   0x0200  /* PGA[11:9] = 001 -> +/-4.096 V */
#define ADS_CFG_DR128  0x0080  /* DR[7:5] = 100 -> 128 SPS */
#define ADS_CFG_CQUE   0x0003  /* COMP_QUE[1:0] = 11 -> disable comparator */

#define RELAY_OFFSET   17
#define REED_OFFSET    27

#define LOG_FILE       "/var/log/door_events.log"
#define SAMPLES        10
#define SAMPLE_DELAY   50000   /* 50 ms in microseconds */
#define POLL_DELAY     200000  /* 200 ms in microseconds */
#define RELAY_HOLD     3       /* seconds */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        struct tm tm;
        localtime_r(&ts.tv_sec, &tm);
        char tbuf[32];
        strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000L, msg);
    } else {
        perror("clock_gettime");
        fprintf(fp, "(timestamp error): %s\n", msg);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                        */
/* ------------------------------------------------------------------ */

static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    struct i2c_msg msg = { .addr = ADS1115_ADDR, .flags = 0,
                           .len = 3, .buf = buf };
    struct i2c_rdwr_ioctl_data data = { .msgs = &msg, .nmsgs = 1 };
    if (ioctl(fd, I2C_RDWR, &data) < 0)
        return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t wbuf = reg;
    struct i2c_msg msgs[2] = {
        { .addr = ADS1115_ADDR, .flags = 0,        .len = 1, .buf = &wbuf },
        { .addr = ADS1115_ADDR, .flags = I2C_M_RD, .len = 2, .buf = (uint8_t *)out }
    };
    struct i2c_rdwr_ioctl_data data = { .msgs = msgs, .nmsgs = 2 };
    if (ioctl(fd, I2C_RDWR, &data) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADS1115                                                            */
/* ------------------------------------------------------------------ */

static int ads1115_init(int fd)
{
    uint16_t cfg = ADS_CFG_BASE | ADS_CFG_MUX0 | ADS_CFG_PGA4 |
                   ADS_CFG_DR128 | ADS_CFG_CQUE;
    if (i2c_write16(fd, ADS_REG_CONFIG, cfg) < 0) {
        perror("ads1115 config write");
        return -1;
    }
    return 0;
}

/*
 * Trigger a single conversion, wait for completion, and read the result.
 * Returns 0 on success and stores the raw 16-bit signed value in *out.
 * Returns -1 on I2C error.
 */
static int ads1115_read(int fd, int16_t *out)
{
    uint16_t cfg = ADS_CFG_BASE | ADS_CFG_MUX0 | ADS_CFG_PGA4 |
                   ADS_CFG_DR128 | ADS_CFG_CQUE;
    if (i2c_write16(fd, ADS_REG_CONFIG, cfg) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    uint16_t raw;
    if (i2c_read16(fd, ADS_REG_CONV, &raw) < 0)
        return -1;

    /* Sign-extend 16-bit two's complement to int16_t */
    if (raw & 0x8000)
        *out = (int16_t)(raw - 0x10000);
    else
        *out = (int16_t)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                              */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa = { .sa_handler = sighandler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (ads1115_init(i2c_fd) < 0) {
        fprintf(stderr, "ADS1115 init failed — sensor absent or bus error\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open gpiochip4 (RPi 5 default) */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay = gpiod_chip_get_line(chip, RELAY_OFFSET);
    struct gpiod_line *reed  = gpiod_chip_get_line(chip, REED_OFFSET);
    if (!relay || !reed) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay, "door_lock", 0) < 0 ||
        gpiod_line_request_input(reed, "door_lock") < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Baseline calibration */
    int16_t samples[SAMPLES];
    printf("Taking %d baseline samples (50 ms apart)...\n", SAMPLES);
    for (int i = 0; i < SAMPLES; i++) {
        if (ads1115_read(i2c_fd, &samples[i]) < 0) {
            fprintf(stderr, "Baseline sample %d read failed\n", i);
            gpiod_line_set_value(relay, 0);
            gpiod_line_release(relay);
            gpiod_line_release(reed);
            gpiod_chip_close(chip);
            close(i2c_fd);
            return EXIT_FAILURE;
        }
        usleep(SAMPLE_DELAY);
    }

    int64_t sum = 0;
    for (int i = 0; i < SAMPLES; i++)
        sum += samples[i];
    int threshold = (int)(sum / SAMPLES * 0.8);
    printf("Calibrated threshold: %d\n", threshold);

    printf("Door lock controller running.  Ctrl+C to exit.\n");

    while (g_running) {
        int16_t val;
        if (ads1115_read(i2c_fd, &val) < 0) {
            log_event("ERROR: I2C read failed");
            usleep(POLL_DELAY);
            continue;
        }

        if (val < threshold) {
            printf("Proximity detected (distance=%d).  Energizing relay.\n", val);
            log_event("Proximity detected — releasing door lock");

            if (gpiod_line_set_value(relay, 1) < 0)
                log_event("ERROR: relay set HIGH failed");

            sleep(RELAY_HOLD);

            if (gpiod_line_set_value(relay, 0) < 0)
                log_event("ERROR: relay set LOW failed");

            int door_open = (gpiod_line_get_value(reed) == 0) ? 1 : 0;
            log_event(door_open ? "Door opened" : "Door not opened");
        }

        usleep(POLL_DELAY);
    }

    /* Cleanup */
    gpiod_line_set_value(relay, 0);
    gpiod_line_release(relay);
    gpiod_line_release(reed);
    gpiod_chip_close(chip);
    close(i2c_fd);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

