#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define DRY_RAW 200
#define WET_RAW 800
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_INTERVAL 60
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int pump_state = 0;

static void log_message(const char *msg) {
    FILE *fp = fopen("irrigation.log", "a");
    if (!fp) { perror("fopen log"); return; }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s: %s\n", ts, msg);
    fclose(fp);
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = {0};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int val = ((rx[1] & 0x03) << 8) | rx[2];
            return val;
        }
        char msg[128];
        snprintf(msg, sizeof(msg), "SPI transfer failed (attempt %d/%d, ret=%d)", attempt + 1, MAX_RETRIES, ret);
        log_message(msg);
        gpioDelay(100000);
    }
    return -1;
}

static int raw_to_moisture(int raw) {
    if (raw < DRY_RAW) raw = DRY_RAW;
    if (raw > WET_RAW) raw = WET_RAW;
    return (int)(((float)(raw - DRY_RAW) / (float)(WET_RAW - DRY_RAW)) * 100.0f);
}

static void control_pump(int on) {
    if (on && !pump_state) {
        gpioWrite(PUMP_GPIO, 1);
        pump_state = 1;
        log_message("Pump activated");
    } else if (!on && pump_state) {
        gpioWrite(PUMP_GPIO, 0);
        pump_state = 0;
        log_message("Pump deactivated");
    }
}

static void cleanup(void) {
    if (pump_state) control_pump(0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int interval = DEFAULT_INTERVAL;

    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't': threshold = atoi(optarg); break;
            case 'd': duration = atoi(optarg); break;
            case 's': interval = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s interval]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (threshold < 0 || threshold > 100) {
        fprintf(stderr, "Threshold must be 0-100\n");
        return EXIT_FAILURE;
    }
    if (duration <= 0) duration = DEFAULT_DURATION;
    if (interval <= 0) interval = DEFAULT_INTERVAL;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Irrigation system started");

    while (running) {
        int raw = read_mcp3008(0);
        if (raw < 0) {
            log_message("Sensor read failed; skipping cycle");
            for (int i = 0; i < interval && running; i++) sleep(1);
            continue;
        }

        int moisture = raw_to_moisture(raw);
        char msg[128];
        snprintf(msg, sizeof(msg), "Moisture: %d%% (raw=%d)", moisture, raw);
        log_message(msg);

        if (moisture < threshold) {
            control_pump(1);
            for (int i = 0; i < duration && running; i++) sleep(1);
            control_pump(0);
        }

        for (int i = 0; i < interval && running; i++) sleep(1);
    }

    log_message("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

