#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define SAMPLE_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the PCF8591 slave address */
    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring PCF8591 AIN0 at 0x%02X on %s (Ctrl-C to stop)\n",
           PCF8591_ADDR, I2C_BUS);

    while (g_running) {
        uint8_t ctrl = 0x00;   /* single-ended channel 0, analog output disabled */
        uint8_t buf[2] = {0};

        /* Write control byte to select channel 0 */
        if (write(fd, &ctrl, 1) != 1) {
            fprintf(stderr, "write control byte failed: %s\n", strerror(errno));
            goto cleanup;
        }

        /* Dummy read: PCF8591 returns the result of the previous conversion */
        ssize_t n = read(fd, buf, 1);
        if (n != 1) {
            fprintf(stderr, "dummy read failed (got %zd bytes): %s\n",
                    n, n < 0 ? strerror(errno) : "short read");
            goto cleanup;
        }

        /* Read the actual conversion result */
        n = read(fd, buf, 1);
        if (n != 1) {
            fprintf(stderr, "read conversion failed (got %zd bytes): %s\n",
                    n, n < 0 ? strerror(errno) : "short read");
            goto cleanup;
        }

        printf("AIN0: %u\n", (unsigned)buf[0]);
        fflush(stdout);

        usleep(SAMPLE_DELAY_US);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        if (close(fd) < 0) {
            fprintf(stderr, "close failed: %s\n", strerror(errno));
            rc = EXIT_FAILURE;
        }
    }
    return rc;
}

