#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8000  /* single-shot, AIN0 single-ended */
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_PGA_4_096V 4.096
#define ADS1115_MAX_COUNTS 32767.0
#define ADS1115_VREF 3.3
#define SS49E_ZERO_FIELD_V 2.5
#define SS49E_SENSITIVITY 0.0014
#define BUFFER_SIZE 10
#define THRESHOLD_GAUSS 500.0
#define GPIO_SHUTDOWN 27
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ads1115_raw(int handle, int16_t *raw) {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE) >> 8;
    config[2] = (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE) & 0xFF;

    if (i2cWriteDevice(handle, config, 3) < 0) {
        syslog(LOG_ERR, "I2C write config failed");
        return -1;
    }

    /* Wait for conversion (~8 ms at 128 SPS, use 10 ms for safety) */
    gpioDelay(10000);

    char reg = ADS1115_REG_CONV;
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        syslog(LOG_ERR, "I2C write pointer failed");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) < 0) {
        syslog(LOG_ERR, "I2C read conversion failed");
        return -1;
    }

    *raw = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

static double raw_to_voltage(int16_t raw) {
    return ((double)raw / ADS1115_MAX_COUNTS) * ADS1115_VREF;
}

static double voltage_to_gauss(double v) {
    return (v - SS49E_ZERO_FIELD_V) / SS49E_SENSITIVITY;
}

static void add_reading(double gauss, double *buffer, int *index, int size) {
    buffer[*index] = gauss;
    *index = (*index + 1) % size;
}

static double rolling_average(const double *buffer, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) sum += buffer[i];
    return sum / (double)size;
}

static void shutdown_motor(void) {
    gpioWrite(GPIO_SHUTDOWN, 1);
    syslog(LOG_CRIT, "Motor shutdown triggered (threshold exceeded)");
}

int main(void) {
    openlog("hall_sensor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d addr 0x%02X", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0);

    double buffer[BUFFER_SIZE] = {0.0};
    int buf_index = 0;

    syslog(LOG_INFO, "Hall sensor monitoring started (ADS1115 @ 0x%02X, GPIO%d)", I2C_ADDR, GPIO_SHUTDOWN);

    while (running) {
        int16_t raw;
        if (read_ads1115_raw(i2c_handle, &raw) != 0) {
            syslog(LOG_ERR, "ADC read failed, skipping sample");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double voltage = raw_to_voltage(raw);
        if (voltage < 0.0 || voltage > ADS1115_VREF) {
            syslog(LOG_ERR, "Invalid voltage reading: %.4f V", voltage);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double gauss = voltage_to_gauss(voltage);
        add_reading(gauss, buffer, &buf_index, BUFFER_SIZE);

        double avg = rolling_average(buffer, BUFFER_SIZE);
        syslog(LOG_INFO, "Voltage: %.4f V, Gauss: %.2f, Avg: %.2f Gauss", voltage, gauss, avg);

        if (avg > THRESHOLD_GAUSS) {
            shutdown_motor();
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down cleanly");
    gpioWrite(GPIO_SHUTDOWN, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

