#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>

#define SPI_CHANNEL 0
#define SPI_BAUD    1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CE */
#define ADC_CHANNEL 0        /* MCP3008 CH0 */
#define ADC_MAX     1023     /* 10-bit ADC */
#define RAINFALL_MAX 10
#define SAMPLE_US   1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI transfer failure.
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer.
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (SGL/DIFF=1, D2 D1 D0 = channel)
     *   Byte 2: 0x00  (clock out remaining bits)
     * Result: bits 9..0 are in ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
}

static int adc_to_intensity(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;
    return (int)(((float)adc_value / (float)ADC_MAX) * (float)RAINFALL_MAX);
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; retrying next cycle\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        int intensity = adc_to_intensity(adc_value);

        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];
        localtime_r(&now, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

        printf("[%s] ADC: %4d  Intensity: %d\n", ts, adc_value, intensity);
        fflush(stdout);

        gpioDelay(SAMPLE_US);
    }

    /* --- Cleanup --- */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();

    printf("\nRain sensor monitoring stopped.\n");
    return EXIT_SUCCESS;
}

