    printf("MCP3008 ADC on SPI0 CE0, PWM on GPIO%d. Press Ctrl+C to exit.\n",
           PWM_PIN);

    while (g_running) {
        int adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; continuing\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (gpioPWM(PWM_PIN, adc_value) != 0) {
            fprintf(stderr, "gpioPWM update failed\n");
        }

        printf("ADC: %4d  PWM: %4d\n", adc_value, adc_value);
        fflush(stdout);

        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    gpioPWM(PWM_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
