/*
 * Raspberry Pi 4 Model B - Honeywell SS49E Hall-Effect Sensor Monitor
 *
 * Hardware:
 *   - Honeywell SS49E linear Hall-effect sensor (analog, ~1.65V at zero gauss)
 *   - ADS1115 16-bit ADC on I2C bus 1, address 0x48, single-ended AIN0
 *   - LED on GPIO17 (with appropriate series resistor)
 *
 * Build: gcc -Wall -o hall_monitor hall_monitor.c -lpigpio -lrt
 * Run:   sudo ./hall_monitor [-t threshold_gauss]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48

#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/*
 * Config word (0x8483):
 *   Bit 15    OS       = 1 (start single conversion)
 *   Bits14:12 MUX      = 100 (AIN0 single-ended)
 *   Bits11:9  PGA      = 001 (4.096V)
 *   Bit 8     MODE     = 1 (single-shot)
 *   Bits7:5   DR       = 100 (128 SPS)
 *   Bit 4     COMP_MODE= 0 (traditional)
 *   Bit 3     COMP_POL = 0 (active low)
 *   Bit 2     COMP_LAT = 0 (non-latching)
 *   Bits1:0   COMP_QUE = 11 (disable comparator)
 */
#define ADS1115_CONFIG_BASE  0x8483

#define LED_GPIO             17
#define SAMPLE_PERIOD_US     100000   /* 100 ms */
#define LED_BLINK_DURATION   1000     /* 1 second */
#define LED_BLINK_HALF_US    50000    /* 50 ms half-period */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_ads1115(void);
static int  read_ads1115(int16_t *raw_out);
static double raw_to_gauss(int16_t raw);
static void led_blink(int duration_ms);
static void cleanup(void);

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ----------------------------- ADS1115 Init ------------------------------ */
static int init_ads1115(void) {
    /*
     * Write the 16-bit config value to the ADS1115 config register.
     * pigpio's i2cWriteWordData sends the 16-bit value as two bytes
     * (big-endian on the wire), so the ADS1115 sees 0x83 0x48.
     */
    int rc = i2cWriteWordData(g_i2c_handle, ADS1115_REG_CONFIG,
                             ADS1115_CONFIG_BASE);
    if (rc < 0) {
        fprintf(stderr, "Error writing ADS1115 config: %d\n", rc);
        return -1;
    }
    return 0;
}

/* ----------------------------- Read ADS1115 ------------------------------ */
static int read_ads1115(int16_t *raw_out) {
    /*
     * Trigger a single conversion by writing OS=1 to the config register.
     * i2cWriteWordData writes the 16-bit value; we set OS=1 by OR'ing
     * the base config with 0x8000 (bit 15).
     */
    uint16_t config = ADS1115_CONFIG_BASE | 0x8000;
    int rc = i2cWriteWordData(g_i2c_handle, ADS1115_REG_CONFIG, config);
    if (rc < 0) {
        fprintf(stderr, "Error triggering ADS1115 conversion: %d\n", rc);
        return -1;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    /* Read the conversion result (2 bytes, big-endian) */
    int16_t raw;
    rc = i2cReadWordData(g_i2c_handle, ADS1115_REG_CONV);
    if (rc < 0) {
        fprintf(stderr, "Error reading ADS1115 conversion: %d\n", rc);
        return -1;
    }

    /* pigpio returns the word as (high_byte << 8) | low_byte */
    raw = (int16_t)rc;
    *raw_out = raw;
    return 0;
}

/* ----------------------------- Conversion -------------------------------- */
static double raw_to_gauss(int16_t raw) {
    /*
     * ADS1115 PGA = 4.096V, 16-bit signed.
     * SS49E ~1.65V at zero gauss -> 1.0 mV/Gauss = 0.001 V/Gauss.
     * 4.096V / 1.0 mV = 4096 counts/Gauss.
     */
    return (double)raw / 4096.0;
}

/* ----------------------------- LED Blink --------------------------------- */
static void led_blink(int duration_ms) {
    int half_period_us = LED_BLINK_HALF_US;
    int cycles = (duration_ms * 1000) / (2 * half_period_us);

    for (int i = 0; i < cycles && g_running; i++) {
        gpioWrite(LED_GPIO, 1);
        gpioDelay(half_period_us);
        gpioWrite(LED_GPIO, 0);
        gpioDelay(half_period_us);
    }
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(int argc, char *argv[]) {
    double threshold = 100.0;  /* Gauss */

    /* Parse command-line threshold */
    if (argc > 1) {
        threshold = atof(argv[1]);
        if (threshold <= 0.0) {
            fprintf(stderr, "Invalid threshold '%s'. Using default 100.0 Gauss.\n",
                    argv[1]);
            threshold = 100.0;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (init_ads1115() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Hall-effect sensor monitoring started. Threshold: %.2f Gauss\n",
           threshold);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t raw;
        if (read_ads1115(&raw) < 0) {
            fprintf(stderr, "ADC read failure; retrying next cycle.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double gauss = raw_to_gauss(raw);
        printf("Magnetic field: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            printf("Threshold exceeded! Blinking LED for 1 second.\n");
            led_blink(LED_BLINK_DURATION);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

