#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define RELAY_GPIO     17
#define MOISTURE_THRESHOLD_LOW  30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER    "localhost"
#define MQTT_PORT      1883
#define MQTT_CLIENT_ID "soil_monitor"
#define MQTT_TOPIC     "soil_moisture"
#define MQTT_CMD_TOPIC "pump_control"
#define SAMPLE_INTERVAL_S 60
#define ADC_MAX        1023
#define ADC_MIN        0
#define ADC_CHANNEL    0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static struct mosquitto *mosq = NULL;
static int pump_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel %d", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed on channel %d", channel);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int control_pump(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write relay GPIO %d", RELAY_GPIO);
        return -1;
    }
    pump_state = state;
    syslog(LOG_INFO, "Pump %s", state ? "activated" : "deactivated");
    return 0;
}

static void mqtt_connect_callback(struct mosquitto *m, void *ud, int rc) {
    (void)m; (void)ud;
    if (rc == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_BROKER, MQTT_PORT);
        int sub_rc = mosquitto_subscribe(m, NULL, MQTT_CMD_TOPIC, 0);
        if (sub_rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to %s: %s", MQTT_CMD_TOPIC, mosquitto_strerror(sub_rc));
        }
    } else {
        syslog(LOG_ERR, "MQTT connect error: %s", mosquitto_strerror(rc));
    }
}

static void mqtt_disconnect_callback(struct mosquitto *m, void *ud, int rc) {
    (void)m; (void)ud;
    syslog(LOG_INFO, "MQTT disconnected (rc=%d)", rc);
}

static void mqtt_message_callback(struct mosquitto *m, void *ud, const struct mosquitto_message *msg) {
    (void)m; (void)ud;
    if (!msg || !msg->payload || msg->payloadlen <= 0) return;
    char buf[32];
    int len = msg->payloadlen < (int)sizeof(buf) - 1 ? msg->payloadlen : (int)sizeof(buf) - 1;
    memcpy(buf, msg->payload, len);
    buf[len] = '\0';
    syslog(LOG_INFO, "Received command: %s", buf);
    if (strcmp(buf, "pump_on") == 0) {
        control_pump(1);
    } else if (strcmp(buf, "pump_off") == 0) {
        control_pump(0);
    }
}

static void cleanup(void) {
    if (pump_state) control_pump(0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting soil moisture monitor");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay GPIO %d as output", RELAY_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed on channel %d", SPI_CHANNEL);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT initialisation failed");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            syslog(LOG_ERR, "Sensor read failed; skipping cycle");
        } else if (adc < ADC_MIN || adc > ADC_MAX) {
            syslog(LOG_ERR, "ADC value %d out of range; sensor absent or wiring fault", adc);
        } else {
            int moisture = (int)(((float)adc / (float)ADC_MAX) * 100.0f);
            syslog(LOG_INFO, "Moisture: %d%% (ADC: %d)", moisture, adc);

            if (moisture < MOISTURE_THRESHOLD_LOW && !pump_state) {
                control_pump(1);
            } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state) {
                control_pump(0);
            }

            char payload[64];
            snprintf(payload, sizeof(payload), "{\"moisture\": %d, \"pump\": %s}", moisture, pump_state ? "ON" : "OFF");
            rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, (int)strlen(payload), payload, 0, false);
            if (rc != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

