#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

#define RELAY_GPIO 17
#define PROXIMITY_THRESHOLD 20
#define POLL_INTERVAL_MS 100
#define DEBOUNCE_DELAY_S 1

#define ADC_CHANNEL 0

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get relay GPIO line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "door_sensor", 0) < 0) {
        perror("Failed to request relay GPIO as output");
        gpiod_chip_close(chip);
        chip = NULL;
        relay_line = NULL;
        return -1;
    }

    return 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int is_proximity_detected(int adc_value) {
    return (adc_value > 0 && adc_value < PROXIMITY_THRESHOLD);
}

static int control_relay(int state) {
    if (gpiod_line_set_value(relay_line, state) < 0) {
        perror("Failed to set relay GPIO value");
        return -1;
    }
    return 0;
}

static void log_event(const char *event) {
    if (!log_file) return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        return;
    }

    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    log_file = fopen("door_events.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    if (init_spi() < 0) {
        cleanup();
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    printf("Door sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying...\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (is_proximity_detected(adc_value)) {
            printf("Proximity detected! ADC: %d\n", adc_value);
            log_event("Proximity detected");

            if (control_relay(1) < 0) {
                fprintf(stderr, "Error activating relay.\n");
            } else {
                printf("Relay activated.\n");
            }

            sleep(DEBOUNCE_DELAY_S);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

