    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    log_file = fopen("door_events.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    if (init_spi() < 0) {
        cleanup();
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    printf("Door sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying...\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (is_proximity_detected(adc_value)) {
            printf("Proximity detected! ADC: %d\n", adc_value);
            log_event("Proximity detected");

            if (control_relay(1) < 0) {
                fprintf(stderr, "Error activating relay.\n");
            } else {
                printf("Relay activated.\n");
            }

            sleep(DEBOUNCE_DELAY_S);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

