            int avg = calculate_average(vals);
            int pos = map_to_valve_position(avg);
            if (set_valve_position(pos) != 0) {
                fprintf(stderr, "Valve set error\n");
            }
            if (log_data(vals, avg, pos) != 0) {
                fprintf(stderr, "Log write error\n");
            }
        }
        sleep(SAMPLE_INTERVAL);
    }
    gpioPWM(VALVE_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

