#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_DEVICE "/dev/spidev0.0"
#define CONFIG_FILE "theremin_config.txt"

#define MIN_FREQUENCY 220
#define MAX_FREQUENCY 880
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TIMEOUT_US 30000
#define PWM_PERIOD_NS 10000000
#define PWM_DUTY_MAX 1000000000

volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trig_line = NULL;
static struct gpiod_line *echo_line = NULL;
static struct gpiod_line *pwm_line = NULL;
static int spi_fd = -1;
static float distance = 0.0;
static float frequency = 440.0;
static float volume = 0.5;
static float last_valid_distance = 0.0;
static float last_valid_frequency = 440.0;
static float last_valid_volume = 0.5;
static int spi_initialized = 0;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return -1;
    }
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    pwm_line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!trig_line || !echo_line || !pwm_line) {
        perror("gpiod_chip_get_line");
        return -1;
    }
    if (gpiod_line_request_output(trig_line, "theremin", 0) < 0 ||
        gpiod_line_request_input(echo_line, "theremin") < 0 ||
        gpiod_line_request_output(pwm_line, "theremin", 0) < 0) {
        perror("gpiod_line_request");
        return -1;
    }
    return 0;
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI");
        return -1;
    }
    int mode = SPI_MODE_0;
    int bits = 8;
    int speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    spi_initialized = 1;
    return 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

float read_distance() {
    struct timespec start, end;
    long long elapsed_us;
    int timeout = 0;
    if (gpiod_line_set_value(trig_line, 0) < 0) return -1.0;
    usleep(2);
    if (gpiod_line_set_value(trig_line, 1) < 0) return -1.0;
    usleep(10);
    if (gpiod_line_set_value(trig_line, 0) < 0) return -1.0;
    while (gpiod_line_get_value(echo_line) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) return -1.0;
        if (++timeout > 100) return -1.0;
    }
    timeout = 0;
    while (gpiod_line_get_value(echo_line) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) return -1.0;
        if (++timeout > 100) return -1.0;
    }
    elapsed_us = (end.tv_sec - start.tv_sec) * 1000000LL + (end.tv_nsec - start.tv_nsec) / 1000LL;
    if (elapsed_us < 0 || elapsed_us > TIMEOUT_US) return -1.0;
    return (float)elapsed_us / 58.0;
}

float map_distance_to_frequency(float d) {
    if (d < MIN_DISTANCE) d = MIN_DISTANCE;
    if (d > MAX_DISTANCE) d = MAX_DISTANCE;
    return MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (1.0 - (d - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE));
}

float map_distance_to_volume(float d) {
    if (d < MIN_DISTANCE) d = MIN_DISTANCE;
    if (d > MAX_DISTANCE) d = MAX_DISTANCE;
    return 1.0 - (d - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
}

int set_pwm_frequency(float freq) {
    if (freq < 0) freq = 0;
    if (freq > 1000000) freq = 1000000;
    int div = 1000000000 / (int)freq;
    char buf[32];
    int len = snprintf(buf, sizeof(buf), "0 %d 0\n", div);
    if (write(spi_fd, buf, len) != len) {
        perror("PWM write");
        return -1;
