#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008 ADC Channels
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// PWM Range
#define PWM_RANGE 255

// Speed Constants
#define MIN_SPEED 50
#define MAX_SPEED 255
#define ACCELERATION_TIME 2.0 // seconds
#define DECCELERATION_TIME 2.0
#define PAUSE_TIME 5.0

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int read_potentiometer(int channel);
float calculate_speed_factor(int pot_value);
void set_motor_speed(int enable_pin, int direction_pin, int speed);
void stop_motor(int enable_pin);
void cleanup();
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup Function
void cleanup() {
    stop_motor(MOTOR1_ENABLE);
    stop_motor(MOTOR2_ENABLE);
    gpioTerminate();
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
}

// Function to read potentiometer value from MCP3008
int read_potentiometer(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 SPI command: Start bit (1), Single-ended mode (1), Channel select (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode + channel
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to calculate speed factor based on potentiometer value
float calculate_speed_factor(int pot_value) {
    if (pot_value < 0 || pot_value > 1023) {
        fprintf(stderr, "Error: Potentiometer value out of range: %d\n", pot_value);
        return 0.0;
    }

    // Logarithmic mapping: 0-1023 maps to 0.1-1.0
    float speed_factor = 0.1 + (pow((float)pot_value / 1023.0, 2.0) * 0.9);
    return speed_factor;
}

// Function to set motor speed and direction
void set_motor_speed(int enable_pin, int direction_pin, int speed) {
    if (speed < 0 || speed > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid speed value: %d\n", speed);
        return;
    }

    gpioWrite(direction_pin, speed > 0 ? 1 : 0); // Forward if speed > 0, reverse otherwise
    gpioPWM(enable_pin, speed);
}

// Function to stop motor
void stop_motor(int enable_pin) {
    gpioPWM(enable_pin, 0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(MOTOR1_ENABLE, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_ENABLE, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read potentiometer values
        int pot1_value = read_potentiometer(POT1_CHANNEL);
        int pot2_value = read_potentiometer(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer values\n");
            break;
        }

        // Calculate speed factors
