#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define NOISE_THRESHOLD 10.0
#define DEBOUNCE_MS 10
#define CALIBRATION_SECONDS 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Calibrating ambient noise for %d seconds...\n", CALIBRATION_SECONDS);
    long long sum = 0;
    int samples = 0;
    for (int i = 0; i < CALIBRATION_SECONDS * 100 && running; i++) {
        int val = read_mcp3008(ADC_CHANNEL);
        if (val >= 0) {
            sum += val;
            samples++;
        }
        gpioDelay(10000);
    }
    if (!running) {
        goto cleanup;
    }
    if (samples == 0) {
        fprintf(stderr, "No valid samples during calibration\n");
        goto cleanup;
    }
    double ambient = (double)sum / samples;
    printf("Ambient noise level: %.2f\n", ambient);

    uint32_t last_trigger = 0;
    while (running) {
        int val = read_mcp3008(ADC_CHANNEL);
        if (val < 0) {
            gpioDelay(100000);
            continue;
        }

        double level = (double)val;
        double diff = level - ambient;
        double threshold = ambient * NOISE_THRESHOLD / 100.0;

        if (diff > threshold) {
            uint32_t now = gpioTick();
            if (now - last_trigger > DEBOUNCE_MS * 1000) {
                gpioWrite(LED_PIN, 1);
                gpioDelay(100000);
                gpioWrite(LED_PIN, 0);
                last_trigger = now;
            }
        }

        gpioDelay(10000);
    }

cleanup:
    gpioWrite(LED_PIN, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return 0;
}

