#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8
#define SAMPLE_PERIOD_NS 1000000  /* 1 ms -> 1000 Hz */
#define LOG_FILE        "audio_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(int *fd_out)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

static int gpio_init(struct gpiod_chip **chip_out, struct gpiod_line **line_out)
{
    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open(%s): %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", CS_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "admp401-spi", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    *chip_out = chip;
    *line_out = line;
    return 0;
}

static int read_mcp3008(int spi_fd, struct gpiod_line *cs_line, uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    /* MCP3008 single-ended: start bit=1, config=(0x08|ch)<<4, dummy=0x00 */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    /* Manually control CS via libgpiod: drive low before transfer, high after */
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "gpiod_line_set_value(0): %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "gpiod_line_set_value(1): %s\n", strerror(errno));
        return -1;
    }

    /* MCP3008 returns 10-bit result: rx[1] low 2 bits + rx[2] 8 bits */
    *out = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int log_sample(FILE *fp, long long timestamp_ns, uint16_t adc_value)
{
    if (fprintf(fp, "%lld|%u\n", timestamp_ns, adc_value) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) == EOF) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    struct gpiod_chip *gpio_chip = NULL;
    struct gpiod_line *cs_line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        goto cleanup;
    }

    /* Initialize SPI */
    if (spi_init(&spi_fd) < 0) {
        goto cleanup;
    }

    /* Initialize GPIO for manual CS control */
    if (gpio_init(&gpio_chip, &cs_line) < 0) {
        goto cleanup;
    }

    /* Open log file */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Sampling ADMP401 via MCP3008 (CH0) at 1 kHz. Press Ctrl+C to stop.\n");

    struct timespec next_deadline;
    clock_gettime(CLOCK_MONOTONIC, &next_deadline);

    while (g_running) {
        uint16_t adc_value = 0;
        if (read_mcp3008(spi_fd, cs_line, 0, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
        } else {
            long long timestamp_ns = (long long)next_deadline.tv_sec * 1000000000LL +
                                    next_deadline.tv_nsec;
            if (log_sample(log_fp, timestamp_ns, adc_value) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        }

        /* Advance deadline by sample period */
        next_deadline.tv_nsec += SAMPLE_PERIOD_NS;
        if (next_deadline.tv_nsec >= 1000000000L) {
            next_deadline.tv_sec += 1;
            next_deadline.tv_nsec -= 1000000000L;
        }

        /* Sleep until next deadline (interruptible by signals) */
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long long sleep_ns = (long long)(next_deadline.tv_sec - now.tv_sec) * 1000000000LL +
                             (long long)(next_deadline.tv_nsec - now.tv_nsec);
        if (sleep_ns > 0) {
            struct timespec sleep_ts;
            sleep_ts.tv_sec = sleep_ns / 1000000000LL;
            sleep_ts.tv_nsec = sleep_ns % 1000000000LL;
            nanosleep(&sleep_ts, NULL);
        }
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp) {
        fclose(log_fp);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

