#define ADXL335_SENSITIVITY 0.3 // V/g
#define ADXL335_BIAS 1.5        // V

// MCP3008 ADC Parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000       // 1 MHz
#define MCP3008_CS 8            // GPIO8 (CE0)
#define MCP3008_CHANNELS 8
#define VREF 3.3

// Kalman Filter Parameters
#define Q 0.001
#define R 0.1

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Kalman Filter State Struct
typedef struct {
    float x;
    float P;
} kalman_state_t;

// Function prototypes
int read_mcp3008(int channel);
float read_adxl335_axis(int channel);
void kalman_filter(float measurement, kalman_state_t *state, float *output);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel >= MCP3008_CHANNELS) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: Start bit (0x01)
    // Byte 1: SGL/DIFF=1, D2 D1 D0 = channel, padded to MSB
    // Byte 2: Don't care (0x00)
    char tx_buffer[3] = {0x01, (0x08 | channel) << 4, 0x00};
    char rx_buffer[3] = {0};

    // Assert CS (active low)
    gpioWrite(MCP3008_CS, 0);

    int spi_result = spiXfer(SPI_CHANNEL, tx_buffer, rx_buffer, 3);

    // De-assert CS
    gpioWrite(MCP3008_CS, 1);

    if (spi_result != 3) {
        fprintf(stderr, "Error: SPI transfer failed for channel %d\n", channel);
        return -1;
    }

    // Extract 10-bit ADC value from response
    // rx_buffer[1] contains the two most significant bits in its lower 2 bits
    // rx_buffer[2] contains the eight least significant bits
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | (rx_buffer[2] & 0xFF);

    return adc_value;
}

// Function to read acceleration from ADXL335 analog output
float read_adxl335_axis(int channel) {
    int adc_value = read_mcp3008(channel);
    if (adc_value < 0) {
        return -1.0; // Indicate error
    }

    // Convert ADC value to voltage
    float voltage = (float)adc_value * VREF / 1023.0;

    // Convert voltage to acceleration (g)
    float acceleration = (voltage - ADXL335_BIAS) / ADXL335_SENSITIVITY;

    return acceleration;
}

// Function to implement the Kalman filter
void kalman_filter(float measurement, kalman_state_t *state, float *output) {
    // Prediction step
    state->x = state->x + state->P * Q;
    state->P = state->P + Q;

    // Update step
    float K = state->P / (state->P + R);
    state->x = state->x + K * (measurement - state->x);
    state->P = (1.0 - K) * state->P;

    *output = state->x;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output and initialize to high (inactive)
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1);

    // Open SPI channel (mode 0, 8 bits per word)
    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize Kalman filter states
    kalman_state_t x_state = {0.0, 1.0};
    kalman_state_t y_state = {0.0, 1.0};
    kalman_state_t z_state = {0.0, 1.0};

    // Set up signal handling for Ctrl+C and termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read acceleration values from ADXL335
        float x_acceleration = read_adxl335_axis(0);
        float y_acceleration = read_adxl335_axis(1);
        float z_acceleration = read_adxl335_axis(2);

        // Check for sensor-absent or bus error
        if (x_acceleration < 0 || y_acceleration < 0 || z_acceleration < 0) {
            fprintf(stderr, "Error: Sensor read failed, skipping iteration\n");
            time_sleep(0.1);
            continue;
        }

        // Apply Kalman filter to smooth the data
        float filtered_x, filtered_y, filtered_z;
        kalman_filter(x_acceleration, &x_state, &filtered_x);
        kalman_filter(y_acceleration, &y_state, &filtered_y);
        kalman_filter(z_acceleration, &z_state, &filtered_z);

        // Print the filtered acceleration values
        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", filtered_x, filtered_y, filtered_z);

        // Delay for 100ms (10 Hz update rate)
        time_sleep(0.1);
    }

    // Close SPI channel and terminate pigpio library
    spiClose(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

