#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

#define VCC 3.3f
#define V_QUIESCENT 1.65f
#define SENSITIVITY 0.025f
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 100
#define MIN_FIELD_MT  -100.0f
#define MAX_FIELD_MT  100.0f

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static float calculate_magnetic_field(int digital_value) {
    float voltage = (float)digital_value * (VCC / 2.0f);
    return (voltage - V_QUIESCENT) / SENSITIVITY;
}

static int log_data(float s1, float s2, float s3) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "%.2f,%.2f,%.2f\n", s1, s2, s3);
    if (ferror(fp)) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fflush(fp);
    fclose(fp);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    line3 = gpiod_chip_get_line(chip, SENSOR3_PIN);
    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "hall_sensor1") < 0 ||
        gpiod_line_request_input(line2, "hall_sensor2") < 0 ||
        gpiod_line_request_input(line3, "hall_sensor3") < 0) {
        fprintf(stderr, "Failed to request GPIO lines as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Starting magnetic field logging. Press Ctrl+C to stop.\n");

    while (program_running) {
        int v1 = gpiod_line_get_value(line1);
        int v2 = gpiod_line_get_value(line2);
        int v3 = gpiod_line_get_value(line3);

        if (v1 < 0 || v2 < 0 || v3 < 0) {
            fprintf(stderr, "Error reading GPIO values: %s\n", strerror(errno));
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        float s1 = calculate_magnetic_field(v1);
        float s2 = calculate_magnetic_field(v2);
        float s3 = calculate_magnetic_field(v3);

        if (s1 < MIN_FIELD_MT || s1 > MAX_FIELD_MT ||
            s2 < MIN_FIELD_MT || s2 > MAX_FIELD_MT ||
            s3 < MIN_FIELD_MT || s3 > MAX_FIELD_MT) {
            fprintf(stderr, "Warning: Magnetic field out of range (s1=%.2f, s2=%.2f, s3=%.2f) mT\n", s1, s2, s3);
        }

        if (log_data(s1, s2, s3) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

