#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18
#define CHIP_NAME "gpiochip0"
#define CONSUMER "sound_alarm"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the sound sensor line */
    sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SOUND_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    /* Get the alarm LED line */
    led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALARM_LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request sound sensor line as input */
    if (gpiod_line_request_input(sound_line, CONSUMER) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", SOUND_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request alarm LED line as output, initial value LOW */
    if (gpiod_line_request_output(led_line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", ALARM_LED_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Sound alarm system started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_level = gpiod_line_get_value(sound_line);
        if (sound_level < 0) {
            fprintf(stderr, "Error reading sound sensor: %s\n", strerror(errno));
            break;
        }

        printf("Sound level: %d\n", sound_level);

        if (sound_level == 0) {
            /* Sound detected: blink LED for 1 second */
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Error setting LED HIGH: %s\n", strerror(errno));
                break;
            }
            sleep(1);
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Error setting LED LOW: %s\n", strerror(errno));
                break;
            }
        }

        usleep(100000); /* 100 ms delay */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure LED is off before releasing */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sound_line) {
        gpiod_line_release(sound_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Clean shutdown complete.\n");
    }
    return ret;
}

