#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP       "/dev/gpiochip0"
#define GPIO_LINE       17
#define LOG_FILE        "/var/log/vibration_shutdown.log"
#define CONSUMER        "vibration-monitor"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    if (fprintf(fp, "%s\n", message) < 0) {
        perror("fprintf log file");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose log file");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct timespec ts;
    char timestamp[32];
    char log_message[256];
    int ret = EXIT_FAILURE;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal SIGINT");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal SIGTERM");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(line, CONSUMER) < 0) {
        perror("gpiod_line_request_falling_edge_events");
        goto cleanup;
    }

    printf("Monitoring SW-420 vibration sensor on GPIO%d (falling edge = vibration)\n", GPIO_LINE);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        ts.tv_sec = 1;
        ts.tv_nsec = 0;

        int rv = gpiod_line_event_wait(line, &ts);
        if (rv < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_wait");
            goto cleanup;
        }
        if (rv == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("gpiod_line_event_read");
            goto cleanup;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            goto cleanup;
        }
        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

        snprintf(log_message, sizeof(log_message),
                 "%s: Vibration detected on GPIO%d (falling edge)", timestamp, GPIO_LINE);

        if (log_event(log_message) < 0) {
            fprintf(stderr, "Failed to log event.\n");
        }
        printf("%s\n", log_message);

        if (system("sudo shutdown -h now") == -1) {
            perror("system shutdown");
        }
        ret = EXIT_SUCCESS;
        break;
    }

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

