    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    if (fprintf(log_file, "%s,%.2f\n", ts, altitude) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int read_sensor(int handle, double *altitude) {
    uint8_t buf[6];
    if (i2cReadI2CBlockData(handle, BMP280_REG_PRESS_MSB, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6-byte pressure+temp block\n");
        return -1;
    }
    int32_t adc_P = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
    int32_t adc_T = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | (buf[5] >> 4);
    int32_t T = compensate_temperature(adc_T);
    uint32_t P = compensate_pressure(adc_P);
    *altitude = calculate_altitude(P);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (addr 0x%02X): %d\n", BMP280_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIP_ID);
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: chip ID mismatch (got 0x%02X, expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: failed to write ctrl_meas\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write config\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("BMP280 initialised at 0x%02X. Logging to %s every 5 s. Ctrl+C to stop.\n", BMP280_I2C_ADDR, LOG_FILE);

    while (running) {
        double altitude;
        if (read_sensor(i2c_handle, &altitude) == 0) {
            if (log_data(altitude) != 0) {
                fprintf(stderr, "Warning: logging failed, continuing\n");
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

