#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL 5.0
#define VREF 3.3
#define LM35_MV_PER_C 10.0

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_celsius(int adc_value) {
    return (float)adc_value * VREF / 1024.0 * 100.0;
}

static void log_to_console(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
}

static void log_to_file(float *buffer, int size) {
    FILE *fp = fopen("temp_log.dat", "wb+");
    if (!fp) {
        fprintf(stderr, "Error opening temp_log.dat for writing\n");
        return;
    }
    size_t written = fwrite(buffer, sizeof(float), (size_t)size, fp);
    if (written != (size_t)size) {
        fprintf(stderr, "Error writing to temp_log.dat (wrote %zu of %d)\n", written, size);
    }
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature;
    float buffer[BUFFER_SIZE];
    int buffer_index = 0;

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
        } else {
            temperature = adc_to_celsius(adc_value);
            log_to_console(temperature);
            buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        }
        time_sleep(SAMPLE_INTERVAL);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return 0;
}

