#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define I2C_BUS 1
#define I2C_ADDR 0x62
#define MCP4725_CMD_WRITE 0x40
#define MCP4725_CMD_POWER_DOWN 0x02
#define MIN_TEMP 0.0
#define MAX_TEMP 50.0
#define MIN_DAC 0.0
#define MAX_DAC 3.3
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 500000

static int spi_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float convert_to_celsius(int adc_value) {
    return (adc_value * 3.3 / 1024.0 - 0.5) * 100.0;
}

static int set_dac_voltage(float voltage) {
    if (voltage < 0.0 || voltage > 3.3) return -1;
    int dac_value = (int)(voltage * 4095.0 / 3.3);
    unsigned char buf[2] = {MCP4725_CMD_WRITE, (unsigned char)(dac_value >> 4)};
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) return -1;
    buf[0] = MCP4725_CMD_POWER_DOWN;
    buf[1] = (unsigned char)((dac_value & 0x0F) << 4);
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) return -1;
    return 0;
}

static void log_data(int adc_value, float temperature, float voltage) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s, ADC: %d, Temp: %.2f C, DAC: %.2f V\n", timestamp, adc_value, temperature, voltage);
    fflush(log_file);
    printf("%s, ADC: %d, Temp: %.2f C, DAC: %.2f V\n", timestamp, adc_value, temperature, voltage);
}

static void cleanup(void) {
    if (spi_handle >= 0) spiClose(spi_handle);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        float temperature = convert_to_celsius(adc_value);
        float voltage = MIN_DAC + (temperature - MIN_TEMP) * (MAX_DAC - MIN_DAC) / (MAX_TEMP - MIN_TEMP);
        if (set_dac_voltage(voltage) != 0) {
            fprintf(stderr, "DAC write error\n");
        }
        log_data(adc_value, temperature, voltage);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

