#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define NUM_SENSORS 3
#define SLEEP_INTERVAL 60
#define LOG_FILE "soil_data.txt"

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value %d\n", adc_value);
        return -1.0f;
    }
    return (1.0f - (float)adc_value / 1023.0f) * 100.0f;
}

static void log_data(float m1, float m2, float m3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, m1, m2, m3);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");
    while (!terminate) {
        int adc0 = read_mcp3008(0);
        int adc1 = read_mcp3008(1);
        int adc2 = read_mcp3008(2);
        float m1 = calculate_moisture(adc0);
        float m2 = calculate_moisture(adc1);
        float m3 = calculate_moisture(adc2);
        if (m1 >= 0.0f && m2 >= 0.0f && m3 >= 0.0f) {
            log_data(m1, m2, m3);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping log entry\n");
        }
        gpioDelay(SLEEP_INTERVAL * 1000000);
    }
    cleanup();
    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

