#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

/* BCM GPIO pins for Songle SRD-05VDC-SL relays */
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

#define NUM_RELAYS 4
static const int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

/* Global handles for cleanup in signal handler */
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS];
static int lines_requested = 0;

/* ------------------------------------------------------------------ */
/* Release all GPIO lines and chip                                     */
/* ------------------------------------------------------------------ */
static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);   /* deactivate relay */
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Signal handler — deactivate relays and release resources            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(EXIT_SUCCESS);
}

/* ------------------------------------------------------------------ */
/* Activate a relay (set HIGH) and wait, then deactivate (LOW)        */
/* ------------------------------------------------------------------ */
static void run_relay(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to activate relay on line %d: %s\n",
                (int)gpiod_line_offset(line), strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }
    sleep(1);
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to deactivate relay on line %d: %s\n",
                (int)gpiod_line_offset(line), strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }
    sleep(1);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void) {
    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire and request each relay line as output, initially LOW */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d: %s\n",
                    relay_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], "relay-seq", 0) < 0) {
            fprintf(stderr, "Failed to request line %d as output: %s\n",
                    relay_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        lines_requested++;
    }

    /* Install signal handlers for graceful shutdown */
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    /* Main sequencing loop — run each relay once, then repeat */
    while (1) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            run_relay(lines[i]);
        }
    }

    /* Unreachable in normal operation, but keep for completeness */
    cleanup();
    return EXIT_SUCCESS;
}

