#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Motor control pins (L298N) */
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */

/* Rain sensor channel on MCP3008 */
#define RAIN_CHANNEL 0

/* Rain threshold (0-10) */
#define RAIN_THRESHOLD 5

/* Motor speed (0-255) */
#define MOTOR_SPEED 150

/* Motor run duration (seconds) */
#define MOTOR_RUN_DURATION 3

/* Polling interval (seconds) */
#define POLL_INTERVAL 1

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; cleanup happens in main()           */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit value from MCP3008 single-ended channel                */
/* Returns 0-1023 on success, -1 on error                             */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0, then
       0x00 padding.  Response: rx[0]=don't care, rx[1]=2 bits + 8 bits,
       rx[2]=8 bits. */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC (0-1023) to rain level (0-10)                           */
/* Higher ADC value = higher voltage = wetter / higher rain           */
/* ------------------------------------------------------------------ */
static int adc_to_rain_level(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return 10 - (adc_value * 10) / 1023;
}

/* ------------------------------------------------------------------ */
/* Drive motor: forward = 1, reverse = 0                              */
/* ------------------------------------------------------------------ */
static void motor_drive(int forward)
{
    if (forward) {
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
    } else {
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
    }
    gpioPWM(MOTOR_ENA, MOTOR_SPEED);
}

/* ------------------------------------------------------------------ */
/* Stop motor                                                          */
/* ------------------------------------------------------------------ */
static void motor_stop(void)
{
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);
}

/* ------------------------------------------------------------------ */
/* Log rain reading with timestamp                                     */
/* ------------------------------------------------------------------ */
static void log_rain_reading(int rain_level)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup — called on every exit path                                 */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motor_stop();

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins */
    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_ENA, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("rain_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    int window_closed = 0;  /* 0 = open, 1 = closed */

    while (g_running) {
        int adc_value = read_mcp3008(RAIN_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading rain sensor\n");
            sleep(POLL_INTERVAL);
            continue;
        }

        int rain_level = adc_to_rain_level(adc_value);
        log_rain_reading(rain_level);

        printf("Rain Level: %d\n", rain_level);

        if (rain_level >= RAIN_THRESHOLD && !window_closed) {
            printf("Rain detected! Closing window...\n");
            motor_drive(1);
            sleep(MOTOR_RUN_DURATION);
            motor_stop();
            window_closed = 1;
        } else if (rain_level < RAIN_THRESHOLD && window_closed) {
            printf("Rain stopped. Opening window...\n");
            motor_drive(0);
            sleep(MOTOR_RUN_DURATION);
            motor_stop();
            window_closed = 0;
        }

        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

