#include <errno.h>

#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define PROXIMITY_THRESHOLD 200.0f
#define A 26.0f
#define B -6.0f

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int gpio_export(int pin) {
    char buf[16];
    int fd;
    snprintf(buf, sizeof(buf), "/sys/class/gpio/export");
    fd = open(buf, O_WRONLY);
    if (fd < 0) {
        perror("open export");
        return -1;
    }
    if (dprintf(fd, "%d", pin) < 0) {
        perror("dprintf export");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int pin) {
    char buf[16];
    int fd;
    snprintf(buf, sizeof(buf), "/sys/class/gpio/unexport");
    fd = open(buf, O_WRONLY);
    if (fd < 0) {
        perror("open unexport");
        return -1;
    }
    if (dprintf(fd, "%d", pin) < 0) {
        perror("dprintf unexport");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    int fd;
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("open direction");
        return -1;
    }
    if (dprintf(fd, "%s", dir) < 0) {
        perror("dprintf direction");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_read_value(int pin) {
    char path[64];
    int fd;
    char val[4];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("open value");
        return -1;
    }
    if (read(fd, val, sizeof(val) - 1) < 0) {
        perror("read value");
        close(fd);
        return -1;
    }
    close(fd);
    val[strcspn(val, "\n")] = '\0';
    return (val[0] == '1') ? 1 : 0;
}

static float voltage_to_distance(float voltage) {
    return A / voltage + B;
}

static void log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Distance: %.2f mm\n", ts, distance);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpio_export(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        return 1;
    }
    if (gpio_set_direction(GPIO_PIN, "in") < 0) {
        fprintf(stderr, "Failed to set direction for GPIO %d\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("Pet feeder started. Press Ctrl+C to exit.\n");

    while (running) {
        int val = gpio_read_value(GPIO_PIN);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO %d, retrying in 1s...\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        float voltage = (float)val * 3.3f;
        float distance = voltage_to_distance(voltage);

        log_distance(distance);

        if (distance < PROXIMITY_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    gpio_unexport(GPIO_PIN);
    printf("Pet feeder stopped.\n");
    return 0;
}

