#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define DRY_ADC_VALUE 800
#define WET_ADC_VALUE 300
#define MOISTURE_THRESHOLD 30
#define PUMP_GPIO_LINE 17
#define LOG_FILE "soil_moisture.log"
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pump_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned char mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    pump_line = gpiod_chip_get_line(chip, PUMP_GPIO_LINE);
    if (!pump_line) {
        perror("Failed to get GPIO line 17");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(pump_line, "soil_moisture", 0) < 0) {
        perror("Failed to request GPIO line 17 as output");
        gpiod_chip_close(chip);
        chip = NULL;
        pump_line = NULL;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0) return -1.0f;
    if (DRY_ADC_VALUE == WET_ADC_VALUE) return 0.0f;
    float pct = 100.0f - ((float)(adc_value - WET_ADC_VALUE) / (float)(DRY_ADC_VALUE - WET_ADC_VALUE) * 100.0f);
    if (pct < 0.0f) pct = 0.0f;
    if (pct > 100.0f) pct = 100.0f;
    return pct;
}

static void control_pump(int on) {
    if (pump_line) {
        gpiod_line_set_value(pump_line, on ? 1 : 0);
    }
}

static void log_data(float moisture, int pump_status) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, Moisture: %.2f%%, Pump: %s\n",
            timestamp, moisture, pump_status ? "ON" : "OFF");
    fflush(log_file);
}

static void cleanup(void) {
    if (pump_line) {
        gpiod_line_set_value(pump_line, 0);
        gpiod_line_release(pump_line);
        pump_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float moisture = calculate_moisture_percentage(adc_value);
        if (moisture < 0.0f) {
            fprintf(stderr, "Error calculating moisture percentage. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        int pump_status = (moisture < MOISTURE_THRESHOLD) ? 1 : 0;
        control_pump(pump_status);
        log_data(moisture, pump_status);

        printf("Moisture: %.2f%%, Pump: %s\n", moisture, pump_status ? "ON" : "OFF");

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

