}

static void cleanup(void) {
    if (pump_line) {
        gpiod_line_set_value(pump_line, 0);
        gpiod_line_release(pump_line);
        pump_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(spi_fd);
