    if (!cs_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* Initialize SPI */
    if (spi_init(&spi_fd) < 0)
        goto cleanup;

    /* Open log file */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    printf("Starting magnetic field logging. Press Ctrl+C to stop.\n");

    while (g_running) {
        int adc_value = 0;

        /* Manually drive CS low to start a SPI transaction */
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            perror("gpiod_line_set_value(0)");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        if (mcp3008_read(spi_fd, 0, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed; skipping sample.\n");
            /* Ensure CS is high on error for proper protocol */
            gpiod_line_set_value(cs_line, 1);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        /* Manually drive CS high to end the transaction */
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("gpiod_line_set_value(1)");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        double magnetic_field = calculate_magnetic_field(adc_value);
        time_t now = time(NULL);

        if (log_data(log_fp, now, magnetic_field) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

