#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* Configuration */
#define SPI_CHANNEL 0          /* SPI0 CE0 (GPIO 8) */
#define SPI_SPEED 1000000      /* 1 MHz */
#define ADC_CHANNEL 0          /* MCP3008 single-ended channel 0 */
#define LED_GPIO 21            /* GPIO21 */
#define VCC 3.3                /* ADC reference voltage */
#define SENSITIVITY 1.65       /* mV/mT for DRV5055VA at 3.3 V */
#define THRESHOLD 10.0         /* mT */
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_DELAY_US 100000 /* 100 ms */

/* Globals for cleanup */
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read MCP3008 single-ended channel (0-7) via SPI.
 * Returns 0-1023 on success, -1 on error. */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI command: start bit, single-ended + channel, then don't-care */
    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* Convert ADC value to voltage */
static float adc_to_voltage(int adc_value) {
    return (float)adc_value * VCC / 1023.0f;
}

/* Convert voltage to magnetic field strength in mT */
static float voltage_to_magnetic_field(float voltage) {
    return (voltage - (VCC / 2.0f)) * 1000.0f / SENSITIVITY;
}

/* Log timestamped field strength to file */
static void log_field_strength(float field_strength) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Field Strength: %.2f mT\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, field_strength);
    } else {
        fprintf(fp, "(time error), Field Strength: %.2f mT\n", field_strength);
    }

    fclose(fp);
}

/* Control LED based on threshold */
static void control_led(float field_strength) {
    gpioWrite(LED_GPIO, (field_strength > THRESHOLD) ? 1 : 0);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output, initially off */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM) failed");
    }

    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float field_strength = voltage_to_magnetic_field(voltage);

        log_field_strength(field_strength);
        control_led(field_strength);

        printf("ADC: %4d  Voltage: %.3f V  Field: %.2f mT  LED: %s\n",
               adc_value, voltage, field_strength,
               (field_strength > THRESHOLD) ? "ON" : "OFF");

        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

