#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

/* Hardware SPI0 wiring on Raspberry Pi Zero W:
 *   MCP3008 VDD  -> Pi 5V  (Pin 2)
 *   MCP3008 VREF -> Pi 5V  (Pin 2)
 *   MCP3008 AGND -> Pi GND (Pin 6)
 *   MCP3008 DGND -> Pi GND (Pin 6)
 *   MCP3008 CLK  -> Pi GPIO11 (Pin 23, SPI0 SCLK)
 *   MCP3008 DOUT -> Pi GPIO9  (Pin 21, SPI0 MISO)
 *   MCP3008 DIN  -> Pi GPIO10 (Pin 19, SPI0 MOSI)
 *   MCP3008 CS   -> Pi GPIO8  (Pin 24, SPI0 CE0)
 *   MCP3008 CH0  -> MLX91211 analog output
 *   MLX91211 VDD -> Pi 5V
 *   MLX91211 GND -> Pi GND
 */

#define SPI_CHANNEL 0          /* CE0 on GPIO8 */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_FLAGS   0          /* mode 0, active-low CE */
#define ADC_CHANNEL 0          /* MCP3008 channel 0 */
#define VREF        5.0        /* MCP3008 reference voltage */
#define ADC_MAX     1023       /* 10-bit ADC full-scale code */
#define MLX_VZERO   2.5        /* MLX91211 output at 0 A */
#define MLX_VFS     5.0        /* MLX91211 output at full-scale +50 A */
#define CURRENT_MAX 50.0       /* full-scale current (A) */
#define LOG_FILE    "current_log.txt"
#define SAMPLE_US   100000     /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_fp    = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl-C)                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel; returns 0-1023 or -1 on error   */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   tx[0] = 0x01                       start bit
     *   tx[1] = 0x80 | (channel << 4)      single-ended + channel
     *   tx[2] = 0x00                       padding
     * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)(0x80 | (channel << 4)), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
}

/* ------------------------------------------------------------------ */
/* Convert raw ADC code to current (A) using MLX91211 ratiometric map  */
/* ------------------------------------------------------------------ */
static float adc_to_current(int adc_code)
{
    if (adc_code < 0 || adc_code > ADC_MAX) {
        fprintf(stderr, "ADC code out of range: %d\n", adc_code);
        return 0.0f;
    }

    float voltage = (float)adc_code * VREF / (float)ADC_MAX;

    if (voltage < MLX_VZERO || voltage > MLX_VFS) {
        fprintf(stderr, "Warning: voltage %.3f V out of MLX91211 range "
                        "(%.1f V to %.1f V); skipping sample\n",
                voltage, MLX_VZERO, MLX_VFS);
        return 0.0f;
    }

    /* Linear interpolation: 2.5 V -> 0 A, 5.0 V -> 50 A */
    return (voltage - MLX_VZERO) * (CURRENT_MAX / (MLX_VFS - MLX_VZERO));
}

/* ------------------------------------------------------------------ */
/* Append a timestamped current reading to the log file                */
/* ------------------------------------------------------------------ */
static void log_current(float current)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s %.2f A\n", ts, current) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX91211 current monitor running. Press Ctrl-C to stop.\n");
    printf("Logging to '%s' every 100 ms.\n", LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error; skipping sample\n");
        } else {
            float current = adc_to_current(adc);
            log_current(current);
        }

        gpioDelay(SAMPLE_US);  /* 100 ms */
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

