#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_MS 2
#define POLL_INTERVAL_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int debounce_read(struct gpiod_line *line) {
    int high_count = 0;
    int low_count = 0;
    int val;

    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
            return -1;
        }
        if (val == 1) high_count++;
        else low_count++;
        usleep(DEBOUNCE_DELAY_MS * 1000);
    }
    return (high_count > low_count) ? 1 : 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip 0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!line1) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SENSOR1_GPIO, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!line2) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SENSOR2_GPIO, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "b5w-reader") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n", SENSOR1_GPIO, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "b5w-reader") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n", SENSOR2_GPIO, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring B5W-DB01 sensors on GPIO%d and GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR1_GPIO, SENSOR2_GPIO);

    while (program_running) {
        int s1 = debounce_read(line1);
        int s2 = debounce_read(line2);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error; exiting.\n");
            goto cleanup;
        }

        printf("Sensor 1: %d | Sensor 2: %d\n", s1, s2);

        if (s1 == 0 && s2 == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

