#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define DEBOUNCE_MS 200
#define POLL_INTERVAL_MS 50
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define IMAGE_DIR "/home/pi/security_cam"
#define MAX_FILENAME 256

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        syslog(LOG_ERR, "Target %s exists but is not a directory", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        syslog(LOG_ERR, "mkdir(%s): %s", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(void) {
    char filename[MAX_FILENAME];
    char command[512];
    time_t rawtime;
    struct tm timeinfo;
    struct timeval tv;

    gettimeofday(&tv, NULL);
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(filename, sizeof(filename), "%Y-%m-%dT%H:%M:%S", &timeinfo);
    snprintf(filename + strlen(filename), sizeof(filename) - strlen(filename), ".%03ld.jpg", tv.tv_usec / 1000);

    snprintf(command, sizeof(command), "libcamera-still -o %s/%s -w %d -h %d --nopreview --timeout 1000 2>/dev/null",
             IMAGE_DIR, filename, IMAGE_WIDTH, IMAGE_HEIGHT);

    syslog(LOG_INFO, "Capturing image: %s/%s", IMAGE_DIR, filename);

    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork: %s", strerror(errno));
        return -1;
    }
    if (pid == 0) {
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
        _exit(127);
    }

    int status;
    if (waitpid(pid, &status, 0) < 0) {
        syslog(LOG_ERR, "waitpid: %s", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        syslog(LOG_INFO, "Image captured: %s/%s", IMAGE_DIR, filename);
        return 0;
    }

    syslog(LOG_ERR, "libcamera-still failed (status=%d)", WIFEXITED(status) ? WEXITSTATUS(status) : -1);
    return -1;
}

int main(void) {
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "Failed to set pull-down on GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_directory(IMAGE_DIR) != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Motion detector started on GPIO%d", PIR_GPIO);

    int last_state = gpioRead(PIR_GPIO);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpioRead failed on GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead failed on GPIO%d", PIR_GPIO);
            break;
        }

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_MS * 1000);
            int confirmed = gpioRead(PIR_GPIO);
            if (confirmed < 0) {
                syslog(LOG_ERR, "gpioRead failed on GPIO%d during debounce", PIR_GPIO);
                break;
            }
            if (confirmed == current_state) {
                if (current_state == 1) {
                    syslog(LOG_INFO, "Motion detected on GPIO%d", PIR_GPIO);
                    if (capture_image() != 0) {
                        syslog(LOG_ERR, "Image capture failed");
                    }
                }
                last_state = current_state;
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

