#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/videodev2.h>
#include <linux/udp.h>

#define MAX_FRAGS 100
#define MAX_PAYLOAD 65000
#define HEADER_SIZE 16
#define MAX_FRAME_SIZE (MAX_PAYLOAD - HEADER_SIZE)

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);
    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Invalid port: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/video0", O_RDWR);
    if (fd == -1) {
        perror("open /dev/video0");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "/dev/video0 is not a video capture device\n");
        close(fd);
        return EXIT_FAILURE;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "/dev/video0 does not support streaming\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    unsigned char *buffers[4] = {0};
    size_t buffer_sizes[4] = {0};
    for (int i = 0; i < 4; i++) {
        buf.index = i;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            goto cleanup;
        }
        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap");
            buffers[i] = NULL;
            goto cleanup;
        }
        buffer_sizes[i] = buf.length;
    }

    for (int i = 0; i < 4; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd == -1) {
        perror("socket");
        goto cleanup;
    }

    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &servaddr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address: %s\n", server_ip);
        close(sockfd);
        goto cleanup;
    }

    int frame_idx = 0;
    while (running) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            if (errno == EAGAIN) continue;
            perror("VIDIOC_DQBUF");
            break;
        }

        size_t payload_len = buffer_sizes[buf.index];
        int frag_count = (payload_len + MAX_PAYLOAD - 1) / MAX_PAYLOAD;
        if (frag_count > MAX_FRAGS) {
            fprintf(stderr, "Frame too large: %zu bytes, max %d fragments\n", payload_len, MAX_FRAGS);
            xioctl(fd, VIDIOC_QBUF, &buf);
            continue;
        }

        for (int i = 0; i < frag_count; i++) {
            size_t frag_len = (i == frag_count - 1) ? (payload_len - i * MAX_PAYLOAD) : MAX_PAYLOAD;
            unsigned char header[HEADER_SIZE];
            memset(header, 0, HEADER_SIZE);
            header[0] = (frame_idx >> 8) & 0xFF;
            header[1] = frame_idx & 0xFF;
            header[2] = (i >> 8) & 0xFF;
            header[3] = i & 0xFF;
            header[4] = (frag_count >> 8) & 0xFF;
            header[5] = frag_count & 0xFF;
            header[6] = (frag_len >> 8) & 0xFF;
            header[7] = frag_len & 0xFF;

            size_t send_len = HEADER_SIZE + frag_len;
            unsigned char *send_buf = malloc(send_len);
            if (!send_buf) {
                perror("malloc");
                xioctl(fd, VIDIOC_QBUF, &buf);
                goto cleanup;
            }
            memcpy(send_buf, header, HEADER_SIZE);
            if (frag_len > 0) {
                memcpy(send_buf + HEADER_SIZE, buffers[buf.index] + i * MAX_PAYLOAD, frag_len);
            }

            if (sendto(sockfd, send_buf, send_len, 0, (struct sockaddr *)&servaddr, sizeof(servaddr)) == -1) {
                perror("sendto");
                free(send_buf);
                xioctl(fd, VIDIOC_QBUF, &buf);
                goto cleanup;
            }
            free(send_buf);
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            break;
        }
        frame_idx++;
    }

cleanup:
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
    }
    for (int i = 0; i < 4; i++) {
        if (buffers[i] && buffers[i] != MAP_FAILED) {
            munmap(buffers[i], buffer_sizes[i]);
        }
    }
    if (sockfd != -1) close(sockfd);
    if (fd != -1) close(fd);
    return EXIT_SUCCESS;
}

