#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define PAN_SERVO_PIN   4
#define TILT_SERVO_PIN  5
#define BTN_UP_PIN      6
#define BTN_DOWN_PIN    7
#define BTN_LEFT_PIN    8
#define BTN_RIGHT_PIN   9

#define SERVO_MIN_DUTY  50
#define SERVO_MAX_DUTY  100
#define SERVO_MID_DUTY  75
#define SERVO_STEP      5
#define SERVO_MIN_POS   25
#define SERVO_MAX_POS   125
#define PWM_PERIOD_US   20000
#define PWM_MIN_US      1000
#define PWM_MAX_US      2000
#define POLL_MS         50

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int map_range(int x, int in_min, int in_max, int out_min, int out_max) {
    if (in_max == in_min) return out_min;
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

static int set_servo(struct gpiod_line *line, int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    int duty_us = map_range(duty_percent, 0, 100, PWM_MIN_US, PWM_MAX_US);
    int on_us = duty_us;
    int off_us = PWM_PERIOD_US - duty_us;
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(on_us);
    if (gpiod_line_set_value(line, 0) < 0) return -1;
    usleep(off_us);
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

