#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define VIDEO_DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define NUM_BUFFERS 4
#define BLUR_RADIUS 2
#define JPEG_QUALITY 75

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static void rgb_from_yuyv(const unsigned char *yuyv, unsigned char *rgb, int w, int h) {
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            int y_idx = (y * w + x) * 2;
            int r_idx = (y * w + x) * 3;
            int y0 = yuyv[y_idx];
            int u = yuyv[y_idx + 1];
            int y1 = yuyv[y_idx + 2];
            int v = yuyv[y_idx + 3];
            int r = (y0 + y1) * 298 + v * (-100);
            int g = (y0 + y1) * 298 + u * (-208) + v * 516;
            int b = (y0 + y1) * 298 + u * 409;
            if (r > 255) r = 255; if (r < 0) r = 0;
            if (g > 255) g = 255; if (g < 0) g = 0;
            if (b > 255) b = 255; if (b < 0) b = 0;
            rgb[r_idx] = r;
            rgb[r_idx + 1] = g;
            rgb[r_idx + 2] = b;
        }
    }
}

static void box_blur(unsigned char *src, unsigned char *dst, int w, int h, int r) {
    int kernel[5][5] = {
        {1, 4, 7, 4, 1},
        {4, 16, 26, 16, 4},
        {7, 26, 41, 26, 7},
        {4, 16, 26, 16, 4},
        {1, 4, 7, 4, 1}
    };
    int sum = 0;
    for (int i = 0; i < 25; i++) sum += kernel[i / 5][i % 5];
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            int r_sum = 0, g_sum = 0, b_sum = 0;
            for (int j = -r; j <= r; j++) {
                for (int i = -r; i <= r; i++) {
                    int nx = x + i, ny = y + j;
                    if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
                    int idx = (ny * w + nx) * 3;
                    r_sum += src[idx] * kernel[j + r][i + r];
                    g_sum += src[idx + 1] * kernel[j + r][i + r];
                    b_sum += src[idx + 2] * kernel[j + r][i + r];
                }
            }
            int idx = (y * w + x) * 3;
            dst[idx] = r_sum / sum;
            dst[idx + 1] = g_sum / sum;
            dst[idx + 2] = b_sum / sum;
        }
    }
}

static int save_jpeg(const char *filename, unsigned char *rgb, int w, int h) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile = fopen(filename, "wb");
    if (!outfile) { perror("fopen"); return -1; }
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_stdio_dest(&cinfo, outfile);
    cinfo.image_width = w;
    cinfo.image_height = h;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;
    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);
    JSAMPROW row_pointer[1];
    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb[cinfo.next_scanline * w * 3];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }
    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    fclose(outfile);
    return 0;
}

int main(void) {
    int fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd < 0) { perror("open"); return 1; }
    struct sigaction sa = {0};
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    struct v4l2_capability cap;
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP"); close(fd); return 1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Not a video capture device\n"); close(fd); return 1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Streaming not supported\n"); close(fd); return 1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT"); close(fd); return 1;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Unsupported pixel format\n"); close(fd); return 1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS"); close(fd); return 1;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n"); close(fd); return 1;
    }
    struct v4l2_buffer buf;
    unsigned char *buffers[NUM_BUFFERS];
    for (int i = 0; i < NUM_BUFFERS; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF"); goto cleanup;
        }
        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap"); goto cleanup;
        }
        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF"); goto cleanup;
        }
    }
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON"); goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;
    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r < 0) {
        if (errno == EINTR) goto cleanup;
        perror("select"); goto streamoff;
    }
    if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n"); goto streamoff;
    }
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF"); goto streamoff;
    }
    unsigned char *yuyv = buffers[buf.index];
    unsigned char *rgb = malloc(WIDTH * HEIGHT * 3);
    if (!rgb) { perror("malloc"); xioctl(fd, VIDIOC_QBUF, &buf); goto streamoff; }
    rgb_from_yuyv(yuyv, rgb, WIDTH, HEIGHT);
    unsigned char *blurred = malloc(WIDTH * HEIGHT * 3);
    if (!blurred) { perror("malloc"); free(rgb); xioctl(fd, VIDIOC_QBUF, &buf); goto streamoff; }
    box_blur(rgb, blurred, WIDTH, HEIGHT, BLUR_RADIUS);
    char filename[64];
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", tm);
    if (save_jpeg(filename, blurred, WIDTH, HEIGHT) < 0) {
        fprintf(stderr, "Failed to save JPEG\n");
    } else {
        printf("Saved %s\n", filename);
    }
    free(blurred);
    free(rgb);
    xioctl(fd, VIDIOC_QBUF, &buf);
streamoff:
    xioctl(fd, VIDIOC_STREAMOFF, &type);
cleanup:
    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (buffers[i] != MAP_FAILED) munmap(buffers[i], buf.length);
    }
    close(fd);
    return 0;
}

