    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT"); close(fd); return 1;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Unsupported pixel format\n"); close(fd); return 1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS"); close(fd); return 1;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n"); close(fd); return 1;
    }
    struct v4l2_buffer buf;
    unsigned char *buffers[NUM_BUFFERS];
    for (int i = 0; i < NUM_BUFFERS; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF"); goto cleanup;
        }
        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap"); goto cleanup;
        }
        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF"); goto cleanup;
        }
    }
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON"); goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;
    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r < 0) {
        if (errno == EINTR) goto cleanup;
        perror("select"); goto streamoff;
    }
    if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n"); goto streamoff;
    }
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF"); goto streamoff;
    }
    unsigned char *yuyv = buffers[buf.index];
    unsigned char *rgb = malloc(WIDTH * HEIGHT * 3);
    if (!rgb) { perror("malloc"); xioctl(fd, VIDIOC_QBUF, &buf); goto streamoff; }
    rgb_from_yuyv(yuyv, rgb, WIDTH, HEIGHT);
    unsigned char *blurred = malloc(WIDTH * HEIGHT * 3);
    if (!blurred) { perror("malloc"); free(rgb); xioctl(fd, VIDIOC_QBUF, &buf); goto streamoff; }
    box_blur(rgb, blurred, WIDTH, HEIGHT, BLUR_RADIUS);
    char filename[64];
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", tm);
    if (save_jpeg(filename, blurred, WIDTH, HEIGHT) < 0) {
        fprintf(stderr, "Failed to save JPEG\n");
    } else {
        printf("Saved %s\n", filename);
    }
    free(blurred);
    free(rgb);
    xioctl(fd, VIDIOC_QBUF, &buf);
streamoff:
    xioctl(fd, VIDIOC_STREAMOFF, &type);
cleanup:
    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (buffers[i] != MAP_FAILED) munmap(buffers[i], buf.length);
    }
    close(fd);
    return 0;
}

