#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static void print_capabilities(const struct v4l2_capability *cap) {
    printf("Driver: %s\n", cap->driver);
    printf("Card: %s\n", cap->card);
    printf("Bus info: %s\n", cap->bus_info);
    printf("Version: %u.%u.%u\n",
           (cap->version >> 16) & 0xFF,
           (cap->version >> 8) & 0xFF,
           cap->version & 0xFF);
}

static void print_formats(const struct v4l2_fmtdesc *fmt) {
    printf("Supported formats:\n");
    for (int i = 0; ; i++) {
        struct v4l2_fmtdesc f;
        memset(&f, 0, sizeof(f));
        f.index = i;
        f.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fmt->fd, VIDIOC_ENUM_FMT, &f) < 0) {
            if (errno == EINVAL) break;
            perror("VIDIOC_ENUM_FMT");
            break;
        }
        printf("  %d. %s (%c%c%c%c)\n",
               i,
               f.description,
               (f.pixelformat & 0xFF),
               (f.pixelformat >> 8) & 0xFF,
               (f.pixelformat >> 16) & 0xFF,
               (f.pixelformat >> 24) & 0xFF);
    }
}

static void print_resolutions(int fd) {
    printf("Supported resolutions:\n");
    for (int i = 0; ; i++) {
        struct v4l2_frmsizeenum size;
        memset(&size, 0, sizeof(size));
        size.index = i;
        size.pixel_format = V4L2_PIX_FMT_YUYV;
        if (xioctl(fd, VIDIOC_ENUM_FRAMESIZES, &size) < 0) {
            if (errno == EINVAL) break;
            perror("VIDIOC_ENUM_FRAMESIZES");
            break;
        }
        if (size.type != V4L2_FRMSIZE_TYPE_DISCRETE) continue;
        printf("  %d x %d\n", size.discrete.width, size.discrete.height);
    }
}

static void print_frame_rates(int fd, int width, int height) {
    printf("Supported frame rates for %dx%d:\n", width, height);
    for (int i = 0; ; i++) {
        struct v4l2_frmivalenum iv;
        memset(&iv, 0, sizeof(iv));
        iv.index = i;
        iv.pixel_format = V4L2_PIX_FMT_YUYV;
        iv.width = width;
        iv.height = height;
        if (xioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &iv) < 0) {
            if (errno == EINVAL) break;
            perror("VIDIOC_ENUM_FRAMEINTERVALS");
            break;
        }
        if (iv.type != V4L2_FRMIVAL_TYPE_DISCRETE) continue;
        printf("  %d/%d fps\n", iv.discrete.numerator, iv.discrete.denominator);
    }
}

static void print_autofocus(int fd) {
    struct v4l2_queryctrl ctrl;
    memset(&ctrl, 0, sizeof(ctrl));
    ctrl.id = V4L2_CID_FOCUS_AUTO;
    if (xioctl(fd, VIDIOC_QUERYCTRL, &ctrl) < 0) {
        if (errno == EINVAL) {
            printf("Autofocus control not supported.\n");
        } else {
            perror("VIDIOC_QUERYCTRL");
        }
        return;
    }
    if (ctrl.flags & V4L2_CTRL_FLAG_DISABLED) {
        printf("Autofocus control disabled.\n");
        return;
    }
    printf("Autofocus control supported.\n");
}

int main(void) {
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device.\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O.\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    print_capabilities(&cap);
    print_formats((struct v4l2_fmtdesc){.fd = fd});
    print_resolutions(fd);
    print_frame_rates(fd, 640, 480);
    print_autofocus(fd);

    close(fd);
    return EXIT_SUCCESS;
}

