#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_SERVO_PIN  4
#define TILT_SERVO_PIN 5

#define BUTTON_UP    6
#define BUTTON_DOWN  7
#define BUTTON_LEFT  8
#define BUTTON_RIGHT 9

#define SERVO_MIN_PULSEWIDTH 1000
#define SERVO_MAX_PULSEWIDTH 2000
#define SERVO_CENTER_PULSEWIDTH 1500
#define SERVO_STEP 10
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_servo(int pin, int pulsewidth) {
    if (pulsewidth < SERVO_MIN_PULSEWIDTH) pulsewidth = SERVO_MIN_PULSEWIDTH;
    if (pulsewidth > SERVO_MAX_PULSEWIDTH) pulsewidth = SERVO_MAX_PULSEWIDTH;
    if (gpioServo(pin, pulsewidth) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d (pw=%d)\n", pin, pulsewidth);
        return -1;
    }
    return 0;
}

static void center_servos(void) {
    set_servo(PAN_SERVO_PIN, SERVO_CENTER_PULSEWIDTH);
    set_servo(TILT_SERVO_PIN, SERVO_CENTER_PULSEWIDTH);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with internal pull-ups (active-low) */
    int button_pins[] = {BUTTON_UP, BUTTON_DOWN, BUTTON_LEFT, BUTTON_RIGHT};
    for (size_t i = 0; i < sizeof(button_pins) / sizeof(button_pins[0]); i++) {
        if (gpioSetMode(button_pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed on button pin %d\n", button_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(button_pins[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed on button pin %d\n", button_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Center the servos and print startup info */
    center_servos();
    printf("Pan-Tilt System Ready\n");
    printf("  Pan servo : GPIO%d\n", PAN_SERVO_PIN);
    printf("  Tilt servo: GPIO%d\n", TILT_SERVO_PIN);
    printf("  Buttons   : UP=GPIO%d, DOWN=GPIO%d, LEFT=GPIO%d, RIGHT=GPIO%d (active-low)\n",
           BUTTON_UP, BUTTON_DOWN, BUTTON_LEFT, BUTTON_RIGHT);
    printf("  Center position: %d us\n", SERVO_CENTER_PULSEWIDTH);
    printf("Press Ctrl+C to exit.\n");

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction failed; exiting may leave servos PWM active\n");
    }

    int pan_pos = SERVO_CENTER_PULSEWIDTH;
    int tilt_pos = SERVO_CENTER_PULSEWIDTH;

    while (g_running) {
        int up    = gpioRead(BUTTON_UP);
        int down  = gpioRead(BUTTON_DOWN);
        int left  = gpioRead(BUTTON_LEFT);
        int right = gpioRead(BUTTON_RIGHT);

        if (up == 0)    pan_pos += SERVO_STEP;
        if (down == 0)  pan_pos -= SERVO_STEP;
        if (left == 0)  tilt_pos -= SERVO_STEP;
        if (right == 0) tilt_pos += SERVO_STEP;

        if (pan_pos < SERVO_MIN_PULSEWIDTH) pan_pos = SERVO_MIN_PULSEWIDTH;
        if (pan_pos > SERVO_MAX_PULSEWIDTH) pan_pos = SERVO_MAX_PULSEWIDTH;
        if (tilt_pos < SERVO_MIN_PULSEWIDTH) tilt_pos = SERVO_MIN_PULSEWIDTH;
        if (tilt_pos > SERVO_MAX_PULSEWIDTH) tilt_pos = SERVO_MAX_PULSEWIDTH;

        if (set_servo(PAN_SERVO_PIN, pan_pos) < 0) break;
        if (set_servo(TILT_SERVO_PIN, tilt_pos) < 0) break;

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown: stop PWM on both servo pins */
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("\nPan-Tilt System Stopped\n");
    return EXIT_SUCCESS;
}

