    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(json, json_len,
             "{\"filename\":\"%s\",\"timestamp\":\"%s.%06ld\",\"motion_detected\":%d,\"gpio_pin\":%d}",
