        return -1;
    }
    res = curl_easy_setopt(curl, CURLOPT_POST, 1L);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: curl_easy_setopt(CURLOPT_POST) failed: %s\n", curl_easy_strerror(res));
        return -1;
    }
