        return -1;
    }
    res = curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json));
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: curl_easy_setopt(CURLOPT_POSTFIELDSIZE) failed: %s\n", curl_easy_strerror(res));
        return -1;
    }
