#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define IMAGE_DIR       "/home/pi/images"
#define LOG_FILE        "/home/pi/motion_capture.log"
#define DEBOUNCE_MS     50
#define CAPTURE_TIMEOUT_MS 2000
#define CAPTURE_WIDTH   640
#define CAPTURE_HEIGHT  480
#define CAPTURE_QUALITY 85

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown time] %s\n", msg);
    }
    fclose(fp);
}

static int ensure_image_dir(void)
{
    struct stat st;
    if (stat(IMAGE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        fprintf(stderr, "Error: %s exists but is not a directory\n", IMAGE_DIR);
        return -1;
    }
    if (mkdir(IMAGE_DIR, 0755) != 0 && errno != EEXIST) {
        perror("mkdir");
        return -1;
    }
    return 0;
}

static int generate_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    struct tm tm;
    if (!localtime_r(&ts.tv_sec, &tm)) {
        perror("localtime_r");
        return -1;
    }
    long ms = ts.tv_nsec / 1000000L;
    int written = snprintf(buf, len, "%04d%02d%02d_%02d%02d%02d_%03ld.jpg",
                           tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                           tm.tm_hour, tm.tm_min, tm.tm_sec, ms);
    if (written < 0 || (size_t)written >= len) {
        fprintf(stderr, "Timestamp buffer too small\n");
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename)
{
    char cmd[512];
    int n = snprintf(cmd, sizeof(cmd),
                     "libcamera-still -o '%s' --width %d --height %d -q %d --timeout %d --nopreview 2>>%s",
                     filename, CAPTURE_WIDTH, CAPTURE_HEIGHT, CAPTURE_QUALITY,
                     CAPTURE_TIMEOUT_MS, LOG_FILE);
    if (n < 0 || (size_t)n >= sizeof(cmd)) {
        fprintf(stderr, "Command buffer too small\n");
        return -1;
    }

    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return -1;
    }
    if (pid == 0) {
        execl("/bin/sh", "sh", "-c", cmd, (char *)NULL);
        perror("execl");
        _exit(127);
    }

    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) {
            if (!g_running)
                return -1;
            continue;
        }
        perror("waitpid");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
        return 0;

    fprintf(stderr, "libcamera-still failed (status=%d)\n", status);
    return -1;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (ensure_image_dir() != 0)
        return EXIT_FAILURE;

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_falling_edge_events(line, "motion-capture") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Motion detection started on BCM GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);
    log_event("Motion detection service started.");

    while (g_running) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            if (errno == EINTR)
                continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0)
            continue;

        if (gpiod_line_event_read(line, &event) < 0) {
            if (errno == EINTR)
                continue;
            perror("gpiod_line_event_read");
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE)
            continue;

        struct timespec ts = {0, DEBOUNCE_MS * 1000000L};
        nanosleep(&ts, NULL);

        char ts_buf[64];
        if (generate_timestamp(ts_buf, sizeof(ts_buf)) != 0) {
            log_event("Error: failed to generate timestamp.");
            continue;
        }

        char filename[256];
        int n = snprintf(filename, sizeof(filename), "%s/%s", IMAGE_DIR, ts_buf);
        if (n < 0 || (size_t)n >= sizeof(filename)) {
            log_event("Error: filename buffer too small.");
            continue;
        }

        printf("Motion detected on GPIO%d. Capturing image: %s\n", GPIO_LINE_OFFSET, filename);
        log_event(filename);

        if (capture_image(filename) == 0) {
            printf("Image saved successfully.\n");
            log_event("Image capture successful.");
        } else {
            fprintf(stderr, "Failed to capture image.\n");
            log_event("Error: image capture failed.");
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    log_event("Motion detection service stopped.");
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

