#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define OUTPUT_FILE "cropped.yuv"
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CAPTURE_FORMAT V4L2_PIX_FMT_YUYV

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer = NULL;
    size_t buffer_size = 0;
    FILE *out = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = CAPTURE_WIDTH;
    fmt.fmt.pix.height = CAPTURE_HEIGHT;
    fmt.fmt.pix.pixelformat = CAPTURE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }
    if (fmt.fmt.pix.pixelformat != CAPTURE_FORMAT) {
        fprintf(stderr, "Device does not support YUYV format\n");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        goto cleanup;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        buffer = NULL;
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    int r;
    do {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = 2;
        tv.tv_usec = 0;
        r = select(fd + 1, &fds, NULL, NULL, &tv);
    } while (r == -1 && errno == EINTR && !stop_flag);

    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "Interrupted by signal during select()\n");
        } else {
            perror("select");
        }
        goto streamoff;
    }
    if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        goto streamoff;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        goto streamoff;
    }

    if (buf.bytesused < (unsigned)(CAPTURE_WIDTH * CAPTURE_HEIGHT * 2)) {
        fprintf(stderr, "Unexpected bytesused: %u\n", buf.bytesused);
        goto streamoff;
    }

    if (buf.width != CAPTURE_WIDTH || buf.height != CAPTURE_HEIGHT) {
        fprintf(stderr, "Unexpected dimensions: %ux%u\n", buf.width, buf.height);
        goto streamoff;
    }

    if (buf.field != V4L2_FIELD_NONE) {
        fprintf(stderr, "Unexpected field: %u\n", buf.field);
        goto streamoff;
    }

    if (buf.flags & V4L2_BUF_FLAG_ERROR) {
        fprintf(stderr, "Buffer error flag set\n");
        goto streamoff;
    }

    size_t expected = (size_t)CAPTURE_WIDTH * CAPTURE_HEIGHT * 2;
    if (buf.bytesused < expected) {
        fprintf(stderr, "Short frame: %u bytes, expected %zu\n", buf.bytesused, expected);
        goto streamoff;
    }

    size_t crop_bytes = (size_t)CROP_WIDTH * CROP_HEIGHT * 2;
    out = fopen(OUTPUT_FILE, "wb");
    if (!out) {
        perror("fopen(" OUTPUT_FILE ")");
        goto streamoff;
    }

    unsigned char *yuyv = (unsigned char *)buffer;
    unsigned char *crop = malloc(crop_bytes);
    if (!crop) {
        perror("malloc");
        goto streamoff;
    }

    for (int y = CROP_Y; y < CROP_Y + CROP_HEIGHT && y < CAPTURE_HEIGHT; y++) {
        for (int x = CROP_X; x < CROP_X + CROP_WIDTH && x < CAPTURE_WIDTH; x++) {
            int idx = (y * CAPTURE_WIDTH + x) * 2;
            int cx = x - CROP_X;
            int cy = y - CROP_Y;
            int cidx = (cy * CROP_WIDTH + cx) * 2;
            crop[cidx]     = yuyv[idx];
            crop[cidx + 1] = yuyv[idx + 1];
        }
    }

    size_t written = fwrite(crop, 1, crop_bytes, out);
    if (written != crop_bytes) {
        fprintf(stderr, "Short write: %zu of %zu\n", written, crop_bytes);
        goto streamoff;
    }

    printf("Cropped %dx%d region saved as %s\n", CROP_WIDTH, CROP_HEIGHT, OUTPUT_FILE);
    ret = EXIT_SUCCESS;

streamoff:
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
    }

cleanup:
    if (buffer && buffer != MAP_FAILED) {
        munmap(buffer, buffer_size);
    }
    if (fd != -1) {
        close(fd);
    }
    if (out) {
        fclose(out);
    }
    if (crop) {
        free(crop);
    }
    return ret;
}

