#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_GPIO 17
#define TILT_GPIO 18
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define STEP 5
#define NEUTRAL_ANGLE 90
#define SERVO_FREQ 50
#define SERVO_RANGE 180
#define SERVO_NEUTRAL 90
#define SERVO_MIN 0
#define SERVO_MAX 180
#define DELAY_MS 100

static volatile int keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int angle_to_pulsewidth(int angle) {
