static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int oled_command(int handle, uint8_t cmd) {
    char buf[2] = {0x00, (char)cmd};
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed for command 0x%02X\n", cmd);
        return -1;
    }
    return 0;
}

static int oled_data(int handle, uint8_t data) {
    char buf[2] = {0x40, (char)data};
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed for data 0x%02X\n", data);
        return -1;
    }
    return 0;
}

static int oled_init(int handle) {
