    if (oled_command(handle, 0x40) != 0) return -1;
    if (oled_command(handle, SSD1306_CMD_SET_DISPLAY_ALL_ON) != 0) return -1;
    if (oled_command(handle, SSD1306_CMD_SET_DISPLAY_NORMAL) != 0) return -1;
    if (oled_command(handle, SSD1306_CMD_DISPLAY_ON) != 0) return -1;
