}

static int oled_clear(int handle) {
    for (int page = 0; page < 8; page++) {
        if (oled_command(handle, SSD1306_CMD_SET_PAGE_START + page) != 0) return -1;
        if (oled_command(handle, SSD1306_CMD_SET_COLUMN_LOW) != 0) return -1;
        if (oled_command(handle, SSD1306_CMD_SET_COLUMN_HIGH) != 0) return -1;
        for (int col = 0; col < OLED_WIDTH; col++) {
            if (oled_data(handle, 0x00) != 0) return -1;
