#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define E_PULSE_US 500
#define E_DELAY_US 500

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;
static double total_volume = 0.0;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio; (void)level; (void)tick;
    pulse_count++;
}

static void lcd_strobe(int data) {
    gpioWrite(FLOW_SENSOR_GPIO, data & ENABLE);
    gpioDelay(E_PULSE_US);
    gpioWrite(FLOW_SENSOR_GPIO, (data & ~ENABLE) | (data & ENABLE));
    gpioDelay(E_DELAY_US);
}

static void lcd_byte(int bits, int mode) {
    int hi = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int lo = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;
    gpioWrite(FLOW_SENSOR_GPIO, hi);
    lcd_strobe(hi);
    gpioWrite(FLOW_SENSOR_GPIO, lo);
    lcd_strobe(lo);
}

static void lcd_string(const char *s) {
    while (*s) lcd_byte(*s++, LCD_CHR);
}

static void lcd_clear(void) {
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(2000);
}

static void lcd_init(void) {
    gpioSetMode(FLOW_SENSOR_GPIO, PI_OUTPUT);
    gpioWrite(FLOW_SENSOR_GPIO, 0);
    gpioDelay(50000);
    lcd_byte(0x33, LCD_CMD);
    lcd_byte(0x32, LCD_CMD);
    lcd_byte(0x28, LCD_CMD);
    lcd_byte(0x0C, LCD_CMD);
    lcd_byte(0x06, LCD_CMD);
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(2000);
}

static void lcd_print(const char *line1, const char *line2) {
    lcd_clear();
    lcd_string(line1);
    lcd_byte(LCD_LINE_2, LCD_CMD);
    lcd_string(line2);
}

static void update_lcd(void) {
    char line1[LCD_WIDTH + 1];
    char line2[LCD_WIDTH + 1];
    snprintf(line1, sizeof(line1), "Flow: %.2f L/min", (pulse_count / 450.0) * 60.0);
    snprintf(line2, sizeof(line2), "Total: %.2f L", total_volume);
    lcd_print(line1, line2);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lcd_init();

    if (gpioSetAlertFunc(FLOW_SENSOR_GPIO, pulse_callback) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    time_t last_lcd_update = time(NULL);

    while (running) {
        time_t now = time(NULL);
        if (difftime(now, last_lcd_update) >= 10.0) {
            update_lcd();
            last_lcd_update = now;
        }

        double flow_rate = (pulse_count / 450.0) * 60.0;
        total_volume += flow_rate / 60.0;
        pulse_count = 0;

        char line1[LCD_WIDTH + 1];
        char line2[LCD_WIDTH + 1];
        snprintf(line1, sizeof(line1), "Flow: %.2f L/min", flow_rate);
        snprintf(line2, sizeof(line2), "Total: %.2f L", total_volume);
        printf("%s\n%s\n", line1, line2);
        fflush(stdout);

        gpioDelay(1000000);
    }

    lcd_clear();
    lcd_print("Shutting down...", "");
    gpioSetAlertFunc(FLOW_SENSOR_GPIO, NULL);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

