        fprintf(stderr, "LCD initialisation failed (sensor absent or bus error)\n");
        goto cleanup;
    }

    /* --- SPI (MCP3008 ADC) --- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED_HZ, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %s\n",
                SPI_CHANNEL, strerror(errno));
        goto cleanup;
    }

    /* --- Anemometer GPIO --- */
    if (gpioSetMode(ANEMOMETER_GPIO, PI_INPUT) < 0) {
