        goto cleanup;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Wind monitor started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        uint32_t pulses = g_pulse_count;
        g_pulse_count = 0;

