 *
 * Hardware:
 *   - 16x2 LCD (PCF8574 I2C backpack) at I2C address 0x27, bus 1
 *   - Anemometer: pulses on GPIO17 (rising edge)
 *   - Wind vane: MCP3008 ADC on SPI0/CE0, channel 0
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o wind_monitor wind_monitor.c -lpigpio -lrt
 *   (run as root)
 */

#include <stdio.h>
