#define SPI_SPEED_HZ         1000000    /* 1 MHz */
#define SPI_FLAGS            0          /* mode 0, active-low CE */
#define ADC_CHANNEL          0          /* MCP3008 channel 0 */
#define SAMPLE_PERIOD_US     500000     /* 500 ms */
#define MAX_PULSES           1000       /* sanity cap on anemometer pulses */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_count = 0;

