static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata);
static void signal_handler(int sig);
static int  lcd_init(int handle);
static int  lcd_write(int handle, uint8_t data);
static int  lcd_command(int handle, uint8_t cmd);
static int  lcd_data(int handle, uint8_t data);
static int  lcd_string(int handle, const char *str);
static void lcd_clear(int handle);
static void lcd_set_cursor(int handle, uint8_t row, uint8_t col);
static void lcd_wind_data(int handle, float wind_speed, float wind_direction);
static int  read_mcp3008(int spi_handle, uint8_t channel);
static void cleanup(int spi_handle, int i2c_handle);

/* ----------------------------- ISR --------------------------------------- */
static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    g_pulse_count++;
}

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- LCD helpers ------------------------------- */
static int lcd_init(int handle)
{
    if (lcd_command(handle, 0x33) < 0) return -1;
    if (lcd_command(handle, 0x32) < 0) return -1;
    if (lcd_command(handle, 0x28) < 0) return -1; /* 2-line, 5x8 font */
    if (lcd_command(handle, 0x0C) < 0) return -1; /* display on, cursor off */
    if (lcd_command(handle, 0x06) < 0) return -1; /* entry mode: increment */
    if (lcd_command(handle, 0x01) < 0) return -1; /* clear */
    return 0;
}

static int lcd_write(int handle, uint8_t data)
{
    /* PCF8574 bit layout: D0-D7 in bits 1-8, RS=bit0, R/W=bit1, E=bit2, BL=bit3 */
    uint8_t buf[2];
    buf[0] = (data & 0xF0) | 0x01;          /* RS=1 (data) */
    buf[1] = ((data << 4) & 0xF0) | 0x01;   /* RS=1, lower nibble */
    if (i2cWriteDevice(handle, (char *)buf, 2) < 0)
        return -1;
    gpioDelay(1000);                         /* 1 ms enable pulse */
    return 0;
}

static int lcd_command(int handle, uint8_t cmd)
{
    return lcd_write(handle, cmd);
}

static int lcd_data(int handle, uint8_t data)
{
    return lcd_write(handle, data);
}

static int lcd_string(int handle, const char *str)
{
    while (*str) {
        if (lcd_data(handle, (uint8_t)*str++) < 0)
            return -1;
    }
    return 0;
}

static void lcd_clear(int handle)
{
    lcd_command(handle, 0x01);
    gpioDelay(2000); /* clear needs ~1.52 ms */
}

static void lcd_set_cursor(int handle, uint8_t row, uint8_t col)
{
    uint8_t addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    lcd_command(handle, addr);
}

/* ----------------------------- Wind data display ------------------------- */
static void lcd_wind_data(int handle, float wind_speed, float wind_direction)
{
    char line1[17];
    char line2[17];

    snprintf(line1, sizeof(line1), "Spd: %.1f m/s", wind_speed);
    snprintf(line2, sizeof(line2), "Dir: %.0f deg", wind_direction);

    lcd_clear(handle);
    lcd_set_cursor(handle, 0, 0);
    lcd_string(handle, line1);
    lcd_set_cursor(handle, 1, 0);
    lcd_string(handle, line2);
}

/* ----------------------------- MCP3008 read ------------------------------ */
static int read_mcp3008(int spi_handle, uint8_t channel)
