        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(int spi_handle, int i2c_handle)
{
    if (spi_handle >= 0) spiClose(spi_handle);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
}

