#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define CALIBRATION_FACTOR 7.5
#define PULSES_PER_LITER 1000.0
#define SAMPLE_INTERVAL_SEC 1
#define MAX_NO_FLOW_SECONDS 60

static volatile int pulse_count = 0;
static volatile sig_atomic_t running = 1;

static void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)level; (void)tick; (void)user_data;
    pulse_count++;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int lcd_write_byte(int handle, unsigned char data, int is_data) {
    unsigned char bits = (is_data) ? (data | 0x40) : (data | 0x80);
    unsigned char buf[4];
    buf[0] = bits;
    buf[1] = data;
    buf[2] = 0x00;
    buf[3] = 0x00;
    if (i2cWriteDevice(handle, (char *)buf, 4) < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int lcd_send_command(int handle, unsigned char cmd) {
    return lcd_write_byte(handle, cmd, 0);
}

static int lcd_send_data(int handle, unsigned char data) {
    return lcd_write_byte(handle, data, 1);
}

static int lcd_init(int handle) {
    if (lcd_send_command(handle, 0x33) < 0) return -1;
    if (lcd_send_command(handle, 0x32) < 0) return -1;
    if (lcd_send_command(handle, 0x28) < 0) return -1;
    if (lcd_send_command(handle, 0x0C) < 0) return -1;
    if (lcd_send_command(handle, 0x06) < 0) return -1;
    if (lcd_send_command(handle, 0x01) < 0) return -1;
    return 0;
}

static int lcd_set_cursor(int handle, int col, int row) {
    unsigned char addr = (row == 0) ? 0x00 : 0x40;
    addr += col;
    return lcd_send_command(handle, 0x80 | addr);
}

static int lcd_print(int handle, const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        if (lcd_send_data(handle, (unsigned char)str[i]) < 0) return -1;
    }
    return 0;
}

static void lcd_clear(int handle) {
    lcd_send_command(handle, 0x01);
    time_sleep(0.002);
}

static void lcd_display_flow_rate(int handle, float flow_rate) {
    char buffer[20];
    snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);
    lcd_set_cursor(handle, 0, 0);
    lcd_print(handle, buffer);
}

int main(void) {
    int i2c_handle = -1;
    int no_flow_count = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n", I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (lcd_init(i2c_handle) < 0) {
        fprintf(stderr, "LCD initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        pulse_count = 0;
        time_sleep(SAMPLE_INTERVAL_SEC);

        if (!running) break;

        int pulses = pulse_count;
        float flow_rate = (float)pulses / CALIBRATION_FACTOR * PULSES_PER_LITER / 60.0;

        lcd_clear(i2c_handle);
        lcd_display_flow_rate(i2c_handle, flow_rate);

        if (pulses == 0) {
            no_flow_count++;
            if (no_flow_count >= MAX_NO_FLOW_SECONDS) {
                fprintf(stderr, "Warning: No flow detected for %d seconds. Sensor may be disconnected.\n", no_flow_count);
                no_flow_count = 0;
            }
        } else {
            no_flow_count = 0;
        }
    }

    printf("\nShutting down gracefully...\n");
    lcd_clear(i2c_handle);
    lcd_print(i2c_handle, "Shutting down...");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

