#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR        0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY  0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_IRQ_STATUS 0x21
#define SI1145_REG_IRQ_ENABLE 0x0F
#define SI1145_REG_COMMAND  0x18
#define SI1145_CMD_RESET    0x01
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PS_AUTO  0x0D
#define SI1145_CMD_ALS_AUTO 0x0E
#define SI1145_PART_ID      0x45
#define I2C_BUS             1
#define LOG_FILE            "biometric_log.txt"
#define SAMPLE_INTERVAL_US  500000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(handle, reg, val);
}

static int si1145_init(int handle) {
    uint8_t part_id = 0;
    if (i2c_read_reg(handle, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read PART_ID register.\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Error: Unexpected PART_ID 0x%02X (expected 0x%02X). Sensor not present?\n",
                part_id, SI1145_PART_ID);
        return -1;
    }

    if (i2c_write_reg(handle, SI1145_REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY.\n");
        return -1;
    }

    if (i2c_write_reg(handle, SI1145_REG_MEAS_RATE0, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write MEAS_RATE0.\n");
        return -1;
    }

    if (i2c_write_reg(handle, SI1145_REG_IRQ_ENABLE, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write IRQ_ENABLE.\n");
        return -1;
    }

    if (i2c_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to send RESET command.\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_PS_AUTO) < 0) {
        fprintf(stderr, "Error: Failed to start PS_AUTO.\n");
        return -1;
    }
    if (i2c_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_AUTO) < 0) {
        fprintf(stderr, "Error: Failed to start ALS_AUTO.\n");
        return -1;
    }
    gpioDelay(10000);

    return 0;
}

static int read_si1145_data(int handle, uint16_t *prox, uint16_t *als) {
    uint8_t ps_low, ps_high, als_low, als_high;

    if (i2c_read_reg(handle, 0x22, &ps_low) < 0) return -1;
    if (i2c_read_reg(handle, 0x23, &ps_high) < 0) return -1;
    if (i2c_read_reg(handle, 0x2C, &als_low) < 0) return -1;
    if (i2c_read_reg(handle, 0x2D, &als_high) < 0) return -1;

    *prox = ((uint16_t)ps_high << 8) | ps_low;
    *als  = ((uint16_t)als_high << 8) | als_low;
    return 0;
}

static void log_data(FILE *fp, uint16_t prox, uint16_t als) {
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Proximity: %u, Ambient Light: %u\n", ts, prox, als);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (si1145_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: Si1145 initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Si1145 initialized. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        uint16_t prox = 0, als = 0;
        if (read_si1145_data(g_i2c_handle, &prox, &als) == 0) {
            log_data(g_log_file, prox, als);
        } else {
            fprintf(stderr, "Warning: I2C read failed, skipping sample.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return 0;
}

