#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_PIN  4   /* GPIO line 4, physical pin 7  */
#define LED_PIN     17  /* GPIO line 17, physical pin 11 */
#define LOG_FILE    "proximity.log"
#define POLL_MS     100
#define BLINK_MS    100
#define CHIP_NAME   "gpiochip4"  /* Raspberry Pi 5 default */

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static int log_event(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        perror("gmtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s Object detected\n", ts) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

static void blink_led(struct gpiod_line *led)
{
    if (gpiod_line_set_value(led, 1) < 0)
        perror("gpiod_line_set_value(ON)");
    usleep(BLINK_MS * 1000);
    if (gpiod_line_set_value(led, 0) < 0)
        perror("gpiod_line_set_value(OFF)");
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        /* Fallback for older kernels that expose the sensor on gpiochip0 */
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *sensor = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor) {
        perror("gpiod_chip_get_line(sensor)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        perror("gpiod_chip_get_line(led)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor, "e18-d50nk-sensor") < 0) {
        perror("gpiod_line_request_input(sensor)");
        goto cleanup;
    }

    if (gpiod_line_request_output(led, "e18-d50nk-led", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    int prev = gpiod_line_get_value(sensor);
    if (prev < 0) {
        perror("gpiod_line_get_value(sensor)");
        goto cleanup;
    }

    printf("Proximity sensor monitoring started (GPIO %d, LED GPIO %d).\n",
           SENSOR_PIN, LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    int first = 1;

    while (running) {
        int val = gpiod_line_get_value(sensor);
        if (val < 0) {
            perror("gpiod_line_get_value(sensor)");
            break;
        }

        /* Falling edge: HIGH -> LOW indicates object entering range */
        if (val == 0 && prev == 1) {
            if (first) {
                first = 0;
            } else {
                blink_led(led);
                if (log_event() < 0)
                    fprintf(stderr, "Warning: failed to log event.\n");
            }
        }

        prev = val;
        usleep(POLL_MS * 1000);
    }

cleanup:
    gpiod_line_release(sensor);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    printf("\nCleanup complete.\n");
    return EXIT_SUCCESS;
}

