        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *sensor = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor) {
        perror("gpiod_chip_get_line(sensor)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        perror("gpiod_chip_get_line(led)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor, "e18-d50nk-sensor") < 0) {
        perror("gpiod_line_request_input(sensor)");
        goto cleanup;
    }

    if (gpiod_line_request_output(led, "e18-d50nk-led", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    int prev = gpiod_line_get_value(sensor);
    if (prev < 0) {
        perror("gpiod_line_get_value(sensor)");
        goto cleanup;
    }

    printf("Proximity sensor monitoring started (GPIO %d, LED GPIO %d).\n",
           SENSOR_PIN, LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    int first = 1;

    while (running) {
        int val = gpiod_line_get_value(sensor);
        if (val < 0) {
            perror("gpiod_line_get_value(sensor)");
            break;
        }

        /* Falling edge: HIGH -> LOW indicates object entering range */
        if (val == 0 && prev == 1) {
            if (first) {
                first = 0;
            } else {
                blink_led(led);
                if (log_event() < 0)
                    fprintf(stderr, "Warning: failed to log event.\n");
            }
        }

        prev = val;
        usleep(POLL_MS * 1000);
    }

cleanup:
    gpiod_line_release(sensor);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    printf("\nCleanup complete.\n");
    return EXIT_SUCCESS;
}

