#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR 0x60

#define SI1145_REG_PART_ID      0x00
#define SI1145_REG_HW_KEY       0x07
#define SI1145_REG_MEAS_RATE0   0x08
#define SI1145_REG_MEAS_RATE1   0x09
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0    0x18
#define SI1145_REG_PS1_DATA1    0x19
#define SI1145_REG_COMMAND      0x30
#define SI1145_REG_CH_LIST      0x4F

#define SI1145_CMD_ALS_FORCE    0x06
#define SI1145_CMD_PS_FORCE     0x07

#define SI1145_PART_ID_EXPECTED 0x45

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, uint16_t *proximity, uint16_t *ambient_light) {
    uint8_t data0, data1;

    if (i2c_read_reg(handle, SI1145_REG_PS1_DATA0, &data0) < 0) return -1;
    if (i2c_read_reg(handle, SI1145_REG_PS1_DATA1, &data1) < 0) return -1;
    *proximity = (uint16_t)((data1 << 8) | data0);

    if (i2c_read_reg(handle, SI1145_REG_ALS_VIS_DATA0, &data0) < 0) return -1;
    if (i2c_read_reg(handle, SI1145_REG_ALS_VIS_DATA1, &data1) < 0) return -1;
    *ambient_light = (uint16_t)((data1 << 8) | data0);

    return 0;
}

static int log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    if (fprintf(fp, "%s,%u,%u\n", timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t part_id;
    if (i2c_read_reg(g_i2c_handle, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID - sensor may be absent\n");
        cleanup();
        return 1;
    }
    if (part_id != SI1145_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID_EXPECTED);
        cleanup();
        return 1;
    }

    if (i2c_write_reg(g_i2c_handle, SI1145_REG_HW_KEY, 0x17) < 0) {
        cleanup();
        return 1;
    }

    if (i2c_write_reg(g_i2c_handle, SI1145_REG_MEAS_RATE0, 0x00) < 0) {
        cleanup();
        return 1;
    }
    if (i2c_write_reg(g_i2c_handle, SI1145_REG_MEAS_RATE1, 0x00) < 0) {
        cleanup();
        return 1;
    }

    if (i2c_write_reg(g_i2c_handle, SI1145_REG_CH_LIST, 0x01) < 0) {
        cleanup();
        return 1;
    }

    g_log_file = fopen("biometric_data.log", "a");
    if (g_log_file == NULL) {
        perror("fopen");
        cleanup();
        return 1;
    }

    while (g_running) {
        if (i2c_write_reg(g_i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) {
            fprintf(stderr, "ALS_FORCE failed, retrying...\n");
            sleep(1);
            continue;
        }
        if (i2c_write_reg(g_i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0) {
            fprintf(stderr, "PS_FORCE failed, retrying...\n");
            sleep(1);
            continue;
        }

        gpioDelay(100000);

        uint16_t proximity, ambient_light;
        if (read_sensor_data(g_i2c_handle, &proximity, &ambient_light) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            sleep(1);
            continue;
        }

        if (log_data(g_log_file, proximity, ambient_light) < 0) {
            fprintf(stderr, "Logging error, continuing...\n");
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

