#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define CHIP_NAME "gpiochip0"
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_SEC 60
#define ECHO_TIMEOUT_SEC 0.030
#define TRIGGER_PULSE_US 10
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define WATERING_THRESHOLD_CM 15.0

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static double measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo) {
    struct timespec ts_start, ts_end;
    struct timespec timeout = { .tv_sec = (long)ECHO_TIMEOUT_SEC, .tv_nsec = 0 };

    if (gpiod_line_set_value(trigger, 0) < 0) {
        log_message("Error: Failed to set trigger low");
        return -1.0;
    }
    usleep(2);
    if (gpiod_line_set_value(trigger, 1) < 0) {
        log_message("Error: Failed to set trigger high");
        return -1.0;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        log_message("Error: Failed to set trigger low after pulse");
        return -1.0;
    }

    while (gpiod_line_get_value(echo) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &ts_start) < 0) {
            log_message("Error: clock_gettime failed");
            return -1.0;
        }
        if (nanosleep(&timeout, NULL) < 0) {
            log_message("Error: Echo start timeout");
            return -1.0;
        }
    }

    while (gpiod_line_get_value(echo) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &ts_end) < 0) {
            log_message("Error: clock_gettime failed");
            return -1.0;
        }
        if (nanosleep(&timeout, NULL) < 0) {
            log_message("Error: Echo end timeout");
            return -1.0;
        }
    }

    double elapsed = (ts_end.tv_sec - ts_start.tv_sec) +
                     (ts_end.tv_nsec - ts_start.tv_nsec) / 1e9;
    if (elapsed <= 0.0) {
        log_message("Error: Invalid echo pulse duration");
        return -1.0;
    }

    double distance = (elapsed * 34300.0) / 2.0;
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        log_message("Error: Distance out of range");
        return -1.0;
    }
    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: gpiod_chip_open_by_name(%s) failed: %s\n", CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        fprintf(stderr, "Error: gpiod_chip_get_line(%d) failed: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error: gpiod_chip_get_line(%d) failed: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hcsr04-trigger", 0) < 0) {
        fprintf(stderr, "Error: gpiod_line_request_output(%d) failed: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Error: gpiod_line_request_input(%d) failed: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    log_message("Program started");

    while (program_running) {
        double distance = measure_distance(trigger, echo);

        if (distance < 0.0) {
            log_message("Error: Sensor read failed");
        } else {
            char log_buf[128];
            snprintf(log_buf, sizeof(log_buf), "Distance: %.2f cm", distance);
            log_message(log_buf);

            if (distance < WATERING_THRESHOLD_CM) {
                log_message("Time to water the plant!");
            }
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    log_message("Program stopped");
    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    return ret;
}

