#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x5A

/* Si1182-A-GMR register map */
#define REG_PART_ID     0x00
#define REG_MEAS_RATE0  0x08
#define REG_COMMAND     0x47
#define REG_PS_DATA0    0x24
#define REG_PS_DATA1    0x25

#define CMD_RESET       0x01
#define CMD_START       0x02

#define EXPECTED_PART_ID 0x82  /* Si1182 */

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

/* Write one byte to a Si1182 register using i2c_smbus_write_byte_data. */
static int si1182_write_reg(int fd, uint8_t reg, uint8_t val)
{
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) {
        fprintf(stderr, "i2c_smbus_write_byte_data(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read one byte from a Si1182 register using i2c_smbus_read_byte_data. */
static int si1182_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    int v = i2c_smbus_read_byte_data(fd, reg);
    if (v < 0) {
        fprintf(stderr, "i2c_smbus_read_byte_data(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

/* Read a 16-bit little-endian register pair (low at reg, high at reg+1). */
static int si1182_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (si1182_read_reg(fd, reg, &lo) < 0)
        return -1;
    if (si1182_read_reg(fd, reg + 1, &hi) < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int si1182_init(int fd)
{
    uint8_t part_id;

    if (si1182_read_reg(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X). Wrong sensor?\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1182 detected (PART_ID=0x%02X).\n", part_id);

    /* Set measurement rate to 0x0A (100 ms typical). */
    if (si1182_write_reg(fd, REG_MEAS_RATE0, 0x0A) < 0)
        return -1;

    /* Reset then start continuous measurement. */
    if (si1182_write_reg(fd, REG_COMMAND, CMD_RESET) < 0)
        return -1;
    usleep(10000);  /* allow reset to complete */
    if (si1182_write_reg(fd, REG_COMMAND, CMD_START) < 0)
        return -1;

    return 0;
}

static int read_proximity(int fd, uint16_t *prox)
{
    return si1182_read_reg16(fd, REG_PS_DATA0, prox);
}

static int calculate_bpm(uint16_t prox)
{
    /* Placeholder: BPM = 60 + (prox / 10). */
    return 60 + (prox / 10);
}

static void log_data(FILE *fp, int bpm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    if (fprintf(fp, "%s,%d\n", ts, bpm) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(fp) != 0)
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1182_ADDR, strerror(errno));
        goto cleanup;
    }

    if (si1182_init(fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        goto cleanup;
    }

    fp = fopen("heartrate.csv", "a");
    if (!fp) {
        fprintf(stderr, "fopen(heartrate.csv) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Logging heart rate to heartrate.csv (Ctrl+C to stop).\n");

    while (running) {
        uint16_t prox;
        int bpm;

        if (read_proximity(fd, &prox) < 0) {
            fprintf(stderr, "Proximity read failed; skipping sample.\n");
            usleep(100000);
            continue;
        }

        bpm = calculate_bpm(prox);
        log_data(fp, bpm);
        usleep(100000);  /* 100 ms */
    }

    printf("\nExiting cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp) {
        if (fclose(fp) != 0)
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
    }
    if (fd >= 0) {
        if (close(fd) != 0)
            fprintf(stderr, "close(fd) failed: %s\n", strerror(errno));
    }
    return rc;
}

