#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* VL53L0X I2C default address */
#define VL53L0X_ADDR 0x29

/* VL53L0X register addresses */
#define VL53L0X_REG_SYSRANGE_START 0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B

/* GPIO pin for triggering range measurements (BCM numbering) */
#define TRIGGER_PIN 17

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Measurement timeout in microseconds (100 ms) */
#define MEASUREMENT_TIMEOUT_US 100000

/* Global state for signal handler */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a VL53L0X register                                 */
/* ------------------------------------------------------------------ */
static int vl53l0x_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a VL53L0X register                                */
/* ------------------------------------------------------------------ */
static int vl53l0x_read_byte(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of bytes from a VL53L0X register                        */
/* ------------------------------------------------------------------ */
static int vl53l0x_read_block(int handle, uint8_t reg, uint8_t *buf, uint8_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, want %u, got %d): %s\n",
                reg, len, rc, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the VL53L0X sensor                                        */
/* ------------------------------------------------------------------ */
static int vl53l0x_init(int handle)
{
    uint8_t model_id = 0;

    /* Verify sensor presence by reading the Model ID register (0x010F) */
    if (vl53l0x_read_byte(handle, 0x010F, &model_id) != 0) {
        fprintf(stderr, "VL53L0X not responding at address 0x%02X\n", VL53L0X_ADDR);
        return -1;
    }

    if (model_id != 0xEA) {
        fprintf(stderr, "Unexpected Model ID: 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }

    /* Clear any pending interrupt */
    if (vl53l0x_write_byte(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    /* Start continuous ranging (bit 0 of SYSRANGE_START) */
    if (vl53l0x_write_byte(handle, VL53L0X_REG_SYSRANGE_START, 0x01) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single distance measurement                               */
/* ------------------------------------------------------------------ */
static int vl53l0x_trigger_and_read(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[14];
    int timeout = 0;

    /* Clear any pending interrupt */
    if (vl53l0x_write_byte(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    /* Start a single measurement */
    if (vl53l0x_write_byte(handle, VL53L0X_REG_SYSRANGE_START, 0x01) < 0)
        return -1;

    /* Poll RESULT_INTERRUPT_STATUS bit 0 until set or timeout */
    while (timeout < MEASUREMENT_TIMEOUT_US) {
        if (vl53l0x_read_byte(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status) != 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
        timeout += 1000;
    }

    if (timeout >= MEASUREMENT_TIMEOUT_US) {
        fprintf(stderr, "VL53L0X measurement timeout\n");
        return -1;
    }

    /* Read 14-byte result block starting at RESULT_RANGE_STATUS */
    if (vl53l0x_read_block(handle, VL53L0X_REG_RESULT_RANGE_STATUS, data, 14) != 0)
        return -1;

    /* Distance is in bytes 10-11 (big-endian 16-bit) */
    *distance_mm = ((uint16_t)data[10] << 8) | data[11];

    /* Clear the interrupt to allow next measurement */
    if (vl53l0x_write_byte(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a distance reading to the CSV file                              */
/* ------------------------------------------------------------------ */
static int log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%u\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x29 */
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l0x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure trigger pin as input with pull-up */
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP);

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L0X ranging started. Press Ctrl+C to stop.\n");

    /* Main measurement loop */
    while (running) {
        /* Wait for falling edge on trigger pin */
        while (gpioRead(TRIGGER_PIN) == 1 && running) {
            gpioDelay(1000); /* 1 ms */
        }
        if (!running)
            break;

        uint16_t distance = 0;
        if (vl53l0x_trigger_and_read(i2c_handle, &distance) == 0) {
            if (log_distance(log_file, distance) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Measurement failed, continuing...\n");
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

