#define MEASURE_DELAY_US 50000
#define LOG_FILE "distance_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;
    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int read_distance(int handle, int *distance_mm) {
    char cmd = 0x01; /* trigger measurement */
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write trigger command to CH101\n");
        return -1;
    }
    gpioDelay(MEASURE_DELAY_US);

