    if (bytes != 2) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 2)\n", bytes);
        return -1;
    }

    *distance_mm = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    return 0;
}

static int log_data(FILE *fp, const char *timestamp, int distance_mm) {
    if (fprintf(fp, "%s, %d\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, CH101_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at bus %d addr 0x%02X (pigpio error %d)\n",
                I2C_BUS, CH101_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("CH101 distance measurement started. Press Ctrl-C to stop.\n");

    while (running) {
        int distance_mm = 0;
        if (read_distance(i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "Warning: I2C read failed, skipping sample\n");
        } else {
            char timestamp[32];
            if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
                fprintf(stderr, "Warning: failed to generate timestamp\n");
            } else {
                if (log_data(log_file, timestamp, distance_mm) != 0) {
                    fprintf(stderr, "Warning: failed to log data\n");
                }
                printf("%s, %d mm\n", timestamp, distance_mm);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

