#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROXIMITY_REG 0x18
#define AMBIENT_REG 0x16
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteByte(handle, reg) < 0) {
            retries++;
            gpioDelay(1000);
            continue;
        }
        if (i2cReadDevice(handle, buf, 2) == 2) {
            *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        retries++;
        gpioDelay(1000);
    }
    return -1;
}

static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, Proximity: %u, Ambient: %u\n", timestamp, proximity, ambient);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1182-GMR proximity sensor logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t proximity = 0, ambient = 0;

        if (read_register(i2c_handle, PROXIMITY_REG, &proximity) < 0) {
            fprintf(stderr, "Error reading proximity data after %d retries\n", MAX_RETRIES);
        } else if (read_register(i2c_handle, AMBIENT_REG, &ambient) < 0) {
            fprintf(stderr, "Error reading ambient data after %d retries\n", MAX_RETRIES);
        } else {
            log_data(log_file, proximity, ambient);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nCleaning up...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

