#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define LED_GPIO 17
#define WHO_AM_I_REG 0x01
#define WHO_AM_I_VAL 0x01
#define DISTANCE_REG 0x10
#define LOG_FILE "tof_log.txt"
#define POLL_DELAY_US 50000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_who_am_i(int handle) {
    int val = i2cReadByteData(handle, WHO_AM_I_REG);
    if (val < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", val);
        return -1;
    }
    if (val != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", val, WHO_AM_I_VAL);
        return -1;
    }
    return 0;
}

static int read_distance(int handle, int *distance) {
    int raw = i2cReadWordData(handle, DISTANCE_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading distance register: %d\n", raw);
        return -1;
    }
    *distance = raw;
    return 0;
}

static void log_data(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %d mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <distance_threshold_mm>\n", argv[0]);
        return 1;
    }

    int threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Threshold must be a positive integer.\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_who_am_i(i2c_handle) != 0) {
        fprintf(stderr, "Sensor not detected or communication error.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    while (running) {
        int distance;
        if (read_distance(i2c_handle, &distance) == 0) {
            log_data(distance);
            if (distance < threshold) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read distance. Continuing...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

