#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define B5L_ADDRESS 0x50
#define LOG_FILE "intrusion_log.txt"
#define SAMPLE_INTERVAL_MS 100
#define MEASUREMENT_DELAY_MS 10
#define INTRUSION_THRESHOLD_MM 1000
#define SAMPLES_PER_CYCLE 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(int fd, uint16_t *distance_mm) {
    uint8_t cmd[4] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t resp[15];

    if (i2c_write_cmd(fd, cmd, sizeof(cmd)) != 0) {
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000);

    if (i2c_read_data(fd, resp, sizeof(resp)) != 0) {
        return -1;
    }

    if (resp[0] != 0x50) {
