#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L0X_ADDR   0x29
#define REG_MODEL_ID   0xC0
#define EXPECTED_ID    0xEE
#define REG_SYSRANGE   0x00
#define REG_INT_STATUS 0x13
#define REG_RANGE      0x14
#define REG_INT_CLEAR  0x0B
#define POLL_TIMEOUT_MS 100
#define LOOP_DELAY_US  500000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16_le(int handle, uint8_t reg, uint16_t *val) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, rc=%d): %s\n", reg, rc, strerror(errno));
        return -1;
    }
    *val = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

static int init_vl53l0x(int handle) {
    uint8_t id = 0;
    if (i2c_read_reg8(handle, REG_MODEL_ID, &id) != 0) {
        fprintf(stderr, "Cannot read model ID - sensor may be absent or bus error\n");
        return -1;
    }
    if (id != EXPECTED_ID) {
        fprintf(stderr, "Unexpected model ID 0x%02X (expected 0x%02X) - wrong sensor?\n", id, EXPECTED_ID);
        return -1;
    }
    printf("VL53L0X detected (model ID 0x%02X)\n", id);
    return 0;
}

static int read_distance(int handle, uint16_t *distance_mm) {
    if (i2c_write_reg8(handle, REG_SYSRANGE, 0x01) != 0)
        return -1;

    uint32_t elapsed = 0;
    while (elapsed < (POLL_TIMEOUT_MS * 1000)) {
        uint8_t status = 0;
        if (i2c_read_reg8(handle, REG_INT_STATUS, &status) != 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000);
        elapsed += 1000;
    }

    if (elapsed >= (POLL_TIMEOUT_MS * 1000)) {
        fprintf(stderr, "Timeout waiting for VL53L0X measurement\n");
        return -1;
    }

    if (i2c_read_reg16_le(handle, REG_RANGE, distance_mm) != 0)
        return -1;

    if (i2c_write_reg8(handle, REG_INT_CLEAR, 0x01) != 0)
        return -1;

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n", I2C_BUS, VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_vl53l0x(handle) != 0) {
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting periodic distance readings (Ctrl+C to stop)...\n");

    while (g_running) {
        uint16_t distance = 0;
        if (read_distance(handle, &distance) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            localtime_r(&now, &tm_info);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            printf("%s Distance: %u mm\n", ts, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: distance read failed, retrying next cycle\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

