#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1182_ADDR        0x39
#define SI1182_REG_CONFIG  0x18
#define SI1182_REG_IRQ     0x25
#define SI1182_REG_LSB     0x2A
#define SI1182_REG_MSB     0x2B
#define SI1182_IRQ_DRDY    0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

static int read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

static int read_proximity(int handle, uint16_t *prox)
{
    uint8_t irq;
    int attempts = 0;

    while (attempts < 10) {
        if (read_reg(handle, SI1182_REG_IRQ, &irq) < 0)
            return -1;
        if (irq & SI1182_IRQ_DRDY)
            break;
        gpioDelay(1000); /* 1 ms */
        attempts++;
    }

    if (attempts >= 10) {
        fprintf(stderr, "Sensor not ready after 10 ms\n");
        return -1;
    }

    uint8_t lsb, msb;
    if (read_reg(handle, SI1182_REG_LSB, &lsb) < 0)
        return -1;
    if (read_reg(handle, SI1182_REG_MSB, &msb) < 0)
        return -1;

    *prox = ((uint16_t)msb << 8) | lsb;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Probe: try a zero-length write to confirm the sensor is present */
    if (i2cWriteByte(g_i2c_handle, 0x00) < 0) {
        fprintf(stderr, "Si1182 not detected at 0x%02X\n", SI1182_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_reg(g_i2c_handle, SI1182_REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Failed to configure Si1182\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1182 proximity reader started (addr 0x%02X). Press Ctrl+C to exit.\n",
           SI1182_ADDR);

    while (g_running) {
        uint16_t prox;
        if (read_proximity(g_i2c_handle, &prox) == 0) {
            printf("Proximity: %u\n", prox);
        } else {
            fprintf(stderr, "Read error; continuing\n");
        }
        gpioDelay(500000); /* 500 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

