#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define OPT3101_ADDR 0x44
#define I2C_BUS 1

#define REG_CH0_CONFIG 0x00
#define REG_CH0_RESULT 0x04
#define REG_AMBIENT_LIGHT 0x08
#define REG_ERROR_FLAGS 0x0A

#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int read_distance(int handle, uint8_t *distance) {
    return read_register(handle, REG_CH0_RESULT, distance);
}

int read_ambient_light(int handle, uint8_t *ambient_light) {
    return read_register(handle, REG_AMBIENT_LIGHT, ambient_light);
}

int read_error_flags(int handle, uint8_t *error_flags) {
    return read_register(handle, REG_ERROR_FLAGS, error_flags);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n", OPT3101_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t distance, ambient_light, error_flags;

    while (running) {
        if (read_distance(i2c_handle, &distance) == 0) {
            if (read_ambient_light(i2c_handle, &ambient_light) == 0) {
                if (read_error_flags(i2c_handle, &error_flags) == 0) {
                    time_t rawtime;
                    struct tm *timeinfo;
                    char timestamp[80];

                    time(&rawtime);
                    timeinfo = localtime(&rawtime);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                    printf("%s - Distance: %u mm, Ambient Light: %u, Error Flags: 0x%02X\n",
                           timestamp, distance, ambient_light, error_flags);
                } else {
                    fprintf(stderr, "Error reading error flags\n");
                }
            } else {
                fprintf(stderr, "Error reading ambient light\n");
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nProgram terminated gracefully.\n");
    return 0;
}

