/*
 * HC-SR04 Ultrasonic Distance Sensor Reader for Raspberry Pi 3 Model B+
 * Library: pigpio (modern, actively maintained)
 *
 * Wiring:
 *   HC-SR04 VCC -> 5V (Pin 2 or 4)
 *   HC-SR04 GND -> GND (Pin 6)
 *   HC-SR04 TRIG -> GPIO 17 (BCM)
 *   HC-SR04 ECHO -> GPIO 18 (BCM) with 1 kOhm series resistor for 5V->3.3V
 *
 * NOTE: The HC-SR04 is rated for 5V logic.  The Pi GPIO is 3.3V tolerant.
 *       Using 5V VCC on the sensor pin may damage the Pi.  The 1 kOhm
 *       series resistor provides a safe level shift.
 *
 * Build:  gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse            */
#define ECHO_TIMEOUT_US  200000      /* 200 ms max echo wait           */
#define SAMPLE_PERIOD_S  1           /* Log once per second            */
#define MAX_DISTANCE_CM  38.0        /* HC-SR04 rated max range (cm)   */

/* Speed of sound at 20 °C: 343 m/s = 0.0343 cm/us */
#define SOUND_SPEED_CM_PER_US 0.0343

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Wait for the echo pin to reach the requested level, with timeout.   */
/* Returns true on success, false on timeout/error.                    */
/* ------------------------------------------------------------------ */
static bool wait_for_level(int pin, int level, uint32_t timeout_us)
{
    uint32_t start_tick = gpioTick();
    uint32_t elapsed;

    while (gpioRead(pin) != level) {
        elapsed = gpioTick() - start_tick;
        if (elapsed >= timeout_us) {
            return false;          /* timeout */
        }
    }
    return true;
}

/* ------------------------------------------------------------------ */
/* Read distance in cm.  Returns -1.0 on error/timeout.                */
/* ------------------------------------------------------------------ */
static float read_distance(void)
{
    uint32_t start_tick, end_tick;
    uint32_t pulse_us;

    /* --- Issue 10 us trigger pulse --- */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER low\n");
        return -1.0f;
    }

    /* --- Wait for echo rising edge (response) --- */
    if (!wait_for_level(ECHO_PIN, 1, ECHO_TIMEOUT_US)) {
        fprintf(stderr, "Error: echo rising edge timeout (sensor absent or wiring fault)\n");
        return -1.0f;
    }
    start_tick = gpioTick();

    /* --- Wait for echo falling edge (echo complete) --- */
    if (!wait_for_level(ECHO_PIN, 0, ECHO_TIMEOUT_US)) {
        fprintf(stderr, "Error: echo falling edge timeout (pulse too long)\n");
        return -1.0f;
    }
    end_tick = gpioTick();

    pulse_us = end_tick - start_tick;

    /* --- Validate pulse duration --- */
    if (pulse_us <= 0 || pulse_us > ECHO_TIMEOUT_US) {
        fprintf(stderr, "Error: invalid pulse duration %u us\n", pulse_us);
        return -1.0f;
    }

    /* distance = (pulse_us * speed_of_sound) / 2 */
    return (float)pulse_us * SOUND_SPEED_CM_PER_US / 2.0f;
}

/* ------------------------------------------------------------------ */
/* Log a reading with a human-readable timestamp.                      */
/* ------------------------------------------------------------------ */
static void log_reading(float distance_cm)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }

    if (distance_cm < 0.0f) {
        printf("[%s] Error: sensor read failed\n", ts);
    } else if (distance_cm > MAX_DISTANCE_CM) {
        printf("[%s] Warning: distance %.2f cm exceeds max %.1f cm (out of range)\n",
               ts, distance_cm, MAX_DISTANCE_CM);
    } else {
        printf("[%s] Distance: %.2f cm\n", ts, distance_cm);
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (run as root?)\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize TRIGGER_PIN low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle after power-up */
    gpioDelay(50000);  /* 50 ms */

    printf("HC-SR04 distance sensor ready.\n");
    printf("  Trigger: GPIO %d | Echo: GPIO %d\n", TRIGGER_PIN, ECHO_PIN);
    printf("  Sampling every %d second(s).  Press Ctrl+C to exit.\n\n", SAMPLE_PERIOD_S);
    fflush(stdout);

    /* --- Main sampling loop --- */
    while (g_running) {
        float distance = read_distance();
        log_reading(distance);
        sleep(SAMPLE_PERIOD_S);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

