#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define RANGE_PROFILE_SIZE 64
#define RANGE_RESOLUTION 0.0486f
#define DISTANCE_THRESHOLD 1.0f
#define ALERT_DURATION_MS 2000
#define LOG_FILE "intrusion_log.csv"

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_radar_data(int fd, float *range_profile) {
    uint8_t header[8] = {0};
    ssize_t bytes_read;

    bytes_read = read(fd, header, sizeof(header));
    if (bytes_read != (ssize_t)sizeof(header)) {
        if (bytes_read < 0) perror("Error reading header");
        return -1;
    }

    if (header[0] != 0x02 || header[1] != 0x01 || header[2] != 0x04 || header[3] != 0x03 ||
        header[4] != 0x06 || header[5] != 0x05 || header[6] != 0x08 || header[7] != 0x07) {
        fprintf(stderr, "Invalid magic word received\n");
        return -1;
    }

    uint8_t data[128];
    bytes_read = read(fd, data, sizeof(data));
    if (bytes_read != (ssize_t)sizeof(data)) {
        if (bytes_read < 0) perror("Error reading data");
        return -1;
    }

    for (int i = 0; i < RANGE_PROFILE_SIZE; i++) {
        range_profile[i] = (float)((int16_t)((data[2 * i] << 8) | data[2 * i + 1])) * RANGE_RESOLUTION;
    }
    return 0;
}

static float detect_intrusion(const float *range_profile) {
    for (int i = 0; i < RANGE_PROFILE_SIZE; i++) {
        if (range_profile[i] > 0.0f && range_profile[i] < DISTANCE_THRESHOLD) {
            return range_profile[i];
        }
    }
    return -1.0f;
}

static void trigger_alert(int gpio_pin) {
    gpioWrite(gpio_pin, 1);
    gpioDelay(ALERT_DURATION_MS * 1000);
    gpioWrite(gpio_pin, 0);
}

static void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    float range_profile[RANGE_PROFILE_SIZE];
    float distance;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance_m\n");
        fflush(log_file);
    }

    printf("Radar intrusion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_radar_data(uart_fd, range_profile) == 0) {
            distance = detect_intrusion(range_profile);
            if (distance > 0.0f) {
                printf("Intrusion detected at %.2f meters!\n", distance);
                trigger_alert(GPIO_LED);
                log_intrusion(distance);
            }
        } else {
            fprintf(stderr, "Error reading radar data. Retrying...\n");
        }
        gpioDelay(100000);
    }

    printf("\nCleaning up...\n");
    if (uart_fd >= 0) close(uart_fd);
    if (log_file != NULL) fclose(log_file);
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();

    return 0;
}

