/*
 * TDK Chirp ICU-20201 Ultrasonic ToF Sensor - Distance Logger
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (I2C + GPIO)
 * Sensor:  TDK Chirp ICU-20201 on I2C bus 1, address 0x69
 * Log:     distance_log.txt (ISO 8601 timestamps)
 * Alert:   BCM 17 (physical pin 17) on LOW when distance < 10.0 cm
 *
 * Build:  gcc -O2 -Wall -o chirp_logger chirp_logger.c -lpigpio -lrt
 * Run:    sudo ./chirp_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x69          /* Chirp ICU-20201 default address   */
#define DISTANCE_REG_HIGH    0x31          /* 16-bit distance, high byte        */
#define DISTANCE_REG_LOW     0x32          /* 16-bit distance, low byte         */
#define ALERT_GPIO           17            /* BCM 17 - physical pin 17          */
#define DISTANCE_THRESHOLD   10.0f         /* cm                               */
#define SAMPLE_PERIOD_US     100000        /* 100 ms                            */
#define LOG_FILE             "distance_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Function prototypes ------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  read_distance(float *distance_out);
static int  log_distance(float distance);
static void trigger_alert(float distance);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C init --------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/* --------------------------- Read distance -------------------------------- */
static int read_distance(float *distance_out)
{
    int hi = i2cReadByteData(g_i2c_handle, DISTANCE_REG_HIGH);
    if (hi < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg 0x%02X) failed: %d\n",
                DISTANCE_REG_HIGH, hi);
        return -1;
    }

    int lo = i2cReadByteData(g_i2c_handle, DISTANCE_REG_LOW);
    if (lo < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg 0x%02X) failed: %d\n",
                DISTANCE_REG_LOW, lo);
        return -1;
    }

    uint16_t raw = ((uint16_t)(hi & 0xFF) << 8) | (uint16_t)(lo & 0xFF);
    *distance_out = (float)raw / 10.0f;   /* cm */
    return 0;
}

/* ------------------------------- Log entry -------------------------------- */
static int log_distance(float distance)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed\n");
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, Distance: %.2f cm\n", ts, distance) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[WARN] fflush() failed on log file\n");
        return -1;
    }

    return 0;
}

/* ------------------------------- Alert GPIO ------------------------------- */
static void trigger_alert(float distance)
{
    if (distance < DISTANCE_THRESHOLD) {
        if (gpioWrite(ALERT_GPIO, 0) != 0) {
            fprintf(stderr, "[WARN] gpioWrite(LOW) on alert pin failed\n");
        }
        printf("[ALERT] Distance %.2f cm < %.1f cm - alert triggered\n",
               distance, DISTANCE_THRESHOLD);
    } else {
        if (gpioWrite(ALERT_GPIO, 1) != 0) {
            fprintf(stderr, "[WARN] gpioWrite(HIGH) on alert pin failed\n");
        }
    }
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------------- main ----------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C --- */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Alert GPIO --- */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, OUTPUT) failed\n", ALERT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(ALERT_GPIO, 1) != 0) {   /* ensure alert is OFF at start */
        fprintf(stderr, "[WARN] Initial gpioWrite(HIGH) on alert pin failed\n");
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction() failed; Ctrl-C will not shut down cleanly\n");
    }

    printf("Chirp ICU-20201 distance logger started.\n");
    printf("  I2C bus : %d  addr : 0x%02X\n", I2C_BUS, I2C_ADDR);
    printf("  Log file: %s  alert: BCM %d (threshold %.1f cm)\n",
           LOG_FILE, ALERT_GPIO, DISTANCE_THRESHOLD);
    printf("Press Ctrl-C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        float distance;

        if (read_distance(&distance) != 0) {
            fprintf(stderr, "[WARN] I2C read failed - will retry next cycle\n");
        } else {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "[WARN] Log write failed\n");
            }
            trigger_alert(distance);
        }

        gpioDelay(SAMPLE_PERIOD_US);   /* 100 ms */
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    gpioWrite(ALERT_GPIO, 1);          /* turn alert off */
    cleanup();
    return EXIT_SUCCESS;
}

