#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define LOG_FILE       "distance_log.csv"
#define POLL_TIMEOUT_MS 100
#define LOOP_DELAY_MS  100

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define REG_SOFT_RESET              0x0000
#define REG_MODEL_ID                0x010F
#define REG_SYSRANGE_START          0x007
#define REG_RESULT_INTERRUPT_STATUS 0x013
#define REG_RESULT_RANGE_STATUS     0x078
#define REG_SYSTEM_INTERRUPT_CLEAR  0x014
#define REG_SYSTEM_MODE_START       0x007

#define EXPECTED_MODEL_ID 0xEA

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address followed by a single data byte */
static int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read a single byte from a 16-bit register address */
static int vl53l1x_read_byte(int handle, uint16_t reg, uint8_t *value)
{
    char addr[2];
    char data;
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, &data, 1) != 1)
        return -1;
    *value = (uint8_t)data;
    return 0;
}

/* Read a 16-bit big-endian value from a 16-bit register address */
static int vl53l1x_read_word(int handle, uint16_t reg, uint16_t *value)
{
    char addr[2];
    char data[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;

    /* Verify sensor presence */
    if (vl53l1x_read_byte(handle, REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: failed to read model ID register\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    /* Software reset */
    if (vl53l1x_write_byte(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write soft reset\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms */

    /* Start continuous back-to-back ranging */
    if (vl53l1x_write_byte(handle, REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start ranging\n");
        return -1;
    }

    /* Poll SYSRANGE__START bit 0 until self-clears (max ~100 ms) */
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        uint8_t status = 0;
        if (vl53l1x_read_byte(handle, REG_SYSRANGE_START, &status) < 0) {
            fprintf(stderr, "Error: failed to poll SYSRANGE__START\n");
            return -1;
        }
        if ((status & 0x01) == 0)
            return 0;
        gpioDelay(1000); /* 1 ms */
    }
    fprintf(stderr, "Error: ranging startup timeout\n");
    return -1;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;

    /* Poll data-ready bit 0 of RESULT__INTERRUPT_STATUS */
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (vl53l1x_read_byte(handle, REG_RESULT_INTERRUPT_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "Warning: data-ready timeout\n");
        return -1;
    }

    /* Read 16-bit distance from RESULT__RANGE_STATUS + 10 (big-endian) */
    uint16_t raw = 0;
    if (vl53l1x_read_word(handle, REG_RESULT_RANGE_STATUS, &raw) < 0)
        return -1;

    /* Clear interrupt to allow next measurement */
    if (vl53l1x_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    *distance_mm = raw;
    return 0;
}

static void log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u\n",
