/*
 * CH201 Ultrasonic ToF Distance Sensor - LED Blink Frequency
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (I2C + GPIO)
 *
 * Wiring:
 *   CH201 SDA -> GPIO 2  (I2C bus 1 SDA)
 *   CH201 SCL -> GPIO 3  (I2C bus 1 SCL)
 *   CH201 VDD -> 3.3 V
 *   CH201 GND -> GND
 *   LED anode -> GPIO 18 (via 330 ohm resistor) -> GND
 *
 * Build:  gcc -Wall -Wextra -O2 -o ch201_blink ch201_blink.c -lpigpio -lrt
 * Run:    sudo ./ch201_blink
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define CH201_I2C_ADDR       0x45          /* CH201 default 7-bit address     */
#define LED_GPIO             18            /* GPIO 18 - hardware PWM capable  */
#define SAMPLE_PERIOD_US     100000        /* 100 ms between samples          */
#define BLINK_HALF_CYCLE_US  100000        /* 100 ms half-cycle (1 Hz blink)  */
#define MAX_RETRIES          3
#define RETRY_DELAY_US       10000         /* 10 ms between retries           */

/* CH201 register addresses (16-bit, big-endian on the bus) */
#define REG_CHIP_ID          0x00
#define REG_DISTANCE         0x04
#define REG_CONFIG           0x0A
#define REG_RANGE_START      0x0B
#define REG_RANGE_STATUS     0x0C

#define EXPECTED_CHIP_ID     0x01          /* CH201 returns 0x01 on CH201     */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal Handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ I2C Helpers ------------------------------ */
/*
 * Write a 16-bit register address + 16-bit data pair to the CH201.
 * pigpio's i2cWriteI2CBlockData sends the register address followed by the
 * data payload, which matches the CH201's 16-bit register addressing.
 */
static int ch201_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    uint8_t buf[4];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = (uint8_t)(value >> 8);
    buf[3] = (uint8_t)(value & 0xFF);

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteI2CBlockData(handle, buf[0], (char *)&buf[2], 2);
        if (rc == 2)
            return 0;
        fprintf(stderr, "I2C write reg 0x%04X failed (attempt %d/%d): rc=%d\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/*
 * Read a 16-bit register from the CH201.
 * The CH201 returns 2 bytes when the register address is written, then
 * the data is read back.
 */
static int ch201_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteByte(handle, (uint8_t)(reg >> 8));
        if (rc < 0) {
            fprintf(stderr, "I2C write reg-addr 0x%04X failed (attempt %d/%d): rc=%d\n",
                    reg, attempt + 1, MAX_RETRIES, rc);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        rc = i2cReadDevice(handle, (char *)out, 2);
        if (rc == 2)
            return 0;

        fprintf(stderr, "I2C read reg 0x%04X failed (attempt %d/%d): rc=%d\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/*
 * Initialise the CH201: verify chip ID, then start a single-shot range
 * measurement and wait for completion.
 */
static int ch201_init(int handle)
{
    uint16_t chip_id = 0;

    if (ch201_read_reg16(handle, REG_CHIP_ID, &chip_id) != 0) {
        fprintf(stderr, "CH201 not responding on I2C bus %d addr 0x%02X\n",
                I2C_BUS, CH201_I2C_ADDR);
        return -1;
    }

    if (chip_id != EXPECTED_CHIP_ID) {
        fprintf(stderr, "Unexpected CHIP_ID: 0x%04X (expected 0x%04X)\n",
                chip_id, EXPECTED_CHIP_ID);
        return -1;
    }

    /* Start a single-shot measurement */
    if (ch201_write_reg16(handle, REG_RANGE_START, 0x0001) != 0) {
        fprintf(stderr, "Failed to start range measurement\n");
        return -1;
    }

    /* Poll RANGE_STATUS until bit 0 (RANGE_READY) is set */
    for (int i = 0; i < 100; ++i) {
        uint16_t status = 0;
        if (ch201_read_reg16(handle, REG_RANGE_STATUS, &status) != 0) {
            fprintf(stderr, "Failed to read RANGE_STATUS\n");
            return -1;
        }
        if (status & 0x0001)
            return 0;
        gpioDelay(1000); /* 1 ms */
    }

    fprintf(stderr, "Timeout waiting for CH201 range measurement\n");
    return -1;
}

/*
 * Read the latest distance in millimetres.
 * Returns 0 on success, -1 on persistent failure.
 */
static int ch201_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t status = 0;

    if (ch201_read_reg16(handle, REG_RANGE_STATUS, &status) != 0)
        return -1;

    if (!(status & 0x0001)) {
        /* Measurement not ready yet */
        return -1;
    }

    if (ch201_read_reg16(handle, REG_DISTANCE, distance_mm) != 0)
        return -1;

    return 0;
}

/* ------------------------------- Blink ----------------------------------- */
static void set_led_frequency(int frequency_hz)
{
    if (frequency_hz <= 0) {
        gpioWrite(LED_GPIO, 0);
        return;
    }

    /* 1 / (2 * period) = frequency; period in seconds */
    double period_s = 1.0 / (2.0 * frequency_hz);
    uint32_t half_period_us = (uint32_t)(period_s * 1e6);

    if (half_period_us < BLINK_HALF_CYCLE_US) {
        gpioWrite(LED_GPIO, 1);
        gpioDelay(half_period_us);
        gpioWrite(LED_GPIO, 0);
        gpioDelay(BLINK_HALF_CYCLE_US - half_period_us);
    } else {
        /* Frequency too high for 100 ms half-cycle; just turn LED on */
        gpioWrite(LED_GPIO, 1);
        gpioDelay(BLINK_HALF_CYCLE_US);
        gpioWrite(LED_GPIO, 0);
    }
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, CH201_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed on bus %d addr 0x%02X: %d\n",
                I2C_BUS, CH201_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (ch201_init(g_i2c_handle) != 0) {
        fprintf(stderr, "CH201 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* --- Signals --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance sensor running.  Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (ch201_read_distance(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "Distance read failed; retrying next cycle\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Map distance to blink frequency: 50mm -> 10Hz, 500mm -> 1Hz */
        int frequency_hz = 10;
        if (distance_mm >= 500) frequency_hz = 1;
        else if (distance_mm >= 50) frequency_hz = 10 - (int)((distance_mm - 50) * 9 / 450);

        set_led_frequency(frequency_hz);

        /* Timestamped log */
        time_t now = time(NULL);
        struct tm tm_info;
        localtime_r(&now, &tm_info);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("%s  Distance: %u mm  Blink: %d Hz\n", ts, distance_mm, frequency_hz);
        fflush(stdout);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

