#define MLX75030_ADDR 0x5A
#define LOG_FILE "distance_log.csv"
#define SAMPLE_INTERVAL_US 100000
#define MEASURE_DELAY_US 50000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n",
                MLX75030_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int trigger_measurement(void) {
    /* Write a dummy byte to trigger a measurement */
    char cmd = 0x00;
    int rc = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (trigger): %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance_cm) {
    char buf[2];
    int rc = i2cReadDevice(i2c_handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "I2C read short: got %d bytes, expected 2\n", rc);
        return -1;
    }
    *distance_cm = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int log_data(uint16_t distance_cm) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s,%u\n", timestamp, distance_cm) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,distance_cm\n");
        fflush(log_file);
    }

    printf("Starting distance logging to %s (Ctrl+C to stop)\n", LOG_FILE);

    while (!terminate) {
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !terminate) {
            if (trigger_measurement() == 0) {
                gpioDelay(MEASURE_DELAY_US);
                uint16_t distance_cm = 0;
                if (read_distance(&distance_cm) == 0) {
                    if (log_data(distance_cm) == 0) {
                        success = 1;
                        break;
                    }
                }
            }
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(RETRY_DELAY_US);
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

