/*
 * CH-101 ToF sensor reader for Raspberry Pi 5 (i2c-dev kernel interface)
 * Bus: /dev/i2c-1   Address: 0x49   Log: distance_log.csv
 *
 * Build:  gcc -O2 -Wall -Wextra -o ch101_reader ch101_reader.c
 * Run:    ./ch101_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x49

/* CH-101 register map (16-bit addresses, big-endian on the wire) */
#define REG_MEAS_TRIGGER  0x04
#define REG_MEAS_STATUS   0x06
#define REG_DIST_HIGH     0x08
#define REG_DIST_LOW      0x09

#define MEAS_TRIGGER_SINGLE  0x01
#define MEAS_STATUS_READY    0x01

#define LOG_FILE        "distance_log.csv"
#define SAMPLE_PERIOD_US 500000   /* 500 ms between samples */
#define MEAS_TIMEOUT_MS  50

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Write a 16-bit value to a 16-bit-addressed register (big-endian on wire). */
static int i2c_write_reg16(int fd, uint8_t reg_hi, uint8_t reg_lo, uint16_t val)
{
    uint8_t buf[4];
    buf[0] = reg_hi;
    buf[1] = reg_lo;
    buf[2] = (uint8_t)(val >> 8);
    buf[3] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, 4) != 4) {
        fprintf(stderr, "i2c_write_reg16(0x%02X%02X) failed: %s\n",
                reg_hi, reg_lo, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from a 16-bit-addressed register (big-endian on wire). */
static int i2c_read_reg16(int fd, uint8_t reg_hi, uint8_t reg_lo, uint16_t *out)
{
    uint8_t reg[2] = { reg_hi, reg_lo };
    uint8_t data[2];

    if (write(fd, reg, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: write addr 0x%02X%02X failed: %s\n",
                reg_hi, reg_lo, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: read from 0x%02X%02X failed: %s\n",
                reg_hi, reg_lo, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* Trigger a single measurement and wait for completion. */
static int ch101_trigger_and_wait(int fd)
{
    if (i2c_write_reg16(fd, REG_MEAS_TRIGGER >> 8, REG_MEAS_TRIGGER & 0xFF,
                        MEAS_TRIGGER_SINGLE) != 0)
        return -1;

    for (int elapsed = 0; elapsed < MEAS_TIMEOUT_MS; elapsed += 5) {
        uint16_t status = 0;
        if (i2c_read_reg16(fd, REG_MEAS_STATUS >> 8, REG_MEAS_STATUS & 0xFF,
                           &status) != 0)
            return -1;
        if (status & MEAS_STATUS_READY)
            return 0;
        usleep(5000);
    }

    fprintf(stderr, "CH-101 measurement timeout after %d ms\n", MEAS_TIMEOUT_MS);
    return -1;
}

/* Read distance in millimetres. Returns -1 on error. */
static int ch101_read_distance(int fd)
{
    if (ch101_trigger_and_wait(fd) != 0)
        return -1;

    uint16_t high = 0, low = 0;
    if (i2c_read_reg16(fd, REG_DIST_HIGH >> 8, REG_DIST_HIGH & 0xFF, &high) != 0)
        return -1;
    if (i2c_read_reg16(fd, REG_DIST_LOW >> 8, REG_DIST_LOW & 0xFF, &low) != 0)
        return -1;

    return (int)((high << 8) | low);
}

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    if (localtime_r(&t, &tmv) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
    else
        snprintf(buf, len, "1970-01-01T00:00:00");
}

int main(void)
{
    int fd = -1;
    FILE *log = NULL;
    int rc = EXIT_FAILURE;

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                CH101_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Open log file */
    log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write CSV header if file is empty */
    if (ftell(log) == 0)
        fprintf(log, "timestamp,distance_mm\n");

    printf("CH-101 parking sensor started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        int distance = ch101_read_distance(fd);
        if (distance >= 0) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            fprintf(log, "%s,%d\n", ts, distance);
            fflush(log);
            printf("%s  distance: %d mm\n", ts, distance);
        } else {
            fprintf(stderr, "Read error; skipping sample.\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (log) {
        fflush(log);
        fclose(log);
    }
    if (fd >= 0)
        close(fd);
    return rc;
}

