#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

static int initialize(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d (pigpio error %d).\n",
                MLX75030_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_distance(uint16_t *distance) {
    char buf[2];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
        if (bytes_read == 2) {
            *distance = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }

        fprintf(stderr, "Warning: I2C read failed (pigpio returned %d). Retries left: %d\n",
                bytes_read, retries - 1);
        retries--;
        if (retries > 0) {
            gpioDelay(RETRY_DELAY_MS * 1000);
        }
    }

    fprintf(stderr, "Error: Failed to read distance after %d retries.\n", RETRY_COUNT);
    return -1;
}

static void log_distance(uint16_t distance) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long milliseconds = ts.tv_nsec / 1000000;

    printf("[%s.%03ld] Distance: %u mm\n", timestamp, milliseconds, distance);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("MLX75030 ToF sensor initialized on I2C bus %d at address 0x%02X.\n",
           I2C_BUS, MLX75030_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance = 0;

        if (read_distance(&distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Error: Sensor read failed. Check wiring and sensor presence.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

