#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* VL53L4CX I2C default address */
#define VL53L4CX_ADDR 0x29

/* VL53L4CX register addresses (16-bit, big-endian on bus) */
#define VL53L4CX_REG_SOFT_RESET       0x7FFF
#define VL53L4CX_REG_SYSTEM_START     0x0009
#define VL53L4CX_REG_INT_STATUS       0x0046
#define VL53L4CX_REG_DISTANCE_H       0x0096
#define VL53L4CX_REG_DISTANCE_L       0x0097

#define I2C_BUS 1
#define POLL_INTERVAL_US 500000  /* 500 ms */
#define RESET_DELAY_US   10000   /* 10 ms after reset */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C / SIGTERM)            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address + 1 byte value to the sensor        */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int vl53l4cx_write_reg(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error: i2cWriteDevice failed for reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register address + 1 byte from the sensor             */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read_reg(int handle, uint16_t reg, uint8_t *value)
{
    char addr_buf[2];
    char data_buf[1];

    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr_buf, 2) != 2) {
        fprintf(stderr, "Error: i2cWriteDevice (addr) failed for reg 0x%04X\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error: i2cReadDevice failed for reg 0x%04X\n", reg);
        return -1;
    }

    *value = (uint8_t)data_buf[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the VL53L4CX sensor: soft reset, then start ranging      */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int vl53l4cx_init(int handle)
{
    /* Soft reset: write 0x00 to register 0x7FFF */
    if (vl53l4cx_write_reg(handle, VL53L4CX_REG_SOFT_RESET, 0x00) != 0)
        return -1;

    gpioDelay(RESET_DELAY_US);

    /* Start ranging: write 0x00 to register 0x0009 */
    if (vl53l4cx_write_reg(handle, VL53L4CX_REG_SYSTEM_START, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit distance value from the sensor                     */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read_distance(int handle, uint16_t *distance)
{
    uint8_t hi, lo;

    if (vl53l4cx_read_reg(handle, VL53L4CX_REG_DISTANCE_H, &hi) != 0)
        return -1;
    if (vl53l4cx_read_reg(handle, VL53L4CX_REG_DISTANCE_L, &lo) != 0)
