static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C / SIGTERM)            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address + 1 byte value to the sensor        */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int vl53l4cx_write_reg(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error: i2cWriteDevice failed for reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
