/*
 * VL53L1X time-of-flight sensor reader with buzzer alert.
 *
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern API, no wiringPi)
 * Sensor:  VL53L1X on I2C bus 1, address 0x29
 * Buzzer:  Active buzzer on GPIO 22 (active-high)
 *
 * Build:  gcc -O2 -Wall -o vl53l1x_buzzer vl53l1x_buzzer.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_buzzer
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define BUZZER_GPIO          22
#define DISTANCE_THRESHOLD   100          /* mm */
#define POLL_INTERVAL_US     500000       /* 500 ms */
#define BUZZER_ON_US         100000       /* 100 ms */
#define BUZZER_OFF_US        100000       /* 100 ms */

/* VL53L1X 16-bit register addresses (big-endian on the bus) */
#define REG_SOFT_RESET                 0x0001
#define REG_I2C_SLAVE_DEVICE_ADDRESS   0x0001
#define REG_SYSTEM_MODE_START          0x0007
#define REG_RESULT_FINAL_DISTANCE_MM   0x0096

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers --------------------------------- */
/*
 * Write a 16-bit register address followed by a single byte value.
 * pigpio's i2cWriteI2CBlockData sends the data payload after the address,
 * so we prepend the 16-bit register address as a 2-byte big-endian block.
 */
static int vl53l1x_write8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (char)((reg >> 8) & 0xFF);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)value;

    if (i2cWriteI2CBlockData(handle, buf[0], &buf[1], 2) < 0)
        return -1;
    return 0;
}

/*
 * Read a 16-bit register: write the register address, then read 2 bytes.
 * pigpio returns the number of bytes read, or < 0 on error.
 */
static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *out)
{
    char addr[2];
    char data[2];

    addr[0] = (char)((reg >> 8) & 0xFF);
    addr[1] = (char)(reg & 0xFF);

    if (i2cWriteI2CBlockData(handle, addr[0], &addr[1], 1) < 0)
        return -1;

    if (i2cReadI2CBlockData(handle, addr[0], data, 2) != 2)
        return -1;

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* --------------------------- Sensor init --------------------------------- */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (vl53l1x_write8(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write soft reset\n");
        return -1;
    }
    gpioDelay(2000);  /* 2 ms settle */

    /* Re-assert reset */
    if (vl53l1x_write8(handle, REG_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: failed to re-assert soft reset\n");
        return -1;
    }
    gpioDelay(2000);  /* 2 ms settle */

    /* Set I2C slave address (0x29) */
    if (vl53l1x_write8(handle, REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Error: failed to set I2C slave address\n");
        return -1;
    }

    /* Start continuous ranging mode */
    if (vl53l1x_write8(handle, REG_SYSTEM_MODE_START, 0x40) < 0) {
        fprintf(stderr, "Error: failed to start ranging\n");
        return -1;
    }

    return 0;
}

/* --------------------------- Distance read ------------------------------- */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t raw;
    if (vl53l1x_read16(handle, REG_RESULT_FINAL_DISTANCE_MM, &raw) < 0) {
        fprintf(stderr, "Error: failed to read distance register\n");
        return -1;
    }
    *distance_mm = raw;
    return 0;
}

/* --------------------------- Buzzer control ------------------------------- */
static void buzzer_on(void)
{
    gpioWrite(BUZZER_GPIO, 1);
}

static void buzzer_off(void)
{
    gpioWrite(BUZZER_GPIO, 0);
}

/* --------------------------- Main loop ------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure buzzer GPIO */
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", BUZZER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    buzzer_off();

    /* Open I2C bus 1 at address 0x29 */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X\n",
                I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed (sensor may be absent)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L1X ready. Polling every %d ms. Threshold: %d mm. Ctrl+C to exit.\n",
           POLL_INTERVAL_US / 1000, DISTANCE_THRESHOLD);

    bool buzzer_active = false;

    while (g_running) {
        uint16_t distance;

        if (vl53l1x_read_distance(g_i2c_handle, &distance) == 0) {
            printf("Distance: %u mm\n", distance);

            if (distance < DISTANCE_THRESHOLD && !buzzer_active) {
                buzzer_on();
                buzzer_active = true;
                gpioDelay(BUZZER_ON_US);
                buzzer_off();
                gpioDelay(BUZZER_OFF_US);
            } else if (distance >= DISTANCE_THRESHOLD && buzzer_active) {
                buzzer_off();
                buzzer_active = false;
            }
        } else {
            fprintf(stderr, "Warning: I2C read error, attempting re-initialization...\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;

            gpioDelay(100000);  /* 100 ms back-off */

            g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "Error: re-open I2C failed, retrying next cycle\n");
            } else {
                if (vl53l1x_init(g_i2c_handle) < 0) {
                    fprintf(stderr, "Error: re-init failed, will retry next cycle\n");
                    i2cClose(g_i2c_handle);
                    g_i2c_handle = -1;
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    buzzer_off();
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

