#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_ANGLE_DEG   -90
#define MAX_ANGLE_DEG   90
#define SERVO_MIN_PULSE_US  1000   /* ~1 ms for -90 deg */
#define SERVO_MAX_PULSE_US  2000   /* ~2 ms for +90 deg */
#define TIMEOUT_US 50000          /* 50 ms echo timeout */
#define LOOP_DELAY_US 200000      /* 200 ms between readings */
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin %d as output\n", SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise trigger pin low\n");
        gpioTerminate();
        return -1;
    }

    /* Allow servo to settle */
    gpioDelay(100000);

    return 0;
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_start;

    trigger_sensor();

    /* Wait for echo rising edge */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US) {
            return -1.0;  /* timeout waiting for echo start */
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US) {
            return -1.0;  /* timeout waiting for echo end */
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    double distance = (pulse_width / 1000000.0) * SPEED_OF_SOUND_CM_PER_S / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0;  /* out of valid range */
    }

    return distance;
}

static int map_distance_to_angle(double distance)
{
    if (distance < 0) {
        return MIN_ANGLE_DEG;
    }
    if (distance < MIN_DISTANCE_CM) {
        return MIN_ANGLE_DEG;
    }
    if (distance > MAX_DISTANCE_CM) {
        return MAX_ANGLE_DEG;
    }

    double ratio = (distance - MIN_DISTANCE_CM) /
                   (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    int angle = (int)(ratio * (MAX_ANGLE_DEG - MIN_ANGLE_DEG) + MIN_ANGLE_DEG);
    return angle;
}

static int set_servo_angle(int angle)
{
    if (angle < MIN_ANGLE_DEG || angle > MAX_ANGLE_DEG) {
        fprintf(stderr, "Invalid angle %d, clamping to range [%d, %d]\n",
                angle, MIN_ANGLE_DEG, MAX_ANGLE_DEG);
        if (angle < MIN_ANGLE_DEG) angle = MIN_ANGLE_DEG;
        if (angle > MAX_ANGLE_DEG) angle = MAX_ANGLE_DEG;
    }

    int pulse_width = (int)(SERVO_MIN_PULSE_US +
                            (double)(angle - MIN_ANGLE_DEG) *
                            (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US) /
                            (MAX_ANGLE_DEG - MIN_ANGLE_DEG));

    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Failed to set servo pulse width %d us\n", pulse_width);
        return -1;
    }
    return 0;
}

static void log_data(double distance, int angle)
{
    FILE *fp = fopen("sensor_data.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm, Angle: %d deg\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                distance, angle);
    } else {
        fprintf(fp, "(time error), Distance: %.2f cm, Angle: %d deg\n",
                distance, angle);
    }

    fclose(fp);
}

static void cleanup(void)
{
    /* Stop servo (pulse 0 = off) */
    gpioServo(SERVO_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);

    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() < 0) {
        return 1;
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Error measuring distance (timeout or out of range)\n");
        } else {
            int angle = map_distance_to_angle(distance);
            if (set_servo_angle(angle) < 0) {
                fprintf(stderr, "Error setting servo angle\n");
            }
            log_data(distance, angle);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("Parking Assist System stopped.\n");
    return 0;
}

