#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND_CM_PER_US 0.01715   /* 34300 cm/s / 2 / 1e6 us/cm */
#define DISTANCE_THRESHOLD_CM    30.0
#define MIN_VALID_DISTANCE_CM    2.0
#define MAX_VALID_DISTANCE_CM    400.0
#define TRIGGER_PULSE_US         10
#define ECHO_TIMEOUT_US          30000      /* 30 ms max echo wait */
#define LOOP_DELAY_US            100000     /* 100 ms between readings */

/* Shared state between alert callback and main thread */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile int      g_echo_seen  = 0;
static volatile int      g_echo_valid = 0;   /* 1 = valid reading, 0 = no echo */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * pigpio alert callback for the echo pin.
 * level: 0 = falling edge (end of pulse), 1 = rising edge (start of pulse).
 * tick: 32-bit microsecond counter (wraps every ~71.6 min).
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_seen  = 1;
        g_echo_valid = 0;
    } else if (level == 0 && g_echo_seen) {
        g_end_tick   = tick;
        g_echo_valid = 1;
    }
}

static void trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger HIGH\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger LOW\n");
    }
}

static double calculate_distance_cm(void)
{
    if (!g_echo_valid) {
        return -1.0;
    }

    /* Handle 32-bit tick wraparound */
    uint32_t elapsed = g_end_tick - g_start_tick;
    if (g_end_tick < g_start_tick) {
        elapsed += (uint32_t)(0xFFFFFFFFUL + 1UL);
    }

    if (elapsed == 0 || elapsed > ECHO_TIMEOUT_US) {
        return -1.0;
    }

    return (double)elapsed * SPEED_OF_SOUND_CM_PER_US;
}

static void control_buzzer(double distance)
{
    if (distance < 0.0) {
        gpioWrite(BUZZER_PIN, 0);
        return;
    }

    if (distance < DISTANCE_THRESHOLD_CM) {
        gpioWrite(BUZZER_PIN, 1);
    } else {
        gpioWrite(BUZZER_PIN, 0);
    }
}

int main(void)
{
    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* Register alert callback for echo pin */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register alert callback on ECHO_PIN %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");
    printf("Trigger: GPIO %d | Echo: GPIO %d | Buzzer: GPIO %d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Threshold: %.1f cm | Valid range: %.1f-%.1f cm\n",
           DISTANCE_THRESHOLD_CM, MIN_VALID_DISTANCE_CM, MAX_VALID_DISTANCE_CM);

    while (g_running) {
        g_echo_seen  = 0;
        g_echo_valid = 0;
        g_start_tick = 0;
        g_end_tick   = 0;

        trigger_sensor();

        /* Wait up to 30 ms for the echo callback to set g_echo_valid */
        uint32_t wait_start = gpioTick();
        while (!g_echo_valid && g_running) {
            if ((gpioTick() - wait_start) > ECHO_TIMEOUT_US) {
                break;
            }
            gpioDelay(100); /* 100 us poll interval */
        }

        double distance = calculate_distance_cm();

        if (distance < 0.0) {
            if (!g_echo_seen) {
                printf("Sensor absent: no echo received (timeout)\n");
            } else {
                printf("Invalid reading: echo received but out of range\n");
            }
        } else if (distance < MIN_VALID_DISTANCE_CM || distance > MAX_VALID_DISTANCE_CM) {
            printf("Invalid reading: %.2f cm (out of range)\n", distance);
        } else {
            printf("Distance: %.2f cm\n", distance);
        }

        control_buzzer(distance);
        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();

    printf("\nParking sensor stopped.\n");
    return EXIT_SUCCESS;
}

