#define VL53L1X_SOFT_RESET 0x00
#define VL53L1X_VHV_CONFIG_TIMEOUT_MACROP_LOOP_BOUND 0x00
#define VL53L1X_SYSTEM_INTERRUPT_CLEAR 0x00
#define VL53L1X_SYSTEM_MODE_START 0x00
#define VL53L1X_RESULT_RANGE_STATUS 0x00
#define VL53L1X_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x00

static int i2c_handle = -1;
static FILE *log_file = NULL;
static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    return i2cWriteDevice(handle, buf, 2);
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) return -1;
    char data[1];
    if (i2cReadDevice(handle, data, 1) != 1) return -1;
    *value = (uint8_t)data[0];
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

