#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_VALID_US 100
#define MAX_VALID_US 30000
#define TIMEOUT_US   60000
#define MEASURE_INTERVAL_US 200000
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static volatile uint32_t rising_tick = 0;
static volatile uint32_t falling_tick = 0;
static volatile int echo_state = 0; /* 0=idle, 1=rising seen, 2=falling seen */

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        rising_tick = tick;
        echo_state = 1;
    } else if (level == 0 && echo_state == 1) {
        falling_tick = tick;
        echo_state = 2;
    }
}

static void trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
    }
}

static double calculate_distance(uint32_t pulse_width_us) {
    return (double)pulse_width_us * SPEED_OF_SOUND_CM_PER_US / 2.0;
}

static void log_reading(double distance_cm) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance_cm);
    if (log_file) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance_cm);
        fflush(log_file);
    }
}

static void log_warning(const char *msg) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(stderr, "[%s] WARNING: %s\n", timestamp, msg);
    if (log_file) {
        fprintf(log_file, "%s,WARNING,%s\n", timestamp, msg);
        fflush(log_file);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(ECHO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(10000);

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFunc(ECHO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open distance_log.txt: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_state = 0;
        rising_tick = 0;
        falling_tick = 0;

        trigger_sensor();

        uint32_t start_wait = gpioTick();
        while (echo_state < 2 && running) {
            if ((gpioTick() - start_wait) > TIMEOUT_US) {
                log_warning("Timeout: no echo received within 60 ms");
                break;
            }
            gpioDelay(100);
        }

        if (!running) break;

        if (echo_state == 2) {
            uint32_t pulse_width = falling_tick - rising_tick;
            if (pulse_width >= MIN_VALID_US && pulse_width <= MAX_VALID_US) {
                double distance = calculate_distance(pulse_width);
                log_reading(distance);
            } else {
                log_warning("Out-of-range pulse width");
            }
        }

        gpioDelay(MEASURE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioSetAlertFunc(ECHO_PIN, NULL);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }

    return EXIT_SUCCESS;
}

