#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_OPEN_PIN 18
#define GATE_CLOSE_PIN 19
#define DISTANCE_THRESHOLD_MM 200
#define POLL_INTERVAL_US 500000
#define LOG_FILE "gate_events.log"

/* VL53L1X 16-bit register addresses */
#define VL53L1X_SOFT_RESET 0x0003
#define VL53L1X_VHV_CONFIG_TIMEOUT_MACROP_LOOP_BOUND 0x0008
#define VL53L1X_PHASECAL_CONFIG_TIMEOUT_MACROP 0x0009
#define VL53L1X_RANGE_CONFIG_TIMEOUT_MACROP_A 0x000A
#define VL53L1X_RANGE_CONFIG_TIMEOUT_MACROP_B 0x000B
#define VL53L1X_SYSTEM_INTERMEASUREMENT 0x000C
#define VL53L1X_SYSTEM_RANGE_CONFIG 0x000E
#define VL53L1X_SYSTEM_INTERRUPT_CONFIG_GPIO 0x0014
#define VL53L1X_GPIO_HV_MUX_CTRL 0x0015
#define VL53L1X_SYSTEM_INTERRUPT_CLEAR 0x0016
#define VL53L1X_RESULT_INTERRUPT_STATUS 0x0018
#define VL53L1X_RESULT_RANGE_STATUS 0x0019
#define VL53L1X_RESULT_DISTANCE 0x001A

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(uint8_t reg_hi, uint8_t reg_lo, uint8_t value) {
    char buf[3] = {reg_hi, reg_lo, value};
    return i2cWriteI2CBlockData(i2c_handle, reg_hi, buf, 3);
}

static int read_reg16(uint8_t reg_hi, uint8_t reg_lo, uint8_t *buf, uint32_t len) {
    char reg[2] = {reg_hi, reg_lo};
    int rc = i2cWriteI2CBlockData(i2c_handle, reg_hi, reg, 2);
    if (rc < 0) return rc;
    return i2cReadI2CBlockData(i2c_handle, reg_hi, (char *)buf, len);
}

static int init_vl53l1x(void) {
    /* Soft reset */
    if (write_reg16(0x00, 0x03, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Set timing budget to 50 ms (0x006B) */
    if (write_reg16(0x00, 0x08, 0x6B) < 0) {
        fprintf(stderr, "Error: Failed to set timing budget\n");
        return -1;
    }

    /* Set inter-measurement period to 100 ms (0x0064) */
    if (write_reg16(0x00, 0x0C, 0x64) < 0) {
        fprintf(stderr, "Error: Failed to set inter-measurement\n");
        return -1;
    }

    /* Start ranging */
    if (write_reg16(0x00, 0x0E, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }

    gpioDelay(10000); /* 10 ms for first measurement */
    return 0;
}

static int read_distance(uint16_t *distance) {
    uint8_t status = 0;
    int rc;

    /* Check if data is ready */
    rc = read_reg16(0x00, 0x18, &status, 1);
    if (rc < 0) {
        fprintf(stderr, "Error: Failed to read interrupt status\n");
        return -1;
    }

    if (!(status & 0x01)) {
        return 1; /* Not ready yet */
    }

    /* Read distance */
    uint8_t dist_buf[2];
    rc = read_reg16(0x00, 0x1A, dist_buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: Failed to read distance\n");
        return -1;
    }

    *distance = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];

    /* Clear interrupt */
    if (write_reg16(0x00, 0x16, 0x01) < 0) {
        fprintf(stderr, "Warning: Failed to clear interrupt\n");
    }

    return 0;
}

static void control_gate(int distance_mm) {
    if (distance_mm < DISTANCE_THRESHOLD_MM) {
        gpioWrite(GATE_OPEN_PIN, 1);
        gpioWrite(GATE_CLOSE_PIN, 0);
    } else {
        gpioWrite(GATE_OPEN_PIN, 0);
        gpioWrite(GATE_CLOSE_PIN, 1);
    }
}

static void log_event(const char *event_type, uint16_t distance_mm) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

    if (log_file) {
        fprintf(log_file, "%s - %s - Distance: %u mm\n", timestamp, event_type, distance_mm);
        fflush(log_file);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 1);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", VL53L1X_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x() < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed\n");
        cleanup();
