/*
 * VL53L1X time-of-flight sensor reader with motor control on Raspberry Pi 4.
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2  (I2C bus 1)
 *   VL53L1X SCL -> GPIO3  (I2C bus 1)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Motor FWD  -> GPIO17 (PWM-capable)
 *   Motor BWD  -> GPIO18 (PWM-capable)
 *   Trigger    -> GPIO24 (rising edge)
 *
 * Build: gcc -O2 -Wall -o vl53l1x_motor vl53l1x_motor.c -lpigpio -lrt
 * Run:   sudo ./vl53l1x_motor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define TRIGGER_PIN          24
#define MOTOR_FWD_PIN        17
#define MOTOR_BWD_PIN        18

#define DISTANCE_THRESHOLD_LOW  100   /* mm  -> drive forward  */
#define DISTANCE_THRESHOLD_HIGH 300   /* mm  -> drive backward */
#define POLL_TIMEOUT_MS         500   /* max wait for data-ready */
#define POLL_INTERVAL_US        1000  /* 1 ms between polls       */
#define MAX_RETRIES             3
#define RETRY_DELAY_US          1000  /* 1 ms base backoff       */

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define REG_SOFT_RESET        0x0000
#define REG_SYSTEM_START      0x0000
#define REG_SYSTEM_STATUS     0x0089
#define REG_RESULT_DISTANCE   0x0096

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value);
static int  vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance_mm);
static void motor_stop(void);
static void motor_forward(void);
static void motor_backward(void);
static void control_motor(uint16_t distance);
static void trigger_isr(int gpio, int level, uint32_t tick, void *userdata);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers --------------------------------- */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 3);
        if (rc == 3)
            return 0;
        fprintf(stderr, "I2C write reg 0x%04X failed (attempt %d/%d): rc=%d\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(RETRY_DELAY_US * (1 << attempt));
    }
    return -1;
}

static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, reg_buf, 2);
        if (rc != 2) {
            fprintf(stderr, "I2C write (addr) reg 0x%04X failed (attempt %d/%d): rc=%d\n",
                    reg, attempt + 1, MAX_RETRIES, rc);
            gpioDelay(RETRY_DELAY_US * (1 << attempt));
            continue;
        }

        rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == (int)len)
            return 0;

        fprintf(stderr, "I2C read reg 0x%04X failed (attempt %d/%d): rc=%d\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(RETRY_DELAY_US * (1 << attempt));
    }
    return -1;
}

/* --------------------------- VL53L1X driver ------------------------------ */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (vl53l1x_write_reg16(handle, REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "VL53L1X soft reset write failed\n");
        return -1;
    }
    gpioDelay(1000);  /* 1 ms */

    /* Start measurement */
    if (vl53l1x_write_reg16(handle, REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "VL53L1X start measurement failed\n");
        return -1;
    }
    gpioDelay(1000);  /* 1 ms settle */

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t dist[2] = {0, 0};
    int elapsed = 0;

    /* Poll data-ready bit in SYSTEM_STATUS (bit 0) */
    while (elapsed < POLL_TIMEOUT_MS) {
        if (vl53l1x_read_reg16(handle, REG_SYSTEM_STATUS, &status, 1) != 0) {
            fprintf(stderr, "VL53L1X poll status read failed\n");
            return -1;
        }
        if (status & 0x01)
            break;
        gpioDelay(POLL_INTERVAL_US);
        elapsed++;
    }

    if (elapsed >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "VL53L1X data-ready timeout\n");
        return -1;
    }

    /* Read 16-bit distance from RESULT_DISTANCE (0x0096-0x0097) */
    if (vl53l1x_read_reg16(handle, REG_RESULT_DISTANCE, dist, 2) != 0) {
        fprintf(stderr, "VL53L1X distance read failed\n");
        return -1;
    }

    *distance_mm = ((uint16_t)dist[0] << 8) | dist[1];
    return 0;
}

/* ------------------------------- Motor ----------------------------------- */
static void motor_stop(void)
{
    gpioWrite(MOTOR_FWD_PIN, 0);
    gpioWrite(MOTOR_BWD_PIN, 0);
    printf("Motor stopped\n");
}

static void motor_forward(void)
{
    gpioWrite(MOTOR_FWD_PIN, 1);
    gpioWrite(MOTOR_BWD_PIN, 0);
    printf("Motor forward\n");
}

static void motor_backward(void)
{
    gpioWrite(MOTOR_FWD_PIN, 0);
    gpioWrite(MOTOR_BWD_PIN, 1);
    printf("Motor backward\n");
}

static void control_motor(uint16_t distance)
{
    if (distance < DISTANCE_THRESHOLD_LOW) {
        motor_forward();
    } else if (distance > DISTANCE_THRESHOLD_HIGH) {
        motor_backward();
    } else {
        motor_stop();
    }
}

/* ----------------------------- ISR / main -------------------------------- */
static void trigger_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;

    uint16_t distance = 0;
    if (vl53l1x_read_distance(g_i2c_handle, &distance) == 0) {
        printf("Distance: %u mm\n", distance);
        control_motor(distance);
    } else {
        fprintf(stderr, "Sensor read failed; stopping motor\n");
        motor_stop();
    }
}

static void cleanup(void)
{
    motor_stop();
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to VL53L1X */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure motor pins */
    if (gpioSetMode(MOTOR_FWD_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_BWD_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }
    motor_stop();

    /* Configure trigger pin */
    if (gpioSetMode(TRIGGER_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set trigger GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on trigger GPIO\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register ISR on rising edge */
    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR on GPIO %d\n", TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X motor control running. Trigger on GPIO%d. Ctrl+C to exit.\n",
           TRIGGER_PIN);

    /* Main loop */
    while (g_running) {
        gpioDelay(100000);  /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

