#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_NHDF 0x2F
#define MPR121_NCLF 0x30
#define MPR121_FDLF 0x31
#define MPR121_NHDPROX 0x32
#define MPR121_NCLPROX 0x33
#define MPR121_FDLPROX 0x34
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E
#define MPR121_SOFTRESET 0x80

#define LED1_PIN 17
#define LED2_PIN 18
#define LED3_PIN 27
#define LED4_PIN 22

#define NUM_ELECTRODES 12
#define POLL_DELAY_MS 50

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_lines[4] = {NULL, NULL, NULL, NULL};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0) return -1;
    usleep(10000);

    uint8_t dummy;
    if (i2c_read_reg8(fd, MPR121_SOFTRESET, &dummy) < 0) return -1;
    if (dummy != 0x63) {
        fprintf(stderr, "MPR121 soft-reset verification failed (read 0x%02X, expected 0x63)\n", dummy);
        return -1;
    }

    if (i2c_write_reg8(fd, MPR121_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLR, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDF, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLF, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLF, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDPROX, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLPROX, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLPROX, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_E0TTH, 0x0C) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_E0RTH, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG2, 0x20) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ECR, 0x0C) < 0) return -1;

    return 0;
}

static int mpr121_read_touch_status(int fd, uint16_t *touch_status) {
    uint8_t low, high;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &low) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, &high) < 0) return -1;
    *touch_status = ((uint16_t)high << 8) | low;
    return 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

static void set_led_pattern(int pattern) {
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], (pattern >> i) & 1);
        }
    }
}

static void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], 0);
            gpiod_line_release(led_lines[i]);
            led_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen("proximity_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed.\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int led_pins[4] = {LED1_PIN, LED2_PIN, LED3_PIN, LED4_PIN};
    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, led_pins[i]);
        if (!led_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "mpr121_leds", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    log_event("Proximity sensor application started.");

    while (running) {
        uint16_t touch_status;
        if (mpr121_read_touch_status(i2c_fd, &touch_status) < 0) {
            log_event("Error reading touch status. Retrying...");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        if (touch_status == 0) {
            set_led_pattern(0);
            log_event("No electrode touched.");
        } else {
            for (int i = 0; i < NUM_ELECTRODES; i++) {
                if (touch_status & (1 << i)) {
                    int pattern = 0;
                    switch (i) {
                        case 0: pattern = 0x1; break;
                        case 1: pattern = 0x2; break;
                        case 2: pattern = 0x4; break;
                        case 3: pattern = 0x8; break;
                        case 4: pattern = 0x10; break;
                        case 5: pattern = 0x20; break;
                        case 6: pattern = 0x40; break;
                        case 7: pattern = 0x80; break;
                        case 8: pattern = 0x1; break;
                        case 9: pattern = 0x2; break;
                        case 10: pattern = 0x4; break;
                        case 11: pattern = 0x8; break;
                    }
                    set_led_pattern(pattern);
                    char msg[64];
                    snprintf(msg, sizeof(msg), "Electrode %d touched (pattern 0x%X).", i, pattern);
                    log_event(msg);
                    break;
                }
            }
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    log_event("Proximity sensor application stopped.");
    cleanup();
    return 0;
}

