/*
 * Capacitive Touch Proximity Detector using MPR121 on Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - MPR121 on I2C bus 1, address 0x5A
 *   - LED on GPIO 27 (with appropriate current-limiting resistor)
 *
 * Behavior:
 *   - Verifies MPR121 presence via device ID read.
 *   - Configures electrode 0 with touch/release thresholds 0x0A/0x05.
 *   - On touch (electrode 0), turns LED on for 1 second, logs event to file.
 *   - Handles I2C errors and cleans up GPIO on SIGINT/SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR        0x5A
#define LED_GPIO           27
#define I2C_BUS            1
#define LOG_FILE           "proximity.log"
#define PROXIMITY_THRESHOLD 0x0A
#define RELEASE_THRESHOLD  0x05
#define LED_ON_TIME_US     1000000  /* 1 second */

