#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_ELE0_T_THRESH  0x41
#define MPR121_ELE0_R_THRESH  0x42
#define MPR121_MHD_R          0x2B
#define MPR121_NHD_R          0x2C
#define MPR121_NCL_R          0x2D
#define MPR121_FDL_R          0x2E
#define MPR121_MHD_F          0x2F
#define MPR121_NHD_F          0x30
#define MPR121_NCL_F          0x31
#define MPR121_FDL_F          0x32
#define MPR121_E0TTH          0x41
#define MPR121_E0RTH          0x42
#define MPR121_DEBOUNCE       0x5B
#define MPR121_CONFIG1        0x5C
#define MPR121_CONFIG2        0x5D
#define MPR121_ECR            0x5E
#define MPR121_SOFTRESET      0x80
#define MPR121_DEVICE_ID      0x5C

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int led_state  = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(i2c_handle, reg, value) < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X\n", reg, value);
        return -1;
    }
    return 0;
}

static int mpr121_read(uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int mpr121_init(void) {
    uint8_t id = 0;

    /* Verify device ID */
    if (mpr121_read(MPR121_DEVICE_ID, &id) < 0) {
        return -1;
    }
    if (id != 0x5A) {
        fprintf(stderr, "MPR121 device ID mismatch: got 0x%02X, expected 0x5A\n", id);
        return -1;
    }

    /* Soft reset */
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(2000); /* 2 ms settle */

    /* AFE config: FFI=6 samples, CDC=16uA, CDT=0.5us, ESI=4ms */
    if (mpr121_write(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Baseline filtering: MHD_R=0x01, NHD_R=0x01, NCL_R=0x00, FDL_R=0x00 */
    if (mpr121_write(MPR121_MHD_R, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCL_R, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_R, 0x00) < 0) return -1;

    /* Touch/release thresholds for electrode 0 */
    if (mpr121_write(MPR121_ELE0_T_THRESH, PROXIMITY_THRESHOLD) < 0) return -1;
    if (mpr121_write(MPR121_ELE0_R_THRESH, RELEASE_THRESHOLD) < 0) return -1;

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write(MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* Enable electrode 0 and run */
    if (mpr121_write(MPR121_ECR, 0x01) < 0) return -1;

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (led_state) {
        gpioWrite(LED_GPIO, 0);
        led_state = 0;
    }
    gpioTerminate();
