        uint8_t touch_status = 0;
        if (mpr121_read(MPR121_TOUCHSTATUS_L, &touch_status) < 0) {
            gpioDelay(100000);
            continue;
        }

        if (touch_status & 0x01) {
            printf("Proximity detected on electrode 0\n");
            log_event("Proximity detected");

            if (gpioWrite(LED_GPIO, 1) == 0) {
                led_state = 1;
            } else {
                fprintf(stderr, "Failed to turn on LED\n");
            }

            /* 1-second LED on delay (interruptible by signals) */
            uint32_t elapsed = 0;
            while (running && elapsed < LED_ON_TIME_US) {
                gpioDelay(100000); /* 100 ms chunks */
                elapsed += 100000;
            }

            if (led_state) {
                gpioWrite(LED_GPIO, 0);
                led_state = 0;
            }
        }

        gpioDelay(50000); /* 50 ms polling interval */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

