#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US 1000000
#define TRIGGER_SETTLE_US 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void get_iso8601_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

static int log_distance(FILE *log_file, const char *timestamp, float distance) {
    if (fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int log_error(FILE *log_file, const char *timestamp, const char *error_msg) {
    if (fprintf(log_file, "%s, Error: %s\n", timestamp, error_msg) < 0) {
        fprintf(stderr, "Error writing error to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo) {
    struct timespec ts_start, ts_end;
    long pulse_duration_us;
    float distance;

    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(TRIGGER_SETTLE_US);

    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Error setting trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(errno));
        return -1;
    }

    struct timespec timeout_start, timeout_end;
    clock_gettime(CLOCK_MONOTONIC, &timeout_start);
    long elapsed_timeout_us = 0;

    while (gpiod_line_get_value(echo) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &ts_end);
        elapsed_timeout_us = (ts_end.tv_sec - timeout_start.tv_sec) * 1000000L +
                             (ts_end.tv_nsec - timeout_start.tv_nsec) / 1000L;
        if (elapsed_timeout_us > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin did not go high (sensor absent or wiring fault)\n");
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &ts_start);

    while (gpiod_line_get_value(echo) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &ts_end);
        elapsed_timeout_us = (ts_end.tv_sec - timeout_start.tv_sec) * 1000000L +
                             (ts_end.tv_nsec - timeout_start.tv_nsec) / 1000L;
        if (elapsed_timeout_us > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin did not go low (timeout)\n");
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &ts_end);
    pulse_duration_us = (ts_end.tv_sec - ts_start.tv_sec) * 1000000L +
                        (ts_end.tv_nsec - ts_start.tv_nsec) / 1000L;

    distance = (pulse_duration_us * SPEED_OF_SOUND_CM_PER_US) / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Error: Distance out of range: %.2f cm\n", distance);
        return -1;
    }

    return (int)(distance * 100.0 + 0.5);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    FILE *log_file = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error getting trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Error getting echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        fprintf(stderr, "Error requesting trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Error requesting echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Starting distance measurement. Press Ctrl+C to exit.\n");

    while (program_running) {
        char timestamp[32];
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        int distance = measure_distance(trigger_line, echo_line);
        if (distance >= 0) {
            if (log_distance(log_file, timestamp, distance / 100.0) < 0) {
                fprintf(stderr, "Error logging distance.\n");
            }
        } else {
            if (log_error(log_file, timestamp, "Distance measurement failed") < 0) {
                fprintf(stderr, "Error logging error.\n");
            }
        }

        usleep(LOOP_DELAY_US);
    }

    printf("\nExiting gracefully.\n");
    ret = 0;

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

