#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define SPEED_OF_SOUND   343.0
#define LOG_FILE         "distance_log.txt"
#define TRIGGER_PULSE_US 10
#define SAMPLE_PERIOD_US 1000000  /* 1 second */
#define MIN_PULSE_US     58       /* ~1 cm round-trip */
#define MAX_PULSE_US     25000    /* ~4 m round-trip */

/* Shared state between ISR and main thread */
static volatile uint32_t g_pulse_start = 0;
static volatile uint32_t g_pulse_end   = 0;
static volatile int      g_echo_seen   = 0;
static volatile int      g_running     = 1;
static FILE             *g_log_fp      = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for clean shutdown                                   */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISR callback: fires on EITHER_EDGE of the echo pin                 */
/* ------------------------------------------------------------------ */
static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_pulse_start = tick;
        g_echo_seen   = 0;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_pulse_end = tick;
        g_echo_seen = 1;
    }
    /* level == 2 indicates a watchdog timeout; ignore */
}

/* ------------------------------------------------------------------ */
/* Compute (b - a) with tick wraparound (32-bit microsecond counter)   */
/* ------------------------------------------------------------------ */
static inline uint32_t tick_diff(uint32_t a, uint32_t b)
{
    return b - a;  /* unsigned subtraction handles wraparound */
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 us pulse on the trigger pin                            */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Append a timestamped distance reading to the log file               */
/* ------------------------------------------------------------------ */
static void log_distance(float distance)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s, Distance: %.2f cm\n", timestamp, distance * 100.0);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure trigger pin as output, echo pin as input --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure trigger starts LOW --- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register ISR on EITHER_EDGE of echo pin --- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  Trigger: GPIO%d | Echo: GPIO%d | Log: %s\n", TRIGGER_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        /* Reset echo state before triggering */
        g_echo_seen   = 0;
        g_pulse_start = 0;
        g_pulse_end   = 0;

        trigger_sensor();

        /* Wait for echo with a 1-second timeout so we can re-trigger */
        uint32_t wait_start = gpioTick();
        while (!g_echo_seen && g_running) {
            if (tick_diff(wait_start, gpioTick()) > 1000000) {
                fprintf(stderr, "Warning: echo timeout (no object detected or sensor absent).\n");
                break;
            }
            gpioDelay(1000);  /* 1 ms */
        }

        if (!g_running) {
            break;
        }

        /* Validate pulse width */
        uint32_t pulse_us = tick_diff(g_pulse_start, g_pulse_end);
        if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Warning: pulse width %u us out of range [%u, %u].\n",
                    pulse_us, MIN_PULSE_US, MAX_PULSE_US);
            continue;
        }

        /* Compute distance: (pulse_us * speed) / 2 */
        float distance = (float)pulse_us * SPEED_OF_SOUND / 2.0e6;

        log_distance(distance);
        printf("Distance: %.2f cm\n", distance * 100.0);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);  /* disable ISR */
    gpioWrite(TRIGGER_PIN, 0);
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

