#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define TRIGGER_PIN 27

#define REG_SYSTEM_START 0x0018
#define REG_RANGE_STATUS 0x0016
#define REG_DISTANCE 0x0014
#define REG_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0019
#define REG_SYSTEM_MODE_START 0x0020

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int read_reg8(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, (char *)value, 1) != 1) return -1;
    return 0;
}

static int read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
    *value = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    return 0;
}

static int init_vl53l1x(int handle) {
    if (write_reg8(handle, REG_SYSTEM_START, 0x00) < 0) return -1;
    if (write_reg8(handle, REG_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) < 0) return -1;
    if (write_reg8(handle, REG_SYSTEM_MODE_START, 0x01) < 0) return -1;
    return 0;
}

static int read_distance(int handle, uint16_t *distance, uint8_t *status) {
    if (read_reg16(handle, REG_DISTANCE, distance) < 0) return -1;
    if (read_reg8(handle, REG_RANGE_STATUS, status) < 0) return -1;
    return 0;
}

int main(void) {
    openlog("vl53l1x_reader", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioWrite(TRIGGER_PIN, 1);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at 0x%02X: %d", VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x(i2c_handle) < 0) {
        syslog(LOG_ERR, "Failed to initialise VL53L1X");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "VL53L1X reader started");

    while (running) {
        uint16_t distance = 0;
        uint8_t status = 0;

        if (read_distance(i2c_handle, &distance, &status) == 0) {
            time_t now = time(NULL);
            syslog(LOG_INFO, "Distance: %u mm, Status: 0x%02X", distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read distance");
        }

        gpioDelay(100000);
    }

    syslog(LOG_INFO, "Shutting down");
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

