        syslog(LOG_ERR, "Failed to initialise VL53L1X");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "VL53L1X reader started");

    while (running) {
        uint16_t distance = 0;
        uint8_t status = 0;

        if (read_distance(i2c_handle, &distance, &status) == 0) {
            time_t now = time(NULL);
            syslog(LOG_INFO, "Distance: %u mm, Status: 0x%02X", distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read distance");
        }

