#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define GATE_GPIO      24
#define DISTANCE_CM    20.0f
#define POLL_MS        100
#define LOG_FILE       "gate_log.txt"

/* VL53L1X register addresses */
#define REG_MODEL_ID        0x010F
#define REG_RANGE_MODE      0x0021
#define REG_SYSTEM_START    0x0015
#define REG_RESULT_DIST     0x0089

#define EXPECTED_MODEL_ID   0xEA

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    if (!g_log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(g_log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(g_log_file, "[unknown] %s\n", msg);
    }
    fflush(g_log_file);
}

static int i2c_write_reg8(int handle, uint16_t reg, uint8_t val)
{
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)val };
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        log_event("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *val)
{
    char addr[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(handle, addr, 2) != 2) {
        log_event("I2C write (addr) failed");
        return -1;
    }
    char data;
    if (i2cReadDevice(handle, &data, 1) != 1) {
        log_event("I2C read failed");
        return -1;
    }
    *val = (uint8_t)data;
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *val)
{
    char addr[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(handle, addr, 2) != 2) {
        log_event("I2C write (addr) failed");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        log_event("I2C read (16-bit) failed");
        return -1;
    }
    *val = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int init_sensor(int handle)
{
    uint8_t model_id = 0;
    if (i2c_read_reg8(handle, REG_MODEL_ID, &model_id) != 0) {
        log_event("Failed to read model ID");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Unexpected model ID: 0x%02X (expected 0x%02X)",
                 model_id, EXPECTED_MODEL_ID);
        log_event(msg);
        return -1;
    }

    /* Set short ranging mode (0x00 = short) */
    if (i2c_write_reg8(handle, REG_RANGE_MODE, 0x00) != 0) return -1;

    /* Start ranging */
    if (i2c_write_reg8(handle, REG_SYSTEM_START, 0x01) != 0) return -1;

    log_event("VL53L1X sensor initialised");
    return 0;
}

static int read_distance_cm(int handle, float *distance_cm)
{
    uint16_t dist_mm = 0;
    if (i2c_read_reg16(handle, REG_RESULT_DIST, &dist_mm) != 0) {
        log_event("Failed to read distance register");
        return -1;
    }
    *distance_cm = (float)dist_mm / 10.0f;
    return 0;
}

static void control_gate(int gpio_pin, int distance_cm, float threshold_cm)
{
    static int gate_open = 0;
    int target = (distance_cm < threshold_cm) ? 1 : 0;

    if (target != gate_open) {
        if (gpioWrite(gpio_pin, target) == 0) {
            gate_open = target;
            char msg[64];
            snprintf(msg, sizeof(msg), "Gate %s", gate_open ? "OPEN" : "CLOSED");
            log_event(msg);
        } else {
            log_event("Failed to write gate GPIO");
        }
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GATE_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GATE_GPIO, 0);

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen log");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Gate control system started");

    while (g_running) {
        float distance_cm = 0.0f;
        if (read_distance_cm(g_i2c_handle, &distance_cm) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance_cm);
            log_event(msg);
            control_gate(GATE_GPIO, (int)distance_cm, DISTANCE_CM);
        } else {
            log_event("Distance read error; keeping gate closed");
            gpioWrite(GATE_GPIO, 0);
        }
        gpioDelay(POLL_MS * 1000);
    }

    log_event("Shutting down");
    gpioWrite(GATE_GPIO, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    if (g_log_file) fclose(g_log_file);
    return EXIT_SUCCESS;
}

