#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0
#define MIN_ANGLE      0
#define MAX_ANGLE      180
#define MIN_PULSE_US   500
#define MAX_PULSE_US   2500
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000
#define MOVING_AVG_SIZE  5
#define TRIGGER_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static volatile uint32_t echo_start_tick = 0;
static volatile uint32_t echo_end_tick = 0;
static volatile int echo_state = 0; /* 0=idle, 1=rising seen, 2=falling seen */
static volatile int pulse_ready = 0;
static volatile uint32_t pulse_width = 0;

static double distance_history[MOVING_AVG_SIZE];
static int history_index = 0;
static int history_filled = 0;

static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        echo_start_tick = tick;
        echo_state = 1;
    } else if (level == 0 && echo_state == 1) {
        echo_end_tick = tick;
        echo_state = 2;
        pulse_width = echo_end_tick - echo_start_tick;
        pulse_ready = 1;
    }
}

static double moving_average(double new_value) {
    distance_history[history_index] = new_value;
    history_index = (history_index + 1) % MOVING_AVG_SIZE;
    if (history_filled < MOVING_AVG_SIZE) history_filled++;

    double sum = 0.0;
    for (int i = 0; i < history_filled; i++) sum += distance_history[i];
    return sum / history_filled;
}

static double calculate_distance(uint32_t pulse_width_us) {
    if (pulse_width_us == 0) return -1.0;
    double time_seconds = (double)pulse_width_us / 1000000.0;
    double distance = (SPEED_OF_SOUND * time_seconds) / 2.0;
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) return -1.0;
    return distance;
}

static double map_distance_to_angle(double distance) {
    if (distance < 0) return (double)MAX_ANGLE / 2.0;
    double angle = 90.0 - (distance / MAX_DISTANCE) * 90.0;
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return angle;
}

static int set_servo_angle(double angle) {
    double pulse_width = MIN_PULSE_US + (angle / 180.0) * (MAX_PULSE_US - MIN_PULSE_US);
    int rc = gpioServo(SERVO_PIN, (int)pulse_width);
    if (rc < 0) {
        fprintf(stderr, "gpioServo failed on pin %d: %d\n", SERVO_PIN, rc);
        return -1;
    }
    return 0;
}

static void log_data(double distance, double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) != 0) {
        fprintf(stderr, "Failed to set alert function on echo pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < MOVING_AVG_SIZE; i++) distance_history[i] = 0.0;

    log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,Distance_cm,ServoAngle_deg\n");
    fflush(log_file);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting distance tracking. Press Ctrl+C to exit.\n");

    while (running) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        echo_state = 0;
        pulse_ready = 0;
        pulse_width = 0;
        echo_start_tick = 0;
        echo_end_tick = 0;

        uint32_t start_wait = gpioTick();
        while (!pulse_ready && (gpioTick() - start_wait) < ECHO_TIMEOUT_US) {
            gpioDelay(100);
        }

        double distance = -1.0;
        if (pulse_ready) {
            distance = calculate_distance(pulse_width);
        }

        double angle = map_distance_to_angle(distance);
        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Failed to set servo angle\n");
        }

        log_data(distance, angle);
        gpioDelay(TRIGGER_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

