        fprintf(stderr, "gpioServo failed on pin %d: %d\n", SERVO_PIN, rc);
        return -1;
    }
    return 0;
}

static void log_data(double distance, double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) != 0) {
        fprintf(stderr, "Failed to set alert function on echo pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < MOVING_AVG_SIZE; i++) distance_history[i] = 0.0;

    log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,Distance_cm,ServoAngle_deg\n");
    fflush(log_file);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting distance tracking. Press Ctrl+C to exit.\n");

    while (running) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        echo_state = 0;
        pulse_ready = 0;
        pulse_width = 0;
        echo_start_tick = 0;
        echo_end_tick = 0;

        uint32_t start_wait = gpioTick();
        while (!pulse_ready && (gpioTick() - start_wait) < ECHO_TIMEOUT_US) {
            gpioDelay(100);
        }

        double distance = -1.0;
        if (pulse_ready) {
            distance = calculate_distance(pulse_width);
        }

        double angle = map_distance_to_angle(distance);
        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Failed to set servo angle\n");
        }

        log_data(distance, angle);
        gpioDelay(TRIGGER_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

