#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define PROXIMITY_HIGH_REG 0x08
#define PROXIMITY_LOW_REG 0x09
#define INTERRUPT_PIN 27
#define LOG_FILE "proximity.log"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t running = 1;
static volatile int proximity_value = -1;
static pthread_mutex_t data_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int read_proximity(int handle, int *value) {
    int high = i2cReadByteData(handle, PROXIMITY_HIGH_REG);
    if (high < 0) {
        fprintf(stderr, "Error reading proximity high byte: %d\n", high);
        return -1;
    }
    int low = i2cReadByteData(handle, PROXIMITY_LOW_REG);
    if (low < 0) {
        fprintf(stderr, "Error reading proximity low byte: %d\n", low);
        return -1;
    }
    *value = (high << 8) | low;
    return 0;
}

static void log_proximity(int value, const char *status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Proximity: %d, Status: %s\n", timestamp, value, status);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    int val;
    if (read_proximity(i2c_handle, &val) == 0) {
        pthread_mutex_lock(&data_mutex);
        proximity_value = val;
        pthread_mutex_unlock(&data_mutex);
    } else {
        fprintf(stderr, "Error reading proximity in interrupt handler\n");
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", i2c_address, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(INTERRUPT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as input\n", INTERRUPT_PIN);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(INTERRUPT_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler on GPIO%d\n", INTERRUPT_PIN);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up SIGINT handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity monitoring started. I2C address: 0x%02X, Threshold: %d, Log: %s\n", i2c_address, threshold, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int val;
        if (read_proximity(i2c_handle, &val) == 0) {
            pthread_mutex_lock(&data_mutex);
            if (proximity_value != -1) {
                val = proximity_value;
                proximity_value = -1;
            }
            pthread_mutex_unlock(&data_mutex);

            if (val > threshold) {
                log_proximity(val, "ALERT");
            } else {
                log_proximity(val, "SAFE");
            }
        } else {
            fprintf(stderr, "Error reading proximity in main loop\n");
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioSetISRFuncEx(INTERRUPT_PIN, RISING_EDGE, 0, NULL, NULL);
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

