#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define PWM_PIN     18

#define MIN_FREQUENCY 200.0
#define MAX_FREQUENCY 2000.0
#define MIN_DISTANCE  2.0
#define MAX_DISTANCE  200.0
#define SPEED_OF_SOUND 34300.0

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  200000
#define LOOP_DELAY_US    10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double calculate_frequency(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0;
    }
    return MIN_FREQUENCY * exp(distance / 50.0);
}

static int measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) != 0) {
        fprintf(stderr, "Error: gpioTrigger failed\n");
        return -1;
    }

    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo pulse start timeout\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo pulse end timeout\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    double distance = (double)pulse_width * SPEED_OF_SOUND / 2000000.0;
    return (int)(distance * 100.0 + 0.5);
}

static int set_pwm_frequency(double frequency) {
    if (frequency < 0.0) {
        fprintf(stderr, "Error: Invalid frequency\n");
        return -1;
    }
    if (gpioSetPWMfrequency(PWM_PIN, (int)frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        return -1;
    }
    if (gpioPWM(PWM_PIN, 128) != 0) {
        fprintf(stderr, "Error: gpioPWM failed\n");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode TRIGGER_PIN failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode ECHO_PIN failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode PWM_PIN failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, 255) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioPWM(PWM_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double current_frequency = MIN_FREQUENCY;
    int last_distance = -1;

    while (running) {
        int distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Error: Distance measurement failed, keeping previous frequency\n");
        } else {
            last_distance = distance;
            double frequency = calculate_frequency((double)distance / 100.0);
            if (frequency >= 0.0) {
                current_frequency = frequency;
            } else {
                fprintf(stderr, "Error: Distance out of range, keeping previous frequency\n");
            }
        }

        if (set_pwm_frequency(current_frequency) != 0) {
            fprintf(stderr, "Error: Failed to set PWM frequency\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

