    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1175_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", SI1175_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (fprintf(g_log_fp, "timestamp,als_visible\n") < 0) {
        fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
        fclose(g_log_fp);
        g_log_fp = NULL;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }
    fflush(g_log_fp);

    printf("Si1175 ALS logger started. Logging to %s every %d seconds. Press Ctrl+C to stop.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (g_running) {
        uint16_t als = 0;
        if (i2c_read_reg16(g_i2c_fd, SI1175_REG_ALS_VIS_DATA0, &als) < 0) {
            fprintf(stderr, "Sensor read error — continuing after delay.\n");
        } else {
            if (log_data(g_log_fp, als) < 0) {
                fprintf(stderr, "Logging error — continuing after delay.\n");
            } else {
                printf("ALS: %u\n", (unsigned)als);
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

