#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SI1120_ADDR 0x60
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_RESET 0x30
#define SI1120_REG_ALS_DATA_LOW 0x22
#define SI1120_REG_ALS_DATA_HIGH 0x23
#define SI1120_REG_PS1_DATA_LOW 0x18
#define SI1120_REG_PS1_DATA_HIGH 0x19
#define SI1120_EXPECTED_PART_ID 0x41
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, pigpio_error(result));
    }
    return result;
}

static int read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, pigpio_error(result));
    }
    return result;
}

static int read_16bit(int handle, uint8_t low_reg, uint8_t high_reg) {
    int low = read_register(handle, low_reg);
    if (low < 0) return -1;
    int high = read_register(handle, high_reg);
    if (high < 0) return -1;
    return (high << 8) | low;
}

static int initialize_sensor(int handle) {
    if (write_register(handle, SI1120_REG_RESET, 0x01) < 0) {
        fprintf(stderr, "Failed to reset Si1120\n");
        return -1;
    }
    gpioDelay(10000);

    int part_id = read_register(handle, SI1120_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read Part ID\n");
        return -1;
    }
    if (part_id != SI1120_EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1120_EXPECTED_PART_ID);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, int *ambient_light, int *proximity) {
    int als_low = read_register(handle, SI1120_REG_ALS_DATA_LOW);
    if (als_low < 0) return -1;
    int als_high = read_register(handle, SI1120_REG_ALS_DATA_HIGH);
    if (als_high < 0) return -1;
    *ambient_light = (als_high << 8) | als_low;

    int ps1_low = read_register(handle, SI1120_REG_PS1_DATA_LOW);
    if (ps1_low < 0) return -1;
    int ps1_high = read_register(handle, SI1120_REG_PS1_DATA_HIGH);
    if (ps1_high < 0) return -1;
    *proximity = (ps1_high << 8) | ps1_low;

    return 0;
}

static void log_data(FILE *fp, int ambient_light, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, Ambient Light: %d, Proximity: %d\n", timestamp, ambient_light, proximity);
    fflush(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Si1120 sensor logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int ambient_light = 0, proximity = 0;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !terminate) {
            if (read_sensor_data(i2c_handle, &ambient_light, &proximity) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(RETRY_DELAY_US);
            }
        }

        if (success) {
            log_data(log_file, ambient_light, proximity);
            printf("Ambient Light: %d, Proximity: %d\n", ambient_light, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

