#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SI1145_ADDR 0x60
#define I2C_BUS 1

#define REG_PART_ID 0x00
#define REG_REV_ID 0x01
#define REG_SEQ_ID 0x02
#define REG_INT_CFG 0x03
#define REG_IRQ_ENABLE 0x04
#define REG_IRQ_MODE1 0x05
#define REG_IRQ_MODE2 0x06
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_PS_LED21 0x0C
#define REG_PS_LED3 0x0F
#define REG_PS_ADC_MISC 0x11
#define REG_PS_ADC_GAIN 0x0D
#define REG_COMMAND 0x80
#define REG_ALS_VIS_IR_ADC_COUNTER 0x21
#define REG_ALS_VIS_ADC_GAIN 0x24
#define REG_PS_ADC_COUNTER 0x22
#define REG_PS1_DATA0 0x16
#define REG_PS1_DATA1 0x17

#define CMD_PS_FORCE 0x05
#define CMD_PARAM_SET 0x80
#define CMD_PARAM_QUERY 0xA0

#define LOG_FILE "proximity_log.txt"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int initialize_sensor(int handle) {
    if (write_register(handle, REG_MEAS_RATE0, 0x02) < 0) return -1;
    if (write_register(handle, REG_INT_CFG, 0x00) < 0) return -1;
    if (write_register(handle, REG_ALS_VIS_IR_ADC_COUNTER, 0x0B) < 0) return -1;
    if (write_register(handle, REG_ALS_VIS_ADC_GAIN, 0x00) < 0) return -1;
    if (write_register(handle, REG_PS_ADC_COUNTER, 0x49) < 0) return -1;
    if (write_register(handle, REG_PS_LED21, 0x03) < 0) return -1;
    if (write_register(handle, REG_PS_LED3, 0x0F) < 0) return -1;
    if (write_register(handle, REG_PS_ADC_MISC, 0x03) < 0) return -1;
    if (write_register(handle, REG_PS_ADC_GAIN, 0x07) < 0) return -1;
    if (write_register(handle, REG_COMMAND, CMD_PS_FORCE) < 0) return -1;
    return 0;
}

static int read_proximity(int handle, uint16_t *proximity) {
    uint8_t low, high;
    if (read_register(handle, REG_PS1_DATA0, &low) < 0) return -1;
    if (read_register(handle, REG_PS1_DATA1, &high) < 0) return -1;
    *proximity = (uint16_t)((high << 8) | low);
    return 0;
}

static void log_data(FILE *file, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d, %u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, proximity);
    fflush(file);
}

static void log_error(FILE *file, const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d, ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint8_t part_id, rev_id, seq_id;
    if (read_register(i2c_handle, REG_PART_ID, &part_id) < 0 ||
        read_register(i2c_handle, REG_REV_ID, &rev_id) < 0 ||
        read_register(i2c_handle, REG_SEQ_ID, &seq_id) < 0) {
        fprintf(stderr, "Sensor not detected or communication error\n");
        log_error(log_file, "Sensor initialization failed");
        cleanup();
        return 1;
    }

    printf("Si1145 detected: Part ID=0x%02X, Rev ID=0x%02X, Seq ID=0x%02X\n",
           part_id, rev_id, seq_id);

    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        log_error(log_file, "Sensor initialization failed");
        cleanup();
        return 1;
    }

    printf("Starting proximity readings...\n");

    while (running) {
        uint16_t proximity = 0;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            if (read_proximity(i2c_handle, &proximity) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "Read failed, retrying (%d/%d)...\n",
                            retries, MAX_RETRIES);
                    gpioDelay(100000);
                }
            }
        }

        if (success) {
            log_data(log_file, proximity);
        } else {
            fprintf(stderr, "Failed to read proximity after %d retries\n", MAX_RETRIES);
            log_error(log_file, "Failed to read proximity after retries");
            break;
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

