#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define DISTANCE_THRESHOLD 20.0
#define SPEED_OF_SOUND 0.0343
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000

static volatile int running = 1;
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_state = 0; /* 0=idle, 1=rising seen, 2=falling seen */

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        start_tick = tick;
        echo_state = 1;
    } else if (level == 0 && echo_state == 1) {
        end_tick = tick;
        echo_state = 2;
    }
}

static int set_pin_mode(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int write_pin(int pin, int value) {
    if (gpioWrite(pin, value) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int trigger_sensor(void) {
    if (write_pin(TRIGGER_PIN, 1) != 0) return -1;
    gpioDelay(TRIGGER_PULSE_US);
    if (write_pin(TRIGGER_PIN, 0) != 0) return -1;
    return 0;
}

static double calculate_distance(uint32_t start, uint32_t end) {
    double pulse_width = (double)(end - start);
    return pulse_width * SPEED_OF_SOUND / 2.0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (set_pin_mode(TRIGGER_PIN, PI_OUTPUT) != 0 ||
        set_pin_mode(ECHO_PIN, PI_INPUT) != 0 ||
        set_pin_mode(BUZZER_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return 1;
    }

    if (write_pin(BUZZER_PIN, 0) != 0) {
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx failed for echo pin\n");
        gpioTerminate();
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor() != 0) {
            fprintf(stderr, "Error: trigger_sensor failed\n");
            break;
        }

        echo_state = 0;
        start_tick = 0;
        end_tick = 0;

        /* Wait for echo with timeout */
        uint32_t wait_start = gpioTick();
        while (echo_state != 2 && running) {
            if ((gpioTick() - wait_start) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Error: Echo timeout - sensor not responding\n");
                break;
            }
            gpioDelay(100);
        }

        if (!running) break;

        if (echo_state != 2) {
            fprintf(stderr, "Error: Echo pulse not detected\n");
            continue;
        }

        double distance = calculate_distance(start_tick, end_tick);
        printf("Distance: %.2f cm\n", distance);

        if (distance < DISTANCE_THRESHOLD) {
            if (write_pin(BUZZER_PIN, 1) != 0) {
                fprintf(stderr, "Error: Failed to activate buzzer\n");
            } else {
                printf("Buzzer ON\n");
            }
        } else {
            if (write_pin(BUZZER_PIN, 0) != 0) {
                fprintf(stderr, "Error: Failed to deactivate buzzer\n");
            } else {
                printf("Buzzer OFF\n");
            }
        }

        sleep(1);
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

