#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MAX_DISTANCE 200.0
#define MIN_DISTANCE 20.0

#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double measure_distance(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0;
    uint32_t end_tick = 0;
    int timeout = 0;

    while (gpioRead(ECHO_PIN) == 0) {
        if (++timeout > ECHO_TIMEOUT_US) {
            return -1.0;
        }
        gpioDelay(1);
    }
    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (++timeout > ECHO_TIMEOUT_US) {
            return -1.0;
        }
        gpioDelay(1);
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    double distance = (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0;
    return distance;
}

static int set_servo_angle(double distance) {
    if (distance < 0) {
        return -1;
    }
    double angle = 0.0;
    if (distance > MAX_DISTANCE) {
        angle = 0.0;
    } else if (distance < MIN_DISTANCE) {
        angle = 90.0;
    } else {
        angle = (MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE) * 90.0;
    }
    int pulse_width = (int)(SERVO_MIN_PULSE + (angle / 180.0) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE));
    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000000);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        double distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Error: Ultrasonic sensor timeout\n");
            gpioDelay(100000);
            continue;
        }

        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        if (set_servo_angle(distance) != 0) {
            fprintf(stderr, "Error: Failed to set servo angle\n");
        }

        gpioDelay(100000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

