#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define VL53L1X_ADDR 0x29
#define GATE_GPIO 18
#define DISTANCE_THRESHOLD_CLOSE 200
#define DISTANCE_THRESHOLD_OPEN 250
#define SERVO_CLOSED 1000
#define SERVO_OPEN 2000
#define SERVO_STEP 10
#define SERVO_SETTLE_US 10000
#define SERVO_SETTLE_MS 10
#define I2C_BUS 1
#define LOG_FILE "gate_log.txt"

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_write16(int handle, uint16_t reg, uint8_t value) {
    char buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    return i2cWriteDevice(handle, buf, 3);
}

static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    uint16_t model_id = 0;
    if (vl53l1x_read16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: Failed to read model ID from sensor.\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID 0x%04X (expected 0xEA).\n", model_id);
        return -1;
    }
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to stop sensor.\n");
        return -1;
    }
    gpioDelay(10000);
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_get_distance(int handle, uint16_t *distance) {
    uint16_t range = 0;
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &range) < 0) {
        fprintf(stderr, "Error: Failed to read distance register.\n");
        return -1;
    }
    *distance = range;
    return 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

static void set_servo_position(int gpio, int position) {
    gpioServo(gpio, position);
