#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_ANGLE       0
#define MAX_ANGLE       180
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define TIMEOUT_US      50000
#define LOOP_DELAY_US   100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1.0;
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0;

    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) return -1.0;
    }
    start_tick = gpioTick();

    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) return -1.0;
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    if (pulse_us == 0) return -1.0;
    return (double)pulse_us * 0.0343 / 2.0;
}

static int angle_to_pulse(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return SERVO_MIN_PULSE + (angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE)) / (MAX_ANGLE - MIN_ANGLE);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set SERVO_PIN %d as output.\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Error: distance measurement failed (timeout or invalid pulse).\n");
        } else {
            int angle;
            if (distance < MIN_DISTANCE_CM) {
                angle = MIN_ANGLE;
            } else if (distance > MAX_DISTANCE_CM) {
                angle = MAX_ANGLE;
            } else {
                angle = (int)(((distance - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM)) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE);
            }

            int pulse = angle_to_pulse(angle);
            if (gpioServo(SERVO_PIN, pulse) < 0) {
                fprintf(stderr, "Error: gpioServo failed for pulse %d.\n", pulse);
            }

            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nParking Assist System stopped.\n");
    return EXIT_SUCCESS;
}

