#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define TEMP_REG 0x01
#define HUMID_REG 0x02
#define CONFIG_REG 0x03
#define CONFIG_VALUE 0x00
#define CONV_DELAY_US 10000
#define POLL_INTERVAL_S 2

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

static int write_config(int handle, uint8_t value) {
    int rc = i2cWriteByteData(handle, CONFIG_REG, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing config register 0x%02X: %d\n", CONFIG_REG, rc);
        return -1;
    }
    return 0;
}

static int read_word(int handle, uint8_t reg, uint16_t *out) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

static void convert(int raw_temp, int raw_humid, float *temp, float *humid) {
    *temp = ((175.72f * (float)raw_temp) / 65536.0f) - 46.85f;
    *humid = ((125.0f * (float)raw_humid) / 65536.0f) - 6.0f;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = init_i2c(I2C_BUS, SI7005_ADDR);
    if (handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_config(handle, CONFIG_VALUE) != 0) {
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(CONV_DELAY_US);

    while (running) {
        uint16_t raw_temp = 0, raw_humid = 0;
        int ok = 1;

        if (read_word(handle, TEMP_REG, &raw_temp) != 0) ok = 0;
        if (ok && read_word(handle, HUMID_REG, &raw_humid) != 0) ok = 0;

        if (!ok) {
            fprintf(stderr, "Recovering I2C bus...\n");
            i2cClose(handle);
            gpioDelay(100000);
            handle = init_i2c(I2C_BUS, SI7005_ADDR);
            if (handle < 0) {
                fprintf(stderr, "Failed to re-initialise I2C. Exiting.\n");
                break;
            }
            if (write_config(handle, CONFIG_VALUE) != 0) {
                fprintf(stderr, "Failed to re-write config. Exiting.\n");
                break;
            }
            gpioDelay(CONV_DELAY_US);
            continue;
        }

        float temp, humid;
        convert(raw_temp, raw_humid, &temp, &humid);

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, humid);
        fflush(stdout);

        for (int i = 0; i < POLL_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

