    int handle = init_i2c(I2C_BUS, SI7005_ADDR);
    if (handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_config(handle, CONFIG_VALUE) != 0) {
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(CONV_DELAY_US);

    while (running) {
        uint16_t raw_temp = 0, raw_humid = 0;
        int ok = 1;

        if (read_word(handle, TEMP_REG, &raw_temp) != 0) ok = 0;
        if (ok && read_word(handle, HUMID_REG, &raw_humid) != 0) ok = 0;

        if (!ok) {
            fprintf(stderr, "Recovering I2C bus...\n");
            i2cClose(handle);
            gpioDelay(100000);
            handle = init_i2c(I2C_BUS, SI7005_ADDR);
            if (handle < 0) {
                fprintf(stderr, "Failed to re-initialise I2C. Exiting.\n");
                break;
            }
            if (write_config(handle, CONFIG_VALUE) != 0) {
                fprintf(stderr, "Failed to re-write config. Exiting.\n");
                break;
            }
            gpioDelay(CONV_DELAY_US);
            continue;
        }

        float temp, humid;
        convert(raw_temp, raw_humid, &temp, &humid);

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, humid);
        fflush(stdout);

        for (int i = 0; i < POLL_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

