#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_WHO_AM_I     0x75
#define MPU6050_ACCEL_XOUT_H 0x3B

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I_VAL 0x68

/* Sample period in microseconds (100 ms) */
#define SAMPLE_PERIOD_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an MPU-6050 register; returns 0 on success,      */
/* -1 on error.                                                      */
/* ------------------------------------------------------------------ */
static int mpu_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (pigpio rc=%d)\n",
                value, reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an MPU-6050 register; returns 0 on success,     */
/* -1 on error.                                                      */
/* ------------------------------------------------------------------ */
static int mpu_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the MPU-6050: verify identity, reset, wait, then        */
/* configure sample-rate, accelerometer, and gyroscope ranges.        */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int mpu6050_init(int handle)
{
    uint8_t who_am_i = 0;

    /* Verify sensor identity */
    if (mpu_read_reg(handle, MPU6050_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error\n");
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Reset device */
    if (mpu_write_reg(handle, MPU6050_PWR_MGMT_1, 0x80) != 0)
        return -1;
    gpioDelay(100000); /* 100 ms settle after reset */

    /* Wake up: clear sleep bit (bit 6) in PWR_MGMT_1 */
    if (mpu_write_reg(handle, MPU6050_PWR_MGMT_1, 0x00) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms for oscillator to stabilise */

    /* Sample rate divider = 7 → 1 kHz / (1 + 7) = 125 Hz */
    if (mpu_write_reg(handle, MPU6050_SMPLRT_DIV, 0x07) != 0)
        return -1;

    /* DLPF_CFG = 0 → bandwidth 256 Hz, delay 0 */
    if (mpu_write_reg(handle, MPU6050_CONFIG, 0x00) != 0)
        return -1;

    /* Gyroscope range ±250 °/s (FS_SEL = 0) */
    if (mpu_write_reg(handle, MPU6050_GYRO_CONFIG, 0x00) != 0)
        return -1;

    /* Accelerometer range ±2 g (AFS_SEL = 0) */
    if (mpu_write_reg(handle, MPU6050_ACCEL_CONFIG, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 14-byte block of accelerometer + temperature + gyroscope data */
/* and print it.  Returns 0 on success, -1 on error.                  */
/* ------------------------------------------------------------------ */
static int read_mpu6050_data(int handle)
{
    char buffer[14];
    int16_t accel_x, accel_y, accel_z;
    int16_t temp_raw;
    int16_t gyro_x, gyro_y, gyro_z;

    int bytes_read = i2cReadI2CBlockData(handle, MPU6050_ACCEL_XOUT_H, buffer, 14);
    if (bytes_read != 14) {
        fprintf(stderr, "Error reading 14-byte block (got %d bytes)\n", bytes_read);
        return -1;
    }

    /* Accelerometer: big-endian, left-justified in 16-bit field */
    accel_x = (int16_t)(((uint16_t)buffer[0]  << 8) | (uint8_t)buffer[1]);
    accel_y = (int16_t)(((uint16_t)buffer[2]  << 8) | (uint8_t)buffer[3]);
    accel_z = (int16_t)(((uint16_t)buffer[4]  << 8) | (uint8_t)buffer[5]);
    /* Temperature: 16-bit signed, left-aligned in 16-bit field */
    temp_raw = (int16_t)(((uint16_t)buffer[6]  << 8) | (uint8_t)buffer[7]);
    /* Gyroscope: big-endian, left-justified in 16-bit field */
    gyro_x = (int16_t)(((uint16_t)buffer[8]  << 8) | (uint8_t)buffer[9]);
    gyro_y = (int16_t)(((uint16_t)buffer[10] << 8) | (uint8_t)buffer[11]);
    gyro_z = (int16_t)(((uint16_t)buffer[12] << 8) | (uint8_t)buffer[13]);

