           accel_x, accel_y, accel_z, temp_raw, gyro_x, gyro_y, gyro_z);
    fflush(stdout);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPU-6050 default address */
    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X (pigpio rc=%d)\n",
                MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (mpu6050_init(g_i2c_handle) != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialised on I2C bus 1 at 0x%02X.  Sampling at 125 Hz.\n",
           MPU6050_ADDR);
    printf("Press Ctrl+C to stop.\n");
    fflush(stdout);

    /* Main sampling loop */
    while (g_running) {
        if (read_mpu6050_data(g_i2c_handle) != 0) {
            fprintf(stderr, "Read error — continuing after 100 ms backoff\n");
            gpioDelay(100000);
            continue;
