#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define MEASURE_DELAY_US 10000
#define POLL_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht40(int handle, float *temp, float *hum) {
    uint8_t cmd = MEASURE_CMD;
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: I2C write failed\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t raw_t = (buf[0] << 8) | buf[1];
    uint16_t raw_h = (buf[3] << 8) | buf[4];

    *temp = -45.0f + 175.0f * (float)raw_t / 65535.0f;
    *hum = -6.0f + 125.0f * (float)raw_h / 65535.0f;

    if (*hum < 0.0f) *hum = 0.0f;
    if (*hum > 100.0f) *hum = 100.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float temp, hum;
        if (read_sht40(i2c_handle, &temp, &hum) == 0) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char ts[64];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
            printf("%s - Temperature: %.2f C, Humidity: %.2f %%\n", ts, temp, hum);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: Re-opening I2C bus...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: I2C re-open failed\n");
                running = 0;
            }
        }
        if (running) sleep(POLL_INTERVAL_S);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

