    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float temp, hum;
        if (read_sht40(i2c_handle, &temp, &hum) == 0) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char ts[64];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
            printf("%s - Temperature: %.2f C, Humidity: %.2f %%\n", ts, temp, hum);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: Re-opening I2C bus...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: I2C re-open failed\n");
                running = 0;
            }
        }
        if (running) sleep(POLL_INTERVAL_S);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

