#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int init_i2c(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MLX90614_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

int read_temperature(uint8_t reg, float *temp) {
    uint8_t buf[2];
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    uint16_t raw = (buf[1] << 8) | buf[0];
    *temp = (float)raw * 0.02 - 273.15;
    return 0;
}

int log_temperature(float ambient, float object) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }
    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, ambient, object) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

void cleanup(void) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        float ambient, object;
        if (read_temperature(AMBIENT_TEMP_REG, &ambient) != 0) {
            fprintf(stderr, "Error reading ambient temperature, retrying in %d seconds...\n", READ_INTERVAL_SEC);
        } else if (read_temperature(OBJECT_TEMP_REG, &object) != 0) {
            fprintf(stderr, "Error reading object temperature, retrying in %d seconds...\n", READ_INTERVAL_SEC);
        } else {
            if (log_temperature(ambient, object) != 0) {
                fprintf(stderr, "Error logging temperature data\n");
            }
        }
        sleep(READ_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

