static void log_error(const char *msg) {
    if (!error_fp) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(error_fp, "%s: %s (errno: %s)\n", ts, msg, strerror(errno));
    fflush(error_fp);
}

static void log_data(float temp) {
    if (!log_fp) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_fp, "%s, %.2f\n", ts, temp);
    fflush(log_fp);
}

static int read_temperature(float *temp) {
    uint8_t cmd[2] = {0x36, 0x08};
    uint8_t buf[3];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        log_error("I2C write failed");
        return -1;
    }
    gpioDelay(20000); /* 20 ms conversion delay */

    if (i2cReadDevice(i2c_handle, (char *)buf, 3) != 3) {
        log_error("I2C read failed");
        return -1;
    }

    if (buf[0] & 0x01) {
        log_error("Sensor not ready");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp = (float)raw / 200.0f;
    return 0;
}

