    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", STS30_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    error_fp = fopen(ERROR_LOG_FILE, "a");
    if (!error_fp) {
        fprintf(stderr, "Failed to open error log file: %s\n", strerror(errno));
        fclose(log_fp);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

