#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define LOG_FILE "pressure_log.csv"
#define POLL_INTERVAL_SEC 1
#define MEASUREMENT_DELAY_US 1000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int init_sensor(void) {
    uint8_t cmd[2] = {0x36, 0x08};
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send continuous measurement command.\n");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_US);
    return 0;
}

static int read_sensor_data(float *pressure, float *temperature) {
    uint8_t buf[9];
    int bytes_read = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 9).\n", bytes_read);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: Scale factor CRC mismatch.\n");
        return -1;
    }

    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    int16_t raw_temperature = (buf[3] << 8) | buf[4];
    int16_t scale_factor = (buf[6] << 8) | buf[7];

    if (scale_factor == 0) {
        fprintf(stderr, "Error: Invalid scale factor (0).\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

static int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X.\n", SDP810_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Differential Pressure (Pa),Temperature (C)\n");
        fflush(log_file);
    }

    printf("Ventilation monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure, temperature;
        if (read_sensor_data(&pressure, &temperature) == 0) {
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Warning: Logging failed for this reading.\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping this cycle.\n");
        }
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

