#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP31_ADDR     0x28
#define LOG_FILE       "airflow.log"
#define SAMPLE_US      100000   /* 100 ms */
#define RETRY_COUNT    3
#define RETRY_BASE_US  1000     /* 1 ms backoff */
#define MEAS_DELAY_US  1000     /* 1 ms measurement settle */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_fp    = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — just set the flag so the main loop exits cleanly. */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 as used by Sensirion: polynomial 0x31, init 0xFF, no final XOR */
/* ------------------------------------------------------------------ */
static uint8_t sdp_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Trigger a continuous measurement on the SDP31.                      */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int sdp31_trigger(int handle)
{
    uint8_t cmd[2] = { 0x21, 0x96 };

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        int rc = i2cWriteDevice(handle, (char *)cmd, 2);
        if (rc == 0)
            return 0;

        fprintf(stderr, "[SDP31] trigger write failed (attempt %d/%d): %d\n",
                attempt + 1, RETRY_COUNT, rc);

        if (attempt < RETRY_COUNT - 1)
            gpioDelay(RETRY_BASE_US * (1 << attempt));
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of differential-pressure + temperature data.          */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int sdp31_read(int handle, float *pressure_pa, float *temperature_c)
{
    uint8_t buf[6];

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        int rc = i2cReadDevice(handle, (char *)buf, 6);
        if (rc == 6) {
            /* CRC checks */
            if (sdp_crc8(&buf[0], 2) != buf[2]) {
                fprintf(stderr, "[SDP31] pressure CRC mismatch (attempt %d/%d)\n",
                        attempt + 1, RETRY_COUNT);
                gpioDelay(RETRY_BASE_US * (1 << attempt));
                continue;
            }
            if (sdp_crc8(&buf[3], 2) != buf[5]) {
                fprintf(stderr, "[SDP31] temperature CRC mismatch (attempt %d/%d)\n",
                        attempt + 1, RETRY_COUNT);
                gpioDelay(RETRY_BASE_US * (1 << attempt));
                continue;
            }

            int16_t raw_p = (int16_t)((buf[0] << 8) | buf[1]);
            int16_t raw_t = (int16_t)((buf[3] << 8) | buf[4]);

            *pressure_pa    = (float)raw_p / 60.0f;
            *temperature_c  = (float)raw_t / 200.0f;
            return 0;
        }

        fprintf(stderr, "[SDP31] read failed (attempt %d/%d): %d\n",
                attempt + 1, RETRY_COUNT, rc);

        if (attempt < RETRY_COUNT - 1)
            gpioDelay(RETRY_BASE_US * (1 << attempt));
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Append one CSV line to the log file.                                */
/* ------------------------------------------------------------------ */
static int log_sample(FILE *fp, float pressure, float temperature)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "[LOG] localtime_r failed\n");
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "[LOG] fprintf failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open I2C ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "[FATAL] cannot open %s\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- trigger continuous measurement ---- */
    if (sdp31_trigger(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] SDP31 trigger failed after retries\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow first conversion to complete */
    gpioDelay(MEAS_DELAY_US);

    /* ---- main sampling loop ---- */
    while (g_running) {
        float pressure, temperature;

        if (sdp31_read(g_i2c_handle, &pressure, &temperature) == 0) {
            if (log_sample(g_log_fp, pressure, temperature) != 0)
                fprintf(stderr, "[WARN] log write failed\n");
        } else {
            fprintf(stderr, "[WARN] SDP31 read failed after retries\n");
        }

        gpioDelay(SAMPLE_US);
    }

    /* ---- graceful shutdown ---- */
    fprintf(stderr, "\n[INFO] shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

