#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7015_ADDR    0x40
#define CMD_TEMP_NOHOLD 0xF3
#define CMD_HUM_NOHOLD  0xF5
#define LOG_FILE       "sensor_data.txt"
#define SAMPLE_SEC     5
#define MAX_POLLS      20

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

static int read_measurement(int handle, uint8_t cmd, uint16_t *raw)
{
    char buf[2];
    int rc;

    rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByte(0x%02X) failed: %s\n",
                cmd, pigpio_error(rc));
        return -1;
    }

    /* No Hold Master mode: sensor holds SCL low for ~10 ms per measurement.
     * Poll for data-ready by reading 2 bytes. */
    for (int i = 0; i < MAX_POLLS; i++) {
        rc = i2cReadDevice(handle, buf, 2);
        if (rc == 2) {
            *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        if (rc < 0) {
            fprintf(stderr, "i2cReadDevice poll failed: %s\n",
                    pigpio_error(rc));
            return -1;
        }
        gpioDelay(2000); /* 2 ms between polls */
    }

    fprintf(stderr, "Measurement 0x%02X timed out after %d polls\n", cmd, MAX_POLLS);
    return -1;
}

static int read_temperature(int handle, float *temp)
{
    uint16_t raw;
    if (read_measurement(handle, CMD_TEMP_NOHOLD, &raw) != 0)
        return -1;
    *temp = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(int handle, float *hum)
{
    uint16_t raw;
    if (read_measurement(handle, CMD_HUM_NOHOLD, &raw) != 0)
        return -1;
    float rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    *hum = rh;
    return 0;
}

static int log_data(float temp, float hum)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, hum);
    fclose(fp);
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SI7015_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si7015 sensor logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp, hum;

        if (read_temperature(g_i2c_handle, &temp) != 0) {
            fprintf(stderr, "Temperature read failed; retrying next cycle\n");
        } else if (read_humidity(g_i2c_handle, &hum) != 0) {
            fprintf(stderr, "Humidity read failed; retrying next cycle\n");
        } else {
            if (log_data(temp, hum) != 0)
                fprintf(stderr, "Logging failed\n");
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly. */
        for (int i = 0; i < SAMPLE_SEC * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

