    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    printf("Ventilation monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure, temperature;
        int ret = read_sdp800(i2c_fd, &pressure, &temperature);

        if (ret == 0) {
            log_data(pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
        } else if (ret == -1) {
            fprintf(stderr, "I2C communication error.\n");
        } else if (ret == -2) {
            fprintf(stderr, "CRC error: sensor data corrupted.\n");
        }

        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

