#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define FAN_GPIO       18
#define TEMP_THRESH_HIGH 28.0f
#define TEMP_THRESH_LOW  27.0f
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD  2
#define I2C_RETRIES    3
#define MEASURE_DELAY_US 10000
#define RETRY_DELAY_US  100000

#define CMD_TEMP_HOLD  0xE3
#define CMD_HUM_HOLD   0xE5

typedef struct {
    time_t timestamp;
    float  temperature;
    float  humidity;
} SensorData;

static SensorData circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

static int read_sensor_data(int handle, float *temperature, float *humidity) {
    char buf[2];
    int  raw;
    int  retries;

    /* Temperature measurement */
    for (retries = 0; retries < I2C_RETRIES; retries++) {
        if (i2cWriteByte(handle, CMD_TEMP_HOLD) < 0) {
            fprintf(stderr, "Error: failed to write temperature command (attempt %d)\n", retries + 1);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(MEASURE_DELAY_US);
        if (i2cReadDevice(handle, buf, 2) == 2) {
            raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            *temperature = (175.72f * (float)raw / 65536.0f) - 46.85f;
            break;
        }
        fprintf(stderr, "Error: temperature read failed (attempt %d)\n", retries + 1);
        gpioDelay(RETRY_DELAY_US);
    }
    if (retries == I2C_RETRIES) return -1;

    /* Humidity measurement */
    for (retries = 0; retries < I2C_RETRIES; retries++) {
        if (i2cWriteByte(handle, CMD_HUM_HOLD) < 0) {
            fprintf(stderr, "Error: failed to write humidity command (attempt %d)\n", retries + 1);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(MEASURE_DELAY_US);
        if (i2cReadDevice(handle, buf, 2) == 2) {
            raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            *humidity = (125.0f * (float)raw / 65536.0f) - 6.0f;
            break;
        }
        fprintf(stderr, "Error: humidity read failed (attempt %d)\n", retries + 1);
        gpioDelay(RETRY_DELAY_US);
    }
    if (retries == I2C_RETRIES) return -1;

    return 0;
}

static void update_circular_buffer(float temperature, float humidity) {
    time(&circular_buffer[buffer_index].timestamp);
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].humidity    = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void control_fan(float temperature) {
    static int fan_on = 0;
    if (temperature > TEMP_THRESH_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = 1;
        printf("Fan ON (temp: %.2f C)\n", temperature);
    } else if (temperature < TEMP_THRESH_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = 0;
        printf("Fan OFF (temp: %.2f C)\n", temperature);
    }
}

static void print_buffer(void) {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm_info = localtime(&circular_buffer[idx].timestamp);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("[%s] Temp: %.2f C, Hum: %.2f %%\n",
               ts, circular_buffer[idx].temperature, circular_buffer[idx].humidity);
    }
    printf("--- End Log ---\n\n");
}

int main(void) {
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (code %d)\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7021 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_sensor_data(i2c_handle, &temperature, &humidity) == 0) {
            update_circular_buffer(temperature, humidity);
            control_fan(temperature);
            printf("Temp: %.2f C, Hum: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error: sensor read failed after %d retries\n", I2C_RETRIES);
        }
        print_buffer();
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

