#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_US 5000000
#define STARTUP_DELAY_US 1000000

#define CMD_START_PERIODIC 0x21B1
#define CMD_STOP_PERIODIC 0x3F86
#define CMD_DATA_READY 0xE4B8
#define CMD_READ_MEASUREMENT 0xEC05

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to send command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int read_measurement(uint16_t *co2, float *temp, float *hum) {
    uint8_t buf[9];
    if (i2cWriteDevice(i2c_handle, (char *)"\x00", 1) != 0) {
        fprintf(stderr, "Error: Failed to write read-measurement command\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from sensor\n");
        return -1;
    }
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CO2 CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }
    *co2 = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t t_raw = (uint16_t)((buf[3] << 8) | buf[4]);
    uint16_t h_raw = (uint16_t)((buf[6] << 8) | buf[7]);
    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *hum = 100.0f * (float)h_raw / 65535.0f;
    return 0;
}

static int data_ready(void) {
    uint8_t buf[3];
    if (i2cWriteDevice(i2c_handle, (char *)"\x00", 1) != 0) {
        fprintf(stderr, "Error: Failed to write data-ready command\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to read data-ready response\n");
        return -1;
    }
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Data-ready CRC mismatch\n");
        return -1;
    }
    uint16_t word = (uint16_t)((buf[0] << 8) | buf[1]);
    return (word & 0x07FF) != 0;
}

static void log_data(uint16_t co2, float temp, float hum) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, hum);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(CMD_STOP_PERIODIC);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X on bus %d\n", SCD40_I2C_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    if (send_command(CMD_START_PERIODIC) != 0) { cleanup(); return 1; }
    gpioDelay(STARTUP_DELAY_US);
    while (running) {
        if (data_ready() < 0) { gpioDelay(POLL_INTERVAL_US); continue; }
        uint16_t co2; float temp, hum;
        if (read_measurement(&co2, &temp, &hum) == 0) {
            log_data(co2, temp, hum);
            printf("CO2: %u ppm, Temp: %.2f C, Hum: %.2f %%\n", co2, temp, hum);
        } else {
            fprintf(stderr, "Warning: Measurement read failed, retrying...\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }
    cleanup();
    return 0;
}

