#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define LED_GPIO 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20
#define MEASUREMENT_INTERVAL_US 5000000

/* SCD40 command codes (16-bit, big-endian on the wire) */
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT  0x3F86
#define CMD_GET_DATA_READY_STATUS     0xE4B8
#define CMD_READ_MEASUREMENT          0xEC05

typedef struct {
    uint16_t co2;
    float    temperature;
    float    humidity;
} sensor_data_t;

static sensor_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int read_measurement(sensor_data_t *data) {
    uint8_t buf[9];
    if (send_command(CMD_READ_MEASUREMENT) != 0)
        return -1;

    /* Datasheet: measurement ready takes ~5 ms; give a little margin */
    gpioDelay(10000);

    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: i2cReadDevice failed for read_measurement\n");
        return -1;
    }

    /* Validate CRC for each 2-byte data word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on CO2 word\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: CRC mismatch on humidity word\n");
        return -1;
    }

    data->co2 = (uint16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (float)((buf[3] << 8) | buf[4]) / 100.0f;
    data->humidity = (float)((buf[6] << 8) | buf[7]) / 100.0f;
    return 0;
}

static int add_to_buffer(sensor_data_t data) {
    circular_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE)
        buffer_count++;
    return 0;
}

static void print_buffer(void) {
    printf("\n--- Circular Buffer Contents ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  [%d] CO2: %u ppm, Temp: %.2f C, Hum: %.2f %%\n",
               i, circular_buffer[idx].co2,
               circular_buffer[idx].temperature,
               circular_buffer[idx].humidity);
    }
    printf("--------------------------------\n");
}

static void control_led(int co2_level) {
    if (co2_level > CO2_THRESHOLD)
        gpioWrite(LED_GPIO, 1);
    else
        gpioWrite(LED_GPIO, 0);
}

static int start_periodic_measurement(void) {
    return send_command(CMD_START_PERIODIC_MEASUREMENT);
}

static int stop_periodic_measurement(void) {
    return send_command(CMD_STOP_PERIODIC_MEASUREMENT);
}

static int get_data_ready_status(void) {
    return send_command(CMD_GET_DATA_READY_STATUS);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (start_periodic_measurement() != 0) {
        fprintf(stderr, "Error: failed to start periodic measurement\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SCD40 periodic measurement started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        int ready = get_data_ready_status();
        if (ready != 0) {
            fprintf(stderr, "Warning: get_data_ready_status failed, retrying\n");
            gpioDelay(MEASUREMENT_INTERVAL_US);
            continue;
        }

        /* Poll until bit 0 of the status word is set */
        int status = -1;
        for (int i = 0; i < 100; i++) {
            gpioDelay(10000); /* 10 ms */
            status = get_data_ready_status();
            if (status == 0)
                break;
        }
        if (status != 0) {
            fprintf(stderr, "Warning: data not ready after 1 s\n");
            gpioDelay(MEASUREMENT_INTERVAL_US);
            continue;
        }

        sensor_data_t data;
        if (read_measurement(&data) != 0) {
            fprintf(stderr, "Warning: read_measurement failed\n");
            gpioDelay(MEASUREMENT_INTERVAL_US);
            continue;
        }

        add_to_buffer(data);
        print_buffer();
        control_led(data.co2);

        printf("CO2: %u ppm, Temp: %.2f C, Hum: %.2f %%\n",
               data.co2, data.temperature, data.humidity);

        gpioDelay(MEASUREMENT_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    stop_periodic_measurement();
    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

