#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define EDGE_TIMEOUT_US 50000        /* 50 ms timeout per edge wait */
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read temperature from TMP05 via busy-wait polling of GPIO4.
 * Returns 0 on success (fills *temperature), -1 on timeout/error. */
static int read_temperature(double *temperature) {
    uint32_t start_tick, end_tick;
    int level;
    int timeout;

    /* Wait for falling edge (end of previous cycle) */
    timeout = 0;
    while (gpioRead(GPIO_PIN) == 1) {
        if (timeout++ > EDGE_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge (sensor absent or stuck high)\n");
            return -1;
        }
        gpioDelay(1);
    }

    /* Measure falling edge (end of low period) */
    start_tick = gpioTick();
    timeout = 0;
    while (gpioRead(GPIO_PIN) == 0) {
        if (timeout++ > EDGE_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return -1;
        }
        gpioDelay(1);
    }
    end_tick = gpioTick();
    uint32_t tl = end_tick - start_tick;

    /* Measure rising edge (start of high period) */
    start_tick = gpioTick();
    timeout = 0;
    while (gpioRead(GPIO_PIN) == 1) {
        if (timeout++ > EDGE_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return -1;
        }
        gpioDelay(1);
    }
    end_tick = gpioTick();
    uint32_t th = end_tick - start_tick;

    /* Measure falling edge (end of high period) */
    start_tick = gpioTick();
    timeout = 0;
    while (gpioRead(GPIO_PIN) == 0) {
        if (timeout++ > EDGE_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return -1;
        }
        gpioDelay(1);
    }
    end_tick = gpioTick();
    uint32_t th2 = end_tick - start_tick;
    if (th2 < th) th2 = th;  /* guard against clock rollover */

    /* Validate: TH must be within TL/2..TL*2, and TL must be non-zero */
    if (tl == 0) {
        fprintf(stderr, "Invalid cycle length (TL=0)\n");
        return -1;
    }
    if (th < tl / 2 || th > tl * 2) {
        fprintf(stderr, "Invalid high-time (TH=%u, TL=%u)\n", th, tl);
        return -1;
    }

    /* Convert: Temperature = 4215 - (2143 * TH / TL) */
    *temperature = 4215.0 - (2143.0 * (double)th / (double)tl);
    return 0;
}

/* Log a temperature reading with ISO-8601 timestamp */
static void log_temperature(double temperature) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file);
}

/* Log a sensor error message */
static void log_error(const char *message) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

int main(void) {
    double temperature;
    int consecutive_errors = 0;

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Configure GPIO4 as input */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        if (read_temperature(&temperature) == 0) {
