#include <math.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD_HIGH 0x24
#define MEASURE_CMD_LOW 0x00
#define RETRY_COUNT 3
#define RETRY_DELAY_US 1000000
#define MEASUREMENT_DELAY_US 15000
#define LOG_INTERVAL_US 5000000
#define SINUSOIDAL_OFFSET_DURATION 3600
#define SINUSOIDAL_OFFSET_AMPLITUDE 2.0
#define SINUSOIDAL_OFFSET_FREQUENCY 0.1

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
    uint8_t buf[6];
    int result;

    result = i2cWriteDevice(handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    result = i2cReadDevice(handle, (char *)buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t temp_raw = (buf[0] << 8) | buf[1];
    uint16_t hum_raw = (buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity = 100.0f * (float)hum_raw / 65535.0f;

    return 0;
}

static float apply_sinusoidal_offset(float value, float amplitude, float frequency, float duration) {
    float elapsed = (float)time(NULL) % duration;
    float offset = amplitude * sinf(2.0f * M_PI * frequency * elapsed);
    return value + offset;
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float temperature, humidity;
    int retry;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT && !terminate) {
            if (read_sht35(i2c_handle, &temperature, &humidity) == 0) {
                temperature = apply_sinusoidal_offset(temperature, SINUSOIDAL_OFFSET_AMPLITUDE, SINUSOIDAL_OFFSET_FREQUENCY, SINUSOIDAL_OFFSET_DURATION);
                humidity = apply_sinusoidal_offset(humidity, SINUSOIDAL_OFFSET_AMPLITUDE, SINUSOIDAL_OFFSET_FREQUENCY, SINUSOIDAL_OFFSET_DURATION);
                log_data(temperature, humidity);
                break;
            } else {
                fprintf(stderr, "Read failed, retry %d/%d\n", retry + 1, RETRY_COUNT);
                retry++;
                if (retry < RETRY_COUNT) {
                    gpioDelay(RETRY_DELAY_US);
                }
            }
        }

        if (retry == RETRY_COUNT && !terminate) {
            fprintf(stderr, "All retries exhausted, logging NaN values\n");
            log_data(NAN, NAN);
        }

        gpioDelay(LOG_INTERVAL_US);
    }

    cleanup();
    return 0;
}

