#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP810_ADDR 0x25
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x2F
#define CONVERSION_DELAY_MS 45
#define LOG_FILE "airflow.csv"
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = {msb, lsb};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

static int read_sdp810(int fd, float *pressure, float *temperature) {
    uint8_t data[9];
    int16_t raw_pressure, raw_temperature, raw_scale_factor;

    if (i2c_write_cmd(fd, MEASURE_CMD_MSB, MEASURE_CMD_LSB) < 0) {
        return -1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, data, 9) < 0) {
        return -1;
    }

    if (crc8(&data[0], 2) != data[2]) {
        return -2;
    }
    if (crc8(&data[3], 2) != data[5]) {
        return -2;
    }
    if (crc8(&data[6], 2) != data[8]) {
        return -2;
    }

    raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    raw_temperature = (int16_t)((data[3] << 8) | data[4]);
    raw_scale_factor = (int16_t)((data[6] << 8) | data[7]);

    if (raw_scale_factor == 0) {
        return -3;
    }

    *pressure = (float)raw_pressure / (float)raw_scale_factor;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

static int log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log file");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float pressure, temperature;
        int ret = read_sdp810(i2c_fd, &pressure, &temperature);

        if (ret == 0) {
            if (log_data(log_fp, pressure, temperature) < 0) {
                fprintf(stderr, "Error writing to log file\n");
            }
        } else {
            fprintf(stderr, "Sensor read error (code: %d)\n", ret);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

