#define CMD_MEASURE    0x2400  /* single-shot, high repeatability, clock-stretching disabled */
#define MEASURE_DELAY  15000   /* microseconds (15 ms) */
#define SAMPLE_PERIOD  5000000 /* microseconds (5 s) */
#define CSV_FILE       "environment.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR) ---- */
static uint8_t sht_crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int ensure_csv_header(void)
{
    FILE *fp = fopen(CSV_FILE, "r");
    if (fp == NULL) {
        fp = fopen(CSV_FILE, "w");
        if (fp == NULL) {
            perror("fopen(" CSV_FILE ")");
            return -1;
        }
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
        fclose(fp);
        return 0;
    }
    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    fclose(fp);
    if (sz <= 0) {
        fp = fopen(CSV_FILE, "w");
        if (fp == NULL) {
            perror("fopen(" CSV_FILE ")");
            return -1;
        }
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
        fclose(fp);
    }
    return 0;
}

static int read_sht35(int handle, float *temp_c, float *rh)
{
    uint8_t cmd[2] = { (uint8_t)(CMD_MEASURE >> 8), (uint8_t)(CMD_MEASURE & 0xFF) };
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X)\n", CMD_MEASURE);
        return -1;
    }

    gpioDelay(MEASURE_DELAY);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "I2C read failed (expected 6 bytes)\n");
        return -1;
    }

    /* CRC validation */
    if (sht_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sht_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temp_c = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static int log_data(float temp_c, float rh)
{
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" CSV_FILE ", a)");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh);
    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SHT35_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ensure_csv_header() != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT35 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp_c, rh;

        if (read_sht35(g_i2c_handle, &temp_c, &rh) == 0) {
            printf("T=%.2f C  RH=%.2f %%\n", temp_c, rh);
            if (log_data(temp_c, rh) != 0)
                fprintf(stderr, "Warning: failed to log data\n");
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

