#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR        0x40
#define I2C_BUS            "/dev/i2c-1"
#define LOG_FILE           "environment.log"
#define POLL_TIMEOUT_MS    100
#define SAMPLE_INTERVAL_S  5
#define RESET_CMD          0xFE
#define CMD_HUMIDITY_NOHOLD 0xF5
#define CMD_TEMP_NOHOLD    0xF3
#define CMD_PREV_TEMP      0xE0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (int)n;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, uint16_t *raw) {
    if (i2c_write_cmd(fd, cmd) < 0) return -1;

    uint8_t buf[3];
    struct timespec ts = {0, POLL_TIMEOUT_MS * 1000000L};
    int elapsed = 0;
    while (elapsed < POLL_TIMEOUT_MS) {
        if (i2c_read_bytes(fd, buf, 3) == 0) {
            if (crc8(buf, 2) != buf[2]) {
                fprintf(stderr, "CRC mismatch on measurement 0x%02X\n", cmd);
                return -1;
            }
            *raw = ((uint16_t)buf[0] << 8) | buf[1];
            return 0;
        }
        if (elapsed >= POLL_TIMEOUT_MS) {
            fprintf(stderr, "Timeout waiting for measurement 0x%02X\n", cmd);
            return -1;
        }
        nanosleep(&ts, NULL);
        elapsed += POLL_TIMEOUT_MS;
    }
    return -1;
}

static int read_temperature(int fd, float *temp) {
    uint16_t raw;
    if (read_measurement(fd, CMD_TEMP_NOHOLD, &raw) < 0) return -1;
    *temp = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(int fd, float *hum) {
    uint16_t raw;
    if (read_measurement(fd, CMD_HUMIDITY_NOHOLD, &raw) < 0) return -1;
    *hum = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*hum < 0.0f) *hum = 0.0f;
    if (*hum > 100.0f) *hum = 100.0f;
    return 0;
}

static int read_previous_temperature(int fd, float *temp) {
    uint16_t raw;
    if (i2c_write_cmd(fd, CMD_PREV_TEMP) < 0) return -1;
    if (i2c_read_bytes(fd, (uint8_t *)&raw, 2) < 0) return -1;
    *temp = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int log_data(const char *ts, float temp, float hum) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    fclose(fp);
    return 0;
}

static int log_error(const char *ts) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "%s,ERROR,ERROR\n", ts);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("Greenhouse monitor started. Logging to %s every %d s.\n", LOG_FILE, SAMPLE_INTERVAL_S);

    while (g_running) {
        float temp = 0.0f, hum = 0.0f;
        int err = 0;

        if (read_humidity(g_i2c_fd, &hum) < 0) {
            fprintf(stderr, "Humidity read failed; resetting sensor.\n");
            if (i2c_write_cmd(g_i2c_fd, RESET_CMD) < 0) {
                fprintf(stderr, "Reset write failed; continuing.\n");
            }
            err = 1;
        }

        if (!err && read_temperature(g_i2c_fd, &temp) < 0) {
            fprintf(stderr, "Temperature read failed; resetting sensor.\n");
            if (i2c_write_cmd(g_i2c_fd, RESET_CMD) < 0) {
                fprintf(stderr, "Reset write failed; continuing.\n");
            }
            err = 1;
        }

        if (!err && read_previous_temperature(g_i2c_fd, &temp) < 0) {
            fprintf(stderr, "Previous temperature read failed; resetting sensor.\n");
            if (i2c_write_cmd(g_i2c_fd, RESET_CMD) < 0) {
                fprintf(stderr, "Reset write failed; continuing.\n");
            }
            err = 1;
        }

        time_t now = time(NULL);
        struct tm tmv;
        char ts[32];
        localtime_r(&now, &tmv);
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);

        if (err) {
            log_error(ts);
            fprintf(stderr, "Logged error record.\n");
        } else {
            log_data(ts, temp, hum);
            printf("%s  T=%.2f C  H=%.2f %%\n", ts, temp, hum);
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return 0;
}

