#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CONVERSION_DELAY_US 20000
#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE "airflow.dat"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int read_sdp810(int handle, float *pressure, float *temperature) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t buf[9];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command to I2C device.\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from I2C device.\n");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }

    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    int16_t raw_temperature = (buf[3] << 8) | buf[4];
    uint16_t scale_factor = (buf[6] << 8) | buf[7];

    if (scale_factor == 0) {
        fprintf(stderr, "Error: Invalid scale factor (0).\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor - 1000.0f;
    *temperature = (float)raw_temperature / 200.0f - 45.0f;

    return 0;
}

static int log_data(FILE *fp, float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, fp) != 1) return -1;
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) return -1;
    fflush(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d.\n", SDP810_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float pressure, temperature;

    while (!terminate) {
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0) {
            if (log_data(log_file, pressure, temperature) != 0) {
                fprintf(stderr, "Error: Failed to write data to log file.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

