#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "flow_log.txt"

/* Linear calibration: 1638 counts = 0 SLPM, 14745 counts = 10 SLPM */
#define MIN_FLOW_COUNTS 1638
#define MAX_FLOW_COUNTS 14745
#define MAX_FLOW_SLPM 10.0

