#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define LPS33HW_ADDR 0x5D
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0xB1
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[20];
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(stderr, "%s: %s (errno: %s)\n", timestamp, message, strerror(errno));
    if (log_file) {
        fprintf(log_file, "%s: %s (errno: %s)\n", timestamp, message, strerror(errno));
        fflush(log_file);
    }
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        return -1;
    }
    return 0;
}

static int read_pressure(int handle, float *pressure) {
    uint8_t xl, l, h;
    if (read_register(handle, PRESS_OUT_XL, &xl) < 0) return -1;
    if (read_register(handle, PRESS_OUT_L, &l) < 0) return -1;
    if (read_register(handle, PRESS_OUT_H, &h) < 0) return -1;
    int32_t raw = (int32_t)((uint32_t)xl | ((uint32_t)l << 8) | ((uint32_t)h << 16));
    if (raw & 0x800000) {
        raw |= 0xFF000000;
    }
    *pressure = (float)raw / 4096.0f;
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    uint8_t l, h;
    if (read_register(handle, TEMP_OUT_L, &l) < 0) return -1;
    if (read_register(handle, TEMP_OUT_H, &h) < 0) return -1;
    int16_t raw = (int16_t)((uint16_t)l | ((uint16_t)h << 8));
    *temperature = 42.5f + (float)raw / 480.0f;
    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[20];
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i;
    if (read_register(i2c_handle, WHO_AM_I, &who_am_i) < 0) {
        log_error("Failed to read WHO_AM_I register");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_VAL, who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (write_register(i2c_handle, CTRL_REG1, 0xB0) < 0) {
        log_error("Failed to write CTRL_REG1");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (program_running) {
        float pressure, temperature;
        if (read_pressure(i2c_handle, &pressure) < 0) {
            log_error("Failed to read pressure");
        } else if (read_temperature(i2c_handle, &temperature) < 0) {
            log_error("Failed to read temperature");
        } else {
            log_data(pressure, temperature);
        }
        gpioDelay(1000000);
    }

    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

