#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD30_I2C_ADDR 0x61
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define MEASUREMENT_INTERVAL 2
#define VENTILATION_OFF_THRESHOLD 800
#define VENTILATION_LOW_THRESHOLD 1200

#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define CMD_GET_DATA_READY 0x0202
#define CMD_READ_MEASUREMENT 0x0300

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t scd30_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int scd30_write_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int scd30_write_command_with_args(uint16_t cmd, uint16_t arg) {
    uint8_t buf[5];
    buf[0] = (uint8_t)(cmd >> 8);
    buf[1] = (uint8_t)(cmd & 0xFF);
    buf[2] = (uint8_t)(arg >> 8);
    buf[3] = (uint8_t)(arg & 0xFF);
    buf[4] = scd30_crc8(&buf[2], 2);
    if (i2cWriteDevice(i2c_handle, (char *)buf, 5) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for command 0x%04X with arg 0x%04X\n", cmd, arg);
        return -1;
    }
    return 0;
}

static int scd30_read_data(uint8_t *buf, size_t len) {
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "Error: i2cReadDevice failed (expected %zu bytes)\n", len);
        return -1;
    }
    return 0;
}

static int scd30_wait_for_data_ready(void) {
    for (int i = 0; i < 100; i++) {
        if (scd30_write_command(CMD_GET_DATA_READY) != 0) return -1;
        gpioDelay(20000);
        uint8_t buf[3];
        if (scd30_read_data(buf, 3) != 0) return -1;
        if (scd30_crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Error: CRC mismatch on data-ready flag\n");
            return -1;
        }
        uint16_t ready = (buf[0] << 8) | buf[1];
        if (ready == 1) return 0;
        gpioDelay(100000);
    }
    fprintf(stderr, "Error: SCD30 data not ready after 10 seconds\n");
    return -1;
}

static int scd30_read_measurement(float *co2, float *temp, float *rh) {
    if (scd30_write_command(CMD_READ_MEASUREMENT) != 0) return -1;
    gpioDelay(20000);
    uint8_t buf[18];
    if (scd30_read_data(buf, 18) != 0) return -1;
    for (int i = 0; i < 3; i++) {
        if (scd30_crc8(&buf[i * 6], 2) != buf[i * 6 + 2]) {
            fprintf(stderr, "Error: CRC mismatch on measurement value %d\n", i);
            return -1;
        }
    }
    uint32_t co2_raw = ((uint32_t)buf[0] << 24) | ((uint32_t)buf[1] << 16) | ((uint32_t)buf[3] << 8) | buf[4];
    uint32_t temp_raw = ((uint32_t)buf[6] << 24) | ((uint32_t)buf[7] << 16) | ((uint32_t)buf[9] << 8) | buf[10];
    uint32_t rh_raw = ((uint32_t)buf[12] << 24) | ((uint32_t)buf[13] << 16) | ((uint32_t)buf[15] << 8) | buf[16];
    *co2 = (float)co2_raw;
    *temp = (float)temp_raw / 100.0f;
    *rh = (float)rh_raw / 100.0f;
    return 0;
}

static void log_data(float co2, float temp, float rh) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", utc);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", ts, co2, temp, rh);
    fflush(log_file);
}

static void control_ventilation(float co2) {
    if (co2 < VENTILATION_OFF_THRESHOLD) {
        printf("Ventilation: OFF (CO2: %.2f ppm)\n", co2);
    } else if (co2 < VENTILATION_LOW_THRESHOLD) {
        printf("Ventilation: LOW (CO2: %.2f ppm)\n", co2);
    } else {
        printf("Ventilation: HIGH (CO2: %.2f ppm)\n", co2);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        scd30_write_command(CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 0;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle %d)\n", i2c_handle);
        gpioTerminate();
        return 0;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    if (scd30_write_command_with_args(CMD_START_PERIODIC_MEASUREMENT, MEASUREMENT_INTERVAL) != 0) {
        fprintf(stderr, "Error: failed to start periodic measurement\n");
        cleanup();
        return 0;
    }

    printf("SCD30 monitoring started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        if (scd30_wait_for_data_ready() != 0) {
            fprintf(stderr, "Warning: data not ready, retrying...\n");
            gpioDelay(1000000);
            continue;
        }
        float co2, temp, rh;
        if (scd30_read_measurement(&co2, &temp, &rh) == 0) {
            log_data(co2, temp, rh);
            control_ventilation(co2);
        } else {
            fprintf(stderr, "Warning: read failed, retrying...\n");
        }
        gpioDelay(5000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

