#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP32_ADDR 0x21
#define I2C_BUS 1
#define DEFAULT_INTERVAL_MS 1000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int sdp32_start_measurement(int handle) {
    uint8_t cmd[2] = {0x36, 0x2F};
    int result = i2cWriteDevice(handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to start measurement (i2cWriteDevice returned %d)\n", result);
        return -1;
    }
    return 0;
}

static int sdp32_read_data(int handle, float *pressure, float *temperature) {
    uint8_t buffer[9];
    int result = i2cReadDevice(handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error: Failed to read data (i2cReadDevice returned %d)\n", result);
        return -1;
    }

    if (crc8(&buffer[0], 2) != buffer[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buffer[3], 2) != buffer[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buffer[6], 2) != buffer[8]) {
        fprintf(stderr, "Error: Scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    uint16_t scale_factor = (uint16_t)((buffer[6] << 8) | buffer[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Error: Invalid scale factor (0)\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
