#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define CMD_CONT_MEAS  0x3615
#define CONV_DELAY_US  45000   /* 45 ms conversion time */
#define POLL_DELAY_US  1000000 /* 1 s between readings */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)               */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Send a 16-bit command to the SDP810                               */
/* ------------------------------------------------------------------ */
static int sdp_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteDevice(0x%04X) failed: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 9 bytes of measurement data (3 words + 3 scale-factor words)  */
/* ------------------------------------------------------------------ */
static int sdp_read_data(int handle, uint8_t *buf)
{
    int rc = i2cReadDevice(handle, (char *)buf, 9);
    if (rc < 0) {
        fprintf(stderr, "i2cReadDevice failed: %d\n", rc);
        return -1;
    }
    if (rc != 9) {
        fprintf(stderr, "Short read: got %d of 9 bytes\n", rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Parse and validate one 3-byte data word + CRC                      */
/* ------------------------------------------------------------------ */
static int parse_word(const uint8_t *buf, int idx, int16_t *out)
{
    if (crc8(&buf[idx], 2) != buf[idx + 2]) {
        fprintf(stderr, "CRC mismatch on word %d\n", idx / 3);
        return -1;
    }
    *out = (int16_t)((buf[idx] << 8) | buf[idx + 1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger continuous measurement and read one reading                */
/* ------------------------------------------------------------------ */
static int sdp_read(int handle, float *pressure, float *temperature)
{
    uint8_t buf[9];

    if (sdp_write_cmd(handle, CMD_CONT_MEAS) != 0)
        return -1;

    gpioDelay(CONV_DELAY_US);

    if (sdp_read_data(handle, buf) != 0)
        return -1;

    int16_t raw_pressure, raw_temperature, scale_factor_pressure, scale_factor_temperature;

    if (parse_word(buf, 0, &raw_pressure) != 0)      return -1;
    if (parse_word(buf, 3, &scale_factor_pressure) != 0) return -1;
    if (parse_word(buf, 6, &raw_temperature) != 0)     return -1;
    if (parse_word(buf, 9, &scale_factor_temperature) != 0) return -1;

    if (scale_factor_pressure == 0) {
        fprintf(stderr, "Invalid scale factor (pressure) = 0\n");
        return -1;
    }
    if (scale_factor_temperature == 0) {
        fprintf(stderr, "Invalid scale factor (temperature) = 0\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor_pressure;
    *temperature = (float)raw_temperature / 200.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP810-125Pa logger started (bus %d, addr 0x%02X). Ctrl+C to stop.\n",
           I2C_BUS, I2C_ADDR);

    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (sdp_read(g_i2c_handle, &pressure, &temperature) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed; retrying...\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(100000); /* 100 ms back-off */
        }

        if (ok) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                   pressure, temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Sensor read failed after %d attempts; continuing.\n",
                    MAX_RETRIES);
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

