#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC1000_ADDR        0x40
#define I2C_BUS             "/dev/i2c-1"
#define REG_TEMP            0x00
#define REG_HUMID           0x01
#define REG_CONFIG          0x02
#define CONFIG_14BIT        0x1000  /* bit 12: TRES=14-bit, HRES=14-bit */
#define CONV_DELAY_MS       20      /* 14-bit T+RH conversion takes ~6.5ms */
#define SAMPLE_INTERVAL_S   5

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_n(int fd, uint8_t reg, uint8_t *dst, size_t n)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_n: write reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t r = read(fd, dst, n);
    if (r < 0 || (size_t)r != n) {
        fprintf(stderr, "i2c_read_n: read reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int hdc1000_init(int fd)
{
    /* 14-bit T+RH measurement, heater off, mode = T+RH */
    if (i2c_write_reg16(fd, REG_CONFIG, CONFIG_14BIT) != 0)
        return -1;
    return 0;
}

static int hdc1000_read(int fd, float *temp, float *hum)
{
    uint8_t buf[4];

    /* Set pointer to temperature register */
    if (write(fd, (uint8_t[]){REG_TEMP}, 1) != 1) {
        fprintf(stderr, "hdc1000_read: set pointer: %s\n", strerror(errno));
        return -1;
    }

    /* 14-bit T+RH conversion takes ~6.5 ms; wait 20 ms to be safe */
    usleep(CONV_DELAY_MS * 1000);

    /* Read 4 bytes: T_MSB, T_LSB, RH_MSB, RH_LSB */
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "hdc1000_read: read data: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw_t = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_h = ((uint16_t)buf[2] << 8) | buf[3];

    *temp = ((float)raw_t / 65536.0f) * 165.0f - 40.0f;
    *hum  = ((float)raw_h / 65536.0f) * 100.0f;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n", HDC1000_ADDR, strerror(errno));
        close(g_fd);
        return EXIT_FAILURE;
    }

    /* Probe: try a zero-length write to confirm the sensor is present */
    if (write(g_fd, NULL, 0) != 0) {
        fprintf(stderr, "HDC1000 not responding at 0x%02X: %s\n", HDC1000_ADDR, strerror(errno));
        close(g_fd);
        return EXIT_FAILURE;
    }

    if (hdc1000_init(g_fd) != 0) {
        fprintf(stderr, "HDC1000 initialization failed\n");
        close(g_fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized on %s at 0x%02X. Sampling every %d s.\n",
           I2C_BUS, HDC1000_ADDR, SAMPLE_INTERVAL_S);

    while (g_running) {
        float temp, hum;
        if (hdc1000_read(g_fd, &temp, &hum) == 0) {
