#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define TEMP_REG 0x00
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_temperature(int handle, float *temperature) {
    char reg = TEMP_REG;
    char data[2];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteDevice(handle, &reg, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing register address (attempt %d): %d\n", attempt + 1, result);
            time_sleep(0.1);
            continue;
        }

        result = i2cReadDevice(handle, data, 2);
        if (result != 0) {
            fprintf(stderr, "Error reading temperature data (attempt %d): %d\n", attempt + 1, result);
            time_sleep(0.1);
            continue;
        }

        uint16_t raw_temp = ((uint16_t)(data[0] << 8)) | (uint8_t)data[1];
        *temperature = (175.72f * raw_temp / 65536.0f) - 46.85f;
        return 0;
    }

    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7051 Temperature Logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature after %d attempts.\n", MAX_RETRIES);
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            time_sleep(1);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

