#define I2C_BUS        1
#define I2C_ADDR       0x63
#define CMD_READ_OTP   0x50
#define CMD_MEASURE    0x40
#define MEASURE_DELAY_US 7000
#define SAMPLE_PERIOD_S 5
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
}

static int read_calibration(int handle, uint16_t *c) {
    char cmd = CMD_READ_OTP;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write OTP read command\n");
        return -1;
    }
    gpioDelay(2000);
    char buf[8];
    if (i2cReadDevice(handle, buf, 8) != 8) {
        fprintf(stderr, "Error: failed to read 8 OTP bytes\n");
        return -1;
    }
    for (int i = 0; i < 4; i++) {
        c[i] = ((uint16_t)(uint8_t)buf[2 * i] << 8) | (uint8_t)buf[2 * i + 1];
    }
    return 0;
}

static int read_measurement(int handle, int32_t *raw_t, int32_t *raw_p) {
    char cmd = CMD_MEASURE;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write measurement command\n");
        return -1;
    }
    gpioDelay(MEASURE_DELAY_US);
    char buf[6];
    if (i2cReadDevice(handle, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read measurement data\n");
        return -1;
    }
    *raw_t = ((int32_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *raw_p = ((int32_t)(uint8_t)buf[3] << 16) | ((uint8_t)buf[2] << 8) | (uint8_t)buf[4];
    return 0;
}

