            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        sleep(1);
    }

    printf("\nShutting down cleanly.\n");
    if (i2c_fd >= 0)
        close(i2c_fd);
    return 0;
}

