    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    int file_exists = (access(LOG_FILE, F_OK) == 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    if (!file_exists) {
        if (fprintf(log_file, "Timestamp,Pressure (Pa)\n") < 0 || fflush(log_file) != 0) {
