#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define MLX90821_ADDR 0x40
#define PRESSURE_REG 0x00
#define SCALE_FACTOR 0.01f
#define MIN_PRESSURE 200.0f
#define MAX_PRESSURE 250.0f
#define LOG_FILE "pressure_log.csv"
#define READ_INTERVAL_SEC 1
#define MAX_RETRIES 2

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, MLX90821_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure) {
    char buf[2];
    int rc;

    rc = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error (rc=%d): %s\n", rc, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure = (float)raw * SCALE_FACTOR;
    return 0;
}

static int log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", ts, pressure) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct stat st;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (stat(LOG_FILE, &st) == 0 && S_ISREG(st.st_mode) && st.st_size == 0) {
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            fprintf(stderr, "Cannot create %s: %s\n", LOG_FILE, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        fprintf(log_file, "timestamp,pressure_kPa\n");
    } else {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Tire pressure monitoring started. Logging to %s\n", LOG_FILE);

    while (!terminate) {
        float pressure;
        int retries = 0;

        while (retries < MAX_RETRIES && !terminate) {
            if (read_pressure(&pressure) == 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Retrying I2C read (%d/%d)...\n", retries, MAX_RETRIES);
                gpioDelay(100000);
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Max retries reached. Re-initializing I2C...\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C re-init failed. Exiting.\n");
                break;
            }
            continue;
        }

        if (log_pressure(pressure) != 0) {
            fprintf(stderr, "Logging failed. Continuing...\n");
        }

        if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
            fprintf(stderr, "WARNING: Pressure %.2f kPa out of range [%.0f-%.0f] kPa\n",
                    pressure, MIN_PRESSURE, MAX_PRESSURE);
        }

        gpioDelay(READ_INTERVAL_SEC * 1000000);
    }

    cleanup();
    printf("Tire pressure monitoring stopped.\n");
    return EXIT_SUCCESS;
}

