#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HIH6130_ADDR 0x27
#define I2C_BUS 1
#define LOG_FILE "environmental_data.log"
#define LOG_SIZE_LIMIT (1024 * 1024) /* 1 MB */
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hih6130(int handle, float *temperature, float *humidity) {
    unsigned char data[4];
    int result;

    /* Trigger measurement: write 0x00 to the sensor */
    result = i2cWriteByte(handle, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    /* Wait for measurement to complete (datasheet: ~36.65 ms typical) */
    gpioDelay(40000); /* 40 ms */

    /* Read 4 bytes: [status, T_MSB, T_LSB, RH_MSB] */
    result = i2cReadDevice(handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading data: expected 4 bytes, got %d\n", result);
        return -1;
    }

    /* Check status bits (bits 7-6 of byte 0) */
    if ((data[0] & 0xC0) != 0x00) {
        fprintf(stderr, "Sensor status error: 0x%02X\n", data[0] & 0xC0);
        return -1;
    }

    /* Convert raw values */
    int raw_temperature = ((data[0] & 0x3F) << 8) | data[1];
    int raw_humidity = (data[2] << 8) | data[3];

    *temperature = (raw_temperature * 165.0f / 16383.0f) - 40.0f;
    *humidity = (raw_humidity * 100.0f / 16383.0f);

    return 0;
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
