    /* Trigger measurement: write 0x00 to the sensor */
    result = i2cWriteByte(handle, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    /* Wait for measurement to complete (datasheet: ~36.65 ms typical) */
    gpioDelay(40000); /* 40 ms */

    /* Read 4 bytes: [status, T_MSB, T_LSB, RH_MSB] */
