#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 4
#define SENT_TICK_US 3
#define SYNC_TICKS 56
#define MIN_NIBBLE_TICKS 36
#define MAX_NIBBLE_TICKS 813
#define MAX_NIBBLES 5
#define TIMEOUT_US 100000
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_nibble(int gpio_pin, int *out_ticks) {
    int start_tick = gpioTick();
    int level;
    int timeout = 0;

    while ((level = gpioRead(gpio_pin)) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1;
        }
    }

    if (level != 0) {
        return -1;
    }

    start_tick = gpioTick();
    while ((level = gpioRead(gpio_pin)) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1;
        }
    }

    *out_ticks = gpioTick() - start_tick;
    return 0;
}

static int read_sent_data(int gpio_pin, int *status, int *data, int *checksum) {
    int ticks;
    int nibbles = 0;

    if (read_nibble(gpio_pin, &ticks) != 0 || ticks < MIN_NIBBLE_TICKS || ticks > MAX_NIBBLE_TICKS) {
        return -1;
    }
    *status = ticks;

    while (nibbles < MAX_NIBBLES - 1) {
        if (read_nibble(gpio_pin, &ticks) != 0) {
            return -1;
        }
        if (ticks < MIN_NIBBLE_TICKS || ticks > MAX_NIBBLE_TICKS) {
            return -1;
        }
        data[nibbles] = ticks;
        nibbles++;
    }

    if (read_nibble(gpio_pin, &ticks) != 0) {
        return -1;
    }
    *checksum = ticks;

    int sum = *status;
    for (int i = 0; i < nibbles; i++) {
        sum += data[i];
    }
    sum = sum & 0x0F;

    if (sum != *checksum) {
        return -1;
    }

    return 0;
}

static float convert_to_pressure(int raw_value) {
    return (float)raw_value * 0.1f + 50.0f;
}

static void log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int status, data[3], checksum;

        if (read_sent_data(GPIO_PIN, &status, data, &checksum) != 0) {
            fprintf(stderr, "Error reading SENT data (sensor absent or bus error)\n");
            gpioDelay(100000);
            continue;
        }

        int raw_value = (status << 8) | (data[0] << 4) | data[1];
        float pressure = convert_to_pressure(raw_value);

        log_pressure(pressure);
        printf("Pressure: %.2f Pa\n", pressure);

        gpioDelay(100000);
    }

    gpioTerminate();
    printf("Pressure monitoring stopped.\n");
    return 0;
}

