#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TMP117_REG_TEMP 0x00
#define TMP117_REG_DEVICE_ID 0x01
#define TMP117_DEVICE_ID 0x0117
#define DATA_FILE "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *data_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, TMP117_REG_TEMP, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature register: %d\n", result);
        return -1;
    }

    int16_t raw_temp = (int16_t)((buf[1] << 8) | buf[0]);
    *temperature = (float)raw_temp * 0.0078125f;
    return 0;
}

static int write_temperature_to_file(FILE *fp, float temperature) {
    uint8_t *raw = (uint8_t *)&temperature;
    if (fwrite(raw, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error writing temperature to file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int device_id = i2cReadWordData(i2c_handle, TMP117_REG_DEVICE_ID);
    if (device_id != TMP117_DEVICE_ID) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%04X (expected 0x%04X)\n", device_id, TMP117_DEVICE_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    data_file = fopen(DATA_FILE, "ab");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Greenhouse monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            if (write_temperature_to_file(data_file, temperature) != 0) {
                fprintf(stderr, "Error writing temperature to file\n");
            } else {
                printf("Temperature: %.2f °C\n", temperature);
            }
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nCleaning up...\n");
    if (data_file != NULL) {
        fclose(data_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

