        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Smart Greenhouse Monitor started. Logging to %s every %d seconds.\n", LOG_FILE, READ_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    while (!terminate) {
        SensorData sd;
        if (read_sht40(i2c_handle, &sd) == 0) {
            if (log_data(log_file, sd.temperature, sd.humidity) != 0) {
                fprintf(stderr, "Warning: Logging failed for this reading\n");
            } else {
                printf("Logged: T=%.2f C, H=%.2f %%\n", sd.temperature, sd.humidity);
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping this cycle\n");
        }
        sleep(READ_INTERVAL_S);
    }

    printf("\nShutting down gracefully...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

