#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHTC3_ADDR        0x70
#define I2C_BUS           1
#define LOG_FILE          "shtc3_environment.log"
#define SAMPLE_INTERVAL_S 5
#define MEAS_DELAY_US     15000  /* 15 ms > 12.4 ms worst-case conversion time */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* CRC-8, polynomial 0x31, initial value 0xFF (Sensirion convention) */
static uint8_t shtc3_crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int shtc3_read(float *temperature, float *humidity)
{
    uint8_t cmd[2] = { 0x78, 0x66 };  /* normal power, clock stretching disabled */
    uint8_t data[6];

    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "[SHTC3] I2C write failed\n");
        return -1;
    }

    gpioDelay(MEAS_DELAY_US);

    if (i2cReadDevice(g_i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "[SHTC3] I2C read failed\n");
        return -1;
    }

    /* CRC validation */
    if (shtc3_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[SHTC3] Temperature CRC mismatch\n");
        return -1;
    }
    if (shtc3_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[SHTC3] Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = 175.0f * (float)t_raw / 65535.0f - 45.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static int log_data(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[LOG] fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[LOG] localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[INIT] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[INIT] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[INIT] sigaction");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("[INFO] SHTC3 indoor air quality monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, humidity;

        if (shtc3_read(&temperature, &humidity) == 0) {
            if (temperature < -40.0f || temperature > 125.0f ||
                humidity < 0.0f   || humidity > 100.0f) {
                fprintf(stderr, "[READ] Out-of-range: T=%.2f C, RH=%.2f %%\n",
                        temperature, humidity);
            } else {
                if (log_data(temperature, humidity) != 0) {
                    fprintf(stderr, "[READ] Logging failed\n");
                }
                printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                       temperature, humidity);
            }
        } else {
            fprintf(stderr, "[READ] Sensor read failed\n");
        }

        /* Sleep in 100 ms increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\n[INFO] Shutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

