#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_SEC 1.0

/* Si7202 register addresses */
#define SI7202_REG_DEVICE_CONFIG 0x00
#define SI7202_REG_FIELD_GAUSS_LSB 0x01
#define SI7202_REG_TEMP_LSB 0x02
#define SI7202_REG_STATUS 0x03

/* Configuration: enable field measurement, 50 Hz ODR, 1.5 Hz filter */
#define SI7202_CONFIG_VALUE 0x00

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X on bus %d: %s\n",
                SI7202_ADDR, I2C_BUS, strerror(errno));
        gpioTerminate();
        return -1;
    }

    /* Configure sensor: enable field measurement */
    if (i2cWriteByteData(i2c_handle, SI7202_REG_DEVICE_CONFIG, SI7202_CONFIG_VALUE) < 0) {
        fprintf(stderr, "Failed to write device config: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor_data(float *field_gauss, float *temp_celsius) {
    int raw_field, raw_temp;

    raw_field = i2cReadByteData(i2c_handle, SI7202_REG_FIELD_GAUSS_LSB);
    if (raw_field < 0) {
        fprintf(stderr, "Failed to read field data: %s\n", strerror(errno));
        return -1;
    }

    raw_temp = i2cReadByteData(i2c_handle, SI7202_REG_TEMP_LSB);
    if (raw_temp < 0) {
        fprintf(stderr, "Failed to read temperature data: %s\n", strerror(errno));
        return -1;
    }

    *field_gauss = (float)raw_field * 0.1f;
    *temp_celsius = (float)raw_temp * 0.01f - 25.0f;

    return 0;
}

