        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n");
        fflush(log_file);
    }

    printf("Starting data logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        float field_gauss, temp_celsius;

        if (read_sensor_data(&field_gauss, &temp_celsius) == 0) {
            if (log_data(field_gauss, temp_celsius) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed, logging NaN values...\n");
            if (log_data(NAN, NAN) != 0) {
                fprintf(stderr, "Failed to log NaN values\n");
            }
        }

        time_sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

