#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define TMP117_ADDR 0x48
#define TMP117_TEMP_REG 0x00
#define TMP117_RESOLUTION 0.0078125f
#define I2C_BUS 1
#define MAX_RETRIES 3
#define LOG_FILE "temperature_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X on bus %d: %s\n",
                TMP117_ADDR, I2C_BUS, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C handle is invalid\n");
        return -1;
    }

    int raw = i2cReadWordData(i2c_handle, TMP117_TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register 0x%02X: %s\n",
                TMP117_TEMP_REG, strerror(errno));
        return -1;
    }

    /* pigpio returns data as (msb << 8) | lsb, TMP117 sends MSB first */
    int16_t signed_raw = (int16_t)((raw & 0xFF00) >> 8) | ((raw & 0x00FF) << 8);
    *temperature = (float)signed_raw * TMP117_RESOLUTION;
    return 0;
}

static int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    int consecutive_failures = 0;

    while (running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            consecutive_failures = 0;
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "Failed to read temperature (attempt %d/%d)\n",
                    consecutive_failures, MAX_RETRIES);

            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }

            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to reinitialize I2C. Exiting.\n");
                break;
            }
        }

        sleep(1);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();

    return 0;
}

