#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_PIN 4
#define LOG_FILE "dht11_readings.txt"
#define ERROR_LOG_FILE "dht11_errors.txt"
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_US 2000000  /* 2 seconds */
#define TIMEOUT_US 1000             /* 1 ms per-phase timeout */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Append a timestamped line to the error log. */
static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen error log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
}

/* Append a timestamped reading to the data log. */
static void log_reading(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen data log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,%.1f,%.1f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, humidity);
    } else {
        fprintf(fp, "[timestamp error],%.1f,%.1f\n", temperature, humidity);
    }
    fclose(fp);
}

/*
 * Wait for the line to reach the requested level or timeout.
 * Returns 0 on success, -1 on timeout.
 */
static int wait_level(int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(DHT11_PIN) != level) {
        if (!running) return -1;
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

/*
 * Read 40 data bits from the DHT11.
 * Returns 0 on success, -1 on timeout or checksum error.
 * On success, data[0..3] hold humidity (integer), data[4] is checksum.
 * data[5..7] hold temperature (integer), data[8] is checksum.
 */
static int read_dht11_data(int data[8]) {
    memset(data, 0, sizeof(data));

    /* --- Start signal: pull low for >= 18 ms, then high --- */
    if (gpioSetMode(DHT11_PIN, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(DHT11_PIN, 0) < 0) return -1;
    gpioDelay(20000);  /* 20 ms low (>= 18 ms required) */

    /* Release line: switch to input; external pull-up keeps it high */
    if (gpioSetMode(DHT11_PIN, PI_INPUT) < 0) return -1;
    gpioDelay(30);     /* 30 us before switch to input */

    /* --- Sensor response: ~80 us low, ~80 us high --- */
    if (wait_level(0, TIMEOUT_US) < 0) return -1;  /* response low */
    if (wait_level(1, TIMEOUT_US) < 0) return -1;  /* response high */
    if (wait_level(0, TIMEOUT_US) < 0) return -1;  /* first bit low */

    /* --- Read 40 data bits --- */
    for (int i = 0; i < 40; i++) {
        /* Each bit begins with a 50 us low pulse */
        if (wait_level(1, TIMEOUT_US) < 0) return -1;

        uint32_t high_start = gpioTick();
        if (wait_level(0, TIMEOUT_US) < 0) return -1;
        uint32_t high_duration = gpioTick() - high_start;

        /* ~26-28 us high => '0', ~70 us high => '1' */
        if (high_duration > 50) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    /* --- Checksum validation --- */
    int checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        return -1;
    }
    int temp_checksum = (data[5] + data[6] + data[7]) & 0xFF;
    if (temp_checksum != data[4]) {
        return -1;
    }

    /* DHT11: decimal parts are always 0; humidity is integer-only */
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int data[8];
    int retries = 0;

    while (running) {
        if (read_dht11_data(data) == 0) {
            float humidity = (float)data[0];
            float temperature = (float)data[2];
            log_reading(temperature, humidity);
            printf("Humidity: %.1f%%, Temperature: %.1f°C\n", humidity, temperature);
            retries = 0;
        } else {
            retries++;
            if (retries >= MAX_RETRIES) {
                log_error("DHT11 read failed after max retries");
                fprintf(stderr, "DHT11 read failed after max retries\n");
                retries = 0;
            } else {
                log_error("DHT11 read failed, retrying...");
                fprintf(stderr, "DHT11 read failed, retrying...\n");
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 20 && running; i++) {
            gpioDelay(100000);
        }
    }

    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return 0;
}

