#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SHT31_ADDR 0x44
#define MEASURE_CMD 0x2C06
#define I2C_BUS 1
#define LOG_FILE "sht31d_data.log"
#define RETRY_COUNT 3
#define RETRY_DELAY_US 100000
#define MEASUREMENT_DELAY_US 20000
#define SAMPLE_INTERVAL_US 5000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht31d(float *temperature, float *humidity) {
    uint8_t cmd[2] = { (MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF };
    uint8_t buf[6];
    int result;

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (result != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        result = i2cReadDevice(i2c_handle, (char *)buf, 6);
        if (result != 6) {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t temp_raw = (buf[0] << 8) | buf[1];
        uint16_t hum_raw = (buf[3] << 8) | buf[4];

        *temperature = -45.0f + (175.0f * temp_raw) / 65535.0f;
        *humidity = (100.0f * hum_raw) / 65535.0f;

        return 0;
    }

    return -1;
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(stderr, "%s ERROR: %s\n", timestamp, message);
    if (log_file) {
        fprintf(log_file, "%s ERROR: %s\n", timestamp, message);
        fflush(log_file);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", SHT31_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        if (read_sht31d(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            log_error("Sensor read failed after retries");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

