#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x64
#define SENSOR2_ADDR 0x65
#define RED_REG 0x64
#define GREEN_REG 0x66
#define BLUE_REG 0x68
#define DEVICE_ID_REG 0x00
#define EXPECTED_DEVICE_ID 0x2A
#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_SEC 1.0

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error at reg 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

static int read_sensor_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_register(handle, RED_REG, red) != 0) return -1;
    if (read_register(handle, GREEN_REG, green) != 0) return -1;
    if (read_register(handle, BLUE_REG, blue) != 0) return -1;
    return 0;
}

static double calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    double r = (double)red;
    double g = (double)green;
    double b = (double)blue;
    if (r <= 0.0 || g <= 0.0 || b <= 0.0) return 0.0;
    double x = 0.0;
    double y = 0.0;
    double z = 0.0;
    if (r > 0.04045) r = pow((r + 0.055) / 1.055, 2.4);
    else r = r / 12.92;
    if (g > 0.04045) g = pow((g + 0.055) / 1.055, 2.4);
    else g = g / 12.92;
    if (b > 0.04045) b = pow((b + 0.055) / 1.055, 2.4);
    else b = b / 12.92;
    r *= 100.0;
    g *= 100.0;
    b *= 100.0;
    x = r * 0.4124 + g * 0.3576 + b * 0.1805;
    y = r * 0.2126 + g * 0.7152 + b * 0.0722;
    z = r * 0.0193 + g * 0.1192 + b * 0.9505;
    if (x <= 0.0 || y <= 0.0) return 0.0;
    double n = (y / 100.0) / 0.95047;
    double cct = 449.0 * pow(n, 3.0) + 3525.0 * pow(n, 2.0) + 6823.3 * n + 5520.33;
    return cct;
}

static double calculate_average_cct(double cct1, double cct2) {
    return (cct1 + cct2) / 2.0;
}

static int log_cct_data(double average_cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(log_file, "%s,%.2f\n", timestamp, average_cct) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    if (log_file) fclose(log_file);
