        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", SENSOR1_ADDR);
        gpioTerminate();
        return 1;
    }
    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", SENSOR2_ADDR);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }
