    if (id1 != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Sensor 1 (0x%02X) device ID mismatch: got 0x%02X, expected 0x%02X\n",
                SENSOR1_ADDR, id1, EXPECTED_DEVICE_ID);
        cleanup();
        return 1;
    }
    int id2 = i2cReadByteData(i2c_handle2, DEVICE_ID_REG);
    if (id2 != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Sensor 2 (0x%02X) device ID mismatch: got 0x%02X, expected 0x%02X\n",
                SENSOR2_ADDR, id2, EXPECTED_DEVICE_ID);
        cleanup();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
        fflush(log_file);
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("Logging CCT data to %s. Press Ctrl+C to stop.\n", LOG_FILE);
    while (running) {
        uint16_t red1 = 0, green1 = 0, blue1 = 0;
        uint16_t red2 = 0, green2 = 0, blue2 = 0;
        if (read_sensor_data(i2c_handle1, &red1, &green1, &blue1) != 0) {
            fprintf(stderr, "Sensor 1 read failed, skipping cycle\n");
            time_sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }
        if (read_sensor_data(i2c_handle2, &red2, &green2, &blue2) != 0) {
            fprintf(stderr, "Sensor 2 read failed, skipping cycle\n");
            time_sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }
        double cct1 = calculate_cct(red1, green1, blue1);
        double cct2 = calculate_cct(red2, green2, blue2);
        double avg = calculate_average_cct(cct1, cct2);
        if (log_cct_data(avg) != 0) {
            fprintf(stderr, "Logging failed, continuing\n");
        }
        time_sleep(SAMPLE_INTERVAL_SEC);
    }
    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

