#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_SEC 2

/* Calibration parameters (example values; adjust for your sensor) */
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define PRESSURE_MIN_KPA 0.0
#define PRESSURE_MAX_KPA 800.0

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
        fflush(log_file);
    }
    fprintf(stderr, "%s, ERROR: %s\n", timestamp, message);
}

static int read_register16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static double convert_pressure(uint16_t raw) {
    return (double)(raw - OUTPUT_MIN) * (PRESSURE_MAX_KPA - PRESSURE_MIN_KPA) / (double)(OUTPUT_MAX - OUTPUT_MIN) + PRESSURE_MIN_KPA;
}

static double convert_temperature(uint16_t raw) {
    return (double)raw * 0.01 - 40.0;
}

static void log_data(double pressure, double temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(log_file, "%s, Pressure: %.2f kPa, Temperature: %.2f C\n", timestamp, pressure, temperature);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Tire pressure monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t raw_pressure = 0, raw_temperature = 0;

        if (read_register16(i2c_handle, PRESSURE_REG, &raw_pressure) != 0) {
            log_error("Failed to read pressure register");
        } else if (read_register16(i2c_handle, TEMPERATURE_REG, &raw_temperature) != 0) {
            log_error("Failed to read temperature register");
        } else {
            double pressure = convert_pressure(raw_pressure);
            double temperature = convert_temperature(raw_temperature);
            log_data(pressure, temperature);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

