#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define TEMP_REG       0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD_HIGH 28.0f
#define TEMP_THRESHOLD_LOW  26.0f
#define SAMPLE_PERIOD_US 1000000  /* 1 second */
#define POLL_DELAY_US   100000    /* 100 ms back-off on error */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Circular buffer ---- */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ---- LM75B temperature read ----
 * The LM75B returns 9-bit data in bits D9-D1 of the 2-byte register.
 * Bit D0 is always 0, so the 9-bit value is (data >> 1) & 0x1FF.
 * Resolution: 0.5 °C per LSB.
 */
static int lm75b_read_temp(int handle, float *out_temp) {
    int raw = i2cReadWordData(handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", TEMP_REG, raw);
        return -1;
    }

    uint16_t word = (uint16_t)raw;
    uint16_t val  = (word >> 1) & 0x1FF;   /* D9-D1 */

    /* Sign-extend 9-bit to 16-bit */
    if (val & 0x100) val |= 0xFFFFFE00;

    *out_temp = (float)val * 0.5f;
    return 0;
}

static void control_fan(int gpio, float avg_temp) {
    static int fan_on = 0;
    if (avg_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(gpio, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (avg %.2f C)\n", avg_temp);
        } else {
            fprintf(stderr, "GPIO write ON failed\n");
        }
    } else if (avg_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(gpio, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (avg %.2f C)\n", avg_temp);
        } else {
            fprintf(stderr, "GPIO write OFF failed\n");
        }
    }
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

int main(void) {
    CircularBuffer temp_buf;
    cb_init(&temp_buf);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);  /* fan off at startup */

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LM75B fan controller started. Ctrl+C to exit.\n");

    while (g_running) {
        float temp;
        if (lm75b_read_temp(g_i2c_handle, &temp) == 0) {
            cb_add(&temp_buf, temp);
            float avg = cb_average(&temp_buf);
            printf("Temp: %.2f C | Avg: %.2f C | Fan: %s\n",
                   temp, avg, avg > TEMP_THRESHOLD_HIGH ? "ON" : "OFF");
            control_fan(FAN_GPIO, avg);
        } else {
            fprintf(stderr, "Temperature read failed; retrying next cycle.\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful shutdown */
    gpioWrite(FAN_GPIO, 0);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

