#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_INTERVAL 60
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000
#define MEASURE_DELAY_US 20000

/* Si7021 commands (single-byte, no register addressing) */
#define CMD_MEASURE_RH_NOHOLD  0xF5
#define CMD_MEASURE_TEMP_NOHOLD 0xF3
#define CMD_READ_TEMP_PREV     0xE0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single command byte to the Si7021 */
static int si7021_write_cmd(int handle, uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 1);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteDevice(0x%02X) attempt %d failed: %d\n",
                cmd, attempt + 1, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* Read 2 bytes from the Si7021 (big-endian, MSB first) */
static int si7021_read_word(int handle, uint16_t *out)
{
    char buf[2];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(handle, buf, 2);
        if (rc == 2) {
            *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "[WARN] i2cReadDevice attempt %d failed: %d\n",
                attempt + 1, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* Read the previous RH measurement via command 0xE0 */
static int si7021_read_prev_rh(int handle, float *rh)
{
    if (si7021_write_cmd(handle, CMD_READ_TEMP_PREV) != 0)
        return -1;
    gpioDelay(MEASURE_DELAY_US);
    uint16_t raw;
    if (si7021_read_word(handle, &raw) != 0)
        return -1;
    *rh = (125.0f * raw) / 65536.0f - 6.0f;
    if (*rh < 0.0f)   *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;
    return 0;
}

/* Read temperature in Celsius */
static int si7021_read_temperature(int handle, float *temp)
{
    if (si7021_write_cmd(handle, CMD_MEASURE_TEMP_NOHOLD) != 0)
        return -1;
    gpioDelay(MEASURE_DELAY_US);
    uint16_t raw;
    if (si7021_read_word(handle, &raw) != 0)
        return -1;
    *temp = (175.72f * raw) / 65536.0f - 46.85f;
    return 0;
}

/* Read humidity in %RH */
static int si7021_read_humidity(int handle, float *rh)
{
    if (si7021_write_cmd(handle, CMD_MEASURE_RH_NOHOLD) != 0)
        return -1;
    gpioDelay(MEASURE_DELAY_US);
    uint16_t raw;
    if (si7021_read_word(handle, &raw) != 0)
        return -1;
    *rh = (125.0f * raw) / 65536.0f - 6.0f;
    if (*rh < 0.0f)   *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;
    return 0;
}

/* Append a timestamped line to the log file and stdout */
static void log_line(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s\n", msg);
        fclose(fp);
    }
    printf("%s\n", msg);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence by reading electronic ID (cmd 0xFA, 8 bytes) */
    char id_cmd[1] = { 0xFA };
    char id_buf[8];
    if (i2cWriteDevice(g_i2c_handle, id_cmd, 1) != 0) {
        fprintf(stderr, "[FATAL] Cannot read Si7021 electronic ID\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
