#define CONVERSION_DELAY_US 25000
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_hdc1080(int handle) {
    /* 14-bit temp + 14-bit humidity, heater off, mode = single-shot */
    if (i2cWriteByteData(handle, CONFIG_REG, 0x10) < 0) {
        fprintf(stderr, "Error: failed to write config register\n");
        return -1;
    }
    return 0;
}

static int read_hdc1080(int handle, float *temperature, float *humidity) {
    char buf[4];
    int ret;

    /* Point to temperature register */
    ret = i2cWriteByte(handle, TEMP_REG);
    if (ret < 0) {
        fprintf(stderr, "Error: failed to set register pointer\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    ret = i2cReadDevice(handle, buf, 4);
    if (ret != 4) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 4)\n", ret);
        return -1;
    }

    unsigned int raw_temp = ((unsigned int)(buf[0] & 0xFF) << 8) | (unsigned int)(buf[1] & 0xFF);
    unsigned int raw_hum  = ((unsigned int)(buf[2] & 0xFF) << 8) | (unsigned int)(buf[3] & 0xFF);

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_hum  / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

