#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data/"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define MEASUREMENT_INTERVAL_SEC 5
#define LOGGING_INTERVAL_SEC 60
#define START_MEASUREMENT_CMD 0x21B1
#define STOP_MEASUREMENT_CMD 0x3F86
#define READ_MEASUREMENT_CMD 0xE000

typedef struct {
    time_t timestamp;
    int co2;
    float temperature;
    float humidity;
} sensor_data_t;

static sensor_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
        fprintf(fp, "%s: %s\n", timestamp, message);
        fclose(fp);
    }
    fprintf(stderr, "%s\n", message);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int send_command(int handle, uint16_t cmd) {
    uint8_t buf[2] = { (cmd >> 8) & 0xFF, cmd & 0xFF };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        log_error("Failed to send command to SCD40");
        return -1;
    }
    return 0;
}

static int read_measurement(int handle, int *co2, float *temperature, float *humidity) {
    if (send_command(handle, READ_MEASUREMENT_CMD) != 0) return -1;
    gpioDelay(20000);

    uint8_t buf[9];
    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        log_error("Failed to read measurement data from SCD40");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        log_error("CRC check failed for CO2 data");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        log_error("CRC check failed for temperature data");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        log_error("CRC check failed for humidity data");
        return -1;
    }

    int raw_co2 = (buf[0] << 8) | buf[1];
    int raw_temp = (buf[3] << 8) | buf[4];
    int raw_hum = (buf[6] << 8) | buf[7];

    *co2 = raw_co2;
    *temperature = -45.0f + 175.0f * (float)raw_temp / 65535.0f;
    *humidity = 100.0f * (float)raw_hum / 65535.0f;
    return 0;
}

static void add_to_buffer(int co2, float temperature, float humidity) {
    pthread_mutex_lock(&buffer_mutex);
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].co2 = co2;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
    pthread_mutex_unlock(&buffer_mutex);
}

static void *log_data_thread(void *arg) {
    (void)arg;
    while (running) {
        sleep(LOGGING_INTERVAL_SEC);
        if (!running) break;

        pthread_mutex_lock(&buffer_mutex);
        int count = buffer_count;
        sensor_data_t local_buffer[BUFFER_SIZE];
        int local_count = (count < BUFFER_SIZE) ? count : BUFFER_SIZE;
        memcpy(local_buffer, circular_buffer, local_count * sizeof(sensor_data_t));
        buffer_count = 0;
        buffer_index = 0;
        pthread_mutex_unlock(&buffer_mutex);

        if (local_count == 0) continue;

        char filename[256];
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        strftime(filename, sizeof(filename), LOG_DIR "%Y-%m-%d_%H-%M-%S.csv", t);

        FILE *fp = fopen(filename, "w");
        if (!fp) {
            log_error("Failed to open CSV file for writing");
            continue;
        }
        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%)\n");
        for (int i = 0; i < local_count; i++) {
            struct tm *t = localtime(&local_buffer[i].timestamp);
            char ts[64];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
            fprintf(fp, "%s,%d,%.2f,%.2f\n", ts, local_buffer[i].co2, local_buffer[i].temperature, local_buffer[i].humidity);
        }
        fclose(fp);
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    if (send_command(i2c_handle, START_MEASUREMENT_CMD) != 0) {
        log_error("Failed to start periodic measurement");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000000);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    pthread_t log_thread;
    if (pthread_create(&log_thread, NULL, log_data_thread, NULL) != 0) {
        log_error("Failed to create logging thread");
        send_command(i2c_handle, STOP_MEASUREMENT_CMD);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int co2, raw_co2;
        float temperature, humidity;
        if (read_measurement(i2c_handle, &raw_co2, &temperature, &humidity) == 0) {
            co2 = raw_co2;
            add_to_buffer(co2, temperature, humidity);
        }
        sleep(MEASUREMENT_INTERVAL_SEC);
    }

    pthread_join(log_thread, NULL);

    send_command(i2c_handle, STOP_MEASUREMENT_CMD);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

