#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VAL 0x08
#define CALIB_REG 0x05
#define MEAS_REG 0x00
#define MEAS_CMD 0x00
#define DATA_LEN 6
#define SAMPLE_INTERVAL_US 5000000
#define MEAS_DELAY_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_calibration(int handle, uint16_t *cal) {
    char buf[8];
    if (i2cReadI2CBlockData(handle, CALIB_REG, buf, 8) != 8) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    for (int i = 0; i < 4; i++) {
        cal[i] = ((uint16_t)(uint8_t)buf[2 * i] << 8) | (uint8_t)buf[2 * i + 1];
    }
    return 0;
}

static int read_sensor_data(int handle, const uint16_t *cal, float *pressure, float *temperature) {
    char cmd = MEAS_CMD;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    char data[DATA_LEN];
    if (i2cReadI2CBlockData(handle, MEAS_REG, data, DATA_LEN) != DATA_LEN) {
        fprintf(stderr, "Error: Failed to read measurement data\n");
        return -1;
    }

    uint32_t raw_p = ((uint32_t)(uint8_t)data[0] << 16) |
                     ((uint32_t)(uint8_t)data[1] << 8) |
                     (uint8_t)data[2];
    uint32_t raw_t = ((uint32_t)(uint8_t)data[3] << 16) |
                     ((uint32_t)(uint8_t)data[4] << 8) |
                     (uint8_t)data[5];

    float LUT = (float)raw_p / 65535.0f;
    *pressure = (float)cal[0] * 0.01f + (float)cal[1] * LUT + (float)cal[2] * LUT * LUT;
    *temperature = (float)cal[3] * 0.01f + (float)cal[1] * LUT + (float)cal[2] * LUT * LUT;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(fp);
    printf("%s,%.2f,%.2f\n", timestamp, pressure, temperature);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int who = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t cal[4];
    if (read_calibration(i2c_handle, cal) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }

    printf("Weather station started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float pressure, temperature;
        if (read_sensor_data(i2c_handle, cal, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

