#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x63
#define LED_PIN        17
#define PRESSURE_THRESHOLD 95000.0f
#define NORMAL_BLINK_MS 500
#define WARNING_BLINK_MS 100
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/* CRC-8 polynomial 0x31, init 0x00 (InvenSense convention) */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_calibration(int fd, uint16_t *cal) {
    if (i2c_write_cmd(fd, 0x66) < 0) return -1;
    usleep(2000);
    uint8_t buf[8];
    if (i2c_read_bytes(fd, buf, 8) < 0) return -1;
    if (crc8(buf, 8) != 0) {
        fprintf(stderr, "Calibration CRC mismatch\n");
        return -1;
    }
    for (int i = 0; i < 4; i++)
        cal[i] = (uint16_t)((buf[2 * i] << 8) | buf[2 * i + 1]);
    return 0;
}

static int read_sensor(int fd, const uint16_t *cal, float *pressure, float *temperature) {
    if (i2c_write_cmd(fd, 0x4011) < 0) return -1;
    usleep(20000);
    uint8_t buf[6];
    if (i2c_read_bytes(fd, buf, 6) < 0) return -1;
    if (crc8(buf, 6) != 0) {
        fprintf(stderr, "Data CRC mismatch\n");
        return -1;
    }
    uint32_t raw_p = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    uint32_t raw_t = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | buf[5];
    /* Convert to physical units using official ICP-10125 formulas */
    float p = (float)raw_p / 1048576.0f;
    float t = (float)raw_t / 1048576.0f;
    float p_comp = (cal[0] * p + cal[1] * t + cal[2]) * p + cal[3] * t;
    *pressure = p_comp * 100.0f; /* Pa */
    *temperature = t * 100.0f;   /* deg C */
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", ICP10125_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint16_t cal[4];
    if (read_calibration(fd, cal) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Cannot open gpiochip4: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }
    if (gpiod_line_request_output(led, "icp10125-led", 0) < 0) {
        fprintf(stderr, "Cannot request LED line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    printf("ICP-10125 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure, temperature;
        if (read_sensor(fd, cal, &pressure, &temperature) < 0) {
            fprintf(stderr, "Sensor read error; retrying in %d s\n", POLL_INTERVAL_S);
            sleep(POLL_INTERVAL_S);
            continue;
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        int blink_ms = (pressure < PRESSURE_THRESHOLD) ? WARNING_BLINK_MS : NORMAL_BLINK_MS;
        int on_ms = blink_ms / 2, off_ms = blink_ms / 2;

        gpiod_line_set_value(led, 1);
        usleep(on_ms * 1000);
        gpiod_line_set_value(led, 0);
        usleep(off_ms * 1000);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

