#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS        1
#define MLX90614_ADDR  0x5A
#define AMBIENT_TEMP   0x06
#define OBJECT_TEMP    0x07
#define FAN_GPIO       18
#define TEMP_HIGH      30.0f
#define TEMP_LOW       28.0f
#define LOG_FILE       "temperature_log.txt"
#define READ_RETRIES   3
#define RETRY_DELAY_US 10000
#define SAMPLE_PERIOD  2

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_temperature(int handle, uint8_t reg, float *temp) {
    char buf[2];
    int rc;

    for (int attempt = 0; attempt < READ_RETRIES; attempt++) {
        rc = i2cWriteByte(handle, reg);
        if (rc < 0) {
            fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d): %d\n", reg, attempt + 1, rc);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(5000);

        rc = i2cReadDevice(handle, buf, 2);
        if (rc == 2) {
            uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            *temp = (float)raw * 0.02f - 273.15f;
            return 0;
        }

        fprintf(stderr, "I2C read reg 0x%02X failed (attempt %d): %d\n", reg, attempt + 1, rc);
        gpioDelay(RETRY_DELAY_US);
    }

    return -1;
}

static void log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, Ambient: %.2f C, Object: %.2f C\n", ts, ambient, object);
    } else {
        fprintf(fp, "(time error), Ambient: %.2f C, Object: %.2f C\n", ambient, object);
    }

    fclose(fp);
}

static void control_fan(float object_temp) {
    static int fan_on = 0;

    if (object_temp > TEMP_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON (object %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (object_temp < TEMP_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (object %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n", I2C_BUS, MLX90614_ADDR, g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(FAN_GPIO, 0);

    printf("MLX90614 temperature monitor started. Ctrl+C to exit.\n");

    while (g_running) {
        float ambient = 0.0f, object = 0.0f;
        int ok = 1;

        if (read_temperature(g_i2c_handle, AMBIENT_TEMP, &ambient) != 0) {
            fprintf(stderr, "Failed to read ambient temperature after retries\n");
            ok = 0;
        }
        if (ok && read_temperature(g_i2c_handle, OBJECT_TEMP, &object) != 0) {
            fprintf(stderr, "Failed to read object temperature after retries\n");
            ok = 0;
        }

        if (ok) {
            log_temperature(ambient, object);
            control_fan(object);
        }

        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("Done.\n");
    return 0;
}

