#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define MEASUREMENT_DELAY_MS 15
#define SERVER_PORT 8080
#define BUFFER_SIZE 1024

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_socket = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_sht40(int handle, float *temperature, float *humidity) {
    unsigned char cmd = MEASURE_CMD;
    unsigned char buf[6];
    int result;

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        result = i2cWriteDevice(handle, (char *)&cmd, 1);
        if (result != 0) {
            fprintf(stderr, "I2C write error (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000);
