#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>

#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define TMP102_TEMP_REG 0x00
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temperature) {
    int raw = i2cReadWordData(handle, TMP102_TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register: %s\n", strerror(errno));
        return -1;
    }
    /* TMP102 sends MSB first, pigpio returns little-endian word */
    int16_t signed_raw = (int16_t)((raw & 0xFF00) | ((raw & 0x00FF) << 8));
    /* 12-bit two's complement, left-justified in 16 bits */
    int16_t temp_12bit = signed_raw >> 4;
    *temperature = (float)temp_12bit * 0.0625f;
    return 0;
}

static int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d, addr 0x%02X: %s\n",
                I2C_BUS, TMP102_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    while (running) {
        float temperature;
        if (read_temperature(handle, &temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, skipping log entry\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    i2cClose(handle);
    gpioTerminate();
    return 0;
}

