#include <signal.h>
#include <pigpio.h>

#define HDC2010_ADDR 0x40
#define TEMP_LOW_REG 0x00
#define TEMP_HIGH_REG 0x01
#define HUMID_LOW_REG 0x02
#define HUMID_HIGH_REG 0x03
#define MEASUREMENT_CONFIG_REG 0x0E
#define CONFIG_REG 0x0F

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_temp_humidity(float *temperature, float *humidity) {
    uint8_t temp_low, temp_high, humid_low, humid_high;
    int rc;

    rc = write_reg(MEASUREMENT_CONFIG_REG, 0x01);
    if (rc < 0) return -1;

    for (int i = 0; i < 50; i++) {
        rc = read_reg(MEASUREMENT_CONFIG_REG, &temp_low);
        if (rc < 0) return -1;
        if ((temp_low & 0x01) == 0) break;
        usleep(10000);
    }

    if (rc < 0) return -1;

    rc = read_reg(TEMP_LOW_REG, &temp_low);
    if (rc < 0) return -1;
    rc = read_reg(TEMP_HIGH_REG, &temp_high);
    if (rc < 0) return -1;
    rc = read_reg(HUMID_LOW_REG, &humid_low);
    if (rc < 0) return -1;
    rc = read_reg(HUMID_HIGH_REG, &humid_high);
    if (rc < 0) return -1;

    uint16_t raw_temp = (uint16_t)((temp_high << 8) | temp_low);
    uint16_t raw_humid = (uint16_t)((humid_high << 8) | humid_low);

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_humid / 65536.0f) * 100.0f;

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", HDC2010_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;
    while (running) {
        if (read_temp_humidity(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read temperature and humidity\n");
        }
        sleep(5);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

