#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define RELAY_GPIO 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX6675_ERROR -1000.0

#define KP 1.0
#define KI 0.1
#define KD 0.01

#define MAX_SETPOINTS 100
#define MAX_PROFILE_LENGTH 1000

typedef struct {
    int time_seconds;
    float target_temp;
} TempProfile;

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static TempProfile *profile = NULL;
static int profile_length = 0;
static float integral = 0.0;
static float previous_error = 0.0;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

float read_max6675(void) {
    uint8_t tx[2] = {0x00, 0x00};
    uint8_t rx[2] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return MAX6675_ERROR;
    }

    int16_t raw = (rx[0] << 8) | rx[1];
    if (raw & 0x04) {
        fprintf(stderr, "MAX6675 fault detected (open circuit)\n");
        return MAX6675_ERROR;
    }

    raw >>= 3;
    return (float)raw * 0.25;
}

int load_profile(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Failed to open profile file");
        return -1;
    }

    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), fp) && count < MAX_PROFILE_LENGTH) {
        if (sscanf(line, "%d, %f", &profile[count].time_seconds, &profile[count].target_temp) == 2) {
            count++;
        }
    }
    fclose(fp);
    profile_length = count;
    return 0;
}

float pid_control(float current_temp, float target_temp) {
    float error = target_temp - current_temp;
    integral += error;
    float derivative = error - previous_error;
    float output = KP * error + KI * integral + KD * derivative;
    previous_error = error;
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;
    return output;
}

int log_data(float current_temp, float target_temp, float duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, current_temp, target_temp, duty_cycle);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (spi_init() != 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "reflow_relay", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    profile = (TempProfile *)malloc(MAX_PROFILE_LENGTH * sizeof(TempProfile));
    if (!profile) {
        perror("Failed to allocate profile memory");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (load_profile(PROFILE_FILE) != 0) {
        free(profile);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Reflow oven started. Press Ctrl+C to exit.\n");

    int current_profile_index = 0;
    time_t last_profile_update = time(NULL);

    while (running) {
        float current_temp = read_max6675();
        if (current_temp <= MAX6675_ERROR + 1.0) {
            fprintf(stderr, "Error reading temperature. Retrying...\n");
            sleep(1);
            continue;
        }

        time_t now = time(NULL);
        if (difftime(now, last_profile_update) >= profile[current_profile_index].time_seconds) {
            if (current_profile_index < profile_length - 1) {
                current_profile_index++;
            }
            last_profile_update = now;
        }

        float target_temp = profile[current_profile_index].target_temp;
        float duty_cycle = pid_control(current_temp, target_temp);

        if (gpiod_line_set_value(relay_line, (duty_cycle > 0.5) ? 1 : 0) < 0) {
            perror("Failed to set relay GPIO");
        }

        if (log_data(current_temp, target_temp, duty_cycle) != 0) {
            fprintf(stderr, "Warning: failed to log data\n");
        }

        printf("Current: %.2f, Target: %.2f, Duty: %.2f\n", current_temp, target_temp, duty_cycle);
        sleep(1);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(relay_line, 0);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    free(profile);
    return EXIT_SUCCESS;
}

