        }

        printf("Temperature: %.2f, Setpoint: %.2f, PID Output: %.2f, Duty Cycle: %d\n", current_temperature, setpoint_temperature, pid_output, duty_cycle);

        sleep(SLEEP_INTERVAL);
    }

