#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define GPIO_CHIP       "gpiochip4"
#define GPIO_LINE       17
#define HUMIDITY_HIGH   60.0f
#define HUMIDITY_LOW    55.0f
#define POLL_INTERVAL   5
#define MAX_RETRIES     3
#define RETRY_DELAY_MS  10
#define MEASURE_DELAY_MS 80

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

static int i2c_write(int fd, const uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, len) == (ssize_t)len) return 0;
        fprintf(stderr, "I2C write failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        sleep_ms(RETRY_DELAY_MS);
    }
    return -1;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        ssize_t n = read(fd, buf, len);
        if (n == (ssize_t)len) return 0;
        fprintf(stderr, "I2C read failed (attempt %d/%d): got %zd, expected %zu: %s\n",
                attempt + 1, MAX_RETRIES, n, len, strerror(errno));
        sleep_ms(RETRY_DELAY_MS);
    }
    return -1;
}

static int aht20_init(int fd) {
    uint8_t init_cmd[] = {0xBE, 0x08, 0x00};
    return i2c_write(fd, init_cmd, sizeof(init_cmd));
}

static int aht20_read_humidity(int fd, float *humidity) {
    uint8_t trigger_cmd[] = {0xAC, 0x33, 0x00};
    uint8_t data[6];

    if (i2c_write(fd, trigger_cmd, sizeof(trigger_cmd)) != 0) {
        fprintf(stderr, "Failed to trigger AHT20 measurement\n");
        return -1;
    }

    sleep_ms(MEASURE_DELAY_MS);

    if (i2c_read(fd, data, sizeof(data)) != 0) {
        fprintf(stderr, "Failed to read AHT20 data\n");
        return -1;
    }

    if ((data[0] & 0x18) != 0x00) {
        fprintf(stderr, "AHT20 status error: 0x%02X\n", data[0]);
        return -1;
    }

    uint32_t raw_h = ((uint32_t)data[1] << 12) |
                     ((uint32_t)data[2] << 4)  |
                     ((uint32_t)data[3] >> 4);
    *humidity = ((float)raw_h / 1048576.0f) * 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (aht20_init(i2c_fd) != 0) {
        fprintf(stderr, "AHT20 initialization failed (sensor may be absent)\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!relay) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay, "dehumidifier", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("AHT20 humidity monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        float humidity;
        if (aht20_read_humidity(i2c_fd, &humidity) == 0) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
            printf("[%s] Humidity: %.2f%%\n", ts, humidity);

            if (humidity > HUMIDITY_HIGH) {
                if (gpiod_line_set_value(relay, 1) < 0) {
                    fprintf(stderr, "Failed to set relay ON: %s\n", strerror(errno));
                } else {
                    printf("Dehumidifier ON\n");
                }
            } else if (humidity < HUMIDITY_LOW) {
                if (gpiod_line_set_value(relay, 0) < 0) {
                    fprintf(stderr, "Failed to set relay OFF: %s\n", strerror(errno));
                } else {
                    printf("Dehumidifier OFF\n");
                }
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep_ms(1000);
        }
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(relay, 0);
    gpiod_line_release(relay);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

