#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define READ_INTERVAL 60
#define MEASURE_HOLDING 0xE5
#define CONVERT_DELAY_MS 20

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        syslog(LOG_ERR, "I2C read reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write reg 0x%02X val 0x%02X failed: %s", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    uint8_t msb, lsb, checksum;

    if (i2c_write_reg8(fd, MEASURE_HOLDING, 0) < 0) {
        return -1;
    }

    usleep(CONVERT_DELAY_MS * 1000);

    if (i2c_read_reg8(fd, 0, &msb) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, 1, &lsb) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, 2, &checksum) < 0) {
        return -1;
    }

    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    uint8_t expected = (uint8_t)(raw >> 8);
    if (expected != checksum) {
        syslog(LOG_ERR, "CRC mismatch: expected 0x%02X, got 0x%02X", expected, checksum);
        return -1;
    }

    uint16_t humidity_raw = raw & 0xFFFC;
    *humidity = (float)humidity_raw / 65536.0f * 100.0f;
    return 0;
}

static int post_humidity(float humidity) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80);

    if (inet_pton(AF_INET, "93.184.216.34", &serv_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char json[128];
    int len = snprintf(json, sizeof(json), "{\"humidity\": %.2f}", humidity);
    if (len < 0 || len >= (int)sizeof(json)) {
        syslog(LOG_ERR, "JSON formatting failed");
        close(sockfd);
        return -1;
    }

    char request[256];
    len = snprintf(request, sizeof(request),
                   "POST %s HTTP/1.1\r\n"
                   "Host: api.example.com\r\n"
                   "Content-Type: application/json\r\n"
                   "Content-Length: %d\r\n"
                   "Connection: close\r\n"
                   "\r\n"
                   "%s",
                   API_ENDPOINT, len, json);
    if (len < 0 || len >= (int)sizeof(request)) {
        syslog(LOG_ERR, "Request formatting failed");
        close(sockfd);
        return -1;
    }

    if (write(sockfd, request, len) < 0) {
        syslog(LOG_ERR, "HTTP write failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char response[1024];
    ssize_t n = read(sockfd, response, sizeof(response) - 1);
    if (n < 0) {
        syslog(LOG_ERR, "HTTP read failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }
    response[n] = '\0';

    if (strstr(response, "200 OK") == NULL) {
        syslog(LOG_ERR, "HTTP POST failed: %s", response);
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main(void) {
    openlog("htu21d_humidity", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "HTU21D humidity monitor started");

    while (running) {
        float humidity;
        if (read_humidity(fd, &humidity) == 0) {
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (post_humidity(humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    close(fd);
    closelog();
    return 0;
}

