/*
 * logger.c — Raspberry Pi 4B daily CSV log of TMP117, AHT20, PIR motion.
 *
 * Build:  gcc -o logger logger.c -lgpiod -lrt
 * Run:    ./logger
 *
 * Hardware:
 *   TMP117  I2C 0x48, temperature register 0x00 (16-bit signed, big-endian)
 *   AHT20   I2C 0x38, init 0xBE 0x08 0x00, measure 0xAC 0x33 0x00
 *   PIR     GPIO 17 (libgpiod, gpiochip4)
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define TMP117_TEMP_REG 0x00
#define AHT20_ADDR     0x38
#define PIR_LINE       17
#define SAMPLE_SEC     1
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_cmd(int fd, uint8_t addr, const uint8_t *cmd, size_t len)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "I2C_SLAVE 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t addr, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "I2C_SLAVE 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* TMP117                                                             */
/* ------------------------------------------------------------------ */

static int read_tmp117(int fd, float *temp)
{
    int16_t raw;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg16(fd, TMP117_ADDR, TMP117_TEMP_REG, &raw) == 0) {
            *temp = (float)raw * 0.0078125f;
            return 0;
        }
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* AHT20                                                              */
/* ------------------------------------------------------------------ */

static int aht20_init(int fd)
{
    uint8_t init_cmd[] = {0xBE, 0x08, 0x00};
    return i2c_write_cmd(fd, AHT20_ADDR, init_cmd, sizeof(init_cmd));
}

static int aht20_measure(int fd, uint8_t *data)
{
    uint8_t meas_cmd[] = {0xAC, 0x33, 0x00};
    if (i2c_write_cmd(fd, AHT20_ADDR, meas_cmd, sizeof(meas_cmd)) < 0)
        return -1;
    usleep(80 * 1000); /* 80 ms max conversion time */
    if (read(fd, data, 7) != 7) {
        fprintf(stderr, "AHT20 read: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_aht20(int fd, float *hum, float *temp)
{
    uint8_t data[7];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (aht20_measure(fd, data) == 0) {
            if (data[0] & 0x80) { /* busy */
                usleep(100 * 1000);
                continue;
            }
            uint32_t hum_raw = ((uint32_t)data[1] << 12) |
                              ((uint32_t)data[2] << 4)  |
                              ((uint32_t)data[3] >> 4);
            uint32_t temp_raw = ((uint32_t)(data[3] & 0x0F) << 16) |
                                ((uint32_t)data[4] << 8) |
                                (uint32_t)data[5];
            *hum  = (float)hum_raw  * 100.0f / 0x100000;
            *temp = (float)temp_raw * 200.0f / 0x100000 - 50.0f;
            return 0;
        }
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* PIR (libgpiod)                                                     */
/* ------------------------------------------------------------------ */

static int read_pir(struct gpiod_line *line)
{
    int v = gpiod_line_get_value(line);
    if (v < 0)
        fprintf(stderr, "PIR read: %s\n", strerror(errno));
    return v;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_data(FILE *fp, float temp, float hum, int motion)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    /* Open GPIO chip and request PIR line */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    struct gpiod_line *pir = gpiod_chip_get_line(chip, PIR_LINE);
    if (!pir) {
        fprintf(stderr, "gpiod get line %d: %s\n", PIR_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_input(pir, "pir_logger") < 0) {
        fprintf(stderr, "gpiod request input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    /* Open log file (daily rotation at midnight) */
    time_t now = time(NULL);
    struct tm tm;
    localtime_r(&now, &tm);
    char filename[64];
    strftime(filename, sizeof(filename), "log_%Y-%m-%d.csv", &tm);
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen %s: %s\n", filename, strerror(errno));
        gpiod_line_release(pir);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    fflush(fp);

    /* Sensor presence checks */
    int tmp_ok = (read_tmp117(i2c_fd, NULL) == 0);
    int aht_ok = (read_aht20(i2c_fd, NULL, NULL) == 0);
    if (!tmp_ok)
        fprintf(stderr, "Warning: TMP117 not responding at 0x%02X\n", TMP117_ADDR);
    if (!aht_ok)
        fprintf(stderr, "Warning: AHT20 not responding at 0x%02X\n", AHT20_ADDR);

    /* Main loop */
    while (g_running) {
        float temp = 0.0f, hum = 0.0f;
        int motion = 0;
        int ok = 1;

        if (tmp_ok && read_tmp117(i2c_fd, &temp) < 0) {
            fprintf(stderr, "TMP117 read failed\n");
            ok = 0;
        }
        if (aht_ok && read_aht20(i2c_fd, &hum, &temp) < 0) {
            fprintf(stderr, "AHT20 read failed\n");
            ok = 0;
        }
        motion = read_pir(pir);

        if (ok)
            log_data(fp, temp, hum, motion);

        /* Daily rotation at midnight */
        time_t now = time(NULL);
        struct tm tm;
        localtime_r(&now, &tm);
        if (tm.tm_hour == 0 && tm.tm_min == 0 && tm.tm_sec == 0) {
            fclose(fp);
            strftime(filename, sizeof(filename), "log_%Y-%m-%d.csv", &tm);
            fp = fopen(filename, "a");
            if (!fp) {
                fprintf(stderr, "fopen %s: %s\n", filename, strerror(errno));
                g_running = 0;
            } else {
                fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
                fflush(fp);
            }
        }

        sleep(SAMPLE_SEC);
    }

    /* Cleanup */
    fclose(fp);
    gpiod_line_release(pir);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return 0;
}

