#include <errno.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24
#define POLL_INTERVAL_SEC 2
#define MOTOR_RUN_TIME_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static int motor_stop(struct gpiod_line *enable, struct gpiod_line *in1, struct gpiod_line *in2) {
    if (gpiod_line_set_value(in1, 0) < 0) {
        perror("Failed to set IN1 low");
        return -1;
    }
    if (gpiod_line_set_value(in2, 0) < 0) {
        perror("Failed to set IN2 low");
        return -1;
    }
    if (gpiod_line_set_value(enable, 0) < 0) {
        perror("Failed to set enable low");
        return -1;
    }
    return 0;
}

static int motor_run(struct gpiod_line *enable, struct gpiod_line *in1, struct gpiod_line *in2) {
    if (gpiod_line_set_value(enable, 1) < 0) {
        perror("Failed to set enable high");
        return -1;
    }
    if (gpiod_line_set_value(in1, 1) < 0) {
        perror("Failed to set IN1 high");
        return -1;
    }
    if (gpiod_line_set_value(in2, 0) < 0) {
        perror("Failed to set IN2 low");
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *enable_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open gpiochip4 (RPi5 default chip)");
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    enable_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (!rain_line || !enable_line || !in1_line || !in2_line) {
        perror("Failed to get GPIO lines");
        goto cleanup;
    }

    if (gpiod_line_request_input(rain_line, "rain_sensor") < 0) {
        perror("Failed to request rain sensor line as input");
        goto cleanup;
    }

    if (gpiod_line_request_output(enable_line, "motor_enable", 0) < 0) {
        perror("Failed to request enable line as output");
        goto cleanup;
    }

    if (gpiod_line_request_output(in1_line, "motor_in1", 0) < 0) {
        perror("Failed to request IN1 line as output");
        goto cleanup;
    }

    if (gpiod_line_request_output(in2_line, "motor_in2", 0) < 0) {
        perror("Failed to request IN2 line as output");
        goto cleanup;
    }

    log_event("Program started. Monitoring rain sensor on GPIO17.");

    while (program_running) {
        int rain_value = gpiod_line_get_value(rain_line);
        if (rain_value < 0) {
            perror("Failed to read rain sensor");
            log_event("Error reading rain sensor. Retrying in 2 seconds.");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (rain_value == 0) {
            log_event("Rain detected! Closing window.");
            if (motor_run(enable_line, in1_line, in2_line) < 0) {
                log_event("Error starting motor.");
            } else {
                for (int i = 0; i < MOTOR_RUN_TIME_SEC && program_running; i++) {
                    sleep(1);
                }
                if (motor_stop(enable_line, in1_line, in2_line) < 0) {
                    log_event("Error stopping motor.");
                } else {
                    log_event("Motor stopped. Window closed.");
                }
            }
        } else {
            log_event("No rain detected.");
        }

        if (program_running) {
            sleep(POLL_INTERVAL_SEC);
        }
    }

    log_event("Program exiting.");
    ret = EXIT_SUCCESS;

cleanup:
    if (enable_line) gpiod_line_release(enable_line);
    if (in1_line) gpiod_line_release(in1_line);
    if (in2_line) gpiod_line_release(in2_line);
    if (rain_line) gpiod_line_release(rain_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

