#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 500000  /* 500 ms */

/* Common-anode: 0 = full brightness, 255 = off */
#define COMMON_ANODE_SCALE 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read CPU load as a fraction (0.0 .. 1.0) since boot. */
static double read_cpu_load(void)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen(/proc/stat)");
        return 0.0;
    }

    unsigned long long user = 0, nice = 0, system = 0, idle = 0;
    unsigned long long iowait = 0, irq = 0, softirq = 0, steal = 0;

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        perror("fgets(/proc/stat)");
        fclose(fp);
        return 0.0;
    }
    fclose(fp);

    if (strncmp(line, "cpu ", 4) != 0)
        return 0.0;

    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal) < 8)
        return 0.0;

    static unsigned long long prev_user = 0, prev_nice = 0, prev_system = 0, prev_idle = 0;
    static unsigned long long prev_iowait = 0, prev_irq = 0, prev_softirq = 0, prev_steal = 0;
    static unsigned long long prev_total = 0;

    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal;

    if (prev_total == 0) {
        prev_user = user; prev_nice = nice; prev_system = system;
        prev_idle = idle; prev_iowait = iowait; prev_irq = irq;
        prev_softirq = softirq; prev_steal = steal; prev_total = total;
        return 0.0;
    }

    unsigned long long prev = prev_user + prev_nice + prev_system + prev_idle +
                             prev_iowait + prev_irq + prev_softirq + prev_steal;

    unsigned long long delta = total - prev;
    unsigned long long idle_delta = idle - prev_idle;

    double load = (double)delta / (double)(total - prev_idle);
    if (load < 0.0) load = 0.0;
    if (load > 1.0) load = 1.0;

    prev_user = user; prev_nice = nice; prev_system = system;
    prev_idle = idle; prev_iowait = iowait; prev_irq = irq;
    prev_softirq = softirq; prev_steal = steal; prev_total = total;

    return load;
}

/* Map CPU load (0.0 .. 1.0) to RGB (0 .. 255) values for a common-anode LED. */
static void cpu_load_to_rgb(double load, int *r, int *g, int *b)
{
    if (load <= 0.5) {
        *r = 0;
        *g = (int)((load / 0.5) * 255.0);
        *b = 255;
    } else {
        *r = (int)(((load - 0.5) / 0.5) * 255.0);
        *g = 255;
        *b = 255 - (int)(((load - 0.5) / 0.5) * 255.0);
    }
}

static void set_led_color(int r, int g, int b)
{
    int rp = r * COMMON_ANODE_SCALE;
    int gp = g * COMMON_ANODE_SCALE;
    int bp = b * COMMON_ANODE_SCALE;

    if (rp > PWM_RANGE) rp = PWM_RANGE;
    if (gp > PWM_RANGE) gp = PWM_RANGE;
    if (bp > PWM_RANGE) bp = PWM_RANGE;

    gpioPWM(RED_PIN,   PWM_RANGE - rp);
    gpioPWM(GREEN_PIN, PWM_RANGE - gp);
    gpioPWM(BLUE_PIN,  PWM_RANGE - bp);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    gpioSetPWMrange(RED_PIN,   PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN,  PWM_RANGE);

    /* Start with LED off (common-anode: 255 = off) */
    gpioPWM(RED_PIN,   PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN,  PWM_RANGE);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct timespec sleep_time = {0, SAMPLE_INTERVAL_US * 1000};

    while (g_running) {
        double load = read_cpu_load();
        int r, g, b;
        cpu_load_to_rgb(load, &r, &g, &b);
        set_led_color(r, g, b);
        nanosleep(&sleep_time, NULL);
    }

    /* Turn LED off before exiting */
    gpioPWM(RED_PIN,   PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN,  PWM_RANGE);
    gpioTerminate();
    return EXIT_SUCCESS;
}

