    unsigned long long delta = total - prev;
    unsigned long long idle_delta = idle - prev_idle;

    double load = (double)delta / (double)(total - prev_idle);
    if (load < 0.0) load = 0.0;
    if (load > 1.0) load = 1.0;

    prev_user = user; prev_nice = nice; prev_system = system;
    prev_idle = idle; prev_iowait = iowait; prev_irq = irq;
    prev_softirq = softirq; prev_steal = steal; prev_total = total;

    return load;
}

/* Map CPU load (0.0 .. 1.0) to RGB (0 .. 255) values for a common-anode LED. */
static void cpu_load_to_rgb(double load, int *r, int *g, int *b)
{
    if (load <= 0.5) {
        *r = 0;
        *g = (int)((load / 0.5) * 255.0);
        *b = 255;
    } else {
        *r = (int)(((load - 0.5) / 0.5) * 255.0);
        *g = 255;
        *b = 255 - (int)(((load - 0.5) / 0.5) * 255.0);
    }
}

static void set_led_color(int r, int g, int b)
{
    int rp = r * COMMON_ANODE_SCALE;
    int gp = g * COMMON_ANODE_SCALE;
    int bp = b * COMMON_ANODE_SCALE;

    if (rp > PWM_RANGE) rp = PWM_RANGE;
    if (gp > PWM_RANGE) gp = PWM_RANGE;
    if (bp > PWM_RANGE) bp = PWM_RANGE;

    gpioPWM(RED_PIN,   PWM_RANGE - rp);
    gpioPWM(GREEN_PIN, PWM_RANGE - gp);
    gpioPWM(BLUE_PIN,  PWM_RANGE - bp);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    gpioSetPWMrange(RED_PIN,   PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN,  PWM_RANGE);

    /* Start with LED off (common-anode: 255 = off) */
    gpioPWM(RED_PIN,   PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN,  PWM_RANGE);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct timespec sleep_time = {0, SAMPLE_INTERVAL_US * 1000};

    while (g_running) {
        double load = read_cpu_load();
        int r, g, b;
        cpu_load_to_rgb(load, &r, &g, &b);
        set_led_color(r, g, b);
        nanosleep(&sleep_time, NULL);
    }

    /* Turn LED off before exiting */
    gpioPWM(RED_PIN,   PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN,  PWM_RANGE);
    gpioTerminate();
    return EXIT_SUCCESS;
}

