#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FAN_GPIO        18
#define SPI_CHANNEL     0
#define SPI_SPEED       500000
#define SPI_MODE        0
#define PWM_FREQUENCY   1000
#define PWM_RANGE       255
#define BUFFER_SIZE     20
#define SAMPLE_INTERVAL 1.0

#define TEMP_MIN        25.0
#define TEMP_MED        40.0
#define TEMP_MAX        60.0

typedef struct {
    time_t timestamp;
    float  temperature;
    int    duty_cycle;
} TemperatureReading;

static TemperatureReading temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_max31855(float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    int ret = spiXfer(spi_handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        if (raw & 0x00000001) fprintf(stderr, "MAX31855 fault: Open circuit\n");
        if (raw & 0x00000002) fprintf(stderr, "MAX31855 fault: Short to GND\n");
        if (raw & 0x00000004) fprintf(stderr, "MAX31855 fault: Short to VCC\n");
        return -1;
    }

    int16_t thermocouple_temp = (int16_t)(raw >> 18);
    *temperature = thermocouple_temp * 0.25f;
    return 0;
}

static int calculate_duty_cycle(float temperature) {
    if (temperature < TEMP_MIN) return 0;
    if (temperature < TEMP_MED) return (int)((temperature - TEMP_MIN) * 50.0f / (TEMP_MED - TEMP_MIN));
    if (temperature < TEMP_MAX) return 50 + (int)((temperature - TEMP_MED) * 150.0f / (TEMP_MAX - TEMP_MED));
    return 255;
}

static void update_fan(float temperature) {
    int duty = calculate_duty_cycle(temperature);
    if (gpioPWM(FAN_GPIO, duty) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle to %d\n", duty);
    }
}

static void log_temperature(float temperature, int duty_cycle) {
    time_t now = time(NULL);
    temperature_buffer[buffer_index].timestamp = now;
    temperature_buffer[buffer_index].temperature = temperature;
    temperature_buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void) {
    printf("\n--- Temperature Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        char time_str[32];
        struct tm *tm_info = localtime(&temperature_buffer[i].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            snprintf(time_str, sizeof(time_str), "INVALID");
        }
        printf("[%s] Temp: %.2f C, Duty: %d\n",
               time_str, temperature_buffer[i].temperature, temperature_buffer[i].duty_cycle);
    }
    printf("--- End of Log Buffer ---\n\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
