        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize PWM duty cycle to 0\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Temperature-controlled fan started. Press Ctrl+C to exit.\n");

