#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define READ_INTERVAL_SEC 5

#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_STATUS_REG 0x03

#define MAX31865_CONFIG_VBIAS 0x80
#define MAX31865_CONFIG_3WIRE 0x40
#define MAX31865_CONFIG_FAULT_AUTO 0x02
#define MAX31865_CONFIG_FAULT_CLEAR 0x01

#define MAX31865_FAULT_OPEN 0x01
#define MAX31865_FAULT_GND 0x02
#define MAX31865_FAULT_RTDIN 0x04
#define MAX31865_FAULT_HOT 0x08
#define MAX31865_FAULT_COLD 0x10

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS line: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS line: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int max31865_write_register(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = {0};
    return spi_transfer(tx, rx, 2);
}

static int max31865_read_register(uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = {0};
    if (spi_transfer(tx, rx, 2) < 0) {
        return -1;
    }
    *value = rx[1];
    return 0;
}

static int max31865_init(void) {
    uint8_t config = MAX31865_CONFIG_VBIAS | MAX31865_CONFIG_3WIRE | MAX31865_CONFIG_FAULT_AUTO;
    if (max31865_write_register(MAX31865_CONFIG_REG, config) < 0) {
        fprintf(stderr, "Failed to write MAX31865 config register\n");
        return -1;
    }
    return 0;
}

static int max31865_read_rtd(float *temperature) {
    uint8_t msb, lsb, fault_status;

    if (max31865_read_register(MAX31865_RTD_MSB_REG, &msb) < 0) {
        return -1;
    }
    if (max31865_read_register(MAX31865_RTD_LSB_REG, &lsb) < 0) {
        return -1;
    }
    if (max31865_read_register(MAX31865_FAULT_STATUS_REG, &fault_status) < 0) {
        return -1;
    }

    if (fault_status & MAX31865_FAULT_OPEN) {
        fprintf(stderr, "MAX31865 fault: Open circuit\n");
        return -2;
    }
    if (fault_status & MAX31865_FAULT_GND) {
        fprintf(stderr, "MAX31865 fault: Short to GND\n");
        return -2;
    }
    if (fault_status & MAX31865_FAULT_RTDIN) {
        fprintf(stderr, "MAX31865 fault: Short to VIN\n");
        return -2;
    }

    uint16_t rtd_raw = ((uint16_t)msb << 8) | lsb;
    rtd_raw >>= 1;

    if (rtd_raw == 0) {
        fprintf(stderr, "MAX31865 fault: RTD register is 0\n");
        return -2;
    }

    float rtd_resistance = (float)rtd_raw * 0.00385;
    float Z_a = 100.0;
    float Z_b = 50.0;
    float Z_ref = 430.0;
    float R_a = 10000.0;
    float R_b = 10000.0;
    float R_0 = 100.0;

    float Z_therm = Z_a + (Z_b * rtd_resistance / R_a);
    float Z_0 = Z_therm - rtd_resistance;
    float Z_0_ratio = Z_0 / Z_ref;

    float temp = (Z_0_ratio) / (Z_0_ratio + 1.0 / (R_b / R_0));
    *temperature = temp * 100.0;

    return 0;
}

static void log_data(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        perror("Failed to get CS line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "max31865-cs", 1) < 0) {
        perror("Failed to request CS line as output");
        cleanup();
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
        return 1;
    }

    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        cleanup();
        return 1;
    }

    if (max31865_init() < 0) {
        fprintf(stderr, "MAX31865 initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    fprintf(log_file, "Timestamp,Temperature (C)\n");

    while (program_running) {
        float temperature;
        int result = max31865_read_rtd(&temperature);

        if (result == 0) {
            log_data(temperature);
        } else if (result == -2) {
            fprintf(stderr, "Sensor fault detected, skipping logging\n");
        } else {
            fprintf(stderr, "SPI communication error, skipping logging\n");
        }

        sleep(READ_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

