#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_ID 0xD0
#define BMP180_CHIP_ID 0x55

#define ALERT_GPIO 24
#define I2C_BUS 1
#define TIMER_INTERVAL_MS 50
#define BUFFER_SIZE 60
#define PRESSURE_THRESHOLD 5.0f

#define OSS 0

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

typedef struct {
    time_t timestamp;
    float pressure;
} data_point_t;

static data_point_t data_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static bmp180_cal_t cal;
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(int handle, bmp180_cal_t *c) {
    uint8_t buf[22];
    if (i2cReadI2CBlockData(handle, BMP180_REG_CAL_AC1, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    c->ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    c->ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    c->ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    c->ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    c->ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    c->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    c->b1 = (int16_t)((buf[12] << 8) | buf[13]);
    c->b2 = (int16_t)((buf[14] << 8) | buf[15]);
    c->mb = (int16_t)((buf[16] << 8) | buf[17]);
    c->mc = (int16_t)((buf[18] << 8) | buf[19]);
    c->md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(handle, BMP180_REG_LSB);
    if (msb < 0 || lsb < 0) return -1;
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(handle, BMP180_REG_XLSB);
    if (msb < 0 || lsb < 0 || xlsb < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

static float calculate_pressure(int32_t ut, int32_t up, const bmp180_cal_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)c->ac1 * 4 + x3) << OSS) + 2) >> 2);
    x1 = ((int32_t)c->ac3 * b6) >> 13;
    x2 = ((int32_t)c->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p / 100.0f;
}

static float calculate_average_pressure(void) {
    if (buffer_count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) sum += data_buffer[i].pressure;
    return sum / buffer_count;
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int32_t ut, up;
    if (read_raw_temperature(i2c_handle, &ut) < 0) {
        fprintf(stderr, "Error: Failed to read temperature\n");
        return;
    }
    if (read_raw_pressure(i2c_handle, &up) < 0) {
        fprintf(stderr, "Error: Failed to read pressure\n");
        return;
    }
    float pressure = calculate_pressure(ut, up, &cal);
    data_buffer[buffer_index].timestamp = time(NULL);
    data_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
    float avg = calculate_average_pressure();
    if (buffer_count > 0 && fabsf(pressure - avg) > PRESSURE_THRESHOLD) {
        fprintf(stderr, "ALERT: Pressure deviation %.2f hPa (current %.2f, avg %.2f)\n", pressure - avg, pressure, avg);
        gpioWrite(ALERT_GPIO, 1);
        gpioDelay(100000);
        gpioWrite(ALERT_GPIO, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }
    int id = i2cReadByteData(i2c_handle, BMP180_REG_ID);
    if (id != BMP180_CHIP_ID) {
        fprintf(stderr, "Error: BMP180 not detected (ID=0x%02X, expected 0x%02X)\n", id, BMP180_CHIP_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration(i2c_handle, &cal) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL_MS, timer_callback, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set timer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");
    while (running) gpioDelay(100000);
    gpioSetTimerFuncEx(0, TIMER_INTERVAL_MS, NULL, NULL);
    gpioWrite(ALERT_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return 0;
}

