static int read_raw_temperature(int handle, int32_t *ut) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x2E};
    if (i2cWriteDevice(handle, cmd, 2) != 0) return -1;
    gpioDelay(5000);
    char reg = BMP180_REG_MSB;
    if (i2cWriteDevice(handle, &reg, 1) != 0) return -1;
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int oss, int32_t *up) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x34 + (oss << 6)};
    if (i2cWriteDevice(handle, cmd, 2) != 0) return -1;
    gpioDelay(2000 + (3000 << oss));
    char reg = BMP180_REG_MSB;
    if (i2cWriteDevice(handle, &reg, 1) != 0) return -1;
    char buf[3];
    if (i2cReadDevice(handle, buf, 3) != 3) return -1;
    *up = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - oss);
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *cal) {
    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    return x1 + x2;
}

static float calculate_temperature(int32_t ut, const bmp180_cal_t *cal) {
    int32_t b5 = compute_b5(ut, cal);
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t ut, const bmp180_cal_t *cal) {
    int32_t b5 = compute_b5(ut, cal);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
