    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    return (p + ((x1 + x2 + 3791) >> 4)) / 100.0f;
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int32_t ut, up;
