#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQ 25000
#define PWM_RANGE 255
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature file");
        return -1;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Failed to parse temperature\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_milli;
}

static int calculate_duty_cycle(int temp_milli) {
    float temp_c = temp_milli / 1000.0f;
    if (temp_c < MIN_TEMP) temp_c = MIN_TEMP;
    if (temp_c > MAX_TEMP) temp_c = MAX_TEMP;
    float duty = (temp_c - MIN_TEMP) / (MAX_TEMP - MIN_TEMP) * PWM_RANGE;
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    return (int)duty;
}

static void log_data(int temp_milli, int duty) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    float temp_c = temp_milli / 1000.0f;
    fprintf(log_fp, "%s, Temp: %.2f C, Duty: %d\n", ts, temp_c, duty);
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log file");
        gpioTerminate();
        return 1;
    }

    while (running) {
        int temp_milli = read_cpu_temp();
        if (temp_milli < 0) {
            fprintf(stderr, "Temperature read failed, skipping cycle\n");
            sleep(POLL_INTERVAL);
            continue;
        }

        int duty = calculate_duty_cycle(temp_milli);
        if (gpioPWM(FAN_GPIO, duty) != 0) {
            fprintf(stderr, "gpioPWM failed\n");
        }

        log_data(temp_milli, duty);
        sleep(POLL_INTERVAL);
    }

    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    if (log_fp) fclose(log_fp);
    return 0;
}

