#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_BUS        "/dev/i2c-1"
#define BMP280_ADDR_1         0x76
#define BMP280_ADDR_2         0x77
#define BMP280_CHIP_ID_REG    0xD0
#define BMP280_CHIP_ID        0x58
#define BMP280_RESET_REG      0xE0
#define BMP280_RESET_CMD      0xB6
#define BMP280_STATUS_REG     0xF3
#define BMP280_CTRL_MEAS_REG  0xF4
#define BMP280_DATA_REG       0xF7
#define BMP280_CALIB_REG      0x88
#define BMP280_CALIB_LEN      24

#define LOG_FILE             "weather_data.txt"
#define SAMPLE_INTERVAL_SEC  5
#define MEAS_TIMEOUT_MS      100

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_u16_le(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (i2c_read(fd, reg, buf, 2) < 0) return -1;
    *out = (uint16_t)buf[1] << 8 | buf[0];
    return 0;
}

static int i2c_read_u24_le(int fd, uint8_t reg, uint32_t *out) {
    uint8_t buf[3];
    if (i2c_read(fd, reg, buf, 3) < 0) return -1;
    *out = (uint32_t)buf[2] << 16 | (uint32_t)buf[1] << 8 | buf[0];
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t chip_id;
    if (i2c_read(fd, BMP280_CHIP_ID_REG, &chip_id, 1) < 0) return -1;
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: got 0x%02X, expected 0x%02X\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write(fd, BMP280_RESET_REG, BMP280_RESET_CMD) < 0) return -1;
    usleep(5000);
    return 0;
}

static int bmp280_read_calibration(int fd, int32_t *t_fine) {
    uint8_t cal[BMP280_CALIB_LEN];
    if (i2c_read(fd, BMP280_CALIB_REG, cal, BMP280_CALIB_LEN) < 0) return -1;
    uint16_t dig_T1 = (uint16_t)cal[0] | ((uint16_t)cal[1] << 8);
    int16_t  dig_T2 = (int16_t)((uint16_t)cal[2] | ((uint16_t)cal[3] << 8));
    int16_t  dig_T3 = (int16_t)((uint16_t)cal[4] | ((uint16_t)cal[5] << 8));
    uint16_t dig_P1 = (uint16_t)cal[6] | ((uint16_t)cal[7] << 8);
    int16_t  dig_P2 = (int16_t)((uint16_t)cal[8] | ((uint16_t)cal[9] << 8));
    int16_t  dig_P3 = (int16_t)((uint16_t)cal[10] | ((uint16_t)cal[11] << 8));
    int16_t  dig_P4 = (int16_t)((uint16_t)cal[12] | ((uint16_t)cal[13] << 8));
    int16_t  dig_P5 = (int16_t)((uint16_t)cal[14] | ((uint16_t)cal[15] << 8));
    int16_t  dig_P6 = (int16_t)((uint16_t)cal[16] | ((uint16_t)cal[17] << 8));
    int16_t  dig_P7 = (int16_t)((uint16_t)cal[18] | ((uint16_t)cal[19] << 8));
    int16_t  dig_P8 = (int16_t)((uint16_t)cal[20] | ((uint16_t)cal[21] << 8));
    int16_t  dig_P9 = (int16_t)((uint16_t)cal[22] | ((uint16_t)cal[23] << 8));
    (void)dig_T1; (void)dig_T2; (void)dig_T3;
    (void)dig_P1; (void)dig_P2; (void)dig_P3; (void)dig_P4; (void)dig_P5;
    (void)dig_P6; (void)dig_P7; (void)dig_P8; (void)dig_P9;
    *t_fine = 0;
    return 0;
}

static int bmp280_read_raw(int fd, int32_t *raw_t, int32_t *raw_p) {
    if (i2c_write(fd, BMP280_CTRL_MEAS_REG, 0x27) < 0) return -1;
    for (int i = 0; i < MEAS_TIMEOUT_MS; i++) {
        uint8_t status;
        if (i2c_read(fd, BMP280_STATUS_REG, &status, 1) < 0) return -1;
        if ((status & 0x08) == 0) break;
        usleep(1000);
        if (i == MEAS_TIMEOUT_MS - 1) {
            fprintf(stderr, "BMP280 measurement timeout\n");
            return -1;
        }
    }
