    if (i2c_read(fd, BMP280_DATA_REG, data, 6) < 0) return -1;
    *raw_p = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    *raw_t = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);
    return 0;
}

static double compensate_temp(int32_t raw, int32_t *t_fine) {
    double v1 = ((double)raw / 16384.0 - (double)t_fine[0] / 1024.0) * (double)t_fine[1];
    double v2 = ((double)raw / 131072.0 - (double)t_fine[0] / 8192.0) *
                ((double)raw / 131072.0 - (double)t_fine[0] / 8192.0) * (double)t_fine[2];
    *t_fine = (int32_t)(v1 + v2);
    return v1 + v2;
}

static double compensate_press(int32_t raw, int32_t t_fine) {
    double v1 = (double)t_fine / 2.0 - 64000.0;
    double v2 = v1 * v1 * (double)t_fine[3] / 32768.0;
    v2 = v2 + v1 * (double)t_fine[4] * 2.0;
    v2 = v2 / 4.0 + (double)t_fine[5] * 65536.0;
    double p = 1048576.0 - (double)raw;
    p = (p - v2) * 6250.0 / 32768.0;
    v1 = (double)t_fine[6] * p * p / 2147483648.0;
    v2 = p * (double)t_fine[7] / 32768.0;
    p = p + (v1 + v2 + (double)t_fine[8]) / 16.0;
    return p;
}

static int log_data(const char *ts, double temp, double press) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%s, Temperature: %.2f C, Pressure: %.2f hPa\n", ts, temp, press) < 0) {
        fprintf(stderr, "Failed to write to %s: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(BMP280_I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", BMP280_I2C_BUS, strerror(errno));
        return 1;
    }

    int addr = BMP280_ADDR_1;
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        addr = BMP280_ADDR_2;
        if (ioctl(fd, I2C_SLAVE, addr) < 0) {
            fprintf(stderr, "Cannot set I2C slave 0x%02X or 0x%02X: %s\n",
                    BMP280_ADDR_1, BMP280_ADDR_2, strerror(errno));
            close(fd);
            return 1;
        }
    }

    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "BMP280 init failed at 0x%02X\n", addr);
        close(fd);
        return 1;
    }

    int32_t t_fine[9];
    if (bmp280_read_calibration(fd, t_fine) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(fd);
        return 1;
    }

    while (g_running) {
        int32_t raw_t, raw_p;
        if (bmp280_read_raw(fd, &raw_t, &raw_p) < 0) {
            fprintf(stderr, "Read error — continuing\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        double temp = compensate_temp(raw_t, t_fine) / 100.0;
        double press = compensate_press(raw_p, t_fine) / 256.0;

        time_t now = time(NULL);
        struct tm tmv;
        char ts[32];
        if (localtime_r(&now, &tmv) && strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv) > 0) {
            if (log_data(ts, temp, press) < 0) {
                fprintf(stderr, "Logging failed\n");
            }
        } else {
            fprintf(stderr, "Timestamp failed\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    fprintf(stderr, "Exiting cleanly\n");
    close(fd);
    return 0;
}

