#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define LM75_ADDR      0x48
#define TEMP_REG       0x00
#define GPIO_CHIP      "gpiochip4"
#define GPIO_OFFSET    18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD 28.0f
#define POLL_INTERVAL  1
#define I2C_RETRIES    3

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
    pthread_mutex_t mutex;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_temperature(int fd, float *temp) {
    uint8_t reg = TEMP_REG;
    uint8_t data[2];

    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write error (attempt %d): %s\n", attempt + 1, strerror(errno));
            usleep(10000);
            continue;
        }
        if (read(fd, data, 2) != 2) {
            fprintf(stderr, "I2C read error (attempt %d): %s\n", attempt + 1, strerror(errno));
            usleep(10000);
            continue;
        }
        int16_t raw = (int16_t)((data[0] << 8) | data[1]);
        raw >>= 5;
        *temp = (float)raw / 256.0f;
        return 0;
    }
    return -1;
}

static void buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

static void buffer_add(CircularBuffer *cb, float value) {
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
    pthread_mutex_unlock(&cb->mutex);
}

static float buffer_average(CircularBuffer *cb) {
    float sum = 0.0f;
    int count;
    pthread_mutex_lock(&cb->mutex);
    count = cb->count;
    for (int i = 0; i < count; i++) {
        sum += cb->buffer[i];
    }
    pthread_mutex_unlock(&cb->mutex);
    return (count > 0) ? (sum / (float)count) : 0.0f;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_OFFSET);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_OFFSET, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "lm75_monitor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_OFFSET, strerror(errno));
        cleanup();
        return 1;
    }

    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        cleanup();
        return 1;
    }

    CircularBuffer temp_buffer;
    buffer_init(&temp_buffer);

    while (running) {
        float temperature;
        if (read_temperature(i2c_fd, &temperature) == 0) {
            buffer_add(&temp_buffer, temperature);
            float avg = buffer_average(&temp_buffer);
            printf("Temperature: %.2f C, Average: %.2f C\n", temperature, avg);

            if (temperature > TEMP_THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        } else {
            fprintf(stderr, "Failed to read temperature after retries. Re-initializing I2C.\n");
            close(i2c_fd);
            i2c_fd = -1;
            sleep(1);
            i2c_fd = init_i2c();
            if (i2c_fd < 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                break;
            }
        }
        sleep(POLL_INTERVAL);
    }

    cleanup();
    return 0;
}

