#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>
#include <jansson.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0x01  /* mode 1, CE0 active low */
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_STATUS_REG 0x07
#define MAX31865_FAULT_OPEN 0x01
#define MAX31865_FAULT_GND 0x02
#define MAX31865_FAULT_VBIAS 0x04
#define MAX31865_FAULT_HOT 0x08
#define MAX31865_FAULT_COLD 0x10
#define MAX31865_FAULT_RANGE 0x20
#define MAX31865_FAULT_MASK 0x3F
#define R_REF 430.0
#define R0 100.0
#define PT100_A 0.0039083
#define PT100_B -0.0000005775
#define PT100_T0 0.0
#define CONFIG_FILE "config.json"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static double target_temperature = 25.0;
static double Kp = 1.0;
static double Ki = 0.1;
static double Kd = 0.01;
static double integral = 0.0;
static double previous_error = 0.0;
static double current_temperature = 25.0;
static int heater_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(void) {
    json_t *root = json_load_file(CONFIG_FILE, 0, NULL);
    if (!root) {
        fprintf(stderr, "Warning: could not load config file '%s', using defaults.\n", CONFIG_FILE);
        return 0;
    }
    json_t *t = json_object_get(root, "target_temperature");
    if (t) target_temperature = json_number_value(t);
    json_t *kp = json_object_get(root, "Kp");
    if (kp) Kp = json_number_value(kp);
    json_t *ki = json_object_get(root, "Ki");
    if (ki) Ki = json_number_value(ki);
    json_t *kd = json_object_get(root, "Kd");
    if (kd) Kd = json_number_value(kd);
    json_decref(root);
    return 0;
}

static int init_max31865(void) {
    char tx[2] = { MAX31865_CONFIG_REG, 0xC1 };
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "Error: SPI write to MAX31865 config register failed.\n");
        return -1;
    }
    return 0;
}

static int read_max31865(double *temperature) {
    char tx[3] = { MAX31865_RTD_MSB_REG, 0x00, 0x00 };
    char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI read from MAX31865 failed.\n");
        return -1;
    }
    int msb = rx[1];
    int lsb = rx[2];
    if (msb & 0x01) {
        char ftx[2] = { MAX31865_FAULT_STATUS_REG, 0x00 };
        char frx[2] = {0};
        if (spiXfer(spi_handle, ftx, frx, 2) != 2) {
            fprintf(stderr, "Error: SPI read fault status failed.\n");
            return -1;
        }
        int fault = frx[1] & MAX31865_FAULT_MASK;
        if (fault & MAX31865_FAULT_OPEN) fprintf(stderr, "MAX31865 fault: open circuit\n");
        if (fault & MAX31865_FAULT_GND) fprintf(stderr, "MAX31865 fault: GND fault\n");
        if (fault & MAX31865_FAULT_VBIAS) fprintf(stderr, "MAX31865 fault: VBIAS fault\n");
        if (fault & MAX31865_FAULT_HOT) fprintf(stderr, "MAX31865 fault: hot-junction fault\n");
        if (fault & MAX31865_FAULT_COLD) fprintf(stderr, "MAX31865 fault: cold-junction fault\n");
        if (fault & MAX31865_FAULT_RANGE) fprintf(stderr, "MAX31865 fault: RTD range fault\n");
        return -1;
    }
    int rtd_code = ((msb & 0x7F) << 8) | lsb;
    double rtd_resistance = (rtd_code / 32768.0) * R_REF;
    double t = PT100_T0 - (rtd_resistance / R0 - 1.0) / (PT100_A + PT100_B * PT100_T0);
    *temperature = t;
    return 0;
}

static int set_heater_pwm(int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    int duty = (duty_percent * PWM_RANGE) / 100;
    if (gpioPWM(HEATER_GPIO, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on GPIO %d.\n", HEATER_GPIO);
        return -1;
    }
    return 0;
}

static void pid_control(double setpoint, double *current_temp) {
    double error = setpoint - *current_temp;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    if (output < 0) output = 0;
    if (output > 100) output = 100;
    int duty = (int)(output + 0.5);
    if (set_heater_pwm(duty) == 0) {
        heater_state = duty > 0 ? 1 : 0;
    }
    previous_error = error;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        set_heater_pwm(0);
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    read_config();
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, speed %d).\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return 1;
    }
    if (init_max31865() != 0) {
        fprintf(stderr, "Error: MAX31865 initialisation failed.\n");
        cleanup();
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    set_heater_pwm(0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (running) {
        double temp;
        if (read_max31865(&temp) == 0) {
            current_temperature = temp;
            pid_control(target_temperature, &current_temperature);
        } else {
            fprintf(stderr, "Error: MAX31865 read failed, shutoff.\n");
            set_heater_pwm(0);
            break;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    cleanup();
    return 0;
}

