#include <unistd.h>
#include <fcntl.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "breach_log.txt"

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34
#define BMP180_CMD_PRESSURE1 0x74
#define BMP180_CMD_PRESSURE2 0xB4
#define BMP180_CMD_PRESSURE3 0xF4

#define TEMP_THRESHOLD 30.0
#define PRESSURE_THRESHOLD 950.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    for (int attempt = 0; attempt < 3; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        if (errno == EINTR) continue;
        usleep(10000);
    }
    return -1;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < 3; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            if (errno == EINTR) continue;
            usleep(10000);
            continue;
        }
        if (read(fd, buf, len) == len) return 0;
        if (errno == EINTR) continue;
        usleep(10000);
    }
    return -1;
}

static int read_calibration_data(int fd, int16_t *ac1, int16_t *ac2, int16_t *ac3,
                                 uint16_t *ac4, uint16_t *ac5, uint16_t *ac6,
                                 int16_t *b1, int16_t *b2, int16_t *mb, int16_t *mc, int16_t *md) {
    uint8_t buf[22];
    if (i2c_read_bytes(fd, 0xAA, buf, 22) != 0) return -1;

    *ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    *ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    *ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    *ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    *ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    *ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    *b1  = (int16_t)((buf[12] << 8) | buf[13]);
