    (void)sig;
    g_running = 0;
}

static void buffer_init(CircularBuffer *buf) {
    buf->head = 0;
    buf->count = 0;
}

static void buffer_add(CircularBuffer *buf, SensorData sd) {
    buf->data[buf->head] = sd;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(handle, reg, val) < 0) return -1;
    return 0;
}

static int read_calibration(int handle) {
    uint8_t buf[22];
    if (i2c_read_block(handle, BMP180_REG_CAL_START, buf, sizeof(buf)) < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        return -1;
    }
    g_ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    g_ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    g_ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    g_ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    g_ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    g_ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    g_b1  = (int16_t)((buf[12] << 8) | buf[13]);
    g_b2  = (int16_t)((buf[14] << 8) | buf[15]);
    g_mb  = (int16_t)((buf[16] << 8) | buf[17]);
    g_mc  = (int16_t)((buf[18] << 8) | buf[19]);
    g_md  = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    if (i2c_write_byte(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(BMP180_TEMP_CONV_US);
    uint8_t buf[2];
    if (i2c_read_block(handle, BMP180_REG_DATA, buf, 2) < 0) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    if (i2c_write_byte(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESS_OSS0) < 0) return -1;
    gpioDelay(BMP180_PRESS_CONV_US);
    uint8_t buf[3];
    if (i2c_read_block(handle, BMP180_REG_DATA, buf, 3) < 0) return -1;
    *up = ((int32_t)(buf[0] << 16) | (int32_t)(buf[1] << 8) | buf[2]) >> 8;
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)g_ac6) * (int32_t)g_ac5) >> 15;
    int32_t x2 = ((int32_t)g_mc << 11) / (x1 + g_md);
    return x1 + x2;
}

static float calculate_temperature(int32_t ut) {
    int32_t b5 = compute_b5(ut);
    return (float)((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t ut) {
    int32_t b5 = compute_b5(ut);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)g_b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)g_ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)g_ac1 * 4 + x3) << 0) + 2) >> 2);
    uint32_t b4 = ((uint32_t)g_ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000UL) p = (b7 * 2) / b4;
    else                   p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (float)p;
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int32_t ut, up;
    if (read_raw_temperature(g_i2c_handle, &ut) < 0) {
        fprintf(stderr, "Temperature read error\n");
        return;
    }
    if (read_raw_pressure(g_i2c_handle, &up) < 0) {
        fprintf(stderr, "Pressure read error\n");
        return;
    }
    float temp = calculate_temperature(ut);
    float pres = calculate_pressure(up, ut);
    SensorData sd;
    sd.timestamp = time(NULL);
    sd.temperature = temp;
    sd.pressure = pres;
    buffer_add(&g_buffer, sd);
    printf("Temp: %.2f C, Pressure: %.2f Pa\n", temp, pres);
    if (temp > TEMP_THRESHOLD_C) {
        if (!g_fan_state) {
            gpioWrite(FAN_GPIO, 1);
            g_fan_state = 1;
        }
    } else {
        if (g_fan_state) {
            gpioWrite(FAN_GPIO, 0);
            g_fan_state = 0;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    g_i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration(g_i2c_handle) < 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);
    buffer_init(&g_buffer);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, timer_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set timer\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    while (g_running) {
        gpioDelay(100000);
    }
    gpioWrite(FAN_GPIO, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

