#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO      17
#define SPI_CHANNEL      0
#define SPI_SPEED        2000000  /* 2 MHz */
#define SPI_FLAGS        0        /* Mode 0, active-low CE */
#define PWM_FREQUENCY    1000     /* 1 kHz */
#define PWM_RANGE        100      /* 0-100 duty */
#define MAX_DUTY         80       /* 80% */
#define TARGET_TEMP      25.0f
#define SAMPLE_PERIOD_S  1.0
#define LOG_FILE         "heater_log.csv"

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MAX31855 read                                                       */
/* ------------------------------------------------------------------ */
/*
 * MAX31855 32-bit SPI payload (MSB first):
 *   D[31:18]  14-bit signed thermocouple temp, bits 13:4
 *   D[15:4]   12-bit signed internal temp, bits 11:2
 *   D[3]      reserved
 *   D[2]      fault
 *   D[1]      open circuit
 *   D[0]      short to VCC
 *
 * Thermocouple temp:  (raw >> 4) & 0x3FFF, sign-extended 14-bit
 * Internal temp:      (raw >> 4) & 0x0FFF, sign-extended 12-bit
 */
static int read_max31855(float *temperature)
{
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    int ret = spiXfer(g_spi_handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    /* Fault bit (D2) */
    if (raw & 0x00000004) {
        if (raw & 0x00000001) {
            fprintf(stderr, "MAX31855 fault: short to VCC\n");
        } else if (raw & 0x00000002) {
            fprintf(stderr, "MAX31855 fault: open circuit\n");
        } else {
            fprintf(stderr, "MAX31855 fault: unknown\n");
        }
        return -1;
    }

    /* Thermocouple temperature: bits 31:18, 14-bit signed */
    int16_t therm_raw = (int16_t)((raw >> 4) & 0x3FFF);
    if (therm_raw & 0x2000) {
        therm_raw |= 0xC000;  /* sign-extend */
    }
    *temperature = (float)therm_raw * 0.25f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* PI controller                                                       */
/* ------------------------------------------------------------------ */
static float pi_controller(float setpoint, float actual,
                           float *integral, float *prev_error,
                           float kp, float ki, float dt)
{
    float error = setpoint - actual;
    *integral += error * dt;
    if (*integral > 100.0f)  *integral = 100.0f;
    if (*integral < -100.0f) *integral = -100.0f;

    float output = kp * error + ki * (*integral);

    /* Anti-windup: clamp integral if output is at its extreme */
    if (output > MAX_DUTY) {
        output = MAX_DUTY;
        *integral -= ki * dt;
    } else if (output < 0.0f) {
        output = 0.0f;
        *integral -= ki * dt;
    }

    *prev_error = error;
    return output;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float temperature, int duty_cycle)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(g_log_file, "%s,%.2f,%d\n", ts, temperature, duty_cycle);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure heater is off before terminating pigpio */
    gpioPWM(HEATER_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", HEATER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioPWM(HEATER_GPIO, 0);

    /* --- SPI setup --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Failed to open log file");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(g_log_file, "# timestamp,temperature_C,duty_cycle_pct\n");
    fflush(g_log_file);

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- PI controller state --- */
    float integral    = 0.0f;
    float prev_error  = 0.0f;
    float kp         = 1.0f;
    float ki         = 0.1f;
    float dt         = SAMPLE_PERIOD_S;

    /* --- Main loop --- */
    while (g_running) {
        float temperature = 0.0f;

        if (read_max31855(&temperature) != 0) {
            /* Sensor fault: turn heater off, log, continue */
            gpioPWM(HEATER_GPIO, 0);
            log_data(temperature, 0);
            time_sleep(SAMPLE_PERIOD_S);
            continue;
        }

        float duty = pi_controller(TARGET_TEMP, temperature,
                                    &integral, &prev_error, kp, ki, dt);

        int pwm = (int)(duty + 0.5f);
        if (pwm < 0)   pwm = 0;
        if (pwm > MAX_DUTY) pwm = MAX_DUTY;

        if (gpioPWM(HEATER_GPIO, pwm) != 0) {
            fprintf(stderr, "gpioPWM failed on GPIO%d\n", HEATER_GPIO);
        }

        log_data(temperature, pwm);
        time_sleep(SAMPLE_PERIOD_S);
    }

    /* --- Graceful shutdown --- */
    gpioPWM(HEATER_GPIO, 0);
    cleanup();
    return EXIT_SUCCESS;
}

