#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define PWM_RANGE 255
#define PWM_FREQ  1000
#define LOOP_US   500000  /* 0.5 s */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read CPU temperature in millidegrees from sysfs; returns 0 on success. */
static int read_cpu_temp(int *temp_millideg)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    char buf[32];
    size_t n = fread(buf, 1, sizeof(buf) - 1, fp);
    int err = ferror(fp);
    int feof = ferror(fp);
    fclose(fp);

    if (err) {
        fprintf(stderr, "Error reading %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }
    if (feof) {
        fprintf(stderr, "Short read from %s\n", TEMP_FILE);
        return -1;
    }
    buf[n] = '\0';

    char *endptr = NULL;
    long val = strtol(buf, &endptr, 10);
    if (endptr == buf || *endptr != '\n' && *endptr != '\0') {
        fprintf(stderr, "Invalid temperature data: '%s'\n", buf);
        return -1;
    }
    if (val < 0 || val > 200000) {
        fprintf(stderr, "Temperature out of plausible range: %ld m°C\n", val);
        return -1;
    }

    *temp_millideg = (int)val;
    return 0;
}

/* Map temperature (m°C) to RGB (0-255 each). Common-anode: 0 = off, 255 = full. */
static void temp_to_rgb(int temp_millideg, int *r, int *g, int *b)
{
    if (temp_millideg < 40000) {
        *r = 0; *g = 0; *b = 255;  /* Blue */
    } else if (temp_millideg < 60000) {
        *r = 0; *g = 255; *b = 0;  /* Green */
    } else {
        *r = 255; *g = 0; *b = 0;  /* Red */
