#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_US 1000000
#define DHT22_START_LOW_US 1000
#define DHT22_START_HIGH_US 30
#define DHT22_TIMEOUT_US 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

typedef struct {
    float humidity;
    float temperature;
} DHT22Data;

int read_dht22(int gpio, DHT22Data *data) {
    int bits[40] = {0};
    int i, j;
    uint32_t start_tick, end_tick;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(DHT22_START_LOW_US);
    gpioWrite(gpio, 1);
    gpioDelay(DHT22_START_HIGH_US);
    gpioSetMode(gpio, PI_INPUT);

    start_tick = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
    }
    start_tick = gpioTick();
    while (gpioRead(gpio) == 0) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
    }
    start_tick = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
    }

    for (i = 0; i < 40; i++) {
        start_tick = gpioTick();
        while (gpioRead(gpio) == 0) {
            if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
        }
        end_tick = gpioTick();
        while (gpioRead(gpio) == 1) {
            if (gpioTick() - end_tick > DHT22_TIMEOUT_US) return -1;
        }
        bits[i] = (gpioTick() - start_tick) > 50 ? 1 : 0;
    }

    int checksum = 0;
    for (i = 0; i < 40; i++) {
        if (i % 2 == 0) {
            data->humidity = (data->humidity << 1) | bits[i];
        } else {
            data->temperature = (data->temperature << 1) | bits[i];
            checksum += bits[i];
        }
    }

    if (checksum != 0) return -2;
    data->temperature = (data->temperature / 10.0) - 40.0;
    data->humidity = data->humidity / 10.0;
    return 0;
}

char* format_json(float humidity, float temperature) {
    char *json_string = malloc(128);
    if (!json_string) return NULL;
    snprintf(json_string, 128, "{\"humidity\": %.1f, \"temperature\": %.1f}", humidity, temperature);
    return json_string;
}

int send_data(const char *json_string) {
    CURL *curl = curl_easy_init();
    if (!curl) return -1;

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) { curl_easy_cleanup(curl); return -1; }

    curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    int ret = (res == CURLE_OK) ? 0 : -1;

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return ret;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    DHT22Data dht22_data;
    int retries = 0;

    while (!terminate) {
        int result = read_dht22(DHT22_GPIO, &dht22_data);
        if (result == 0) {
            char *json_string = format_json(dht22_data.humidity, dht22_data.temperature);
            if (json_string) {
                if (send_data(json_string) == 0) {
                    printf("Humidity: %.1f%%, Temperature: %.1f°C\n", dht22_data.humidity, dht22_data.temperature);
                    free(json_string);
                    retries = 0;
                    break;
                } else {
                    fprintf(stderr, "Failed to send data\n");
                    free(json_string);
                }
            } else {
                fprintf(stderr, "Failed to format JSON\n");
            }
        } else if (result == -1) {
            fprintf(stderr, "DHT22 read timeout\n");
        } else {
            fprintf(stderr, "DHT22 checksum error\n");
        }

        retries++;
        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "Max retries reached. Exiting.\n");
            break;
        }
        gpioDelay(RETRY_DELAY_US);
    }

    gpioTerminate();
    return 0;
}

