#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY_US 2000000
#define READ_INTERVAL_US 10000000
#define MAX_TIMINGS 85

static volatile sig_atomic_t running = 1;
static char server_url[] = "http://your-server.com/api/humidity";

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22_data(float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int counter = 0;
    int j = 0;

    for (int i = 0; i < MAX_TIMINGS; i++) {
        int state = gpioRead(DHT22_GPIO);
        if (state != laststate) {
            counter++;
            if (counter == 255) {
                syslog(LOG_ERR, "DHT22: timeout at bit %d", i);
                return -1;
            }
            laststate = state;
            if ((state == PI_LOW) && (i > 3)) {
                if ((i - j) > 3) {
                    data[j / 8] <<= 1;
                    if (i - j > 25) {
                        data[j / 8] |= 1;
                    }
                    j++;
                }
            }
        }
    }

    if (j < 40) {
        syslog(LOG_ERR, "DHT22: incomplete data (%d bits)", j);
        return -1;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        syslog(LOG_ERR, "DHT22: checksum error");
        return -1;
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0f;
    return 0;
}

static int post_humidity(float humidity) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "curl_easy_init() failed");
        return -1;
    }

    char json[64];
    snprintf(json, sizeof(json), "{\"humidity\": %.1f}", humidity);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        syslog(LOG_ERR, "curl_slist_append failed");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, server_url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);

    CURLcode res = curl_easy_perform(curl);
    int ret = -1;
    if (res != CURLE_OK) {
        syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
    } else {
        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code >= 200 && http_code < 300) {
            ret = 0;
        } else {
            syslog(LOG_ERR, "HTTP POST returned status %ld", http_code);
        }
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return ret;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                strncpy(server_url, optarg, sizeof(server_url) - 1);
                server_url[sizeof(server_url) - 1] = '\0';
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("dht22_humidity", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, PI_HIGH);
    gpioDelay(1000000);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        float humidity = -1.0f;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            gpioWrite(DHT22_GPIO, PI_LOW);
            gpioDelay(2000);
            gpioWrite(DHT22_GPIO, PI_HIGH);
            gpioDelay(30);

            if (read_dht22_data(&humidity) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    syslog(LOG_WARNING, "DHT22 read failed, retry %d/%d", retries, MAX_RETRIES);
                    gpioDelay(RETRY_DELAY_US);
                }
            }
        }

        if (success) {
            retries = 0;
            int post_ok = 0;
            while (retries < MAX_RETRIES && !post_ok) {
                if (post_humidity(humidity) == 0) {
                    post_ok = 1;
                } else {
                    retries++;
                    if (retries < MAX_RETRIES) {
                        syslog(LOG_WARNING, "HTTP POST failed, retry %d/%d", retries, MAX_RETRIES);
                        gpioDelay(RETRY_DELAY_US);
                    }
                }
            }
            if (!post_ok) {
                syslog(LOG_ERR, "Failed to post humidity after %d retries", MAX_RETRIES);
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
        }

        gpioDelay(READ_INTERVAL_US);
    }

    gpioTerminate();
    curl_global_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

