    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading %s: %s\n", CPU_TEMP_PATH, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *endptr;
    long temp = strtol(buffer, &endptr, 10);
    if (*endptr != '\n' && *endptr != '\0') {
        fprintf(stderr, "Error parsing temperature from %s\n", buffer);
        return -1;
    }

    *temp_out = (int)temp;
    return 0;
}

static int read_fan_max_state(int *max_state_out) {
    FILE *fp = fopen(FAN_SPEED_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_SPEED_PATH, strerror(errno));
        return -1;
    }

    char buffer[16];
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading %s: %s\n", FAN_SPEED_PATH, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *endptr;
    long max_state = strtol(buffer, &endptr, 10);
    if (*endptr != '\n' && *endptr != '\0') {
