        return -1;
    }

    if (fprintf(fp, "%d", speed) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", FAN_SPEED_PATH, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", FAN_SPEED_PATH, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_fan_speed(int speed) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
