        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int current_speed = -1;
    int max_state = -1;

    if (read_fan_max_state(&max_state) != 0) {
        fprintf(stderr, "Failed to read fan max state. Exiting.\n");
        return 1;
    }

    printf("Fan control started. Max state: %d\n", max_state);

    while (program_running) {
        int cpu_temp;
        if (read_cpu_temp(&cpu_temp) != 0) {
            fprintf(stderr, "Error reading CPU temperature. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int desired_speed = determine_fan_speed(cpu_temp);

        if (desired_speed != current_speed) {
            if (desired_speed > max_state) {
                fprintf(stderr, "Desired speed %d exceeds max state %d. Clamping to max.\n", desired_speed, max_state);
                desired_speed = max_state;
            }

            if (set_fan_speed(desired_speed) != 0) {
                fprintf(stderr, "Error setting fan speed. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            } else {
                current_speed = desired_speed;
                if (log_fan_speed(current_speed) != 0) {
                    fprintf(stderr, "Warning: Failed to log fan speed change.\n");
                }
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("Shutting down...\n");
    if (set_fan_speed(0) != 0) {
        fprintf(stderr, "Error stopping fan during shutdown.\n");
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        FILE *fp = fopen(LOG_FILE, "a");
        if (fp) {
            fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Fan control stopped.\n",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec);
            fclose(fp);
        }
