#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "heater_log.txt"
#define TEMPERATURE_THRESHOLD 100.0
#define TEMPERATURE_MIN 0.0
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static double Kp = 1.0;
static double Ki = 0.1;
static double Kd = 0.01;
static double target_temperature = 50.0;
static double integral = 0.0;
static double previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(double *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    int ret = spiXfer(spi_handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00000004) {
        fprintf(stderr, "MAX31855 fault: ");
        if (raw & 0x00000001) fprintf(stderr, "open circuit ");
        if (raw & 0x00000002) fprintf(stderr, "short to GND ");
        if (raw & 0x00000020) fprintf(stderr, "short to VCC ");
        fprintf(stderr, "\n");
        return -1;
    }

    int16_t temp_raw = (int16_t)(raw >> 18);
    *temperature = (double)temp_raw * 0.25;
    return 0;
}

static void set_heater_pwm(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;
    int pwm_value = (int)(duty_cycle * (PWM_RANGE / 100.0));
    gpioPWM(HEATER_GPIO, pwm_value);
}

static double calculate_pid(double current_temperature) {
    double error = target_temperature - current_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

static void log_data(double temperature, double duty_cycle, double pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f, Duty Cycle: %.2f, PID Output: %.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(HEATER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    set_heater_pwm(0.0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature control started. Press Ctrl+C to exit.\n");

    while (running) {
        double temperature;
        if (read_max31855(&temperature) != 0) {
            fprintf(stderr, "Error reading temperature, disabling heater\n");
            set_heater_pwm(0.0);
            integral = 0.0;
            previous_error = 0.0;
            log_data(-1000.0, 0.0, 0.0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (temperature > TEMPERATURE_THRESHOLD || temperature < TEMPERATURE_MIN) {
            fprintf(stderr, "Temperature out of range (%.2f), disabling heater\n", temperature);
            set_heater_pwm(0.0);
            integral = 0.0;
            previous_error = 0.0;
            log_data(temperature, 0.0, 0.0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double pid_output = calculate_pid(temperature);
        double duty_cycle = pid_output;

        if (duty_cycle < 0.0) duty_cycle = 0.0;
        if (duty_cycle > 100.0) duty_cycle = 100.0;

        set_heater_pwm(duty_cycle);
        log_data(temperature, duty_cycle, pid_output);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

