        perror("sigaction");
        set_fan_speed(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring CPU temperature. Press Ctrl+C to exit.\n");

    while (running) {
        int temp_milli = read_cpu_temp();
        if (temp_milli < 0) {
            fprintf(stderr, "Temperature read failed; retrying in %d s\n", POLL_INTERVAL);
            sleep(POLL_INTERVAL);
            continue;
        }

        float temp_c = temp_milli / 1000.0f;
        int duty = calculate_duty_cycle(temp_milli);

        if (set_fan_speed(duty) != 0) {
            fprintf(stderr, "Failed to set fan speed; continuing\n");
        }

        if (log_data(temp_c, duty) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        printf("Temp: %.2f C, Duty: %d%%\n", temp_c, duty);
        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    set_fan_speed(0);
    gpioTerminate();
    printf("Fan stopped. Resources released.\n");
    return EXIT_SUCCESS;
}

