#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x08
#define NUM_SENSORS 2
#define RETRY_COUNT 3
#define POLL_INTERVAL_SEC 1
#define LOG_FILE "flow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handles[NUM_SENSORS];
static int i2c_bus = I2C_BUS;
static int i2c_addr = I2C_ADDR;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int init_sensor(int handle) {
    uint8_t cmd[2] = {0x36, 0x08};
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write continuous measurement command to handle %d\n", handle);
        return -1;
    }
    gpioDelay(10000); // 10 ms settling time
    return 0;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t buf[3];
    int retries = RETRY_COUNT;
    while (retries > 0) {
        int bytes_read = i2cReadDevice(handle, (char *)buf, 3);
        if (bytes_read == 3) {
            if (crc8(buf, 2) == buf[2]) {
                int16_t raw = (buf[0] << 8) | buf[1];
                *flow_rate = (float)raw * 0.01f;
                return 0;
            } else {
                fprintf(stderr, "Warning: CRC mismatch on handle %d, retries left: %d\n", handle, retries - 1);
            }
        } else {
            fprintf(stderr, "Warning: I2C read error on handle %d (returned %d), retries left: %d\n", handle, bytes_read, retries - 1);
        }
        retries--;
        gpioDelay(10000); // 10 ms delay before retry
    }
    return -1;
}

static int log_data(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(i2c_bus, i2c_addr + i, 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Error: Failed to open I2C device for sensor %d (addr 0x%02X)\n", i, i2c_addr + i);
            gpioTerminate();
            return 1;
        }
        if (init_sensor(i2c_handles[i]) != 0) {
            fprintf(stderr, "Error: Sensor %d initialization failed\n", i);
            i2cClose(i2c_handles[i]);
            gpioTerminate();
            return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting flow monitoring. Press Ctrl+C to stop.\n");

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ret1 = read_flow_rate(i2c_handles[0], &flow1);
        int ret2 = read_flow_rate(i2c_handles[1], &flow2);

        if (ret1 == 0 && ret2 == 0) {
            if (log_data(flow1, flow2) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read flow rate from one or more sensors\n");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2cClose(i2c_handles[i]);
    }
    gpioTerminate();
    return 0;
}

