#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18
#define LOG_FILE "encoder_log.txt"
#define PULSES_PER_REVOLUTION 360

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(int state, double angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - State: %d, Angle: %.2f degrees\n", timestamp, state, angle);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetMode(SENSOR_B_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    int last_state = (gpioRead(SENSOR_A_PIN) << 1) | gpioRead(SENSOR_B_PIN);
    int current_state;
    int rotation_count = 0;
    double angle = 0.0;

    printf("Monitoring magnetic rotary encoder on GPIO%d and GPIO%d...\n", SENSOR_A_PIN, SENSOR_B_PIN);

    while (running) {
        current_state = (gpioRead(SENSOR_A_PIN) << 1) | gpioRead(SENSOR_B_PIN);

        if (current_state != last_state) {
            int state_change = current_state - last_state;
            if (state_change == 1 || state_change == -3) {
                rotation_count++;
            } else if (state_change == -1 || state_change == 3) {
                rotation_count--;
            }

            angle = (double)rotation_count * (360.0 / PULSES_PER_REVOLUTION);
            if (log_data(current_state, angle) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            last_state = current_state;
        }

        gpioDelay(1000);
    }

    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

