 * Bus:    I2C bus 1 (/dev/i2c-1), address 0x39
 * LED:    GPIO 17 (active-high)
 * Log:    adpd144ri_log.txt (CSV)
 *
 * Build:  gcc -O2 -Wall -Wextra -o adpd144ri adpd144ri.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- ADPD144RI constants (verified against datasheet) ---- */
#define ADPD144RI_I2C_BUS        "/dev/i2c-1"
#define ADPD144RI_I2C_ADDR       0x39

#define ADPD144RI_REG_MODE       0x00
#define ADPD144RI_REG_FIFO_DATA  0x60
#define ADPD144RI_REG_FIFO_COUNT 0x0A
#define ADPD144RI_REG_LED_CTRL   0x0B

#define ADPD144RI_MODE_STANDBY   0x00
#define ADPD144RI_MODE_OPERATE   0x01

#define ADPD144RI_LED_ON         0x01
#define ADPD144RI_LED_OFF        0x00

#define IR_THRESHOLD            2000
#define SAMPLE_PERIOD_US        100000   /* 100 ms */
#define LOG_FILE_NAME           "adpd144ri_log.txt"

/* ---- GPIO constants ---- */
#define GPIO_CHIP_NAME          "gpiochip4"   /* BCM GPIO bank on Pi 3B+ */
#define LED_GPIO_OFFSET         17

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_file = NULL;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_led  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_led) {
        gpiod_line_set_value(g_led, 0);
        gpiod_line_release(g_led);
        g_led = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* ADPD144RI is little-endian: LSB first */
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
static int adpd144ri_init(int fd)
{
    uint8_t mode;
    if (i2c_read_reg8(fd, ADPD144RI_REG_MODE, &mode) < 0)
        return -1;

    if (mode != ADPD144RI_MODE_OPERATE) {
        if (i2c_write_reg8(fd, ADPD144RI_REG_MODE, ADPD144RI_MODE_OPERATE) < 0)
            return -1;
        usleep(10000);  /* allow mode transition */
    }

    /* Enable LED drive on the LED control register */
    if (i2c_write_reg8(fd, ADPD144RI_REG_LED_CTRL, ADPD144RI_LED_ON) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int adpd144ri_read_data(int fd, uint16_t *red, uint16_t *ir)
{
    uint8_t count;
    if (i2c_read_reg8(fd, ADPD144RI_REG_FIFO_COUNT, &count) < 0)
        return -1;

    if (count == 0) {
        *red = 0;
        *ir  = 0;
        return 0;  /* no data available yet */
    }

    if (i2c_read_reg16(fd, ADPD144RI_REG_FIFO_DATA, red) < 0)
        return -1;

    /* Read IR channel from the next 2 bytes in the FIFO */
    uint8_t ir_buf[2];
    if (read(fd, ir_buf, 2) != 2) {
        fprintf(stderr, "I2C read IR channel failed: %s\n", strerror(errno));
        return -1;
    }
    *ir = (uint16_t)ir_buf[0] | ((uint16_t)ir_buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, (unsigned)red, (unsigned)ir);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(ADPD144RI_I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", ADPD144RI_I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADPD144RI_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADPD144RI_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (adpd144ri_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADPD144RI initialization failed (sensor absent or bus error).\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request LED line ---- */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_led = gpiod_chip_get_line(g_chip, LED_GPIO_OFFSET);
    if (!g_led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                LED_GPIO_OFFSET, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_led, "adpd144ri-led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO %d as output: %s\n",
                LED_GPIO_OFFSET, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADPD144RI reader started. Logging to %s. Press Ctrl+C to exit.\n",
           LOG_FILE_NAME);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t red = 0, ir = 0;

        if (adpd144ri_read_data(g_i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Read error — continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        log_data(g_log_file, red, ir);

        if (ir > IR_THRESHOLD) {
            gpiod_line_set_value(g_led, 1);
        } else {
            gpiod_line_set_value(g_led, 0);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

