#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static volatile int pulse_count = 0;
static volatile int running = 1;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

static void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)level; (void)tick; (void)user_data;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static double calculate_rpm(int pulses, double interval_sec) {
    if (interval_sec <= 0.0) return 0.0;
    return (double)pulses / interval_sec * 60.0;
}

static void log_rpm(double rpm) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s, %.2f\n", timestamp, rpm);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        time_t start = time(NULL);
        pulse_count = 0;

        while (running && (time(NULL) - start) < SAMPLE_INTERVAL_SEC) {
            gpioDelay(100000); /* 100 ms */
        }

        int pulses;
        pthread_mutex_lock(&pulse_mutex);
        pulses = pulse_count;
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = calculate_rpm(pulses, (double)(time(NULL) - start));
        log_rpm(rpm);

        printf("Pulses: %d, RPM: %.2f\n", pulses, rpm);
    }

    printf("\nShutting down...\n");
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    if (log_file) fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    return EXIT_SUCCESS;
}

