#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define START_MEAS_CMD_MSB 0x36
#define START_MEAS_CMD_LSB 0x08
#define FLOW_SCALE 1000.0f
#define LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_sensor(void) {
    uint8_t cmd[2] = { START_MEAS_CMD_MSB, START_MEAS_CMD_LSB };
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to write start-measurement command to sensor\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_flow_rate(float *flow_rate) {
    uint8_t buffer[3];
    int bytes_read = i2cReadDevice(i2c_handle, (char *)buffer, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 3)\n", bytes_read);
        return -1;
    }

    if (sensirion_crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "Error: CRC mismatch on flow data\n");
        return -1;
    }

    int16_t raw_flow = (int16_t)((buffer[0] << 8) | buffer[1]);
    *flow_rate = (float)raw_flow / FLOW_SCALE;
    return 0;
}

static void log_flow_rate(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at address 0x%02X on bus %d\n", SLF3S_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float flow_rate;
    while (!terminate) {
        if (read_flow_rate(&flow_rate) == 0) {
            log_flow_rate(flow_rate);
        } else {
            fprintf(stderr, "Warning: sensor read failed, will retry next cycle\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

