#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define LOG_FILE "air_quality_log.csv"
#define READ_INTERVAL_SEC 5
#define SENSOR_DATA_LEN 7
#define TVOC_REG 0x00
#define IAQ_MAX 100.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    uint16_t tvoc;
    uint16_t eco2;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sensor_data(int handle, sensor_data_t *data) {
    char buf[SENSOR_DATA_LEN];
    int result = i2cReadI2CBlockData(handle, TVOC_REG, buf, SENSOR_DATA_LEN);
    if (result != SENSOR_DATA_LEN) {
        fprintf(stderr, "Error reading sensor data: expected %d bytes, got %d\n",
                SENSOR_DATA_LEN, result);
        return -1;
    }
    data->tvoc = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    data->eco2 = ((uint16_t)(uint8_t)buf[6] << 8) | (uint8_t)buf[5];
    return 0;
}

static float calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    float iaq = 100.0f - ((float)tvoc / 10.0f) - ((float)(eco2 - 400) / 50.0f);
    if (iaq < 0.0f) iaq = 0.0f;
    if (iaq > IAQ_MAX) iaq = IAQ_MAX;
    return iaq;
}

static int log_data(FILE *fp, float iaq, uint16_t tvoc, uint16_t eco2) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%u,%u\n", timestamp, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,IAQ,TVOC_ppb,eCO2_ppm\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    sensor_data_t sensor_data;
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            float iaq = calculate_iaq(sensor_data.tvoc, sensor_data.eco2);
            if (log_data(log_file, iaq, sensor_data.tvoc, sensor_data.eco2) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed, continuing...\n");
        }
        sleep(READ_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

