#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE       17
#define POLL_INTERVAL_MS 100
#define TOUCH_THRESHOLD_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip by name */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Request the line as input with a consumer label */
    if (gpiod_line_request_input(line, "ttp223_tamper") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
                GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring TTP223B touch sensor on GPIO %d (chip %s).\n",
           GPIO_LINE, GPIO_CHIP_NAME);
    printf("Press Ctrl+C to exit.\n");

    int last_value = -1;
    time_t touch_start = 0;
    int alert_sent = 0;

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line %d: %s\n",
                    GPIO_LINE, strerror(errno));
            goto cleanup;
        }

        if (value != last_value) {
            if (value == 1) {
                /* Sensor touched (HIGH) */
                if (touch_start == 0) {
                    touch_start = time(NULL);
                    alert_sent = 0;
                }
            } else {
                /* Sensor released (LOW) */
                if (touch_start != 0) {
                    time_t now = time(NULL);
                    if (now - touch_start >= TOUCH_THRESHOLD_SEC) {
                        if (!alert_sent) {
                            printf("INTRUSION DETECTED: Touch held for %ld seconds!\n",
                                   (long)(now - touch_start));
                            fflush(stdout);
                            alert_sent = 1;
                        }
                    }
                    touch_start = 0;
                }
            }
            last_value = value;
        }

        /* Sleep for POLL_INTERVAL_MS using CLOCK_MONOTONIC for accurate timing */
        struct timespec ts;
        ts.tv_sec = POLL_INTERVAL_MS / 1000;
        ts.tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000L;
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

