#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define SAMPLE_RATE 16000
#define NUM_CHANNELS 1
#define BITS_PER_SAMPLE 16
#define RECORD_SECONDS 5
#define FILENAME "audio_capture.pcm"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2s(int *fd) {
    int ret;
    int format = AFMT_S32_LE;
    int channels = NUM_CHANNELS;
    int rate = SAMPLE_RATE;

    *fd = open(I2S_DEVICE, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening I2S device %s: %s\n", I2S_DEVICE, strerror(errno));
        return -1;
    }

    ret = ioctl(*fd, SNDCTL_DSP_SETFMT, &format);
    if (ret < 0) {
        fprintf(stderr, "Error setting I2S format: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    ret = ioctl(*fd, SNDCTL_DSP_CHANNELS, &channels);
    if (ret < 0) {
        fprintf(stderr, "Error setting I2S channels: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    ret = ioctl(*fd, SNDCTL_DSP_SPEED, &rate);
    if (ret < 0) {
        fprintf(stderr, "Error setting I2S sample rate: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

static int extract_24bit_sample(uint32_t raw_sample) {
    // INMP441 outputs 24-bit data left-justified in a 32-bit frame.
    // The upper 8 bits are always 0, so we right-shift by 8 to get the 24-bit value.
    // Then we right-shift by 8 more to get a 16-bit value.
    int32_t sample = (int32_t)(raw_sample >> 8) >> 8;
    return (int16_t)sample;
}

static int log_audio_data(const char *filename, int *audio_data, int num_samples) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t written = fwrite(audio_data, sizeof(int16_t), num_samples, fp);
    if (written != (size_t)num_samples) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int *audio_data = NULL;
    int ret = 1;

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    // Initialize I2S
    if (init_i2s(&fd) != 0) {
        fprintf(stderr, "I2S initialization failed\n");
        goto cleanup;
    }

    // Initialize GPIO using libgpiod
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "audio_capture", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    // Allocate memory for audio data
    int num_samples = SAMPLE_RATE * RECORD_SECONDS;
    audio_data = (int *)malloc(num_samples * sizeof(int));
    if (audio_data == NULL) {
        fprintf(stderr, "Error allocating memory for audio data\n");
        goto cleanup;
    }

    printf("Recording audio for %d seconds...\n", RECORD_SECONDS);

    // Main loop to read and process audio data
    for (int i = 0; i < num_samples && running; i++) {
        uint32_t raw_sample;
        ssize_t bytes_read = read(fd, &raw_sample, sizeof(uint32_t));

        if (bytes_read < 0) {
            fprintf(stderr, "Error reading from I2S device: %s\n", strerror(errno));
            goto cleanup;
        }

        if (bytes_read == 0) {
            fprintf(stderr, "End of stream reached unexpectedly\n");
            goto cleanup;
        }

        // Extract 16-bit PCM sample from 24-bit data
        audio_data[i] = extract_24bit_sample(raw_sample);

        // Toggle GPIO line to select left channel
        gpiod_line_set_value(line, i % 2);
    }

    printf("Recording complete.\n");

    // Log audio data to file
    if (log_audio_data(FILENAME, audio_data, num_samples) != 0) {
        fprintf(stderr, "Error logging audio data\n");
        goto cleanup;
    }

    printf("Audio data logged to %s\n", FILENAME);
    ret = 0;

cleanup:
    if (audio_data) free(audio_data);
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    if (fd >= 0) close(fd);

    return ret;
}

