#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define TRIGGER_PIN 23
#define DATA_READY_PIN 24
#define DATA_SIZE 32768
#define LOG_FILE "radar_data.log"

#define MAGIC_NUMBER 0x52444144

typedef struct {
    uint64_t timestamp;
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint32_t num_chirps;
    uint32_t num_samples;
    uint32_t frame_period_us;
} radar_config_t;

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_gpio(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to write trigger pin\n");
        return -1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set data-ready pin mode\n");
        return -1;
    }
    return 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

static int write_log_header(void) {
    uint64_t ts = (uint64_t)time(NULL);
    radar_config_t cfg = {
        .timestamp = ts,
        .start_frequency = 770000000,
        .end_frequency = 790000000,
        .num_chirps = 64,
        .num_samples = 256,
        .frame_period_us = 100000
    };

    if (fwrite(&MAGIC_NUMBER, sizeof(uint32_t), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write magic number\n");
        return -1;
    }
    if (fwrite(&ts, sizeof(uint64_t), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write timestamp\n");
        return -1;
    }
    if (fwrite(&cfg, sizeof(radar_config_t), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write config\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int read_data(uint8_t *data, int data_size) {
    int bytes_read = spiRead(spi_handle, (char *)data, data_size);
    if (bytes_read != data_size) {
        fprintf(stderr, "SPI read failed: expected %d bytes, got %d\n", data_size, bytes_read);
        return -1;
    }
    return 0;
}

static int log_frame_data(const uint8_t *data, uint64_t timestamp, int frame_number) {
    if (fwrite(&timestamp, sizeof(uint64_t), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write timestamp\n");
        return -1;
    }
    if (fwrite(&frame_number, sizeof(int), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write frame number\n");
        return -1;
    }
    if (fwrite(data, sizeof(uint8_t), DATA_SIZE, log_file) != DATA_SIZE) {
        fprintf(stderr, "Failed to write data\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "wb");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    if (write_log_header() != 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint8_t *data = malloc(DATA_SIZE);
    if (!data) {
        fprintf(stderr, "Memory allocation failed\n");
        cleanup();
        return 1;
    }

    int frame_number = 0;
    while (!terminate) {
        if (gpioWrite(TRIGGER_PIN, 1) < 0) {
            fprintf(stderr, "Failed to assert trigger\n");
            break;
        }
        gpioDelay(1000);

        if (gpioWrite(TRIGGER_PIN, 0) < 0) {
            fprintf(stderr, "Failed to deassert trigger\n");
            break;
        }

        while (!terminate) {
            if (gpioRead(DATA_READY_PIN) == 1) {
                break;
            }
            gpioDelay(100);
        }

        if (terminate) break;

        uint64_t ts = (uint64_t)time(NULL);
        if (read_data(data, DATA_SIZE) != 0) {
            fprintf(stderr, "Failed to read data\n");
            break;
        }
        if (log_frame_data(data, ts, frame_number) != 0) {
            fprintf(stderr, "Failed to log frame data\n");
            break;
        }
        frame_number++;
    }

    free(data);
    cleanup();
    return 0;
}

