#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define REG_RESULT 0x00
#define REG_CONFIG 0x01
#define REG_MANUFACTURER_ID 0x7E
#define REG_DEVICE_ID 0x7F

#define CONFIG_CONTINUOUS 0x0000
#define CONFIG_RANGE_AUTO 0x0000
#define CONFIG_CONV_TIME_100MS 0x0000
#define CONFIG_DEFAULT (CONFIG_CONTINUOUS | CONFIG_RANGE_AUTO | CONFIG_CONV_TIME_100MS)

#define LOG_FILE "light_data.txt"
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int read_reg16(uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 0) return -1;
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) return -1;
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int init_opt3001(void) {
    uint16_t manuf_id = 0, dev_id = 0;
    if (read_reg16(REG_MANUFACTURER_ID, &manuf_id) != 0) {
        fprintf(stderr, "Error: Failed to read manufacturer ID.\n");
        return -1;
    }
    if (read_reg16(REG_DEVICE_ID, &dev_id) != 0) {
        fprintf(stderr, "Error: Failed to read device ID.\n");
        return -1;
    }
    printf("OPT3001 detected: Manufacturer ID=0x%04X, Device ID=0x%04X\n", manuf_id, dev_id);

    if (write_reg16(REG_CONFIG, CONFIG_DEFAULT) != 0) {
        fprintf(stderr, "Error: Failed to write configuration register.\n");
        return -1;
    }
    return 0;
}

static int read_lux(float *lux) {
    uint16_t raw;
    if (read_reg16(REG_RESULT, &raw) != 0) {
        fprintf(stderr, "Error: Failed to read result register.\n");
        return -1;
    }
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    *lux = 0.01f * (float)(1 << exponent) * (float)mantissa;
    return 0;
}

static int log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    if (fprintf(log_file, "%s, Lux: %.2f\n", timestamp, lux) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d.\n", OPT3001_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (init_opt3001() != 0) {
        fprintf(stderr, "Error: OPT3001 initialization failed.\n");
        cleanup();
        return 1;
    }

    printf("Starting light sensor readings. Press Ctrl+C to exit.\n");

    while (running) {
        float lux = 0.0f;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_lux(&lux) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Retrying (%d/%d)...\n", retries, MAX_RETRIES);
                gpioDelay(100000);
            }
        }

        if (success) {
            if (log_data(lux) != 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read lux after %d retries.\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

