/*
 * Flame Detection Sensor Reader using libgpiod (v2.x API)
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: SainSmart IR Flame Detection Module
 * Wiring: DOUT -> GPIO17 (BCM), VCC -> 3.3V, GND -> GND
 * Logic:  DOUT is active-low: 0 = flame detected, 1 = no flame.
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[unknown-time] ");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[unknown-time] ");
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[unknown-time] ");
        return;
    }
    fprintf(stderr, "%s ", buf);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        print_timestamp();
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        print_timestamp();
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure line settings: input, bias pulled-up */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        print_timestamp();
        fprintf(stderr, "Failed to allocate line settings: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);

    /* Configure line config with one offset */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        print_timestamp();
        fprintf(stderr, "Failed to allocate line config: %s\n", strerror(errno));
        goto cleanup;
    }
    unsigned int offsets[1] = { GPIO_LINE_OFFSET };
    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 1, settings) != 0) {
        print_timestamp();
        fprintf(stderr, "Failed to add line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure request config */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        print_timestamp();
        fprintf(stderr, "Failed to allocate request config: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "flame-detector");

    /* Request the line */
    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (request == NULL) {
        print_timestamp();
        fprintf(stderr, "Failed to request GPIO line %u: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    print_timestamp();
    printf("Flame detection started on GPIO %u. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Main polling loop */
    while (g_running) {
        int value = gpiod_line_request_get_value(request, GPIO_LINE_OFFSET);
        if (value < 0) {
            print_timestamp();
            fprintf(stderr, "Failed to read GPIO %u: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        print_timestamp();
        if (value == 0) {
            printf("Flame Detected: YES\n");
        } else {
            printf("Flame Detected: NO\n");
        }
        fflush(stdout);

        /* Sleep for 1 second, checking g_running every second */
        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    print_timestamp();
    printf("Exiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (request != NULL) {
        gpiod_line_request_release(request);
    }
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

