        print_timestamp();
        fprintf(stderr, "Failed to allocate line settings: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);

    /* Configure line config with one offset */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        print_timestamp();
        fprintf(stderr, "Failed to allocate line config: %s\n", strerror(errno));
        goto cleanup;
    }
    unsigned int offsets[1] = { GPIO_LINE_OFFSET };
    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 1, settings) != 0) {
        print_timestamp();
        fprintf(stderr, "Failed to add line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure request config */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        print_timestamp();
        fprintf(stderr, "Failed to allocate request config: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "flame-detector");

    /* Request the line */
    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (request == NULL) {
        print_timestamp();
        fprintf(stderr, "Failed to request GPIO line %u: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    print_timestamp();
    printf("Flame detection started on GPIO %u. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Main polling loop */
    while (g_running) {
        int value = gpiod_line_request_get_value(request, GPIO_LINE_OFFSET);
        if (value < 0) {
            print_timestamp();
            fprintf(stderr, "Failed to read GPIO %u: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        print_timestamp();
        if (value == 0) {
            printf("Flame Detected: YES\n");
        } else {
            printf("Flame Detected: NO\n");
        }
        fflush(stdout);

        /* Sleep for 1 second, checking g_running every second */
        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    print_timestamp();
    printf("Exiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (request != NULL) {
        gpiod_line_request_release(request);
    }
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

