#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = i + 2;  /* BCM 2-9 */

        if (gpioSetMode(pin, PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for BCM pin %d\n", pin);
            return -1;
        }

        if (gpioSetPullUpDown(pin, PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for BCM pin %d\n", pin);
            return -1;
        }
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int states[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int pin = i + 2;
            int val = gpioRead(pin);
            if (val < 0) {
                fprintf(stderr, "Error: gpioRead failed for BCM pin %d\n", pin);
                error = 1;
                break;
            }
            states[i] = val;
        }

        if (error) {
            break;
        }

        printf("[+");
        {
            struct timespec ts;
            if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
                printf("%ld", ts.tv_sec * 1000L + ts.tv_nsec / 1000000L);
            } else {
                printf("?");
            }
        }
        printf(" ms] ");
        for (int i = 0; i < NUM_CHANNELS; i++) {
            printf("CH%d=%d ", i + 1, states[i]);
        }
        printf("\n");
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

