#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SI1145_ADDR 0x60
#define I2C_BUS 1

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_CHLIST 0x01
#define SI1145_REG_UVINDEX 0x2C
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_COMMAND 0x18
#define SI1145_CMD_ALS_FORCE 0x06

#define SI1145_PART_ID 0x45
#define HW_KEY_VAL 0x17

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_si1145(int handle) {
    uint8_t part_id = 0;
    if (read_register(handle, SI1145_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (write_register(handle, SI1145_REG_HW_KEY, HW_KEY_VAL) != 0) {
        fprintf(stderr, "Failed to write HW_KEY\n");
        return -1;
    }

    if (write_register(handle, SI1145_REG_CHLIST, 0x0F) != 0) {
        fprintf(stderr, "Failed to write CHLIST\n");
        return -1;
    }

    return 0;
}

static int read_uv_index(int handle, uint8_t *uv_index) {
    if (read_register(handle, SI1145_REG_UVINDEX, uv_index) != 0) {
        return -1;
    }
    return 0;
}

static int read_als_vis(int handle, uint16_t *als_vis) {
    uint8_t lo = 0, hi = 0;
    if (read_register(handle, SI1145_REG_ALS_VIS_DATA0, &lo) != 0) {
        return -1;
    }
    if (read_register(handle, SI1145_REG_ALS_VIS_DATA0 + 1, &hi) != 0) {
        return -1;
    }
    *als_vis = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int log_data(FILE *fp, uint8_t uv_index, uint16_t als_vis) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%u,%u\n", timestamp, uv_index, als_vis) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n", SI1145_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_si1145(i2c_handle) != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        uint8_t uv_index = 0;
        uint16_t als_vis = 0;

        if (read_uv_index(i2c_handle, &uv_index) != 0) {
            fprintf(stderr, "Failed to read UV index\n");
        } else if (read_als_vis(i2c_handle, &als_vis) != 0) {
            fprintf(stderr, "Failed to read ALS_VIS\n");
        } else {
            printf("UV Index: %u, ALS_VIS: %u\n", uv_index, als_vis);
            if (log_data(log_file, uv_index, als_vis) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        }

        gpioSleep(PI_TIME_RELATIVE, 1, 0);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

