#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define GPIO_CHIP "gpiochip4"
#define ALARM_PIN 17
#define FLOW_SCALE_FACTOR 0.036f
#define FLOW_THRESHOLD 0.5f
#define LOG_FILE "flow_log.txt"
#define MEASUREMENT_DELAY_MS 100
#define LOOP_DELAY_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd_msb, uint8_t cmd_lsb) {
    uint8_t buf[2] = {cmd_msb, cmd_lsb};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X%02X): %s\n", cmd_msb, cmd_lsb, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg failed: %s\n", strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu): %s\n", n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(int fd) {
    if (i2c_write_cmd(fd, 0x36, 0x08) < 0) return -1;
    usleep(MEASUREMENT_DELAY_MS * 1000);
    return 0;
}

static int read_flow_rate(int fd, float *flow_rate) {
    uint8_t buf[9];
    if (i2c_read_bytes(fd, 0x00, buf, sizeof(buf)) < 0) return -1;

    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC error on flow data\n");
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC error on temperature data\n");
        return -1;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC error on scale factor data\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw * FLOW_SCALE_FACTOR;
    return 0;
}

static void log_flow_rate(FILE *fp, float avg_flow) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Average Flow: %.3f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, avg_flow);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }
    struct gpiod_line *alarm_line = gpiod_chip_get_line(chip, ALARM_PIN);
    if (!alarm_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALARM_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(alarm_line, "flow_alarm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", ALARM_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int fd1 = open(I2C_BUS, O_RDWR);
    if (fd1 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (ioctl(fd1, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SENSOR1_ADDR, strerror(errno));
        close(fd1);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (init_sensor(fd1) < 0) {
        fprintf(stderr, "Sensor 1 init failed\n");
        close(fd1);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    int fd2 = open(I2C_BUS, O_RDWR);
    if (fd2 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        close(fd1);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (ioctl(fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SENSOR2_ADDR, strerror(errno));
        close(fd1);
        close(fd2);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (init_sensor(fd2) < 0) {
        fprintf(stderr, "Sensor 2 init failed\n");
        close(fd1);
        close(fd2);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(fd1);
        close(fd2);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = (read_flow_rate(fd1, &flow1) == 0);
        int ok2 = (read_flow_rate(fd2, &flow2) == 0);

        if (ok1 && ok2) {
            float avg = (flow1 + flow2) / 2.0f;
            log_flow_rate(log_fp, avg);
            int alarm = (avg < FLOW_THRESHOLD) ? 1 : 0;
            gpiod_line_set_value(alarm_line, alarm);
            printf("Avg: %.3f ml/min, Alarm: %s\n", avg, alarm ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(alarm_line, 0);
    gpiod_line_release(alarm_line);
    gpiod_chip_close(chip);
    close(fd1);
    close(fd2);
    fclose(log_fp);
    return 0;
}

