#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000  /* 50 ms */

typedef struct {
    time_t timestamp;
    int    reading;
} SensorData;

static SensorData sensor_buffer[BUFFER_SIZE];
static int        buffer_index = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void print_buffer(void)
{
    printf("\n--- Sensor Data Log (circular buffer, %d entries) ---\n",
           BUFFER_SIZE);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        if (sensor_buffer[idx].timestamp == 0)
            continue;
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S",
                 localtime(&sensor_buffer[idx].timestamp));
        printf("[%s] Reading: %d\n", ts, sensor_buffer[idx].reading);
    }
    printf("--- End of Log ---\n");
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    /* Configure sensor pin as input with internal pull-up */
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);

    printf("KY-033 Obstacle Avoidance Sensor Monitor\n");
    printf("Sensor pin: GPIO %d (BCM, physical pin 7)\n", SENSOR_PIN);
    printf("Press Ctrl+C to view the sensor data log.\n");

    while (running) {
        int reading = gpioRead(SENSOR_PIN);
        if (reading < 0) {
            fprintf(stderr, "Error: gpioRead failed on pin %d.\n", SENSOR_PIN);
            break;
        }

        /* KY-033 outputs LOW (0) when obstacle detected */
        if (reading == 0) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                perror("time");
                break;
            }

            sensor_buffer[buffer_index].timestamp = now;
            sensor_buffer[buffer_index].reading    = reading;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S",
                     localtime(&now));
            printf("[ALERT] Obstacle detected at %s (reading=%d)\n",
                   ts, reading);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown: print buffer and release pigpio */
    print_buffer();
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

