/*
 * fan_health.c — Omron D7S vibration sensor monitor for Raspberry Pi 5.
 *
 * Wiring:
 *   D7S SDA  -> GPIO 2  (pin 3)
 *   D7S SCL  -> GPIO 3  (pin 5)
 *   D7S VDD  -> 3.3 V
 *   D7S GND  -> GND
 *
 * I2C:  /dev/i2c-1, 7-bit address 0x55, up to 400 kHz.
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_health fan_health.c
 */

#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

/* ---- D7S constants (verified against datasheet) ---- */
#define D7S_I2C_ADDR        0x55
#define I2C_BUS             "/dev/i2c-1"

#define REG_MODE_CONTROL    0x1D
#define REG_OPERATING_STATUS 0x1B
#define REG_X_LSB           0x2A
#define REG_X_MSB           0x2B
#define REG_Y_LSB           0x2C
#define REG_Y_MSB           0x2D
#define REG_Z_LSB           0x2E
#define REG_Z_MSB           0x2F

#define MODE_ACTIVE         0x10
#define STATUS_ACTIVE       0x01

#define SCALE_FACTOR_G      0.0009765625f   /* 1/1024 g per LSB */
#define SAMPLE_PERIOD_MS    500
#define ACTIVE_TIMEOUT_S    1
#define CSV_FILENAME        "fan_health.csv"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Write a single byte to a D7S register.
 * Returns 0 on success, -1 on error.
 */
static int d7s_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(reg=0x%02X, val=0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, value, strerror(errno), n);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit little-endian value from two consecutive registers.
 * Returns 0 on success and stores the signed value in *out; -1 on error.
 */
static int d7s_read_reg16(int fd, uint8_t reg_lsb, int16_t *out)
{
    uint8_t lsb, msb;
    ssize_t n;

    n = read(fd, &lsb, 1);
    if (n != 1) {
        fprintf(stderr, "read(reg=0x%02X, LSB) failed: %s (read %zd bytes)\n",
                reg_lsb, strerror(errno), n);
        return -1;
    }

    n = read(fd, &msb, 1);
    if (n != 1) {
        fprintf(stderr, "read(reg=0x%02X, MSB) failed: %s (read %zd bytes)\n",
                reg_lsb + 1, strerror(errno), n);
        return -1;
    }

    *out = (int16_t)((uint16_t)msb << 8 | (uint16_t)lsb);
    return 0;
}

/*
 * Initialise the D7S: set MODE_CONTROL to active mode.
 * Returns 0 on success, -1 on error.
 */
static int d7s_init(int fd)
{
    if (d7s_write_reg(fd, REG_MODE_CONTROL, MODE_ACTIVE) != 0)
        return -1;

    /* Poll operating-status bit 0 until ACTIVE_TIMEOUT_S elapses. */
    for (int elapsed = 0; elapsed < ACTIVE_TIMEOUT_S * 1000; elapsed += 100) {
        uint8_t status;
        ssize_t n = read(fd, &status, 1);
        if (n != 1) {
            fprintf(stderr, "read(operating-status) failed: %s (read %zd bytes)\n",
                    strerror(errno), n);
            return -1;
        }
        if ((status & STATUS_ACTIVE) != 0)
            return 0;
        usleep(100 * 1000); /* 100 ms */
    }

    fprintf(stderr, "D7S did not become active within %d s; check wiring/address.\n",
            ACTIVE_TIMEOUT_S);
    return -1;
}

/*
 * Append a CSV row: timestamp,accel_x_g,accel_y_g,accel_z_g
 * Returns 0 on success, -1 on error.
 */
static int log_sample(FILE *fp, float x_g, float y_g, float z_g)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        return -1;
    }

    struct tm tm_local;
    if (localtime_r(&t, &tm_local) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_local) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x_g, y_g, z_g) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    /* Open the I2C bus. */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, D7S_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialise the sensor. */
    if (d7s_init(fd) != 0) {
        fprintf(stderr, "D7S initialisation failed.\n");
        goto cleanup;
    }

    /* Open CSV file for append. */
    fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        goto cleanup;
    }

    /* Write header if file is empty. */
    if (fseek(fp, 0, SEEK_END) != 0) {
        perror("fseek");
        goto cleanup;
    }
    long pos = ftell(fp);
    if (pos < 0) {
        perror("ftell");
        goto cleanup;
    }
    if (pos == 0) {
        if (fprintf(fp, "timestamp,accel_x_g,accel_y_g,accel_z_g\n") < 0) {
            perror("fprintf(header)");
            goto cleanup;
        }
        if (fflush(fp) != 0) {
            perror("fflush(header)");
            goto cleanup;
        }
    }

    printf("D7S monitoring started. Logging to %s. Press Ctrl+C to stop.\n",
           CSV_FILENAME);

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;

        if (d7s_read_reg16(fd, REG_X_LSB, &raw_x) != 0 ||
            d7s_read_reg16(fd, REG_Y_LSB, &raw_y) != 0 ||
            d7s_read_reg16(fd, REG_Z_LSB, &raw_z) != 0) {
            fprintf(stderr, "I2C read error; retrying next cycle.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        float x_g = (float)raw_x * SCALE_FACTOR_G;
        float y_g = (float)raw_y * SCALE_FACTOR_G;
        float z_g = (float)raw_z * SCALE_FACTOR_G;

        if (log_sample(fp, x_g, y_g, z_g) != 0) {
            fprintf(stderr, "CSV write error; continuing.\n");
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0)
            perror("fclose");
    }
    if (fd >= 0) {
        if (close(fd) != 0)
            perror("close(i2c)");
    }
    return rc;
}

