#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN     25
#define POLL_US     100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-ups so the input reads HIGH when no obstacle is present */
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize LED state on GPIO %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("KY-032 obstacle detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error reading sensor GPIOs (s1=%d, s2=%d)\n", s1, s2);
            break;
        }

        /* Active-LOW: LOW = obstacle detected */
        int obstacle = (s1 == 0 || s2 == 0) ? 1 : 0;

        if (gpioWrite(LED_PIN, obstacle) != 0) {
            fprintf(stderr, "Failed to write LED state on GPIO %d\n", LED_PIN);
            break;
        }

        gpioDelay(POLL_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

