#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TMAG5170-Q1 I2C address (A0=A1=0) */
#define TMAG5170_ADDR 0x0E

/* TMAG5170 register addresses */
#define REG_DEVICE_ID     0x00
#define REG_X_MSB         0x01
#define REG_X_LSB         0x02
#define REG_Y_MSB         0x03
#define REG_Y_LSB         0x04
#define REG_Z_MSB         0x05
#define REG_Z_LSB         0x06
#define REG_RANGE         0x0F
#define REG_MODE          0x10

/* Expected device ID for TMAG5170-Q1 */
#define TMAG5170_ID       0x8D

/* Range register bits for 50 mT */
#define RANGE_50MT        0x00

/* Mode register bits: continuous conversion, all axes enabled */
#define MODE_CONTINUOUS   0x01

/* LSB scale factor for 50 mT range: 0.0009765625 mT per LSB */
#define SCALE_50MT        0.0009765625f

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a TMAG5170 register                               */
/* ------------------------------------------------------------------ */
static int tmag_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a TMAG5170 register                              */
/* ------------------------------------------------------------------ */
static int tmag_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit two's-complement value from two consecutive registers  */
/* ------------------------------------------------------------------ */
static int tmag_read_axis(int handle, uint8_t reg_msb, uint8_t reg_lsb,
                          int16_t *out)
{
    uint8_t msb, lsb;

    if (tmag_read_reg(handle, reg_msb, &msb) < 0)
        return -1;
    if (tmag_read_reg(handle, reg_lsb, &lsb) < 0)
        return -1;

    /* TMAG5170 outputs data MSB first */
    int16_t raw = (int16_t)(((uint16_t)msb << 8) | (uint16_t)lsb);
    *out = raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file                                    */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the TMAG5170 address */
    g_i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                TMAG5170_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify device identity */
    uint8_t id = 0;
    if (tmag_read_reg(g_i2c_handle, REG_DEVICE_ID, &id) < 0) {
        fprintf(stderr, "[FATAL] Cannot read device ID — sensor absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (id != TMAG5170_ID) {
        fprintf(stderr, "[FATAL] Device ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, TMAG5170_ID);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("[INFO] TMAG5170 detected (device ID 0x%02X)\n", id);

    /* Configure range: 50 mT */
    if (tmag_write_reg(g_i2c_handle, REG_RANGE, RANGE_50MT) < 0) {
        fprintf(stderr, "[FATAL] Failed to set range register\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure mode: continuous conversion, all axes enabled */
    if (tmag_write_reg(g_i2c_handle, REG_MODE, MODE_CONTINUOUS) < 0) {
        fprintf(stderr, "[FATAL] Failed to set mode register\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("magnetic_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open magnetic_log.csv for writing\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,x_mt,y_mt,z_mt\n");
        fflush(g_log_file);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Logging magnetic field data to magnetic_log.csv (Ctrl+C to stop)\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t x_raw, y_raw, z_raw;

        if (tmag_read_axis(g_i2c_handle, REG_X_MSB, REG_X_LSB, &x_raw) < 0 ||
            tmag_read_axis(g_i2c_handle, REG_Y_MSB, REG_Y_LSB, &y_raw) < 0 ||
            tmag_read_axis(g_i2c_handle, REG_Z_MSB, REG_Z_LSB, &z_raw) < 0) {
            fprintf(stderr, "[WARN] Sensor read error — skipping sample\n");
        } else {
            float x_mt = (float)x_raw * SCALE_50MT;
            float y_mt = (float)y_raw * SCALE_50MT;
            float z_mt = (float)z_raw * SCALE_50MT;
            log_data(g_log_file, (int16_t)x_mt, (int16_t)y_mt, (int16_t)z_mt);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

