#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <stdatomic.h>

#define SENSOR_GPIO 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static atomic_int pulse_count = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    atomic_fetch_add(&pulse_count, 1);
}

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO %d.\n", SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetAlertFuncEx(SENSOR_GPIO, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert callback on GPIO %d.\n", SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int open_log_file(void)
{
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

static void log_rpm(float rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    if (fprintf(log_file, "%s %.2f\n", timestamp, rpm) < 0) {
        perror("Error writing to log file");
    } else {
        fflush(log_file);
    }
}

static void cleanup(void)
{
    gpioSetAlertFuncEx(SENSOR_GPIO, NULL, NULL);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (open_log_file() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    while (running) {
        atomic_store(&pulse_count, 0);
        time_sleep(SAMPLE_INTERVAL_SEC);

        int pulses = atomic_load(&pulse_count);
        float rpm = (float)pulses * 60.0f / (float)SAMPLE_INTERVAL_SEC;

        log_rpm(rpm);
        printf("RPM: %.2f\n", rpm);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

