#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE "rotation_log.txt"

/* Quadrature state machine: 0 = no rotation, 1 = CW, -1 = CCW */
static volatile int rotation_state = 0;
static volatile int running = 1;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

/* Quadrature decoder: returns 0, 1, or -1 on each edge */
static int quadrature_decode(int prev, int curr) {
    if (prev == 0 && curr == 1) return 1;  /* A rising -> B rising -> CW */
    if (prev == 1 && curr == 0) return -1; /* A falling -> B falling -> CCW */
    return 0;
}

/* pigpio alert callback (edge-triggered) */
static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (level != 0 && level != 1) return; /* ignore timeout/fail */

    int prev_state;
    pthread_mutex_lock(&state_mutex);
    prev_state = rotation_state;
    pthread_mutex_unlock(&state_mutex);

    int delta = quadrature_decode(prev_state, level);
    if (delta == 0) return; /* no rotation */

    pthread_mutex_lock(&state_mutex);
    rotation_state = delta;
    pthread_mutex_unlock(&state_mutex);
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
    pthread_mutex_lock(&state_mutex);
    rotation_state = 0;
    pthread_mutex_unlock(&state_mutex);
}

/* Log a rotation event with millisecond timestamp */
static void log_rotation(int direction) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s - Direction: %s\n", timestamp,
            direction == 1 ? "CW" : "CCW");
    fflush(log_file);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as inputs with pull-up resistors */
    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up resistors.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register signal handler: %s\n",
                strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register alert callbacks for both sensor pins */
    if (gpioSetAlertFunc(SENSOR_A_PIN, sensor_callback) != 0 ||
        gpioSetAlertFunc(SENSOR_B_PIN, sensor_callback) != 0) {
        fprintf(stderr, "Error: failed to set alert function.\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    /* Main loop: wait for rotation events */
    while (running) {
        int state;
        pthread_mutex_lock(&state_mutex);
        state = rotation_state;
        pthread_mutex_unlock(&state_mutex);

        if (state != 0) {
            log_rotation(state);
            pthread_mutex_lock(&state_mutex);
            rotation_state = 0;
            pthread_mutex_unlock(&state_mutex);
        }
        gpioDelay(10000); /* 10 ms sleep to reduce CPU usage */
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    gpioSetAlertFunc(SENSOR_A_PIN, NULL);
    gpioSetAlertFunc(SENSOR_B_PIN, NULL);
    fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&state_mutex);
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

