#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TOUCH_GPIO 17
#define LED_GPIO   18
#define DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch = NULL, *led = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    touch = gpiod_chip_get_line(chip, TOUCH_GPIO);
    if (!touch) {
        perror("gpiod_chip_get_line(touch)");
        goto cleanup;
    }

    led = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led) {
        perror("gpiod_chip_get_line(led)");
        goto cleanup;
    }

    if (gpiod_line_request_rising_edge_events(touch, "ttp223b-touch") < 0) {
        perror("gpiod_line_request_rising_edge_events");
        goto cleanup;
    }

    if (gpiod_line_request_output(led, "ttp223b-led", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Touch sensor on GPIO %d, LED on GPIO %d. Press Ctrl+C to exit.\n",
           TOUCH_GPIO, LED_GPIO);

    int led_state = 0;
    while (running) {
        struct gpiod_line_event event;
        int rc = gpiod_line_event_wait(touch, NULL);
        if (rc < 0) {
            perror("gpiod_line_event_wait");
            break;
        }
        if (rc == 0) {
            continue;
        }

        if (gpiod_line_event_read(touch, &event) < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        usleep(DEBOUNCE_MS * 1000);

        int val = gpiod_line_get_value(touch);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        if (val == 1) {
            led_state = !led_state;
            if (gpiod_line_set_value(led, led_state) < 0) {
                perror("gpiod_line_set_value");
                break;
            }
            printf("Touch detected, LED %s\n", led_state ? "ON" : "OFF");
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led) gpiod_line_release(led);
    if (touch) gpiod_line_release(touch);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

