#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} Event;

static Event event_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int overflow_count = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_1_PIN);
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_2_PIN);
        return -1;
    }

    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED GPIO %d low\n", LED_1_PIN);
        return -1;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED GPIO %d low\n", LED_2_PIN);
        return -1;
    }

    return 0;
}

static void log_event(int sensor_pin, time_t timestamp, int state) {
    event_buffer[buffer_index].sensor_pin = sensor_pin;
    event_buffer[buffer_index].timestamp = timestamp;
    event_buffer[buffer_index].state = state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_index == 0) {
        overflow_count++;
    }
}

static void print_log(void) {
    printf("\n--- Touch Sensor Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        if (event_buffer[idx].sensor_pin == 0 && event_buffer[idx].timestamp == 0 && event_buffer[idx].state == 0) {
            break;
        }
        char state_str[8];
        snprintf(state_str, sizeof(state_str), "%s", event_buffer[idx].state ? "Touched" : "Released");
        printf("Sensor: GPIO %d, Timestamp: %ld, State: %s\n",
               event_buffer[idx].sensor_pin,
               (long)event_buffer[idx].timestamp,
               state_str);
    }
    printf("Overflow count: %d\n", overflow_count);
    printf("--- End of Log ---\n\n");
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO %d\n", SENSOR_1_PIN);
        } else {
            int target = s1 ? 1 : 0;
            if (gpioWrite(LED_1_PIN, target) != 0) {
                fprintf(stderr, "Warning: gpioWrite failed on GPIO %d\n", LED_1_PIN);
            }
            log_event(SENSOR_1_PIN, time(NULL), target);
        }

        if (s2 < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO %d\n", SENSOR_2_PIN);
        } else {
            int target = s2 ? 1 : 0;
            if (gpioWrite(LED_2_PIN, target) != 0) {
                fprintf(stderr, "Warning: gpioWrite failed on GPIO %d\n", LED_2_PIN);
            }
            log_event(SENSOR_2_PIN, time(NULL), target);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
    print_log();
    printf("Program terminated.\n");
    return 0;
}

