#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define DEBOUNCE_US 5000
#define PULSES_PER_REV 2
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;
static volatile int last_sensor1_state = -1;
static volatile int last_sensor2_state = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(int s1, int s2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%d,%d\n", ts, s1, s2);
    } else {
        fprintf(fp, "unknown,%d,%d\n", s1, s2);
    }
    fclose(fp);
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)tick;
    (void)userdata;
    if (level == PI_HIGH) {
        int *state = (int *)userdata;
        if (gpio == SENSOR1_GPIO) {
            *state = 1;
        } else if (gpio == SENSOR2_GPIO) {
            *state = 2;
        }
    } else if (level == PI_LOW) {
        int *state = (int *)userdata;
        *state = 0;
    }
}

static void calculate_rpm(int *s1_state, int *s2_state, double *rpm) {
    static uint32_t last_tick1 = 0;
    static uint32_t last_tick2 = 0;
    uint32_t now = gpioTick();

    if (*s1_state == 1 && last_sensor1_state == 0) {
        uint32_t diff = now - last_tick1;
        if (diff > DEBOUNCE_US) {
            *rpm = 60000000.0 / (double)diff * PULSES_PER_REV;
            last_tick1 = now;
        }
    } else if (*s1_state == 0 && last_sensor1_state == 1) {
        last_tick1 = now;
    }

    if (*s2_state == 2 && last_sensor2_state == 0) {
        uint32_t diff = now - last_tick2;
        if (diff > DEBOUNCE_US) {
            *rpm = 60000000.0 / (double)diff * PULSES_PER_REV;
            last_tick2 = now;
        }
    } else if (*s2_state == 0 && last_sensor2_state == 2) {
        last_tick2 = now;
    }

    last_sensor1_state = *s1_state;
    last_sensor2_state = *s2_state;
}

int main(void) {
    int s1_state = 0, s2_state = 0;
    double rpm = 0.0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-ups\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(SENSOR1_GPIO, pulse_callback, &s1_state) != 0 ||
        gpioSetAlertFuncEx(SENSOR2_GPIO, pulse_callback, &s2_state) != 0) {
        fprintf(stderr, "Failed to set alert functions\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring RPM on GPIO %d and %d. Press Ctrl+C to exit.\n",
           SENSOR1_GPIO, SENSOR2_GPIO);

    while (running) {
        calculate_rpm(&s1_state, &s2_state, &rpm);
        if (rpm > 0.0) {
            printf("RPM: %.2f\n", rpm);
        }
        log_data(s1_state, s2_state);
        gpioDelay(100000);
    }

    printf("\nExiting gracefully...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

