#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x28

#define REG_PART_ID 0x00
#define REG_HR_DATA 0x02
#define REG_SPO2_DATA 0x04
#define REG_CONFIG 0x30

#define EXPECTED_PART_ID 0x82
#define CONFIG_CONT_MEAS 0x01

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, int *heart_rate, int *spo2) {
    uint8_t hr_raw, spo2_raw;

    if (read_register(handle, REG_HR_DATA, &hr_raw) != 0) return -1;
    if (read_register(handle, REG_SPO2_DATA, &spo2_raw) != 0) return -1;

    *heart_rate = (int)hr_raw;
    *spo2 = (int)spo2_raw;
    return 0;
}

static void log_data(FILE *fp, int heart_rate, int spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(fp);
}

int main(void) {
    int heart_rate, spo2;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    uint8_t part_id;
    if (read_register(i2c_handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Sensor not detected (PART_ID read failed)\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_register(i2c_handle, REG_CONFIG, CONFIG_CONT_MEAS) != 0) {
        fprintf(stderr, "Failed to configure sensor for continuous measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!terminate) {
        if (read_sensor_data(i2c_handle, &heart_rate, &spo2) == 0) {
            log_data(log_file, heart_rate, spo2);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(1);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

