#define ALARM_PIN    27
#define LOG_FILE     "bridge_integrity.log"
#define POLL_DELAY_US 100000   /* 100 ms */
#define TILT_THRESHOLD_US 2000000 /* 2 seconds */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
        fprintf(log_file, "%s: %s\n", ts, event);
        fflush(log_file);
    }
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure alarm is off before terminating pigpio */
    gpioWrite(ALARM_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ALARM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) < 0 ||
        gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistors\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALARM_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize alarm pin LOW\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");
    log_event("Monitoring started");

