                tilt_active = 1;
                tilt_start_tick = gpioTick();
                log_event("Tilt threshold exceeded (both sensors HIGH)");
            } else {
                if (gpioTick() - tilt_start_tick > TILT_THRESHOLD_US) {
                    if (!alarm_active) {
                        if (gpioWrite(ALARM_PIN, 1) == 0) {
                            alarm_active = 1;
                            log_event("Alarm activated");
                        } else {
                            fprintf(stderr, "Failed to activate alarm\n");
                        }
                    }
                }
            }
        } else {
            if (tilt_active) {
                tilt_active = 0;
                log_event("Tilt ended (sensors LOW)");
            }
            if (alarm_active) {
                if (gpioWrite(ALARM_PIN, 0) == 0) {
                    alarm_active = 0;
                    log_event("Alarm deactivated");
                } else {
                    fprintf(stderr, "Failed to deactivate alarm\n");
                }
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    log_event("Monitoring stopped");
    cleanup();
    return EXIT_SUCCESS;
}

