/*
 * Raspberry Pi 3 Model B+ - Omron D7S-A0011 Seismic Sensor Monitor
 *
 * Wiring:
 *   D7S SDA -> GPIO2 (I2C1 SDA)
 *   D7S SCL -> GPIO3 (I2C1 SCL)
 *   D7S VDD -> 3.3 V
 *   D7S GND -> GND
 *   LED anode -> GPIO17 (with 330 ohm series resistor) -> GND
 *
 * Build: gcc -O2 -Wall -o seismic seismic.c -lpigpio -lm -lrt
 * Run:   sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x1D          /* D7S-A0011 7-bit I2C address      */
#define CTRL1_REG            0x1F          /* Control register 1                */
#define CTRL1_CLEAR_PD_BIT   0x01          /* Bit 0 = power-down (0 = active)   */
#define ACCEL_XOUT_L_REG     0x28          /* Accel X-axis LSB                  */
#define ACCEL_XOUT_H_REG     0x29
#define ACCEL_YOUT_L_REG     0x2A
#define ACCEL_YOUT_H_REG     0x2B
#define ACCEL_ZOUT_L_REG     0x2C
#define ACCEL_ZOUT_H_REG     0x2D
#define LED_GPIO             17
#define VIBRATION_THRESHOLD  500.0f        /* Raw magnitude threshold           */
#define SAMPLE_PERIOD_US     100000        /* 100 ms                            */
#define LED_ON_DURATION_US   1000000       /* 1 s                               */
#define MAX_RETRIES          3
#define LOG_FILE             "seismic_events.log"

/* ----------------------------- Globals ----------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_sensor(void);
static int  read_acceleration(int16_t *x, int16_t *y, int16_t *z);
static float calculate_magnitude(int16_t x, int16_t y, int16_t z);
static void control_led(int on);
static void log_event(float magnitude);
static void cleanup(void);

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ----------------------------- I2C Init ---------------------------------- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- Sensor Init ------------------------------- */
static int init_sensor(void)
{
    /* Read current CTRL1 value */
    int ctrl1 = i2cReadByteData(i2c_handle, CTRL1_REG);
    if (ctrl1 < 0) {
        fprintf(stderr, "Error: failed to read CTRL1 register: %d\n", ctrl1);
        return -1;
    }

    /* Clear power-down bit (bit 0) */
    int new_ctrl1 = ctrl1 & ~CTRL1_CLEAR_PD_BIT;
    if (i2cWriteByteData(i2c_handle, CTRL1_REG, new_ctrl1) < 0) {
        fprintf(stderr, "Error: failed to write CTRL1 register\n");
        return -1;
    }

    /* Verify write by reading back */
    int verify = i2cReadByteData(i2c_handle, CTRL1_REG);
    if (verify < 0 || (verify & CTRL1_CLEAR_PD_BIT) != 0) {
        fprintf(stderr, "Error: CTRL1 verification failed (read=0x%02X)\n", verify);
        return -1;
    }

    return 0;
}

/* ----------------------------- Read Acceleration -------------------------- */
static int read_acceleration(int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];

    /* Read 6 bytes starting at ACCEL_XOUT_L_REG (0x28) */
    int bytes = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_L_REG, buf, 6);
    if (bytes != 6) {
        fprintf(stderr, "Error: i2cReadI2CBlockData returned %d (expected 6)\n", bytes);
        return -1;
    }

    *x = (int16_t)((uint16_t)buf[1] << 8 | (uint8_t)buf[0]);
    *y = (int16_t)((uint16_t)buf[3] << 8 | (uint8_t)buf[2]);
    *z = (int16_t)((uint16_t)buf[5] << 8 | (uint8_t)buf[4]);
    return 0;
}

/* ----------------------------- Magnitude Calc ---------------------------- */
static float calculate_magnitude(int16_t x, int16_t y, int16_t z)
{
    float fx = (float)x;
    float fy = (float)y;
    float fz = (float)z;
    return sqrtf(fx * fx + fy * fy + fz * fz);
}

/* ----------------------------- LED Control ------------------------------- */
static void control_led(int on)
{
    gpioWrite(LED_GPIO, on ? 1 : 0);
}

/* ----------------------------- Log Event --------------------------------- */
static void log_event(float magnitude)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (log_file) {
        fprintf(log_file, "%s, %.2f\n", ts, magnitude);
        fflush(log_file);
    } else {
        fprintf(stderr, "Warning: log file not open\n");
    }
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    control_led(0);

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor() != 0) {
        fprintf(stderr, "Error: sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic monitor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        int16_t x = 0, y = 0, z = 0;
        bool read_ok = false;

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_acceleration(&x, &y, &z) == 0) {
                read_ok = true;
                break;
            }
            fprintf(stderr, "Warning: read attempt %d/%d failed\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(10000); /* 10 ms backoff */
        }

        if (!read_ok) {
            fprintf(stderr, "Error: sensor read failed after %d attempts\n",
                    MAX_RETRIES);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude > VIBRATION_THRESHOLD) {
            control_led(1);
            log_event(magnitude);
            gpioDelay(LED_ON_DURATION_US);
            control_led(0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

