        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor() != 0) {
        fprintf(stderr, "Error: sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic monitor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        int16_t x = 0, y = 0, z = 0;
        bool read_ok = false;

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_acceleration(&x, &y, &z) == 0) {
                read_ok = true;
                break;
            }
            fprintf(stderr, "Warning: read attempt %d/%d failed\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(10000); /* 10 ms backoff */
        }

        if (!read_ok) {
            fprintf(stderr, "Error: sensor read failed after %d attempts\n",
                    MAX_RETRIES);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude > VIBRATION_THRESHOLD) {
            control_led(1);
            log_event(magnitude);
            gpioDelay(LED_ON_DURATION_US);
            control_led(0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

