/*
 * flame_monitor.c — KY-026 flame sensor monitor for Raspberry Pi 3 B+
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor   (root needed for /var/log write)
 *
 * Sensors: 5 Keyes KY-026 on BCM GPIO 2, 3, 4, 17, 27
 *   (physical pins 3, 5, 7, 11, 13)
 *   Digital output: LOW = flame detected, HIGH = no flame
 *   VCC: 3.3 V, GND: GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/file.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS   5
#define LOG_FILE      "/var/log/flame_events.log"
#define POLL_INTERVAL 1          /* seconds between polls */
#define DEBOUNCE_MS   50         /* debounce re-read window */

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
static const char *sensor_ids[NUM_SENSORS] = {"S1", "S2", "S3", "S4", "S5"};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped flame event line to the log file.              */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_flame_event(int sensor_id, unsigned int pin)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "fopen(%s): %s", LOG_FILE, strerror(errno));
        return -1;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock(LOCK_EX): %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        syslog(LOG_ERR, "time(): %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r() failed");
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %u) - Flame Detected\n",
                ts, sensor_id, pin) < 0) {
        syslog(LOG_ERR, "fprintf(): %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "fflush(): %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "flock(LOCK_UN): %s", strerror(errno));
    }

    if (fclose(fp) == EOF) {
        syslog(LOG_ERR, "fclose(): %s", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single sensor line.                                         */
/* Returns 0 or 1 on success, -1 on error.                            */
/* ------------------------------------------------------------------ */
static int read_sensor(struct gpiod_line *line, const char *id,
                       unsigned int pin)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        syslog(LOG_ERR, "gpiod_line_get_value(%s, GPIO %u): %s",
               id, pin, strerror(errno));
        return -1;
    }
    return val;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- Open the default gpiochip (gpiochip0 on Pi 3 B+) ---- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(gpiochip0): %s",
               strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- Acquire each sensor line ---- */
    struct gpiod_line *lines[NUM_SENSORS];
    int line_acquired[NUM_SENSORS];
    int acquired_count = 0;

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "gpiod_chip_get_line(GPIO %u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup_chip;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(GPIO %u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup_chip;
        }

        line_acquired[i] = 1;
        acquired_count++;
    }

    syslog(LOG_INFO, "Flame sensor monitoring started (GPIO %u, %u, %u, %u, %u)",
           sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    /* ---- Main polling loop ---- */
    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = read_sensor(lines[i], sensor_ids[i], sensor_pins[i]);
            if (val < 0) {
                /* Per-sensor read failure — log and continue */
                continue;
            }

            /* KY-026 digital output: LOW (0) means flame detected */
            if (val == 0) {
                /* Debounce: re-read after 50 ms */
                struct timespec ts = {0, DEBOUNCE_MS * 1000000L};
                nanosleep(&ts, NULL);

                int confirm = read_sensor(lines[i], sensor_ids[i],
                                          sensor_pins[i]);
                if (confirm < 0) {
                    continue;          /* re-read error — skip */
                }
                if (confirm == 0) {
                    if (log_flame_event(i + 1, sensor_pins[i]) == 0) {
                        syslog(LOG_INFO,
                               "Flame detected on sensor %d (GPIO %u)",
                               i + 1, sensor_pins[i]);
                    }
                }
            }
        }

        /* Sleep POLL_INTERVAL seconds, but wake early on signal */
        for (int s = 0; s < POLL_INTERVAL && g_running; s++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down flame sensor monitoring");

    /* ---- Release all acquired lines ---- */
    for (int i = 0; i < acquired_count; i++) {
        if (line_acquired[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    closelog();
    return EXIT_SUCCESS;

    /* ---- Error path: release lines and close chip ---- */
cleanup_chip:
    for (int i = 0; i < acquired_count; i++) {
        if (line_acquired[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    gpiod_chip_close(chip);
    closelog();
    return EXIT_FAILURE;
}

