#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"

#define VEML7700_ALS_CONF_REG 0x00
#define VEML7700_ALS_REG 0x04

#define VEML7700_ALS_GAIN_1_8 0x00
#define VEML7700_ALS_IT_100MS 0x00

#define LUX_PER_COUNT 0.0576f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int veml7700_init(int handle) {
    uint16_t config = (VEML7700_ALS_GAIN_1_8 << 11) | (VEML7700_ALS_IT_100MS << 6);
    char buf[3] = { VEML7700_ALS_CONF_REG, (char)(config & 0xFF), (char)((config >> 8) & 0xFF) };
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing VEML7700 config register\n");
        return -1;
    }
    return 0;
}

static int veml7700_read_als(int handle, uint16_t *als) {
    char reg = VEML7700_ALS_REG;
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error setting ALS register pointer\n");
        return -1;
    }
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading ALS data\n");
        return -1;
    }
    *als = (uint16_t)((uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static int calculate_brightness(uint16_t lux) {
    if (lux < 100) return 100;
    if (lux < 500) return 75;
    if (lux < 1000) return 50;
    return 25;
}

static void log_data(uint16_t lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s, Lux: %u, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (veml7700_init(i2c_handle) != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        uint16_t lux_raw;
        int error_code = 0;

        if (veml7700_read_als(i2c_handle, &lux_raw) != 0) {
            error_code = -1;
        }

        int brightness = 0;
        if (error_code == 0) {
            brightness = calculate_brightness((uint16_t)(lux_raw * LUX_PER_COUNT));
            gpioPWM(LED_GPIO, brightness);
        } else {
            gpioPWM(LED_GPIO, 0);
        }

        log_data(lux_raw, brightness, error_code);
        sleep(1);
    }

    cleanup();
    return 0;
}

