#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define NUM_CHANNELS 8
#define LED_GPIO 17
#define POLL_DELAY_US 50000  /* 50 ms */
#define DEBOUNCE_MS 50

static const int channel_gpios[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_touch_event(int channel) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];
    FILE *fp;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    fp = fopen("touch_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening touch_log.txt: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s - Channel %d Touched\n", timestamp, channel) < 0) {
        fprintf(stderr, "Error writing to touch_log.txt: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing touch_log.txt: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void control_led(int state) {
    if (gpioWrite(LED_GPIO, state) != 0) {
        fprintf(stderr, "Warning: gpioWrite(LED_GPIO, %d) failed\n", state);
    }
}

int main(void) {
    int prev_state[NUM_CHANNELS];
    int current_state[NUM_CHANNELS];
    int led_state = 0;
    int i;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(channel_gpios[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", channel_gpios[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(channel_gpios[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down on GPIO %d\n", channel_gpios[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        prev_state[i] = gpioRead(channel_gpios[i]);
        if (prev_state[i] < 0) {
            fprintf(stderr, "Failed to read initial state of GPIO %d\n", channel_gpios[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_led(0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Security Keypad started. Press Ctrl+C to exit.\n");

    while (running) {
        int any_touched = 0;

        for (i = 0; i < NUM_CHANNELS; i++) {
            current_state[i] = gpioRead(channel_gpios[i]);
            if (current_state[i] < 0) {
                fprintf(stderr, "Failed to read GPIO %d\n", channel_gpios[i]);
                continue;
            }

            if (current_state[i] == 1 && prev_state[i] == 0) {
                if (log_touch_event(i + 1) != 0) {
                    fprintf(stderr, "Failed to log touch event for channel %d\n", i + 1);
                }
                any_touched = 1;
            }
            prev_state[i] = current_state[i];
        }

        if (any_touched) {
            if (!led_state) {
                control_led(1);
                led_state = 1;
            }
        } else {
            if (led_state) {
                control_led(0);
                led_state = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    control_led(0);
    gpioTerminate();
    printf("\nSecurity Keypad stopped.\n");
    return EXIT_SUCCESS;
}

