    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Security Keypad started. Press Ctrl+C to exit.\n");

    while (running) {
        int any_touched = 0;

        for (i = 0; i < NUM_CHANNELS; i++) {
            current_state[i] = gpioRead(channel_gpios[i]);
            if (current_state[i] < 0) {
                fprintf(stderr, "Failed to read GPIO %d\n", channel_gpios[i]);
                continue;
            }

            if (current_state[i] == 1 && prev_state[i] == 0) {
                if (log_touch_event(i + 1) != 0) {
                    fprintf(stderr, "Failed to log touch event for channel %d\n", i + 1);
                }
                any_touched = 1;
            }
            prev_state[i] = current_state[i];
        }

        if (any_touched) {
            if (!led_state) {
                control_led(1);
                led_state = 1;
            }
        } else {
            if (led_state) {
                control_led(0);
                led_state = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    control_led(0);
    gpioTerminate();
    printf("\nSecurity Keypad stopped.\n");
    return EXIT_SUCCESS;
}

