#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00

/* Configuration word: RN[3:0]=1100 (auto-range), CT=00 (100ms), M[2:0]=000 (continuous), FC=0 */
#define CONFIG_WORD 0xC810

#define I2C_BUS 1
#define LOG_FILE "light_data.txt"
#define SAMPLE_INTERVAL_US 1000000
#define CONVERSION_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_config(uint16_t config) {
    /* OPT3001 expects big-endian (MSB first), pigpio i2cWriteWordData sends as little-endian */
    uint16_t swapped = ((config & 0xFF00) >> 8) | ((config & 0x00FF) << 8);
    int rc = i2cWriteWordData(i2c_handle, CONFIG_REG, swapped);
    if (rc < 0) {
        fprintf(stderr, "Error writing config register: %s\n", pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int read_result(uint16_t *result) {
    int rc = i2cReadWordData(i2c_handle, RESULT_REG);
    if (rc < 0) {
        fprintf(stderr, "Error reading result register: %s\n", pigpio_error(rc));
        return -1;
    }
    /* pigpio returns little-endian word; swap to get big-endian value */
    *result = ((rc & 0xFF00) >> 8) | ((rc & 0x00FF) << 8);
    return 0;
}

static float calculate_lux(uint16_t raw) {
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    return (float)mantissa * 0.01f * (float)(1u << exponent);
}

static int log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, OPT3001_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_config(CONFIG_WORD) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Wait for first conversion to complete */
    gpioDelay(CONVERSION_DELAY_US);

    while (running) {
        uint16_t raw;
        if (read_result(&raw) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float lux = calculate_lux(raw);
        printf("Lux: %.2f\n", lux);

        if (log_data(lux) != 0) {
            fprintf(stderr, "Warning: failed to log data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

