#include <errno.h>

#define FLAME_SENSOR_PIN 4
#define ALERT_LED_PIN 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_MS 500
#define ALERT_DURATION_MS 1000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        log_event("Error reading flame sensor.");
        return -1;
    }
    return value;
}

static void trigger_alert(void) {
    if (gpioWrite(ALERT_LED_PIN, 1) < 0) {
        log_event("Error setting alert LED HIGH.");
        return;
    }
    gpioDelay(ALERT_DURATION_MS * 1000);
    if (gpioWrite(ALERT_LED_PIN, 0) < 0) {
        log_event("Error setting alert LED LOW.");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        log_event("Error setting flame sensor pin as input.");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ALERT_LED_PIN, PI_OUTPUT) < 0) {
        log_event("Error setting alert LED pin as output.");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(ALERT_LED_PIN, 0) < 0) {
        log_event("Error resetting alert LED to LOW.");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    log_event("Flame sensor monitoring started.");

    while (running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected == 0) {
            log_event("Flame detected!");
            trigger_alert();
        } else if (flame_detected < 0) {
            log_event("Sensor read error, skipping alert.");
        }
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    log_event("Flame sensor monitoring stopped.");
    gpioWrite(ALERT_LED_PIN, 0);
    gpioTerminate();
    if (log_file) fclose(log_file);
    return 0;
}

