        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (value != prev_value) {
            if (value == 1) {
                if (log_event(fp, "Touch Detected") != 0) {
                    fprintf(stderr, "Failed to log touch detected event.\n");
                }
            } else {
                if (log_event(fp, "Touch Released") != 0) {
                    fprintf(stderr, "Failed to log touch released event.\n");
                }
            }
            prev_value = value;
        }

        usleep(DEBOUNCE_MS * 1000);
    }

    ret = EXIT_SUCCESS;

    if (fclose(fp) != 0)
        perror("fclose");

cleanup_line:
    gpiod_line_release(line);

cleanup_chip:
    gpiod_chip_close(chip);

    return ret;
}

