#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x08
#define FLOW_LOG_FILE "cooling_log.csv"
#define SAMPLE_INTERVAL_US 1000000
#define MEAS_DELAY_US 2000
#define FLOW_SCALE 90.0f
#define FLOW_MIN 0.0f
#define FLOW_MAX 100.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int start_measurement(void) {
    char cmd[2] = {0x36, 0x08};
    int rc = i2cWriteDevice(i2c_handle, cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", rc);
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);
    return 0;
}

static int read_flow(float *flow_out, int *flags_out) {
    char buf[3];
    int rc = i2cReadDevice(i2c_handle, buf, 3);
    if (rc != 3) {
        fprintf(stderr, "Error reading I2C data: expected 3 bytes, got %d\n", rc);
        return -1;
    }
    if (crc8((uint8_t *)buf, 2) != (uint8_t)buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }
    int16_t raw = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    *flow_out = (float)raw / FLOW_SCALE;
    *flags_out = 0;
    return 0;
}

static void log_data(float flow, int flags, const char *status) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s,%.2f,%s\n", ts, flow, status);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (start_measurement() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(FLOW_LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(log_file);
    }

    while (running) {
        float flow = 0.0f;
        int flags = 0;
        int rc = read_flow(&flow, &flags);
        if (rc != 0) {
            fprintf(stderr, "Read failed, attempting I2C re-init...\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "Re-init failed, exiting.\n");
                break;
            }
            if (start_measurement() != 0) {
                fprintf(stderr, "Re-start failed, exiting.\n");
                break;
            }
            continue;
        }

        if (flow < FLOW_MIN || flow > FLOW_MAX) {
            log_data(flow, flags, "INVALID");
        } else {
            log_data(flow, flags, "OK");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

