        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(left_line, "ky033_left") != 0) {
        fprintf(stderr, "Failed to request left line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(middle_line, "ky033_middle") != 0) {
        fprintf(stderr, "Failed to request middle line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(right_line, "ky033_right") != 0) {
        fprintf(stderr, "Failed to request right line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        goto cleanup;
    }

    printf("Logging KY-033 sensor data to %s. Press Ctrl+C to stop.\n", LOG_FILE_NAME);

    while (g_running) {
        int left_val = gpiod_line_get_value(left_line);
        int middle_val = gpiod_line_get_value(middle_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || middle_val < 0 || right_val < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
            break;
        }

        char timestamp[32];
        get_timestamp(timestamp, sizeof(timestamp));

        if (log_data(log_file, timestamp, left_val, middle_val, right_val) != 0) {
            break;
        }

        struct timespec delay = {0, POLL_INTERVAL_MS * 1000000L};
        nanosleep(&delay, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    if (left_line != NULL) gpiod_line_release(left_line);
    if (middle_line != NULL) gpiod_line_release(middle_line);
    if (right_line != NULL) gpiod_line_release(right_line);
    if (chip != NULL) gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return ret;
}

