    struct gpiod_line *line = NULL;
    struct gpiod_line_event event;
    struct timespec ts = {0, 100000000}; /* 100ms poll timeout */

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_falling_edge_events(line, "flame_sensor") < 0) {
        perror("Failed to request falling edge events on GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (program_running) {
        int ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("Error waiting for GPIO event");
            break;
        }
        if (ret == 0) {
            continue; /* Timeout, no event */
        }

        if (gpiod_line_event_read(line, &event) < 0) {
            perror("Error reading GPIO event");
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

            printf("Flame detected at: %s\n", timestamp);
            log_event(timestamp);
        }
    }

    printf("\nExiting gracefully...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

