/*
 * Flame Detection Safety System for Raspberry Pi 3 Model B+
 * Uses libgpiod (character-device API) — no wiringPi, sysfs.
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 * Run:    sudo ./flame_alert   (root needed for /dev/gpiochip0 on some kernels)
 */

#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN  17   /* GPIO17, physical pin 11 */
#define BUZZER_PIN        18   /* GPIO18, physical pin 12 */
#define POLL_INTERVAL_MS  500
#define BUZZER_DURATION_MS 2000
#define POLL_SLICE_MS     100
#define LOG_FILE          "alert_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(FILE *log, const char *event)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[64];

    if (t == NULL) {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    if (fprintf(log, "%s: %s\n", ts, event) < 0) {
        perror("fprintf to log");
    }
    fflush(log);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    FILE *log = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    log_event(log, "System started");

    /* ---- Open gpiochip0 ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    /* ---- Get lines ---- */
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (flame_line == NULL) {
        perror("gpiod_chip_get_line(flame)");
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (buzzer_line == NULL) {
        perror("gpiod_chip_get_line(buzzer)");
        goto cleanup;
    }

    /* ---- Request flame line as input ---- */
    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        perror("gpiod_line_request_input(flame)");
        goto cleanup;
    }

    /* ---- Request buzzer line as output, initial value LOW ---- */
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("gpiod_line_request_output(buzzer)");
        goto cleanup;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    int last_flame = 1;   /* assume no flame at startup (HIGH = no flame) */

    while (g_running) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            perror("gpiod_line_get_value(flame)");
            break;
        }

        /* Detect HIGH -> LOW transition (flame newly detected) */
        if (val == 0 && last_flame == 1) {
            log_event(log, "Flame detected!");
            printf("Flame detected!\n");

            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                perror("gpiod_line_set_value(buzzer ON)");
                break;
            }

            /* Non-blocking 2-second buzzer pulse using slices */
            for (int i = 0; i < BUZZER_DURATION_MS / POLL_SLICE_MS && g_running; i++) {
                usleep(POLL_SLICE_MS * 1000);
            }

            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                perror("gpiod_line_set_value(buzzer OFF)");
                break;
            }
        }

        last_flame = val;

        /* Poll every 500 ms */
        for (int i = 0; i < POLL_INTERVAL_MS / POLL_SLICE_MS && g_running; i++) {
            usleep(POLL_SLICE_MS * 1000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Ensure buzzer is off ---- */
    if (buzzer_line != NULL) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (flame_line != NULL) {
        gpiod_line_release(flame_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log != NULL) {
        log_event(log, "System stopped");
        fclose(log);
    }

    printf("Exiting.\n");
    return ret;
}

