/*
 * TMAG5110A1 Hall-effect latch magnetic sensor monitor.
 *
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (http://abyz.me.uk/rpi/pigpio/)
 *
 * Three TMAG5110A1 sensors are wired as open-drain Hall-effect latches:
 *   - OUT  -> GPIO4   (BCM)
 *   - OUT  -> GPIO17  (BCM)
 *   - OUT  -> GPIO27  (BCM)
 *   - VCC  -> 3.3 V
 *   - GND  -> GND
 *
 * An external pull-up resistor (e.g. 4.7 kΩ) is required between the
 * sensor OUT pin and the Pi GPIO pin so that the sensor's open-drain
 * output is never floating.  The internal pull-up on the Pi GPIO is
 * enabled so that the line is defined when the sensor output is high.
 *
 * The TMAG5110A1 OUT pin is active-low: it reads LOW when a south
 * magnetic pole is near and HIGH when the pole is removed.  This
 * matches the internal pull-up: a logic low means magnet-present
 * (state 0), a logic high means magnet-removed (state 1).
 *
 * Build:  gcc -Wall -Wextra -O2 -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:    sudo ./magnet_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

#define LOG_FILE      "magnet_log.txt"
#define POLL_DELAY_US 100000          /* 100 ms */
#define TIMESTAMP_LEN 32

/* ------------------------------------------------------------------ */
/* Global state for signal handler                                     */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write an ISO-8601 timestamp into buf (thread-safe wrt signal-handler) */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00");
    }
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0 (magnet present), 1 (magnet removed),
 * or -1 on error.                                                */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "gpioRead failed on pin %d (rc=%d)\n", pin, level);
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* Log a state change with an ISO-8601 timestamp.                      */
/* ------------------------------------------------------------------ */
static void log_state_change(int sensor_id, int state)
{
    char ts[TIMESTAMP_LEN];

    get_timestamp(ts, sizeof(ts));

    if (g_log_fp != NULL) {
        fprintf(g_log_fp, "%s - Sensor %d: %s\n",
                ts, sensor_id, state == 0 ? "MAGENT_PRESENT" : "MAGNET_REMOVED");
        fflush(g_log_fp);
    } else {
        fprintf(stderr, "Log file not open; state change for sensor %d lost.\n",
                sensor_id);
    }
}

/* ------------------------------------------------------------------ */
/* Initialize a GPIO pin as input with internal pull-up.              */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int init_sensor_pin(int pin)
{
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int prev1 = -1, prev2 = -1, prev3 = -1;
    int rc = EXIT_SUCCESS;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins ---- */
    if (init_sensor_pin(SENSOR1_PIN) != 0 ||
        init_sensor_pin(SENSOR2_PIN) != 0 ||
        init_sensor_pin(SENSOR3_PIN) != 0) {
        fprintf(stderr, "Failed to configure sensor GPIO pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Magnet sensor monitoring started.\n");
    printf("  Sensor 1: GPIO%d\n", SENSOR1_PIN);
    printf("  Sensor 2: GPIO%d\n", SENSOR2_PIN);
    printf("  Sensor 3: GPIO%d\n", SENSOR3_PIN);
    printf("  Log file: %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    while (g_running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);
        int s3 = read_sensor(SENSOR3_PIN);

        if (s1 >= 0 && s1 != prev1) {
            log_state_change(1, s1);
            prev1 = s1;
        }
        if (s2 >= 0 && s2 != prev2) {
            log_state_change(2, s2);
            prev2 = s2;
        }
        if (s3 >= 0 && s3 != prev3) {
            log_state_change(3, s3);
            prev3 = s3;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
    printf("Cleanup complete.\n");
    return rc;
}

