/*
 * TTP226 8-channel capacitive touch sensor -> 8-bit counter on Raspberry Pi Zero W.
 *
 * Wiring (BCM numbering):
 *   TTP226 OUT1 -> GPIO5   OUT2 -> GPIO6   OUT3 -> GPIO7   OUT4 -> GPIO8
 *   TTP226 OUT5 -> GPIO9   OUT6 -> GPIO10  OUT7 -> GPIO11  OUT8 -> GPIO12
 *   Counter bits 0..7 -> GPIO17 (bit 0), GPIO24 (bit 7)
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define LOG_FILE     "touch_log.txt"
#define POLL_MS      10
#define STABILIZE_MS 200

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int output_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(FILE *fp, int channel, int counter)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (fp == NULL) {
        fprintf(stderr, "log_event: log file unavailable\n");
        return;
    }
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "log_event: localtime_r failed\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm) == 0) {
        fprintf(stderr, "log_event: strftime failed\n");
        return;
    }
    if (fprintf(fp, "%s, Channel: %d, Counter: %d\n", ts, channel, counter) < 0) {
        fprintf(stderr, "log_event: fprintf failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(fp) != 0)
        fprintf(stderr, "log_event: fflush failed: %s\n", strerror(errno));
}

static void set_outputs(struct gpiod_line_request *req, int counter)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int val = (counter >> i) & 1;
        if (gpiod_line_request_set_value(req, output_pins[i], val) < 0)
            fprintf(stderr, "set_outputs: set_value failed on GPIO%u: %s\n",
                    output_pins[i], strerror(errno));
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *sensor_req = NULL;
    struct gpiod_line_request *output_req = NULL;
    struct gpiod_line_config *sensor_cfg = NULL;
    struct gpiod_line_config *output_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    int counter = 0;
    int prev_state[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++)
        prev_state[i] = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Sensor lines: input, active-high (TTP226 OUT1-OUT8) */
    sensor_cfg = gpiod_line_config_new();
    if (!sensor_cfg) {
        fprintf(stderr, "gpiod_line_config_new (sensor) failed\n");
        goto cleanup;
    }
    settings = gpiod_line_settings_new();
    if (!settings) {
        fprintf(stderr, "gpiod_line_settings_new failed\n");
        goto cleanup;
    }
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_DOWN);

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_config_add_line_settings(sensor_cfg, &sensor_pins[i], 1, settings) < 0) {
            fprintf(stderr, "gpiod_line_config_add_line_settings (sensor GPIO%u) failed: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    sensor_req = gpiod_chip_request_lines(chip, NULL, sensor_cfg);
    if (!sensor_req) {
        fprintf(stderr, "gpiod_chip_request_lines (sensor) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Output lines: output, initial value 0 */
    output_cfg = gpiod_line_config_new();
    if (!output_cfg) {
        fprintf(stderr, "gpiod_line_config_new (output) failed\n");
        goto cleanup;
    }
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_settings_set_output_value(settings, GPIOD_LINE_VALUE_INACTIVE);

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_config_add_line_settings(output_cfg, &output_pins[i], 1, settings) < 0) {
            fprintf(stderr, "gpiod_line_config_add_line_settings (output GPIO%u) failed: %s\n",
                    output_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    output_req = gpiod_chip_request_lines(chip, NULL, output_cfg);
    if (!output_req) {
        fprintf(stderr, "gpiod_chip_request_lines (output) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Stabilize sensor lines */
    usleep(STABILIZE_MS * 1000);

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Warning: cannot open %s: %s; logging to stdout only\n",
                LOG_FILE, strerror(errno));
    }

    printf("Touch counter running. Press Ctrl+C to exit.\n");

    while (g_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_request_get_value(sensor_req, sensor_pins[i]);
            if (val < 0) {
                fprintf(stderr, "read sensor GPIO%u failed: %s\n",
                        sensor_pins[i], strerror(errno));
                continue;
            }
            int active = (val == GPIOD_LINE_VALUE_ACTIVE);
            if (active && !prev_state[i]) {
                counter = (counter + 1) & 0xFF;
                set_outputs(output_req, counter);
                if (log_fp)
                    log_event(log_fp, i + 1, counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
            prev_state[i] = active;
        }
        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (output_req) {
        for (int i = 0; i < NUM_CHANNELS; i++)
            gpiod_line_request_set_value(output_req, output_pins[i], GPIOD_LINE_VALUE_INACTIVE);
        gpiod_line_request_release(output_req);
    }
    if (sensor_req)
        gpiod_line_request_release(sensor_req);
    if (settings)
        gpiod_line_settings_free(settings);
    if (output_cfg)
        gpiod_line_config_free(output_cfg);
    if (sensor_cfg)
        gpiod_line_config_free(sensor_cfg);
    if (chip)
        gpiod_chip_close(chip);
    if (log_fp)
        fclose(log_fp);
    return ret;
}

