#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_SENSORS 4
#define CSV_FILE "tracking_log.csv"
#define POLL_INTERVAL_US 100000  /* 100 ms */

static const unsigned int sensor_pins[NUM_SENSORS] = {17, 18, 27, 22};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int write_csv_header(FILE *fp)
{
    if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
        perror("fprintf (header)");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush (header)");
        return -1;
    }
    return 0;
}

static int write_csv_row(FILE *fp, const int values[NUM_SENSORS])
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d,%d\n",
                timestamp,
                values[0], values[1], values[2], values[3]) < 0) {
        perror("fprintf (row)");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush (row)");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int values[NUM_SENSORS];
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;
    int i;

    for (i = 0; i < NUM_SENSORS; i++)
        lines[i] = NULL;

    /* Install signal handlers for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip4 on Pi 5) */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Acquire each GPIO line as input */
    for (i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line failed for BCM GPIO %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ky033-tracker") < 0) {
            fprintf(stderr, "gpiod_line_request_input failed for BCM GPIO %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Open CSV file in append mode; write header if newly created */
    fp = fopen(CSV_FILE, "a+");
    if (fp == NULL) {
        perror("fopen");
        goto cleanup;
    }

    if (fseek(fp, 0, SEEK_END) != 0) {
        perror("fseek");
        goto cleanup;
    }

    long file_size = ftell(fp);
    if (file_size < 0) {
        perror("ftell");
        goto cleanup;
    }

    if (file_size == 0) {
        if (write_csv_header(fp) != 0) {
            fprintf(stderr, "Failed to write CSV header\n");
            goto cleanup;
        }
    }

    printf("KY-033 tracking started. Logging to '%s'. Press Ctrl+C to stop.\n", CSV_FILE);

    while (program_running) {
        int read_error = 0;

        for (i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value failed for BCM GPIO %u: %s\n",
                        sensor_pins[i], strerror(errno));
                read_error = 1;
                break;
            }
            values[i] = val;
        }

        if (read_error)
            continue;

        if (write_csv_row(fp, values) != 0) {
            fprintf(stderr, "Failed to write CSV row\n");
            goto cleanup;
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0)
            perror("fclose");
    }
    for (i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

