#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x49
#define SI1175_ALS_VIS_LSB 0x24
#define SI1175_ALS_VIS_MSB 0x25
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t lsb_reg, uint16_t *val) {
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, lsb_reg, &lsb) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, lsb_reg + 1, &msb) < 0) {
        return -1;
    }
    *val = ((uint16_t)msb << 8) | lsb;
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1175_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("Si1175 Heart Rate Sensor Reader\n");
    printf("Bus: %s, Address: 0x%02X\n", I2C_BUS, SI1175_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        uint16_t als_vis;
        if (i2c_read_reg16(fd, SI1175_ALS_VIS_LSB, &als_vis) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            break;
        }
        printf("ALS Visible: %u\n", als_vis);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return ret;
}

