    struct gpiod_line *left_line = NULL;
    struct gpiod_line *middle_line = NULL;
    struct gpiod_line *right_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for SIGINT (Ctrl+C) */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    /* Open the gpiochip device */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: failed to open %s: %s\n",
                CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO lines */
    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    if (left_line == NULL) {
        fprintf(stderr, "Error: failed to get line %d: %s\n",
                LEFT_PIN, strerror(errno));
        goto cleanup;
    }

    middle_line = gpiod_chip_get_line(chip, MIDDLE_PIN);
    if (middle_line == NULL) {
        fprintf(stderr, "Error: failed to get line %d: %s\n",
