        goto cleanup;
    }

    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);
    if (right_line == NULL) {
        fprintf(stderr, "Error: failed to get line %d: %s\n",
                RIGHT_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request each line as input */
    if (gpiod_line_request_input(left_line, "keywish_sensor") < 0) {
        fprintf(stderr, "Error: failed to request line %d as input: %s\n",
                LEFT_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(middle_line, "keywish_sensor") < 0) {
        fprintf(stderr, "Error: failed to request line %d as input: %s\n",
