        goto cleanup;
    }

    if (gpiod_line_request_input(right_line, "keywish_sensor") < 0) {
        fprintf(stderr, "Error: failed to request line %d as input: %s\n",
                RIGHT_PIN, strerror(errno));
        goto cleanup;
    }

