    /* Main polling loop */
    while (program_running) {
        int left_val = gpiod_line_get_value(left_line);
        int middle_val = gpiod_line_get_value(middle_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || middle_val < 0 || right_val < 0) {
            fprintf(stderr, "Error: failed to read sensor values: %s\n",
                    strerror(errno));
            break;
        }

        printf("L:%d M:%d R:%d\n", left_val, middle_val, right_val);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on every exit path */
    if (left_line != NULL)
        gpiod_line_release(left_line);
    if (middle_line != NULL)
        gpiod_line_release(middle_line);
    if (right_line != NULL)
        gpiod_line_release(right_line);
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting gracefully.\n");

    return ret;
}

