/*
 * TTP226 8-channel capacitive touch sensor reader using libgpiod (v1.x API).
 *
 * Wiring (TTP226 outputs -> BCM GPIO):
 *   TP1 -> GPIO 5
 *   TP2 -> GPIO 6
 *   TP3 -> GPIO 13
 *   TP4 -> GPIO 19
 *   TP5 -> GPIO 26
 *   TP6 -> GPIO 12
 *   TP7 -> GPIO 16
 *   TP8 -> GPIO 20
 *
 * Compile:
 *   gcc -O2 -Wall -Wextra -o ttp226 ttp226.c -lgpiod
 *
 * Run:
 *   ./ttp226
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200
#define GPIO_CHIP_NAME "gpiochip0"

static const unsigned int gpio_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
        printf("[%ld.%03lds] ", (long)ts.tv_sec, ts.tv_nsec / 1000000);
    } else {
        printf("[?] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int line_values[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Request each GPIO line as an input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", gpio_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ttp226-touch") < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n", gpio_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        print_timestamp();

        int read_error = 0;
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading GPIO %u: %s\n", gpio_pins[i], strerror(errno));
                read_error = 1;
                break;
            }
            line_values[i] = val;
        }

        if (read_error) {
            goto cleanup;
        }

        printf("CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               line_values[0], line_values[1], line_values[2], line_values[3],
               line_values[4], line_values[5], line_values[6], line_values[7]);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release all line requests and close the chip */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
}

