#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define FADE_STEPS    50
#define FADE_DELAY_US (5000000 / FADE_STEPS)  /* 100 ms per step */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Convert HSV to RGB (0-255 each). H is [0, 360], S, V [0, 1]. */
static void hsv_to_rgb(float h, float s, float v, int *r, int *g, int *b)
{
    if (s <= 0.0f) {
        *r = (int)(v * 255.0f);
        *g = (int)(v * 255.0f);
        *b = (int)(v * 255.0f);
        return;
    }

    float hh = h / 60.0f;
    int   i  = (int)hh;
    float f  = hh - (float)i;
    float p = v * (1.0f - s);
    float q = v * (1.0f - s * f);
    float t = v * (1.0f - s * (1.0f - f));

    switch (i) {
        case 0: *r = (int)(v * 255.0f); *g = (int)(t * 255.0f); *b = (int)(p * 255.0f); break;
        case 1: *r = (int)(q * 255.0f); *g = (int)(v * 255.0f); *b = (int)(p * 255.0f); break;
        case 2: *r = (int)(p * 255.0f); *g = (int)(v * 255.0f); *b = (int)(t * 255.0f); break;
        case 3: *r = (int)(p * 255.0f); *g = (int)(q * 255.0f); *b = (int)(v * 255.0f); break;
        case 4: *r = (int)(t * 255.0f); *g = (int)(p * 255.0f); *b = (int)(v * 255.0f); break;
        default: *r = (int)(v * 255.0f); *g = (int)(p * 255.0f); *b = (int)(q * 255.0f); break;
    }
}

/* Common-anode: invert duty-cycle (0 = full on, 255 = full off). */
static int set_led_color(int r, int g, int b)
{
    int inv_r = 255 - r;
    int inv_g = 255 - g;
    int inv_b = 255 - b;

    if (gpioPWM(RED_PIN,   inv_r) < 0) { syslog(LOG_ERR, "gpioPWM RED failed: %s", pigpio_error(inv_r)); return -1; }
    if (gpioPWM(GREEN_PIN, inv_g) < 0) { syslog(LOG_ERR, "gpioPWM GREEN failed: %s", pigpio_error(inv_g)); return -1; }
    if (gpioPWM(BLUE_PIN,  inv_b) < 0) { syslog(LOG_ERR, "gpioPWM BLUE failed: %s", pigpio_error(inv_b)); return -1; }
    return 0;
}

static void fade_to_color(int r, int g, int b)
{
    int cur_r, cur_g, cur_b;
    int dr, dg, db;

    if (set_led_color(r, g, b) < 0) return;

    gpioDelay(FADE_DELAY_US);

    for (int i = 0; i < FADE_STEPS && g_running; i++) {
        float t = (float)i / (float)FADE_STEPS;
        cur_r = (int)(r * t);
        cur_g = (int)(g * t);
        cur_b = (int)(b * t);

        if (set_led_color(cur_r, cur_g, cur_b) < 0) return;
        gpioDelay(FADE_DELAY_US);
    }
}

int main(void)
{
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (set_led_color(0, 0, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialise LED to off");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    while (g_running) {
        float hue = (float)(rand() % 360);
        int   r, g, b;
        hsv_to_rgb(hue, 1.0f, 1.0f, &r, &g, &b);

        if (r < 0) r = 0; if (r > 255) r = 255;
        if (g < 0) g = 0; if (g > 255) g = 255;
        if (b < 0) b = 0; if (b > 255) b = 255;

        fade_to_color(r, g, b);

        /* Sleep 5 s in 100 ms slices so signals are caught promptly. */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    set_led_color(0, 0, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

