/*
 * TCS34725 color sensor reader with GPIO threshold LED control.
 * Board:  Raspberry Pi 4 Model B
 * I2C:    /dev/i2c-1  (BCM 2 = SDA, BCM 3 = SCL), TCS34725 @ 0x29
 * GPIO:   libgpiod line 17 (BCM 17), active-high LED indicator
 *
 * Build:  gcc -O2 -Wall -Wextra -o tcs34725 tcs34725.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>

/* ---- TCS34725 register definitions ---- */
#define TCS34725_I2C_ADDR        0x29
#define TCS34725_CMD_BIT         0x80
#define TCS34725_REG_ENABLE      0x00
#define TCS34725_REG_ATIME       0x01
#define TCS34725_REG_ID          0x12
#define TCS34725_REG_CDATA       0x14
#define TCS34725_REG_RDATA       0x16
#define TCS34725_REG_GDATA       0x18
#define TCS34725_REG_BDATA       0x1A
#define TCS34725_REG_CONTROL     0x0F

#define TCS34725_ENABLE_PON      0x01
#define TCS34725_ENABLE_AEN      0x02
#define TCS34725_ID_VALUE        0x44

/* ---- Calibration (replace with your own calibrated values) ---- */
#define RED_OFFSET   0.0f
#define GREEN_OFFSET 0.0f
#define BLUE_OFFSET  0.0f
#define RED_GAIN     1.0f
#define GREEN_GAIN   1.0f
#define BLUE_GAIN    1.0f

/* ---- GPIO / I2C ---- */
#define GPIO_CHIP    "gpiochip4"   /* BCM GPIO bank on Pi 4 */
#define GPIO_OFFSET  17
#define I2C_DEV      "/dev/i2c-1"

/* ---- Application ---- */
#define RED_THRESHOLD 200
#define POLL_MS       200

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { (uint8_t)(reg | TCS34725_CMD_BIT), val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    uint8_t cmd = (uint8_t)(reg | TCS34725_CMD_BIT);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "i2c write (read-addr) reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "i2c read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t cmd = (uint8_t)(reg | TCS34725_CMD_BIT);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "i2c write (read-addr) reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c read16 reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ---- Sensor init ---- */
static int sensor_init(int fd)
{
    uint8_t id = 0;
    if (i2c_read_reg8(fd, TCS34725_REG_ID, &id) != 0) {
        fprintf(stderr, "Cannot read ID register.\n");
        return -1;
    }
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Unexpected ID 0x%02X (expected 0x%02X).\n", id, TCS34725_ID_VALUE);
        return -1;
    }

    /* Power on */
    if (i2c_write_reg8(fd, TCS34725_REG_ENABLE, TCS34725_ENABLE_PON) != 0)
        return -1;
    usleep(3000);  /* 2.4 ms min power-up; 3 ms is safe */

    /* Disable before configuration */
    if (i2c_write_reg8(fd, TCS34725_REG_ENABLE, 0x00) != 0)
        return -1;

    /* Integration time ~154 ms (ATIME = 0x00) */
    if (i2c_write_reg8(fd, TCS34725_REG_ATIME, 0x00) != 0)
        return -1;

    /* Gain 1x (CONTROL = 0x00) */
    if (i2c_write_reg8(fd, TCS34725_REG_CONTROL, 0x00) != 0)
        return -1;

    /* Enable RGBC */
    if (i2c_write_reg8(fd, TCS34725_REG_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0)
        return -1;

    usleep(3000);
    return 0;
}

/* ---- Read with retry on failure ---- */
static int sensor_read(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c)
{
    if (i2c_read_reg16_le(fd, TCS34725_REG_CDATA, c) != 0) return -1;
    if (i2c_read_reg16_le(fd, TCS34725_REG_RDATA, r) != 0) return -1;
    if (i2c_read_reg16_le(fd, TCS34725_REG_GDATA, g) != 0) return -1;
    if (i2c_read_reg16_le(fd, TCS34725_REG_BDATA, b) != 0) return -1;
    return 0;
}

/* ---- Calibration ---- */
static void calibrate(uint16_t r, uint16_t g, uint16_t b, uint16_t c,
                      float *cr, float *cg, float *cb, float *cc)
{
    *cr = (float)r * RED_GAIN   + RED_OFFSET;
    *cg = (float)g * GREEN_GAIN + GREEN_OFFSET;
    *cb = (float)b * BLUE_GAIN  + BLUE_OFFSET;
    *cc = (float)c;
}

/* ---- Cleanup ---- */
static void cleanup(int i2c_fd, struct gpiod_line *led)
{
    if (i2c_fd >= 0) {
        /* Power down */
        if (i2c_fd >= 0)
            (void)i2c_write_reg8(i2c_fd, TCS34725_REG_ENABLE, 0x00);
        close(i2c_fd);
    }
    if (led)
        gpiod_line_release(led);
}

int main(void)
{
    int i2c_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led = NULL;
    int rc = EXIT_FAILURE;

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", TCS34725_I2C_ADDR, strerror(errno));
        goto out;
    }

    /* Initialize sensor */
    if (sensor_init(i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        goto out;
    }

    /* Open GPIO chip and request LED line */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open(%s) failed: %s\n", GPIO_CHIP, strerror(errno));
        goto out;
    }

    led = gpiod_chip_get_line(chip, GPIO_OFFSET);
    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", GPIO_OFFSET, strerror(errno));
