        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        goto out;
    }

    printf("TCS34725 ready. Polling every %d ms. Press Ctrl+C to exit.\n", POLL_MS);

    while (g_running) {
        uint16_t r, g, b, c;
        float cr, cg, cb, cc;

        if (sensor_read(i2c_fd, &r, &g, &b, &c) != 0) {
            fprintf(stderr, "Read failed; re-initializing sensor...\n");
            if (sensor_init(i2c_fd) != 0) {
                fprintf(stderr, "Re-init failed; continuing to retry.\n");
            }
            usleep(POLL_MS * 1000);
            continue;
        }

        calibrate(r, g, b, c, &cr, &cg, &cb, &cc);

        printf("R=%5u G=%5u B=%5u C=%5u  |  CR=%.1f CG=%.1f CB=%.1f CC=%.1f\n",
               r, g, b, c, cr, cg, cb, cc);

