/*
 * Raspberry Pi 4 Model B
 * WS2812B 10-LED strip on GPIO18 (PCM_CLK)
 * BH1750 I2C light sensor at 0x23 (continuous high-res mode)
 * pigpio hardware PWM/waveform generation for WS2812B timing
 *
 * Build: gcc -O2 -Wall -o light_led light_led.c -lpigpio -lrt
 * Run:   sudo ./light_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define WS2812B_GPIO      18
#define NUM_LEDS          10
#define BH1750_ADDR       0x23
#define BH1750_CMD_CONT_HRES 0x10
#define BH1750_MEAS_MS    180
#define I2C_RETRIES       3
#define I2C_RETRY_DELAY_US 100000
#define LOOP_DELAY_US     50000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- WS2812B helpers ---- */

static void ws2812b_set_pixel(uint8_t r, uint8_t g, uint8_t b) {
    /* WS2812B expects GRB order */
    uint8_t rgb[3] = {g, r, b};
    for (int i = 0; i < 3; i++) {
        uint8_t bit = 0x80;
        for (int j = 0; j < 8; j++) {
            if (rgb[i] & bit) {
                gpioPWM(WS2812B_GPIO, 1);
            } else {
                gpioPWM(WS2812B_GPIO, 0);
            }
            gpioDelay(1); /* >0.4 us per bit; 1 us is safe */
            gpioPWM(WS2812B_GPIO, 0);
            bit >>= 1;
        }
    }
}

static void ws2812b_update(const uint8_t *colors, int count) {
    for (int i = 0; i < count; i++) {
        ws2812b_set_pixel(colors[i], colors[i], colors[i]);
    }
    gpioDelay(50); /* >50 us latch / reset */
}

/* ---- BH1750 helpers ---- */

static int bh1750_read_lux(int handle, float *lux_out) {
    if (i2cWriteByteData(handle, 0x00, BH1750_CMD_CONT_HRES) < 0) {
        return -1;
    }
    gpioDelay(BH1750_MEAS_MS * 1000);

    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int bh1750_init(int *handle_out) {
    int handle = i2cOpen(1, BH1750_ADDR, 0);
    if (handle < 0) {
        return -1;
    }
    *handle_out = handle;
    return 0;
}

/* ---- Application logic ---- */

static float map_light_to_brightness(float lux) {
    if (lux < 0.0f) lux = 0.0f;
    if (lux > 1000.0f) lux = 1000.0f;

    /* Logarithmic mapping: 0 lux -> 0 brightness, 1000 lux -> 100 brightness */
    float b = 100.0f * log10f(1.0f + lux);
    if (b < 0.0f) b = 0.0f;
    if (b > 100.0f) b = 100.0f;
    return b;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int bh1750_handle = -1;
    if (bh1750_init(&bh1750_handle) != 0) {
        fprintf(stderr, "BH1750 init failed (sensor absent or bus error)\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t leds[NUM_LEDS];
    for (int i = 0; i < NUM_LEDS; i++) {
        leds[i] = 0;
    }

    while (g_running) {
        float lux = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < I2C_RETRIES && g_running; attempt++) {
            if (bh1750_read_lux(bh1750_handle, &lux) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "BH1750 read attempt %d/%d failed\n", attempt + 1, I2C_RETRIES);
            gpioDelay(I2C_RETRY_DELAY_US);
        }

        if (!ok) {
            fprintf(stderr, "BH1750 unreachable after %d retries; keeping last value or 0\n", I2C_RETRIES);
        }

        float brightness = map_light_to_brightness(lux);
        uint8_t val = (uint8_t)(brightness / 100.0f * 255.0f);
        for (int i = 0; i < NUM_LEDS; i++) {
            leds[i] = val;
        }

        ws2812b_update(leds, NUM_LEDS);
        gpioDelay(LOOP_DELAY_US);
    }

    /* Cleanup */
    for (int i = 0; i < NUM_LEDS; i++) {
        leds[i] = 0;
    }
    ws2812b_update(leds, NUM_LEDS);

    if (bh1750_handle >= 0) {
        i2cClose(bh1750_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

