#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define I2C_DEVICE "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define BH1750_ONE_TIME_HIGH_RES 0x20
#define BH1750_CONV_TIME_MS 120
#define LUX_MIN 10.0f
#define LUX_MAX 300.0f
#define BRIGHTNESS_MIN 0
#define BRIGHTNESS_MAX 31
#define NUM_LEDS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        return -1;
    }
    if (i2c_write_byte(fd, BH1750_ONE_TIME_HIGH_RES) < 0) {
        fprintf(stderr, "Failed to send BH1750 power-on command\n");
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
