#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CMD_OT_H_RES_2 0x21
#define BH1750_CONV_TIME_MS 180
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define NUM_SENSORS 3
#define BRIGHTNESS_MAX 31
#define FADE_DURATION_MS 500
#define LOOP_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_handles[NUM_SENSORS];
static int spi_handle = -1;
static int num_sensors = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_bh1750(int handle) {
    if (i2cWriteByte(handle, BH1750_CMD_OT_H_RES_2) < 0) {
        fprintf(stderr, "Error: failed to write BH1750 command to handle %d\n", handle);
        return -1;
    }
    return 0;
}

static int read_bh1750(int handle, float *lux) {
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error: I2C read returned %d bytes from handle %d\n", bytes, handle);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    int handles[NUM_SENSORS] = {BH1750_ADDR_LOW, BH1750_ADDR_HIGH, 0};
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, handles[i], 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Warning: i2cOpen failed for addr 0x%02X: %d\n", handles[i], i2c_handles[i]);
            i2c_handles[i] = -1;
        } else {
            if (init_bh1750(i2c_handles[i]) == 0) {
                num_sensors++;
            } else {
                i2cClose(i2c_handles[i]);
                i2c_handles[i] = -1;
            }
        }
    }
    return 0;
}

static int init_all(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (init_i2c() != 0) {
        gpioTerminate();
        return -1;
    }
    if (init_spi() != 0) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) i2cClose(i2c_handles[i]);
        }
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        char off[4] = {0x00, 0x00, 0x00, 0x00};
        spiWrite(spi_handle, off, 4);
        spiClose(spi_handle);
        spi_handle = -1;
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }
    gpioTerminate();
}

static int map_lux_to_brightness(float lux) {
    if (lux < 0.0f) lux = 0.0f;
    if (lux > 10000.0f) lux = 10000.0f;
    return (int)(BRIGHTNESS_MAX * (1.0f - lux / 10000.0f));
}

static int set_apa102_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > BRIGHTNESS_MAX) brightness = BRIGHTNESS_MAX;
    char frame[4 + 4 * (BRIGHTNESS_MAX + 1)];
    frame[0] = 0x00;
    frame[1] = 0x00;
    frame[2] = 0x00;
    frame[3] = (char)(0xE0 | (brightness & 0x1F));
    for (int i = 0; i < brightness; i++) {
        frame[4 + 4 * i] = 0xFF;
        frame[4 + 4 * i + 1] = 0x00;
        frame[4 + 4 * i + 2] = 0x00;
        frame[4 + 4 * i + 3] = 0xFF;
    }
    for (int i = brightness; i < BRIGHTNESS_MAX; i++) {
        frame[4 + 4 * i] = 0x00;
        frame[4 + 4 * i + 1] = 0x00;
        frame[4 + 4 * i + 2] = 0x00;
        frame[4 + 4 * i + 3] = 0x00;
    }
    if (spiWrite(spi_handle, frame, sizeof(frame)) != (int)sizeof(frame)) {
        fprintf(stderr, "Error: SPI write failed\n");
        return -1;
    }
    return 0;
}

static int fade_brightness(int target, int duration_ms) {
    int steps = duration_ms / 10;
    if (steps == 0) steps = 1;
    int step_delay = duration_ms / steps;
    for (int i = 0; i <= steps; i++) {
        if (!running) return -1;
        int current = (target * i) / steps;
        if (set_apa102_brightness(current) != 0) return -1;
        gpioDelay(step_delay * 1000);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_all() != 0) {
        return EXIT_FAILURE;
    }

    int current_brightness = 0;
    int target_brightness = 0;

    while (running) {
        float lux_sum = 0.0f;
        int valid = 0;

        for (int i = 0; i < num_sensors; i++) {
            if (i2c_handles[i] < 0) continue;
            if (init_bh1750(i2c_handles[i]) != 0) continue;
            gpioDelay(BH1750_CONV_TIME_MS * 1000);
            float lux;
            if (read_bh1750(i2c_handles[i], &lux) == 0) {
                lux_sum += lux;
                valid++;
            }
        }

        if (valid > 0) {
            float avg_lux = lux_sum / valid;
            target_brightness = map_lux_to_brightness(avg_lux);
        } else {
            target_brightness = 0;
        }

        if (target_brightness != current_brightness) {
            if (fade_brightness(target_brightness, FADE_DURATION_MS) == 0) {
                current_brightness = target_brightness;
            }
        }

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

