    sigaction(SIGTERM, &sa, NULL);

    if (init_all() != 0) {
        return EXIT_FAILURE;
    }

    int current_brightness = 0;
    int target_brightness = 0;

    while (running) {
        float lux_sum = 0.0f;
        int valid = 0;

        for (int i = 0; i < num_sensors; i++) {
            if (i2c_handles[i] < 0) continue;
            if (init_bh1750(i2c_handles[i]) != 0) continue;
            gpioDelay(BH1750_CONV_TIME_MS * 1000);
            float lux;
            if (read_bh1750(i2c_handles[i], &lux) == 0) {
                lux_sum += lux;
                valid++;
            }
        }

        if (valid > 0) {
            float avg_lux = lux_sum / valid;
            target_brightness = map_lux_to_brightness(avg_lux);
        } else {
            target_brightness = 0;
        }

        if (target_brightness != current_brightness) {
            if (fade_brightness(target_brightness, FADE_DURATION_MS) == 0) {
                current_brightness = target_brightness;
            }
        }

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

