#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <math.h>

#define I2C_DEVICE "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_DATA_REG 0x04
#define WS2812B_GPIO_PIN 18
#define NUM_LEDS 10
#define MAX_LUX 120000.0
#define MAX_BRIGHTNESS 255
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int init_veml7700(int fd) {
    if (i2c_write_reg16(fd, VEML7700_CONFIG_REG, 0x0000) < 0) {
        fprintf(stderr, "Error writing VEML7700 config: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);
    return 0;
}

int read_lux(int fd, float *lux) {
    uint16_t raw;
    if (i2c_read_reg16(fd, VEML7700_ALS_DATA_REG, &raw) < 0) {
        fprintf(stderr, "Error reading VEML7700 ALS data: %s\n", strerror(errno));
        return -1;
    }
    *lux = (float)raw * 0.0288f;
    return 0;
}

void set_led_brightness(struct gpiod_line *line, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;
    uint8_t grb[NUM_LEDS * 3];
    for (int i = 0; i < NUM_LEDS * 3; i++) {
        grb[i] = (uint8_t)brightness;
    }
    for (int i = 0; i < NUM_LEDS * 24; i++) {
        int bit = (grb[i / 24] >> (23 - i % 24)) & 1;
        if (gpiod_line_set_value(line, bit) < 0) {
            fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
            return;
        }
        usleep(1);
    }
}

void cleanup() {
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (init_veml7700(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing VEML7700\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    line = gpiod_chip_get_line(chip, WS2812B_GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", WS2812B_GPIO_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(line, "ws2812b", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        float lux = 0.0f;
        int retries = 0;
        int success = 0;
        while (retries < I2C_RETRY_COUNT && !success) {
            if (read_lux(i2c_fd, &lux) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < I2C_RETRY_COUNT) {
                    fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", retries, I2C_RETRY_COUNT);
                    usleep(I2C_RETRY_DELAY_MS * 1000);
                }
            }
        }

        if (!success) {
            fprintf(stderr, "I2C read failed after %d retries, continuing with last known lux\n", I2C_RETRY_COUNT);
        }

        float brightness = MAX_BRIGHTNESS * powf(lux / MAX_LUX, 1.0f / 2.2f);
        if (brightness < 0) brightness = 0;
        if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;

        set_led_brightness(line, (int)brightness);
        printf("Lux: %.2f, Brightness: %.2f\n", lux, brightness);

        usleep(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

