#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18
#define CONSUMER "flame_detector"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t running = 1;

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static void cleanup(void) {
    if (flame_line) gpiod_line_release(flame_line);
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open gpiochip4");
        return -1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);

    if (!flame_line || !buzzer_line || !led_line) {
        perror("Failed to get GPIO lines");
        return -1;
    }

    if (gpiod_line_request_input(flame_line, CONSUMER) < 0) {
        perror("Failed to request flame sensor line as input");
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, CONSUMER, 0) < 0) {
        perror("Failed to request buzzer line as output");
        return -1;
    }

    if (gpiod_line_request_output(led_line, CONSUMER, 0) < 0) {
        perror("Failed to request LED line as output");
        return -1;
    }

    return 0;
}

static void self_test(void) {
    log_event("Starting self-test...");

    // Blink LED twice
    for (int i = 0; i < 2; i++) {
        if (!running) return;
        gpiod_line_set_value(led_line, 1);
        usleep(500000);
        gpiod_line_set_value(led_line, 0);
        usleep(500000);
    }

    // Read sensor 5 times
    int flame_count = 0;
    for (int i = 0; i < 5; i++) {
        if (!running) return;
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            log_event("Error reading flame sensor during self-test");
            return;
        }
        if (val == 0) {
            flame_count++;
        }
        usleep(100000);
    }

    if (flame_count == 5) {
        log_event("Self-test failed: Sensor fault detected");
        // Blink rapidly
        while (running) {
            gpiod_line_set_value(led_line, 1);
            gpiod_line_set_value(buzzer_line, 1);
            usleep(100000);
            gpiod_line_set_value(led_line, 0);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(100000);
        }
        cleanup();
        exit(1);
    } else {
        log_event("Self-test passed");
    }
}

static void handle_flame(void) {
    log_event("Flame detected!");
    gpiod_line_set_value(buzzer_line, 1);
    gpiod_line_set_value(led_line, 1);

    while (running) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            log_event("Error reading flame sensor");
            break;
        }
        if (val == 1) {
            break;
        }
        usleep(50000);
    }

    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_set_value(led_line, 0);
    log_event("Flame gone");
}

int main(void) {
    signal(SIGINT, signal_handler);

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    self_test();

    log_event("Entering main loop");
    while (running) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            log_event("Error reading flame sensor");
            usleep(100000);
            continue;
        }
        if (val == 0) {
            handle_flame();
        }
        usleep(50000);
    }

    log_event("Exiting");
    cleanup();
    return 0;
}

