#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define LED_PIN 17
#define BUTTON_PIN 18
#define BLINK_PERIOD_MS 2000
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    struct gpiod_line_event event;
    int ret;

    // Set up signal handler for graceful exit
    signal(SIGINT, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request LED line as output, initially low
    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get button line
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Failed to get button line %d: %s\n", BUTTON_PIN, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request button line as input with pull-up, falling edge events
    ret = gpiod_line_request_falling_edge_events_flags(button_line, "blink_button", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to request button line events: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Blinking LED on GPIO%d with button on GPIO%d. Press Ctrl+C to exit.\n", LED_PIN, BUTTON_PIN);

    // Main loop
    while (keep_running) {
        // Blink LED
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set LED high: %s\n", strerror(errno));
            break;
        }
        usleep(BLINK_PERIOD_MS * 1000);

        if (!keep_running) break;

        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set LED low: %s\n", strerror(errno));
            break;
        }
        usleep(BLINK_PERIOD_MS * 1000);

        // Check for button press (non-blocking with timeout)
        ret = gpiod_line_event_wait(button_line, &(struct timespec){0, POLL_TIMEOUT_MS * 1000000});
        if (ret < 0) {
            fprintf(stderr, "Error waiting for button event: %s\n", strerror(errno));
            break;
        } else if (ret > 0) {
            // Event detected, read it
            ret = gpiod_line_event_read(button_line, &event);
            if (ret < 0) {
                fprintf(stderr, "Error reading button event: %s\n", strerror(errno));
                break;
            }
            printf("Button pressed! Stopping blinking.\n");
            gpiod_line_set_value(led_line, 0);
            break;
        }
    }

    // Cleanup
    if (led_line) gpiod_line_release(led_line);
    if (button_line) gpiod_line_release(button_line);
    if (chip) gpiod_chip_close(chip);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

