#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

#define PWM_PERIOD_NS 10000000  /* 10 ms = 100 Hz */
#define STEP_NS       1000000   /* 1 ms per step for 1% resolution */
#define MAX_DUTY      100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ns(long ns) {
    struct timespec ts;
    ts.tv_sec  = ns / 1000000000L;
    ts.tv_nsec = ns % 1000000000L;
    clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
}

static void set_pwm(struct gpiod_line *line, int duty) {
    if (duty <= 0) {
        gpiod_line_set_value(line, 0);
        return;
    }
    if (duty >= MAX_DUTY) {
        gpiod_line_set_value(line, 1);
        return;
    }
    long on_ns  = (PWM_PERIOD_NS * duty) / MAX_DUTY;
    long off_ns = PWM_PERIOD_NS - on_ns;
    gpiod_line_set_value(line, 1);
    sleep_ns(on_ns);
    gpiod_line_set_value(line, 0);
    sleep_ns(off_ns);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip 0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    red_line   = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line  = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(red_line,   "rgb_led", 0) < 0 ||
        gpiod_line_request_output(green_line, "rgb_led", 0) < 0 ||
        gpiod_line_request_output(blue_line,  "rgb_led", 0) < 0) {
        fprintf(stderr, "Failed to request output lines: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        int r = rand() % MAX_DUTY;
        int g = rand() % MAX_DUTY;
        int b = rand() % MAX_DUTY;

        set_pwm(red_line,   r);
        set_pwm(green_line, g);
        set_pwm(blue_line,  b);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (red_line)   gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line)  gpiod_line_release(blue_line);
    if (chip)       gpiod_chip_close(chip);
    return ret;
}

