#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define LED_GPIO 18
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

#define REG_MODE 0x0D
#define REG_ALS_LSB 0x64
#define REG_ALS_MSB 0x65
#define REG_RED_LSB 0x66
#define REG_RED_MSB 0x67
#define REG_GREEN_LSB 0x68
#define REG_GREEN_MSB 0x69
#define REG_BLUE_LSB 0x6A
#define REG_BLUE_MSB 0x6B

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    int rc = i2cWriteByteData(i2c_handle, REG_MODE, 0x01);
    if (rc < 0) {
        fprintf(stderr, "Error writing MODE register: %d\n", rc);
        return -1;
    }
    return 0;
}

static int read_als(uint16_t *als) {
    int lsb = i2cReadByteData(i2c_handle, REG_ALS_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading ALS LSB: %d\n", lsb);
        return -1;
    }
    int msb = i2cReadByteData(i2c_handle, REG_ALS_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading ALS MSB: %d\n", msb);
        return -1;
    }
    *als = (uint16_t)((msb << 8) | lsb);
    return 0;
}

static int read_color(uint16_t *r, uint16_t *g, uint16_t *b) {
    int rl = i2cReadByteData(i2c_handle, REG_RED_LSB);
    if (rl < 0) {
        fprintf(stderr, "Error reading Red LSB: %d\n", rl);
        return -1;
    }
    int rh = i2cReadByteData(i2c_handle, REG_RED_MSB);
    if (rh < 0) {
        fprintf(stderr, "Error reading Red MSB: %d\n", rh);
        return -1;
    }
    *r = (uint16_t)((rh << 8) | rl);

    int gl = i2cReadByteData(i2c_handle, REG_GREEN_LSB);
    if (gl < 0) {
        fprintf(stderr, "Error reading Green LSB: %d\n", gl);
        return -1;
    }
    int gh = i2cReadByteData(i2c_handle, REG_GREEN_MSB);
    if (gh < 0) {
        fprintf(stderr, "Error reading Green MSB: %d\n", gh);
        return -1;
    }
    *g = (uint16_t)((gh << 8) | gl);

    int bl = i2cReadByteData(i2c_handle, REG_BLUE_LSB);
    if (bl < 0) {
        fprintf(stderr, "Error reading Blue LSB: %d\n", bl);
        return -1;
    }
    int bh = i2cReadByteData(i2c_handle, REG_BLUE_MSB);
    if (bh < 0) {
        fprintf(stderr, "Error reading Blue MSB: %d\n", bh);
        return -1;
    }
    *b = (uint16_t)((bh << 8) | bl);
    return 0;
}

static void log_data(uint16_t als, uint16_t r, uint16_t g, uint16_t b) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, r, g, b);
    fflush(log_file);
}

static void control_led(uint16_t als) {
    int pwm_value = (int)((als * PWM_RANGE) / 65535);
    if (pwm_value > PWM_RANGE) pwm_value = PWM_RANGE;
    if (pwm_value < 0) pwm_value = 0;
    gpioPWM(LED_GPIO, pwm_value);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("color_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t als, r, g, b;

    while (!terminate) {
        if (read_als(&als) == 0 && read_color(&r, &g, &b) == 0) {
            log_data(als, r, g, b);
            control_led(als);
        } else {
            fprintf(stderr, "Read error, retrying in %d ms\n", RETRY_DELAY_US / 1000);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

