#define FXOS8700_REGISTER_WHO_AM_I     0x0D
#define FXOS8700_REGISTER_XYZ_DATA_CFG 0x0E
#define FXOS8700_REGISTER_CTRL_REG1    0x2A

/* Expected WHO_AM_I value for FXOS8700CQ */
#define FXOS8700_WHO_AM_I_EXPECTED     0xC7

/* ±2g range: 4096 counts/g */
#define FXOS8700_SENSITIVITY_2G        4096.0f

/* Impact threshold: 2 g in m/s^2 */
#define IMPACT_THRESHOLD_M_S2          19.62f

/* Sample period in microseconds (50 ms) */
#define SAMPLE_PERIOD_US              50000

/* Log file path */
#define LOG_FILE_PATH                 "impact_log.txt"

/* Global I2C handle for signal handler access */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int signal)
{
    (void)signal;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an FXOS8700CQ register                            */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int fxos_write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an FXOS8700CQ register                           */
/* Returns the byte value (0–255) on success, -1 on failure.           */
/* ------------------------------------------------------------------ */
static int fxos_read_register(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration (14-bit left-justified)                */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int fxos_read_acceleration(int handle,
                                  int16_t *x, int16_t *y, int16_t *z)
{
    char buffer[6];

    /* Set the register pointer to OUT_X_MSB (0x01) */
    int rc = i2cWriteByte(handle, FXOS8700_REGISTER_OUT_X_MSB);
    if (rc < 0) {
        fprintf(stderr, "Error setting register pointer (rc=%d)\n", rc);
        return -1;
    }

    /* Read 6 bytes: X_MSB, X_LSB, Y_MSB, Y_LSB, Z_MSB, Z_LSB */
    rc = i2cReadDevice(handle, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading acceleration data (rc=%d)\n", rc);
        return -1;
    }

    /* Combine high and low bytes; shift right by 2 to get 14-bit value */
    *x = (int16_t)(((uint16_t)(uint8_t)buffer[0] << 8) | (uint8_t)buffer[1]) >> 2;
    *y = (int16_t)(((uint16_t)(uint8_t)buffer[2] << 8) | (uint8_t)buffer[3]) >> 2;
    *z = (int16_t)(((uint16_t)(uint8_t)buffer[4] << 8) | (uint8_t)buffer[5]) >> 2;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw 14-bit acceleration to m/s^2                            */
/* ------------------------------------------------------------------ */
static float convert_to_mps2(int16_t raw_x, int16_t raw_y, int16_t raw_z)
{
    float x_g = (float)raw_x / FXOS8700_SENSITIVITY_2G;
    float y_g = (float)raw_y / FXOS8700_SENSITIVITY_2G;
    float z_g = (float)raw_z / FXOS8700_SENSITIVITY_2G;
    return sqrtf(x_g * x_g + y_g * y_g + z_g * z_g) * 9.81f;
}

