#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define GYRO_ADDR        0x69
#define I2C_BUS          "/dev/i2c-1"
#define WHO_AM_I         0x0F
#define WHO_AM_I_VAL     0xD3
#define CTRL_REG1        0x20
#define CTRL_REG4        0x23
#define OUT_X_L          0x28
#define NUM_CAL_SAMPLES  100
#define CAL_THRESHOLD    50.0f
#define SENSITIVITY      0.00875f
#define LOG_FILE         "gyro_log.txt"
#define SAMPLE_PERIOD_US 50000

static volatile sig_atomic_t running = 1;
static int g_fd = -1;
static FILE *g_log = NULL;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int gyro_init(int fd) {
    uint8_t who;
    if (i2c_read_block(fd, WHO_AM_I, &who, 1) < 0) return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, CTRL_REG1, 0x0F) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG4, 0x00) < 0) return -1;
    return 0;
}

static int gyro_read(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L | 0x80, buf, 6) < 0) return -1;
    int16_t rx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t ry = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t rz = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)rx * SENSITIVITY;
    *y = (float)ry * SENSITIVITY;
    *z = (float)rz * SENSITIVITY;
    return 0;
}

static int calibrate_gyro(int fd, float *ox, float *oy, float *oz) {
    float sx = 0, sy = 0, sz = 0;
    int ok = 0;
    for (int i = 0; i < NUM_CAL_SAMPLES; i++) {
        float x, y, z;
        if (gyro_read(fd, &x, &y, &z) < 0) return -1;
        sx += x; sy += y; sz += z;
        usleep(1000);
    }
    *ox = sx / NUM_CAL_SAMPLES;
    *oy = sy / NUM_CAL_SAMPLES;
    *oz = sz / NUM_CAL_SAMPLES;
    printf("Calibration complete: X=%.3f Y=%.3f Z=%.3f dps\n", *ox, *oy, *oz);
    return 0;
}

static void log_data(FILE *f, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(f, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(f);
}

static void log_alert(FILE *f, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(f, "%s,ALERT,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fprintf(stderr, "ALERT: X=%.3f Y=%.3f Z=%.3f dps\n", x, y, z);
    fflush(f);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", GYRO_ADDR, strerror(errno));
        close(g_fd);
        return 1;
    }

    if (gyro_init(g_fd) < 0) {
        fprintf(stderr, "Gyro init failed\n");
        close(g_fd);
        return 1;
    }

    float ox, oy, oz;
    if (calibrate_gyro(g_fd, &ox, &oy, &oz) < 0) {
        fprintf(stderr, "Calibration failed\n");
        close(g_fd);
        return 1;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_fd);
        return 1;
    }

    printf("Logging to %s at 20 Hz. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        float x, y, z;
        if (gyro_read(g_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, continuing\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        x -= ox; y -= oy; z -= oz;
        log_data(g_log, x, y, z);
        if (fabsf(x) > CAL_THRESHOLD || fabsf(y) > CAL_THRESHOLD || fabsf(z) > CAL_THRESHOLD) {
            log_alert(g_log, x, y, z);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log) fclose(g_log);
    if (g_fd >= 0) close(g_fd);
    return 0;
}

