#define ACCEL_THRESHOLD 2.0
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int adxl345_init(int handle) {
    int devid = i2cReadByteData(handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error reading DEVID register: %d\n", devid);
        return -1;
    }
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0x%02X)\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    if (i2cWriteByteData(handle, ADXL345_DATA_FORMAT, 0x00) < 0) {
        fprintf(stderr, "Error writing DATA_FORMAT\n");
        return -1;
    }
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing POWER_CTL\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    int bytes = i2cReadI2CBlockData(handle, ADXL345_DATAX0, buffer, 6);
    if (bytes != 6) {
        fprintf(stderr, "Error reading acceleration data: %d\n", bytes);
        return -1;
    }

    raw_x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

    *x = (float)raw_x * 0.0039f;
    *y = (float)raw_y * 0.0039f;
    *z = (float)raw_z * 0.0039f;
    return 0;
