    int on = (fabsf(x) > ACCEL_THRESHOLD ||
              fabsf(y) > ACCEL_THRESHOLD ||
              fabsf(z) > ACCEL_THRESHOLD);
    gpioWrite(LED_GPIO, on);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
