        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init(i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

