#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM303DLHC I2C addresses */
#define ACCEL_ADDR 0x19
#define MAG_ADDR   0x1E

/* LSM303DLHC register addresses */
#define CTRL_REG1_A 0x20
#define OUT_X_L_A   0x28
#define MR_REG_M    0x02
#define OUT_X_H_M   0x03

/* Scaling factors */
#define ACCEL_SCALE 0.000244f  /* 1 mg/LSB -> g */
#define MAG_SCALE   0.00014f   /* 1 mG/LSB -> gauss */

static int accel_handle = -1;
static int mag_handle   = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_accelerometer(void) {
    if (i2cWriteByteData(accel_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to accelerometer (CTRL_REG1_A)\n");
        return -1;
    }
    return 0;
}

static int init_magnetometer(void) {
    if (i2cWriteByteData(mag_handle, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to magnetometer (MR_REG_M)\n");
        return -1;
    }
    return 0;
}

static int read_accelerometer(float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(accel_handle, OUT_X_L_A | 0x80, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;
    return 0;
}

static int read_magnetometer(float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(mag_handle, OUT_X_H_M, buf, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_z = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_y = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)raw_x * MAG_SCALE;
    *y = (float)raw_y * MAG_SCALE;
    *z = (float)raw_z * MAG_SCALE;
    return 0;
}

static float calculate_heading(float mx, float my) {
    float heading = atan2f(my, mx) * 180.0f / (float)M_PI;
    if (heading < 0) heading += 360.0f;
    return heading;
}

static void log_data(float heading, float ax, float ay, float az,
                     float mx, float my, float mz) {
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            heading, ax, ay, az, mx, my, mz);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    accel_handle = i2cOpen(1, ACCEL_ADDR, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Error opening accelerometer I2C device\n");
        gpioTerminate();
        return 1;
    }

    mag_handle = i2cOpen(1, MAG_ADDR, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Error opening magnetometer I2C device\n");
        i2cClose(accel_handle);
        gpioTerminate();
        return 1;
    }

    if (init_accelerometer() < 0 || init_magnetometer() < 0) {
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    FILE *fp = fopen("compass_log.txt", "r");
    if (!fp) {
        fp = fopen("compass_log.txt", "w");
        if (fp) {
            fprintf(fp, "timestamp,heading,ax,ay,az,mx,my,mz\n");
            fclose(fp);
        }
    } else {
        fclose(fp);
    }

    while (running) {
        float ax, ay, az, mx, my, mz;
        if (read_accelerometer(&ax, &ay, &az) == 0 &&
            read_magnetometer(&mx, &my, &mz) == 0) {
            float heading = calculate_heading(mx, my);
            log_data(heading, ax, ay, az, mx, my, mz);
        }
        gpioDelay(100000);
    }

    i2cClose(accel_handle);
    i2cClose(mag_handle);
    gpioTerminate();
    return 0;
}

