    sigaction(SIGTERM, &sa, NULL);

    FILE *fp = fopen("compass_log.txt", "r");
    if (!fp) {
        fp = fopen("compass_log.txt", "w");
        if (fp) {
            fprintf(fp, "timestamp,heading,ax,ay,az,mx,my,mz\n");
            fclose(fp);
        }
    } else {
        fclose(fp);
    }

    while (running) {
        float ax, ay, az, mx, my, mz;
        if (read_accelerometer(&ax, &ay, &az) == 0 &&
            read_magnetometer(&mx, &my, &mz) == 0) {
            float heading = calculate_heading(mx, my);
            log_data(heading, ax, ay, az, mx, my, mz);
        }
        gpioDelay(100000);
    }

    i2cClose(accel_handle);
    i2cClose(mag_handle);
    gpioTerminate();
    return 0;
}

