static int vl6180x_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    return i2cWriteDevice(i2c_handle, buf, 2);
}

static int vl6180x_read_reg(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) return -1;
    char data[1];
    if (i2cReadDevice(i2c_handle, data, 1) != 1) return -1;
    *value = (uint8_t)data[0];
