#define VL6180X_ADDR 0x29
#define I2C_BUS 1
#define DISTANCE_THRESHOLD 100
#define LOG_FILE "distance_log.txt"
#define SAMPLE_DELAY_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int vl6180x_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    return i2cWriteDevice(i2c_handle, buf, 2);
}

static int vl6180x_read_reg(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) return -1;
    char data[1];
    if (i2cReadDevice(i2c_handle, data, 1) != 1) return -1;
    *value = (uint8_t)data[0];
    return 0;
}

static int vl6180x_init(void) {
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    i2c_handle = i2cOpen(I2C_BUS, VL6180X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", VL6180X_ADDR, i2c_handle);
        return -1;
    }

    uint8_t id;
    if (vl6180x_read_reg(0x016, &id) != 0) {
        fprintf(stderr, "Error reading device ID register\n");
        return -1;
    }
