#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG 0x01
#define CTRL_REG 0x00
#define CTRL_VALUE 0x80
#define SAMPLING_INTERVAL_US 10000
#define LOG_FILE "audio_log.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_sensor(int handle, int addr) {
    if (handle < 0) {
        fprintf(stderr, "Invalid I2C handle for address 0x%02X\n", addr);
        return -1;
    }
    if (i2cWriteByteData(handle, CTRL_REG, CTRL_VALUE) < 0) {
        fprintf(stderr, "Failed to write control register for sensor at 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, int16_t *data) {
    if (handle < 0) {
        fprintf(stderr, "Invalid I2C handle\n");
        return -1;
    }
    int raw = i2cReadWordData(handle, DATA_REG);
    if (raw < 0) {
        fprintf(stderr, "Failed to read data register: %s\n", strerror(errno));
        return -1;
    }
    *data = (int16_t)raw;
    return 0;
}

static void log_data(FILE *fp, struct timespec ts, int16_t s1, int16_t s2, int16_t tdoa) {
    if (fp == NULL) return;
    fprintf(fp, "%ld,%ld,%d,%d,%d\n", (long)ts.tv_sec, (long)ts.tv_nsec, s1, s2, tdoa);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle1 = i2cOpen(1, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1 at 0x%02X: %s\n", SENSOR1_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle2 = i2cOpen(1, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2 at 0x%02X: %s\n", SENSOR2_ADDR, strerror(errno));
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(i2c_handle1, SENSOR1_ADDR) < 0 || init_sensor(i2c_handle2, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp_sec,timestamp_nsec,sensor1,sensor2,tdoa\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Bat echolocation simulation started. Press Ctrl+C to stop.\n");

    while (running) {
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            gpioDelay(SAMPLING_INTERVAL_US);
            continue;
        }

        int16_t s1 = 0, s2 = 0;
        int16_t tdoa = 0;
        int err1 = read_sensor_data(i2c_handle1, &s1);
        int err2 = read_sensor_data(i2c_handle2, &s2);

        if (err1 < 0 || err2 < 0) {
            fprintf(stderr, "Sensor read error, skipping sample\n");
            gpioDelay(SAMPLING_INTERVAL_US);
            continue;
        }

        tdoa = s1 - s2;
        log_data(log_file, ts, s1, s2, tdoa);
        gpioDelay(SAMPLING_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

