#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16488A register addresses (16-bit, MSB=0) */
#define ADIS16488A_REG_XGYRO  0x04
#define ADIS16488A_REG_YGYRO  0x06
#define ADIS16488A_REG_ZGYRO  0x08
#define ADIS16488A_REG_XACCEL 0x0A
#define ADIS16488A_REG_YACCEL 0x0C
#define ADIS16488A_REG_ZACCEL 0x0E

/* Sensitivities (from datasheet) */
#define GYRO_SENSITIVITY  0.005f   /* deg/sec per LSB  */
#define ACCEL_SENSITIVITY 0.00025f /* g per LSB       */

/* SPI parameters */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000      /* 1 MHz             */
#define SPI_FLAGS   0b11000000000 /* mode 3: CPHA=1, CPOL=1, aux SPI off */

/* Sampling interval */
#define SAMPLE_PERIOD_US 100000  /* 100 ms            */

/* Stall between request and data transfer (datasheet: ~40 us) */
#define STALL_US 40

/* Globals for cleanup() */
static int  spi_handle = -1;
static FILE *fp        = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — close SPI, close CSV, terminate pigpio                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from ADIS16488A                              */
/* Returns 0 on success, -1 on SPI error.                              */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2], rx[2];
    int  ret;

    /* Request: MSB=0, 7-bit address, padded to 16 bits */
    tx[0] = (char)(reg & 0x7F);
    tx[1] = 0x00;

    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI request failed for reg 0x%02X (spiXfer returned %d)\n",
                reg, ret);
        return -1;
    }

    /* Stall between request and data transfer */
    gpioDelay(STALL_US);

    /* Data transfer: send dummy request, capture response */
    tx[0] = 0x00;
    tx[1] = 0x00;
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI data transfer failed for reg 0x%02X (spiXfer returned %d)\n",
                reg, ret);
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a signed 16-bit value with a given sensitivity                 */
/* ------------------------------------------------------------------ */
static int read_sensor(uint8_t reg, float sensitivity, float *out)
{
    int16_t raw;
    if (read_register(reg, &raw) != 0)
        return -1;
    *out = (float)raw * sensitivity;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Non-blocking sleep that checks the running flag every 10 ms        */
/* ------------------------------------------------------------------ */
static void sleep_running(unsigned int us)
{
    unsigned int remaining = us;
    while (remaining > 0 && running) {
        unsigned int chunk = (remaining > 10000) ? 10000 : remaining;
        gpioDelay(chunk);
        remaining -= chunk;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz, flags 0x%08X): %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV file */
    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv for writing\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    fflush(fp);

    /* Register cleanup with atexit so we close everything on every exit path */
    if (atexit(cleanup) != 0) {
        fprintf(stderr, "Warning: could not register atexit cleanup\n");
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16488A logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (running) {
        float gx, gy, gz, ax, ay, az;
        struct timespec ts;
        char tbuf[32];

        /* Read sensors */
        if (read_sensor(ADIS16488A_REG_XGYRO,  GYRO_SENSITIVITY,  &gx) != 0 ||
            read_sensor(ADIS16488A_REG_YGYRO,  GYRO_SENSITIVITY,  &gy) != 0 ||
            read_sensor(ADIS16488A_REG_ZGYRO,  GYRO_SENSITIVITY,  &gz) != 0 ||
            read_sensor(ADIS16488A_REG_XACCEL, ACCEL_SENSITIVITY, &ax) != 0 ||
            read_sensor(ADIS16488A_REG_YACCEL, ACCEL_SENSITIVITY, &ay) != 0 ||
            read_sensor(ADIS16488A_REG_ZACCEL, ACCEL_SENSITIVITY, &az) != 0) {
            fprintf(stderr, "Sensor read error — skipping sample\n");
            sleep_running(SAMPLE_PERIOD_US);
            continue;
        }

        /* Timestamp with millisecond precision */
        clock_gettime(CLOCK_REALTIME, &ts);
        snprintf(tbuf, sizeof(tbuf), "%ld.%03ld",
                 (long)ts.tv_sec, ts.tv_nsec / 1000000);

        /* Log to CSV */
        fprintf(fp, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                tbuf, gx, gy, gz, ax, ay, az);
        fflush(fp);

        /* Non-blocking sleep */
        sleep_running(SAMPLE_PERIOD_US);
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

