    while (running) {
        float gx, gy, gz, ax, ay, az;
        if (read_imu(spi_fd, cs, &gx, &gy, &gz, &ax, &ay, &az) < 0) {
            fprintf(stderr, "IMU read error, continuing...\n");
        } else {
            printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f dps | Accel: X=%.4f, Y=%.4f, Z=%.4f g\n",
