#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

/* ADIS16448 Register Addresses */
#define X_GYRO_OUT  0x04
#define Y_GYRO_OUT  0x06
#define Z_GYRO_OUT  0x08
#define X_ACCL_OUT  0x0A
#define Y_ACCL_OUT  0x0C
#define Z_ACCL_OUT  0x0E

/* Scaling factors (from datasheet) */
#define GYRO_SCALE  0.05f   /* deg/sec/LSB */
#define ACCL_SCALE  0.00025f /* g/LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 /* 1 MHz */
#define SPI_FLAGS   0       /* Mode 0, active-low CS */

/* Timing */
#define STALL_US    40      /* ADIS16448 stall time after read command */
#define LOOP_US     100000  /* 100 ms loop period */

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read a 16-bit register from ADIS16448 via SPI.
 * Returns 0 on success, -1 on error. */
static int read_register(uint8_t reg, int16_t *value) {
    char tx[2], rx[2];
    int ret;

    /* First transfer: send read command (reg | 0x8000) */
    tx[0] = (char)((reg | 0x8000) >> 8);
    tx[1] = (char)(reg | 0x8000);
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI write failed for reg 0x%02X (ret=%d): %s\n",
                reg, ret, strerror(errno));
        return -1;
    }

    /* Stall time per datasheet */
    gpioDelay(STALL_US);

    /* Second transfer: clock out the 16-bit data */
    tx[0] = 0x00;
    tx[1] = 0x00;
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read failed for reg 0x%02X (ret=%d): %s\n",
                reg, ret, strerror(errno));
        return -1;
    }

    *value = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

int main(void) {
    int16_t gx, gy, gz, ax, ay, az;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d): %s\n",
                spi_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("ADIS16448 IMU reader started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_register(X_GYRO_OUT, &gx) != 0 ||
            read_register(Y_GYRO_OUT, &gy) != 0 ||
            read_register(Z_GYRO_OUT, &gz) != 0 ||
            read_register(X_ACCL_OUT, &ax) != 0 ||
            read_register(Y_ACCL_OUT, &ay) != 0 ||
            read_register(Z_ACCL_OUT, &az) != 0) {
            fprintf(stderr, "SPI transfer error; continuing...\n");
            gpioDelay(LOOP_US);
            continue;
        }

        float gx_dps = gx * GYRO_SCALE;
        float gy_dps = gy * GYRO_SCALE;
        float gz_dps = gz * GYRO_SCALE;
        float ax_g   = ax * ACCL_SCALE;
        float ay_g   = ay * ACCL_SCALE;
        float az_g   = az * ACCL_SCALE;

        printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s | "
               "Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
               gx_dps, gy_dps, gz_dps, ax_g, ay_g, az_g);

        gpioDelay(LOOP_US);
    }

    /* Clean shutdown */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

