#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6886_ADDR        0x68
#define MPU6886_WHO_AM_I    0x75
#define MPU6886_WHO_AM_I_VAL 0x86
#define PWR_MGMT_1          0x6B
#define ACCEL_CONFIG        0x1C
#define GYRO_CONFIG         0x1B
#define ACCEL_XOUT_H        0x3B
#define GYRO_XOUT_H         0x43

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C burst read from 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6886_init(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, MPU6886_WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != MPU6886_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, MPU6886_WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);

    if (i2c_write_reg8(fd, ACCEL_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, GYRO_CONFIG, 0x00) < 0) return -1;

    return 0;
}

static int read_sensor_data(int fd, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[14];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, sizeof(buf)) < 0) {
        return -1;
    }

    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    *gx = (int16_t)((buf[8] << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_fd = open("/dev/i2c-1", O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPU6886_ADDR, strerror(errno));
        close(g_fd);
        return EXIT_FAILURE;
    }

    if (mpu6886_init(g_fd) < 0) {
        fprintf(stderr, "MPU-6886 initialization failed.\n");
        close(g_fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6886 initialized. Reading data every 50 ms (Ctrl+C to exit)...\n");

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;
        if (read_sensor_data(g_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d | Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        usleep(50000);
    }

    printf("\nExiting cleanly.\n");
    if (g_fd >= 0) {
        close(g_fd);
    }
    return EXIT_SUCCESS;
}

