#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_DEVID   0x00
#define ADXL345_DEVID_EXPECTED 0xE5
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0   0x32
#define ADXL345_BW_RATE  0x2C
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_THRESH_ACT 0x24
#define ADXL345_ACT_INACT_CTL 0x27

#define LED_PIN 17
#define IMPACT_THRESHOLD 2.5
#define POLL_DELAY_US 10000
#define LED_ON_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(handle, reg, val);
}

static int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int rc = i2cReadI2CBlockData(handle, ADXL345_DATAX0, buf, 6);
    if (rc != 6) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    double xg = (double)x / 256.0;
    double yg = (double)y / 256.0;
    double zg = (double)z / 256.0;
    return sqrt(xg * xg + yg * yg + zg * zg);
}

static void log_impact(double magnitude, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s, Magnitude: %.2f g, X: %d, Y: %d, Z: %d\n",
            timestamp, magnitude, x, y, z);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X\n", ADXL345_ADDRESS);
        gpioTerminate();
        return 1;
    }

    uint8_t devid = 0;
    if (read_register(i2c_handle, ADXL345_DEVID, &devid) < 0) {
        fprintf(stderr, "Failed to read DEVID register\n");
        cleanup();
        return 1;
    }
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "ADXL345 not detected (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_EXPECTED);
        cleanup();
        return 1;
    }

    if (write_register(i2c_handle, ADXL345_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Failed to reset power control register\n");
        cleanup();
        return 1;
    }
    if (write_register(i2c_handle, ADXL345_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "Failed to set data rate\n");
        cleanup();
        return 1;
    }
    if (write_register(i2c_handle, ADXL345_DATA_FORMAT, 0x08) < 0) {
        fprintf(stderr, "Failed to set full resolution mode\n");
        cleanup();
        return 1;
    }
    if (write_register(i2c_handle, ADXL345_THRESH_ACT, 0x20) < 0) {
        fprintf(stderr, "Failed to set activity threshold\n");
        cleanup();
        return 1;
    }
    if (write_register(i2c_handle, ADXL345_ACT_INACT_CTL, 0x10) < 0) {
        fprintf(stderr, "Failed to set activity detection\n");
        cleanup();
        return 1;
    }
    if (write_register(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Failed to enable measurement mode\n");
        cleanup();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "I2C read error\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        double magnitude = calculate_magnitude(x, y, z);
        if (magnitude > IMPACT_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            log_impact(magnitude, x, y, z);
            gpioDelay(LED_ON_DELAY_US);
            gpioWrite(LED_PIN, 0);
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

