#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

/* Expected WHO_AM_I value for ICM-20602 */
#define ICM20602_WHO_AM_I 0x12

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* Signal handler for Ctrl+C */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Function to initialize the ICM-20602 */
static int init_icm20602(int handle) {
    int status;

    /* Wake up the device (clear sleep bit) */
    status = i2cWriteByteData(handle, PWR_MGMT_1, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", status);
        return -1;
    }
    gpioDelay(100000); /* 100 ms delay after wake-up */

    /* Set accelerometer range to +/- 2g (AFS_SEL = 0) */
    status = i2cWriteByteData(handle, ACCEL_CONFIG, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to ACCEL_CONFIG: %d\n", status);
        return -1;
    }

    /* Set gyroscope range to +/- 250 dps (FS_SEL = 0) */
    status = i2cWriteByteData(handle, GYRO_CONFIG, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG: %d\n", status);
        return -1;
    }

    return 0;
}

/* Function to read accelerometer data */
static int read_accelerometer(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;

    /* Burst read 6 bytes starting at ACCEL_XOUT_H */
    status = i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", status);
        return -1;
    }

    /* Combine high and low bytes (little-endian) */
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

