static int read_gyroscope(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;

    /* Burst read 6 bytes starting at GYRO_XOUT_H */
    status = i2cReadI2CBlockData(handle, GYRO_XOUT_H, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading gyroscope data: %d\n", status);
        return -1;
    }

