    int16_t ax, ay, az, gx, gy, gz;
    int status;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at the ICM-20602 address */
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Verify sensor presence by reading WHO_AM_I */
    status = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (status < 0) {
        fprintf(stderr, "Error reading WHO_AM_I: %d\n", status);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
