        if (read_accelerometer(i2c_handle, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
            gpioDelay(100000); /* 100 ms delay before retry */
            continue;
        }

        /* Read gyroscope data */
        if (read_gyroscope(i2c_handle, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Error reading gyroscope data, retrying...\n");
            gpioDelay(100000); /* 100 ms delay before retry */
            continue;
        }

        /* Log the data */
        if (log_data(log_file, ax, ay, az, gx, gy, gz) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        /* Flush the log file to ensure data is written */
        fflush(log_file);

        /* Delay for 100 ms (10 Hz sampling rate) */
        gpioDelay(100000);
    }

