        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mma8451_init(int fd) {
    uint8_t who;
    if (i2c_read(fd, WHO_AM_I, &who, 1) < 0) return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write(fd, CTRL_REG1, 0x00) < 0) return -1;
    if (i2c_write(fd, CTRL_REG2, 0x00) < 0) return -1;
    if (i2c_write(fd, CTRL_REG4, 0x00) < 0) return -1;
    if (i2c_write(fd, CTRL_REG5, 0x00) < 0) return -1;
    if (i2c_write(fd, CTRL_REG6, 0x00) < 0) return -1;
    if (i2c_write(fd, CTRL_REG7, 0x00) < 0) return -1;
    if (i2c_write(fd, CTRL_REG1, 0x01) < 0) return -1;
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t status;
    if (i2c_read(fd, STATUS_REG, &status, 1) < 0) return -1;
    if (!(status & STATUS_ZYXDR)) return 1;
    uint8_t raw[6];
    if (i2c_read(fd, XOUT_H, raw, 6) < 0) return -1;
    *x = (int16_t)((raw[0] << 8) | raw[1]);
    *y = (int16_t)((raw[2] << 8) | raw[3]);
    *z = (int16_t)((raw[4] << 8) | raw[5]);
    return 0;
}

static void log_impact(int16_t x, int16_t y, int16_t z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", ts, x, y, z);
    fclose(fp);
}

int main(void) {
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", MMA8451_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (mma8451_init(i2c_fd) < 0) {
        fprintf(stderr, "MMA8451 init failed\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(LED_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", LED_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_LINE);
    if (!led) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(led, "mma8451_impact", 0) < 0) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("MMA8451 impact monitor running. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t x, y, z;
        int rc = read_accel(i2c_fd, &x, &y, &z);
        if (rc < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(POLL_MS * 1000);
            continue;
        }
        if (rc == 1) {
            usleep(POLL_MS * 1000);
            continue;
        }
        float gx = x / SCALE_FACTOR;
        float gy = y / SCALE_FACTOR;
        float gz = z / SCALE_FACTOR;
        float mag = sqrtf(gx * gx + gy * gy + gz * gz);
        if (mag > THRESHOLD_G) {
            printf("Impact: X=%.2fg Y=%.2fg Z=%.2fg\n", gx, gy, gz);
            gpiod_line_set_value(led, 1);
            log_impact(x, y, z);
            usleep(LED_ON_MS * 1000);
            gpiod_line_set_value(led, 0);
        }
        usleep(POLL_MS * 1000);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

