    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (!file_exists) {
        if (fprintf(log_fp, "Timestamp,X,Y,Z\n") < 0 || fflush(log_fp) != 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            fclose(log_fp);
            close(i2c_fd);
            return 1;
        }
    }

    printf("TMAG5273 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t x, y, z;
        if (i2c_read_reg16(i2c_fd, X_REG, &x) == 0 &&
            i2c_read_reg16(i2c_fd, Y_REG, &y) == 0 &&
            i2c_read_reg16(i2c_fd, Z_REG, &z) == 0) {
            if (log_data(log_fp, x, y, z) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read error, continuing...\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

