#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0x6A
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

#define ACCEL_SENSITIVITY 0.061f
#define GYRO_SENSITIVITY 8.75f
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define FREEFALL_WINDOW 1.0f
#define SAMPLE_RATE 104.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_imu(void) {
    int who = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "I2C read error on WHO_AM_I: %d\n", who);
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X (expected 0x%02X)\n", who, WHO_AM_I_VAL);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Failed to write CTRL1_XL\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) {
        fprintf(stderr, "Failed to write CTRL2_G\n");
        return -1;
    }
    return 0;
}

static int read_imu(sensor_data_t *data) {
    char buf[6];
    int16_t raw;

    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buf, 6) != 6) {
        fprintf(stderr, "Gyro read error\n");
        return -1;
    }
    raw = (int16_t)((buf[1] << 8) | buf[0]);
    data->gyro_x = (float)raw / 32768.0f * 250.0f;

    raw = (int16_t)((buf[3] << 8) | buf[2]);
    data->gyro_y = (float)raw / 32768.0f * 250.0f;

    raw = (int16_t)((buf[5] << 8) | buf[4]);
    data->gyro_z = (float)raw / 32768.0f * 250.0f;

    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buf, 6) != 6) {
        fprintf(stderr, "Accel read error\n");
        return -1;
    }
    raw = (int16_t)((buf[1] << 8) | buf[0]);
    data->accel_x = (float)raw / 32768.0f * 2.0f;

    raw = (int16_t)((buf[3] << 8) | buf[2]);
    data->accel_y = (float)raw / 32768.0f * 2.0f;

    raw = (int16_t)((buf[5] << 8) | buf[4]);
    data->accel_z = (float)raw / 32768.0f * 2.0f;

    return 0;
}

static void log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            ts, data->accel_x, data->accel_y, data->accel_z,
            data->gyro_x, data->gyro_y, data->gyro_z);
    fflush(log_file);
}

static void detect_fall(const sensor_data_t *data) {
    static float freefall_start = 0.0f;
    static int in_freefall = 0;
    static float impact_start = 0.0f;
    static int in_impact = 0;
    float mag = sqrtf(data->accel_x * data->accel_x +
                      data->accel_y * data->accel_y +
                      data->accel_z * data->accel_z);

    time_t now = time(NULL);
    float t = (float)now;

    if (mag < FREEFALL_THRESHOLD && !in_freefall) {
        freefall_start = t;
        in_freefall = 1;
        printf("Freefall detected\n");
    } else if (mag > IMPACT_THRESHOLD && in_freefall) {
        if (t - freefall_start <= FREEFALL_WINDOW) {
            printf("Impact detected\n");
        }
        in_freefall = 0;
    }

    if (mag > IMPACT_THRESHOLD && !in_impact) {
        impact_start = t;
        in_impact = 1;
        printf("Impact detected\n");
    } else if (mag < FREEFALL_THRESHOLD && in_impact) {
        if (t - impact_start <= FREEFALL_WINDOW) {
            printf("Impact confirmed\n");
        }
        in_impact = 0;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_imu() < 0) {
        fprintf(stderr, "IMU init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    sensor_data_t data;
    while (running) {
        if (read_imu(&data) == 0) {
            log_data(&data);
            detect_fall(&data);
        } else {
            fprintf(stderr, "Read error, retrying...\n");
        }
        gpioDelay((int)(1000000.0f / SAMPLE_RATE));
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

