#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16266 Register Addresses */
#define ADIS16266_REG_XGYRO_OUT  0x14
#define ADIS16266_REG_WHO_AM_I   0x36
#define ADIS16266_WHO_AM_I_VAL   0x3F5A

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    3        /* CPOL=1, CPHA=1 */

/* Scaling factor: 0.0305 deg/sec per LSB */
#define GYRO_SCALE  0.0305f

/* Sampling interval: 10 ms */
#define SAMPLE_INTERVAL_US 10000

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x_gyro;
    float y_gyro;
    float z_gyro;
} gyro_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit register from ADIS16266.
 * Returns 0 on success, -1 on SPI error, -2 on WHO_AM_I mismatch. */
static int read_register(uint8_t reg, int16_t *value) {
    char tx[2], rx[2];
    int ret;

    /* Read command: bit 7 set, lower 7 bits = register address */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;

    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read transfer failed for reg 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }

    /* Second transfer: send dummy address, receive data */
    tx[0] = 0x00;
    tx[1] = 0x00;
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read data transfer failed for reg 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }

    *value = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int read_gyro_data(gyro_data_t *data) {
    int16_t raw_x, raw_y, raw_z;
    int rc;

    rc = read_register(ADIS16266_REG_XGYRO_OUT, &raw_x);
    if (rc != 0) return rc;

    /* Y and Z gyro data are 16-bit consecutive registers */
