#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* L3G4200D I2C address (SA0 tied high on GY-50 breakout) */
#define GYRO_ADDR 0x69

/* L3G4200D register addresses */
#define WHO_AM_I   0x0F
#define CTRL_REG1  0x20
#define CTRL_REG4  0x23
#define OUT_X_L    0x28

/* Expected device ID */
#define WHO_AM_I_VAL 0xD3

/* Sensitivity for +/-250 dps full-scale: 8.75 mdps/LSB = 0.00875 dps/LSB */
#define SENSITIVITY 0.00875f

/* Sampling interval in microseconds (10 ms) */
#define SAMPLE_INTERVAL_US 10000

/* Retry count for I2C writes during initialization */
#define I2C_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_retry(int handle, uint8_t reg, uint8_t val) {
    for (int i = 0; i < I2C_RETRIES; i++) {
        if (i2cWriteByteData(handle, reg, val) == 0) {
            return 0;
        }
        gpioDelay(1000); /* 1 ms backoff */
    }
    return -1;
}

static int initialize_gyro(int handle) {
    /* Verify device identity */
    int who = i2cReadByteData(handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error reading WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }

    /* Normal mode, all axes enabled, 100 Hz ODR (0x0F) */
    if (i2c_write_retry(handle, CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Error writing CTRL_REG1\n");
        return -1;
    }

    /* +/-250 dps full-scale, continuous update (0x00) */
    if (i2c_write_retry(handle, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Error writing CTRL_REG4\n");
        return -1;
    }

    return 0;
}

static int read_gyro_data(int handle, gyro_data_t *data) {
    char buffer[6];

    /* Read 6 bytes starting at OUT_X_L (0x28) in a single block */
    int bytes = i2cReadI2CBlockData(handle, OUT_X_L, buffer, 6);
    if (bytes != 6) {
        fprintf(stderr, "Error reading gyro data: %s\n", strerror(errno));
        return -1;
    }

    /* Combine little-endian low and high bytes */
    int16_t raw_x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

    /* Convert to dps */
    data->x = (float)raw_x * SENSITIVITY;
    data->y = (float)raw_y * SENSITIVITY;
    data->z = (float)raw_z * SENSITIVITY;

    return 0;
}

static int log_data(FILE *fp, const gyro_data_t *data) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%ld.%09ld,%.4f,%.4f,%.4f\n",
                (long)ts.tv_sec, ts.tv_nsec, data->x, data->y, data->z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at GY-50 address */
    i2c_handle = i2cOpen(1, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize gyroscope */
    if (initialize_gyro(i2c_handle) != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering signal handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    gyro_data_t gyro_data;

    /* Main sampling loop */
    while (!terminate) {
        if (read_gyro_data(i2c_handle, &gyro_data) == 0) {
            if (log_data(log_file, &gyro_data) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyro data, continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

