#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown (Ctrl+C) */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Function to read the flame sensor value */
static int read_flame_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value == PI_BAD_GPIO) {
        fprintf(stderr, "Error: Invalid GPIO pin %d\n", gpio_pin);
        return -1;
    }
    return value;
}

/* Function to log events to a file */
static void log_event(FILE *fp, const char *event) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: Failed to get current time\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: Failed to convert time\n");
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: Failed to format timestamp\n");
        return;
    }

    if (fprintf(fp, "%s - %s\n", timestamp, event) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
    } else {
        fflush(fp);
    }
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

