#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8452Q_ADDR  0x1D
#define WHO_AM_I       0x0D
#define WHO_AM_I_VAL   0x2A
#define CTRL_REG1      0x2A
#define OUT_X_MSB      0x01
#define NUM_DATA_REGS  6
#define TILT_THRESHOLD 45.0
#define LOG_FILE       "fall_log.txt"
#define POLL_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C block write (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read (reg 0x%02X, %zu bytes) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mma8452q(int fd)
{
    uint8_t whoami = 0;
    if (i2c_read_reg8(fd, WHO_AM_I, &whoami) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register.\n");
        return -1;
    }
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                whoami, WHO_AM_I_VAL);
        return -1;
    }

    uint8_t ctrl1 = 0;
    if (i2c_read_reg8(fd, CTRL_REG1, &ctrl1) != 0) {
        fprintf(stderr, "Cannot read CTRL_REG1.\n");
        return -1;
    }
    ctrl1 &= ~0x01;                       /* standby mode */
    ctrl1 &= ~0x38;                       /* clear data rate bits */
    ctrl1 |= 0x02;                        /* 100 Hz ODR */
    if (i2c_write_reg8(fd, CTRL_REG1, ctrl1) != 0) {
        fprintf(stderr, "Cannot write CTRL_REG1.\n");
        return -1;
    }

    ctrl1 |= 0x01;                        /* active mode */
    if (i2c_write_reg8(fd, CTRL_REG1, ctrl1) != 0) {
        fprintf(stderr, "Cannot set active mode.\n");
        return -1;
    }
    return 0;
}

static int read_accelerometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_MSB, buf, sizeof(buf)) != 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 4;
    return 0;
}

static double calculate_tilt_angle(int16_t x, int16_t y, int16_t z)
{
    double xg = (double)x / 4096.0;
    double yg = (double)y / 4096.0;
    double zg = (double)z / 4096.0;
    return atan2(xg, sqrt(yg * yg + zg * zg)) * 180.0 / M_PI;
}

static void log_fall_event(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", ts, x, y, z);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MMA8452Q_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_mma8452q(g_i2c_fd) != 0) {
        fprintf(stderr, "MMA8452Q initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("MMA8452Q tilt monitor started. Logging to %s. Press Ctrl+C to exit.\n",
           LOG_FILE);

    while (g_running) {
        int16_t x, y, z;
        if (read_accelerometer(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error; continuing.\n");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        double tilt = calculate_tilt_angle(x, y, z);
        if (fabs(tilt) > TILT_THRESHOLD) {
            log_fall_event(g_log_fp, x, y, z);
            printf("Fall detected! Tilt: %.2f deg, X:%d Y:%d Z:%d\n",
                   tilt, x, y, z);
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

