#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LIS3MDL_ADDR   0x1E
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0x3D
#define CTRL_REG1      0x20
#define CTRL_REG2      0x21
#define CTRL_REG3      0x22
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define OUT_X_H        0x29
#define OUT_Y_L        0x2A
#define OUT_Y_H        0x2B
#define OUT_Z_L        0x2C
#define OUT_Z_H        0x2D

#define X_OFFSET       0.0f
#define Y_OFFSET       0.0f
#define Z_OFFSET       0.0f
#define X_SCALE        0.146f
#define Y_SCALE        0.146f
#define Z_SCALE        0.146f
#define METAL_THRESHOLD 800.0f
#define SAMPLE_PERIOD_NS 100000000L
#define MAX_INIT_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C burst write (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_lis3mdl(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I, &who_am_i) < 0) return -1;
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg8(fd, CTRL_REG1, 0x70) < 0) return -1; /* 80 Hz ODR, continuous mode */
    if (i2c_write_reg8(fd, CTRL_REG2, 0x00) < 0) return -1; /* default gain */
    if (i2c_write_reg8(fd, CTRL_REG3, 0x00) < 0) return -1; /* continuous conversion */
    if (i2c_write_reg8(fd, CTRL_REG4, 0x0C) < 0) return -1; /* high performance mode, all axes */

    return 0;
}

static int read_magnetometer(int fd, float *x, float *y, float *z) {
    uint8_t raw[6];
    if (i2c_read_burst(fd, OUT_X_L, raw, 6) < 0) return -1;

    int16_t x_raw = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t y_raw = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t z_raw = (int16_t)((raw[5] << 8) | raw[4]);

    *x = (float)x_raw * X_SCALE + X_OFFSET;
    *y = (float)y_raw * Y_SCALE + Y_OFFSET;
    *z = (float)z_raw * Z_SCALE + Z_OFFSET;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    fprintf(fp, "%.2f,%.2f,%.2f\n", x, y, z);
    fflush(fp);
}

static void metal_detected(float x, float y, float z) {
    float mag = sqrtf(x * x + y * y + z * z);
    if (mag > METAL_THRESHOLD) {
        fprintf(stderr, "Metal Detected! |X|=%.2f |Y|=%.2f |Z|=%.2f |M|=%.2f\n", x, y, z, mag);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LIS3MDL_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    int init_retries = 0;
    while (init_retries < MAX_INIT_RETRIES) {
        if (init_lis3mdl(g_i2c_fd) == 0) break;
        init_retries++;
        fprintf(stderr, "LIS3MDL init attempt %d/%d failed\n", init_retries, MAX_INIT_RETRIES);
        if (init_retries < MAX_INIT_RETRIES) usleep(100000);
    }
    if (init_retries >= MAX_INIT_RETRIES) {
        fprintf(stderr, "LIS3MDL initialization failed after %d retries.\n", MAX_INIT_RETRIES);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("magnetic_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open magnetic_log.txt: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    struct timespec next;
    clock_gettime(CLOCK_MONOTONIC, &next);

    while (g_running) {
        float x, y, z;
        if (read_magnetometer(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_log_fp, x, y, z);
            metal_detected(x, y, z);
        } else {
            fprintf(stderr, "Read error, attempting reinit...\n");
            init_retries = 0;
            while (init_retries < MAX_INIT_RETRIES && g_running) {
                if (init_lis3mdl(g_i2c_fd) == 0) break;
                init_retries++;
                fprintf(stderr, "LIS3MDL reinit attempt %d/%d failed\n", init_retries, MAX_INIT_RETRIES);
                if (init_retries < MAX_INIT_RETRIES) usleep(100000);
            }
            if (init_retries >= MAX_INIT_RETRIES) {
                fprintf(stderr, "LIS3MDL reinit failed after %d retries.\n", MAX_INIT_RETRIES);
                break;
            }
        }

        next.tv_nsec += SAMPLE_PERIOD_NS;
        if (next.tv_nsec >= 1000000000L) {
            next.tv_nsec -= 1000000000L;
            next.tv_sec++;
        }
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (next.tv_sec > now.tv_sec || (next.tv_sec == now.tv_sec && next.tv_nsec > now.tv_nsec)) {
            struct timespec sleep_ts = { next.tv_sec - now.tv_sec, next.tv_nsec - now.tv_nsec };
            nanosleep(&sleep_ts, NULL);
        }
    }

