#define ADXL354B_REG_XDATA 0x08
#define ADXL354B_REG_YDATA 0x0B
#define ADXL354B_REG_ZDATA 0x0E
#define ADXL354B_REG_RESET 0x1F
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_STATUS 0x04

#define ADXL354B_PARTID 0x1D
#define ADXL354B_SENSITIVITY 0.0000039f

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = {0};
    int retries = SPI_RETRIES;
    while (retries > 0) {
        if (spiXfer(spi_handle, tx, rx, 2) == 2) {
            *value = (uint8_t)rx[1];
            return 0;
        }
        retries--;
        if (retries > 0) gpioDelay(SPI_RETRY_DELAY_US);
    }
    return -1;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    int retries = SPI_RETRIES;
    while (retries > 0) {
        if (spiWrite(spi_handle, tx, 2) == 2) return 0;
        retries--;
        if (retries > 0) gpioDelay(SPI_RETRY_DELAY_US);
    }
    return -1;
}

static int spi_read_block(uint8_t reg, uint8_t *buf, int len) {
    char tx[7] = {0};
    char rx[7] = {0};
    if (len > 6) return -1;
    tx[0] = (char)(reg | 0xA0);
    int retries = SPI_RETRIES;
    while (retries > 0) {
        if (spiXfer(spi_handle, tx, rx, len + 1) == (len + 1)) {
            memcpy(buf, rx + 1, len);
            return 0;
        }
        retries--;
        if (retries > 0) gpioDelay(SPI_RETRY_DELAY_US);
    }
    return -1;
}

static int adxl354b_init(void) {
    uint8_t partid = 0;
    if (spi_read_register(ADXL354B_REG_PARTID, &partid) != 0) {
        fprintf(stderr, "Error: Failed to read PARTID register.\n");
        return -1;
    }
    if (partid != ADXL354B_PARTID) {
        fprintf(stderr, "Error: Unexpected PARTID 0x%02X (expected 0x%02X).\n", partid, ADXL354B_PARTID);
        return -1;
    }
    printf("ADXL354B detected (PARTID=0x%02X).\n", partid);

    if (spi_write_register(ADXL354B_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "Error: Failed to reset ADXL354B.\n");
        return -1;
    }
    gpioDelay(1000);

    uint8_t status = 0;
    int timeout = 100;
    while (timeout > 0) {
        if (spi_read_register(ADXL354B_REG_STATUS, &status) == 0) break;
        gpioDelay(1000);
        timeout--;
    }
    if (timeout == 0) {
        fprintf(stderr, "Error: Timeout waiting for ADXL354B to become stable.\n");
        return -1;
    }

    if (spi_write_register(ADXL354B_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to clear POWER_CTL.\n");
        return -1;
    }
    gpioDelay(1000);

    timeout = 100;
    uint8_t status_val = 0;
    while (timeout > 0) {
        if (spi_read_register(ADXL354B_REG_STATUS, &status_val) == 0) {
            if ((status_val & 0x01) == 0) break;
        }
        gpioDelay(1000);
        timeout--;
    }
    if (timeout == 0) {
        fprintf(stderr, "Error: Timeout waiting for STABLE bit.\n");
        return -1;
    }

    if (spi_write_register(ADXL354B_REG_POWER_CTL, 0x02) != 0) {
        fprintf(stderr, "Error: Failed to set RUN bit.\n");
        return -1;
    }
    gpioDelay(1000);

    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    uint8_t data[6];
    if (spi_read_block(ADXL354B_REG_XDATA, data, 6) != 0) {
        fprintf(stderr, "Error: Failed to read acceleration data.\n");
        return -1;
    }
    int32_t x_raw = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    int32_t y_raw = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);
    *x = (float)x_raw * ADXL354B_SENSITIVITY;
    *y = (float)y_raw * ADXL354B_SENSITIVITY;
    *z = 0.0f;
    return 0;
}

static void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed.\n");
        gpioTerminate();
        return 1;
    }

    if (adxl354b_init() != 0) {
        fprintf(stderr, "Error: ADXL354B initialisation failed.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Warning: Failed to read acceleration data, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

