#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADIS16362 Register Addresses */
#define X_GYRO_REG  0x04
#define Y_GYRO_REG  0x06
#define Z_GYRO_REG  0x08
#define X_ACCL_REG  0x0A
#define Y_ACCL_REG  0x0C
#define Z_ACCL_REG  0x0E

/* Scaling factors (from datasheet) */
#define GYRO_SCALE  0.05f   /* degrees/sec per LSB */
#define ACCL_SCALE  0.0025f /* g per LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000 /* 1 MHz */
#define SPI_FLAGS   0x00000003 /* Mode 3: CPOL=1, CPHA=1 */

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 10000

/* Global state for signal handler */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit register from ADIS16362.
 * Protocol: send address with MSB set, then dummy byte, then read 16-bit data.
 * Returns 0 on success, -1 on error. */
static int read_register(uint8_t reg_addr, int16_t *out_value) {
    char tx_buf[3];
    char rx_buf[3];
    int ret;

    /* Phase 1: send read command (address + MSB set) */
    tx_buf[0] = (char)(reg_addr | 0x80);
    tx_buf[1] = 0x00; /* dummy byte to clock out data */
    tx_buf[2] = 0x00; /* dummy byte to clock out data */

    ret = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer (read command) failed for reg 0x%02X (ret=%d)\n",
                reg_addr, ret);
        return -1;
    }

    /* Small delay to allow conversion to complete (per datasheet timing) */
    gpioDelay(10);

    /* Phase 2: send dummy address to clock out data */
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    ret = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer (data read) failed for reg 0x%02X (ret=%d)\n",
                reg_addr, ret);
        return -1;
    }

    /* Data is returned in rx_buf[1] and rx_buf[2] (MSB first) */
    *out_value = (int16_t)(((uint8_t)rx_buf[1] << 8) | (uint8_t)rx_buf[2]);
    return 0;
}

/* Read a signed 16-bit value from a register */
static int read_signed_register(uint8_t reg_addr, int16_t *out_value) {
    int16_t raw;
    if (read_register(reg_addr, &raw) != 0) {
