/*
 * KY-032 IR Obstacle Avoidance Sensor Collision Avoidance Simulator
 * Board:  Raspberry Pi 3 Model B+
 * Library: libgpiod (v2 API)
 *
 * Wiring:
 *   KY-032 OUT  -> GPIO17 (BCM 17, physical pin 11)
 *   KY-032 VCC  -> 3.3 V (physical pin 1)
 *   KY-032 GND  -> GND  (physical pin 9)
 *   KY-032 OUT  -> GPIO27 (BCM 27, physical pin 13)
 *
 * The KY-032 output is active-low: 0 = obstacle detected, 1 = clear.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o obstacle_avoid obstacle_avoid.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO17_OFFSET    17
#define GPIO27_OFFSET    27
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "unknown-time");
    printf("[%s] ", ts);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *req = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the gpiochip --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure both lines as inputs --- */
    settings = gpiod_line_settings_new();
    if (!settings) {
        fprintf(stderr, "Failed to allocate line settings: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        fprintf(stderr, "Failed to allocate line config: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned int offsets[2] = { GPIO17_OFFSET, GPIO27_OFFSET };
    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 2, settings) < 0) {
        fprintf(stderr, "Failed to add line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Request config --- */
    req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        fprintf(stderr, "Failed to allocate request config: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ky032-obstacle-avoid");

    /* --- Request both lines together --- */
    req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (!req) {
        fprintf(stderr, "Failed to request GPIO lines %u and %u: %s\n",
                GPIO17_OFFSET, GPIO27_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Obstacle avoidance system started.\n");
    printf("  Sensor 1: GPIO17 (BCM 17, physical pin 11)\n");
    printf("  Sensor 2: GPIO27 (BCM 27, physical pin 13)\n");
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        enum gpiod_line_value values[2];
        int rc = gpiod_line_request_get_values(req, values);
        if (rc < 0) {
            fprintf(stderr, "gpiod_line_request_get_values failed: %s\n", strerror(errno));
            break;
        }

        int v17 = values[0];
        int v27 = values[1];

        print_timestamp();
        printf("Sensor 1: %s | Sensor 2: %s\n",
               v17 == GPIOD_LINE_VALUE_ACTIVE ? "OBSTACLE" : "clear",
               v27 == GPIOD_LINE_VALUE_ACTIVE ? "OBSTACLE" : "clear");

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (req)
        gpiod_line_request_release(req);
    if (req_cfg)
        gpiod_request_config_free(req_cfg);
    if (line_cfg)
        gpiod_line_config_free(line_cfg);
    if (settings)
        gpiod_line_settings_free(settings);
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nObstacle avoidance system stopped.\n");

    return ret;
}

