    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the gpiochip --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure both lines as inputs --- */
    settings = gpiod_line_settings_new();
    if (!settings) {
        fprintf(stderr, "Failed to allocate line settings: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        fprintf(stderr, "Failed to allocate line config: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned int offsets[2] = { GPIO17_OFFSET, GPIO27_OFFSET };
    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 2, settings) < 0) {
        fprintf(stderr, "Failed to add line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Request config --- */
    req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        fprintf(stderr, "Failed to allocate request config: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ky032-obstacle-avoid");

    /* --- Request both lines together --- */
    req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (!req) {
        fprintf(stderr, "Failed to request GPIO lines %u and %u: %s\n",
                GPIO17_OFFSET, GPIO27_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Obstacle avoidance system started.\n");
    printf("  Sensor 1: GPIO17 (BCM 17, physical pin 11)\n");
    printf("  Sensor 2: GPIO27 (BCM 27, physical pin 13)\n");
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        enum gpiod_line_value values[2];
        int rc = gpiod_line_request_get_values(req, values);
        if (rc < 0) {
            fprintf(stderr, "gpiod_line_request_get_values failed: %s\n", strerror(errno));
            break;
        }

        int v17 = values[0];
        int v27 = values[1];

        print_timestamp();
        printf("Sensor 1: %s | Sensor 2: %s\n",
               v17 == GPIOD_LINE_VALUE_ACTIVE ? "OBSTACLE" : "clear",
               v27 == GPIOD_LINE_VALUE_ACTIVE ? "OBSTACLE" : "clear");

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (req)
        gpiod_line_request_release(req);
    if (req_cfg)
        gpiod_request_config_free(req_cfg);
    if (line_cfg)
        gpiod_line_config_free(line_cfg);
    if (settings)
        gpiod_line_settings_free(settings);
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nObstacle avoidance system stopped.\n");

    return ret;
}

