#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 8

#define ADIS16266_REG_XGYRO_OUT 0x04
#define ADIS16266_REG_YGYRO_OUT 0x06
#define ADIS16266_REG_ZGYRO_OUT 0x08
#define ADIS16266_REG_MSC_CTRL 0x24

#define ADIS16266_MSC_CTRL_DATA_READY 0x0001
#define ADIS16266_MSC_CTRL_GYRO_EN 0x0002
#define ADIS16266_MSC_CTRL_GYRO_RESET 0x0004

#define GYRO_SCALE 0.02f
#define CS_PIN 8
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int adis16266_write_reg(int fd, struct gpiod_line *cs, uint8_t reg, uint16_t value) {
    uint8_t tx[4] = {0x80 | (reg & 0x7F), (uint8_t)(value >> 8), (uint8_t)(value & 0xFF), 0x00};
    uint8_t rx[4] = {0};

    gpiod_line_set_value(cs, 0);
    usleep(10);
    if (spi_transfer(fd, tx, rx, 4) < 0) {
        gpiod_line_set_value(cs, 1);
        return -1;
    }
    gpiod_line_set_value(cs, 1);
    return 0;
}

static int adis16266_read_reg(int fd, struct gpiod_line *cs, uint8_t reg, uint16_t *value) {
    uint8_t tx[4] = {0x00 | (reg & 0x7F), 0x00, 0x00, 0x00};
    uint8_t rx[4] = {0};

    gpiod_line_set_value(cs, 0);
    usleep(10);
    if (spi_transfer(fd, tx, rx, 4) < 0) {
        gpiod_line_set_value(cs, 1);
        return -1;
    }
    gpiod_line_set_value(cs, 1);

    *value = ((uint16_t)rx[1] << 8) | rx[2];
    return 0;
}

static int adis16266_read_gyro(int fd, struct gpiod_line *cs, float *x, float *y, float *z) {
    uint16_t raw_x, raw_y, raw_z;

    if (adis16266_read_reg(fd, cs, ADIS16266_REG_XGYRO_OUT, &raw_x) < 0) return -1;
    if (adis16266_read_reg(fd, cs, ADIS16266_REG_YGYRO_OUT, &raw_y) < 0) return -1;
    if (adis16266_read_reg(fd, cs, ADIS16266_REG_ZGYRO_OUT, &raw_z) < 0) return -1;

    *x = (float)raw_x * GYRO_SCALE;
    *y = (float)raw_y * GYRO_SCALE;
    *z = (float)raw_z * GYRO_SCALE;

    return 0;
}

int main(void) {
    int fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open gpiochip4");
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        perror("Failed to get CS line");
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "adis16266_cs", 1) < 0) {
        perror("Failed to request CS line as output");
        goto cleanup;
    }

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        goto cleanup;
    }

    if (adis16266_write_reg(fd, cs_line, ADIS16266_REG_MSC_CTRL, ADIS16266_MSC_CTRL_GYRO_RESET) < 0) {
        fprintf(stderr, "Failed to reset gyro\n");
        goto cleanup;
    }
    usleep(10000);

    if (adis16266_write_reg(fd, cs_line, ADIS16266_REG_MSC_CTRL, ADIS16266_MSC_CTRL_GYRO_EN | ADIS16266_MSC_CTRL_DATA_READY) < 0) {
        fprintf(stderr, "Failed to enable data ready mode\n");
        goto cleanup;
    }
    usleep(10000);

    printf("ADIS16266 initialized. Reading gyro data...\n");

    while (running) {
        float x, y, z;
        if (adis16266_read_gyro(fd, cs_line, &x, &y, &z) == 0) {
            printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }
        usleep(POLL_INTERVAL_US);
    }

    ret = 0;

cleanup:
    if (fd >= 0) close(fd);
    if (cs_line) gpiod_line_release(cs_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

