#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LSM6DSR_ADDR        0x6B
#define WHO_AM_I            0x0F
#define WHO_AM_I_VAL        0x6B
#define CTRL1_XL            0x10
#define CTRL2_G             0x11
#define OUTX_L_G            0x22

#define GYRO_SENSITIVITY    0.00875f   /* mdps/LSB at +/-250 dps */
#define ACCEL_SENSITIVITY   0.000061f  /* mg/LSB at +/-2g */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: pigpio rc=%d\n", reg, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "I2C short read at reg 0x%02X: got %d of %u bytes\n", reg, rc, len);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: pigpio rc=%d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(int handle)
{
    uint8_t whoami = 0;
    if (i2c_read_block(handle, WHO_AM_I, &whoami, 1) != 0)
        return -1;
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, WHO_AM_I_VAL);
        return -1;
    }

    /* Gyro: 104 Hz, +/-250 dps, anti-aliasing 408 Hz */
    if (i2c_write_byte(handle, CTRL2_G, 0x42) != 0)
        return -1;
    /* Accel: 104 Hz, +/-2g, anti-aliasing 408 Hz */
    if (i2c_write_byte(handle, CTRL1_XL, 0x42) != 0)
        return -1;

    return 0;
}

static int read_sensor_data(int handle, float *ax, float *ay, float *az,
                            float *gx, float *gy, float *gz)
{
    uint8_t buf[12];
    if (i2c_read_block(handle, OUTX_L_G, buf, sizeof(buf)) != 0)
        return -1;

    int16_t raw_gx = (int16_t)((buf[1]  << 8) | buf[0]);
    int16_t raw_gy = (int16_t)((buf[3]  << 8) | buf[2]);
    int16_t raw_gz = (int16_t)((buf[5]  << 8) | buf[4]);
    int16_t raw_ax = (int16_t)((buf[7]  << 8) | buf[6]);
    int16_t raw_ay = (int16_t)((buf[9]  << 8) | buf[8]);
    int16_t raw_az = (int16_t)((buf[11] << 8) | buf[10]);

    *gx = (float)raw_gx * GYRO_SENSITIVITY;
    *gy = (float)raw_gy * GYRO_SENSITIVITY;
    *gz = (float)raw_gz * GYRO_SENSITIVITY;
    *ax = (float)raw_ax * ACCEL_SENSITIVITY;
    *ay = (float)raw_ay * ACCEL_SENSITIVITY;
    *az = (float)raw_az * ACCEL_SENSITIVITY;

    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: pigpio rc=%d\n",
                LSM6DSR_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_handle) != 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float ax, ay, az, gx, gy, gz;
    while (g_running) {
        if (read_sensor_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%.3f g, Y=%.3f g, Z=%.3f g | Gyro: X=%.3f dps, Y=%.3f dps, Z=%.3f dps\n",
                   ax, ay, az, gx, gy, gz);
            fflush(stdout);
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

