#define FXOS8700_ADDR 0x1D
#define WHO_AM_I 0x0D
#define WHO_AM_I_VAL 0xC7
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define M_CTRL_REG1 0x5B
#define M_CTRL_REG2 0x5C
#define OUT_X_MSB 0x01

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_fxos8700(void) {
    int who = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register (pigpio error %d)\n", who);
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who, WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set standby mode\n");
        return -1;
    }

    /* Set hybrid mode: accelerometer and magnetometer active */
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x3F) < 0) {
        fprintf(stderr, "Error: failed to set CTRL_REG1\n");
        return -1;
    }

    /* Set high-resolution mode (CTRL_REG2 bit 0) */
    if (i2cWriteByteData(i2c_handle, CTRL_REG2, 0x01) < 0) {
        fprintf(stderr, "Error: failed to set CTRL_REG2\n");
        return -1;
    }

    /* Configure magnetometer: OSR=1, 0.5 Hz output data rate */
    if (i2cWriteByteData(i2c_handle, M_CTRL_REG1, 0x1F) < 0) {
        fprintf(stderr, "Error: failed to set M_CTRL_REG1\n");
        return -1;
    }

    /* M_CTRL_REG2: auto-increment off, 12-bit mode */
    if (i2cWriteByteData(i2c_handle, M_CTRL_REG2, 0x20) < 0) {
        fprintf(stderr, "Error: failed to set M_CTRL_REG2\n");
        return -1;
    }

    return 0;
}

static int read_sensor_data(int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *mx, int16_t *my, int16_t *mz) {
    char buf[12];
    int n = i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buf, 12);
    if (n != 12) {
        fprintf(stderr, "Error: I2C block read returned %d bytes (expected 12)\n", n);
        return -1;
    }

    /* Accelerometer: 14-bit left-aligned, shift right 2 to get 14-bit value */
    *ax = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8 | (uint8_t)buf[1]) >> 2);
