    *mx = (int16_t)(((uint16_t)(uint8_t)buf[6]  | ((uint16_t)(uint8_t)buf[7]  << 8)));
    *my = (int16_t)(((uint16_t)(uint8_t)buf[8]  | ((uint16_t)(uint8_t)buf[9]  << 8)));
    *mz = (int16_t)(((uint16_t)(uint8_t)buf[10] | ((uint16_t)(uint8_t)buf[11] << 8)));

