        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_fxos8700() < 0) {
        fprintf(stderr, "Error: FXOS8700 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("FXOS8700 initialized. Reading data every 100 ms. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int16_t ax, ay, az, mx, my, mz;

        if (read_sensor_data(&ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d, Y=%6d, Z=%6d | Mag: X=%6d, Y=%6d, Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Warning: sensor read failed, retrying in 100 ms...\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

