#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37
#define I2C_BUS "/dev/i2c-1"
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg, int16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

int init_adxl345(int fd) {
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: Could not write to POWER_CTL register: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);
    if (i2c_write_reg8(fd, ADXL345_DATA_FORMAT, 0x08) < 0) {
        fprintf(stderr, "Error: Could not write to DATA_FORMAT register: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Could not write to POWER_CTL register: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);
    return 0;
}

int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    if (i2c_read_reg16(fd, ADXL345_DATAX0, x) < 0) {
        fprintf(stderr, "Error: Could not read DATAX0 register: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_read_reg16(fd, ADXL345_DATAY0, y) < 0) {
        fprintf(stderr, "Error: Could not read DATAY0 register: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_read_reg16(fd, ADXL345_DATAZ0, z) < 0) {
        fprintf(stderr, "Error: Could not read DATAZ0 register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double x_val = (double)x;
    double y_val = (double)y;
    double z_val = (double)z;
    double tilt_angle = atan2(y_val, sqrt(x_val * x_val + z_val * z_val)) * 180.0 / M_PI;
    return tilt_angle;
}

void log_tilt_event(double tilt_angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Tilt Angle: %.2f degrees\n", timestamp, tilt_angle);
    fclose(fp);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_adxl345(i2c_fd) < 0) {
        fprintf(stderr, "Error: ADXL345 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("ADXL345 initialized. Logging tilt events to %s\n", LOG_FILE);

    while (running) {
        int16_t x, y, z;
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            double tilt_angle = calculate_tilt_angle(x, y, z);
            printf("Tilt Angle: %.2f degrees\n", tilt_angle);
            if (fabs(tilt_angle) > TILT_THRESHOLD) {
                log_tilt_event(tilt_angle);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

