    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Tilt Angle: %.2f degrees\n", timestamp, tilt_angle);
    fclose(fp);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_adxl345(i2c_fd) < 0) {
        fprintf(stderr, "Error: ADXL345 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("ADXL345 initialized. Logging tilt events to %s\n", LOG_FILE);

    while (running) {
        int16_t x, y, z;
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            double tilt_angle = calculate_tilt_angle(x, y, z);
            printf("Tilt Angle: %.2f degrees\n", tilt_angle);
            if (fabs(tilt_angle) > TILT_THRESHOLD) {
                log_tilt_event(tilt_angle);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

