/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Two 12V electromagnetic door locks driven by 5V active-HIGH relay modules
 * (TIP120) on GPIO17 (Door A) and GPIO27 (Door B).  A 6-digit security
 * code is generated at startup and accepted via stdin.  On successful
 * entry the door is unlocked for 5 s, then re-locked, and a CSV log
 * line is appended to access_log.txt.
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 * Run:    ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define DOOR_A_PIN      17
#define DOOR_B_PIN      27
#define UNLOCK_DURATION 5          /* seconds */
#define LOG_FILE        "access_log.txt"
#define CODE_LEN        6
#define CODE_MIN        100000
#define CODE_MAX        999999

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Return a static buffer containing a 6-digit security code.         */
/* ------------------------------------------------------------------ */
static char *generate_code(void)
{
    static char code[CODE_LEN + 1];
    int i;

    for (i = 0; i < CODE_LEN; i++)
        code[i] = (char)((rand() % 10) + '0');
    code[CODE_LEN] = '\0';
    return code;
}

/* ------------------------------------------------------------------ */
/* Unlock the door (relay HIGH) for UNLOCK_DURATION seconds, then      */
/* re-lock (LOW).                                                       */
/* ------------------------------------------------------------------ */
static void unlock_door(struct gpiod_line *line)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set DOOR HIGH: %s\n", strerror(errno));
        return;
    }

    sleep(UNLOCK_DURATION);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set DOOR LOW: %s\n", strerror(errno));
        return;
    }
}

/* ------------------------------------------------------------------ */
/* Append a CSV log line: "YYYY-MM-DD HH:MM:SS,NNNNNN"                  */
/* ------------------------------------------------------------------ */
static void log_access(const char *code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, code);

    if (fclose(fp) != 0)
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL, *line_b = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Seed PRNG ----------------------------------------------- */
    srand((unsigned int)time(NULL));

    /* ---- Open GPIO chip ------------------------------------------- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Get lines ------------------------------------------------ */
    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!line_a) {
        fprintf(stderr, "Failed to get GPIO%d: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }
    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!line_b) {
        fprintf(stderr, "Failed to get GPIO%d: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Request lines as outputs, default LOW -------------------- */
    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO%d as output: %s\n",
                DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO%d as output: %s\n",
                DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Door access control system started.\n");
    printf("Enter the security code to unlock the door.\n");
    printf("Press Ctrl+C to exit.\n\n");

    /* ---- Main loop ------------------------------------------------ */
    while (g_running) {
        char *code = generate_code();
        printf("Enter code: %s\n", code);
        fflush(stdout);

        char input[CODE_LEN + 1];
        if (fgets(input, sizeof(input), stdin) == NULL) {
            if (feof(stdin)) {
                printf("\nEOF received, exiting.\n");
                break;
            }
            if (errno == EINTR) {
                clearerr(stdin);
                continue;
            }
            fprintf(stderr, "fgets error: %s\n", strerror(errno));
            continue;
        }

        /* Strip trailing newline */
        input[strcspn(input, "\n")] = '\0';

        /* Validate: must be exactly CODE_LEN digits */
        if (strlen(input) != CODE_LEN) {
            printf("Invalid input. Please enter a %d-digit code.\n", CODE_LEN);
            continue;
        }

        /* Validate: all characters must be digits */
        for (int i = 0; i < CODE_LEN; i++) {
            if (input[i] < '0' || input[i] > '9') {
                printf("Invalid input. Please enter a %d-digit code.\n", CODE_LEN);
                goto next_iteration;
            }
        }

        if (strcmp(code, input) == 0) {
            printf("Access granted.\n");
            unlock_door(line_a);
            log_access(code);
            printf("Door re-locked.\n");
        } else {
            printf("Access denied.\n");
        }

    next_iteration:
        printf("\n");
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Ensure both doors are locked on exit --------------------- */
    if (line_a) {
        gpiod_line_set_value(line_a, 0);
        gpiod_line_release(line_a);
    }
    if (line_b) {
        gpiod_line_set_value(line_b, 0);
        gpiod_line_release(line_b);
    }
    if (chip)
        gpiod_chip_close(chip);

    printf("Door access control system stopped.\n");
    return ret;
}

