#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR 0x23
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "light_log.txt"
#define CONVERSION_TIME_MS 180
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int init_i2c(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

int read_bh1750(int fd, float *lux) {
    uint8_t cmd = 0x21; // One-Time High-Resolution Mode 2
    if (write(fd, &cmd, 1) != 1) {
        perror("Failed to write measurement command");
        return -1;
    }
    usleep(CONVERSION_TIME_MS * 1000);
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read sensor data");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

int log_data(const char *filename, float lux) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Failed to open log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

