    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    while (running) {
        float lux;
        if (read_bh1750(i2c_fd, &lux) == 0) {
            if (log_data(LOG_FILE, lux) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: failed to read sensor data\n");
        }
        sleep(POLL_INTERVAL_SEC);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return EXIT_SUCCESS;
}

