#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_GPIO 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define PORT 12345
#define SHARED_SECRET "MySecretKey"
#define LOG_FILE "frequency_log.txt"
#define SAMPLE_INTERVAL_US 20000
#define PLAYBACK_DURATION_S 5

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHD_RISING 0x2B
#define MPR121_NHD_RISING 0x2C
#define MPR121_NCL_RISING 0x2D
#define MPR121_FDL_RISING 0x2E
#define MPR121_MHD_FALLING 0x2F
#define MPR121_NHD_FALLING 0x30
#define MPR121_NCL_FALLING 0x31
#define MPR121_FDL_FALLING 0x32
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_fd = -1;
static int client_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_init(void) {
    if (i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "MPR121 soft reset failed\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "MPR121 electrode config failed\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, MPR121_MHD_RISING, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NHD_RISING, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NCL_RISING, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_FDL_RISING, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_MHD_FALLING, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NHD_FALLING, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NCL_FALLING, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_FDL_FALLING, 0x00) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_E0TTH + i * 2, 0x0F) < 0) return -1;
        if (i2cWriteByteData(i2c_handle, MPR121_E0RTH + i * 2, 0x0A) < 0) return -1;
    }
    return 0;
}

static int mpr121_read_touch_data(unsigned short *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "MPR121 read failed\n");
        return -1;
    }
    *touch_data = (unsigned short)((buf[1] << 8) | buf[0]);
    return 0;
}

static double calculate_frequency(unsigned short touch_data) {
    if (touch_data == 0) return 0.0;
    double log_freq = 10.0 + 9.0 * log10((double)touch_data);
    return 220.0 * pow(2.0, log_freq / 12.0);
}

static void log_frequency(double frequency) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f\n", ts, frequency);
    fclose(fp);
}

static void play_tone(double frequency, int duration_ms) {
    if (frequency <= 0.0) {
        gpioPWM(PWM_GPIO, 0);
        return;
    }
    int pwm_duty = (int)((double)PWM_RANGE * (1.0 + sin(2.0 * M_PI * frequency / 1000.0 * (double)duration_ms / 1000.0)));
    if (pwm_duty < 0) pwm_duty = 0;
    if (pwm_duty > PWM_RANGE) pwm_duty = PWM_RANGE;
    gpioPWM(PWM_GPIO, pwm_duty);
}

static void handle_client_message(const char *message) {
    char *secret_pos = strstr(message, SHARED_SECRET);
    if (!secret_pos) {
        fprintf(stderr, "Shared secret not found\n");
        return;
    }
    char *start = strstr(message, "MOTION_DETECTED:");
    if (!start) {
        fprintf(stderr, "Motion detected marker not found\n");
        return;
    }
    start += strlen("MOTION_DETECTED:");
    char *end = strstr(start, "\n");
    if (!end) end = strstr(start, "\r");
    if (!end) end = start + strlen(start);
    char freq_str[32];
    int len = end - start;
    if (len >= (int)sizeof(freq_str)) len = (int)sizeof(freq_str) - 1;
    strncpy(freq_str, start, len);
    freq_str[len] = '\0';
    char *endptr;
    double freq = strtod(freq_str, &endptr);
    if (*endptr != '\0') {
        fprintf(stderr, "Invalid frequency format\n");
        return;
    }
    printf("Playing tone at %.2f Hz\n", freq);
    play_tone(freq, PLAYBACK_DURATION_S * 1000);
    log_frequency(freq);
}

static void cleanup(void) {
    gpioPWM(PWM_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (client_fd >= 0) close(client_fd);
    if (server_fd >= 0) close(server_fd);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 init failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        cleanup();
        return 1;
    }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    while (running) {
        client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (running) perror("accept");
            continue;
        }
        printf("Client connected\n");

        char buffer[1024];
        int bytes = read(client_fd, buffer, sizeof(buffer) - 1);
        if (bytes > 0) {
            buffer[bytes] = '\0';
            printf("Received: %s", buffer);
            handle_client_message(buffer);
        } else {
            fprintf(stderr, "Client read error\n");
        }
        close(client_fd);
        client_fd = -1;
    }

    cleanup();
    return 0;
}

