#define OUT_X_L_M 0x08
#define LED_PIN 17
#define PWM_PERIOD_NS 10000000  // 10 ms period (100 Hz)
#define PWM_DUTY_MAX 1000000    // 1 ms duty cycle max

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg address error: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read block error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int init_magnetometer(int fd) {
    if (i2c_write_reg8(fd, CTRL_REG1_M, 0x18) < 0) {
        fprintf(stderr, "Failed to configure magnetometer\n");
        return -1;
    }
    return 0;
}

int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L_M, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrtf((float)(x * x + y * y + z * z));
}

int set_led_brightness(struct gpiod_line *line, float magnitude) {
    float normalized = magnitude / 100.0f;
    if (normalized < 0.0f) normalized = 0.0f;
    if (normalized > 1.0f) normalized = 1.0f;
    int duty_ns = (int)(PWM_DUTY_MAX * normalized);
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set LED high: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set LED low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_magnetometer(i2c_fd) < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "mag_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Magnetometer data acquisition started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t x, y, z;
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read magnetometer data, skipping sample\n");
            usleep(100000);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);
        if (set_led_brightness(led_line, magnitude) < 0) {
            fprintf(stderr, "Failed to set LED brightness\n");
        }

        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

