#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

#define NUM_SAMPLES 100
#define SAMPLE_DELAY_US 500000
#define I2C_BUS 1

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: reg=0x%02X, rc=%d\n", reg, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read error: reg=0x%02X, rc=%d, expected=%u\n", reg, rc, len);
        return -1;
    }
    return 0;
}

static int init_hmc5883l(void) {
    if (write_reg(HMC5883L_CONFIG_A, 0x70) < 0) return -1;
    if (write_reg(HMC5883L_CONFIG_B, 0x20) < 0) return -1;
    if (write_reg(HMC5883L_MODE, 0x00) < 0) return -1;
    return 0;
}

static int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (read_block(HMC5883L_DATA_X_MSB, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void calculate_offsets(int16_t *x, int16_t *y, int16_t *z, int num_samples) {
    double sx = 0.0, sy = 0.0, sz = 0.0;
    int valid = 0;
    for (int i = 0; i < num_samples; i++) {
        if (read_magnetometer(x, y, z) == 0) {
            sx += (double)*x; sy += (double)*y; sz += (double)*z;
            valid++;
        }
        gpioDelay(10000);
    }
    if (valid == 0) {
        fprintf(stderr, "Warning: no valid magnetometer readings during offset calculation\n");
        *x = 0; *y = 0; *z = 0;
        return;
    }
    sx /= valid; sy /= valid; sz /= valid;
    *x = (int16_t)sx; *y = (int16_t)sy; *z = (int16_t)sz;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, HMC5883L_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int16_t x_offset = 0, y_offset = 0, z_offset = 0;
    calculate_offsets(&x_offset, &y_offset, &z_offset, NUM_SAMPLES);
    printf("Calculated offsets: X=%d, Y=%d, Z=%d\n", x_offset, y_offset, z_offset);

    while (running) {
        int16_t x, y, z;
        if (read_magnetometer(&x, &y, &z) == 0) {
            int16_t x_corr = x - x_offset;
            int16_t y_corr = y - y_offset;
            int16_t z_corr = z - z_offset;
            printf("X: %d, Y: %d, Z: %d\n", x_corr, y_corr, z_corr);
        } else {
            fprintf(stderr, "Failed to read magnetometer data\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

