/*
 * LSM303D accelerometer interrupt monitor for Raspberry Pi Zero W
 * Uses Linux i2c-dev (no wiringPi) and libgpiod for GPIO interrupt.
 *
 * Wiring:
 *   LSM303D SDA  -> GPIO2  (I2C1 SDA, physical pin 3)
 *   LSM303D SCL  -> GPIO3  (I2C1 SCL, physical pin 5)
 *   LSM303D VDD  -> 3.3 V
 *   LSM303D GND  -> GND
 *   LSM303D INT1 -> GPIO23 (physical pin 16) with pull-up
 *
 * Build: gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- LSM303D constants ---- */
#define LSM303D_ADDR        0x1D
#define WHO_AM_I            0x0F
#define WHO_AM_I_VAL        0x49
#define CTRL_REG1           0x20
#define CTRL_REG4           0x23
#define INT1_CFG            0x30
#define INT1_THS            0x32
#define INT1_DURATION       0x33
#define INT1_SRC            0x31
#define INT1_CFG_MASK       0x3F
#define INT1_SRC_MASK       0x3F
#define OUT_X_L_A           0x28
#define OUT_X_L_A_AUTOINC   0x80

/* ---- GPIO / libgpiod constants ---- */
#define GPIO_CHIP           "gpiochip0"
#define GPIO_LINE_OFFSET    23          /* BCM 23, physical pin 16 */
#define I2C_BUS             "/dev/i2c-1"

/* ---- Application constants ---- */
#define BUFFER_SIZE         64
#define SAMPLE_PERIOD_US    10000       /* 10 ms -> ~100 Hz polling */
#define THRESHOLD_MG        2000
#define THRESHOLD_REG       (THRESHOLD_MG / 16)  /* 125 */
#define INT1_DURATION_REG   0x00        /* immediate */

