{
    if (i2c_smbus_read_i2c_block_data(fd, reg, len, buf) < 0) {
        fprintf(stderr, "I2C block read 0x%02X (%d bytes) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- LSM303D init ---- */
static int lsm303d_init(int fd)
{
    uint8_t who;

    if (i2c_read_byte(fd, WHO_AM_I, &who) < 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: 50 Hz ODR, all axes enabled -> 0x57 */
    if (i2c_write_byte(fd, CTRL_REG1, 0x57) < 0)
        return -1;

    /* CTRL_REG4: +/-2g full-scale, high-resolution off -> 0x00 */
    if (i2c_write_byte(fd, CTRL_REG4, 0x00) < 0)
        return -1;

    /* INT1_CFG: enable all axes, high threshold, active high -> 0x2A */
    if (i2c_write_byte(fd, INT1_CFG, 0x2A) < 0)
        return -1;

    /* INT1_THS: threshold in mg units (16 mg/LSB) */
    if (i2c_write_byte(fd, INT1_THS, THRESHOLD_REG) < 0)
        return -1;

