    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE_OFFSET);
    if (!g_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_rising_edge_events(g_line, "lsm303d-int1") < 0) {
