    while (g_running) {
        accel_sample_t sample;

        if (read_acceleration(g_i2c_fd, &sample) < 0) {
            /* I2C read warning already printed; skip this sample */
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        cb_push(&cb, sample);

        /* Check for rising edge on INT1 */
        int ev = gpiod_line_event_wait(g_line, NULL);  /* block */
        if (ev < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "gpiod_line_event_wait error: %s\n", strerror(errno));
            break;
        }
        if (ev > 0) {
            int1_active = 1;
        }

        if (int1_active) {
            int1_active = 0;
            if (gpiod_line_event_read(g_line, NULL) < 0) {
                if (errno != EINTR)
                    fprintf(stderr, "gpiod_line_event_read error: %s\n",
                            strerror(errno));
            }
            printf("\n--- Interrupt triggered! ---\n");
            cb_dump(&cb);
            printf("-----------------------\n");
            fflush(stdout);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nExiting...\n");
    cleanup();
    return EXIT_SUCCESS;
