#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DELAY_MS 500
#define CONSUMER "solenoid-actuator"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = {
        .tv_sec = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    while (nanosleep(&ts, &ts) == -1) {
        /* Retry on EINTR */
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SOLENOID_1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line(solenoid 1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SOLENOID_2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line(solenoid 2)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(solenoid 1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(solenoid 2)");
        goto cleanup;
    }

    /* Ensure both solenoids start de-energized */
    if (gpiod_line_set_value(line1, 0) < 0) {
        perror("gpiod_line_set_value(solenoid 1, 0)");
        goto cleanup;
    }
    if (gpiod_line_set_value(line2, 0) < 0) {
        perror("gpiod_line_set_value(solenoid 2, 0)");
        goto cleanup;
    }

    while (running) {
        /* Energize solenoid 1 */
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value(solenoid 1, 1)");
            goto cleanup;
        }
        sleep_ms(DELAY_MS);
        if (!running) break;

        /* De-energize solenoid 1, energize solenoid 2 */
        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value(solenoid 1, 0)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(solenoid 2, 1)");
            goto cleanup;
        }
        sleep_ms(DELAY_MS);
        if (!running) break;

        /* De-energize solenoid 2 */
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value(solenoid 2, 0)");
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure both solenoids are de-energized on exit */
    if (line1) gpiod_line_set_value(line1, 0);
    if (line2) gpiod_line_set_value(line2, 0);
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

