#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define SERIAL_PORT1 "/dev/serial0"
#define SERIAL_PORT2 "/dev/serial1"
#define EXPECTED_CODE "123456"
#define UNLOCK_DURATION_MS 2000
#define POLL_INTERVAL_US 10000
#define TIMEOUT_SEC 5

static volatile sig_atomic_t running = 1;
static int serial_handle1 = -1;
static int serial_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (serial_handle1 >= 0) {
        serClose(serial_handle1);
        serial_handle1 = -1;
    }
    if (serial_handle2 >= 0) {
        serClose(serial_handle2);
        serial_handle2 = -1;
    }
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);
    gpioTerminate();
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);
    if (gpioWrite(LOCK1_GPIO, 0) != 0 || gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to set lock GPIOs LOW\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int initialize_serial(const char *port) {
    int handle = serOpen(port, 9600, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: failed to open serial port %s (pigpio error %d)\n", port, handle);
        return -1;
    }
    return handle;
}

static int read_code(int handle, char *code, int max_len) {
    char buf[32];
    int idx = 0;
    time_t start = time(NULL);

    while (running && (time(NULL) - start) < TIMEOUT_SEC) {
        int avail = serDataAvailable(handle);
        if (avail > 0) {
            int n = serRead(handle, buf, sizeof(buf) - 1);
            if (n > 0) {
                buf[n] = '\0';
                for (int i = 0; i < n; i++) {
                    if (buf[i] >= '0' && buf[i] <= '9') {
                        if (idx < max_len - 1) {
                            code[idx++] = buf[i];
                        }
                    } else {
                        idx = 0;
                    }
                }
                if (idx == max_len) {
                    code[idx] = '\0';
                    return 0;
                }
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }
    return -1;
}

static int are_codes_equal(const char *a, const char *b) {
    if (strlen(a) != strlen(b)) return 0;
    size_t len = strlen(a);
    for (size_t i = 0; i < len; i++) {
        if (a[i] != b[i]) return 0;
    }
    return 1;
}

static int unlock_doors(void) {
    if (gpioWrite(LOCK1_GPIO, 1) != 0 || gpioWrite(LOCK2_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to unlock doors (GPIO write failed)\n");
        return -1;
    }
    gpioDelay(UNLOCK_DURATION_MS * 1000);
    if (gpioWrite(LOCK1_GPIO, 0) != 0 || gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to re-lock doors (GPIO write failed)\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() != 0) return 1;

    serial_handle1 = initialize_serial(SERIAL_PORT1);
    if (serial_handle1 < 0) { cleanup(); return 1; }

    serial_handle2 = initialize_serial(SERIAL_PORT2);
    if (serial_handle2 < 0) { cleanup(); return 1; }

    char code1[7] = {0};
    char code2[7] = {0};

    while (running) {
        if (read_code(serial_handle1, code1, sizeof(code1)) != 0) {
            fprintf(stderr, "Error: timeout reading code from %s\n", SERIAL_PORT1);
            break;
        }
        if (read_code(serial_handle2, code2, sizeof(code2)) != 0) {
            fprintf(stderr, "Error: timeout reading code from %s\n", SERIAL_PORT2);
            break;
        }

        if (are_codes_equal(code1, code2) && are_codes_equal(code1, EXPECTED_CODE)) {
            printf("Codes match expected code '%s'. Unlocking doors.\n", EXPECTED_CODE);
            if (unlock_doors() != 0) {
                fprintf(stderr, "Error: door unlock sequence failed\n");
                break;
            }
        } else {
            fprintf(stderr, "Codes do not match or do not match expected code.\n");
        }
    }

    cleanup();
    return 0;
}

