#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip0"
#define PIR_PIN             4
#define RELAY_PIN           17
#define RELAY_ON_TIME_SEC   1
#define POLL_INTERVAL_MS    50
#define STUCK_TIMEOUT_SEC   10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(int priority, const char *msg)
{
    syslog(priority, "%s", msg);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open %s: %s", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay line %d: %s", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(pir_line, "door_strike_pir") < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "door_strike_relay", 0) < 0) {
        syslog(LOG_ERR, "Failed to request relay line as output: %s", strerror(errno));
        goto cleanup;
    }

    log_event(LOG_INFO, "Door strike system started");

    int relay_state = 0;
    time_t last_motion_time = 0;
    int stuck = 0;

    while (g_running) {
        int pir_val = gpiod_line_get_value(pir_line);
        if (pir_val < 0) {
            syslog(LOG_ERR, "Failed to read PIR line: %s", strerror(errno));
            break;
        }

        if (pir_val == 1) {
            if (last_motion_time == 0) {
                last_motion_time = time(NULL);
            }

            if (!relay_state) {
                if (gpiod_line_set_value(relay_line, 1) < 0) {
                    syslog(LOG_ERR, "Failed to energize relay: %s", strerror(errno));
                    break;
                }
                relay_state = 1;
                log_event(LOG_INFO, "Motion detected, relay ON");
            }

            stuck = 0;
        } else {
            if (relay_state) {
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    syslog(LOG_ERR, "Failed to de-energize relay: %s", strerror(errno));
                    break;
                }
                relay_state = 0;
                log_event(LOG_INFO, "Motion stopped, relay OFF");
            }

            if (last_motion_time != 0) {
                time_t now = time(NULL);
                if (difftime(now, last_motion_time) > STUCK_TIMEOUT_SEC) {
                    if (!stuck) {
                        log_event(LOG_WARNING, "PIR stuck HIGH for >10s, relay de-energized");
                        stuck = 1;
                    }
                }
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    if (relay_state) {
        gpiod_line_set_value(relay_line, 0);
    }

    log_event(LOG_INFO, "Door strike system shutting down");
    ret = EXIT_SUCCESS;

cleanup:
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

