#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

#define RELAY1 4
#define RELAY2 17
#define RELAY3 27
#define RELAY4 22

#define ACTIVATION_DURATION 300
#define PAUSE_DURATION 60
#define TIMER_INTERVAL 60

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t timer_fired = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void timer_callback(void *user_data) {
    (void)user_data;
    timer_fired = 1;
}

static void log_relay_state(int gpio, int state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_buf[32];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", tm_info);
    syslog(LOG_INFO, "Relay on GPIO %d set to %s at %s",
           gpio, state ? "OFF" : "ON", time_buf);
}

static void deactivate_all_relays(void) {
    int relays[] = {RELAY1, RELAY2, RELAY3, RELAY4};
    for (size_t i = 0; i < sizeof(relays) / sizeof(relays[0]); ++i) {
        if (gpioWrite(relays[i], 1) != 0) {
            syslog(LOG_ERR, "Failed to deactivate relay on GPIO %d", relays[i]);
        }
    }
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
