#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define MPU6050_ADDR        0x68
#define I2C_BUS             "/dev/i2c-1"
#define SYSFS_PATH          "/sys/kernel/mpu6050_accel/latest"
#define BUFFER_SIZE         100
#define SAMPLE_RATE_HZ      100
#define SAMPLE_PERIOD_NS    (1000000000L / SAMPLE_RATE_HZ)

#define REG_PWR_MGMT_1      0x6B
#define REG_ACCEL_CONFIG    0x1C
#define REG_ACCEL_XOUT_H    0x3B

#define ACCEL_SCALE         16384.0f

typedef struct {
    float x, y, z;
} AccelData;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_sysfs_file = NULL;
static AccelData g_buffer[BUFFER_SIZE];
static int g_buf_head = 0;
static int g_buf_count = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read burst from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd) {
    if (i2c_write_reg8(fd, REG_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, REG_ACCEL_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_accel(int fd, AccelData *out) {
    uint8_t raw[6];
    if (i2c_read_burst(fd, REG_ACCEL_XOUT_H, raw, 6) < 0) return -1;
    int16_t x = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t y = (int16_t)((raw[2] << 8) | raw[3]);
    int16_t z = (int16_t)((raw[4] << 8) | raw[5]);
    out->x = (float)x / ACCEL_SCALE;
    out->y = (float)y / ACCEL_SCALE;
    out->z = (float)z / ACCEL_SCALE;
    return 0;
}

static void timer_handler(int sig, siginfo_t *si, void *uc) {
    (void)sig; (void)si; (void)uc;
    AccelData d;
    if (read_accel(g_i2c_fd, &d) == 0) {
        g_buffer[g_buf_head] = d;
        g_buf_head = (g_buf_head + 1) % BUFFER_SIZE;
        if (g_buf_count < BUFFER_SIZE) g_buf_count++;
    }
}

static int sysfs_init(void) {
    g_sysfs_file = fopen(SYSFS_PATH, "w");
    if (!g_sysfs_file) {
        fprintf(stderr, "Failed to open sysfs %s: %s\n", SYSFS_PATH, strerror(errno));
        return -1;
    }
    return 0;
}

static void sysfs_write(const AccelData *d) {
    if (!g_sysfs_file) return;
    fprintf(g_sysfs_file, "%.4f,%.4f,%.4f\n", d->x, d->y, d->z);
    fflush(g_sysfs_file);
}

static void cleanup(void) {
    if (g_sysfs_file) { fclose(g_sysfs_file); g_sysfs_file = NULL; }
    if (g_i2c_fd >= 0) { close(g_i2c_fd); g_i2c_fd = -1; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (mpu6050_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 init failed (sensor absent or bus error)\n");
        cleanup();
        return 1;
    }

    if (sysfs_init() < 0) {
        cleanup();
        return 1;
    }

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = NULL;
    if (timer_create(CLOCK_MONOTONIC, &sev, &g_timerid) < 0) {
        fprintf(stderr, "timer_create failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct itimerspec its;
    memset(&its, 0, sizeof(its));
    its.it_interval.tv_nsec = SAMPLE_PERIOD_NS;
    its.it_value.tv_nsec = SAMPLE_PERIOD_NS;
    if (timer_settime(g_timerid, 0, &its, NULL) < 0) {
        fprintf(stderr, "timer_settime failed: %s\n", strerror(errno));
        timer_delete(g_timerid);
        cleanup();
        return 1;
    }

    printf("MPU6050 running at %d Hz. Press Ctrl+C to stop.\n", SAMPLE_RATE_HZ);

    while (g_running) {
        pause();
    }

    timer_delete(g_timerid);
    cleanup();
    printf("\nExiting cleanly.\n");
    return 0;
}

