#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CHIP_NAME "gpiochip0"

// BCM GPIO pins for relays
const int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};
const int prime_intervals[NUM_RELAYS] = {2, 3, 5, 7};

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    struct timespec last_toggle[NUM_RELAYS];
    int ret = EXIT_FAILURE;

    // Initialize lines to NULL for safe cleanup
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = NULL;
    }

    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    // Request each relay line as output, initially low
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "smart-lighting", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }

        // Initialize last_toggle to current time
        if (clock_gettime(CLOCK_MONOTONIC, &last_toggle[i]) == -1) {
            fprintf(stderr, "Failed to get initial time for relay %d: %s\n", i, strerror(errno));
            goto cleanup;
        }
    }

    printf("Smart lighting system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            struct timespec now;
            if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
                fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
                goto cleanup;
            }

            double elapsed = (now.tv_sec - last_toggle[i].tv_sec) +
                             (now.tv_nsec - last_toggle[i].tv_nsec) / 1e9;

            if (elapsed >= prime_intervals[i]) {
                int current_value = gpiod_line_get_value(lines[i]);
                if (current_value < 0) {
                    fprintf(stderr, "Failed to read GPIO line %d: %s\n", relay_pins[i], strerror(errno));
                    goto cleanup;
                }

                if (gpiod_line_set_value(lines[i], !current_value) < 0) {
                    fprintf(stderr, "Failed to set GPIO line %d: %s\n", relay_pins[i], strerror(errno));
                    goto cleanup;
                }

                last_toggle[i] = now;
                printf("Relay %d toggled to %d\n", i, !current_value);
            }
        }
        // Sleep for a short interval to prevent busy-waiting
        struct timespec sleep_time = {0, 10000000}; // 10ms
        nanosleep(&sleep_time, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    // Turn off all relays and release lines
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Smart lighting system stopped.\n");
    return ret;
}

