#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define ALARM_DURATION_MS 3000
#define POLL_INTERVAL_MS 100
#define LOG_FILE "alarm_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_alarm_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Alarm triggered\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_relay(int duration_ms) {
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        fprintf(stderr, "Error activating relay on GPIO%d\n", RELAY_PIN);
        return -1;
    }

    gpioDelay(duration_ms * 1000);

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error deactivating relay on GPIO%d\n", RELAY_PIN);
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error initializing relay to OFF state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound-activated relay alarm started. Press Ctrl+C to exit.\n");

    int last_state = gpioRead(SOUND_SENSOR_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Error reading initial sound sensor state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_state = gpioRead(SOUND_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error reading sound sensor on GPIO%d\n", SOUND_SENSOR_PIN);
            break;
        }

        if (current_state == 1 && last_state == 0) {
            printf("Sound detected! Activating relay for %d ms.\n", ALARM_DURATION_MS);
            if (activate_relay(ALARM_DURATION_MS) != 0) {
                fprintf(stderr, "Relay activation failed\n");
            }
            if (log_alarm_event() != 0) {
                fprintf(stderr, "Failed to log alarm event\n");
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

