#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define MPU6050_WHO_AM_I 0x75
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_XOUT_H 0x43

// Sensitivity scale factor for default +/- 250 degrees/sec range
#define GYRO_SCALE 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold
#define ANGULAR_VELOCITY_THRESHOLD 50.0

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
static int i2c_fd = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int init_mpu6050(int fd);
int read_gyro_data(int fd, gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
gyro_data_t get_latest_data(circular_buffer_t *buffer);
float calculate_angular_velocity(gyro_data_t data);
void check_threshold(float angular_velocity);
void signal_handler(int signal);
void cleanup();

// Function to write a byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from an I2C register
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading %d bytes from register 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the MPU-6050
int init_mpu6050(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_bytes(fd, MPU6050_WHO_AM_I, &who_am_i, 1) < 0) {
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0x68\n", who_am_i);
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep bit)
    if (i2c_write_byte(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        return -1;
    }
    usleep(100000); // Wait 100ms for the sensor to stabilize
    return 0;
}

// Function to read gyroscope data from the MPU-6050
int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_bytes(fd, MPU6050_GYRO_XOUT_H, buf, 6) < 0) {
        return -1;
    }

    int16_t raw_x = (buf[0] << 8) | buf[1];
    int16_t raw_y = (buf[2] << 8) | buf[3];
    int16_t raw_z = (buf[4] << 8) | buf[5];

    data->x = (float)raw_x / GYRO_SCALE;
    data->y = (float)raw_y / GYRO_SCALE;
    data->z = (float)raw_z / GYRO_SCALE;

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
}

// Function to get the latest data from the circular buffer
gyro_data_t get_latest_data(circular_buffer_t *buffer) {
    gyro_data_t data = {0.0, 0.0, 0.0};
    if (buffer->count > 0) {
        data = buffer->data[(buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE];
    }
    return data;
}

// Function to calculate the angular velocity from the gyroscope data
float calculate_angular_velocity(gyro_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Function to check if the angular velocity exceeds the threshold
void check_threshold(float angular_velocity) {
    if (angular_velocity > ANGULAR_VELOCITY_THRESHOLD) {
        printf("Angular velocity threshold exceeded! Velocity: %.2f\n", angular_velocity);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup function to close I2C and exit
void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    printf("\nCleanup complete. Exiting.\n");
}

int main() {
    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing MPU-6050\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("MPU-6050 data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gyro_data_t gyro_data;
        if (read_gyro_data(i2c_fd, &gyro_data) < 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
            usleep(100000);
            continue;
        }

        add_to_buffer(&gyro_buffer, gyro_data);
        float angular_velocity = calculate_angular_velocity(gyro_data);
        check_threshold(angular_velocity);

        usleep(10000); // 10ms delay
    }

    cleanup();
    return 0;
}

