// Function to read gyroscope data from the MPU-6050
int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_bytes(fd, MPU6050_GYRO_XOUT_H, buf, 6) < 0) {
        return -1;
    }

    int16_t raw_x = (buf[0] << 8) | buf[1];
    int16_t raw_y = (buf[2] << 8) | buf[3];
    int16_t raw_z = (buf[4] << 8) | buf[5];

    data->x = (float)raw_x / GYRO_SCALE;
    data->y = (float)raw_y / GYRO_SCALE;
    data->z = (float)raw_z / GYRO_SCALE;

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
}

// Function to get the latest data from the circular buffer
gyro_data_t get_latest_data(circular_buffer_t *buffer) {
    gyro_data_t data = {0.0, 0.0, 0.0};
    if (buffer->count > 0) {
        data = buffer->data[(buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE];
    }
    return data;
}

// Function to calculate the angular velocity from the gyroscope data
float calculate_angular_velocity(gyro_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Function to check if the angular velocity exceeds the threshold
void check_threshold(float angular_velocity) {
    if (angular_velocity > ANGULAR_VELOCITY_THRESHOLD) {
        printf("Angular velocity threshold exceeded! Velocity: %.2f\n", angular_velocity);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup function to close I2C and exit
void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    printf("\nCleanup complete. Exiting.\n");
}

int main() {
    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing MPU-6050\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("MPU-6050 data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gyro_data_t gyro_data;
        if (read_gyro_data(i2c_fd, &gyro_data) < 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
            usleep(100000);
            continue;
        }

        add_to_buffer(&gyro_buffer, gyro_data);
        float angular_velocity = calculate_angular_velocity(gyro_data);
        check_threshold(angular_velocity);

        usleep(10000); // 10ms delay
    }

    cleanup();
    return 0;
}

