/*
 * MH-Z19B CO2 monitor for Raspberry Pi 3 Model B+
 * UART: /dev/serial0 (TXD=GPIO14, RXD=GPIO15), 9600 baud
 * Library: pigpio (userspace, no manual GPIO config)
 * Build: gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE    "/dev/serial0"
#define BAUD_RATE      9600
#define LOG_FILE       "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define READ_INTERVAL  5          /* seconds between readings */
#define READ_TIMEOUT   1000       /* ms to wait for 9-byte response */
#define RETRY_DELAY    100        /* ms between read retries */
#define READ_CMD_LEN   9
#define READ_RESP_LEN  9
#define MAX_RETRIES    10

static const uint8_t READ_CMD[READ_CMD_LEN] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};

static int  uart_handle = -1;
static FILE *log_file   = NULL;
static FILE *err_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    if (!err_file) return;

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    fprintf(err_file, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000L, msg);
    fflush(err_file);
}

/* ------------------------------------------------------------------ */
/* UART helpers                                                        */
/* ------------------------------------------------------------------ */
static int init_uart(void)
{
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "serOpen failed: %d\n", uart_handle);
        return -1;
    }
    return 0;
}

static int send_read_command(void)
{
    if (serWrite(uart_handle, (char *)READ_CMD, READ_CMD_LEN) != READ_CMD_LEN) {
        log_error("Failed to send read command");
        return -1;
    }
    return 0;
}

/*
 * Read exactly READ_RESP_LEN bytes from the MH-Z19B.
 * Returns 0 on success, -1 on timeout, -2 on checksum error.
 */
static int read_response(uint8_t *buf)
{
    int total = 0;
    int elapsed = 0;

    while (total < READ_RESP_LEN) {
        int avail = serDataAvailable(uart_handle);
        if (avail < 0) {
            log_error("serDataAvailable failed");
            return -1;
        }
        if (avail > 0) {
            int n = serRead(uart_handle, (char *)(buf + total), READ_RESP_LEN - total);
            if (n < 0) {
                log_error("serRead failed");
                return -1;
            }
            total += n;
        } else {
            gpioDelay(RETRY_DELAY * 1000);   /* pigpio microseconds */
            elapsed += RETRY_DELAY;
            if (elapsed >= READ_TIMEOUT) {
                log_error("Timeout waiting for sensor response");
                return -1;
            }
        }
    }
    return 0;
}

static int validate_checksum(const uint8_t *buf)
{
    uint8_t calc = 0;
    for (int i = 1; i < 8; i++)
        calc += buf[i];
    calc = (uint8_t)(~calc + 1);
    return (calc == buf[8]) ? 0 : -1;
}

static int read_co2_ppm(int *ppm_out)
{
    if (send_read_command() != 0)
        return -1;

    uint8_t resp[READ_RESP_LEN];
    int rc = read_response(resp);
    if (rc != 0)
        return rc;

    if (validate_checksum(resp) != 0) {
        log_error("Checksum mismatch on sensor response");
        return -2;
    }

    *ppm_out = (resp[2] << 8) | resp[3];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int init_log(void)
{
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        return -1;
    }
    err_file = fopen(ERROR_LOG_FILE, "a");
    if (!err_file) {
        perror("fopen err");
        fclose(log_file);
        log_file = NULL;
        return -1;
    }
    return 0;
}

static void log_data(int ppm, int error)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

    fprintf(log_file, "{\"timestamp\":\"%s.%03ld\",\"co2_ppm\":%d,\"error\":%d}\n",
            tbuf, ts.tv_nsec / 1000000L, ppm, error);
    fflush(log_file);

    printf("{\"timestamp\":\"%s.%03ld\",\"co2_ppm\":%d,\"error\":%d}\n",
           tbuf, ts.tv_nsec / 1000000L, ppm, error);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (err_file) {
        fclose(err_file);
        err_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_uart() != 0 || init_log() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CO2 monitor started. Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (!terminate) {
        int ppm = 0;
        int rc = read_co2_ppm(&ppm);

        if (rc == 0) {
            log_data(ppm, 0);
        } else {
            log_data(0, rc);
        }

        /* Sleep READ_INTERVAL seconds, but wake early on signal */
        for (int i = 0; i < READ_INTERVAL && !terminate; i++)
            sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

