#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA 0x03

#define GPIO_PIN 17
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static double heading_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_hmc5883l(void) {
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing CONFIG_A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing CONFIG_B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing MODE\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer(double *x, double *y, double *z) {
    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA, data, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_z = (int16_t)((data[2] << 8) | data[3]);
    int16_t raw_y = (int16_t)((data[4] << 8) | data[5]);
    *x = (double)raw_x;
    *y = (double)raw_y;
    *z = (double)raw_z;
    return 0;
}

static double calculate_heading(double x, double y) {
    double heading = atan2(y, x) * 180.0 / M_PI;
    if (heading < 0) heading += 360.0;
    return heading;
}

static void update_gpio(double heading) {
    double deviation = fabs(heading - TARGET_HEADING);
    if (deviation > 180.0) deviation = 360.0 - deviation;
    if (deviation > DEVIATION_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1);
    } else {
        gpioWrite(GPIO_PIN, 0);
    }
}

static void add_to_buffer(double heading) {
    heading_buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        double x, y, z;
        if (read_magnetometer(&x, &y, &z) == 0) {
            double heading = calculate_heading(x, y);
            double compensated_heading = heading - 100.0 + 50.0;
            if (compensated_heading < 0) compensated_heading += 360.0;
            if (compensated_heading >= 360.0) compensated_heading -= 360.0;
            update_gpio(compensated_heading);
            add_to_buffer(compensated_heading);
        } else {
            fprintf(stderr, "Read failed, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

