#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_RELAY_PIN    17
#define GREEN_RELAY_PIN  27
#define BLUE_RELAY_PIN   22
#define BH1750_ADDR      0x23
#define I2C_BUS          "/dev/i2c-1"
#define LOG_FILE         "lighting_log.txt"
#define BH1750_PWR_ON    0x01
#define BH1750_CONT_HRES 0x10
#define CONV_TIME_MS     120
#define POLL_MS          1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_PWR_ON) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_CONT_HRES) < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void set_relay(struct gpiod_line *line, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        fprintf(stderr, "Failed to set relay: %s\n", strerror(errno));
    }
}

static void log_data(FILE *fp, float lux, int r, int g, int b) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Lux: %.2f, Red: %d, Green: %d, Blue: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux, r, g, b);
    fflush(fp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int i2c_fd = -1;
    FILE *log_fp = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        goto cleanup;
    }

    red_line = gpiod_chip_get_line(chip, RED_RELAY_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_RELAY_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_RELAY_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(red_line, "smart_lighting", 0) < 0 ||
        gpiod_line_request_output(green_line, "smart_lighting", 0) < 0 ||
        gpiod_line_request_output(blue_line, "smart_lighting", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output: %s\n", strerror(errno));
        goto cleanup;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        goto cleanup;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed (sensor absent or bus error)\n");
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        int r = 0, g = 0, b = 0;

        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
            usleep(POLL_MS * 1000);
            continue;
        }

        if (lux < 50.0f) {
            r = 1; g = 0; b = 0;
        } else if (lux < 150.0f) {
            r = 0; g = 1; b = 0;
        } else if (lux < 300.0f) {
            r = 0; g = 0; b = 1;
        } else {
            r = 1; g = 1; b = 1;
        }

        set_relay(red_line, r);
        set_relay(green_line, g);
        set_relay(blue_line, b);

        log_data(log_fp, lux, r, g, b);

        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = 0;

cleanup:
    if (red_line) gpiod_line_set_value(red_line, 0);
    if (green_line) gpiod_line_set_value(green_line, 0);
    if (blue_line) gpiod_line_set_value(blue_line, 0);
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_fp) fclose(log_fp);
    return ret;
}

