#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

#define DISTANCE_THRESHOLD 50
#define MIN_DISTANCE 10
#define MAX_DISTANCE 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_set_pwm(unsigned gpio, unsigned freq, unsigned range, unsigned duty) {
    if (gpioSetPWMfrequency(gpio, freq) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%u, %u) failed\n", gpio, freq);
        return -1;
    }
    if (gpioSetPWMrange(gpio, range) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%u, %u) failed\n", gpio, range);
        return -1;
    }
    if (gpioPWM(gpio, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", gpio, duty);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static void motor_stop(void) {
    safe_write(MOTOR_A_IN1, 0);
    safe_write(MOTOR_A_IN2, 0);
    safe_write(MOTOR_B_IN3, 0);
    safe_write(MOTOR_B_IN4, 0);
}

static int motor_control(int distance_a, int distance_b) {
    int duty_a = 0, duty_b = 0;

    if (distance_a < MIN_DISTANCE) distance_a = MIN_DISTANCE;
    if (distance_a > MAX_DISTANCE) distance_a = MAX_DISTANCE;
    if (distance_b < MIN_DISTANCE) distance_b = MIN_DISTANCE;
    if (distance_b > MAX_DISTANCE) distance_b = MAX_DISTANCE;

    duty_a = (MAX_DISTANCE - distance_a) * (PWM_RANGE / (MAX_DISTANCE - MIN_DISTANCE));
    duty_b = (MAX_DISTANCE - distance_b) * (PWM_RANGE / (MAX_DISTANCE - MIN_DISTANCE));

    if (duty_a > PWM_RANGE) duty_a = PWM_RANGE;
    if (duty_b > PWM_RANGE) duty_b = PWM_RANGE;

    if (distance_a < DISTANCE_THRESHOLD) {
        if (safe_write(MOTOR_A_IN1, 1) != 0) return -1;
        if (safe_write(MOTOR_A_IN2, 0) != 0) return -1;
        if (safe_set_pwm(MOTOR_A_IN2, PWM_FREQUENCY, PWM_RANGE, duty_a) != 0) return -1;
    } else {
        if (safe_write(MOTOR_A_IN1, 0) != 0) return -1;
        if (safe_write(MOTOR_A_IN2, 1) != 0) return -1;
        if (safe_set_pwm(MOTOR_A_IN2, PWM_FREQUENCY, PWM_RANGE, duty_a) != 0) return -1;
    }

    if (distance_b < DISTANCE_THRESHOLD) {
        if (safe_write(MOTOR_B_IN3, 0) != 0) return -1;
        if (safe_write(MOTOR_B_IN4, 1) != 0) return -1;
        if (safe_set_pwm(MOTOR_B_IN4, PWM_FREQUENCY, PWM_RANGE, duty_b) != 0) return -1;
    } else {
        if (safe_write(MOTOR_B_IN3, 1) != 0) return -1;
        if (safe_write(MOTOR_B_IN4, 0) != 0) return -1;
        if (safe_set_pwm(MOTOR_B_IN4, PWM_FREQUENCY, PWM_RANGE, duty_b) != 0) return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(MOTOR_A_IN1, PI_OUTPUT) != 0 ||
        safe_set_mode(MOTOR_A_IN2, PI_OUTPUT) != 0 ||
        safe_set_mode(MOTOR_B_IN3, PI_OUTPUT) != 0 ||
        safe_set_mode(MOTOR_B_IN4, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        motor_stop();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int distance_a = 50;
    int distance_b = 60;

    while (running) {
        if (motor_control(distance_a, distance_b) != 0) {
            fprintf(stderr, "Error: motor control failed\n");
            break;
        }
        usleep(100000);
    }

    motor_stop();
    gpioTerminate();
    return EXIT_SUCCESS;
}

