#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define FADE_DURATION 1800
#define SCHEDULE_FILE "lighting_schedule.txt"

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(const char *filename, int schedule[][3]) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    int count = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) && count < 100) {
        int h, m, s, r, v;
        if (sscanf(line, "%d:%d:%d,%d,%d", &h, &m, &s, &r, &v) == 5) {
            if (r < 1 || r > NUM_RELAYS || (v != 0 && v != 1)) {
                fprintf(stderr, "Invalid schedule entry: %s", line);
                continue;
            }
            schedule[count][0] = h;
            schedule[count][1] = m;
            schedule[count][2] = s;
            schedule[count][3] = r;
            schedule[count][4] = v;
            count++;
        } else {
            fprintf(stderr, "Invalid format in schedule file: %s", line);
        }
    }
    fclose(fp);
    return count;
}

static int set_relay(int pin, int state) {
    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", pin);
        return -1;
    }
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int fade_relay(int pin, int target) {
    int current = gpioGetPWMdutycycle(pin);
    if (current < 0) current = 0;

    int step = (target - current) / (FADE_DURATION / 10);
    if (step == 0) return 0;

    for (int i = 0; i < FADE_DURATION && running; i += 10) {
        current += step;
        if (current < 0) current = 0;
        if (current > 100) current = 100;
        if (gpioPWM(pin, current) < 0) {
            fprintf(stderr, "PWM write failed on GPIO %d\n", pin);
            return -1;
        }
        gpioDelay(100000);
    }
    return 0;
}

static void apply_schedule(int schedule[][5], int count, int current_time[3]) {
    for (int i = 0; i < count; i++) {
        if (schedule[i][0] == current_time[0] &&
            schedule[i][1] == current_time[1] &&
            schedule[i][2] == current_time[2]) {
            int pin = relay_pins[schedule[i][3] - 1];
            int target = schedule[i][4] * 100;
            if (fade_relay(pin, target) < 0) {
                fprintf(stderr, "Fade failed for relay %d\n", schedule[i][3]);
            }
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return 1;
        }
        gpioWrite(relay_pins[i], 0);
        gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY);
        gpioSetPWMrange(relay_pins[i], PWM_RANGE);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int schedule[100][5];
    int count = read_schedule(SCHEDULE_FILE, schedule);
    if (count < 0) {
        gpioTerminate();
        return 1;
    }

    while (running) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        if (!tm_info) {
            fprintf(stderr, "localtime failed\n");
            break;
        }
        int current_time[3] = {tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec};
        apply_schedule(schedule, count, current_time);
        gpioDelay(1000000);
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 0);
    }
    gpioTerminate();
    return 0;
}

