#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  30.0f
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000
#define LOOP_DELAY_US    60000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);
    return 0;
}

static float read_distance(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0;
    uint32_t timeout_tick = gpioTick() + ECHO_TIMEOUT_US;

    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Warning: HC-SR04 timeout waiting for echo start.\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Warning: HC-SR04 timeout waiting for echo end.\n");
            return -1.0f;
        }
    }
    uint32_t end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    float distance_cm = (float)pulse_width / 58.0f;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.1f, %.1f].\n",
                distance_cm, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }
    return distance_cm;
}

static int set_buzzer_frequency(float distance_cm) {
    if (distance_cm < 0.0f) {
        gpioPWM(BUZZER_PIN, 0);
        return -1;
    }

    float freq = (distance_cm - MIN_DISTANCE_CM) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM) *
                 (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) +
                 MIN_FREQUENCY_HZ;

    if (freq < MIN_FREQUENCY_HZ) freq = MIN_FREQUENCY_HZ;
    if (freq > MAX_FREQUENCY_HZ) freq = MAX_FREQUENCY_HZ;

    if (gpioSetPWMfrequency(BUZZER_PIN, (int)freq) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency to %.0f Hz.\n", freq);
        return -1;
    }
    gpioPWM(BUZZER_PIN, 128);
    return 0;
}

static void cleanup(void) {
    gpioPWM(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Theremin running. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = read_distance();
        if (distance < 0.0f) {
            fprintf(stderr, "Error: failed to read distance from HC-SR04.\n");
        } else {
            set_buzzer_frequency(distance);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

