#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define PWR_MGMT_1     0x6B
#define GYRO_XOUT_H    0x43
#define GYRO_SCALE     131.0f
#define LOG_FILE       "gyro_log.txt"
#define SAMPLE_MS      100

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int16_t combine(uint8_t hi, uint8_t lo) {
    return (int16_t)((uint16_t)hi << 8 | (uint16_t)lo);
}

static void log_data(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    } else {
        fprintf(fp, "(no-time),%.3f,%.3f,%.3f\n", x, y, z);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "MPU-6050 not responding at 0x%02X on %s\n", MPU6050_ADDR, I2C_BUS);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized at 0x%02X on %s. Logging to %s every %d ms.\n",
           MPU6050_ADDR, I2C_BUS, LOG_FILE, SAMPLE_MS);

    while (running) {
        uint8_t buf[6];
        if (i2c_read_burst(fd, GYRO_XOUT_H, buf, sizeof(buf)) < 0) {
            fprintf(stderr, "Gyro read error; continuing.\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        int16_t raw_x = combine(buf[0], buf[1]);
        int16_t raw_y = combine(buf[2], buf[3]);
        int16_t raw_z = combine(buf[4], buf[5]);

        float x = (float)raw_x / GYRO_SCALE;
        float y = (float)raw_y / GYRO_SCALE;
        float z = (float)raw_z / GYRO_SCALE;

        log_data(x, y, z);
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

