/*
 * Musical Doorbell for Raspberry Pi 4 Model B
 * Button: GPIO17 (active-low, internal pull-up)
 * Buzzer:  GPIO18 (hardware PWM0)
 *
 * Build: gcc -O2 -Wall -o doorbell doorbell.c -lpigpio -lrt
 * Run:   sudo ./doorbell
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define BUTTON_PIN      17
#define BUZZER_PIN      18
#define DEBOUNCE_US     50000   /* 50 ms */
#define PWM_DUTY_50     128     /* 50% of 255 */

/* Melody: frequency (Hz) and duration (ms) for each note */
static const int melody[][2] = {
    {262, 250}, {294, 250}, {330, 250}, {349, 250},
    {392, 250}, {440, 250}, {494, 250}, {523, 250},
    {587, 250}, {659, 250}, {698, 250}, {783, 250},
    {880, 250}, {988, 250}, {1046, 250}, {1175, 250},
    {1319, 250}, {1397, 250}, {1568, 250}, {1760, 250},
    {1976, 250}, {2093, 250}, {2349, 250}, {2637, 250},
    {2794, 250}, {3136, 250}, {3520, 250}, {3951, 250},
    {4186, 250}, {4698, 250}, {5274, 250}, {5588, 250},
    {6272, 250}, {7040, 250}, {7902, 250}, {8372, 250},
    {0, 0}          /* Sentinel: rest */
};

static volatile sig_atomic_t g_playing = 0;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISR: button press detected (active-low)                             */
/* ------------------------------------------------------------------ */
static void button_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    /* Only act on falling edge (button press) */
    if (level != 0)
        return;

    static uint32_t last_tick = 0;
    uint32_t elapsed = tick - last_tick;   /* pigpio tick is uint32_t */

    if (elapsed < DEBOUNCE_US)
        return;                            /* debounce */

    last_tick = tick;

    /* If already playing, stop immediately */
    if (g_playing) {
        g_playing = 0;
        gpioHardwarePWM(BUZZER_PIN, 0, 0);  /* stop PWM */
        return;
    }

    g_playing = 1;
    printf("Button pressed — playing melody\n");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Play one note via hardware PWM                                      */
/* ------------------------------------------------------------------ */
static void play_note(int freq, int duration_ms)
{
    if (freq <= 0) {
        gpioDelay(duration_ms * 1000);
        return;
    }

    /* 50% duty cycle for volume */
    if (gpioHardwarePWM(BUZZER_PIN, freq, PWM_DUTY_50) != 0) {
        fprintf(stderr, "Warning: gpioHardwarePWM failed for %d Hz\n", freq);
        return;
    }

    gpioDelay(duration_ms * 1000);        /* blocking delay */

    /* Turn off to save power */
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop PWM first for a clean tone */
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO configuration ---------------------------------------- */
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Internal pull-up for the button */
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: gpioSetPullUpDown failed\n");
    }

    /* Ensure buzzer is off before we start */
    gpioHardwarePWM(BUZZER_PIN, 0, 0);

    /* --- ISR registration ------------------------------------------ */
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers ------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Musical doorbell ready. Press the button (GPIO%d) to play.\n",
           BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        if (g_playing) {
            const int (*m)[2] = melody;
            for (int i = 0; m[i][0] != 0 && g_running; i++) {
                play_note(m[i][0], m[i][1]);
            }
            g_playing = 0;                 /* melody finished */
        }
        gpioDelay(100000);                 /* 100 ms poll interval */
    }

    /* --- Graceful shutdown ----------------------------------------- */
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

