#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "vibration_events.log"
#define EARTHQUAKE_THRESHOLD 3
#define EARTHQUAKE_WINDOW_SIZE 5
#define DEFAULT_POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void get_iso8601_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &timeinfo);
}

static void log_event(FILE *log_fp, int value) {
    char timestamp[32];
    get_iso8601_timestamp(timestamp, sizeof(timestamp));
    if (fprintf(log_fp, "%s, %d\n", timestamp, value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    } else {
        fflush(log_fp);
    }
}

static void check_earthquake(const int *events, int count) {
    int high_count = 0;
    for (int i = 0; i < count && i < EARTHQUAKE_WINDOW_SIZE; i++) {
        if (events[i] == 1) high_count++;
    }
    if (high_count >= EARTHQUAKE_THRESHOLD) {
        char timestamp[32];
        get_iso8601_timestamp(timestamp, sizeof(timestamp));
        printf("EARTHQUAKE ALERT: %s - High vibration detected (count=%d)\n",
               timestamp, high_count);
        fflush(stdout);
    }
}

int main(int argc, char *argv[]) {
    int poll_timeout_ms = DEFAULT_POLL_TIMEOUT_MS;
    if (argc > 1) {
        poll_timeout_ms = atoi(argv[1]);
        if (poll_timeout_ms <= 0) {
            fprintf(stderr, "Invalid poll timeout '%s', using default %d ms\n",
                    argv[1], DEFAULT_POLL_TIMEOUT_MS);
            poll_timeout_ms = DEFAULT_POLL_TIMEOUT_MS;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "sw420-vibration") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int events[EARTHQUAKE_WINDOW_SIZE];
    int event_index = 0;
    int event_count = 0;

    printf("Monitoring SW-420 vibration sensor on GPIO%d (poll timeout %d ms)...\n",
           GPIO_LINE_OFFSET, poll_timeout_ms);
    fflush(stdout);

    while (program_running) {
        struct timespec ts;
        ts.tv_sec = poll_timeout_ms / 1000;
        ts.tv_nsec = (long)(poll_timeout_ms % 1000) * 1000000L;

        int ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
            continue;
        }

        int value = gpiod_line_event_get_event_type(&event);
        log_event(log_fp, value);

        events[event_index] = value;
        event_index = (event_index + 1) % EARTHQUAKE_WINDOW_SIZE;
        if (event_count < EARTHQUAKE_WINDOW_SIZE) {
            event_count++;
        }

        check_earthquake(events, event_count);
    }

    printf("\nShutting down...\n");
    fflush(stdout);

    fclose(log_fp);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

