    }

    int events[EARTHQUAKE_WINDOW_SIZE];
    int event_index = 0;
    int event_count = 0;

    printf("Monitoring SW-420 vibration sensor on GPIO%d (poll timeout %d ms)...\n",
           GPIO_LINE_OFFSET, poll_timeout_ms);
    fflush(stdout);

    while (program_running) {
        struct timespec ts;
        ts.tv_sec = poll_timeout_ms / 1000;
        ts.tv_nsec = (long)(poll_timeout_ms % 1000) * 1000000L;

        int ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
            continue;
        }

        int value = gpiod_line_event_get_event_type(&event);
        log_event(log_fp, value);

        events[event_index] = value;
        event_index = (event_index + 1) % EARTHQUAKE_WINDOW_SIZE;
        if (event_count < EARTHQUAKE_WINDOW_SIZE) {
            event_count++;
        }

        check_earthquake(events, event_count);
    }

    printf("\nShutting down...\n");
    fflush(stdout);

    fclose(log_fp);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

