/*
 * LSM303DLHC magnetometer reader for Raspberry Pi Zero W
 * Uses the Linux I2C-dev interface (no wiringPi).
 *
 * Wiring:
 *   LSM303DLHC SDA -> GPIO2 (physical pin 3)
 *   LSM303DLHC SCL -> GPIO3 (physical pin 5)
 *   LSM303DLHC VDD -> 3.3 V
 *   LSM303DLHC GND -> GND
 *
 * Build:  gcc -O2 -Wall -o mag_log mag_log.c -lm
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* ---- LSM303DLHC constants (7-bit addresses) ---- */
#define LSM303_MAG_ADDR   0x1E
#define LSM303_ACC_ADDR   0x19   /* accelerometer also shares 0x1D */

/* Magnetometer registers */
#define CRA_REG_M         0x00   /* Temp sensor enable + output rate */
#define MR_REG_M          0x02   /* Operating mode */
#define OUT_X_H_M         0x03   /* X MSB, X LSB, Z MSB, Z LSB, Y MSB, Y LSB */

/* Accelerometer registers (read-only) */
#define OUT_X_L_A         0x28   /* X LSB (accel) */

/* ---- Calibration offsets (replace with your own values) ---- */
#define X_OFFSET  10.0f
#define Y_OFFSET -5.0f
#define Z_OFFSET  20.0f

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SMBus read of one byte from a register. Returns 0 on success, -1 on error. */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* SMBus write of one byte to a register. Returns 0 on success, -1 on error. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* SMBus block read of N bytes starting at reg. Returns 0 on success, -1 on error. */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_block: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_block: read reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of magnetometer data and assemble signed 16-bit values. */
static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t raw[6];
    if (i2c_read_block(fd, OUT_X_H_M, raw, 6) != 0)
        return -1;

    *x = (int16_t)((raw[0] << 8) | raw[1]);
    *z = (int16_t)((raw[2] << 8) | raw[3]);
    *y = (int16_t)((raw[4] << 8) | raw[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
static float calibrate_x(int16_t raw) { return (float)raw - X_OFFSET; }
static float calibrate_y(int16_t raw) { return (float)raw - Y_OFFSET; }
static float calibrate_z(int16_t raw) { return (float)raw - Z_OFFSET; }

/* ------------------------------------------------------------------ */
static float calculate_heading(float cal_x, float cal_y)
{
    float heading = atan2f(cal_y, cal_x) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

/* ------------------------------------------------------------------ */
static const char *determine_direction(float heading)
{
    if (heading >= 337.5f || heading < 22.5f)   return "N";
    if (heading < 67.5f)                        return "NE";
    if (heading < 112.5f)                       return "E";
    if (heading < 157.5f)                       return "SE";
    if (heading < 202.5f)                       return "S";
    if (heading < 247.5f)                       return "SW";
    if (heading < 292.5f)                       return "W";
    return "NW";
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float cal_x, float cal_y, float cal_z,
                    float heading, const char *dir)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "log_data: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%s\n",
                ts, cal_x, cal_y, cal_z, heading, dir) < 0) {
        fprintf(stderr, "log_data: fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "log_data: fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open /dev/i2c-1 failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Set slave address ---- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Verify device presence with a dummy read ---- */
    uint8_t dummy;
    if (i2c_read_reg8(g_i2c_fd, OUT_X_H_M, &dummy) != 0) {
        fprintf(stderr, "LSM303DLHC not responding at 0x%02X\n", LSM303_MAG_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure magnetometer: continuous-conversion mode ---- */
    if (i2c_write_reg8(g_i2c_fd, MR_REG_M, 0x00) != 0) {
        fprintf(stderr, "Failed to set magnetometer continuous mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Optional: set output data rate to 15 Hz ---- */
    if (i2c_write_reg8(g_i2c_fd, CRA_REG_M, 0x14) != 0) {
        fprintf(stderr, "Warning: failed to set CRA_REG_M (continuing)\n");
    }

    /* ---- Open log file (append mode) ---- */
    g_log_fp = fopen("mag_log.csv", "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen mag_log.csv failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_fp) == 0) {
        if (fprintf(g_log_fp, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n") < 0) {
            fprintf(stderr, "fprintf header failed: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_fp);
    }

    printf("LSM303DLHC logging started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t raw_x, raw_y, raw_z;

        if (read_magnetometer(g_i2c_fd, &raw_x, &raw_y, &raw_z) != 0) {
            fprintf(stderr, "Skipping sample due to I2C read failure\n");
            sleep(1);
            continue;
        }

        float cal_x = calibrate_x(raw_x);
        float cal_y = calibrate_y(raw_y);
        float cal_z = calibrate_z(raw_z);
        float heading = calculate_heading(cal_x, cal_y);
        const char *dir = determine_direction(heading);

        printf("X: %7.2f  Y: %7.2f  Z: %7.2f  Heading: %6.2f  %s\n",
               cal_x, cal_y, cal_z, heading, dir);

        if (log_data(g_log_fp, cal_x, cal_y, cal_z, heading, dir) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

