#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define LOG_FILE         "relay_log.json"
#define DEBOUNCE_MS      200
#define POLL_DELAY_US    10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void touch_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)tick; (void)userdata;
    static uint32_t last_tick = 0;
    uint32_t now = gpioTick();
    if (now - last_tick < DEBOUNCE_MS * 1000) return;
    last_tick = now;

    if (level == 1) {
        int state = gpioRead(RELAY_PIN);
        if (gpioWrite(RELAY_PIN, !state) != 0) {
            fprintf(stderr, "Failed to toggle relay\n");
            return;
        }
        time_t rawtime;
        time(&rawtime);
        struct tm *timeinfo = localtime(&rawtime);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        FILE *fp = fopen(LOG_FILE, "a");
        if (fp) {
            fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n",
                    timestamp, state ? "ON" : "OFF");
            fclose(fp);
        } else {
            perror("fopen log");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set touch pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
