#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25
#define MOISTURE_THRESHOLD 30
#define RELAY_DURATION 5
#define GAP_DURATION 1
#define POLL_INTERVAL 10
#define LOG_FILE "irrigation_log.txt"

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[4] = {NULL, NULL, NULL, NULL};
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 1);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

static int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    int pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get line %d: %s\n", pins[i], strerror(errno));
            return -1;
        }
        if (gpiod_line_request_output(relay_lines[i], "irrigation", 1) < 0) {
            fprintf(stderr, "Failed to request line %d as output: %s\n", pins[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int read_soil_moisture(void) {
    return rand() % 101;
}

static void activate_relay(int relay_num) {
    if (relay_num < 1 || relay_num > 4) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_num);
        return;
    }
    int idx = relay_num - 1;
    if (gpiod_line_set_value(relay_lines[idx], 0) < 0) {
        fprintf(stderr, "Failed to activate relay %d: %s\n", relay_num, strerror(errno));
        return;
    }
    printf("Relay %d activated\n", relay_num);
}

static void deactivate_relay(int relay_num) {
    if (relay_num < 1 || relay_num > 4) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_num);
        return;
    }
    int idx = relay_num - 1;
    if (gpiod_line_set_value(relay_lines[idx], 1) < 0) {
        fprintf(stderr, "Failed to deactivate relay %d: %s\n", relay_num, strerror(errno));
        return;
    }
    printf("Relay %d deactivated\n", relay_num);
}

static void log_irrigation(int relay_num, int moisture) {
    if (!log_fp) {
        fprintf(stderr, "Log file not open\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    if (fprintf(log_fp, "%s - Relay %d activated, Moisture: %d%%\n", timestamp, relay_num, moisture) < 0) {
        fprintf(stderr, "Failed to write to log: %s\n", strerror(errno));
        return;
    }
    if (fflush(log_fp) == EOF) {
        fprintf(stderr, "Failed to flush log: %s\n", strerror(errno));
    }
}

int main(void) {
    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (setup_gpio() < 0) {
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture = read_soil_moisture();
        printf("Soil Moisture: %d%%\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            for (int i = 1; i <= 4; i++) {
                activate_relay(i);
                log_irrigation(i, moisture);
                sleep(RELAY_DURATION);
                deactivate_relay(i);
                if (i < 4) {
                    sleep(GAP_DURATION);
                }
            }
        }

        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

