/*
 * Automated Plant Watering System for Raspberry Pi Zero W
 * Uses pigpio library to drive two SG90 servos.
 *
 * Wiring:
 *   Valve servo signal -> GPIO17 (physical pin 11)
 *   Nozzle servo signal -> GPIO18 (physical pin 12)
 *   Common GND for both servos
 *
 * Build: gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run:   sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_SERVO_PIN      17
#define NOZZLE_SERVO_PIN     18

#define MOISTURE_THRESHOLD   50
#define WATERING_DURATION    5   /* seconds per nozzle angle */
#define CYCLE_DELAY          5   /* seconds between moisture readings */
#define SERVO_SET_RETRIES    3
#define SERVO_SET_RETRY_DELAY_US 100000  /* 100 ms */

/* SG90 pulse width range: 500 us (0 deg) to 2500 us (180 deg) */
#define SERVO_MIN_PULSE_US   500
#define SERVO_MAX_PULSE_US   2500

/* Nozzle servo positions in degrees (0-180) */
static const int nozzle_positions[] = {0, 45, 90, 135, 180};
static const int num_positions =
    sizeof(nozzle_positions) / sizeof(nozzle_positions[0]);

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — only async-signal-safe operations                 */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Convert moisture reading (0-100) to servo pulse width (us)         */
/* ------------------------------------------------------------------ */
static int moisture_to_pulse(int moisture)
{
    if (moisture < 0)  moisture = 0;
    if (moisture > 100) moisture = 100;
    return SERVO_MIN_PULSE_US +
           (int)((long)(moisture) * (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US) / 100);
}

/* ------------------------------------------------------------------ */
/* Set servo pulse width with retry on failure                         */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int set_servo_with_retry(int pin, int pulse_us)
{
    for (int attempt = 0; attempt < SERVO_SET_RETRIES; attempt++) {
        if (gpioServo(pin, pulse_us) == 0)
            return 0;
        fprintf(stderr, "Warning: gpioServo(pin=%d, %d us) failed (attempt %d/%d)\n",
                pin, pulse_us, attempt + 1, SERVO_SET_RETRIES);
        if (attempt < SERVO_SET_RETRIES - 1)
            gpioDelay(SERVO_SET_RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Open valve to 90 degrees (moisture > threshold)                     */
/* ------------------------------------------------------------------ */
static int open_valve(void)
{
    int pulse = moisture_to_pulse(90);
    if (set_servo_with_retry(VALVE_SERVO_PIN, pulse) != 0) {
        fprintf(stderr, "Error: failed to open valve (pulse %d us)\n", pulse);
        return -1;
    }
    printf("Valve opened to %d degrees (pulse %d us)\n", 90, pulse);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Close valve to 0 degrees                                            */
/* ------------------------------------------------------------------ */
static int close_valve(void)
{
    int pulse = moisture_to_pulse(0);
    if (set_servo_with_retry(VALVE_SERVO_PIN, pulse) != 0) {
        fprintf(stderr, "Warning: failed to close valve (pulse %d us)\n", pulse);
        return -1;
    }
    printf("Valve closed to 0 degrees (pulse %d us)\n", pulse);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Water one nozzle angle, then hold for WATERING_DURATION seconds     */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int water_one_angle(int angle)
{
    int pulse = moisture_to_pulse(angle);
    if (set_servo_with_retry(NOZZLE_SERVO_PIN, pulse) != 0) {
        fprintf(stderr, "Error: failed to set nozzle to %d degrees (pulse %d us)\n",
                angle, pulse);
        return -1;
    }
    printf("Nozzle at %d degrees (pulse %d us)\n", angle, pulse);

    /* Hold for the watering duration, checking g_running every second */
    for (int i = 0; i < WATERING_DURATION && g_running; i++)
        gpioDelay(1000000);  /* 1 second */

    if (!g_running) {
        fprintf(stderr, "Interrupted during watering at %d degrees\n", angle);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Water all nozzle angles in sequence                                 */
/* ------------------------------------------------------------------ */
static int water_all_angles(void)
{
    for (int i = 0; i < num_positions && g_running; i++) {
        if (water_one_angle(nozzle_positions[i]) != 0)
            return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — stop servos and terminate pigpio                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop both servos (pulse 0 = off) */
    gpioServo(VALVE_SERVO_PIN, 0);
    gpioServo(NOZZLE_SERVO_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Automated Plant Watering System started\n");
    printf("  Valve servo : GPIO%d\n", VALVE_SERVO_PIN);
    printf("  Nozzle servo: GPIO%d\n", NOZZLE_SERVO_PIN);
    printf("  Threshold   : %d\n", MOISTURE_THRESHOLD);
    printf("  Cycle delay : %d s\n", CYCLE_DELAY);
    printf("  Watering dur: %d s/angle\n", WATERING_DURATION);
    printf("Press Ctrl+C to exit\n\n");

    /* Main loop */
    while (g_running) {
        int moisture = 0;  /* dummy value — replaced in real cycle */

        /* ---- Simulated moisture cycle ---- */
        const int readings[] = {20, 40, 60, 80, 100};
        const int num_readings =
            sizeof(readings) / sizeof(readings[0]);

        for (int i = 0; i < num_readings && g_running; i++) {
            moisture = readings[i];
            printf("Simulated moisture reading: %d\n", moisture);

            if (moisture < MOISTURE_THRESHOLD) {
                printf("Moisture below threshold (%d < %d). Watering...\n",
                       moisture, MOISTURE_THRESHOLD);

                if (open_valve() != 0) {
                    fprintf(stderr, "Error: valve open failed, aborting cycle\n");
                    break;
                }

                if (water_all_angles() != 0) {
                    fprintf(stderr, "Error: watering failed at angle %d\n",
                            nozzle_positions[0]);
                    break;
                }

                if (close_valve() != 0) {
                    fprintf(stderr, "Warning: valve close failed\n");
                }
            } else {
