    switch (step) {
        case 0: safe_write(IN1, 1); safe_write(IN2, 0); safe_write(IN3, 0); safe_write(IN4, 0); break;
        case 1: safe_write(IN1, 0); safe_write(IN2, 1); safe_write(IN3, 0); safe_write(IN4, 0); break;
        case 2: safe_write(IN1, 0); safe_write(IN2, 0); safe_write(IN3, 1); safe_write(IN4, 0); break;
        case 3: safe_write(IN1, 0); safe_write(IN2, 0); safe_write(IN3, 0); safe_write(IN4, 1); break;
        default: deenergize(); return;
    }
    gpioDelay(STEP_DELAY_US);
}

static void rotate(int steps, int direction) {
    int step = 0;
    if (direction > 0) {
        for (int i = 0; i < steps && running; i++) {
            step = (step + 1) % 4;
            rotate_step(step);
        }
    } else {
        for (int i = 0; i < steps && running; i++) {
            step = (step + 3) % 4;
            rotate_step(step);
        }
    }
    deenergize();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_mode(IN1, PI_OUTPUT) < 0 ||
        safe_set_mode(IN2, PI_OUTPUT) < 0 ||
        safe_set_mode(IN3, PI_OUTPUT) < 0 ||
        safe_set_mode(IN4, PI_OUTPUT) < 0 ||
        safe_set_mode(LOCK_BUTTON, PI_INPUT) < 0 ||
        safe_set_mode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        deenergize();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_pull(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        safe_set_pull(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        deenergize();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    deenergize();
    printf("Automatic Door Lock System running. Press LOCK (BCM 24) to open, UNLOCK (BCM 23) to close.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(LOCK_BUTTON) == 0) {
                printf("Locking door...\n");
                rotate(STEPS_PER_REV, 1);
                printf("Door locked.\n");
                while (running && gpioRead(LOCK_BUTTON) == 0) gpioDelay(100000);
            }
        } else if (gpioRead(UNLOCK_BUTTON) == 0) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(UNLOCK_BUTTON) == 0) {
                printf("Unlocking door...\n");
                rotate(STEPS_PER_REV, -1);
                printf("Door unlocked.\n");
                while (running && gpioRead(UNLOCK_BUTTON) == 0) gpioDelay(100000);
            }
        }
        gpioDelay(10000);
    }

    deenergize();
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

