#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define SPEED_OF_SOUND_CM_PER_US 0.01715   /* 343 m/s in cm/us */
#define ECHO_TIMEOUT_US 50000              /* 50 ms */
#define TRIGGER_PULSE_US 10
#define MIN_GAP_US 60000                   /* 60 ms between measurements */
#define POLL_INTERVAL_US 1000000           /* 1 s */

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static long long now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
        return 0;
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static int wait_for_value(struct gpiod_line *line, int target, long long timeout_us)
{
    long long deadline = now_us() + timeout_us;
    for (;;) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            return -1;
        }
        if (val == target)
            return 0;
        if (now_us() >= deadline)
            return -1;
    }
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo, float *distance_cm)
{
    long long t0, t_rise, t_fall;

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to reset trigger: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for echo rising edge (timeout) */
    t0 = now_us();
    if (wait_for_value(echo, 1, ECHO_TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo rising edge\n");
        return -1;
    }
    t_rise = now_us();

    /* Wait for echo falling edge (timeout) */
    if (wait_for_value(echo, 0, ECHO_TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo falling edge\n");
        return -1;
    }
    t_fall = now_us();

    long long duration = t_fall - t_rise;
    *distance_cm = (float)duration * SPEED_OF_SOUND_CM_PER_US;
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    FILE *log = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open log file once */
    log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open gpiochip4 (RPi 4 default) */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        goto cleanup;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "gpiod_chip_get_line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Request trigger line failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Request echo line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to stop.\n");

    while (running) {
        float dist;
        if (measure_distance(trig, echo, &dist) == 0) {
            fprintf(log, "%.2f\n", dist);
            fflush(log);
            printf("Distance: %.2f cm\n", dist);
        } else {
            fprintf(log, "-1\n");
            fflush(log);
            fprintf(stderr, "Measurement failed\n");
        }
        usleep(POLL_INTERVAL_US);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig)
        gpiod_line_release(trig);
    if (echo)
        gpiod_line_release(echo);
    if (chip)
        gpiod_chip_close(chip);
    if (log)
        fclose(log);
    return rc;
}

