/*
 * Proximity-based automated door system for Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - VL53L1X time-of-flight sensor on I2C bus 1, address 0x29
 *   - Relay module on BCM GPIO18 (active-high)
 *
 * Behaviour:
 *   - Software-reset the VL53L1X (reg 0x0000 = 0x00)
 *   - Set ranging mode to continuous (reg 0x0080 = 0x01)
 *   - Poll every 100 ms; when distance <= 50 cm, drive GPIO18 HIGH
 *   - On SIGINT, release all resources cleanly
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define RELAY_GPIO     18
#define DISTANCE_CM    50
#define POLL_MS        100

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define REG_SOFT_RESET          0x0000
#define REG_SYSTEM_MODE_START   0x0080
#define REG_GPIO_HV_MUX_CTRL    0x0030
#define REG_SYSTEM_INTERRUPT    0x0044
#define REG_RESULT_RANGE_STATUS 0x0089
#define REG_RESULT_DISTANCE     0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address + 1 byte payload */
static int vl53l1x_write_reg(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read N bytes starting at a 16-bit register address */
static int vl53l1x_read_reg(int handle, uint16_t reg, uint8_t *data, uint8_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)data, len);
}

static int vl53l1x_init(int handle)
{
    /* Software reset */
    if (vl53l1x_write_reg(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write soft reset register\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms settle */

    /* Start continuous ranging mode */
    if (vl53l1x_write_reg(handle, REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start ranging mode\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance)
{
    uint8_t status = 0;
    uint8_t data[2] = {0};

    /* Check interrupt status for data-ready */
    if (vl53l1x_read_reg(handle, REG_SYSTEM_INTERRUPT, &status, 1) < 0) {
        fprintf(stderr, "Error: failed to read interrupt status\n");
        return -1;
    }
    if ((status & 0x07) == 0) {
        return 1; /* no data ready yet */
    }

    /* Read 16-bit distance (big-endian) */
    if (vl53l1x_read_reg(handle, REG_RESULT_DISTANCE, data, 2) < 0) {
        fprintf(stderr, "Error: failed to read distance data\n");
        return -1;
    }

    *distance = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

int main(void)
{
    uint16_t distance = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity-based door system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance);
        if (rc == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance <= (uint16_t)(DISTANCE_CM * 10)) {
                gpioWrite(RELAY_GPIO, 1);
            } else {
                gpioWrite(RELAY_GPIO, 0);
            }
        } else if (rc < 0) {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
        }
        /* rc == 1 means no new data yet; just wait */
        gpioDelay(POLL_MS * 1000);
    }

    /* Clean shutdown */
    gpioWrite(RELAY_GPIO, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

