/*
 * Automated plant watering system for Raspberry Pi 4 Model B
 * Uses libgpiod v1 API (modern, actively maintained).
 *
 * Relay pins (BCM): 17, 18, 27, 22  (physical: 11, 12, 13, 15)
 * Active-low relay: HIGH = relay OFF, LOW = relay ON
 *
 * Build: gcc -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define WATERING_DURATION 5          /* seconds */
#define POLL_INTERVAL 60             /* seconds */
#define LOG_FILE "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int log_watering_event(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Watering event triggered\n", timestamp) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

static int activate_relay(struct gpiod_line *line, int pin)
{
    int ret = gpiod_line_set_value(line, 0); /* LOW = relay ON */
    if (ret < 0) {
        fprintf(stderr, "Failed to activate relay on BCM %u: %s\n",
                pin, strerror(errno));
        return -1;
    }
    return 0;
}

static int deactivate_relay(struct gpiod_line *line, int pin)
{
    int ret = gpiod_line_set_value(line, 1); /* HIGH = relay OFF */
    if (ret < 0) {
        fprintf(stderr, "Failed to deactivate relay on BCM %u: %s\n",
                pin, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++)
        lines[i] = NULL;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default GPIO chip (gpiochip0 on Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    /* Request each relay line as output, initial value HIGH (inactive) */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(BCM %u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "watering-relay", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output(BCM %u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Automated plant watering system started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_RELAYS && running; i++) {
            printf("Watering relay on BCM %u for %d seconds...\n",
                   relay_pins[i], WATERING_DURATION);

            if (activate_relay(lines[i], relay_pins[i]) < 0)
                goto cleanup;

            /* Sleep in 1-second increments so signals are caught promptly */
            for (int s = 0; s < WATERING_DURATION && running; s++)
                sleep(1);

            if (deactivate_relay(lines[i], relay_pins[i]) < 0)
                goto cleanup;

            if (log_watering_event() < 0)
                goto cleanup;

            /* Wait before activating the next relay */
            for (int s = 0; s < POLL_INTERVAL && running; s++)
                sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Deactivate all relays before releasing lines */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1); /* HIGH = OFF */
            gpiod_line_release(lines[i]);
        }
    }

    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nWatering system stopped.\n");

    return ret;
}

