#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43

/* Expected WHO_AM_I value */
#define MPU6050_WHO_AM_I_VAL 0x68

/* GPIO pin for LED */
#define LED_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Sampling period (microseconds) */
#define SAMPLE_PERIOD_US 50000

/* Gyroscope full-scale range: ±250 deg/s */
#define GYRO_SCALE 131.0f

/* Threshold for LED activation (degrees/second) */
#define THRESHOLD 250.0f

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Re-initialisation attempts on read failure */
#define MAX_REINIT_ATTEMPTS 3

/* Data structure for gyroscope readings */
typedef struct {
    float x;
    float y;
    float z;
    struct timespec timestamp;
} gyro_data_t;

/* Circular buffer */
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* Global state */
static int i2c_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int init_mpu6050(void);
static int read_gyro_data(float *x, float *y, float *z);
static void add_to_buffer(circular_buffer_t *cb, float x, float y, float z);
static void check_threshold(float x, float y, float z);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

static int init_mpu6050(void)
{
    /* Verify device identity */
    int who = i2cReadByteData(i2c_handle, MPU6050_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: I2C read failed for WHO_AM_I (pigpio error %d)\n", who);
        return -1;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up the MPU-6050 (clear SLEEP bit) */
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time after wake-up */

    /* Set sample rate divider: 1 kHz / (1 + 7) = 125 Hz internal rate,
       but we want 1 kHz.  SMPLRT_DIV = 7 gives 1 kHz / (1 + 7) = 125 Hz.
       For 1 kHz output, SMPLRT_DIV = 0 (default).  We set it to 7 to
       keep the sample rate at 1 kHz and avoid the discontinuous rate. */
    if (i2cWriteByteData(i2c_handle, MPU6050_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Failed to write SMPLRT_DIV\n");
        return -1;
    }

    /* Gyro full-scale range: ±250 deg/s (0x00) */
    if (i2cWriteByteData(i2c_handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

static int read_gyro_data(float *x, float *y, float *z)
{
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    /* Read 6 bytes starting at GYRO_XOUT_H (0x43) */
    int n = i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, buf, 6);
    if (n != 6) {
        fprintf(stderr, "Error: I2C block read failed (got %d bytes)\n", n);
        return -1;
    }

    /* MPU-6050 is big-endian: [H][L] */
    raw_x = (int16_t)(((uint16_t)buf[0] << 8) | (uint8_t)buf[1]);
    raw_y = (int16_t)(((uint16_t)buf[2] << 8) | (uint8_t)buf[3]);
    raw_z = (int16_t)(((uint16_t)buf[4] << 8) | (uint8_t)buf[5]);

    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

static void add_to_buffer(circular_buffer_t *cb, float x, float y, float z)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    cb->buffer[cb->head].x = x;
    cb->buffer[cb->head].y = y;
    cb->buffer[cb->head].z = z;
    cb->buffer[cb->head].timestamp = ts;

    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

static void check_threshold(float x, float y, float z)
{
    if (fabsf(x) > THRESHOLD ||
        fabsf(y) > THRESHOLD ||
        fabsf(z) > THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output, initially off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open I2C bus 1 at address 0x68 */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;
    int reinit_attempts = 0;

    /* Main sampling loop */
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(&gyro_buffer, x, y, z);
            check_threshold(x, y, z);
            reinit_attempts = 0;
        } else {
            fprintf(stderr, "Warning: Gyro read failed, re-initialising...\n");
            if (reinit_attempts < MAX_REINIT_ATTEMPTS) {
                if (init_mpu6050() == 0) {
                    reinit_attempts = 0;
                } else {
                    reinit_attempts++;
                }
            } else {
                fprintf(stderr, "Error: Re-initialisation failed after %d attempts, exiting.\n",
                        MAX_REINIT_ATTEMPTS);
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    cleanup();
    return EXIT_SUCCESS;
}

