#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define CS_PIN 8
#define LED_PIN 17
#define BUFFER_SIZE 64
#define GYRO_SENSITIVITY 131.0f
#define THRESHOLD 200.0f
#define SPI_SPEED_HZ 3900000
#define SPI_MODE 0
#define SPI_BITS 8

typedef struct {
    time_t timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_line *led_line = NULL;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        perror("Failed to get CS line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "mpu6050_cs", 1) < 0) {
        perror("Failed to request CS line as output");
        gpiod_chip_close(chip);
        chip = NULL;
        cs_line = NULL;
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        chip = NULL;
        cs_line = NULL;
        return -1;
    }

    if (gpiod_line_request_output(led_line, "mpu6050_led", 0) < 0) {
        perror("Failed to request LED line as output");
        gpiod_line_release(cs_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        chip = NULL;
        cs_line = NULL;
        led_line = NULL;
        return -1;
    }

    return 0;
}

static int read_register(uint8_t reg, uint8_t *data, size_t len) {
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Failed to assert CS");
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)reg,
        .rx_buf = (unsigned long)data,
        .len = 1,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI write failed");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    tr.tx_buf = 0;
    tr.rx_buf = (unsigned long)data;
    tr.len = len;
    tr.cs_change = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI read failed");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Failed to deassert CS");
        return -1;
    }

    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    uint8_t data[6];

    if (read_register(0x43, data, 6) < 0) {
        return -1;
    }

    int16_t raw_x = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_y = (int16_t)((data[2] << 8) | data[3]);
    int16_t raw_z = (int16_t)((data[4] << 8) | data[5]);

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

static void add_to_buffer(float x, float y, float z) {
    time(&gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&gyro_buffer[idx].timestamp);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("%s,%.2f,%.2f,%.2f\n", time_str, gyro_buffer[idx].x, gyro_buffer[idx].y, gyro_buffer[idx].z);
    }
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return 1;
    }

    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    if (gpio_init() < 0) {
        cleanup();
        return 1;
    }

    printf("MPU-6050 Gyroscope Data Logger\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;

        if (read_gyro_data(&x, &y, &z) < 0) {
            fprintf(stderr, "Error reading gyro data. Retrying...\n");
            usleep(100000);
            continue;
        }

        add_to_buffer(x, y, z);

        if (fabsf(x) > THRESHOLD || fabsf(y) > THRESHOLD || fabsf(z) > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
            usleep(500000);
            gpiod_line_set_value(led_line, 0);
            usleep(500000);
        }

        usleep(10000);
    }

    printf("\nExiting...\n");
    print_buffer();
    cleanup();
    return 0;
}

