#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

/* GPIO pin for the LED */
#define LED_PIN 21

/* Tilt threshold in degrees */
#define TILT_THRESHOLD 45.0

/* I2C bus on Raspberry Pi 4 Model B */
#define I2C_BUS 1

/* Global variables for signal handling */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

/* Function prototypes */
static int  init_mpu6050(int handle);
static int  read_accelerometer(int handle, int16_t *x, int16_t *y, int16_t *z);
static void calculate_tilt(int16_t x, int16_t y, int16_t z, float *roll, float *pitch);
static void control_led(int led_pin, float roll, float pitch, float threshold);
static void log_tilt_data(float roll, float pitch);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* Initialize the MPU-6050 */
static int init_mpu6050(int handle) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050 (PWR_MGMT_1 write failed).\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time */

    /* Set accelerometer full-scale range to ±2g (AFS_SEL = 0) */
    if (i2cWriteByteData(handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure accelerometer range (ACCEL_CONFIG write failed).\n");
        return -1;
    }

    return 0;
}

/* Read accelerometer data from the MPU-6050 */
static int read_accelerometer(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    /* Read 6 bytes starting from ACCEL_XOUT_H (0x3B) */
    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data (I2C block read failed).\n");
        return -1;
    }

    /* Combine high and low bytes (big-endian) */
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

/* Calculate roll and pitch from accelerometer data */
static void calculate_tilt(int16_t x, int16_t y, int16_t z, float *roll, float *pitch) {
    float x_g = (float)x / 16384.0; /* Convert to g units (±2g range) */
    float y_g = (float)y / 16384.0;
    float z_g = (float)z / 16384.0;

    *roll  = atan2f(y_g, z_g) * 180.0 / M_PI;
    *pitch = atan2f(-x_g, sqrtf(y_g * y_g + z_g * z_g)) * 180.0 / M_PI;
}

/* Control the LED based on tilt thresholds */
static void control_led(int led_pin, float roll, float pitch, float threshold) {
    if (fabsf(roll) > threshold || fabsf(pitch) > threshold) {
        gpioWrite(led_pin, 1); /* Turn LED on */
    } else {
        gpioWrite(led_pin, 0); /* Turn LED off */
    }
}

/* Log tilt data to a file */
static void log_tilt_data(float roll, float pitch) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open tilt_log.txt for writing: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fclose(fp);
}

int main(void) {
    int16_t x, y, z;
    float roll, pitch;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection on bus 1 */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device on bus %d, address 0x%02X.\n", I2C_BUS, MPU6050_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the MPU-6050 */
    if (init_mpu6050(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: Could not register SIGINT handler: %s\n", strerror(errno));
    }

    printf("Tilt monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        /* Read accelerometer data */
        if (read_accelerometer(i2c_handle, &x, &y, &z) == 0) {
            /* Calculate roll and pitch */
            calculate_tilt(x, y, z, &roll, &pitch);

            /* Control the LED */
            control_led(LED_PIN, roll, pitch, TILT_THRESHOLD);

            /* Log the data */
            log_tilt_data(roll, pitch);

            /* Print roll and pitch to the console */
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping this cycle.\n");
        }

        gpioDelay(100000); /* 100 ms delay */
    }

    /* Cleanup and exit */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

