#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1145_ADDR    0x5A
#define AMBIENT_REG    0x20
#define PROXIMITY_REG  0x22
#define GPIO_CHIP      "gpiochip0"
#define LED_PIN        17
#define PROXIMITY_THRESHOLD 100
#define LOG_FILE       "biometric_log.txt"
#define POLL_MS        100
#define I2C_RETRIES    3
#define I2C_RETRY_MS   10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d): %s\n",
                    reg, attempt + 1, strerror(errno));
            usleep(I2C_RETRY_MS * 1000);
            continue;
        }
        if (read(fd, buf, 2) != 2) {
            fprintf(stderr, "I2C read reg 0x%02X failed (attempt %d): %s\n",
                    reg, attempt + 1, strerror(errno));
            usleep(I2C_RETRY_MS * 1000);
            continue;
        }
        *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
        return 0;
    }
    return -1;
}

static int log_data(FILE *fp, uint16_t ambient, uint16_t proximity) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    if (!localtime_r(&now, &tm_info)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", ts, ambient, proximity) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1145_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                LED_PIN, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(led_line, "si1145-led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Si1145 biometric sensor logging started. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t ambient = 0, proximity = 0;
        int rc = 0;

        if (i2c_read_reg16(i2c_fd, AMBIENT_REG, &ambient) != 0) {
            fprintf(stderr, "Failed to read ambient light after %d retries.\n", I2C_RETRIES);
            rc = 1;
        }
        if (rc == 0 && i2c_read_reg16(i2c_fd, PROXIMITY_REG, &proximity) != 0) {
            fprintf(stderr, "Failed to read proximity after %d retries.\n", I2C_RETRIES);
            rc = 1;
        }

        if (rc == 0) {
            if (log_data(log_fp, ambient, proximity) != 0) {
                fprintf(stderr, "Logging failed.\n");
            }
            gpiod_line_set_value(led_line, (proximity > PROXIMITY_THRESHOLD) ? 1 : 0);
        }

        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

