#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADXRS290 register addresses */
#define ADXRS290_REG_X_RATE  0x02
#define ADXRS290_REG_Y_RATE  0x04

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0        /* CPOL=0, CPHA=0 */

/* Sensitivity: 200 LSB per deg/s */
#define GYRO_SENSITIVITY 200.0f

/* Sampling interval: ~100 Hz */
#define SAMPLE_DELAY_US 10000

/* SPI re-init attempts on failure */
#define MAX_SPI_REINIT 3

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit two's-complement register from the ADXRS290.
 * Returns 0 on success, -1 on SPI transfer failure. */
static int read_gyro_register(uint8_t reg_addr, int16_t *out) {
    char tx[3];
    char rx[3];

    /* ADXRS290 SPI read: send address | 0x80, then a dummy byte */
    tx[0] = (char)(reg_addr | 0x80);
    tx[1] = 0x00;
    tx[2] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    /* Response: rx[1] = high byte, rx[2] = low byte */
    int16_t raw = (int16_t)(((uint8_t)rx[1] << 8) | (uint8_t)rx[2]);
    *out = raw;
    return 0;
}

static int read_gyro_data(gyro_data_t *data) {
    if (read_gyro_register(ADXRS290_REG_X_RATE, &data->x_rate) != 0) return -1;
    if (read_gyro_register(ADXRS290_REG_Y_RATE, &data->y_rate) != 0) return -1;
    return 0;
}

static int log_gyro_data(const gyro_data_t *data) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(log_file, "%ld.%06ld,%d,%d\n",
                (long)ts.tv_sec, ts.tv_nsec / 1000,
                data->x_rate, data->y_rate) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return 1;
    }

    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("gyro_data.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "fopen gyro_data.csv failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (fprintf(log_file, "timestamp,x_rate,y_rate\n") < 0) {
        fprintf(stderr, "fprintf header failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    gyro_data_t gyro_data;
    int spi_reinit_count = 0;

    while (!terminate) {
        if (read_gyro_data(&gyro_data) == 0) {
            if (log_gyro_data(&gyro_data) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
            spi_reinit_count = 0;
        } else {
            fprintf(stderr, "Gyro read failed; reinitialising SPI...\n");
            spiClose(spi_handle);
            spi_handle = -1;

            if (spi_reinit_count < MAX_SPI_REINIT) {
                if (initialize_spi() == 0) {
                    spi_reinit_count = 0;
                } else {
                    spi_reinit_count++;
                }
            } else {
                fprintf(stderr, "SPI reinitialisation failed after %d attempts.\n", MAX_SPI_REINIT);
                break;
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    return 0;
}

