#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN    17
#define THRESHOLD_MS 500
#define ALERT_DURATION_MS 2000
#define LOG_FILE     "seismic_events.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) return;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s - %s\n", ts, message);
    fflush(log_file);
}

static void seismic_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    static int      s1_state  = 0;
    static int      s2_state  = 0;
    uint32_t elapsed;

    if (level == 1) {
        if (gpio == SENSOR_1_PIN) s1_state = 1;
        if (gpio == SENSOR_2_PIN) s2_state = 1;
        if (s1_state && s2_state) {
            elapsed = tick - last_tick;
            if (elapsed >= (uint32_t)(THRESHOLD_MS * 1000)) {
                log_event("Seismic event detected!");
                gpioWrite(ALERT_PIN, 1);
                gpioDelay(ALERT_DURATION_MS * 1000);
                gpioWrite(ALERT_PIN, 0);
            }
            last_tick = tick;
        }
    } else if (level == 0) {
        if (gpio == SENSOR_1_PIN) s1_state = 0;
        if (gpio == SENSOR_2_PIN) s2_state = 0;
    }
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_1_PIN\n");
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_2_PIN\n");
        return -1;
    }
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for ALERT_PIN\n");
        return -1;
    }
    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise ALERT_PIN LOW\n");
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down for SENSOR_1_PIN\n");
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down for SENSOR_2_PIN\n");
        return -1;
    }
    if (gpioSetAlertFunc(SENSOR_1_PIN, seismic_callback) < 0) {
        fprintf(stderr, "Failed to register callback for SENSOR_1_PIN\n");
        return -1;
    }
    if (gpioSetAlertFunc(SENSOR_2_PIN, seismic_callback) < 0) {
        fprintf(stderr, "Failed to register callback for SENSOR_2_PIN\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        fclose(log_file);
        return 1;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");
    log_event("Seismic monitoring started.");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioWrite(ALERT_PIN, 0);
    gpioSetAlertFunc(SENSOR_1_PIN, NULL);
    gpioSetAlertFunc(SENSOR_2_PIN, NULL);
    gpioTerminate();
    if (log_file) {
        log_event("Seismic monitoring stopped.");
        fclose(log_file);
    }
    return 0;
}

