#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <math.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_PIN 17
#define THRESHOLD 20.0
#define BUFFER_SIZE 100
#define ADXRS290_SENSITIVITY 200.0

#define ADXRS290_REG_RATE_XL 0x02
#define ADXRS290_REG_RATE_XH 0x03

#define ADXRS290_READ_BIT 0x80

typedef struct {
    struct timespec timestamp;
    double angular_velocity;
} gyro_data_t;

typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int spi_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_read_register(uint8_t reg, uint8_t *data, int len) {
    char tx_buf[32];
    char rx_buf[32];

    if (len > 32) {
        fprintf(stderr, "Error: SPI read length %d exceeds buffer size\n", len);
        return -1;
    }

    tx_buf[0] = reg | ADXRS290_READ_BIT;
    for (int i = 1; i < len + 1; i++) {
        tx_buf[i] = 0x00;
    }

    int result = spiXfer(spi_handle, tx_buf, rx_buf, len + 1);
    if (result != len + 1) {
        fprintf(stderr, "Error: SPI read failed for register 0x%02X (result=%d)\n", reg, result);
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

static int read_gyro_data(double *x_rate, double *y_rate) {
    uint8_t xl, xh, yl, yh;

    if (spi_read_register(ADXRS290_REG_RATE_XL, &xl, 1) != 0) return -1;
    if (spi_read_register(ADXRS290_REG_RATE_XH, &xh, 1) != 0) return -1;
    if (spi_read_register(ADXRS290_REG_RATE_XL, &yl, 1) != 0) return -1;
    if (spi_read_register(ADXRS290_REG_RATE_XH, &yh, 1) != 0) return -1;

    int16_t raw_x = (int16_t)((xh << 8) | xl);
    int16_t raw_y = (int16_t)((yh << 8) | yl);

    *x_rate = (double)raw_x / ADXRS290_SENSITIVITY;
    *y_rate = (double)raw_y / ADXRS290_SENSITIVITY;

    return 0;
}

static void add_to_buffer(circular_buffer_t *buffer, struct timespec ts, double angular_velocity) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->buffer[buffer->head].timestamp = ts;
    buffer->buffer[buffer->head].angular_velocity = angular_velocity;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

static void check_threshold(double angular_velocity) {
    if (fabs(angular_velocity) > THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    if (pthread_mutex_init(&gyro_buffer.mutex, NULL) != 0) {
        fprintf(stderr, "Error: mutex initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct timespec ts;
    double x_rate, y_rate;

    while (running) {
        if (read_gyro_data(&x_rate, &y_rate) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &ts);
            add_to_buffer(&gyro_buffer, ts, x_rate);
            check_threshold(x_rate);
        } else {
            fprintf(stderr, "Error: Failed to read gyro data\n");
        }
        gpioDelay(10000);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    spiClose(spi_handle);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    pthread_mutex_destroy(&gyro_buffer.mutex);
    return 0;
}

