#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27
#define PWM_RANGE 255
#define PWM_FREQUENCY 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(LAMP1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LAMP1_GPIO);
        return -1;
    }
    if (gpioSetMode(LAMP2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LAMP2_GPIO);
        return -1;
    }
    if (gpioSetMode(LAMP3_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LAMP3_GPIO);
        return -1;
    }

    if (gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", LAMP1_GPIO);
        return -1;
    }
    if (gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", LAMP2_GPIO);
        return -1;
    }
    if (gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", LAMP3_GPIO);
        return -1;
    }

    if (gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", LAMP1_GPIO);
        return -1;
    }
    if (gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", LAMP2_GPIO);
        return -1;
    }
    if (gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", LAMP3_GPIO);
        return -1;
    }

    return 0;
}

static void set_lamp_brightness(int gpio, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    gpioPWM(gpio, brightness);
}

static void turn_off_all_lamps(void) {
    set_lamp_brightness(LAMP1_GPIO, 0);
    set_lamp_brightness(LAMP2_GPIO, 0);
    set_lamp_brightness(LAMP3_GPIO, 0);
}

static void fade_lamp(int gpio, int duration_seconds) {
    if (duration_seconds <= 0) return;

    int step_delay_us = (duration_seconds * 1000000) / PWM_RANGE;
    if (step_delay_us < 1000) step_delay_us = 1000;

    for (int i = PWM_RANGE; i >= 0; i--) {
        if (!running) break;
        set_lamp_brightness(gpio, i);
        gpioDelay(step_delay_us);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        fprintf(stderr, "  fade_duration_seconds: 1-3600\n");
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long duration = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: invalid fade duration '%s'. Must be an integer between 1 and 3600.\n", argv[1]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started. Fade duration: %ld seconds\n", duration);
    printf("Lamp 1: GPIO%d | Lamp 2: GPIO%d | Lamp 3: GPIO%d\n", LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO);
    printf("Press Ctrl+C to exit at any time.\n");

    int lamps[] = {LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO};
    int num_lamps = sizeof(lamps) / sizeof(lamps[0]);

    for (int i = 0; i < num_lamps && running; i++) {
        printf("Fading lamp on GPIO%d (full brightness)...\n", lamps[i]);
        set_lamp_brightness(lamps[i], PWM_RANGE);
        fade_lamp(lamps[i], duration);
        if (!running) break;
        printf("Lamp on GPIO%d faded to off.\n", lamps[i]);
    }

    turn_off_all_lamps();
    printf("All lamps turned off. Exiting.\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

