#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define AMBER_PIN  24

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_line(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static int all_off(struct gpiod_line *r, struct gpiod_line *y, struct gpiod_line *g, struct gpiod_line *a) {
    if (set_line(r, 1) || set_line(y, 1) || set_line(g, 1) || set_line(a, 1))
        return -1;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red = NULL, *yellow = NULL, *green = NULL, *amber = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    red   = gpiod_chip_get_line(chip, RED_PIN);
    yellow = gpiod_chip_get_line(chip, YELLOW_PIN);
    green  = gpiod_chip_get_line(chip, GREEN_PIN);
    amber  = gpiod_chip_get_line(chip, AMBER_PIN);
    if (!red || !yellow || !green || !amber) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(red,   "traffic-light", 1) < 0 ||
        gpiod_line_request_output(yellow, "traffic-light", 1) < 0 ||
        gpiod_line_request_output(green,  "traffic-light", 1) < 0 ||
        gpiod_line_request_output(amber,  "traffic-light", 1) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Traffic light simulator started. Press Ctrl+C to exit.\n");

    while (running) {
