#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5D
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5E
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed: reg=0x%02X val=0x%02X rc=%d", reg, value, rc);
        log_message(msg);
    }
    return rc;
}

static int mpr121_init(int handle) {
    if (mpr121_write(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(1000);
    if (mpr121_write(handle, MPR121_CONFIG2, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_ELECTRODE_CONFIG, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_TOUCHTH_0, 0x0A) < 0) return -1;
    if (mpr121_write(handle, MPR121_RELEASETH_0, 0x08) < 0) return -1;
    if (mpr121_write(handle, MPR121_DEBOUNCE, 0x21) < 0) return -1;
    if (mpr121_write(handle, MPR121_CONFIG1, 0x0D) < 0) return -1;
    if (mpr121_write(handle, MPR121_CONFIG2, 0x0D) < 0) return -1;
    return 0;
}

static int read_touch_status(int handle) {
    int lsb = i2cReadByteData(handle, MPR121_TOUCHSTATUS_L);
    if (lsb < 0) {
        log_message("Failed to read touch status LSB");
        return -1;
    }
    int msb = i2cReadByteData(handle, MPR121_TOUCHSTATUS_H);
    if (msb < 0) {
        log_message("Failed to read touch status MSB");
        return -1;
    }
    return (msb << 8) | lsb;
}

int main(void) {
    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        fclose(log_file);
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to open I2C device at 0x%02X: %d", MPR121_ADDR, i2c_handle);
        log_message(msg);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    if (mpr121_init(i2c_handle) < 0) {
        log_message("MPR121 initialisation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int last_touch = 0;
    int relay_state = 0;

    while (running) {
        int touch = read_touch_status(i2c_handle);
        if (touch < 0) {
            gpioDelay(10000);
            continue;
        }

        if (touch & 0x01) {
            if (!last_touch) {
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state);
                char msg[128];
                snprintf(msg, sizeof(msg), "Relay toggled to %s", relay_state ? "ON" : "OFF");
                log_message(msg);
            }
            gpioDelay(100000);
        } else {
            last_touch = 0;
            gpioDelay(10000);
        }
    }

    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file) fclose(log_file);
    return 0;
}

