#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

// Motor A pins
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B pins
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// L298N enable pins (must be HIGH for PWM control)
#define ENABLE_A 24
#define ENABLE_B 25

// PID constants
#define KP 1.0
#define KI 0.01
#define KD 0.1

// Obstacle avoidance threshold
#define OBSTACLE_THRESHOLD 20.0

// Global variables
static volatile int running = 1;
FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void set_motor_speed(int motor, int speed);
void stop_motors();
float calculate_tilt_error();
float calculate_distance();
void control_motors(float tilt_error, float distance);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void obstacle_avoidance(float distance);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set motor pins as outputs
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);

    // Set enable pins as outputs and ensure HIGH for PWM control
    gpioSetMode(ENABLE_A, PI_OUTPUT);
    gpioSetMode(ENABLE_B, PI_OUTPUT);
    gpioWrite(ENABLE_A, 1);
    gpioWrite(ENABLE_B, 1);

    return 0;
}

// Set motor speed (range: -255 to 255)
void set_motor_speed(int motor, int speed) {
    if (speed > 255) speed = 255;
    if (speed < -255) speed = -255;

    if (motor == 1) {
        if (speed > 0) {
            gpioWrite(MOTOR_A_FORWARD, 1);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(MOTOR_A_FORWARD, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 1);
            gpioPWM(MOTOR_A_BACKWARD, -speed);
        } else {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 0);
        }
    } else if (motor == 2) {
        if (speed > 0) {
            gpioWrite(MOTOR_B_FORWARD, 1);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(MOTOR_B_FORWARD, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 1);
            gpioPWM(MOTOR_B_BACKWARD, -speed);
        } else {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 0);
        }
    }
}

// Stop both motors
void stop_motors() {
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
}

// Calculate tilt error (simulated random float between -10.0 and 10.0)
float calculate_tilt_error() {
    return ((float)rand() / RAND_MAX) * 20.0 - 10.0;
}

// Calculate distance (simulated random float between 2.0 and 400.0 cm)
float calculate_distance() {
    return ((float)rand() / RAND_MAX) * 398.0 + 2.0;
}

// PID control for motors
void control_motors(float tilt_error, float distance) {
    static float integral = 0.0;
    static float previous_error = 0.0;
    float output;
    float dt = 0.05; // 50 ms

    // Proportional term
    float proportional = KP * tilt_error;

    // Integral term
    integral += KI * tilt_error * dt;
    if (integral > 255.0) integral = 255.0;
    if (integral < -255.0) integral = -255.0;

    // Derivative term
    float derivative = KD * (tilt_error - previous_error) / dt;
    output = proportional + integral + derivative;

    // Clamp output to -255 to 255
    if (output > 255.0) output = 255.0;
    if (output < -255.0) output = -255.0;

    // Update previous error
    previous_error = tilt_error;

    // Set motor speeds
    set_motor_speed(1, (int)output);
    set_motor_speed(2, (int)output);

    // Obstacle avoidance
    obstacle_avoidance(distance);
}

// Obstacle avoidance logic
void obstacle_avoidance(float distance) {
    if (distance < OBSTACLE_THRESHOLD) {
        // Reverse both motors at 50% speed
        set_motor_speed(1, -128);
        set_motor_speed(2, -128);
        gpioDelay(500000); // 500 ms
        stop_motors();
    }
}

// Log data to file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f, %d, %d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main() {
    // Seed random number generator
    srand(time(NULL));

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("balance_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Calculate tilt error and distance
        float tilt_error = calculate_tilt_error();
        float distance = calculate_distance();

        // Control motors
        control_motors(tilt_error, distance);

        // Log data
        int motor_a_speed = gpioGetPWMdutycycle(MOTOR_A_FORWARD) - gpioGetPWMdutycycle(MOTOR_A_BACKWARD);
        int motor_b_speed = gpioGetPWMdutycycle(MOTOR_B_FORWARD) - gpioGetPWMdutycycle(MOTOR_B_BACKWARD);
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay 50 ms
        gpioDelay(50000);
    }

    // Cleanup
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

