#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pin as input with internal pull-down */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output and ensure it starts OFF */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d LOW.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart light switch ready. Touch sensor on GPIO%d, relay on GPIO%d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    int relay_state = 0;

    while (running) {
        /* Read touch sensor (returns 0 or 1) */
        int touch = gpioRead(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n", TOUCH_SENSOR_PIN);
            gpioDelay(DEBOUNCE_DELAY_US);
            continue;
        }

        if (touch == 1) {
            /* Debounce: wait and re-read */
            gpioDelay(DEBOUNCE_DELAY_US);
            touch = gpioRead(TOUCH_SENSOR_PIN);
            if (touch < 0) {
                fprintf(stderr, "Warning: gpioRead failed on GPIO%d during debounce.\n", TOUCH_SENSOR_PIN);
                continue;
            }
            if (touch == 1) {
                /* Confirmed touch: toggle relay */
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error: gpioWrite failed on GPIO%d.\n", RELAY_PIN);
                } else {
                    printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
                }
                /* Wait for release to avoid repeated toggles */
                while (running) {
                    int r = gpioRead(TOUCH_SENSOR_PIN);
                    if (r < 0) {
                        fprintf(stderr, "Warning: gpioRead failed on GPIO%d during release wait.\n", TOUCH_SENSOR_PIN);
                        break;
                    }
                    if (r == 0) break;
                    gpioDelay(DEBOUNCE_DELAY_US);
                }
            }
        }

        /* Small idle delay to prevent busy-waiting */
        gpioDelay(10000); /* 10 ms */
    }

    /* Clean shutdown: ensure relay is OFF */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nSmart light switch terminated cleanly.\n");
    return EXIT_SUCCESS;
}

