/*
 * mood_light.c — Raspberry Pi 3 Model B+
 *
 * Reads ambient noise from ALSA (default device) at 8000 Hz, 16-bit LE,
 * 1 channel, computes RMS amplitude, and drives a common-cathode RGB LED
 * on GPIO17/18/27 using pigpio software PWM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lpigpio -lm
 * Run:    sudo ./mood_light [sensitivity]
 *
 * Compile with -DALSA_AVAILABLE to enable ALSA audio capture.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#if defined(ALSA_AVAILABLE)
#include <alsa/asoundlib.h>
#endif

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define SAMPLE_RATE     8000
#define PERIOD_FRAMES   1024
#define PERIOD_US       (1000000 / SAMPLE_RATE)
#define UPDATE_DELAY_US 10000

#define DEFAULT_SENSITIVITY 1.0f

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Color mapping ---------------------------------------------------- */

static void hsv_to_rgb(float h, float s, float v, int *r, int *g, int *b)
{
    float c = v * s;
    float h1 = h * 6.0f;
    float x = c * (1.0f - fabsf(fmodf(h1, 2.0f) - 1.0f));
    float m = v - c;

    if (h1 < 1.0f)   { *r = (int)((c + m) * 255.0f); *g = (int)((x + m) * 255.0f); *b = (int)(m * 255.0f); }
    else if (h1 < 2.0f) { *r = (int)((x + m) * 255.0f); *g = (int)((c + m) * 255.0f); *b = (int)(m * 255.0f); }
    else if (h1 < 3.0f) { *r = (int)(m * 255.0f); *g = (int)((c + m) * 255.0f); *b = (int)((x + m) * 255.0f); }
    else if (h1 < 4.0f) { *r = (int)(m * 255.0f); *g = (int)((x + m) * 255.0f); *b = (int)((c + m) * 255.0f); }
    else if (h1 < 5.0f) { *r = (int)((x + m) * 255.0f); *g = (int)(m * 255.0f); *b = (int)((c + m) * 255.0f); }
    else               { *r = (int)((c + m) * 255.0f); *g = (int)(m * 255.0f); *b = (int)((x + m) * 255.0f); }
}

static void set_led_color(int r, int g, int b)
{
    if (r < 0) r = 0; if (r > 255) r = 255;
    if (g < 0) g = 0; if (g > 255) g = 255;
    if (b < 0) b = 0; if (b > 255) b = 255;

    gpioPWM(RED_PIN,   r);
    gpioPWM(GREEN_PIN, g);
    gpioPWM(BLUE_PIN,  b);
}

/* ---- RMS computation -------------------------------------------------- */

static float calculate_rms(const short *buffer, int n, float sensitivity)
{
    if (n <= 0) return 0.0f;
    if (sensitivity <= 0.0f) sensitivity = DEFAULT_SENSITIVITY;

    double sum_sq = 0.0;
    for (int i = 0; i < n; i++)
        sum_sq += (double)buffer[i] * buffer[i];

    double rms = sqrt(sum_sq / (double)n);
    return (float)(rms * sensitivity);
}

/* ---- ALSA audio capture ----------------------------------------------- */

#if defined(ALSA_AVAILABLE)
static int init_alsa(snd_pcm_t **handle)
{
    int err;
    snd_pcm_hw_params_t *hw;

    err = snd_pcm_open(handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_open failed: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_malloc(&hw);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_malloc failed: %s\n", snd_strerror(err));
        snd_pcm_close(*handle);
        *handle = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_any(*handle, hw);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_any failed: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw);
        snd_pcm_close(*handle);
        *handle = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_set_access(*handle, hw, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_access failed: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw);
        snd_pcm_close(*handle);
        *handle = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_set_format(*handle, hw, SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_format failed: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw);
        snd_pcm_close(*handle);
        *handle = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_set_channels(*handle, hw, 1);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_channels failed: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw);
        snd_pcm_close(*handle);
        *handle = NULL;
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    err = snd_pcm_hw_params_set_rate_near(*handle, hw, &rate, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_rate_near failed: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw);
        snd_pcm_close(*handle);
        *handle = NULL;
        return -1;
    }

    err = snd_pcm_hw_params(*handle, hw);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params failed: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw);
        snd_pcm_close(*handle);
        *handle = NULL;
        return -1;
    }

    snd_pcm_hw_params_free(hw);
    return 0;
}

static int read_audio(snd_pcm_t *handle, short *buffer, int n)
{
    int err = snd_pcm_readi(handle, buffer, n);
    if (err == -EPIPE) {
        fprintf(stderr, "ALSA buffer overrun — recovering...\n");
        snd_pcm_prepare(handle);
        return -1;
    }
    if (err == -ESTRPIPE) {
        fprintf(stderr, "ALSA suspended — resuming...\n");
        snd_pcm_resume(handle);
        return -1;
    }
    if (err < 0) {
        fprintf(stderr, "snd_pcm_readi failed: %s\n", snd_strerror(err));
        return -1;
    }
    return 0;
}

static void close_alsa(snd_pcm_t *handle)
{
    if (handle) {
        snd_pcm_drain(handle);
        snd_pcm_close(handle);
    }
}
#else
static int init_alsa(snd_pcm_t **handle) { (void)handle; return 0; }
static int read_audio(snd_pcm_t *handle, short *buffer, int n) { (void)handle; (void)buffer; (void)n; return 0; }
static void close_alsa(snd_pcm_t *handle) { (void)handle; }
#endif

/* ---- Main ------------------------------------------------------------- */

int main(int argc, char *argv[])
{
    float sensitivity = DEFAULT_SENSITIVITY;
    if (argc > 1) {
        float f = strtof(argv[1], NULL);
        if (f <= 0.0f) {
            fprintf(stderr, "Invalid sensitivity '%s' (must be positive)\n", argv[1]);
            return EXIT_FAILURE;
        }
        sensitivity = f;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    snd_pcm_t *alsa_handle = NULL;
    int alsa_ok = 0;

#if defined(ALSA_AVAILABLE)
    if (init_alsa(&alsa_handle) == 0) {
        alsa_ok = 1;
        printf("ALSA audio initialized (default, %d Hz, 1 ch)\n", SAMPLE_RATE);
    } else {
        fprintf(stderr, "ALSA unavailable — using simulated audio\n");
    }
#else
    fprintf(stderr, "ALSA support not compiled in — using simulated audio\n");
#endif

    short *audio_buffer = malloc(PERIOD_FRAMES * sizeof(short));
    if (!audio_buffer) {
        fprintf(stderr, "Failed to allocate audio buffer: %s\n", strerror(errno));
        close_alsa(alsa_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Mood light running. Ctrl+C to exit.\n");

    while (g_running) {
        float rms = 0.0f;

        if (alsa_ok) {
            int n = PERIOD_FRAMES;
            while (n > 0 && g_running) {
                int got = read_audio(alsa_handle, audio_buffer, n);
                if (got < 0) {
                    usleep(10000);
                    continue;
                }
                n -= got;
            }
            if (n != 0) {
                fprintf(stderr, "Audio read interrupted\n");
                break;
            }
            rms = calculate_rms(audio_buffer, PERIOD_FRAMES, sensitivity);
        } else {
            /* Simulated audio: sine wave over one period */
            for (int i = 0; i < PERIOD_FRAMES; i++) {
                float phase = (float)i / (float)PERIOD_FRAMES * 2.0f * (float)M_PI;
                audio_buffer[i] = (short)(1000.0f * sinf(phase));
            }
            rms = calculate_rms(audio_buffer, PERIOD_FRAMES, sensitivity);
        }

        /* Non-linear color mapping */
        float hue = 0.0f;
        if (rms > 0.0f) {
            hue = 0.5f + 0.5f * atan2f(0.0f, rms) / (float)M_PI;
        }

        int r, g, b;
        hsv_to_rgb(hue, 1.0f, 1.0f, &r, &g, &b);
        set_led_color(r, g, b);

        printf("RMS: %.2f  Hue: %.2f  RGB: %d %d %d\n", rms, hue, r, g, b);

        usleep(UPDATE_DELAY_US);
    }

    /* Cleanup */
    set_led_color(0, 0, 0);
    free(audio_buffer);
    close_alsa(alsa_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

