        fprintf(stderr, "snd_pcm_hw_params_set_access failed: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw);
        snd_pcm_close(*handle);
        *handle = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_set_format(*handle, hw, SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_format failed: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw);
        snd_pcm_close(*handle);
        *handle = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_set_channels(*handle, hw, 1);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_channels failed: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw);
        snd_pcm_close(*handle);
        *handle = NULL;
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    err = snd_pcm_hw_params_set_rate_near(*handle, hw, &rate, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_rate_near failed: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw);
        snd_pcm_close(*handle);
        *handle = NULL;
        return -1;
    }

    err = snd_pcm_hw_params(*handle, hw);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params failed: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw);
        snd_pcm_close(*handle);
        *handle = NULL;
        return -1;
    }

    snd_pcm_hw_params_free(hw);
    return 0;
}

static int read_audio(snd_pcm_t *handle, short *buffer, int n)
{
    int err = snd_pcm_readi(handle, buffer, n);
    if (err == -EPIPE) {
        fprintf(stderr, "ALSA buffer overrun — recovering...\n");
        snd_pcm_prepare(handle);
        return -1;
    }
    if (err == -ESTRPIPE) {
        fprintf(stderr, "ALSA suspended — resuming...\n");
        snd_pcm_resume(handle);
        return -1;
    }
    if (err < 0) {
        fprintf(stderr, "snd_pcm_readi failed: %s\n", snd_strerror(err));
        return -1;
    }
    return 0;
}

static void close_alsa(snd_pcm_t *handle)
{
    if (handle) {
        snd_pcm_drain(handle);
        snd_pcm_close(handle);
    }
}
