#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CHIP_NAME "gpiochip0"
#define RELAY_PINS {17, 27, 22, 23}
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_seconds(int seconds) {
    for (int i = 0; i < seconds && running; i++) {
        sleep(1);
    }
}

static void set_relay(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Failed to set relay value");
    }
}

static void all_off(struct gpiod_line *lines[], int num) {
    for (int i = 0; i < num; i++) {
        set_relay(lines[i], 1);
    }
}

static void sunrise_phase(struct gpiod_line *lines[], int num) {
    printf("Sunrise phase started\n");
    for (int i = 0; i < SUNRISE_DURATION && running; i++) {
        int duty = (i * 255) / SUNRISE_DURATION;
        for (int j = 0; j < num; j++) {
            set_relay(lines[j], (duty > 127) ? 0 : 1);
        }
        usleep(100000);
    }
    all_off(lines, num);
    printf("Sunrise phase complete\n");
}

