#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>

#define MOTION_SENSOR_GPIO 17
#define VIDEO_DURATION_SEC 5
#define DEBOUNCE_MS 200
#define LOG_FILE_PATH "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: %s exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        perror("mkdir");
        return -1;
    }
    return 0;
}

static int log_motion_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    char filename[256];
    char command[512];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("localtime");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

    snprintf(filename, sizeof(filename), "%s%s.h264", VIDEO_DIR, timestamp);

    snprintf(command, sizeof(command),
             "raspivid -o %s -t %d 2>/dev/null",
             filename, VIDEO_DURATION_SEC * 1000);

    if (system(command) != 0) {
        fprintf(stderr, "Error: raspivid command failed for %s\n", filename);
        return -1;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s Motion detected, video saved: %s\n", timestamp, filename);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open\n");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (ensure_directory(VIDEO_DIR) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_PATH, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTION_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", MOTION_SENSOR_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", MOTION_SENSOR_GPIO);

    uint32_t last_trigger_tick = 0;

    while (running) {
        int level = gpioRead(MOTION_SENSOR_GPIO);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed for GPIO %d\n", MOTION_SENSOR_GPIO);
            break;
        }

        if (level == 0) {
            uint32_t now = gpioTick();
            if (now - last_trigger_tick > DEBOUNCE_MS * 1000) {
                if (log_motion_event() == 0) {
                    printf("Motion detected and video recorded.\n");
                }
                last_trigger_tick = now;
            }
        }

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

