#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0f
#define I2C_BUS 1
#define MAX_REINIT_ATTEMPTS 3
#define SAMPLE_INTERVAL_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_mpu6050(void) {
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake MPU-6050 (PWR_MGMT_1): %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100000);
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Failed to set sample rate divider: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set gyro config: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read gyro data block: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void log_data(FILE *fp, double timestamp, float x, float y, float z) {
    fprintf(fp, "%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("gyro_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }

    while (!terminate) {
        int16_t raw_x, raw_y, raw_z;
        int attempt;

        for (attempt = 0; attempt < MAX_REINIT_ATTEMPTS; attempt++) {
            if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
                float x = (float)raw_x / GYRO_SENSITIVITY;
                float y = (float)raw_y / GYRO_SENSITIVITY;
                float z = (float)raw_z / GYRO_SENSITIVITY;
                struct timespec ts;
                clock_gettime(CLOCK_REALTIME, &ts);
                double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
                log_data(log_file, timestamp, x, y, z);
                break;
            }
            fprintf(stderr, "Warning: Read attempt %d/%d failed, re-initializing sensor...\n", attempt + 1, MAX_REINIT_ATTEMPTS);
            gpioDelay(100000);
            if (init_mpu6050() < 0) {
                fprintf(stderr, "Error: Re-initialization failed after attempt %d\n", attempt + 1);
            }
        }
        if (attempt == MAX_REINIT_ATTEMPTS) {
            fprintf(stderr, "Error: Max re-initialization attempts reached, continuing to log errors...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

