    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }

    while (!terminate) {
        int16_t raw_x, raw_y, raw_z;
        int attempt;

        for (attempt = 0; attempt < MAX_REINIT_ATTEMPTS; attempt++) {
            if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
                float x = (float)raw_x / GYRO_SENSITIVITY;
                float y = (float)raw_y / GYRO_SENSITIVITY;
                float z = (float)raw_z / GYRO_SENSITIVITY;
                struct timespec ts;
                clock_gettime(CLOCK_REALTIME, &ts);
                double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
                log_data(log_file, timestamp, x, y, z);
                break;
            }
            fprintf(stderr, "Warning: Read attempt %d/%d failed, re-initializing sensor...\n", attempt + 1, MAX_REINIT_ATTEMPTS);
            gpioDelay(100000);
            if (init_mpu6050() < 0) {
                fprintf(stderr, "Error: Re-initialization failed after attempt %d\n", attempt + 1);
            }
        }
        if (attempt == MAX_REINIT_ATTEMPTS) {
            fprintf(stderr, "Error: Max re-initialization attempts reached, continuing to log errors...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

