    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    srand((unsigned int)time(NULL));

    while (running) {
        int sensor_reading = read_moisture_sensor();
        int relay_state = (sensor_reading < MOISTURE_THRESHOLD) ? 0 : 1;

        if (control_relay(RELAY1_PIN, relay_state) != 0) {
            break;
        }
        if (control_relay(RELAY2_PIN, relay_state) != 0) {
            break;
        }
        if (control_relay(RELAY3_PIN, relay_state) != 0) {
            break;
        }
        if (control_relay(RELAY4_PIN, relay_state) != 0) {
            break;
        }

        if (log_data(sensor_reading, relay_state) != 0) {
            break;
        }

        gpioDelay(SENSOR_READ_INTERVAL * 1000000);
    }

    cleanup();
    return 0;
}

