#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define FREEFALL_THRESHOLD 0.2f
#define FREEFALL_DURATION 0.5f
#define FREEFALL_CONFIRMED_DURATION 0.5f
#define ALARM_GPIO 27
#define SAMPLE_INTERVAL_US 100000
#define FREEFALL_CONFIRMED_DELAY_US 500000
#define ALARM_HOLD_US 5000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int adxl345_init(int handle) {
    if (i2cWriteByteData(handle, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing DATA_FORMAT register\n");
        return -1;
    }
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing POWER_CTL register\n");
        return -1;
    }
    return 0;
}

static int read_accelerometer(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;
    return 0;
}

static int detect_freefall(float x, float y, float z) {
    return (fabsf(x) < FREEFALL_THRESHOLD && fabsf(y) < FREEFALL_THRESHOLD && fabsf(z) < FREEFALL_THRESHOLD);
}

static void log_freefall(float x, float y, float z) {
    FILE *fp = fopen("freefall.log", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (adxl345_init(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0);
    signal(SIGINT, signal_handler);
    float x, y, z;
    int freefall_count = 0;
    int freefall_confirmed = 0;
    while (!terminate) {
        if (read_accelerometer(i2c_handle, &x, &y, &z) == 0) {
            if (detect_freefall(x, y, z)) {
                freefall_count++;
                if (freefall_count >= (int)(FREEFALL_DURATION / FREEFALL_CONFIRMED_DURATION)) {
                    freefall_confirmed = 1;
                }
            } else {
                freefall_count = 0;
                freefall_confirmed = 0;
            }
            if (freefall_confirmed) {
                printf("Freefall detected!\n");
                log_freefall(x, y, z);
                gpioWrite(ALARM_GPIO, 1);
                gpioDelay(ALARM_HOLD_US);
                gpioWrite(ALARM_GPIO, 0);
                freefall_confirmed = 0;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    gpioWrite(ALARM_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

