#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pthread.h>
#include <pigpio.h>

#define TRIG_PIN 4
#define ECHO_PIN 18

#define TRIGGER_PULSE_US 10
#define MEASUREMENT_INTERVAL_US 200000
#define MAX_ECHO_US 23200
#define TIMEOUT_US 100000

#define LOG_FILE "distance_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

static volatile uint32_t pulse_start_tick = 0;
static volatile uint32_t pulse_end_tick = 0;
static volatile int pulse_ready = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    pthread_mutex_lock(&pulse_mutex);
    if (level == 1) {
        pulse_start_tick = tick;
    } else if (level == 0) {
        pulse_end_tick = tick;
        pulse_ready = 1;
    }
    pthread_mutex_unlock(&pulse_mutex);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIG_PIN %d as output.\n", TRIG_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN %d.\n", ECHO_PIN);
    }

    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to set ISR for ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

static double calculate_distance(uint32_t pulse_width_us) {
    return (double)pulse_width_us * 0.01715;
}

static int log_distance(double distance_cm) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    uint64_t timestamp_ns = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;

    if (fprintf(log_file, "%llu,%.2f\n", (unsigned long long)timestamp_ns, distance_cm) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioWrite(TRIG_PIN, 0);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    pthread_mutex_destroy(&pulse_mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        pulse_ready = 0;
        pulse_start_tick = 0;
        pulse_end_tick = 0;

        trigger_sensor();

        uint32_t start_tick = gpioTick();
        uint32_t elapsed = 0;

        while (running && elapsed < TIMEOUT_US) {
            if (pulse_ready) {
                break;
            }
            gpioDelay(100);
            uint32_t now = gpioTick();
            elapsed = now - start_tick;
        }

        if (!running) {
            break;
        }

        if (!pulse_ready) {
            fprintf(stderr, "Warning: echo timeout (no response within %d us).\n", TIMEOUT_US);
            gpioDelay(MEASUREMENT_INTERVAL_US);
            continue;
        }

        pthread_mutex_lock(&pulse_mutex);
        uint32_t pulse_width = pulse_end_tick - pulse_start_tick;
        pthread_mutex_unlock(&pulse_mutex);

        if (pulse_width > MAX_ECHO_US) {
            fprintf(stderr, "Warning: pulse width %u us exceeds max (%d us).\n", pulse_width, MAX_ECHO_US);
            gpioDelay(MEASUREMENT_INTERVAL_US);
            continue;
        }

        double distance = calculate_distance(pulse_width);
        if (log_distance(distance) != 0) {
            fprintf(stderr, "Error: failed to log distance.\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL_US);
    }

    cleanup();
    printf("Program terminated.\n");
    return 0;
}

