static int i2c_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (i2cWriteDevice(i2c_handle, buf, 2) == 0) return 0;
        gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (i2cWriteDevice(i2c_handle, reg_buf, 1) == 0) {
            char data[1];
            if (i2cReadDevice(i2c_handle, data, 1) == 1) {
                *value = (uint8_t)data[0];
                return 0;
            }
        }
        gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = {(char)reg};
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (i2cWriteDevice(i2c_handle, reg_buf, 1) == 0) {
            if (i2cReadDevice(i2c_handle, (char *)buf, len) == (int)len) return 0;
