    (void)sig;
    shutdown_requested = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(i2c_handle, reg, val) < 0) {
        fprintf(stderr, "Error writing reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int init_lis3dh(int addr) {
    if (write_reg(CTRL_REG1, 0x57) < 0) return -1;
    if (write_reg(CTRL_REG4, 0x88) < 0) return -1;
    return 0;
}

static int read_accel(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buf, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        *x = *y = *z = 0;
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void log_event(int16_t x, int16_t y, int16_t z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", ts, x, y, z);
    fclose(fp);
}

static void shutdown_system(void) {
    printf("Shutting down system...\n");
    fflush(stdout);
    int rc = system("sudo shutdown -h now");
    if (rc == -1) {
        fprintf(stderr, "Failed to execute shutdown command\n");
    }
}

int main(int argc, char *argv[]) {
    int addr = LIS3DH_ADDR_DEFAULT;
    float threshold = SHUTDOWN_THRESHOLD_G;

    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                addr = (int)strtol(optarg, NULL, 0);
                if (addr < 0x08 || addr > 0x77) {
                    fprintf(stderr, "Invalid I2C address: 0x%02X (must be 0x08-0x77)\n", addr);
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Threshold must be greater than 0\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-t threshold_g]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", addr, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lis3dh(addr) < 0) {
        fprintf(stderr, "Error initializing LIS3DH at 0x%02X\n", addr);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("Monitoring acceleration (threshold: %.2f g)...\n", threshold);

    while (!shutdown_requested) {
        int16_t x, y, z;
        if (read_accel(&x, &y, &z) == 0) {
            float gx = (float)x * ACCEL_SCALE;
            float gy = (float)y * ACCEL_SCALE;
            float gz = (float)z * ACCEL_SCALE;
            if (fabsf(gx) > threshold || fabsf(gy) > threshold || fabsf(gz) > threshold) {
                log_event(x, y, z);
                shutdown_system();
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

