/*
 * Line-following robot using SunFounder 3-Way Tracking Sensor (IR reflectance).
 * Board: Raspberry Pi 5
 * API: libgpiod (modern Linux GPIO character-device interface)
 *
 * Wiring:
 *   Sensor LEFT  -> GPIO4   (physical pin 7)
 *   Sensor CENTER-> GPIO17  (physical pin 11)
 *   Sensor RIGHT -> GPIO27  (physical pin 13)
 *   Alert LED/Buzzer-> GPIO22 (physical pin 15) - active-high
 *
 * Build: gcc -O2 -Wall -Wextra -o line_follow line_follow.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN    4
#define CENTER_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27
#define ALERT_PIN          22

#define BUFFER_SIZE        5
#define CONSECUTIVE_READINGS 5
#define ALERT_DURATION_SEC  2
#define POLL_INTERVAL_US    10000  /* 10 ms */

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */
typedef struct {
    int left[BUFFER_SIZE];
    int center[BUFFER_SIZE];
    int right[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    cb->head = 0;
    cb->count = 0;
    memset(cb->left, 0, sizeof(cb->left));
    memset(cb->center, 0, sizeof(cb->center));
    memset(cb->right, 0, sizeof(cb->right));
}

static void cb_push(CircularBuffer *cb, int l, int c, int r)
{
    cb->left[cb->head]  = l;
    cb->center[cb->head] = c;
    cb->right[cb->head] = r;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

/* ------------------------------------------------------------------ */
/* Motor control (placeholders)                                        */
/* ------------------------------------------------------------------ */
static void motor_forward(void)  { printf("Motor: forward\n");  }
static void motor_left(void)     { printf("Motor: left\n");     }
static void motor_right(void)    { printf("Motor: right\n");    }
static void motor_stop(void)     { printf("Motor: stop\n");     }

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void log_data(int l, int c, int r)
{
    printf("L:%d C:%d R:%d\n", l, c, r);
}

static void log_alert(void)
{
    printf("ALERT: no line detected for %d consecutive readings\n",
           CONSECUTIVE_READINGS);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_left = NULL, *line_center = NULL,
                      *line_right = NULL, *line_alert = NULL;
    CircularBuffer cb;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto out;

    /* Open the default gpiochip (gpiochip4 on Pi 5) */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        goto out;
    }

    line_left   = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    line_center = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    line_right  = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    line_alert  = gpiod_chip_get_line(chip, ALERT_PIN);

    if (!line_left || !line_center || !line_right || !line_alert) {
        fprintf(stderr, "Failed to get one or more GPIO lines: %s\n",
                strerror(errno));
        goto cleanup_chip;
    }

    /* Request sensor lines as inputs */
    if (gpiod_line_request_input(line_left, "line_follow_left") < 0) {
        fprintf(stderr, "Request LEFT line failed: %s\n", strerror(errno));
        goto cleanup_chip;
    }
    if (gpiod_line_request_input(line_center, "line_follow_center") < 0) {
        fprintf(stderr, "Request CENTER line failed: %s\n", strerror(errno));
        goto cleanup_chip;
    }
    if (gpiod_line_request_input(line_right, "line_follow_right") < 0) {
        fprintf(stderr, "Request RIGHT line failed: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    /* Request alert line as output, initial value LOW */
    if (gpiod_line_request_output(line_alert, "line_follow_alert", 0) < 0) {
        fprintf(stderr, "Request ALERT line failed: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    cb_init(&cb);

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int l = gpiod_line_get_value(line_left);
        int c = gpiod_line_get_value(line_center);
        int r = gpiod_line_get_value(line_right);

        if (l < 0 || c < 0 || r < 0) {
            fprintf(stderr, "GPIO read error: %s\n", strerror(errno));
            break;
        }

        cb_push(&cb, l, c, r);
        log_data(l, c, r);

        /* Consecutive no-line detection */
        int no_line_count = 0;
        for (int i = 0; i < cb.count; i++) {
            if (cb.center[i] == 1)
                no_line_count = 0;
            else
                no_line_count++;
            if (no_line_count >= CONSECUTIVE_READINGS) {
                log_alert();

                if (gpiod_line_set_value(line_alert, 1) < 0) {
                    fprintf(stderr, "Alert HIGH failed: %s\n", strerror(errno));
                    break;
                }
                sleep(ALERT_DURATION_SEC);
                if (gpiod_line_set_value(line_alert, 0) < 0) {
                    fprintf(stderr, "Alert LOW failed: %s\n", strerror(errno));
                    break;
                }
                no_line_count = 0;  /* reset so we don't spam */
            }
        }

        /* Line-following logic */
        if (c == 1) {
            motor_forward();
        } else if (l == 1) {
            motor_left();
        } else if (r == 1) {
            motor_right();
        } else {
            motor_stop();
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup_chip:
    /* Ensure alert is off on exit */
    if (line_alert)
        gpiod_line_set_value(line_alert, 0);

    if (line_left)   gpiod_line_release(line_left);
    if (line_center) gpiod_line_release(line_center);
    if (line_right)  gpiod_line_release(line_right);
    if (line_alert)  gpiod_line_release(line_alert);

    if (chip)
        gpiod_chip_close(chip);

out:
    printf("Exiting.\n");
    return ret;
}

