#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x30
#define RELAY_GPIO     17
#define FIELD_THRESHOLD_MT 5.0f
#define SAMPLE_PERIOD_US 100000
#define CONV_TIMEOUT_US  50000
#define CONV_POLL_US    1000
#define LOG_FILE        "magnetic_events.txt"

/* Si7210 register addresses */
#define REG_DEVICE_ID   0x00
#define REG_FIELD_LSB   0xC0
#define REG_FIELD_MSB   0xC1
#define REG_CTRL        0xC2
#define REG_CONFIG      0xC3
#define REG_INT_EN      0xC4
#define REG_INT_STS    0xC5

#define CTRL_ONE_SHOT   0x01
#define CTRL_MODE_CONT  0x00

#define EXPECTED_DEVICE_ID 0x72

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s %s\n", ts, msg);
    fclose(fp);
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte_checked(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C write failed: reg=0x%02X val=0x%02X rc=%d", reg, val, rc);
        log_event(buf);
        return -1;
    }
    return 0;
}

static int i2c_read_byte_checked(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C read failed: reg=0x%02X rc=%d", reg, rc);
        log_event(buf);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

static int read_field_raw(int handle, int16_t *raw)
{
    /* Start one-shot conversion */
    if (i2c_write_byte_checked(handle, REG_CTRL, CTRL_ONE_SHOT) < 0)
        return -1;

    /* Poll until conversion bit (bit 0) clears (0x00) */
    uint8_t status = 0xFF;
    int elapsed = 0;
    while (status != 0x00) {
        if (i2c_read_byte_checked(handle, REG_CTRL, &status) < 0)
            return -1;
        if (elapsed >= CONV_TIMEOUT_US) {
            log_event("Si7210 conversion timeout");
            return -1;
        }
        gpioDelay(CONV_POLL_US);
        elapsed += CONV_POLL_US;
    }

    /* Read 2 bytes from field data registers */
    uint8_t lsb = 0, msb = 0;
    if (i2c_read_byte_checked(handle, REG_FIELD_LSB, &lsb) < 0)
        return -1;
    if (i2c_read_byte_checked(handle, REG_FIELD_MSB, &msb) < 0)
        return -1;

    *raw = (int16_t)(((uint16_t)msb << 8) | (uint16_t)lsb);
    return 0;
}

static void control_relay(int state)
{
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        log_event("Failed to write relay GPIO");
        return;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "Relay %s", state ? "activated" : "deactivated");
    log_event(msg);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    log_event("Program terminated");
}

int main(void)
{
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "i2cOpen failed: %d", g_i2c_handle);
        log_event(buf);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify device identity */
    uint8_t dev_id = 0;
    if (i2c_read_byte_checked(g_i2c_handle, REG_DEVICE_ID, &dev_id) < 0) {
        log_event("Failed to read device ID");
        cleanup();
        return EXIT_FAILURE;
    }
    if (dev_id != EXPECTED_DEVICE_ID) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Unexpected device ID: 0x%02X (expected 0x%02X)",
                 dev_id, EXPECTED_DEVICE_ID);
        log_event(buf);
        cleanup();
        return EXIT_FAILURE;
    }

