#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define RELAY_GPIO 18
#define PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (client_fd >= 0) { close(client_fd); client_fd = -1; }
    if (server_fd >= 0) { close(server_fd); server_fd = -1; }
    if (log_file) { fclose(log_file); log_file = NULL; }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
    if (client_fd >= 0) { shutdown(client_fd, SHUT_RDWR); }
    if (server_fd >= 0) { shutdown(server_fd, SHUT_RDWR); }
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    return 0;
}

static int init_socket(void) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket creation failed");
        return -1;
    }
    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(fd);
        return -1;
    }
    return fd;
}

static int setup_server(int fd) {
    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);
    if (bind(fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(fd);
        return -1;
    }
    if (listen(fd, 3) < 0) {
        perror("listen failed");
        close(fd);
        return -1;
    }
    return 0;
}

static int handle_client(int fd) {
    char buffer[BUFFER_SIZE];
    ssize_t n = recv(fd, buffer, BUFFER_SIZE - 1, 0);
    if (n < 0) {
        perror("recv failed");
        return -1;
    }
    if (n == 0) {
        return 0;
    }
    buffer[n] = '\0';
    char *cmd = buffer;
    while (*cmd == ' ' || *cmd == '\t') cmd++;
    char *end = cmd + strlen(cmd);
    while (end > cmd && (end[-1] == ' ' || end[-1] == '\t' || end[-1] == '\n' || end[-1] == '\r')) end--;
    *end = '\0';
    if (strcasecmp(cmd, "ON") == 0) {
        gpioWrite(RELAY_GPIO, 1);
        log_event("Relay turned ON");
        send(fd, "OK\n", 3, 0);
    } else if (strcasecmp(cmd, "OFF") == 0) {
        gpioWrite(RELAY_GPIO, 0);
        log_event("Relay turned OFF");
        send(fd, "OK\n", 3, 0);
    } else {
        log_event("Invalid command received");
        send(fd, "ERROR: Invalid command\n", 22, 0);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }
    if (init_gpio() < 0) return 1;
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }
    server_fd = init_socket();
    if (server_fd < 0) { cleanup(); return 1; }
    if (setup_server(server_fd) < 0) { cleanup(); return 1; }
    printf("Listening on port %d...\n", PORT);
    log_event("Server started");
    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("accept failed");
            continue;
        }
        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, ip, sizeof(ip));
        printf("Connection from %s:%d\n", ip, ntohs(client_addr.sin_port));
        log_event("Connection accepted");
        while (running && handle_client(client_fd) == 0) {
            usleep(10000);
        }
        if (client_fd >= 0) { close(client_fd); client_fd = -1; }
    }
    log_event("Server shutting down");
    cleanup();
    return 0;
}

