#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS              1
#define SENSOR1_ADDR         0x08
#define SENSOR2_ADDR         0x09
#define RELAY_GPIO           18
#define FLOW_THRESHOLD       5.0f
#define SCALE_FACTOR         (1.0f / 1500.0f)
#define POLL_DELAY_US        100000   /* 100 ms */
#define LOG_FILE             "flow_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c1 = -1;
static int g_i2c2 = -1;

/* ------------------------------------------------------------------ */
/* CRC-8 used by Sensirion: poly 0x31, init 0xFF, no final XOR         */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one sample from a SLF3S-1300F: 2 data bytes + 1 CRC byte       */
/* Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.         */
/* ------------------------------------------------------------------ */
static int read_flow_rate(int handle, float *flow_out)
{
    uint8_t buf[3];
    int n = i2cReadDevice(handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "[WARN] I2C read failed (handle %d, got %d bytes)\n",
                handle, n);
        return -1;
    }
    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[WARN] CRC mismatch on handle %d\n", handle);
        return -2;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw * SCALE_FACTOR;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Send start-measurement command (0x36 0x08)                         */
/* ------------------------------------------------------------------ */
static int start_measurement(int handle)
{
    uint8_t cmd[2] = { 0x36, 0x08 };
    int rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] start-measurement failed (handle %d, rc=%d)\n",
                handle, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Energize / de-energize relay                                        */
/* ------------------------------------------------------------------ */
static int set_relay(int state)
{
    int rc = gpioWrite(RELAY_GPIO, state);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d) failed (rc=%d)\n", state, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped flow reading to the log file                   */
/* ------------------------------------------------------------------ */
static void log_flow_data(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld,%.3f,%.3f\n", tbuf, ts.tv_nsec / 1000000L, f1, f2);
    fflush(fp);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Signal handler — just set the flag so the main loop exits          */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
