#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

#define POLL_INTERVAL_US 200000   /* 200 ms */
#define MOTOR_RUN_US 5000000      /* 5 s   */
#define DRY_STABLE_POLL_COUNT 3   /* 3 * 200 ms = ~600 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_write(unsigned pin, unsigned level, const char *label)
{
    if (gpioWrite(pin, level) != 0) {
        syslog(LOG_ERR, "gpioWrite(%u, %u) failed for %s", pin, level, label);
        return -1;
    }
    return 0;
}

static int motor_stop(void)
{
    if (safe_write(MOTOR_ENABLE_PIN, 0, "motor_enable") != 0)
        return -1;
    if (safe_write(MOTOR_IN1_PIN, 0, "motor_in1") != 0)
        return -1;
    if (safe_write(MOTOR_IN2_PIN, 0, "motor_in2") != 0)
        return -1;
    return 0;
}

static int motor_run(void)
{
    if (safe_write(MOTOR_ENABLE_PIN, 1, "motor_enable") != 0)
        return -1;
    if (safe_write(MOTOR_IN1_PIN, 1, "motor_in1") != 0)
        return -1;
    if (safe_write(MOTOR_IN2_PIN, 0, "motor_in2") != 0)
        return -1;
    return 0;
}

static int read_rain_sensor(void)
{
    int v = gpioRead(RAIN_SENSOR_PIN);
    if (v < 0) {
        syslog(LOG_ERR, "gpioRead(%d) failed", RAIN_SENSOR_PIN);
        return -1;
    }
    return v;
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure rain sensor pin as input with pull-up */
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_INPUT) failed", RAIN_SENSOR_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(%d, PI_PUD_UP) failed", RAIN_SENSOR_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure motor control pins as outputs, initialise LOW */
    if (gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_OUTPUT) failed", MOTOR_ENABLE_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_OUTPUT) failed", MOTOR_IN1_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_OUTPUT) failed", MOTOR_IN2_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (motor_stop() != 0) {
        syslog(LOG_ERR, "Initial motor_stop() failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed");
        motor_stop();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed");
        motor_stop();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain-actuated window controller started (GPIO %d sensor, ENA=%d IN1=%d IN2=%d)",
           RAIN_SENSOR_PIN, MOTOR_ENABLE_PIN, MOTOR_IN1_PIN, MOTOR_IN2_PIN);

    int last_rain = read_rain_sensor();
    if (last_rain < 0) {
        syslog(LOG_ERR, "Initial rain sensor read failed; aborting");
        motor_stop();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    int dry_stable_count = 0;

    while (g_running) {
        int rain = read_rain_sensor();
        if (rain < 0) {
            /* Sensor read failure: back off briefly and retry */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        /* Rising edge: dry -> wet transition */
        if (last_rain == 1 && rain == 0) {
            syslog(LOG_INFO, "Rain detected (dry -> wet)");
            if (motor_run() != 0) {
                syslog(LOG_ERR, "Failed to start motor");
            } else {
                syslog(LOG_INFO, "Motor running for %d us", MOTOR_RUN_US);
                usleep(MOTOR_RUN_US);
                if (motor_stop() != 0) {
                    syslog(LOG_ERR, "Failed to stop motor");
                } else {
                    syslog(LOG_INFO, "Motor stopped");
                }
            }
            /* Re-read after motor run to detect new rain state */
            int r = read_rain_sensor();
            if (r < 0) {
                syslog(LOG_ERR, "Re-read after motor run failed");
            } else {
                last_rain = r;
            }
            dry_stable_count = 0;
            continue;
        }

        /* Track dry state for the post-motor suppression */
        if (rain == 1) {
            dry_stable_count++;
            if (dry_stable_count >= DRY_STABLE_POLL_COUNT) {
                syslog(LOG_INFO, "Rain cleared (dry stable for %d polls)",
                       DRY_STABLE_POLL_COUNT);
                dry_stable_count = 0;
            }
        } else {
            dry_stable_count = 0;
        }

        last_rain = rain;
        usleep(POLL_INTERVAL_US);
    }

    /* Graceful shutdown */
    syslog(LOG_INFO, "Shutting down");
    motor_stop();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

