                       DRY_STABLE_POLL_COUNT);
                dry_stable_count = 0;
            }
        } else {
            dry_stable_count = 0;
        }

        last_rain = rain;
        usleep(POLL_INTERVAL_US);
    }

    /* Graceful shutdown */
    syslog(LOG_INFO, "Shutting down");
    motor_stop();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

