#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define BUTTON_LOCK    21
#define BUTTON_UNLOCK  22

#define PULSE_LOCKED   2000   /* µs — door locked */
#define PULSE_UNLOCKED 1000   /* µs — door unlocked */
#define PULSE_STOP     0      /* µs — stop servo */

#define DEBOUNCE_US    20000  /* 20 ms debounce */
#define POLL_US        10000  /* 10 ms poll interval */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo(int pin, int pulsewidth)
{
    if (gpioServo(pin, pulsewidth) < 0) {
        fprintf(stderr, "gpioServo(pin=%d, pw=%d) failed\n", pin, pulsewidth);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop the servo before terminating pigpio */
    gpioServo(SERVO_PIN, PULSE_STOP);
    gpioTerminate();
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure button pins as inputs with internal pull-ups --- */
    if (gpioSetMode(BUTTON_LOCK, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(BUTTON_LOCK) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUTTON_UNLOCK, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(BUTTON_UNLOCK) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_LOCK, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(BUTTON_LOCK) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_UNLOCK, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(BUTTON_UNLOCK) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Ensure servo is stopped at start --- */
    if (set_servo(SERVO_PIN, PULSE_STOP) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door lock control started.\n");
    printf("  Lock button : GPIO %d\n", BUTTON_LOCK);
    printf("  Unlock button: GPIO %d\n", BUTTON_UNLOCK);
    printf("  Servo       : GPIO %d\n", SERVO_PIN);
    printf("Press Ctrl+C to exit.\n");

    int last_lock    = 1;   /* pull-up idle high */
    int last_unlock  = 1;
    int last_lock_debounced = 1;
    int last_unlock_debounced = 1;

    while (g_running) {
        int cur_lock    = gpioRead(BUTTON_LOCK);
        int cur_unlock  = gpioRead(BUTTON_UNLOCK);

        /* --- Debounce: require stable reading for DEBOUNCE_US --- */
        if (cur_lock != last_lock) {
            if (gpioTick() - last_lock > DEBOUNCE_US) {
                last_lock = cur_lock;
                if (cur_lock == 0) {
                    last_lock_debounced = 0;
                }
            }
        }
        if (cur_unlock != last_unlock) {
            if (gpioTick() - last_unlock > DEBOUNCE_US) {
                last_unlock = cur_unlock;
                if (cur_unlock == 0) {
                    last_unlock_debounced = 0;
                }
            }
        }

        /* --- Process stable, debounced presses --- */
        if (last_lock_debounced == 0 && last_lock == 0) {
            printf("Locking door...\n");
            fflush(stdout);
            if (set_servo(SERVO_PIN, PULSE_LOCKED) == 0) {
                printf("Door locked.\n");
            } else {
                fprintf(stderr, "Failed to lock door.\n");
            }
            last_lock_debounced = 1;
            gpioDelay(DEBOUNCE_US);  /* wait for release */
        }

        if (last_unlock_debounced == 0 && last_unlock == 0) {
            printf("Unlocking door...\n");
            fflush(stdout);
            if (set_servo(SERVO_PIN, PULSE_UNLOCKED) == 0) {
                printf("Door unlocked.\n");
            } else {
                fprintf(stderr, "Failed to unlock door.\n");
            }
            last_unlock_debounced = 1;
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(POLL_US);  /* 10 ms — light CPU load */
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Door lock control stopped.\n");
    return EXIT_SUCCESS;
}

