#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN      4
#define FLOODLIGHT_PIN 17
#define FLOODLIGHT_ON_DURATION 60
#define POLL_DELAY_US 100000
#define LOG_FILE "security_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event_type, int duration_sec)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (duration_sec >= 0) {
        if (fprintf(fp, "%s - %s - Duration: %d seconds\n", ts, event_type, duration_sec) < 0) {
            perror("fprintf");
            fclose(fp);
            return -1;
        }
    } else {
        if (fprintf(fp, "%s - %s\n", ts, event_type) < 0) {
            perror("fprintf");
            fclose(fp);
            return -1;
        }
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

static int control_floodlight(int on)
{
    if (gpioWrite(FLOODLIGHT_PIN, on ? 1 : 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", FLOODLIGHT_PIN, on ? 1 : 0);
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(PIR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(FLOODLIGHT_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (control_floodlight(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        control_floodlight(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        control_floodlight(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Security Light started. PIR=GPIO%d, Floodlight=GPIO%d\n", PIR_PIN, FLOODLIGHT_PIN);
    printf("Press Ctrl+C to exit.\n");

    int floodlight_active = 0;

    while (g_running) {
        int pir = gpioRead(PIR_PIN);
        if (pir < 0) {
            fprintf(stderr, "gpioRead(PIR_PIN) failed\n");
            break;
        }

        if (pir == 1 && !floodlight_active) {
            printf("Motion detected! Activating floodlight for %d seconds.\n", FLOODLIGHT_ON_DURATION);

            if (control_floodlight(1) != 0) {
                break;
            }
            floodlight_active = 1;

            if (log_event("Motion Detected", -1) != 0) {
                fprintf(stderr, "Warning: failed to log motion detection event\n");
            }

            time_t start = time(NULL);
            int timed_out = 0;

            while (g_running && !timed_out) {
                int pir_val = gpioRead(PIR_PIN);
                if (pir_val < 0) {
                    fprintf(stderr, "gpioRead(PIR_PIN) failed during floodlight\n");
                    break;
                }
                if (pir_val == 0) {
                    break;
                }
                gpioDelay(POLL_DELAY_US);
                timed_out = (time(NULL) - start >= FLOODLIGHT_ON_DURATION);
            }

            if (control_floodlight(0) != 0) {
                break;
            }
            floodlight_active = 0;

            if (timed_out) {
                printf("Floodlight timed out.\n");
            } else {
                printf("Motion stopped. Floodlight deactivated.\n");
            }

            if (log_event("Floodlight Deactivated", (int)(time(NULL) - start)) != 0) {
                fprintf(stderr, "Warning: failed to log deactivation event\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    control_floodlight(0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

