        fprintf(stderr, "I2C read failed: rc=%d\n", rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "I2C short read: got %d bytes, expected 2\n", rc);
        return -1;
    }
    *touch_status = (uint16_t)((uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

int main(void)
{
