    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
