/*
 * MPR121 Capacitive Touch Relay Controller for Raspberry Pi 5
 *
 * Wiring:
 *   MPR121 SDA -> GPIO2 (I2C bus 1 SDA)
 *   MPR121 SCL -> GPIO3 (I2C bus 1 SCL)
 *   MPR121 ADDR -> GND (I2C address 0x5A)
 *   Relay IN  -> GPIO17 (active-high relay module)
 *
 * Behavior:
 *   - On a fresh touch (rising edge) of electrode 0, toggle the relay.
 *   - Relay is OFF at startup and on every exit path.
 *   - Robust error handling: pigpio errors, I2C bus errors, sensor-absent.
 *   - Clean shutdown on SIGINT/SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR        0x5A
#define RELAY_GPIO         17
#define I2C_BUS            1

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS 0x00
#define MPR121_ELECONFIG   0x5E
#define MPR121_SOFTRESET   0x80
#define MPR121_MHD         0x2B
#define MPR121_NHD         0x2C
#define MPR121_NCL         0x2D
#define MPR121_FDL         0x2E
#define MPR121_DEBOUNCE    0x5B
#define MPR121_FFI_SFI_CDT 0x2C
#define MPR121_AUTO_CONFIG 0x7B
#define MPR121_USL         0x7C
#define MPR121_LSL         0x7D
#define MPR121_TL          0x7E

#define NUM_ELECTRODES     12
#define DEBOUNCE_MS        200
#define POLL_DELAY_US      10000  /* 10 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

static int mpr121_write(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X rc=%d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

static int mpr121_init(void)
{
    /* Soft reset */
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0)
