#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"
#define PWM_PERIOD_US 20000  /* 50 Hz */
#define MIN_PULSE_US 1000
#define MAX_PULSE_US 2000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;

static void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s ", ts);
        vfprintf(log_file, format, args);
        fprintf(log_file, "\n");
        fflush(log_file);
    }
    va_end(args);
    vsyslog(priority, format, args);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo line (GPIO%d): %s", SERVO_PIN, strerror(errno));
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR line (GPIO%d): %s", PIR_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        log_message(LOG_ERR, "Failed to request servo line as output: %s", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        log_message(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        return -1;
    }

    return 0;
}

static void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse_us = MIN_PULSE_US + (angle * (MAX_PULSE_US - MIN_PULSE_US)) / 180;
    int on_time = pulse_us;
    int off_time = PWM_PERIOD_US - pulse_us;

    if (gpiod_line_set_value(servo_line, 1) < 0) {
        log_message(LOG_ERR, "Failed to set servo line high: %s", strerror(errno));
        return;
    }
    usleep(on_time);
    if (gpiod_line_set_value(servo_line, 0) < 0) {
        log_message(LOG_ERR, "Failed to set servo line low: %s", strerror(errno));
        return;
    }
    usleep(off_time);
}

static int read_pir_sensor(void) {
    int val = gpiod_line_get_value(pir_line);
    if (val < 0) {
        log_message(LOG_ERR, "Failed to read PIR line: %s", strerror(errno));
        return -1;
    }
    return val;
}

static void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        log_message(LOG_ERR, "Receive failed: %s", strerror(errno));
        close(client_socket);
        return;
    }
    if (bytes_received == 0) {
        log_message(LOG_INFO, "Client disconnected");
        close(client_socket);
        return;
    }
    buffer[bytes_received] = '\0';
    log_message(LOG_INFO, "Received command: %s", buffer);

    if (strncmp(buffer, "SERVO", 5) == 0) {
        int angle = atoi(buffer + 6);
        if (angle < 0 || angle > 180) {
            log_message(LOG_ERR, "Invalid angle: %d", angle);
            const char *err = "ERROR: Invalid angle\n";
            send(client_socket, err, strlen(err), 0);
        } else {
            set_servo_angle(angle);
            const char *ok = "OK\n";
            send(client_socket, ok, strlen(ok), 0);
        }
    } else if (strncmp(buffer, "PIR", 3) == 0) {
        int val = read_pir_sensor();
        if (val < 0) {
            const char *err = "ERROR: PIR read failed\n";
            send(client_socket, err, strlen(err), 0);
        } else {
            char response[64];
            snprintf(response, sizeof(response), "PIR:%d\n", val);
            send(client_socket, response, strlen(response), 0);
        }
    } else {
        log_message(LOG_ERR, "Unknown command: %s", buffer);
        const char *err = "ERROR: Unknown command\n";
        send(client_socket, err, strlen(err), 0);
    }
    close(client_socket);
}

static void cleanup(void) {
    if (servo_line) {
        gpiod_line_set_value(servo_line, 0);
        gpiod_line_release(servo_line);
        servo_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    closelog();
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_message(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sockaddr_in address;
    int opt = 1;
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        log_message(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message(LOG_ERR, "setsockopt failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message(LOG_INFO, "Server listening on port %d", PORT);

    while (running) {
        int client_socket = accept(server_fd, NULL, NULL);
        if (client_socket < 0) {
            if (errno == EINTR && !running) break;
            log_message(LOG_ERR, "Accept failed: %s", strerror(errno));
            continue;
        }
        handle_client(client_socket);
    }

    log_message(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

