#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define DOUT_PIN 23
#define SCK_PIN 24
#define SOLENOID_PIN 25

#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION_MS 200
#define NUM_READINGS 5
#define TARE_READINGS 10
#define MAX_RETRIES 3
#define DOUT_TIMEOUT_MS 1000
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t running = 1;
static double threshold = DEFAULT_THRESHOLD;
static double scale = DEFAULT_SCALE;
static int duration_ms = DEFAULT_DURATION_MS;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *dout_line = NULL;
static struct gpiod_line *sck_line = NULL;
static struct gpiod_line *solenoid_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (solenoid_line) {
        gpiod_line_set_value(solenoid_line, 0);
        gpiod_line_release(solenoid_line);
        solenoid_line = NULL;
    }
    if (sck_line) {
        gpiod_line_set_value(sck_line, 0);
        gpiod_line_release(sck_line);
        sck_line = NULL;
    }
    if (dout_line) {
        gpiod_line_release(dout_line);
        dout_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    closelog();
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        return -1;
    }

    dout_line = gpiod_chip_get_line(chip, DOUT_PIN);
    if (!dout_line) {
        syslog(LOG_ERR, "Failed to get DOUT line %d: %s", DOUT_PIN, strerror(errno));
        return -1;
    }

    sck_line = gpiod_chip_get_line(chip, SCK_PIN);
    if (!sck_line) {
        syslog(LOG_ERR, "Failed to get SCK line %d: %s", SCK_PIN, strerror(errno));
        return -1;
    }

    solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!solenoid_line) {
        syslog(LOG_ERR, "Failed to get solenoid line %d: %s", SOLENOID_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(sck_line, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output: %s", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(dout_line, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input: %s", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(solenoid_line, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output: %s", strerror(errno));
        return -1;
    }

    return 0;
}

static long read_hx711(void) {
    int retries = 0;
    struct timespec ts = {0, 1000000}; /* 1 ms */

    while (gpiod_line_get_value(dout_line) == 1) {
        nanosleep(&ts, NULL);
        retries++;
        if (retries >= DOUT_TIMEOUT_MS) {
            syslog(LOG_ERR, "DOUT timeout waiting for data ready");
            return -1;
        }
    }

    long data = 0;
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck_line, 1) < 0) {
            syslog(LOG_ERR, "Failed to set SCK high: %s", strerror(errno));
            return -1;
        }
        nanosleep(&ts, NULL);

        data <<= 1;
        int bit = gpiod_line_get_value(dout_line);
        if (bit < 0) {
            syslog(LOG_ERR, "Failed to read DOUT: %s", strerror(errno));
            return -1;
        }
        if (bit) {
            data |= 1;
        }

        if (gpiod_line_set_value(sck_line, 0) < 0) {
            syslog(LOG_ERR, "Failed to set SCK low: %s", strerror(errno));
            return -1;
        }
        nanosleep(&ts, NULL);
    }

    /* 25th pulse: Channel A, Gain 128 */
    if (gpiod_line_set_value(sck_line, 1) < 0) {
        syslog(LOG_ERR, "Failed to set SCK high for 25th pulse: %s", strerror(errno));
        return -1;
    }
    nanosleep(&ts, NULL);
    if (gpiod_line_set_value(sck_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to set SCK low for 25th pulse: %s", strerror(errno));
        return -1;
    }
    nanosleep(&ts, NULL);

    /* Convert 24-bit two's complement to 32-bit signed */
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

static double tare(void) {
    double sum = 0.0;
    int valid = 0;

    for (int i = 0; i < TARE_READINGS; i++) {
        long raw = read_hx711();
        if (raw < 0) {
            syslog(LOG_ERR, "Tare read %d failed", i + 1);
            continue;
        }
        sum += (double)raw;
        valid++;
        usleep(1000);
    }

    if (valid == 0) {
        syslog(LOG_ERR, "Tare failed: no valid readings");
        return 0.0;
    }

    return sum / valid;
}

static double get_weight(void) {
    double sum = 0.0;
    int valid = 0;

    for (int i = 0; i < NUM_READINGS; i++) {
        long raw = read_hx711();
        if (raw < 0) {
            syslog(LOG_ERR, "Weight read %d failed", i + 1);
            continue;
        }
        sum += (double)raw;
        valid++;
        usleep(1000);
    }

    if (valid == 0) {
        syslog(LOG_ERR, "Weight measurement failed: no valid readings");
        return 0.0;
    }

    return (sum / valid - tare_offset) / scale;
}

static void control_solenoid(double weight) {
    if (weight > threshold) {
        syslog(LOG_INFO, "Weight %.2f g exceeds threshold %.2f g, activating solenoid for %d ms",
               weight, threshold, duration_ms);
        if (gpiod_line_set_value(solenoid_line, 1) < 0) {
            syslog(LOG_ERR, "Failed to set solenoid HIGH: %s", strerror(errno));
            return;
        }
        usleep(duration_ms * 1000);
        if (gpiod_line_set_value(solenoid_line, 0) < 0) {
            syslog(LOG_ERR, "Failed to set solenoid LOW: %s", strerror(errno));
        }
    } else {
        syslog(LOG_INFO, "Weight %.2f g below threshold %.2f g, solenoid deactivated",
               weight, threshold);
    }
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration_ms = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration_ms]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("weight_control", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting weight control program");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    tare_offset = tare();
    syslog(LOG_INFO, "Tare complete, offset = %.2f", tare_offset);

    while (running) {
        double weight = get_weight();
        syslog(LOG_INFO, "Weight: %.2f g", weight);
        control_solenoid(weight);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

