/*
 * relay_controller.c — Raspberry Pi 4 Model B
 *
 * Subscribes to home/lights/control on localhost:1883 and drives a relay
 * on GPIO17 (BCM) via pigpio.  Payload "ON" energizes the relay, "OFF"
 * de-energizes it, and any other payload is logged as an error.
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *               -lmosquitto -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST      "localhost"
#define MQTT_PORT      1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC     "home/lights/control"
#define GPIO_PIN       17
#define KEEPALIVE_SEC  60

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata,
                       int reason_code, int flags)
{
    (void)userdata;
    (void)flags;

    if (reason_code == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected (broker returned %d)", reason_code);
        if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS)
            syslog(LOG_ERR, "Failed to subscribe to %s", MQTT_TOPIC);
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s (rc=%d)",
               mosquitto_connack_string(reason_code), reason_code);
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata,
                          int reason_code)
{
    (void)mosq;
    (void)userdata;
    syslog(LOG_INFO, "MQTT disconnected (rc=%d)", reason_code);
}

static void on_message(struct mosquitto *mosq, void *userdata,
                       const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message->payloadlen <= 0) {
        syslog(LOG_ERR, "Empty MQTT message on %s", message->topic);
        return;
    }

    /* Ensure payload is NUL-terminated */
    char payload[32];
    size_t len = (size_t)message->payloadlen;
    if (len >= sizeof(payload))
        len = sizeof(payload) - 1;
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    syslog(LOG_INFO, "Received %zu-byte message on %s: %s",
           message->payloadlen, message->topic, payload);

    if (strcmp(payload, "ON") == 0) {
        if (gpioWrite(GPIO_PIN, 1) == 0)
            syslog(LOG_INFO, "Relay ON (GPIO%d HIGH)", GPIO_PIN);
        else
            syslog(LOG_ERR, "gpioWrite(ON) failed on GPIO%d", GPIO_PIN);
    } else if (strcmp(payload, "OFF") == 0) {
        if (gpioWrite(GPIO_PIN, 0) == 0)
            syslog(LOG_INFO, "Relay OFF (GPIO%d LOW)", GPIO_PIN);
        else
            syslog(LOG_ERR, "gpioWrite(OFF) failed on GPIO%d", GPIO_PIN);
    } else {
        syslog(LOG_ERR, "Invalid payload '%s' — expected ON or OFF", payload);
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct mosquitto *mosq = NULL;
    int rc;

    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, OUTPUT) failed", GPIO_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Relay OFF at startup */
    if (gpioWrite(GPIO_PIN, 0) != 0)
        syslog(LOG_WARNING, "Initial gpioWrite(%d, 0) failed", GPIO_PIN);

    /* ---- mosquitto init ---- */
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "mosquitto_new failed");
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    /* ---- connect ---- */
    rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, KEEPALIVE_SEC);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect to %s:%d failed: %s",
               MQTT_HOST, MQTT_PORT, mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- main loop ---- */
    syslog(LOG_INFO, "Starting MQTT relay controller on %s:%d",
           MQTT_HOST, MQTT_PORT);

    while (g_running) {
        rc = mosquitto_loop(mosq, -1, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop returned %s — reconnecting",
                   mosquitto_strerror(rc));
            sleep(5);
            if (g_running) {
                mosquitto_reconnect(mosq);
                sleep(5);
            }
        }
    }

    /* ---- graceful shutdown ---- */
    syslog(LOG_INFO, "Shutting down");
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

