#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};
    int pulse_widths[] = {1000, 1500, 2000, 500, 2500};
    int num_servos = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_servos; i++) {
        int pin = pins[i];
        int pulse = pulse_widths[i];

        if (pulse < SERVO_MIN_PULSE || pulse > SERVO_MAX_PULSE) {
            fprintf(stderr, "Error: pulse width %d out of range for pin %d\n", pulse, pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (gpioSetMode(pin, PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set pin %d as output\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (gpioSetPWMfrequency(pin, 50) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency for pin %d\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (gpioSetPWMrange(pin, 1000000) < 0) {
            fprintf(stderr, "Error: failed to set PWM range for pin %d\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (gpioPWM(pin, pulse) != 0) {
            fprintf(stderr, "Error: failed to set PWM pulse for pin %d\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("Servo on pin %d set to %d us\n", pin, pulse);
    }

    printf("Servos moving to positions. Hold for 3 seconds...\n");
    sleep(3);

    for (int i = 0; i < num_servos; i++) {
        int pin = pins[i];
        if (gpioPWM(pin, 0) != 0) {
            fprintf(stderr, "Error: failed to stop PWM on pin %d\n", pin);
        }
    }

    gpioTerminate();
    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

