/*
 * Closed-loop speed control for two DC motors using pigpio.
 *
 * Hardware (DRV8833 H-bridge, 1:1 encoder-to-output-shaft ratio):
 *   Motor A: IN1=GPIO17, IN2=GPIO18
 *   Motor B: IN3=GPIO22, IN4=GPIO23
 *   Encoder A: A=GPIO4, B=GPIO5
 *   Encoder B: A=GPIO6, B=GPIO12
 *
 * Build: gcc -Wall -O2 -o motor_control motor_control.c -lpigpio -lrt
 * Run:   sudo ./motor_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments ---- */
#define MOTOR_A_PWM_PIN   17
#define MOTOR_A_DIR_PIN   18
#define MOTOR_B_PWM_PIN   22
#define MOTOR_B_DIR_PIN   23

#define ENCODER_A_A_PIN   4
#define ENCODER_A_B_PIN   5
#define ENCODER_B_A_PIN   6
#define ENCODER_B_B_PIN   12

/* ---- Physical constants ---- */
#define WHEEL_RADIUS_M    0.05          /* meters */
#define ENCODER_PPR       64.0          /* pulses per revolution (DRV8833) */
#define COUNTS_PER_REV    (ENCODER_PPR * 4.0)  /* 256 ticks per rev */
#define TARGET_RPM        50.0          /* desired speed (RPM) */
#define PWM_FREQ_HZ       10000         /* 10 kHz */
#define PWM_RANGE         255
#define CONTROL_PERIOD_US 100000        /* 100 ms */
#define STALL_TIMEOUT_S   2.0           /* warn if no ticks for this long */

/* ---- PI controller ---- */
#define KP 0.5
#define KI 0.05
#define INTEGRAL_LIMIT   100.0

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static volatile int32_t g_enc_a = 0;
static volatile int32_t g_enc_b = 0;

/* ---- Prototypes ---- */
static void sigint_handler(int sig);
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata);
static void motor_set(int pwm_pin, int dir_pin, int duty);
static double encoder_rpm(int32_t *count, double dt_s);
static double pid_step(double setpoint, double measured, double *integral,
                        double dt_s);
static void cleanup(void);

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Encoder ISRs (rising edge, atomic) ---- */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    __sync_fetch_and_add(&g_enc_a, 1);
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    __sync_fetch_and_add(&g_enc_b, 1);
}

/* ---- Motor helpers ---- */
static void motor_set(int pwm_pin, int dir_pin, int duty)
{
    if (duty < 0) {
        duty = 0;
    } else if (duty > PWM_RANGE) {
        duty = PWM_RANGE;
    }
    if (gpioPWM(pwm_pin, duty) < 0) {
        fprintf(stderr, "Warning: gpioPWM(%d, %d) failed\n", pwm_pin, duty);
    }
    if (gpioWrite(dir_pin, duty > 0 ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", dir_pin,
                duty > 0 ? 1 : 0);
    }
}

/* ---- Encoder helper ---- */
static double encoder_rpm(int32_t *count, double dt_s)
{
    int32_t c = *count;
    *count = 0;
    return (c / COUNTS_PER_REV) / dt_s * 60.0;
}

/* ---- PI controller ---- */
static double pid_step(double setpoint, double measured, double *integral,
                        double dt_s)
{
    double error = setpoint - measured;
    *integral += error * dt_s;
    if (*integral > INTEGRAL_LIMIT)  *integral = INTEGRAL_LIMIT;
    if (*integral < -INTEGRAL_LIMIT) *integral = -INTEGRAL_LIMIT;
    return KP * error + KI * (*integral);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    motor_set(MOTOR_A_PWM_PIN, MOTOR_A_DIR_PIN, 0);
    motor_set(MOTOR_B_PWM_PIN, MOTOR_B_DIR_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure motor pins ---- */
    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set motor pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure encoder pins ---- */
    if (gpioSetMode(ENCODER_A_A_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_A_B_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_A_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_B_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set encoder pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Register encoder ISRs ---- */
    if (gpioSetISRFuncEx(ENCODER_A_A_PIN, RISING_EDGE, 0,
                         encoder_a_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR for encoder A\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_A_B_PIN, RISING_EDGE, 0,
                         encoder_a_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR for encoder B\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A_PIN, RISING_EDGE, 0,
                         encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR for encoder A\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_B_B_PIN, RISING_EDGE, 0,
                         encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR for encoder B\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure PWM ---- */
    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQ_HZ) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_A_PWM_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install SIGINT handler ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Main control loop ---- */
    double integral_a = 0.0, integral_b = 0.0;
    double last_a = 0.0, last_b = 0.0;
    uint32_t last_tick = gpioTick();

    while (g_running) {
        uint32_t now = gpioTick();
        double dt_s = (now - last_tick) / 1000000.0;
        last_tick = now;

        /* Encoder stall detection */
        static uint32_t last_a_tick = 0, last_b_tick = 0;
        if (g_enc_a == 0) {
            if (now - last_a_tick > STALL_TIMEOUT_S * 1000000) {
                fprintf(stderr, "Warning: encoder A stalled (no ticks for %.1f s)\n",
                        STALL_TIMEOUT_S);
            }
        } else {
            last_a_tick = now;
        }
        if (g_enc_b == 0) {
            if (now - last_b_tick > STALL_TIMEOUT_S * 1000000) {
                fprintf(stderr, "Warning: encoder B stalled (no ticks for %.1f s)\n",
                        STALL_TIMEOUT_S);
            }
        } else {
            last_b_tick = now;
        }

        /* Speed control */
        double rpm_a = encoder_rpm(&g_enc_a, dt_s);
        double rpm_b = encoder_rpm(&g_enc_b, dt_s);

        double pid_a = pid_step(TARGET_RPM, rpm_a, &integral_a, dt_s);
        double pid_b = pid_step(TARGET_RPM, rpm_b, &integral_b, dt_s);

        int pwm_a = (int)pid_a;
        int pwm_b = (int)pid_b;

        /* Anti-windup: if integral is saturated, clamp PWM to avoid
         * discontinuous jumps. */
        if (pwm_a > PWM_RANGE) {
            pwm_a = PWM_RANGE;
            integral_a = INTEGRAL_LIMIT;
        } else if (pwm_a < 0) {
            pwm_a = 0;
            integral_a = -INTEGRAL_LIMIT;
        }
        if (pwm_b > PWM_RANGE) {
            pwm_b = PWM_RANGE;
            integral_b = INTEGRAL_LIMIT;
        } else if (pwm_b < 0) {
            pwm_b = 0;
            integral_b = -INTEGRAL_LIMIT;
        }

        motor_set(MOTOR_A_PWM_PIN, MOTOR_A_DIR_PIN, pwm_a);
        motor_set(MOTOR_B_PWM_PIN, MOTOR_B_DIR_PIN, pwm_b);

        printf("Motor A: RPM=%.2f  PWM=%d  |  Motor B: RPM=%.2f  PWM=%d\n",
               rpm_a, pwm_a, rpm_b, pwm_b);

        gpioDelay(CONTROL_PERIOD_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

