#define BH1750_ADDR 0x23
#define LUX_THRESHOLD_LOW 50.0
#define LUX_THRESHOLD_HIGH 200.0
#define POLL_INTERVAL_SEC 5
#define BH1750_MEASURE_DELAY_US 180000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (handle=%d).\n", I2C_BUS, BH1750_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_lux(float *lux_out) {
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C handle invalid.\n");
        return -1;
    }

    /* BH1750 One-Time High-Resolution Mode 2: 1 lux resolution, ~120 ms */
    if (i2cWriteByte(i2c_handle, 0x21) < 0) {
        fprintf(stderr, "Error: Failed to write measurement command to BH1750.\n");
        return -1;
    }

    gpioDelay(BH1750_MEASURE_DELAY_US);

    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error: Failed to read 2 bytes from BH1750 (read=%d).\n", bytes_read);
        return -1;
    }

    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

static void log_event(float lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: Failed to register signal handler");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("chicken_coop_log.txt", "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int relay_state = 0;
    int last_relay_state = -1;

    while (running) {
        float lux = 0.0f;
        if (read_lux(&lux) != 0) {
            fprintf(stderr, "Error: Sensor read failed. Turning off relay for safety.\n");
            control_relay(0);
            relay_state = 0;
            log_event(-1.0f, 0);
        } else {
            printf("Lux: %.2f\n", lux);

            if (lux < LUX_THRESHOLD_LOW && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
            } else if (lux > LUX_THRESHOLD_HIGH && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
            }

            if (relay_state != last_relay_state) {
                log_event(lux, relay_state);
                last_relay_state = relay_state;
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

