#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000   /* 50 ms */
#define LOOP_DELAY_US 10000       /* 10 ms */
#define POLL_TIMEOUT_US 100000    /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_relay_state(int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("[%s] Relay %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void)
{
    int relay_state = 0;
    int last_touch = 0;
    int first_read = 1;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Error: failed to initialize relay state on GPIO %d.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_relay_state(relay_state);

    while (running) {
        int touch = gpioRead(TOUCH_SENSOR_PIN);

        if (touch < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d.\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (first_read) {
            last_touch = touch;
            first_read = 0;
        }

        if (touch == 1 && last_touch == 1) {
            /* Still touched — wait for release with a timeout */
            uint32_t elapsed = 0;
            while (running && touch == 1) {
                touch = gpioRead(TOUCH_SENSOR_PIN);
                if (touch < 0) {
                    fprintf(stderr, "Error: gpioRead failed on GPIO %d.\n", TOUCH_SENSOR_PIN);
                    goto cleanup;
                }
                gpioDelay(1000); /* 1 ms */
                elapsed += 1000;
                if (elapsed >= POLL_TIMEOUT_US) {
                    break;
                }
            }
            if (touch == 0) {
                /* Debounce: wait and re-read */
                gpioDelay(DEBOUNCE_DELAY_US);
                touch = gpioRead(TOUCH_SENSOR_PIN);
                if (touch < 0) {
                    fprintf(stderr, "Error: gpioRead failed on GPIO %d.\n", TOUCH_SENSOR_PIN);
                    goto cleanup;
                }
                if (touch == 1) {
                    relay_state = !relay_state;
                    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                        fprintf(stderr, "Error: gpioWrite failed on GPIO %d.\n", RELAY_PIN);
                        goto cleanup;
                    }
                    log_relay_state(relay_state);
                }
            }
        }

        last_touch = touch;
        gpioDelay(LOOP_DELAY_US);
    }

cleanup:
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

