#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define DEBOUNCE_US 1000000
#define LOG_FILE "water_flow.log"

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flow_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static void log_event(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t) {
        fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec, msg);
        fflush(log_file);
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set FLOW_SENSOR_PIN mode\n");
        return -1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set SOLENOID_PIN mode\n");
        return -1;
    }
    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        fprintf(stderr, "Failed to initialize SOLENOID_PIN to HIGH\n");
        return -1;
    }
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, DEBOUNCE_US, flow_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for FLOW_SENSOR_PIN\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file) {
        log_event("Program terminating, cleaning up...");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(SOLENOID_PIN, 1);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting.");
        cleanup();
        return 1;
    }

    log_event("Program started.");

    int solenoid_state = 1;
    log_event("Solenoid initially OPEN (HIGH).");

    while (running) {
        time_sleep(1.0);

        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = ((double)pulses / PULSES_PER_LITER) * 60.0;

        char msg[128];
        snprintf(msg, sizeof(msg), "Flow rate: %.2f LPM (pulses: %d)", lpm, pulses);
        log_event(msg);

        if (lpm > LPM_THRESHOLD_HIGH && solenoid_state == 1) {
            if (gpioWrite(SOLENOID_PIN, 0) == 0) {
                solenoid_state = 0;
                log_event("Solenoid CLOSED (LOW).");
            } else {
                log_event("ERROR: Failed to close solenoid.");
            }
        } else if (lpm < LPM_THRESHOLD_LOW && solenoid_state == 0) {
            if (gpioWrite(SOLENOID_PIN, 1) == 0) {
                solenoid_state = 1;
                log_event("Solenoid OPEN (HIGH).");
            } else {
                log_event("ERROR: Failed to open solenoid.");
            }
        }
    }

    log_event("Received termination signal, shutting down.");
    cleanup();
    return 0;
}

