#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18

#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_LOG_FILE "dispensing_log.json"
#define DEFAULT_TIMEOUT_US 1000

#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000

#define SERVO_OPEN_PULSE_WIDTH 1500
#define SERVO_CLOSE_PULSE_WIDTH 1000

#define DISPENSE_DURATION_MS 1000

volatile sig_atomic_t program_running = 1;
int server_socket = -1;
int client_socket = -1;
double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
char server_ip[16] = DEFAULT_SERVER_IP;
int server_port = DEFAULT_SERVER_PORT;
char log_file[256] = DEFAULT_LOG_FILE;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s': %s. Using defaults.\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");
        if (!key || !value) continue;

        if (strcmp(key, "calibration_factor") == 0) {
            calibration_factor = atof(value);
        } else if (strcmp(key, "server_ip") == 0) {
            strncpy(server_ip, value, sizeof(server_ip) - 1);
            server_ip[sizeof(server_ip) - 1] = '\0';
        } else if (strcmp(key, "server_port") == 0) {
            server_port = atoi(value);
        } else if (strcmp(key, "log_file") == 0) {
            strncpy(log_file, value, sizeof(log_file) - 1);
            log_file[sizeof(log_file) - 1] = '\0';
        }
    }

    fclose(fp);
    return 0;
}

int log_event(double target_weight, double actual_weight, const char *error_msg) {
    FILE *fp = fopen(log_file, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", log_file, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f", timestamp, target_weight, actual_weight);
    if (error_msg) {
        fprintf(fp, ", \"error\": \"%s\"", error_msg);
    }
    fprintf(fp, "}\n");

    fclose(fp);
    return 0;
}

int read_hx711(int data_pin, int sck_pin, int timeout_us) {
    if (gpioSetMode(data_pin, PI_INPUT) < 0) return -1;
    if (gpioSetMode(sck_pin, PI_OUTPUT) < 0) return -1;

    int value = 0;
    int timeout = 0;

    while (gpioRead(data_pin) == 1) {
        if (timeout++ > timeout_us) {
            return -2;
        }
        gpioDelay(1);
    }

    for (int i = 0; i < 24; i++) {
        if (gpioWrite(sck_pin, 1) < 0) return -1;
        gpioDelay(1);
        value = (value << 1) | gpioRead(data_pin);
        if (gpioWrite(sck_pin, 0) < 0) return -1;
        gpioDelay(1);
    }

    if (gpioWrite(sck_pin, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(sck_pin, 0) < 0) return -1;
    gpioDelay(1);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

double calibrate_hx711(int data_pin, int sck_pin, double known_weight, int timeout_us) {
    int raw_value = read_hx711(data_pin, sck_pin, timeout_us);
    if (raw_value < 0) {
        return -1.0;
    }
    return (double)raw_value / calibration_factor - known_weight;
}

int set_servo_angle(int pin, int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_width = SERVO_MIN_PULSE_WIDTH + (angle * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 180);
