}

int handle_client(int client_socket, int data_pin, int sck_pin, int timeout_us) {
    char buffer[256];
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("recv failed");
        return -1;
    }
    if (bytes_received == 0) {
        printf("Client disconnected.\n");
        return -1;
    }
    buffer[bytes_received] = '\0';

    char *endptr;
    double target_weight = strtod(buffer, &endptr);
    if (*endptr != '\0' || target_weight <= 0) {
        fprintf(stderr, "Error: Invalid target weight received: %s\n", buffer);
        const char *err_msg = "Invalid target weight";
        send(client_socket, err_msg, strlen(err_msg), 0);
        return -1;
    }

    printf("Received target weight: %.2f grams\n", target_weight);

    if (dispense_ingredient(data_pin, sck_pin, target_weight, timeout_us) < 0) {
        fprintf(stderr, "Error: Dispense failed.\n");
        const char *err_msg = "Dispense failed";
        send(client_socket, err_msg, strlen(err_msg), 0);
        return -1;
    }

    double actual_weight = calibrate_hx711(data_pin, sck_pin, target_weight, timeout_us);
    if (actual_weight < 0) {
        fprintf(stderr, "Error: Failed to read actual weight after dispense.\n");
        const char *err_msg = "Failed to read actual weight";
        send(client_socket, err_msg, strlen(err_msg), 0);
        return -1;
    }

    char response[256];
    snprintf(response, sizeof(response), "%.2f", actual_weight);
    send(client_socket, response, strlen(response), 0);

    if (log_event(target_weight, actual_weight, NULL) < 0) {
        fprintf(stderr, "Error: Failed to log event.\n");
    }

    return 0;
}

int setup_server(const char *ip, int port) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket failed");
        return -1;
    }

    int opt = 1;
    if (setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(sock);
        return -1;
    }

    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = inet_addr(ip);
    address.sin_port = htons(port);

    if (bind(sock, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(sock);
        return -1;
    }

    if (listen(sock, 3) < 0) {
        perror("listen failed");
        close(sock);
        return -1;
    }

