#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEFAULT_DEBOUNCE_MS 50
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime() failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEFAULT_DEBOUNCE_MS;
    int relay_state = 0;
    int last_touch_level = 0;
    int last_touch_time = 0;
    int current_time = 0;

    if (argc > 1) {
        debounce_ms = atoi(argv[1]);
        if (debounce_ms <= 0) {
            fprintf(stderr, "Invalid debounce value '%s'. Using default %d ms.\n", argv[1], DEFAULT_DEBOUNCE_MS);
            debounce_ms = DEFAULT_DEBOUNCE_MS;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, relay_state) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_relay_state(relay_state);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    while (running) {
        int touch_level = gpioRead(TOUCH_SENSOR_GPIO);
        if (touch_level < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d\n", TOUCH_SENSOR_GPIO);
            break;
        }

        current_time = gpioTick() / 1000;

        if (touch_level == 1 && last_touch_level == 0) {
            if (current_time - last_touch_time > debounce_ms) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_GPIO, relay_state) != 0) {
                    fprintf(stderr, "gpioWrite failed on GPIO %d\n", RELAY_GPIO);
                    break;
                }
                log_relay_state(relay_state);
                last_touch_time = current_time;
            }
        }

        last_touch_level = touch_level;
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

