            if (current_time - last_touch_time > debounce_ms) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_GPIO, relay_state) != 0) {
                    fprintf(stderr, "gpioWrite failed on GPIO %d\n", RELAY_GPIO);
                    break;
                }
                log_relay_state(relay_state);
                last_touch_time = current_time;
            }
        }

        last_touch_level = touch_level;
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

