#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define MIN_PULSE_US   500
#define MAX_PULSE_US   2500
#define MIN_ANGLE      0
#define MAX_ANGLE      180
#define DEFAULT_ANGLE  90
#define STEP_ANGLE     10
#define PWM_FREQ_HZ    50
#define LOOP_DELAY_US  100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static struct termios g_orig_termios;

static void restore_terminal(void)
{
    if (isatty(STDIN_FILENO)) {
        tcsetattr(STDIN_FILENO, TCSANOW, &g_orig_termios);
    }
}

static void cleanup(void)
{
    /* Stop PWM pulses on the servo pin */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    restore_terminal();
}

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int set_terminal_raw(void)
{
    struct termios raw;

    if (!isatty(STDIN_FILENO)) {
        fprintf(stderr, "Error: stdin is not a terminal.\n");
        return -1;
    }

    if (tcgetattr(STDIN_FILENO, &g_orig_termios) != 0) {
        perror("tcgetattr");
        return -1;
    }

    raw = g_orig_termios;
    raw.c_lflag &= ~(ICANON | ECHO);
    raw.c_cc[VMIN]  = 0;
    raw.c_cc[VTIME] = 0;

    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int angle_to_pulse_us(int angle)
{
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return MIN_PULSE_US + (angle * (MAX_PULSE_US - MIN_PULSE_US)) / MAX_ANGLE;
}

static int set_servo_angle(int angle)
{
    int pulse_us = angle_to_pulse_us(angle);
    if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Error: pulse width %d us out of range [%d, %d]\n",
                pulse_us, MIN_PULSE_US, MAX_PULSE_US);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse_us) != 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

int main(void)
{
    int angle = DEFAULT_ANGLE;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Set up signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set terminal to raw mode for non-Enter keyboard input */
    if (set_terminal_raw() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set servo to initial angle */
    if (set_servo_angle(angle) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    printf("Servo angle set to %d degrees (pulse %d us).\n",
           angle, angle_to_pulse_us(angle));
    fflush(stdout);

    /* Main loop: read single-char commands without Enter */
    while (g_running) {
        int c = getchar();
        if (c == EOF) {
            break;
        }

        switch (c) {
        case '+':
            angle += STEP_ANGLE;
            break;
        case '-':
            angle -= STEP_ANGLE;
            break;
        case 'q':
        case 'Q':
        case '\x03': /* Ctrl-C */
            g_running = 0;
            break;
        default:
            continue;
        }

        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Error: failed to set servo angle.\n");
            break;
        }
        printf("Servo angle set to %d degrees (pulse %d us).\n",
               angle, angle_to_pulse_us(angle));
        fflush(stdout);
    }

    /* Clean exit */
    cleanup();
    return EXIT_SUCCESS;
}

