#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE       17
#define DEBOUNCE_MS     2
#define SAMPLE_PERIOD_S 5
#define LOG_FILE        "motor_rpm.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_rpm(FILE *fp, double rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                GPIO_LINE, strerror(errno));
        goto cleanup_chip;
    }

    /* Request the line as input with internal pull-up so the A3144
     * open-collector output has a defined high level when the sensor
     * is absent or inactive. */
    if (gpiod_line_request_input_flags(line, "motor_rpm",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "gpiod_line_request_input_flags failed: %s\n",
                strerror(errno));
        goto cleanup_chip;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup_line;
    }

    printf("Monitoring motor RPM on GPIO %d (chip %s). Press Ctrl+C to exit.\n",
           GPIO_LINE, GPIO_CHIP_NAME);

    struct timespec last_sample;
    if (clock_gettime(CLOCK_MONOTONIC, &last_sample) == -1) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        goto cleanup_all;
    }

    int pulse_count = 0;
    struct timespec last_event;
    if (clock_gettime(CLOCK_MONOTONIC, &last_event) == -1) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        goto cleanup_all;
    }

    while (running) {
        struct timespec timeout;
        timeout.tv_sec  = 1;
        timeout.tv_nsec = 0;

        int rv = gpiod_line_event_wait(line, &timeout);
        if (rv < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n",
                    strerror(errno));
            goto cleanup_all;
        }
        if (rv == 0) {
            /* Timeout — check if it was a deliberate break. */
            continue;
        }

        /* Event detected — read it to clear the event queue. */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "gpiod_line_event_read failed: %s\n",
                    strerror(errno));
            goto cleanup_all;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        struct timespec now;
        if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            goto cleanup_all;
        }

        long delta_ms = (now.tv_sec - last_event.tv_sec) * 1000L
                      + (now.tv_nsec - last_event.tv_nsec) / 1000000L;

        if (delta_ms >= DEBOUNCE_MS) {
            pulse_count++;
            last_event = now;
        }
    }

    ret = EXIT_SUCCESS;

cleanup_all:
    if (log_fp != NULL) {
        fclose(log_fp);
    }
cleanup_line:
    gpiod_line_release(line);
cleanup_chip:
    gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
}

