#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define POLL_DELAY_US    50000   /* 50 ms */
#define FAILSAFE_TIMEOUT 10      /* seconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    int rc;

    /* --- Initialize pigpio --- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", rc);
        return EXIT_FAILURE;
    }

    /* --- Configure pins --- */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Relay module is active-HIGH: start with relay OFF */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize relay state on GPIO%d.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-controlled relay started. Touch GPIO%d to toggle relay GPIO%d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    int relay_state = 0;
    int failsafe_active = 0;
    uint32_t failsafe_start_tick = 0;

    while (g_running) {
        int touch = gpioRead(TOUCH_SENSOR_PIN);
        if (touch == PI_BAD_GPIO) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch) {
            if (!failsafe_active) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error: gpioWrite failed on GPIO%d.\n", RELAY_PIN);
                    break;
                }
                printf("Touch detected — relay %s.\n", relay_state ? "ON" : "OFF");
            } else {
                /* Sensor still HIGH; keep relay OFF, but keep track of time */
                if (failsafe_start_tick == 0) {
                    failsafe_start_tick = gpioTick();
                } else if ((gpioTick() - failsafe_start_tick) / 1000000 >= FAILSAFE_TIMEOUT) {
                    /* Failsafe expired: force relay OFF and reset */
                    if (gpioWrite(RELAY_PIN, 0) != 0) {
                        fprintf(stderr, "Error: failed to force relay OFF.\n");
                        break;
                    }
                    relay_state = 0;
                    failsafe_active = 0;
                    failsafe_start_tick = 0;
                    printf("Failsafe triggered — relay forced OFF.\n");
                }
            }
        } else {
            /* Sensor released: reset failsafe */
            failsafe_active = 0;
            failsafe_start_tick = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Cleanup --- */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nCleanup complete. Relay OFF, pigpio terminated.\n");
    return EXIT_SUCCESS;
}

