#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_GPIO 23
#define FLOW_SENSOR_GPIO 24
#define PWM_GPIO 18

#define PULSES_PER_LITER 450.0
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "flow_log.csv"

static volatile int pulse_count = 0;
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static double target_flow_rate = 0.0;
static double kp = 1.0;

static void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)level; (void)tick; (void)user_data;
    pulse_count++;
}

static double calculate_flow_rate(int pulses, double interval_seconds) {
    if (interval_seconds <= 0.0) return 0.0;
    return (double)pulses / PULSES_PER_LITER / interval_seconds * 60.0;
}

static int set_valve_position(int position) {
    if (position < 0 || position > PWM_RANGE) {
        fprintf(stderr, "Error: Valve position out of range [0, %d]\n", PWM_RANGE);
        return -1;
    }
    if (gpioPWM(PWM_GPIO, position) != 0) {
        fprintf(stderr, "Error: Failed to set PWM on GPIO %d\n", PWM_GPIO);
        return -1;
    }
    return 0;
}

static int log_data(double flow_rate, int valve_position) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not open\n");
        return -1;
    }
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    long timestamp_ms = (long)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
    if (fprintf(log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(PWM_GPIO, 0);
    gpioWrite(VALVE_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                if (target_flow_rate <= 0.0) {
                    fprintf(stderr, "Error: Target flow rate must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t target_flow_rate_Lmin]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (target_flow_rate <= 0.0) {
        fprintf(stderr, "Error: Target flow rate not specified or invalid\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", VALVE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PWM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d\n", PWM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d\n", PWM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(VALVE_GPIO, 1) != 0) {
        fprintf(stderr, "Error: Failed to enable valve on GPIO %d\n", VALVE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR on GPIO %d\n", FLOW_SENSOR_GPIO);
        gpioWrite(VALVE_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);
        gpioWrite(VALVE_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fprintf(log_file, "timestamp_ms,flow_rate_Lmin,valve_position\n") < 0) {
        perror("Error writing CSV header");
        fclose(log_file);
        log_file = NULL;
        gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);
        gpioWrite(VALVE_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control started. Target: %.2f L/min. Press Ctrl+C to exit.\n", target_flow_rate);

    while (running) {
        int pulses = pulse_count;
        pulse_count = 0;

        struct timespec start, end;
        if (clock_gettime(CLOCK_MONOTONIC, &start) != 0) {
            perror("clock_gettime");
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_US);

        if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
            perror("clock_gettime");
            break;
        }

        double interval_seconds = (end.tv_sec - start.tv_sec) +
                                  (end.tv_nsec - start.tv_nsec) / 1e9;
        if (interval_seconds <= 0.0) {
            continue;
        }

        double flow_rate = calculate_flow_rate(pulses, interval_seconds);

        double error = target_flow_rate - flow_rate;
        double adjustment = kp * error;
        int valve_position = (int)(adjustment + 0.5);
        if (valve_position < 0) valve_position = 0;
        if (valve_position > PWM_RANGE) valve_position = PWM_RANGE;

        if (set_valve_position(valve_position) != 0) {
            fprintf(stderr, "Warning: Failed to set valve position\n");
        }

        if (log_data(flow_rate, valve_position) != 0) {
            fprintf(stderr, "Warning: Failed to log data\n");
        }

        printf("Flow: %.2f L/min | Target: %.2f L/min | Valve: %d | Error: %.2f\n",
               flow_rate, target_flow_rate, valve_position, error);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

