#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK1_PIN      17
#define LOCK2_PIN      27
#define BUTTON_PIN     22
#define SPI_CHANNEL    0
#define SPI_SPEED      100000
#define TAG_LENGTH     10
#define LOG_FILE       "/var/log/door_access.log"
#define DEBOUNCE_US    50000   /* 50 ms */
#define LOCK_HOLD_US   5000000 /* 5 s  */

static const unsigned char VALID_TAG[TAG_LENGTH] = {
    0x01, 0x02, 0x03, 0x04, 0x05,
    0x06, 0x07, 0x08, 0x09, 0x0A
};

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_fp    = NULL;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    if (!g_log_fp) return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(g_log_fp, "%s - %s\n", ts, event);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                       */
/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(LOCK1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LOCK2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        return -1;
    }

    /* YM-180 actuators are normally-locked (HIGH = locked). */
    if (gpioWrite(LOCK1_PIN, 1) < 0 || gpioWrite(LOCK2_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite (lock init) failed\n");
        return -1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed\n");
        return -1;
    }

    return 0;
}

static void release_locks(void)
{
    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);
}

static void engage_locks(void)
{
    gpioWrite(LOCK1_PIN, 0);
    gpioWrite(LOCK2_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* SPI                                                                */
/* ------------------------------------------------------------------ */
static int init_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", g_spi_handle);
        return -1;
    }
    return 0;
}

/*
 * Read TAG_LENGTH bytes from the RFID reader.
 * Returns 0 on success, -1 on SPI transfer failure.
 * On success, fills `tag` with the read data.
 */
static int read_rfid_tag(unsigned char *tag)
{
    unsigned char tx[TAG_LENGTH];
    unsigned char rx[TAG_LENGTH];

    memset(tx, 0x00, sizeof(tx));

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, TAG_LENGTH);
    if (ret != TAG_LENGTH) {
        fprintf(stderr, "spiXfer returned %d (expected %d)\n", ret, TAG_LENGTH);
        return -1;
    }

    memcpy(tag, rx, TAG_LENGTH);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Button                                                            */
/* ------------------------------------------------------------------ */
static int read_button(void)
{
    return (gpioRead(BUTTON_PIN) == 0);
}

/* ------------------------------------------------------------------ */
/* Authentication                                                    */
/* ------------------------------------------------------------------ */
static int authenticate(const unsigned char *tag)
{
    return (memcmp(tag, VALID_TAG, TAG_LENGTH) == 0);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                           */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    release_locks();
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                              */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("System started");

    while (g_running) {
        unsigned char tag[TAG_LENGTH];
        int button_pressed = 0;

        /* Poll button (active-low with pull-up) */
        if (read_button()) {
            gpioDelay(DEBOUNCE_US);
            if (read_button()) {
                button_pressed = 1;
            }
        }

        if (button_pressed) {
            log_event("Button pressed");

            if (read_rfid_tag(tag) == 0) {
                if (authenticate(tag)) {
                    log_event("Authentication successful");
                    engage_locks();
                    gpioDelay(LOCK_HOLD_US);
                    release_locks();
                } else {
                    log_event("Invalid tag");
                }
            } else {
                log_event("RFID read failure");
            }
        }

        gpioDelay(100000); /* 100 ms poll interval */
    }

    log_event("System shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

