    *prev_error = error;
    return output;
}

static void cleanup(void) {
    if (motor1_ena) gpiod_line_set_value(motor1_ena, 0);
    if (motor1_in1) gpiod_line_set_value(motor1_in1, 0);
    if (motor1_in2) gpiod_line_set_value(motor1_in2, 0);
    if (motor2_enb) gpiod_line_set_value(motor2_enb, 0);
    if (motor2_in3) gpiod_line_set_value(motor2_in3, 0);
    if (motor2_in4) gpiod_line_set_value(motor2_in4, 0);
    if (enc1_a) gpiod_line_release(enc1_a);
    if (enc1_b) gpiod_line_release(enc1_b);
    if (enc2_a) gpiod_line_release(enc2_a);
    if (enc2_b) gpiod_line_release(enc2_b);
    if (motor1_ena) gpiod_line_release(motor1_ena);
    if (motor1_in1) gpiod_line_release(motor1_in1);
    if (motor1_in2) gpiod_line_release(motor1_in2);
    if (motor2_enb) gpiod_line_release(motor2_enb);
    if (motor2_in3) gpiod_line_release(motor2_in3);
    if (motor2_in4) gpiod_line_release(motor2_in4);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    motor1_ena = gpiod_chip_get_line(chip, MOTOR1_ENA);
    motor1_in1 = gpiod_chip_get_line(chip, MOTOR1_IN1);
    motor1_in2 = gpiod_chip_get_line(chip, MOTOR1_IN2);
    motor2_enb = gpiod_chip_get_line(chip, MOTOR2_ENB);
    motor2_in3 = gpiod_chip_get_line(chip, MOTOR2_IN3);
    motor2_in4 = gpiod_chip_get_line(chip, MOTOR2_IN4);
    enc1_a = gpiod_chip_get_line(chip, ENCODER1_A);
    enc1_b = gpiod_chip_get_line(chip, ENCODER1_B);
    enc2_a = gpiod_chip_get_line(chip, ENCODER2_A);
    enc2_b = gpiod_chip_get_line(chip, ENCODER2_B);

    if (!motor1_ena || !motor1_in1 || !motor1_in2 || !motor2_enb || !motor2_in3 || !motor2_in4 ||
        !enc1_a || !enc1_b || !enc2_a || !enc2_b) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(motor1_ena, "motor1_ena", 0) < 0 ||
        gpiod_line_request_output(motor1_in1, "motor1_in1", 0) < 0 ||
        gpiod_line_request_output(motor1_in2, "motor1_in2", 0) < 0 ||
        gpiod_line_request_output(motor2_enb, "motor2_enb", 0) < 0 ||
        gpiod_line_request_output(motor2_in3, "motor2_in3", 0) < 0 ||
        gpiod_line_request_output(motor2_in4, "motor2_in4", 0) < 0) {
        fprintf(stderr, "Failed to request output lines\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_both_edges_events(enc1_a, "enc1_a") < 0 ||
        gpiod_line_request_both_edges_events(enc2_a, "enc2_a") < 0) {
        fprintf(stderr, "Failed to request edge events\n");
        cleanup();
        return 1;
    }

    log_file = fopen("motor_log.csv", "a");
    if (!log_file) {
        perror("fopen");
        cleanup();
        return 1;
    }
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,PID1_P,PID1_I,PID1_D,PID1_Output,PID2_P,PID2_I,PID2_D,PID2_Output\n");
    fflush(log_file);

    pthread_t enc1_tid, enc2_tid;
    if (pthread_create(&enc1_tid, NULL, encoder_thread, enc1_a) != 0 ||
        pthread_create(&enc2_tid, NULL, encoder_thread, enc2_a) != 0) {
        perror("pthread_create");
        running = 0;
        pthread_join(enc1_tid, NULL);
        pthread_join(enc2_tid, NULL);
        cleanup();
        return 1;
    }

    double target_rpm1 = 60.0, target_rpm2 = 60.0;
    double integral1 = 0.0, prev_error1 = 0.0;
    double integral2 = 0.0, prev_error2 = 0.0;

    struct timespec last_time, now;
    clock_gettime(CLOCK_MONOTONIC, &last_time);

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed = (now.tv_sec - last_time.tv_sec) + (now.tv_nsec - last_time.tv_nsec) / 1e9;
        if (elapsed < 0.001) {
            usleep(1000);
            continue;
        }
        last_time = now;

        pthread_mutex_lock(&enc1_mutex);
        long pulses1 = enc1_count;
        enc1_count = 0;
        pthread_mutex_unlock(&enc1_mutex);

        pthread_mutex_lock(&enc2_mutex);
        long pulses2 = enc2_count;
        enc2_count = 0;
        pthread_mutex_unlock(&enc2_mutex);

        double rpm1 = calculate_rpm(pulses1, elapsed);
        double rpm2 = calculate_rpm(pulses2, elapsed);

        double pid1 = pid_control(target_rpm1, rpm1, &integral1, &prev_error1);
        double pid2 = pid_control(target_rpm2, rpm2, &integral2, &prev_error2);

        int speed1 = (int)pid1;
        int speed2 = (int)pid2;

        if (speed1 > 255) speed1 = 255;
        if (speed1 < -255) speed1 = -255;
        if (speed2 > 255) speed2 = 255;
        if (speed2 < -255) speed2 = -255;

        set_motor_speed(motor1_ena, motor1_in1, motor1_in2, speed1);
        set_motor_speed(motor2_enb, motor2_in3, motor2_in4, speed2);

        log_data(rpm1, rpm2, KP * (target_rpm1 - rpm1), KI * integral1, KD * (target_rpm1 - rpm1) - prev_error1, pid1,
                 KP * (target_rpm2 - rpm2), KI * integral2, KD * (target_rpm2 - rpm2) - prev_error2, pid2);

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    pthread_join(enc1_tid, NULL);
    pthread_join(enc2_tid, NULL);
    cleanup();
    return 0;
}

