#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define LOG_FILE "relay_log.txt"
#define POLL_DELAY_US 50000

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHD_RISE 0x2B
#define MPR121_NHD_RISE 0x2C
#define MPR121_NCL_RISE 0x2D
#define MPR121_FDL_RISE 0x2E
#define MPR121_MHD_FALL 0x2F
#define MPR121_NHD_FALL 0x30
#define MPR121_NCL_FALL 0x31
#define MPR121_FDL_FALL 0x32
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X: %d\n", value, reg, rc);
        return -1;
    }
    return 0;
}

static int mpr121_init(int handle) {
    /* Soft reset */
    if (mpr121_write_reg(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Filtering configuration */
    if (mpr121_write_reg(handle, MPR121_MHD_RISE, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHD_RISE, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCL_RISE, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL_RISE, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_MHD_FALL, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHD_FALL, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCL_FALL, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL_FALL, 0x00) < 0) return -1;

    /* Touch and release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(handle, MPR121_E0TTH + i * 2, 0x0F) < 0) return -1;
        if (mpr121_write_reg(handle, MPR121_E0RTH + i * 2, 0x0A) < 0) return -1;
    }

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write_reg(handle, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=6 samples, CDC=16 µA, CDT=0.5 µs */
    if (mpr121_write_reg(handle, MPR121_CONFIG1, 0x10) < 0) return -1;

    /* CDT=0.5 µs, SFI=4 samples, ESI=4 ms */
    if (mpr121_write_reg(handle, MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking, run mode */
    if (mpr121_write_reg(handle, MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

static int read_touch_status(int handle, uint16_t *status) {
    int low = i2cReadByteData(handle, MPR121_TOUCHSTATUS_L);
    if (low < 0) {
        fprintf(stderr, "Error reading touch status low byte: %d\n", low);
        return -1;
    }
    int high = i2cReadByteData(handle, MPR121_TOUCHSTATUS_H);
    if (high < 0) {
        fprintf(stderr, "Error reading touch status high byte: %d\n", high);
        return -1;
    }
    *status = (uint16_t)((high << 8) | low);
    return 0;
}

static void log_relay_state(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Relay %s\n", timestamp, state ? "ON" : "OFF");
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(i2c_handle, &touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int new_state = (touch_status & 0x0FFF) ? 1 : 0;

        if (new_state != relay_state) {
            gpioWrite(RELAY_GPIO, new_state);
            relay_state = new_state;
            log_relay_state(relay_state);
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

