#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define CHIP_NAME "gpiochip0"
#define LOG_FILE "valve_log.txt"

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (valve1_line) {
        gpiod_line_release(valve1_line);
        valve1_line = NULL;
    }
    if (valve2_line) {
        gpiod_line_release(valve2_line);
        valve2_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", CHIP_NAME, strerror(errno));
        return -1;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!valve1_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", VALVE1_GPIO, strerror(errno));
        return -1;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve2_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", VALVE2_GPIO, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(valve1_line, "solenoid_valve", 0) < 0) {
        fprintf(stderr, "Failed to request output for GPIO %d: %s\n", VALVE1_GPIO, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(valve2_line, "solenoid_valve", 0) < 0) {
        fprintf(stderr, "Failed to request output for GPIO %d: %s\n", VALVE2_GPIO, strerror(errno));
        return -1;
    }

    return 0;
}

static int log_event(const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
        return -1;
    }

    struct tm *tstruct = localtime(&now);
    if (!tstruct) {
        fprintf(stderr, "Failed to convert time: %s\n", strerror(errno));
        return -1;
    }

    char buf[80];
    if (strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", tstruct) == 0) {
        fprintf(stderr, "Failed to format timestamp\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", buf, message) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_valve(struct gpiod_line *line, int gpio_pin, int duration_ms) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to activate valve on GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }

    if (log_event("Valve activated") < 0) {
