    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (valve1_line) {
        gpiod_line_release(valve1_line);
        valve1_line = NULL;
    }
    if (valve2_line) {
        gpiod_line_release(valve2_line);
        valve2_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", CHIP_NAME, strerror(errno));
        return -1;
    }

