        fprintf(stderr, "Failed to request output for GPIO %d: %s\n", VALVE2_GPIO, strerror(errno));
        return -1;
    }

    return 0;
}

static int log_event(const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
        return -1;
    }

    struct tm *tstruct = localtime(&now);
    if (!tstruct) {
        fprintf(stderr, "Failed to convert time: %s\n", strerror(errno));
        return -1;
    }

    char buf[80];
    if (strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", tstruct) == 0) {
