#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define I2C_BUS 1

// MPR121 Register Addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG0     0x5E
#define MPR121_ELECONFIG1     0x5F
#define MPR121_MHD_R          0x2B
#define MPR121_NHD_R          0x2C
#define MPR121_NCL_R          0x2D
#define MPR121_FDL_R          0x2E
#define MPR121_MHD_F          0x2F
#define MPR121_NHD_F          0x30
#define MPR121_NCL_F          0x31
#define MPR121_FDL_F          0x32
#define MPR121_E0TTH          0x41
#define MPR121_E0RTH          0x42
#define MPR121_DEBOUNCE       0x5B
#define MPR121_CONFIG1        0x5C
#define MPR121_CONFIG2        0x5D
#define MPR121_ECR            0x5E

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to MPR121 register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

int mpr121_init(int handle) {
    // Stop mode
    if (mpr121_write_reg(handle, MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000); // 1 ms

    // Filter/Charge Time (0x20: FDL=6, NHD=4, NCL=4, FDL=4)
    if (mpr121_write_reg(handle, MPR121_CONFIG2, 0x20) < 0) return -1;
    // Electrode Configuration (0x01: 12 electrodes, 0.5uA charge current)
    if (mpr121_write_reg(handle, MPR121_CONFIG1, 0x01) < 0) return -1;
    // Touch and Release Thresholds for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(handle, MPR121_E0TTH + i * 2, 0x0A) < 0) return -1; // Touch threshold
        if (mpr121_write_reg(handle, MPR121_E0RTH + i * 2, 0x05) < 0) return -1; // Release threshold
    }
    // Debounce: 3 samples for touch, 3 for release
    if (mpr121_write_reg(handle, MPR121_DEBOUNCE, 0x33) < 0) return -1;
    // Enter Run Mode with 12 electrodes enabled
    if (mpr121_write_reg(handle, MPR121_ECR, 0x8F) < 0) return -1;
    gpioDelay(100000); // 100 ms for stabilization
    return 0;
}

int read_touch_status(int handle) {
    int low = i2cReadByteData(handle, MPR121_TOUCHSTATUS_L);
    if (low < 0) {
        fprintf(stderr, "Error reading touch status low byte: %d\n", low);
        return -1;
    }
    int high = i2cReadByteData(handle, MPR121_TOUCHSTATUS_H);
    if (high < 0) {
        fprintf(stderr, "Error reading touch status high byte: %d\n", high);
        return -1;
    }
    return (high << 8) | low;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        int touch_status = read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (touch_status > 0) {
            int current_state = gpioRead(RELAY_PIN);
            gpioWrite(RELAY_PIN, !current_state);
            printf("Touch detected! Relay toggled to %d\n", !current_state);
        }

        gpioDelay(100000); // 100 ms
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

