                last_motion_tick = now;
            } else {
                log_event("Motion detected (rate-limited)");
            }
        }
        last_state = pir_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("System shutting down");
    gpioWrite(RELAY_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

