#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define WEIGHT_THRESHOLD 10.0
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define HX711_TIMEOUT_US 500000

static double scale_factor = 1.0;
static double offset = 0.0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin, long *out_value) {
    long value = 0;
    int i;

    for (i = 0; i < 24; i++) {
        if (gpioWrite(clock_pin, 1) < 0) return -1;
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(data_pin)) value++;
        if (gpioWrite(clock_pin, 0) < 0) return -1;
        gpioDelay(1);
    }

    if (gpioWrite(clock_pin, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(clock_pin, 0) < 0) return -1;
    gpioDelay(1);

    if (value & 0x800000) value |= ~0xFFFFFF;

    *out_value = value;
    return 0;
}

static int calibrate_hx711(int data_pin, int clock_pin, double *scale, double *off) {
    long sum = 0;
    int i;
    printf("Starting calibration...\n");

    for (i = 0; i < 100; i++) {
        long val;
        if (read_hx711(data_pin, clock_pin, &val) != 0) {
            fprintf(stderr, "Error: HX711 read failed during calibration.\n");
            return -1;
        }
        sum += val;
        gpioDelay(10000);
    }

    *off = (double)sum / 100.0;
    printf("Calibration offset: %.2f\n", *off);

    sum = 0;
    for (i = 0; i < 100; i++) {
        long val;
        if (read_hx711(data_pin, clock_pin, &val) != 0) {
            fprintf(stderr, "Error: HX711 read failed during calibration.\n");
            return -1;
        }
        sum += val - *off;
        gpioDelay(10000);
    }

    *scale = 1000.0 / ((double)sum / 100.0);
    printf("Calibration scale: %.2f\n", *scale);

    return 0;
}

static int load_calibration(const char *filename, double *scale, double *off) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open calibration file '%s'. Using defaults.\n", filename);
        return -1;
    }

    if (fscanf(fp, "%lf %lf", scale, off) != 2) {
        fprintf(stderr, "Warning: Invalid calibration data in '%s'. Using defaults.\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Loaded calibration: scale=%.2f, offset=%.2f\n", *scale, *off);
    return 0;
}

static int save_calibration(const char *filename, double scale, double off) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Error: Could not open calibration file '%s' for writing.\n", filename);
        return -1;
    }

    fprintf(fp, "%.6f %.6f\n", scale, off);
    fclose(fp);
    printf("Calibration saved to '%s'.\n", filename);
    return 0;
}

static double convert_to_weight(long raw_value, double scale, double off) {
    return (double)(raw_value - off) / scale;
}

static int log_weight(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file '%s'.\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Weight: %.2f kg\n", timestamp, weight);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    if (load_calibration(CALIBRATION_FILE, &scale_factor, &offset) != 0) {
        if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &scale_factor, &offset) != 0) {
            fprintf(stderr, "Error: Calibration failed.\n");
            gpioTerminate();
            return 1;
        }
        save_calibration(CALIBRATION_FILE, scale_factor, offset);
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin mode.\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(SOLENOID_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting weight monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        long raw_value;
        if (read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw_value) != 0) {
            fprintf(stderr, "Error: HX711 read failed.\n");
            gpioDelay(100000);
            continue;
        }

        double weight = convert_to_weight(raw_value, scale_factor, offset);

        if (weight > WEIGHT_THRESHOLD) {
            gpioWrite(SOLENOID_PIN, 1);
            printf("Weight %.2f kg exceeds threshold. Solenoid engaged.\n", weight);
        } else {
            gpioWrite(SOLENOID_PIN, 0);
            printf("Weight %.2f kg within threshold. Solenoid released.\n", weight);
        }

        if (log_weight(weight) != 0) {
            fprintf(stderr, "Warning: Failed to log weight.\n");
        }

        gpioDelay(500000);
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return 0;
}

