#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 50000
#define MOTOR_RUN_TIME_S 5
#define CHECK_INTERVAL_S 60
#define POST_CLOSE_DELAY_S 60

#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (gpioRead(RAIN_SENSOR_PIN) == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_US);
    }
    return (low_count >= 3) ? 1 : 0;
}

static void close_window(void) {
    syslog(LOG_INFO, "Closing window...");
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 high");
        return;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low");
        gpioWrite(MOTOR_IN1_PIN, 0);
        return;
    }
    if (gpioPWM(MOTOR_PWM_PIN, PWM_DUTY_CYCLE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM duty cycle");
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        return;
    }
    gpioDelay(MOTOR_RUN_TIME_S * 1000000);
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 low");
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low");
    }
    if (gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to stop PWM");
    }
    syslog(LOG_INFO, "Window closed.");
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor IN1 pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor IN2 pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor PWM pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_PWM_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0 || gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialise motor pins");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialise PWM");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Window control system started.");

    while (running) {
        if (read_rain_sensor()) {
            log_event("Rain detected!");
            close_window();
            for (int i = 0; i < POST_CLOSE_DELAY_S && running; i++) {
                sleep(1);
            }
        } else {
            for (int i = 0; i < CHECK_INTERVAL_S && running; i++) {
                sleep(1);
            }
        }
    }

    log_event("Shutting down...");
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

