#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17
#define STOCK_THRESHOLD 100.0
#define SOLENOID_DURATION 5
#define POLL_INTERVAL 1
#define HX711_TIMEOUT_US 1000000
#define HX711_SETTLE_US 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int dt, int sck, long *out) {
    int i;
    long count = 0;
    uint32_t start;

    if (gpioSetMode(dt, PI_INPUT) != 0) return -1;
    if (gpioSetMode(sck, PI_OUTPUT) != 0) return -1;
    if (gpioWrite(sck, 0) != 0) return -1;

    start = gpioTick();
    while (gpioRead(dt) == 1) {
        if ((int)(gpioTick() - start) > HX711_TIMEOUT_US) return -2;
    }

    for (i = 0; i < 24; i++) {
        if (gpioWrite(sck, 1) != 0) return -1;
        gpioDelay(HX711_SETTLE_US);
        count = count << 1;
        if (gpioRead(dt) == 1) count++;
        if (gpioWrite(sck, 0) != 0) return -1;
        gpioDelay(HX711_SETTLE_US);
    }

    if (gpioWrite(sck, 1) != 0) return -1;
    gpioDelay(HX711_SETTLE_US);
    if (gpioWrite(sck, 0) != 0) return -1;
    gpioDelay(HX711_SETTLE_US);

    if (count & 0x800000) count |= 0xFF000000;
    *out = count;
    return 0;
}

static float calculate_weight(long raw) {
    return (float)raw / 100.0;
}

