#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define WEIGHT_THRESHOLD 5.0
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define CALIBRATION_TIMEOUT_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;
static double calibration_factor = 1.0;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read 24-bit signed value from HX711 with timeout protection. */
static long read_hx711(void) {
    long data = 0;
    int i;

    /* Wait for data line to go low (data ready) with timeout */
    uint32_t start = gpioTick();
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if ((int32_t)(gpioTick() - start) > CALIBRATION_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout: data line stuck high\n");
            return 0x80000000L;  /* sentinel error code */
        }
    }

    /* Read 24 bits, MSB first */
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);  /* 1 us high */
        data = (data << 1) | (gpioRead(HX711_DATA_PIN) & 1);
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);  /* 1 us low */
    }

    /* 25th pulse to set gain to 128 for next reading */
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    /* Convert 24-bit two's complement to signed 32-bit */
    if (data & 0x800000L) {
        data |= 0xFF000000L;
    }
    return data;
}

static double calculate_weight(long raw_value) {
    return (double)raw_value / calibration_factor;
}

static int calibrate_hx711(void) {
    double known_weight;
    long raw_value;
    FILE *fp;

    printf("Place a known weight on the load cell (in kg): ");
    fflush(stdout);
    if (scanf("%lf", &known_weight) != 1 || known_weight <= 0.0) {
        fprintf(stderr, "Invalid weight input\n");
        return -1;
    }

    printf("Reading raw value...\n");
    raw_value = read_hx711();
    if (raw_value == 0x80000000L) {
        fprintf(stderr, "HX711 read failed during calibration\n");
        return -1;
    }

    calibration_factor = (double)raw_value / known_weight;
    printf("Calibration factor: %.6f\n", calibration_factor);

    fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", CALIBRATION_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "%.6f", calibration_factor);
    fclose(fp);
    printf("Calibration data saved to %s\n", CALIBRATION_FILE);
    return 0;
}

static int load_calibration(void) {
    FILE *fp;
    double factor;

    fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: %s not found, using default calibration factor\n", CALIBRATION_FILE);
        return -1;
    }
    if (fscanf(fp, "%lf", &factor) != 1) {
        fprintf(stderr, "Warning: invalid calibration data in %s, using default\n", CALIBRATION_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    calibration_factor = factor;
    printf("Calibration factor loaded: %.6f\n", calibration_factor);
    return 0;
}

static void log_event(double weight) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Weight exceeded threshold: %.2f kg\n", timestamp, weight);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: log file not open\n");
    }
}

static void control_solenoid(int lock) {
    if (lock) {
        printf("Locking solenoid...\n");
        gpioWrite(SOLENOID_PIN, 1);
        gpioDelay(5000000);  /* 5 seconds */
        gpioWrite(SOLENOID_PIN, 0);
        printf("Solenoid unlocked.\n");
    } else {
        gpioWrite(SOLENOID_PIN, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (load_calibration() != 0) {
        if (calibrate_hx711() != 0) {
            fprintf(stderr, "Calibration failed, exiting\n");
            fclose(log_file);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Weight monitoring system started. Press Ctrl+C to exit.\n");

    while (running) {
        long raw_value = read_hx711();
        if (raw_value == 0x80000000L) {
            fprintf(stderr, "HX711 read failed, skipping cycle\n");
            gpioDelay(1000000);
            continue;
        }

        double weight = calculate_weight(raw_value);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            log_event(weight);
            control_solenoid(1);
        }

        gpioDelay(100000);  /* 100 ms between readings */
    }

    /* Graceful cleanup */
    control_solenoid(0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

