        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Weight monitoring system started. Press Ctrl+C to exit.\n");

    while (running) {
        long raw_value = read_hx711();
        if (raw_value == 0x80000000L) {
            fprintf(stderr, "HX711 read failed, skipping cycle\n");
            gpioDelay(1000000);
            continue;
        }

        double weight = calculate_weight(raw_value);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            log_event(weight);
            control_solenoid(1);
        }

        gpioDelay(100000);  /* 100 ms between readings */
    }

    /* Graceful cleanup */
    control_solenoid(0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

