#include <time.h>
#include <gpiod.h>

#define CONFIG_FILE "watering.conf"
#define GPIO_CHIP_NAME "gpiochip0"
#define VALVE_GPIO_LINE 18
#define MIN_DURATION 1
#define MAX_DURATION 3600

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_config(const char *filename, int *duration)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        if (feof(fp)) {
            fprintf(stderr, "Config file '%s' is empty\n", filename);
        } else {
            fprintf(stderr, "Error reading config file '%s': %s\n",
                    filename, strerror(errno));
        }
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Strip trailing newline */
    line[strcspn(line, "\r\n")] = '\0';

    char *eq = strchr(line, '=');
    if (!eq) {
        fprintf(stderr, "Malformed config line: missing '='\n");
        return -1;
    }

    *eq = '\0';
    char *key = line;
    char *val = eq + 1;

    if (strcmp(key, "duration") != 0) {
        fprintf(stderr, "Unexpected config key '%s', expected 'duration'\n", key);
        return -1;
    }

    errno = 0;
    char *endptr = NULL;
    long val_l = strtol(val, &endptr, 10);
    if (errno != 0 || endptr == val || *endptr != '\0') {
        fprintf(stderr, "Invalid duration value: '%s'\n", val);
        return -1;
    }

    if (val_l < MIN_DURATION || val_l > MAX_DURATION) {
        fprintf(stderr, "Duration out of range: %ld (must be %d-%d)\n",
                val_l, MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *duration = (int)val_l;
    return 0;
}

static void sleep_interruptible(unsigned int seconds)
{
    while (seconds > 0 && g_running) {
        unsigned int remaining = sleep(seconds);
        if (remaining == 0) {
            break;
        }
        seconds = remaining;
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, VALVE_GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                VALVE_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "watering-valve", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                VALVE_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    int duration = 0;
    if (read_config(CONFIG_FILE, &duration) != 0) {
        goto cleanup;
    }

    printf("Watering duration: %d seconds\n", duration);
    fflush(stdout);

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to activate valve: %s\n", strerror(errno));
        goto cleanup;
    }
    printf("Valve ON\n");
    fflush(stdout);

    sleep_interruptible((unsigned int)duration);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to deactivate valve: %s\n", strerror(errno));
        goto cleanup;
    }
    printf("Valve OFF\n");
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

