#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_LEFT   4
#define SENSOR_MIDDLE 17
#define SENSOR_RIGHT  27

#define MOTOR_LEFT_FORWARD  22
#define MOTOR_LEFT_BACKWARD 23
#define MOTOR_RIGHT_FORWARD 24
#define MOTOR_RIGHT_BACKWARD 25

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255

#define BASE_SPEED 150
#define TURN_SCALE 0.5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int gpio) {
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return v;
}

static void set_motor(int forward_pin, int backward_pin, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    if (speed == 0) {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
        gpioPWM(forward_pin, 0);
        gpioPWM(backward_pin, 0);
    } else {
        gpioWrite(forward_pin, 1);
        gpioWrite(backward_pin, 0);
        gpioPWM(forward_pin, speed);
        gpioPWM(backward_pin, 0);
    }
}

static void log_data(int s1, int s2, int s3, int l, int r) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(log_file, "%s, S1=%d, S2=%d, S3=%d, L=%d, R=%d\n", ts, s1, s2, s3, l, r);
    fflush(log_file);
}

static void cleanup(void) {
    set_motor(MOTOR_LEFT_FORWARD, MOTOR_LEFT_BACKWARD, 0);
    set_motor(MOTOR_RIGHT_FORWARD, MOTOR_RIGHT_BACKWARD, 0);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {SENSOR_LEFT, SENSOR_MIDDLE, SENSOR_RIGHT,
                  MOTOR_LEFT_FORWARD, MOTOR_LEFT_BACKWARD,
                  MOTOR_RIGHT_FORWARD, MOTOR_RIGHT_BACKWARD};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "gpioSetMode failed on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetPWMfrequency(MOTOR_LEFT_FORWARD, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_LEFT_BACKWARD, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_RIGHT_FORWARD, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_RIGHT_BACKWARD, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_LEFT_FORWARD, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_LEFT_BACKWARD, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_RIGHT_FORWARD, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_RIGHT_BACKWARD, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("trace_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line-following robot started. Press Ctrl+C to stop.\n");

    while (running) {
        int s1 = read_sensor(SENSOR_LEFT);
        int s2 = read_sensor(SENSOR_MIDDLE);
        int s3 = read_sensor(SENSOR_RIGHT);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "Sensor read error, stopping motors\n");
            set_motor(MOTOR_LEFT_FORWARD, MOTOR_LEFT_BACKWARD, 0);
            set_motor(MOTOR_RIGHT_FORWARD, MOTOR_RIGHT_BACKWARD, 0);
            break;
        }

        int left_speed = BASE_SPEED;
        int right_speed = BASE_SPEED;

        if (s1 == 0) {
            left_speed = (int)(BASE_SPEED * TURN_SCALE);
        } else if (s3 == 0) {
            right_speed = (int)(BASE_SPEED * TURN_SCALE);
        }

        set_motor(MOTOR_LEFT_FORWARD, MOTOR_LEFT_BACKWARD, left_speed);
        set_motor(MOTOR_RIGHT_FORWARD, MOTOR_RIGHT_BACKWARD, right_speed);

        log_data(s1, s2, s3, left_speed, right_speed);

        gpioDelay(10000);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

