#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22

#define SERVO_MIN_PW 500
#define SERVO_MAX_PW 2500
#define SERVO_LOCK_PW 1000
#define SERVO_UNLOCK_PW 2000

static volatile int running = 1;

void cleanup(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);

    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    gpioServo(SERVO_PIN, SERVO_UNLOCK_PW);

    printf("Door lock control started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            gpioDelay(100000);
            if (gpioRead(LOCK_BUTTON) == 0) {
                gpioServo(SERVO_PIN, SERVO_LOCK_PW);
                printf("Locking door...\n");
                while (gpioRead(LOCK_BUTTON) == 0 && running) {
                    gpioDelay(10000);
                }
                gpioServo(SERVO_PIN, SERVO_UNLOCK_PW);
            }
        }

        if (gpioRead(UNLOCK_BUTTON) == 0) {
            gpioDelay(100000);
            if (gpioRead(UNLOCK_BUTTON) == 0) {
                gpioServo(SERVO_PIN, SERVO_UNLOCK_PW);
                printf("Unlocking door...\n");
                while (gpioRead(UNLOCK_BUTTON) == 0 && running) {
                    gpioDelay(10000);
                }
                gpioServo(SERVO_PIN, SERVO_LOCK_PW);
            }
        }

        gpioDelay(10000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Door lock control stopped.\n");
    return EXIT_SUCCESS;
}

