#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define CONSUMER "haptic-feedback"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line_motor1 = NULL;
static struct gpiod_line *line_motor2 = NULL;
static volatile sig_atomic_t keep_running = 1;

static void cleanup_resources(void) {
    if (line_motor1) {
        gpiod_line_set_value(line_motor1, 0);
        gpiod_line_release(line_motor1);
        line_motor1 = NULL;
    }
    if (line_motor2) {
        gpiod_line_set_value(line_motor2, 0);
        gpiod_line_release(line_motor2);
        line_motor2 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    line_motor1 = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!line_motor1) {
        perror("Failed to get GPIO17 line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    line_motor2 = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!line_motor2) {
        perror("Failed to get GPIO27 line");
        gpiod_line_release(line_motor1);
        line_motor1 = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(line_motor1, CONSUMER, 0) < 0) {
        perror("Failed to request GPIO17 as output");
        gpiod_line_release(line_motor1);
        line_motor1 = NULL;
        gpiod_line_release(line_motor2);
        line_motor2 = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(line_motor2, CONSUMER, 0) < 0) {
        perror("Failed to request GPIO27 as output");
        gpiod_line_release(line_motor1);
        line_motor1 = NULL;
        gpiod_line_release(line_motor2);
        line_motor2 = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    return 0;
}

static void pulse_motor(struct gpiod_line *line, int duration_ms) {
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to set motor line high");
        return;
    }
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set motor line low");
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    while (keep_running) {
        pulse_motor(line_motor1, 200);
        if (!keep_running) break;
        pulse_motor(line_motor2, 300);
    }

    cleanup_resources();
    return EXIT_SUCCESS;
}

