#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>
#include <zmq.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define ZMQ_SERVER_ADDRESS "tcp://*:5555"
#define ZMQ_CLIENT_ADDRESS "tcp://localhost:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"
#define POLL_TIMEOUT_MS 100
#define POLL_INTERVAL_US 10000
#define ALARM_DURATION_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  sound_sensor: poll sound sensor on GPIO17\n");
        fprintf(stderr, "  alarm_node:   subscribe to ZMQ on %s\n", ZMQ_CLIENT_ADDRESS);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    if (strcmp(mode, "sound_sensor") != 0 && strcmp(mode, "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_line) {
        perror("gpiod_chip_get_line(sound)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(led)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sound_line, "sound_sensor") < 0) {
        perror("gpiod_line_request_input(sound)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "alarm_led", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    void *zmq_ctx = zmq_ctx_new();
    if (!zmq_ctx) {
        perror("zmq_ctx_new");
        gpiod_line_release(sound_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    void *zmq_pub = zmq_socket(zmq_ctx, ZMQ_PUB);
    if (!zmq_pub) {
        perror("zmq_socket(pub)");
        zmq_ctx_destroy(zmq_ctx);
        gpiod_line_release(sound_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (zmq_bind(zmq_pub, ZMQ_SERVER_ADDRESS) < 0) {
        perror("zmq_bind");
        zmq_close(zmq_pub);
        zmq_ctx_destroy(zmq_ctx);
        gpiod_line_release(sound_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    void *zmq_sub = zmq_socket(zmq_ctx, ZMQ_SUB);
    if (!zmq_sub) {
        perror("zmq_socket(sub)");
        zmq_close(zmq_pub);
        zmq_ctx_destroy(zmq_ctx);
        gpiod_line_release(sound_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (zmq_connect(zmq_sub, ZMQ_CLIENT_ADDRESS) < 0) {
        perror("zmq_connect");
        zmq_close(zmq_pub);
        zmq_close(zmq_sub);
        zmq_ctx_destroy(zmq_ctx);
        gpiod_line_release(sound_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (zmq_setsockopt(zmq_sub, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC)) < 0) {
        perror("zmq_setsockopt(ZMQ_SUBSCRIBE)");
        zmq_close(zmq_pub);
        zmq_close(zmq_sub);
        zmq_ctx_destroy(zmq_ctx);
        gpiod_line_release(sound_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Sound-triggered alarm started. Mode: %s\n", mode);

    while (running) {
        if (strcmp(mode, "sound_sensor") == 0) {
            int val = gpiod_line_get_value(sound_line);
            if (val < 0) {
                perror("gpiod_line_get_value(sound)");
                break;
            }
            if (val == 0) {
                char msg[64];
                snprintf(msg, sizeof(msg), "%s: Sound detected", ZMQ_TOPIC);
                if (zmq_send(zmq_pub, msg, strlen(msg), 0) < 0) {
                    perror("zmq_send");
                    break;
                }
            }
            sleep_us(POLL_INTERVAL_US);
        } else if (strcmp(mode, "alarm_node") == 0) {
            zmq_msg_t msg;
            int rc = zmq_msg_init(&msg);
            if (rc < 0) {
                perror("zmq_msg_init");
                break;
            }
            rc = zmq_recv(zmq_sub, &msg, 0);
            if (rc < 0) {
                if (errno == EINTR) continue;
                perror("zmq_recv");
                zmq_msg_close(&msg);
                break;
            }
            if (rc > 0) {
                printf("Alert received: %s\n", (char *)zmq_msg_data(&msg));
                if (gpiod_line_set_value(led_line, 1) < 0) {
                    perror("gpiod_line_set_value(led on)");
                    zmq_msg_close(&msg);
                    break;
                }
                sleep_us(ALARM_DURATION_MS * 1000U);
                if (gpiod_line_set_value(led_line, 0) < 0) {
                    perror("gpiod_line_set_value(led off)");
                    zmq_msg_close(&msg);
                    break;
                }
            }
            zmq_msg_close(&msg);
        }
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(led_line, 0);
    zmq_close(zmq_pub);
    zmq_close(zmq_sub);
    zmq_ctx_destroy(zmq_ctx);
    gpiod_line_release(sound_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

