        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (zmq_setsockopt(zmq_sub, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC)) < 0) {
        perror("zmq_setsockopt(ZMQ_SUBSCRIBE)");
        zmq_close(zmq_pub);
        zmq_close(zmq_sub);
        zmq_ctx_destroy(zmq_ctx);
        gpiod_line_release(sound_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Sound-triggered alarm started. Mode: %s\n", mode);

    while (running) {
        if (strcmp(mode, "sound_sensor") == 0) {
            int val = gpiod_line_get_value(sound_line);
            if (val < 0) {
                perror("gpiod_line_get_value(sound)");
                break;
            }
            if (val == 0) {
                char msg[64];
                snprintf(msg, sizeof(msg), "%s: Sound detected", ZMQ_TOPIC);
                if (zmq_send(zmq_pub, msg, strlen(msg), 0) < 0) {
                    perror("zmq_send");
                    break;
                }
            }
            sleep_us(POLL_INTERVAL_US);
        } else if (strcmp(mode, "alarm_node") == 0) {
            zmq_msg_t msg;
            int rc = zmq_msg_init(&msg);
            if (rc < 0) {
                perror("zmq_msg_init");
                break;
            }
            rc = zmq_recv(zmq_sub, &msg, 0);
            if (rc < 0) {
                if (errno == EINTR) continue;
                perror("zmq_recv");
                zmq_msg_close(&msg);
                break;
            }
            if (rc > 0) {
                printf("Alert received: %s\n", (char *)zmq_msg_data(&msg));
                if (gpiod_line_set_value(led_line, 1) < 0) {
                    perror("gpiod_line_set_value(led on)");
                    zmq_msg_close(&msg);
                    break;
                }
                sleep_us(ALARM_DURATION_MS * 1000U);
                if (gpiod_line_set_value(led_line, 0) < 0) {
                    perror("gpiod_line_set_value(led off)");
                    zmq_msg_close(&msg);
                    break;
                }
            }
            zmq_msg_close(&msg);
        }
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(led_line, 0);
    zmq_close(zmq_pub);
    zmq_close(zmq_sub);
    zmq_ctx_destroy(zmq_ctx);
    gpiod_line_release(sound_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

