#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define IR_GPIO 17
#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MQTT_CLIENT_ID "ir_decoder"
#define MQTT_KEEP_ALIVE 60
#define MQTT_MAX_RETRIES 3
#define MQTT_RETRY_DELAY 2
#define MAX_PULSES 100
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_TOLERANCE 300
#define NEC_TIMEOUT 1000000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t pulse_count = 0;
static volatile uint32_t pulse_lengths[MAX_PULSES];
static volatile uint32_t last_tick = 0;
static volatile bool last_level = 1;
static volatile bool frame_ready = false;
static volatile uint32_t decoded_command = 0;
static volatile uint32_t decoded_address = 0;
static volatile bool decoding = false;

static MQTTClient mqtt_client = NULL;
static MQTTClient_connectOptions mqtt_conn_opts = MQTTClient_connectOptions_initializer;
static MQTTClient_message mqtt_message = MQTTClient_message_initializer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    syslog(LOG_ERR, "%s", msg);
}

static void log_info(const char *msg) {
    syslog(LOG_INFO, "%s", msg);
}

static void log_debug(const char *msg) {
    syslog(LOG_DEBUG, "%s", msg);
}

static void decode_nec_frame(void) {
    if (pulse_count < 34) {
        log_error("Pulse count too small for NEC frame");
        decoding = false;
        return;
    }

    uint32_t address = 0;
    uint32_t command = 0;

    for (int i = 0; i < 16; i++) {
        if (pulse_lengths[i * 2 + 1] > NEC_BIT_MARK + NEC_TOLERANCE) {
            address |= (1 << i);
        }
    }

    for (int i = 0; i < 16; i++) {
        if (pulse_lengths[34 + i * 2 + 1] > NEC_BIT_MARK + NEC_TOLERANCE) {
            command |= (1 << i);
        }
    }

    uint8_t address_inv = (uint8_t)(~address & 0xFF);
    uint8_t command_inv = (uint8_t)(~command & 0xFF);

    if ((address_inv != (address & 0xFF)) || (command_inv != (command & 0xFF))) {
        log_error("NEC checksum failed");
        decoding = false;
        return;
    }

    decoded_address = address;
    decoded_command = command;
    frame_ready = true;
    decoding = false;
}

static void ir_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == PI_TIMEOUT) return;

    uint32_t diff = tick - last_tick;
    last_tick = tick;

    if (diff > NEC_TIMEOUT) {
        if (decoding) {
            decode_nec_frame();
        }
        decoding = false;
        pulse_count = 0;
        return;
    }

    if (pulse_count < MAX_PULSES) {
        pulse_lengths[pulse_count++] = diff;
    } else {
        log_error("Pulse buffer overflow");
        decoding = false;
        pulse_count = 0;
        return;
    }

    if (pulse_count >= 34) {
        if (decoding) {
            decode_nec_frame();
        }
        decoding = true;
    }
}

static int mqtt_connect(void) {
    int rc = MQTTClient_connect(mqtt_client, &mqtt_conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

static void mqtt_publish(void) {
    if (!frame_ready) return;

    char json[128];
    snprintf(json, sizeof(json), "{\"address\": %u, \"command\": %u}", decoded_address, decoded_command);

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &mqtt_message, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", MQTTClient_strerror(rc));
    } else {
        MQTTClient_waitForCompletion(mqtt_client, token, 1000);
        log_info("Published to MQTT");
    }
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        log_error("pigpio init failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    if (gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL) != 0) {
        log_error("Failed to set alert function");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    int rc = MQTTClient_create(&mqtt_client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        log_error("MQTT create failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mqtt_conn_opts.keepAliveInterval = MQTT_KEEP_ALIVE;
    mqtt_conn_opts.cleansession = 1;
    mqtt_conn_opts.connectTimeout = 10;
    mqtt_conn_opts.retryInterval = MQTT_RETRY_DELAY;
    mqtt_conn_opts.maxRetry = MQTT_MAX_RETRIES;

    mqtt_message.payload = NULL;
    mqtt_message.payloadlen = 0;
    mqtt_message.qos = 0;
    mqtt_message.retained = 0;

    if (mqtt_connect() != 0) {
        MQTTClient_destroy(&mqtt_client);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    log_info("IR decoder started");

    while (running) {
        mqtt_publish();
        sleep(1);
    }

    log_info("Shutting down");

    if (mqtt_client) {
        MQTTClient_disconnect(mqtt_client, 1000);
        MQTTClient_destroy(&mqtt_client);
    }
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

