    usleep(CONV_TIME_MS * 1000);
    uint8_t data[2];
    ssize_t r = read(fd, data, 2);
    if (r != 2) {
        fprintf(stderr, "BH1750 read failed: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(int sockfd, const char *msg) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);
    if (sendto(sockfd, msg, strlen(msg), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int i2c_fds[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        char name[16];
        snprintf(name, sizeof(name), "BH1750_%d", i + 1);
        i2c_fds[i] = i2c_open(I2C_BUS, BH1750_ADDR + i);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "%s: init failed\n", name);
        } else {
            printf("%s: I2C opened (fd=%d)\n", name, i2c_fds[i]);
        }
    }

    int udp_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_fd < 0) {
        fprintf(stderr, "socket() failed: %s\n", strerror(errno));
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_fds[i] >= 0) close(i2c_fds[i]);
        }
        return 1;
    }

    int ttl = 1;
    if (setsockopt(udp_fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "setsockopt(IP_MULTICAST_TTL) failed: %s\n", strerror(errno));
        close(udp_fd);
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_fds[i] >= 0) close(i2c_fds[i]);
        }
        return 1;
    }

    printf("Starting BH1750 multicast (Ctrl+C to stop)...\n");

    while (g_running) {
        char msg[256] = {0};
        int ok = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            float lux = NAN;
            if (i2c_fds[i] >= 0) {
                if (bh1750_read(i2c_fds[i], &lux) == 0) {
                    ok = 1;
                }
            }
            char val[32];
            if (isnan(lux)) {
                snprintf(val, sizeof(val), "NaN");
            } else {
                snprintf(val, sizeof(val), "%.2f", lux);
            }
            char id[8];
            snprintf(id, sizeof(id), "%d", i + 1);
            char kv[64];
            snprintf(kv, sizeof(kv), "%s,%s", id, val);
            if (msg[0] != '\0') {
                strncat(msg, ";", sizeof(msg) - strlen(msg) - 1);
            }
            strncat(msg, kv, sizeof(msg) - strlen(msg) - 1);
        }

        if (ok) {
            printf("Sending: %s\n", msg);
            if (send_multicast(udp_fd, msg) < 0) {
                fprintf(stderr, "Multicast send failed\n");
            }
        } else {
            fprintf(stderr, "All sensors failed this cycle\n");
        }

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_fds[i] >= 0) {
            close(i2c_fds[i]);
            printf("I2C fd %d closed\n", i2c_fds[i]);
        }
    }
    close(udp_fd);
    printf("UDP socket closed\n");
    return 0;
}

