/*
 * AS7341 10-Channel Light/Color Sensor reader for Raspberry Pi 3 Model B+
 * Uses the Linux i2c-dev kernel interface (no wiringPi).
 *
 * Wiring:
 *   AS7341 SDA  -> GPIO2 (pin 3, I2C1 SDA)
 *   AS7341 SCL  -> GPIO3 (pin 5, I2C1 SCL)
 *   AS7341 VDD  -> 3.3 V
 *   AS7341 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o as7341_reader as7341_reader.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- AS7341 register definitions (per datasheet) ---- */
#define AS7341_I2C_ADDR        0x39
#define AS7341_REG_ENABLE      0x80
#define AS7341_REG_ATIME       0x81
#define AS7341_REG_CFG0        0x83
#define AS7341_REG_CFG1        0x84
#define AS7341_REG_CFG2        0x85
#define AS7341_REG_CFG3        0x86
#define AS7341_REG_CFG4        0x87
#define AS7341_REG_CFG5        0x88
#define AS7341_REG_CFG6        0xAF
#define AS7341_REG_ID          0x24
#define AS7341_REG_CH0_DATA    0x60
#define AS7341_REG_CH1_DATA    0x61
#define AS7341_REG_CH2_DATA    0x62
#define AS7341_REG_CH3_DATA    0x63
#define AS7341_REG_CH4_DATA    0x64
#define AS7341_REG_CH5_DATA    0x65
#define AS7341_REG_CH6_DATA    0x66
#define AS7341_REG_CH7_DATA    0x67
#define AS7341_REG_CH8_DATA    0x68  /* Clear */
#define AS7341_REG_CH9_DATA    0x69  /* NIR  */

#define AS7341_ENABLE_PON      0x01
#define AS7341_ENABLE_SP_EN    0x02
#define AS7341_ID_EXPECTED     0x19

#define I2C_BUS               "/dev/i2c-1"
#define LOG_FILE              "spectral_log.csv"
#define SAMPLE_INTERVAL_SEC   5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register. Returns 0 on success, -1 on error. */
static int reg_write(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register. Returns 0 on success, -1 on error. */
static int reg_read(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of 10 bytes starting at CH0_DATA (0x60). Returns 0 on success. */
static int read_spectral_data(int fd, uint16_t *ch0, uint16_t *ch1,
                              uint16_t *ch2, uint16_t *ch3,
                              uint16_t *ch4, uint16_t *ch5,
                              uint16_t *ch6, uint16_t *ch7,
                              uint16_t *ch8, uint16_t *ch9)
{
    uint8_t data[10];
    ssize_t n = read(fd, data, sizeof(data));
    if (n != (ssize_t)sizeof(data)) {
        fprintf(stderr, "I2C spectral read failed: expected 10 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    *ch0 = (uint16_t)data[0]  | ((uint16_t)data[1]  << 8);
    *ch1 = (uint16_t)data[2]  | ((uint16_t)data[3]  << 8);
    *ch2 = (uint16_t)data[4]  | ((uint16_t)data[5]  << 8);
    *ch3 = (uint16_t)data[6]  | ((uint16_t)data[7]  << 8);
    *ch4 = (uint16_t)data[8]  | ((uint16_t)data[9]  << 8);
    *ch5 = (uint16_t)data[10] | ((uint16_t)data[11] << 8);
    *ch6 = (uint16_t)data[12] | ((uint16_t)data[13] << 8);
    *ch7 = (uint16_t)data[14] | ((uint16_t)data[15] << 8);
    *ch8 = (uint16_t)data[16] | ((uint16_t)data[17] << 8);
    *ch9 = (uint16_t)data[18] | ((uint16_t)data[19] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Simplified lux approximation: sum of the first 8 channels. */
static float calculate_lux(uint16_t ch0, uint16_t ch1, uint16_t ch2,
                           uint16_t ch3, uint16_t ch4, uint16_t ch5,
                           uint16_t ch6, uint16_t ch7)
{
    return (float)(ch0 + ch1 + ch2 + ch3 + ch4 + ch5 + ch6 + ch7);
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AS7341_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                AS7341_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    uint8_t id = 0;
    if (reg_read(g_i2c_fd, AS7341_REG_ID, &id) != 0) {
        fprintf(stderr, "Cannot read AS7341 ID register.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (id != AS7341_ID_EXPECTED) {
        fprintf(stderr, "Unexpected AS7341 ID: 0x%02X (expected 0x%02X).\n",
                id, AS7341_ID_EXPECTED);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("AS7341 detected (ID = 0x%02X).\n", id);

    /* Power on */
    if (reg_write(g_i2c_fd, AS7341_REG_ENABLE, AS7341_ENABLE_PON) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    usleep(10000); /* 10 ms power-on settling */

    /* Configure SMUX for spectral readings (CFG6: 0x0C = 12-bit, 1x gain) */
    if (reg_write(g_i2c_fd, AS7341_REG_CFG6, 0x0C) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable spectral measurement */
    if (reg_write(g_i2c_fd, AS7341_REG_ENABLE, AS7341_ENABLE_PON | AS7341_ENABLE_SP_EN) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,lux\n");
        fflush(g_log_fp);
    }

    printf("Logging spectral data to %s every %d seconds. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (g_running) {
        uint16_t ch0, ch1, ch2, ch3, ch4, ch5, ch6, ch7, ch8, ch9;

        if (read_spectral_data(g_i2c_fd, &ch0, &ch1, &ch2, &ch3, &ch4, &ch5,
                               &ch6, &ch7, &ch8, &ch9) != 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float lux = calculate_lux(ch0, ch1, ch2, ch3, ch4, ch5, ch6, ch7);

        if (log_data(g_log_fp, lux) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("Lux: %.2f  (ch0=%u ch1=%u ch2=%u ch3=%u ch4=%u ch5=%u ch6=%u ch7=%u ch8=%u ch9=%u)\n",
               lux, ch0, ch1, ch2, ch3, ch4, ch5, ch6, ch7, ch8, ch9);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

