#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <getopt.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define ERROR_LOG_FILENAME "seismic_error.log"
#define ACCEL_REG 0x28
#define ACCEL_BYTES 6
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_MS 10
#define GRAVITY_PER_LSB 0.000244f

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *data_file = NULL;
static FILE *error_log = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    if (!error_log) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(error_log, "%s: %s (errno: %d - %s)\n", ts, message, errno, strerror(errno));
    fflush(error_log);
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            log_error("I2C write (reg select) failed");
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(fd, val, 1) != 1) {
            log_error("I2C read failed");
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        return 0;
    }
    return -1;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            log_error("I2C write (reg select) failed");
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        ssize_t n = read(fd, buf, len);
        if (n < 0 || (size_t)n != len) {
            log_error("I2C block read failed");
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        return 0;
    }
    return -1;
}

static int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t buf[ACCEL_BYTES];
    if (i2c_read_block(fd, ACCEL_REG, buf, ACCEL_BYTES) != 0) {
        log_error("Failed to read acceleration data");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x * GRAVITY_PER_LSB;
    *y = (float)raw_y * GRAVITY_PER_LSB;
    *z = (float)raw_z * GRAVITY_PER_LSB;
    return 0;
}

static void log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(data_file, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z);
    fflush(data_file);
}

static void cleanup(void) {
    if (data_file) { fclose(data_file); data_file = NULL; }
    if (error_log) { fclose(error_log); error_log = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int interval = DEFAULT_INTERVAL;
    const char *filename = DEFAULT_FILENAME;

    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a': i2c_address = (int)strtol(optarg, NULL, 0); break;
            case 'i': interval = atoi(optarg); break;
            case 'f': filename = optarg; break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval_sec] [-f filename]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    error_log = fopen(ERROR_LOG_FILENAME, "a");
    if (!error_log) {
        fprintf(stderr, "Failed to open error log: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open /dev/i2c-1");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        log_error("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t probe;
    if (i2c_read_reg8(i2c_fd, ACCEL_REG, &probe) != 0) {
        log_error("Sensor not responding at given address");
        cleanup();
        return EXIT_FAILURE;
    }

    data_file = fopen(filename, "a");
    if (!data_file) {
        log_error("Failed to open data file");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(data_file, 0, SEEK_END);
    if (ftell(data_file) == 0) {
        fprintf(data_file, "timestamp,x_g,y_g,z_g\n");
        fflush(data_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic data logging started. Address: 0x%02X, Interval: %d s, File: %s\n", i2c_address, interval, filename);

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            log_error("Failed to read acceleration data during main loop");
        }
        sleep(interval);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

