#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <time.h>
#include <signal.h>
#include <sys/select.h>

#define UART_PORT "/dev/serial0"
#define BAUD_RATE B115200
#define LINE_BUF_SIZE 256
#define READ_BUF_SIZE 256
#define POLL_TIMEOUT_SEC 2
#define INTER_BYTE_TIMEOUT_MS 500

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag = 0;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);

    tty.c_lflag = 0;
    tty.c_oflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_line(int fd, char *buf, size_t buf_size) {
    size_t idx = 0;
    char ch;
    struct timeval tv = {0, INTER_BYTE_TIMEOUT_MS * 1000};

    while (idx < buf_size - 1) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        int ret = select(fd + 1, &readfds, NULL, NULL, &tv);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            return -1;
        }
        if (ret == 0) {
            if (idx == 0) return 0;
            buf[idx] = '\0';
            return (int)idx;
        }

        ssize_t n = read(fd, &ch, 1);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "read() error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) continue;

        if (ch == '\n') {
            buf[idx] = '\0';
            return (int)idx;
        }
        if (ch != '\r') {
            buf[idx++] = ch;
        }
    }

    buf[buf_size - 1] = '\0';
    return (int)buf_size - 1;
}

static void process_line(const char *line) {
    char *copy = strdup(line);
    if (!copy) {
        fprintf(stderr, "strdup() failed: %s\n", strerror(errno));
        return;
    }

    char *saveptr = NULL;
    char *token = strtok_r(copy, ",", &saveptr);
    if (!token) {
        free(copy);
        return;
    }

    char *endptr = NULL;
    long ts = strtol(token, &endptr, 10);
    if (endptr == token) {
        fprintf(stderr, "Invalid timestamp: %s\n", token);
        free(copy);
        return;
    }

    token = strtok_r(NULL, ",", &saveptr);
    if (!token) {
        fprintf(stderr, "Missing range value in line: %s\n", line);
        free(copy);
        return;
    }

    double range = strtod(token, &endptr);
    if (endptr == token) {
        fprintf(stderr, "Invalid range value: %s\n", token);
        free(copy);
        return;
    }

    time_t rawtime = (time_t)ts;
    struct tm *timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "localtime() failed\n");
        free(copy);
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range);
    fflush(stdout);

    free(copy);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    g_uart_fd = init_uart(UART_PORT);
    if (g_uart_fd < 0) {
        return 1;
    }

    char line_buf[LINE_BUF_SIZE];
    char read_buf[READ_BUF_SIZE];

    while (g_running) {
        int bytes_read = read_line(g_uart_fd, read_buf, sizeof(read_buf));
        if (bytes_read < 0) {
            fprintf(stderr, "UART read error, continuing...\n");
            continue;
        }
        if (bytes_read > 0) {
            size_t remaining = (size_t)bytes_read;
            while (remaining > 0 && g_running) {
                size_t to_copy = remaining < LINE_BUF_SIZE - 1 ? remaining : LINE_BUF_SIZE - 1;
                memcpy(line_buf, read_buf + (read_buf - line_buf) - (int)remaining, to_copy);
                line_buf[to_copy] = '\0';
                remaining -= to_copy;

                if (strchr(line_buf, '\n')) {
                    char *nl = strchr(line_buf, '\n');
                    *nl = '\0';
                    process_line(line_buf);
                    size_t consumed = (size_t)(nl - line_buf) + 1;
                    memmove(line_buf, line_buf + consumed, strlen(line_buf + consumed) + 1);
                }
            }
        } else {
            struct timeval tv = {POLL_TIMEOUT_SEC, 0};
            fd_set readfds;
            FD_ZERO(&readfds);
            FD_SET(g_uart_fd, &readfds);

            int ret = select(g_uart_fd + 1, &readfds, NULL, NULL, &tv);
            if (ret < 0) {
                if (errno == EINTR) continue;
                fprintf(stderr, "select() error: %s\n", strerror(errno));
            }
        }
    }

    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }

    printf("\nExiting gracefully.\n");
    return 0;
}

