    if (g_uart_fd < 0) {
        return 1;
    }

    char line_buf[LINE_BUF_SIZE];
    char read_buf[READ_BUF_SIZE];

    while (g_running) {
        int bytes_read = read_line(g_uart_fd, read_buf, sizeof(read_buf));
        if (bytes_read < 0) {
            fprintf(stderr, "UART read error, continuing...\n");
            continue;
        }
        if (bytes_read > 0) {
            size_t remaining = (size_t)bytes_read;
            while (remaining > 0 && g_running) {
                size_t to_copy = remaining < LINE_BUF_SIZE - 1 ? remaining : LINE_BUF_SIZE - 1;
                memcpy(line_buf, read_buf + (read_buf - line_buf) - (int)remaining, to_copy);
                line_buf[to_copy] = '\0';
                remaining -= to_copy;

                if (strchr(line_buf, '\n')) {
                    char *nl = strchr(line_buf, '\n');
                    *nl = '\0';
                    process_line(line_buf);
                    size_t consumed = (size_t)(nl - line_buf) + 1;
                    memmove(line_buf, line_buf + consumed, strlen(line_buf + consumed) + 1);
                }
            }
        } else {
            struct timeval tv = {POLL_TIMEOUT_SEC, 0};
            fd_set readfds;
            FD_ZERO(&readfds);
            FD_SET(g_uart_fd, &readfds);

            int ret = select(g_uart_fd + 1, &readfds, NULL, NULL, &tv);
            if (ret < 0) {
                if (errno == EINTR) continue;
                fprintf(stderr, "select() error: %s\n", strerror(errno));
            }
        }
    }

    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }

    printf("\nExiting gracefully.\n");
    return 0;
}

