#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_LEFT   4
#define SENSOR_MIDDLE 17
#define SENSOR_RIGHT  27
#define SERIAL_PORT   "/dev/ttyAMA0"
#define BAUD_RATE     115200
#define POLL_DELAY_US 100000  /* 100 ms -> 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_serial_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_sensor(int gpio)
{
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d: %s\n",
                gpio, strerror(errno));
        return -1;
    }
    return v;
}

static void emergency_stop(void)
{
    const char *msg = "EMERGENCY STOP!\n";
    if (g_serial_fd >= 0) {
        if (serialWrite(g_serial_fd, msg, strlen(msg)) < 0) {
            fprintf(stderr, "serialWrite failed: %s\n", strerror(errno));
        }
    } else {
        fprintf(stderr, "Emergency stop requested but serial port not open.\n");
    }
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor GPIOs as inputs with pull-up --- */
    int pins[] = {SENSOR_LEFT, SENSOR_MIDDLE, SENSOR_RIGHT};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "gpioSetMode failed for GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* --- Open serial port --- */
    g_serial_fd = serialOpen(SERIAL_PORT, BAUD_RATE);
    if (g_serial_fd < 0) {
        fprintf(stderr, "Failed to open serial port %s: %s\n",
                SERIAL_PORT, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        serialClose(g_serial_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        serialClose(g_serial_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("KY-033 3-Way Tracking Sensor Monitor\n");
    printf("Left=GPIO%d, Middle=GPIO%d, Right=GPIO%d, Serial=%s @ %d baud\n",
           SENSOR_LEFT, SENSOR_MIDDLE, SENSOR_RIGHT,
           SERIAL_PORT, BAUD_RATE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int left   = read_sensor(SENSOR_LEFT);
        int middle = read_sensor(SENSOR_MIDDLE);
        int right  = read_sensor(SENSOR_RIGHT);

        if (left < 0 || middle < 0 || right < 0) {
            /* Sensor read error already reported; skip this cycle. */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* KY-033 outputs LOW (0) when obstacle/line detected, HIGH (1) when clear */
        int obstacle = (left == 0 && middle == 0 && right == 0) ? 1 : 0;

        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];
        if (localtime_r(&now, &tm_info) != NULL) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            snprintf(ts, sizeof(ts), "unknown-time");
        }

        printf("[%s] Left=%d Middle=%d Right=%d Obstacle=%d\n",
               ts, left, middle, right, obstacle);

        if (obstacle) {
            emergency_stop();
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");
    if (g_serial_fd >= 0) {
        serialClose(g_serial_fd);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

